window.__BOOK__['p01'].push([{"id":"b1-1","bab":"الجزء 1","sec":"ذكر المائة الصوت المختارة","page":"ج1 ص8","text":"الرشيد يأمر المغنين باختيار ثلاثة أصوات أخبرنا أبو أحمد يحيى بن علي بن يحيى المنجم قال حدثني أبي قال حدثني إسحاق بن إبراهيم الموصلي أن أباه أخبره أن الرشيد رحمة الله عليه أمر المغنين وهم يومئذ متوافرون أن يختاروا له ثلاثة أصوات من جميع الغناء فأجمعوا على ثلاثة أصوات أنا أذكرها بعد هذا إن شاء الله قال إسحاق فجرى هذا الحديث يوما وأنا عند أمير المؤمنين الواثق بالله فأمرني باختيار أصوات من الغناء القديم فاخترت له من غناء أهل كل عصر ما اجتمع علماؤهم على براعته وإحكام صنعته ونسبته إلى من شدا به ثم نظرت إلى ما أحدث الناس بعد ممن شاهدناه في عصرنا وقبيل ذلك فاجتبيت منه ما كان مشبها لما تقدم أو سالكا طريقه فذكرته ولم أبخسه ما يجب له وإن كان قريب العهد لأن الناس قد يتنازعون الصوت في كل حين وزمان وإن كان السبق للقدماء إلى كل إحسان وأخبرني أحمد بن جعفر جحظة قال حدثني هارون بن الحسن بن سهل وأبو العبيس بن حمدون وابن دقاق وهو محمد بن أحمد بن يحيى المعروف بابن دقاق بهذا الخبر فزعم\nأن الرشيد أمر هؤلاء المغنين أن يختاروا له مائة صوت فاختاروها ثم أمرهم باختيار عشرة منها فاختاروها ثم أمرهم أن يختاروا منها ثلاثة ففعلوا وذكر نحو ما ذكره يحيى بن علي ووافقه في صوت من الثلاثة الأصوات وخالفه في صوتين وذكر يحيى بن علي بإسناده المذكور أن منها لحن معبد في شعر أبي قطيفة وهو من خفيف الثقيل الأول\n(القصر فالنخل فالجماء بينهما ... أشهى إلى القلب من أبواب جيرون)\nلحن ابن سريج في شعر عمر بن أبي ربيعة ولحنه من الثقيل الثاني\n(تشكى الكميت الجري لما جهدته ... وبين لو يستطيع أن يتكلما)\nلحن ابن محرز في شعر نصيب وهو من الثقيل الثاني أيضا\n(أهاج هواك المنزل المتقادم ... نعم وبه ممن شجاك معالم)\nوذكر جحظة عمن روى عنه أن من الثلاثة الأصوات لحن ابن محرز في شعر\nالمجنون وهو من الثقيل الثاني\n(إذا ما طواك الدهر يا أم مالك ... فشأن المنايا القاضيات وشانيا)\nلحن إبراهيم الموصلي في شعر العرجي وهو من خفيف الثقيل الثاني\n(إلى جيداء قد بعثوا رسولا ... ليحزنها فلا صحب الرسول)\nلحن ابن محرز في شعر نصيب وهو على ما ذكر هزج\n(أهاج هواك المنزل المتقادم ... نعم وبه ممن شجاك معالم)\nوحكي عن أصحابه أن هذه الثلاثة الأصوات على هذه الطرائق لا تبقي نغمة في الغناء إلا وهي فيها المغنون يختارون لحن ابن محرز أخبرني الحسن بن علي الأدمي قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا عبد الله بن أبي سعد الوراق قال حدثني أبو توبة صالح بن محمد قال حدثني محمد بن جبر المغني قال حدثني إبراهيم بن المهدي أن الرشيد أمر المغنين أن يختاروا له أحسن صوت غني فيه فاختاروا له لحن ابن محرز في شعر نصيب\n(أهاج هواك المنزل المتقادم ... )","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":0,"spl":"ذكر المائة الصوت المختارة","partial":1},
{"id":"b1-2","bab":"الجزء 1","sec":"ذكر المائة الصوت المختارة","page":"ج1 ص8","text":"قال وفيه دور كثير أي صنعة كثيرة والذي ذكره أبو أحمد يحيى بن علي أصح عندي ويدل على ذلك تباين ما بين الأصوات التي ذكرها والأصوات الأخر في جودة الصنعة وإتقانها وإحكام مباديها ومقاطعها وما فيها من العمل وأن الأخرى ليست مثلها ولا قريبة منها وأخرى هي أن جحظة حكى عمن روى عنه أن فيها صوتا لإبراهيم الموصلي وهو أحد من كان اختار هذه الأصوات للرشيد وكان معه في اختيارها إسماعيل بن جامع وفليح بن أبي العوراء وليس أحد منهما دونه إن لم يفقه فكيف يمكن أن يقال إنهما ساعدا إبراهيم على اختيار لحن من صنعته في ثلاثة أصوات اختيرت من سائر الأغاني وفضلت عليها ألم يكونا لو فعلا ذلك قد حكما لإبراهيم على أنفسهما بالتقدم والحذق والرياسة وليس هو كذلك عندهما اختلاف وجهتي نظر إبراهيم بن ميمون وولده في غناء ابن جامع ولقد أخبرنا يحيى بن علي بن يحيى المنجم عن حماد بن إسحاق عن أبيه أنه أتى أباه إبراهيم بن ميمون يوما مسلما فقال له أبوه يا بني ما أعلم أحدا بلغ من بر ولده ما بلغته من برك وإني لأستقل ذلك لك فهل من حاجة أصير فيها إلى محبتك قلت قد كان جعلت فداك كل ما ذكرت فأطال الله لي بقاءك ولكني أسألك واحدة يموت هذا الشيخ غدا أو بعد غد ولم أسمعه فيقول الناس لي ماذا وأنا أحل منك هذا المحل قال لي ومن هو قلت ابن جامع قال صدقت يا بني أسرجوا لنا فجئنا ابن جامع فدخل عليه أبي وأنا معه فقال يا أبا القاسم قد جئتك في حاجة فإن شئت فاشتمني وإن شئت فاقذفني غير أنه لا بد لك من قضائها هذا عبدك وابن أخيك إسحاق قال لي كذا وكذا فركبت\nمعه أسألك أن تسعفه فيما سأل فقال نعم على شريطة تقيمان عندي أطعمكما مشوشة وقلية وأسقيكما من نبيذي التمري وأغنيكما فإن جاءنا رسول الخليفة مضينا إليه وإلا أقمنا يومنا فقال أبي السمع والطاعة وأمر بالدواب فردت فجاءنا ابن جامع بالمشوشة والقلية ونبيذه التمري فأكلنا وشربنا ثم اندفع فغنانا فنظرت إلى أبي يقل في عيني ويعظم ابن جامع حتى صار أبي في عيني كلا شيء فلما طربنا غاية الطرب جاء رسول الخليفة فركبا وركبت معهما فلما كنا في بعض الطريق قال لي أبي كيف رأيت ابن جامع يا بني قلت له أو تعفيني جعلت فداك قال لست أعفيك فقل فقلت له رأيتك ولا شيء أكبر عندي منك قد صغرت عندي في الغناء معه حتى صرت كلا شيء ثم مضينا إلى الرشيد وانصرفت إلى منزلي وذلك لأني لم أكن بعد وصلت إلى الرشيد فلما أصبحت أرسل إلي أبي فقال يا بني هذا الشتاء قد هجم عليك وأنت تحتاج فيه إلى مؤونة وإذا مال عظيم بن يديه فاصرف هذا المال في حوائجك فقمت فقبلت يده ورأسه وأمرت بحمل المال واتبعته فصوت بي يا إسحاق ارجع فرجعت فقال لي أتدري لم وهبت لك هذا المال قلت نعم جعلت فداك قال لم قلت لصدقي فيك وفي ابن جامع قال صدقت يا بني امض راشدا ولهما في هذا الجنس أخبار كثيرة تأتي في غير هذا الموضع متفرقة في أماكن تحسن فيها ولا يستغنى بما ذكر هاهنا عنها فإبراهيم يحل ابن جامع هذا المحل مع ما كان بينهما من المنافسة والمفاخرة ثم يقدم على أن يختار فيما هو معه فيه صوتا لنفسه يكون مقدما على سائر الغناء ويطابقه هو وفليح عليه خطأ لا يتخيل وعلى ما به فإنا نذكر الصوتين اللذين رويناهما عن جحظة المخالفين لرواية يحيى بن علي بعد ذكرنا ما رواه يحيى ثم نتبعهما باقي\nالاختيار فأول ذلك من رواية أبي الحسن علي بن يحيى الكلام على أحد هذه الأصوات الثلاثة","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":1,"spl":"ذكر المائة الصوت المختارة"},
{"id":"b1-3","bab":"الجزء 1","sec":"صوت فيه لحنان","page":"ج1 ص13","text":"(القصر فالنخل فالجماء بينهما ... أشهى إلى القلب من أبواب جيرون)\n(إلى البلاط فما حازت قرائنه ... دور نزحن عن الفحشاء والهون)\n(قد يكتم الناس أسرارا فأعلمها ... ولا ينالون حتى الموت مكنوني)\nروضه من أول البسيط القصر الذي عناه هاهنا قصر سعيد بن العاص بالعرصة والنخل الذي عناه نخل كان لسعيد هناك بين قصره وبين الجماء وهي أرض كانت له فصار جميع ذلك لمعاوية بن أبي سفيان بعد وفاة سعيد ابتاعه من ابنه عمرو باحتمال دينه عنه ولذلك خبر يذكر بعد وأبواب جيرون بدمشق ويروى حاذت قرائنه من المحاذاة والقرائن دور كانت لبني سعيد بن العاص متلاصقة سميت بذلك لاقترانها ونزحن بعدن والنازح\nالبعيد يقال نزح نزوحا والهون الهوان قال الراجز\n(لم يبتذل مثل كريم مكنون ... أبيض ماض كالسنان المسنون)\n(كان يوقي نفسه من الهون ... )\nالمكنون المستور الخفي وهو مأخوذ من الكن الشعر لأبي قطيفة المعيطي والغناء لمعبد وله فيه لحنان أحدهما خفيف ثقيل أول بالوسطى في مجراها من رواية إسحاق وهو اللحن المختار والآخر ثقيل أول بالوسطى على مذهب إسحاق من رواية عمرو بن بانة","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":2,"spl":"صوت فيه لحنان — خبر أبي قطيفة ونسبه","partial":1},
{"id":"b1-4","bab":"الجزء 1","sec":"خبر أبي قطيفة ونسبه","page":"ج1 ص15","text":"هو عمرو بن الوليد بن عقبة بن أبي معيط واسم أبي معيط أبان بن أبي عمرو بن أمية بن عبد شمس بن عبد مناف بن قصي بن كلاب بن مرة بن كعب بن لؤي بن غالب هذا الذي عليه النسابون وذكر الهيثم بن عدي في كتاب المثالب أن أبا عمرو بن أمية كان عبدا لأمية اسمه ذكوان فاستلحقه وذكر أن دغفلا النسابة دخل على معاوية فقال له من رأيت من علية قريش فقال رأيت عبد المطلب بن هاشم وأمية بن عبد شمس فقال صفهما لي فقال كان عبد المطلب أبيض مديد القامة حسن الوجه في جبينه نور النبوة وعز الملك يطيف به عشرة من بنيه كأنهم أسد غاب قال فصف أمية قال رأيته شيخا قصيرا نحيف الجسم ضريرا يقوده عبده ذكوان فقال مه ذاك ابنه أبو عمرو فقال هذا شيء قلتموه بعد وأحدثتموه وأما الذي عرفت فهو الذي أخبرتك به ثم نعود إلى سياقة النسب من لؤي بن\nغالب بن فهر بن مالك بن النضر بن كنانة والنضر عند أكثر النسابين أصل قريش فمن ولده النضر عد منهم ومن لم يلده فليس منهم وقال بعض نسابي قريش بل فهر بن مالك أصل قريش فمن لم يلده فليس من قريش ثم نعود للنسب إلى النضر بن كنانة بن خزيمة بن مدركة بن إلياس بن مضر بن نزار وولد إلياس يقال له خندف لهم سموا بأمهم خندف وهو لقبها واسمها ليلى بنت حلوان بن عمران بن الحاف بن قضاعة وهي أم مدركة وطابخة وقمعة بني إلياس بن مضر بن نزار بن معد بن عدنان بن أد بن أدد بن الهميسع بن يشجب وقيل أشجب بن نبت بن قيدار بن إسماعيل بن إبراهيم هذا النسب الذي رواه نسابو العرب وروي عن ابن شهاب الزهري وهو من علماء قريش وفقهائها وقال قوم آخرون من النسابين ممن أخذ فيما يزعم عن دغفل وغيره معد بن عدنان بن أدد بن آمين بن شاجيب بن نبت بن ثعلبة بن عنز بن سريج بن محلم بن العوام بن المحتمل بن رائمة بن العقيان بن غلة بن شحدود بن الضرب بن عيفر بن إبراهيم بن إسماعيل بن رزين بن أعوج بن المطعم بن الطمح بن القسور بن عتود بن دعدع بن محمود بن الرائد بن بدوان بن أمامة بن دوس بن حصين بن النزال بن الغمير بن محشر بن معذر بن صيفي بن نبت بن قيدار بن إسماعيل ذبيح الله بن إبراهيم خليل الله صلى الله عليهما وعلى أنبيائه أجميعن وسلم تسليما ثم أجمعوا أن إبراهيم بن آزر وهو اسمه بالعربية كما ذكره\nالله تعالى في كتابه وهو في التوراة بالعبرانية تارح بن ناحور وقيل الناحر بن الشارع وهو شاروع بن أرغو وهو الرامح بن فالغ وهو قاسم الأرض الذي قسمها بين أهلها بن عابر بن شالخ بن أرفخشذ وهو الرافد بن سام بن نوح صلى الله عليه و سلم بن لامك وهو في لغة العرب ملكان بن المتوشلخ وهو المنوف بن أخنخ وهو إدريس نبي الله عليه السلام بن يارد وهو الرائد بن مهلايل بن قينان وهو قنان بن أنوش وهو الطاهر بن شيث وهو هبة الله ويقال له أيضا شاث بن آدم أبي البشر صلى الله عليه وعلى سائر الأنبياء وعلى نبينا محمد خاصة وسلم تسليما هذا الذي في أيدي الناس من النسب على اختلافهم فيه وقد روي عن النبي تكذيب للنسابين ودفع لهم وروي أيضا خلاف لأسماء بعض الآباء وقد شرحت ذلك في كتاب النسب شرحا يستغنى به عن غيره","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":2,"spl":"صوت فيه لحنان — خبر أبي قطيفة ونسبه"},
{"id":"b1-5","bab":"الجزء 1","sec":"العنابس والأعياص","page":"ج1 ص17","text":"وأبو قطيفة وأهله من العنابس من بني أمية وكان لأمية من الولد أحد عشر ذكرا كل واحد منهم يكنى باسم صاحبه وهم العاص وأبو العاص والعيص وأبو العيص وعمرو وأبو عمرو وحرب وأبو حرب وسفيان وأبو سفيان والعويص لا\nكنى له فمنهم الأعياص فيما أخبرنا حرمي بن أبي العلاء واسمه أحمد بن محمد بن إسحاق والطوسي واسمه أحمد بن سليمان قالا حدثنا الزبير بن بكار عن محمد بن الضحاك الحزامي عن أبيه قال الأعياص العاص وأبو العاص والعيص وأبو العيص والعويص ومنهم العنابس وهم حرب وأبو حرب وسفيان وأبو سفيان وعمرو وأبو عمرو وإنما سموا العنابس لأنهم ثبتوا مع أخيهم حرب بن أمية بعكاظ وعقلوا أنفسهم وقاتلوا قتالا شديدا فشبهوا بالأسد والأسد يقال لها العنابس واحدها عنبسة وفي الأعياص يقول عبد الله بن فضالة الأسدي\n(من الأعياص أو من آل حرب ... أغر كغرة الفرس الجواد)\nالسبب في قوله هذا الشعر ما أخبرنا به أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة وحدثنا محمد بن العباس اليزيدي قال حدثنا أحمد بن الحارث الخراز قال حدثنا المدائني وابن غزالة قالوا أتى عبد الله بن فضالة بن شريك الوالبي ثم الأسدي من بني أسد بن خزيمة عبد الله بن الزبير فقال له نفدت نفقتي ونقبت راحلتي قال أحضرها\nفأحضرها فقال أقبل بها أدبر بها ففعل فقال ارقعها بسبت واخصفها بهلب وأنجد بها يبرد خفها وسر البردين تصح فقال ابن فضالة إني أتيتك مستحملا ولم آتك مستوصفا فلعن الله ناقة حملتني إليك قال ابن الزبير إن وراكبها فانصرف عنه ابن فضالة وقال","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":3,"spl":"العنابس والأعياص — عبد الله بن فضالة يهجو ابن الزبير"},
{"id":"b1-6","bab":"الجزء 1","sec":"عبد الله بن فضالة يهجو ابن الزبير","page":"ج1 ص19","text":"(أقول لغلمتي شدوا ركابي ... أجاوز بطن مكة في سواد)\n(فما لي حين أقطع ذات عرق ... إلى ابن الكاهلية من معاد)\n(سيبعد بيننا نص المطايا ... وتعليق الأداوى والمزاد)\n(وكل معبد قد أعلمته ... مناسمهن طلاع النجاد)\n(أرى الحاجات عند أبي خبيب ... نكدن ولا أمية بالبلاد)\n(من الأعياص أو من آل حرب ... أغر كغرة الفرس الجواد)\nبو خبيب عبد الله بن الزبير كان يكنى أبا بكر وخبيب ابن له هو أكبر ولده ولم يكن يكنيه به إلا من ذمه يجعله كاللقب له قال فقال ابن الزبير لما بلغه هذا الشعر علم أنها شر أمهاتي فعيرني بها وهي خير عماته قال اليزيدي إن هاهنا بمعنى نعم كأنه إقرار بما قال ومثله قول ابن قيس الرقيات\n(ويقلن شيب قد علاك ... وقد كبرت فقلت إنه)\nأم أبي معيط آمنة بنت أبان بن كليب بن ربيعة بن عامر بن صعصعة بن معاوية بن بكر بن هوازن ولها يقول نابغة بني جعدة\n(وشاركنا قريشا في تقاها ... وفي أنسابها شرك العنان)\n(بما ولدت نساء بني هلال ... وما ولدت نساء بني أبان)\nكانت آمنة هذه تحت أمية بن عبد شمس فولدت له العاص وأبا العاص وأبا العيص والعويص وصفية وتوبة وأروى بني أمية فلما مات أمية تزوجها بعده ابنه أبو عمرو وكان أهل الجاهلية يفعلون ذلك يتزوج الرجل امرأة أبيه بعده فولدت له أبا معيط فكان بنو أمية من آمنة إخوة أبي معيط وعمومته أخبرني بذلك كله الطوسي عن الزبير بن بكار قال الزبير وحدثني عمي مصعب قال زعموا أن ابنها أبا العاص زوجها أخاه أبا عمرو وكان هذا نكاحا تنكحه الجاهلية فأنزل الله تعالى تحريمه قال الله تعالى ( ولا تنكحوا ما نكح آباؤكم من النساء إلا ما قد سلف إنه كان فاحشة ومقتا وساء سبيلا\nفسمي نكاح المقت","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":3,"spl":"العنابس والأعياص — عبد الله بن فضالة يهجو ابن الزبير"},
{"id":"b1-7","bab":"الجزء 1","sec":"مقتل عقبة والحارث","page":"ج1 ص21","text":"وأسر عقبة بن أبي معيط في يوم بدر فقتله رسول الله صبرا حدثنا بذلك محمد بن جرير الطبري قال حدثنا محمد بن حميد الرازي قال حدثنا سلمة ابن الفضل عن محمد بن إسحاق في خبر ذكره طويل وحدثني به أحمد بن محمد بن الجعد قال حدثنا محمد بن إسحاق المسيبي قال حدثنا محمد بن فليح عن موسى بن عقبة عن ابن شهاب الزهري قالوا جميعا\nقتله رسول الله صبرا فقال له وقد أمر بذلك فيه يا محمد أأنا خاصة من قريش قال نعم قال فمن للصبية بعدي قال النار فلذلك يسمى بنو أبي معيط صبية النار واختلف في قاتله فقيل إن علي بن أبي طالب صلوات الله عليه تولى قتله وهذا من رواية بعض الكوفيين حدثني به أحمد بن محمد بن سعيد بن عقدة قال أخبرني المنذر بن محمد اللخمي قال حدثنا سليمان بن عباد قال حدثني عبد العزيز بن أبي ثابت المدني عن أبيه عن محمد بن عبد الله بن حسن بن حسن عن أبيه عن جده عن علي بن أبي طالب عليهم السلام أن النبي أمر عليا يوم بدر فضرب عنق عقبة بن أبي معيط والنضر بن الحارث وروى ابن إسحاق أن عاصم بن ثابت بن أبي الأقلح الأنصاري قتله وأن الذي قتله علي بن أبي طالب عليه السلام النضر بن الحارث بن كلدة أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثني الحسن بن عثمان قال حدثني ابن أبي زائدة عن محمد بن إسحاق عن أصحابه وحدثنا محمد بن جرير قال حدثنا أحمد بن حميد قال حدثنا سلمة عن ابن إسحاق عن أصحابه قالوا","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":4,"spl":"مقتل عقبة والحارث — قتيلة بنت الحارث ترثي أخاها"},
{"id":"b1-8","bab":"الجزء 1","sec":"قتيلة بنت الحارث ترثي أخاها","page":"ج1 ص22","text":"قتل رسول الله يوم بدر عقبة بن أبي معيط صبرا أمر عاصم بن ثابت\nفضرب عنقه ثم أقبل من بدر حتى إذا كان ب الصفراء قتل النضر بن الحارث بن كلدة أحد بني عبد الدار أمر عليا عليه السلام أن يضرب عنقه قال عمر بن شبة في حديثه ب الأثيل فقالت أخته قتيلة بنت الحارث ترثيه\n(يا راكبا إن الأثيل مظنة ... من صبح خامسة وأنت موفق)\n(أبلغ به ميتا بأن تحية ... ما إن تزال بها النجائب تخفق)\n(مني إليك وعبرة مسفوحة ... جادت بدرتها وأخرى تخنق)\n(هل يسمعن النضر إن ناديته ... إن كان يسمع هالك لا ينطق)\n(ظلت سيوف بني أبيه تنوشه ... لله أرحام هناك تشقق)\n(صبرا يقاد إلى المنية متعبا ... رسف المقيد وهو عان موثق)\n(أمحمد ولأنت نسل نجيبة ... في قومها والفحل فحل معرق)\n(ما كان ضرك لو مننت وربما ... من الفتى وهو المغيظ المحنق)\n(أو كنت قابل فدية فليأتين ... بأعز ما يغلو لديك وينفق)\n(والنضر أقرب من أخذت بزلة ... وأحقهم إن كان عتق يعتق)\nبلغنا أن النبي قال لو سمعت هذا قبل أن أقتله ما قتلته فيقال إن شعرها أكرم شعر موتورة وأعفه وأكفه وأحلمه قال ابن إسحاق وحدثني أبو عبيدة بن محمد بن عمار بن ياسر أن رسول الله لما كان بعرق الظبية قتل عقبة بن أبي معيط قال حين أمر به أن يقتل فمن للصبية يا محمد قال النار فقتله عاصم بن ثابت بن أبي الأقلح أحد بني عمرو بن عوف حدثني أحمد بن الجعد قال حدثنا عبد الله بن محمد بن إسحاق الأدمي قال حدثنا الوليد بن مسلم قال حدثني الأوزاعي قال حدثني يحيى بن أبي كثير عن محمد بن إبراهيم التيمي قال حدثني عروة بن الزبير قال سألت عبد الله بن عمرو فقلت أخبرني بأشد شيء صنعه المشركون برسول الله فقال بينا رسول الله يصلي في حجر الكعبة إذا أقبل عقبة بن أبي معيط فوضع ثوبه في عنق رسول الله\nفخنقه به خنقا شديدا فأقبل أبو بكر رحمة الله عليه حتى أخذ بمنكبه فدفعه عن رسول الله وقال أتقتلون رجلا أن يقول ربي الله","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":4,"spl":"مقتل عقبة والحارث — قتيلة بنت الحارث ترثي أخاها"},
{"id":"b1-9","bab":"الجزء 1","sec":"الوليد بن عقبة يتولى الكوفة","page":"ج1 ص25","text":"وكان الوليد بن عقبة أخا عثمان بن عفان لأمه أمهما أروى بنت عامر بن كريز وأمها أم حكيم البيضاء بنت عبد المطلب بن هاشم بن عبد مناف والبيضاء وعبد الله أبو رسول الله توءمان وكان عقبة بن أبي معيط تزوج أروى بعد وفاة عفان فولدت له الوليد وخالدا وعمارة وأم كلثوم كل هؤلاء أخوه عثمان لأمه وولى عثمان الوليد بن عقبة في خلافته الكوفة فشرب الخمر وصلى بالناس وهو سكران فزاد في الصلاة وشهد عليه بذلك عند عثمان فجلده الحد وسيأتي خبره بعد هذا في موضعه وأبو قطيفة عمرو بن الوليد يكنى أبا الوليد وأبو قطيفة لقب لقب به وأمه بنت الربيع بن ذي الخمار من بني أسد بن خزيمة وقال أبو قطيفة هذا الشعر حين نفاه ابن الزبير مع بني أمية عن المدينة مع نظائر له تشوقا إليها حدثني بالسبب في ذلك أحمد بن محمد بن شبيب بن أبي شيبة البزار قال حدثنا أحمد بن الحارث الخراز عن المدائني وأخبرني ببعضه أحمد بن محمد بن الجعد قال حدثنا أحمد بن زهير بن حرب قال حدثني أبي قال\nحدثني وهب بن جرير عن أبيه في كتابه المسمى كتاب الأزارقة ونسخت بعضه من كتاب منسوب إلى الهيثم بن عدي واللفظ للمدائني في الخبر ما اتسق فإذا انقطع أو اختلف نسبت الخلاف إلى راويه قال الهيثم بن عدي أخبرنا ابن عياش عن مجالد عن الشعبي وعن ابن أبي الجهم ومحمد بن المنتشر","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":5,"spl":"الوليد بن عقبة يتولى الكوفة"},
{"id":"b1-10","bab":"الجزء 1","sec":"خروج ابن الزبير على بني أمية","page":"ج1 ص26","text":"أن الحسين بن علي بن أبي طالب عليه وعلى أبيه السلام لما سار إلى العراق شمر ابن الزبير للأمر الذي أراده ولبس المعافري وشبر بطنه وقال إنما بطني شبر وما عسى أن يسع الشبر وجعل يظهر عيب بني أمية ويدعو إلى خلافهم فأمهله يزيد سنة ثم بعث إليه عشرة من أهل الشام عليهم النعمان بن بشير وكان أهل الشام يسمون أولئك العشرة النفر الركب منهم عبد الله بن عضاه الأشعري وروح بن زنباع الجذامي وسعد بن حمزة الهمداني ومالك ابن هبيرة السكوني وأبو كبشة السكسكي وزمل بن عمرو العذري وعبد الله بن مسعود وقيل ابن مسعدة الفزاري وأخوه عبد الرحمن وشريك بن عبد الله\nالكناني وعبد الله بن عامر الهمداني وجعل عليهم النعمان بن بشير فأقبلوا حتى قدموا مكة على عبد الله بن الزبير وكان النعمان يخلو به في الحجر كثيرا فقال له عبد الله بن عضاه يوما يابن الزبير إن هذا الأنصاري والله ما أمر بشيء إلا وقد أمرنا بمثله إلا أنه قد أمر علينا إني والله ما أدري ما بين المهاجرين والأنصار فقال ابن الزبير يابن عضاه مالي ولك إنما أنا بمنزلة حمامة من حمام مكة أفكنت قاتلا حماما من حمام مكة قال نعم وما حرمة حمام مكة يا غلام ائتني بقوسي وأسهمي فأتاه بقوسه وأسهمه فأخذ سهما فوضعه في كبد القوس ثم سدده نحو حمامة من حمام المسجد وقال يا حمامة أيشرب يزيد بن معاوية الخمر قولي نعم فوالله لئن فعلت لأرمينك يا حمامة أتخلعين يزيد بن معاوية وتفارقين أمة محمد وتقيمين في الحرم حتى يستحل بك والله لئن فعلت لأرمينك فقال ابن الزبير ويحك أو يتكلم الطائر قال لا ولكنك يا بن الزبير تتكلم أقسم بالله لتبايعن طائعا أو مكرها أو لتتعرفن راية الأشعريين في هذه البطحاء ثم لا أعظم من حقها ما تعظم فقال ابن الزبير أو تستحل الحرم قال إنما يستحله من ألحد فيه فحبسهم شهرا ثم ردهم إلى يزيد بن معاوية ولم يجبه إلى شيء وفي رواية أحمد بن الجعد وقال بعض الشعراء وهو أبو العباس الأعمى واسمه السائب بن فروخ يذكر ذلك وشبر ابن الزبير بطنه\n(ما زال في سورة الأعراف يدرسها ... حتى بدا لي مثل الخز في اللين)\n(لو كان بطنك شبرا قد شبعت وقد ... أفضلت فضلا كثيرا للمساكين)\nال الهيثم ثم إن ابن الزبير مضى إلى صفية بنت أبي عبيد زوجة عبد الله\nابن عمر فذكر لها أن خروجه كان غضبا لله تعالى ورسوله والمهاجرين والأنصار من أثرة معاوية وابنه وأهله بالفيء وسألها مسألته أن يبايعه فلما قدمت له عشاءه ذكرت له أمر ابن الزبير واجتهاده وأثنت عليه وقالت ما يدعو إلا إلى طاعة الله جل وعز وأكثرت القول في ذلك فقال لها أما رأيت بغلات معاوية اللواتي كان يحج عليهن الشهب فإن ابن الزبير ما يريد غيرهن قال المدائني في خبره وأقام ابن الزبير على خلع يزيد ومالأه على ذلك أكثر الناس فدخل عليه عبد الله بن مطيع وعبد الله بن حنظلة وأهل المدينة المسجد وأتوا المنبر فخلعوا يزيد فقال عبد الله بن أبي عمرو بن حفص بن المغيرة المخزومي خلعت يزيد كما خلعت عمامتي ونزعها عن رأسه وقال إني لأقول هذا وقد وصلني وأحسن جائزتي ولكن عدو الله سكير خمير وقال آخر خلعته كما خلعت نعلي وقال آخر خلعته كما خلعت ثوبي وقال آخر قد خلعته كما خلعت خفي حتى كثرت العمائم والنعال والخفاف وأظهروا البراءة منه وأجمعوا على ذلك وامتنع منه عبد الله بن عمر ومحمد بن علي بن أبي طالب عليهما السلام وجرى بين محمد خاصة وبين أصحاب ابن الزبير فيه\nقول كثير حتى أرادوا إكراهه على ذلك فخرج إلى مكة وكان هذا أول ما هاج الشر بينه وبين ابن الزبير","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":6,"spl":"خروج ابن الزبير على بني أمية"},
{"id":"b1-11","bab":"الجزء 1","sec":"وقعة الحرة","page":"ج1 ص29","text":"قال المدائني واجتمع أهل المدينة لإخراج بني أمية عنها فأخذوا عليهم العهود ألا يعينوا عليهم الجيش وأن يردوهم عنهم فإن لم يقدروا على ردهم لا يرجعوا إلى المدينة معهم فقال لهم عثمان بن محمد بن أبي سفيان أنشدكم الله في دمائكم وطاعتكم فإن الجنود تأتيكم وتطؤكم وأعذر لكم ألا تخرجوا أميركم إنكم إن ظفرتم وأنا مقيم بين أظهركم فما أيسر شأني وأقدركم على إخراجي وما أقول هذا إلا نظرا لكم أريد به حقن دمائكم فشتموه وشتموا يزيد وقالوا لا نبدأ إلا بك ثم نخرجهم بعدك فأتى مروان عبد الله بن عمر فقال يا أبا عبد الرحمن إن هؤلاء القوم قد ركبونا بما ترى فضم عيالنا فقال لست من أمركم وأمر هؤلاء في شيء فقام مروان وهو يقول قبح الله هذا أمرا وهذا دينا ثم أتى علي بن الحسين عليهما السلام فسأله أن يضم أهله وثقله ففعل ووجههم وامرأته أم أبان بنت عثمان إلى الطائف ومعها ابناه عبد الله ومحمد فعرض حريث رقاصة وهو مولى لبني بهز من سليم كان بعض عمال المدينة قطع رجله فكان إذا مشى كأنه يرقص فسمي رقاصة لثقل مروان وفيه أم عاصم بنت عاصم\nابن عمر بن الخطاب فضربته بعصا فكادت تدق عنقه فولى ومضى ومضوا إلى الطائف وأخرجوا بني أمية فحس بهم سليمان بن أبي الجهم العدوي وحريث رقاصة فأراد مروان أن يصلي بمن معه فمنعوه وقالوا لا يصلي والله بالناس أبدا ولكن إن أراد أن يصلي بأهله فليصل فصلى بهم ومضى فمر مروان بعبد الرحمن بن أزهر الزهري فقال له هلم إلي يا أبا عبد الملك فلا يصل إليك مكروه ما بقي رجل من بني زهرة فقال له وصلتك رحم قومنا على أمر فأكره أن أعرضك لهم وقال ابن عمر بعد ذلك لما أخرجوا وندم على ما كان قاله لمروان لو وجدت سبيلا إلى نصر هؤلاء لفعلت فقد ظلموا وبغي عليهم فقال ابنه سالم لو كلمت هؤلاء القوم فقال يا بني لا ينزع هؤلاء القوم عما هم عليه وهم بعين الله إن أراد أن يغير غير قال فمضوا إلى ذي خشب وفيهم عثمان بن محمد بن أبي سفيان والوليد بن عتبة بن أبي سفيان واتبعهم العبيد والصبيان والسفلة يرمونهم ثم رجع حريث رقاصة وأصحابه إلى المدينة وأقامت بنو أمية ب ذي خشب عشرة أيام وسرحوا حبيب بن كرة إلى يزيد بن معاوية يعلمونه وكتبوا إليه يسألونه الغوث وبلغ أهل المدينة أنهم وجهوا رجلا إلى يزيد فخرج محمد بن عمرو بن حزم ورجل من بني سليم من بهز وحريث رقاصة وخمسون راكبا فأزعجوا بني أمية منها فنخس حريث بمروان فكاد يسقط عن ناقته فتأخر عنها وزجرها وقال اعلي واسلمي فلما كانوا بالسويداء عرض لهم مولى لمروان فقال جعلت فداك لو نزلت فأرحت وتغديت فالغداء حاضر كثير قد أدرك فقال لا يدعني رقاصة وأشباهه وعسى أن يمكن الله منه\nفتقطع يده ونظر مروان إلى ماله ب ذي خشب فقال لا مال إلا ما أحرزته العياب فمضوا فنزلوا حقيلا أو وادي القرى وفي ذلك يقول الأحوص\n(لا ترثين لحزمي رأيت به ... ضرا ولو سقط الحزمي في النار)\n(الناخسين بمروان بذي خشب ... والمقحمين على عثمان في الدار)\nال المدائني فدخل حبيب بن كرة على يزيد وهو واضع رجله في طست لوجع كان يجده بكتاب بني أمية وأخبره الخبر فقال أما كان بنو أمية ومواليهم ألف رجل قال بلى وثلاثة آلاف قال أفعجزوا أن يقاتلوا ساعة من نهار قال كثرهم الناس ولم تكن لهم بهم طاقة فندب الناس وأمر عليهم صخر بن أبي الجهم القيني فمات قبل أن يخرج الجيش فأمر مسلم بن عقبة الذي يسمى مسرفا قال وقال ليزيد ما كنت مرسلا إلى المدينة أحدا إلا قصر وما صاحبهم غيري إني رأيت في منامي شجرة غرقد تصيح على يدي مسلم فأقبلت\nنحو الصوت فسمعت قائلا يقول أدرك ثأرك أهل المدينة قتلة عثمان فخرج مسلم وكان من قصة الحرة ما كان على يده وليس هذا موضعه فقال أبو قطيفة في ذلك لما أخرجوا عن المدينة","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":7,"spl":"وقعة الحرة — حنين أبي قطيفة إلى المدينة وأهلها صوت من غير المائة فيه لحنان"},
{"id":"b1-12","bab":"الجزء 1","sec":"حنين أبي قطيفة إلى المدينة وأهلها صوت من غير المائة فيه لحنان","page":"ج1 ص32","text":"(بكى أحد لما تحمل أهله ... فكيف بذي وجد من القوم آلف)\n(من اجل أبي بكر جلت عن بلادها ... أمية والأيام ذات تصارف)\nروضه من الطويل وفيه ثقيل أول والغناء لسائب خاثر خفيف ثقيل أول بالوسطى ذكر ذلك حماد عن أبيه وذكر أن فيه لحنا آخر لأهل المدينة لا يعرف صاحبه قال الهيثم في خبره وقال أبو العباس الأعمى في ذلك\n(قد حل في دار البلاط مجوع ... ودار أبي العاص التميمي حنتف)\n(فلم أر مثل الحي حين تحملوا ... ولا مثلنا عن مثلهم يتنكف)\nوقال أبو قطيفة أيضا","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":7,"spl":"وقعة الحرة — حنين أبي قطيفة إلى المدينة وأهلها صوت من غير المائة فيه لحنان"},
{"id":"b1-13","bab":"الجزء 1","sec":"صوت من غير المائة فيه ثلاثة ألحان","page":"ج1 ص32","text":"(بكى أحد لما تحمل أهله ... فسلع فدار المال أمست تصدع)\n(وبالشام إخواني وجل عشيرتي ... فقد جعلت نفسي إليهم تطلع)\nروضه من الطويل غنى فيه دحمان ولحنه ثقيل أول بإطلاق الوتر في مجرى البنصر من رواية إسحاق وفيه لمعبد ثقيل أول بالوسطى من رواية حبش وذكر إسحاق أن فيه لحنا فيه خفيف الثقيل الأول بالخنصر في مجرى البنصر مجهول الصانع وقال أبو قطيفة أيضا","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":8,"spl":"صوت من غير المائة فيه ثلاثة ألحان — ابن الزبير يعفو عن أبي قطيفة"},
{"id":"b1-14","bab":"الجزء 1","sec":"صوت من غير المائة المختارة","page":"ج1 ص33","text":"(ليت شعري هل البلاط كعهدي ... والمصلى إلى قصور العقيق)\n(لامني في هواك يا أم يحيى ... من مبين بغشه أو صديق)\nروضه من الخفيف غناه معبد ويقال دحمان ولحنه ثقيل أول بالسبابة في مجرى الوسطى وذكر إسحاق أنه لا يعرف صاحبه\nحدثني أحمد بن عبيد الله بن عمار قال حدثني محمد بن يونس بن الوليد قال كان ابن الزبير قد نفى أبا قطيفة مع من نفاه من بني أمية عن المدينة إلى الشأم فلما طال مقامه بها\n(ألا ليت شعري هل تغير بعدنا ... قباء وهل زال العقيق وحاضره)\n(وهل برحت بطحاء قبر محمد ... أراهط غر من قريش تباكره)\n(لهم منتهى حبي وصفو مودتي ... ومحض الهوى مني وللناس سائره)\nال وقال أيضا صوت من غير المائة المختارة\n(ليت شعري وأين مني ليت ... أعلى العهد يلبن فبرام)\n(أم كعهدي العقيق أم غيرته ... بعدي الحادثات والأيام)\n(وبأهلي بدلت عكا ولخما ... وجذاما وأين مني جذام)\n(وتبدلت من مساكن قومي ... والقصور التي بها الآطام)\n(كل قصر مشيد ذي أواس ... يتغنى على ذراه الحمام)\n(اقر مني السلام إن جئت قومي ... وقليل لهم لدي السلام)\nعروضه من الخفيف غناه معبد ولحنه ثقيل أول بالخنصر في مجرى البنصر ويلبن وبرام موضعان والآطام جمع أطم وهي القصور والحصون وقال الأصمعي الآطام الدور المسطحة السقوف وفي رواية ابن عمار ذي أواش بالشين معجمة كأنه أراد به أن هذه القصور موشية أي منقوشة ورواه إسحاق أواس بالسين غير معجمة وقال واحدها آسي وهو الأصل قال ويقال فلان في آسيه أي في أصله والآسي والأساس واحد وذرا كل شيء أعاليه وهو جمع واحدته ذروة ويروى\n(أبلغن السلام إن جئت قومي ... )\nروى الزبير بن بكار هذه الأبيات لأبي قطيفة وزاد فيها\n(أقطع الليل كله باكتئاب ... وزفير فما أكاد أنام)\n(نحو قومي إذ فرقت بيننا الدار ... وحادت عن قصدها الأحلام)\n(خشية أن يصيبهم عنت الدهر ... وحرب يشيب منها الغلام)\n(فلقد حان أن يكون لهذا الدهر ... عنا تباعد وانصرام)","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":8,"spl":"صوت من غير المائة فيه ثلاثة ألحان — ابن الزبير يعفو عن أبي قطيفة","partial":1},
{"id":"b1-15","bab":"الجزء 1","sec":"ابن الزبير يعفو عن أبي قطيفة","page":"ج1 ص35","text":"رجع الخبر إلى سياقته من رواية ابن عمار وأخبرنا بمثله من هذا الموضع الحسين بن يحيى عن حماد بن إسحاق عن أبيه عن الحزامي وهو إبراهيم بن المنذر عن مطرف بن عبد الله المدني قالا إن ابن الزبير لما بلغه شعر أبي قطيفة هذا قال حن والله أبو قطيفة وعليه السلام ورحمة الله من لقيه فليخبره أنه آمن\nفليرجع فأخبر بذلك فانكفأ إلى المدينة راجعا فلم يصل إليها حتى مات قال ابن عمار فحدثت عن المدائني أن امرأة من أهل المدينة تزوجها رجل من أهل الشام فخرج بها إلى بلده على كره منها فسمعت منشدا ينشد شعر أبي قطيفة هذا فشهقت شهقة وخرت على وجهها ميتة هكذا ذكر ابن عمار في خبره وأخبرني الحسين بن يحيى قال قال حماد قرأت على أبي عن أيوب بن عباية قال قال حدثني سعيد بن عائشة مولى آل المطلب بن عبد مناف قال خرجت امرأة من بني زهرة في خف فرآها رجل من بني عبد شمس من أهل الشام فأعجبته فسأل عنها فنسبت له فخطبها إلى أهلها فزوجوه إياها بكره منها فخرج بها إلى الشام وخرجت مخرجا فسمعت متمثلا يقول","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":8,"spl":"صوت من غير المائة فيه ثلاثة ألحان — ابن الزبير يعفو عن أبي قطيفة"},
{"id":"b1-16","bab":"الجزء 1","sec":"صوت من غير المائة المختارة","page":"ج1 ص36","text":"(ألا ليت شعري هل تغير بعدنا ... جبوب المصلى أم كعهدي القرائن)\n(وهل أدؤر حول البلاط عوامر ... من الحي أم هل بالمدينة ساكن)\n(إذا برقت نحو الحجاز سحابة ... دعا الشوق مني برقها المتيامن)\n(فلم أتركنها رغبة عن بلادها ... ولكنه ما قدر الله كائن)\nروضه من الطويل يقال إن لمعبد فيه لحنا قال فتنفست بين النساء فوقعت ميتة قال أيوب فحدثت بهذا الحديث عبد العزيز بن أبي ثابت الأعرج فقال أتعرفها قلت لا قال هي والله عمتي حميدة بنت عمر بن عبد الرحمن بن عوف\nأخبرنا محمد بن العباس اليزيدي قال حدثنا الرياشي قال أخبرني ابن عائشة قال لما أجلى ابن الزبير بني أمية عن الحجاز قال أيمن بن خريم الأسدي\n(كأن بني أمية يوم راحوا ... وعري عن منازلهم صرار)\n(شماريخ الجبال إذا تردت ... بزينتها وجادتها القطار)\nأخبرني الحسن بن علي الخفاف قال حدثنا محمد بن سعد الكراني قال حدثنا العمري عن العتبي قال كتب أبو قطيفة عمرو بن الوليد بن عقبة إلى أبيه وهو متولي الكوفة لعثمان بن عفان\n(من مبلغ عني الأمير بأنني ... أرق بلا داء سوى الإنعاظ)\n(إن لم تغثني خفت إثمك أو أرى ... في الدار محدودا بزرق لحاظ)\nيعني دار عثمان التي تقام فيها الحدود فابتاع له جارية بالكوفة وبعث بها إليه أخبرني عبد الله بن محمد الرازي قال حدثنا الخراز عن المدائني قال كان أبو قطيفة من شعراء قريش وكان ممن نفاه ابن الزبير مع بني أمية إلى الشام فقال في ذلك\n(وما أحرجتنا رغبة عن بلادنا ... ولكنه ما قدر الله كائن)\n(أحن إلى تلك الوجوه صبابة ... كأني أسير في السلاسل راهن)\nكان يتحرق على المدينة فأتى عباد بن زياد ذات يوم عبد الملك فقال له إن خاله أخبره أن العراقين قد فتحا فقال عبد الملك لأبي قطيفة لما يعلمه من حبه المدينة أما تسمع ما يقوله عباد عن خاله قد طابت لك المدينة الآن فقال أبو قطيفة\n(إني لأحمق من يمشي على قدم ... إن غرني من حياتي خال عباد)\n(أنشا يقول لنا المصران قد فتحا ... ودون ذلك يوم شره بادي)\nال وأذن له ابن الزبير في الرجوع فرجع فمات في طريقه","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":9,"spl":"صوت من غير المائة المختارة"},
{"id":"b1-17","bab":"الجزء 1","sec":"وصية سعيد بن العاص","page":"ج1 ص38","text":"وأما خبر القصر الذي تقدم ذكره وبيعه من معاوية فأخبرني الحسين بن\nيحيى عن حماد عن أبيه قال ذكر مصعب بن عمار بن مصعب بن عروة بن الزبير أن سعيد بن العاص لما حضرته الوفاة وهو في قصره هذا قال له ابنه عمرو لو نزلت إلى المدينة فقال يا بني إن قومي لن يضنوا علي بأن يحملوني على رقابهم ساعة من نهار وإذا أنا مت فآذنهم فإذا واريتني فانطلق إلى معاوية فانعني له وانظر في ديني واعلم أنه سيعرض عليك قضاءه فلا تفعل واعرض عليه قصري هذا فإني إنما اتخذته نزهة وليس بمال فلما مات آذن به الناس فحملوه من قصره حتى دفن بالبقيع ورواحل عمرو بن سعيد مناخة فعزاه الناس على قبره وودعوه فكان هو أول من نعاه لمعاوية فتوجع له وترحم عليه ثم قال هل ترك دينا قال نعم قال كم هو قال ثلثمائة ألف درهم قال هي علي قال قد ظن ذلك وأمرني ألا أقبله منك وأن أعرض عليك بعض ماله فتبتاعه فيكون قضاء دينه منه قال فاعرض علي قال قصره بالعرصة قال قد أخذته بدينه قال هو لك على أن تحملها إلى المدينة وتجعلها بالوافية قال نعم فحملها له إلى المدينة وفرقها في غرمائه وكان أكثرها عدات فأتاه شاب من قريش بصك فيه عشرون ألف درهم بشهادة سعيد على نفسه وشهادة مولى له عليه فأرسل إلى المولى فاقرأه الصك فلما قرأه بكى وقال نعم هذا خطه وهذه شهادتي عليه فقال له عمرو من أين يكون لهذا الفتى عليه عشرون ألف درهم وإنما هو صعلوك من صعاليك قريش قال أخبرك عنه مرسعيد بعد عزله فاعترض له هذا الفتى ومشى معه حتى صار إلى منزله فوقف له سعيد فقال ألك حاجة قال لا إلا أني رأيتك تمشي وحدك فأحببت أن أصل جناحك فقال لي ائتني بصحيفة فأتيته بهذه فكتب له على نفسه هذا الدين\nوقال إنك لم تصادف عندنا شيئا فخذ هذا فإذا جاءنا شيء فأتنا فقال عمرو لا جرم والله لا يأخذها إلا بالوافية أعطه إياها فدفع إليه عشرين ألف درهم وافية أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا الصلت بن مسعود قال حدثنا سفيان بن عيينة قال حدثنا هارون المدائني قال كان الرجل يأتي سعيد بن العاص يسأله فلا يكون عنده فيقول ما عندي ولكن اكتب علي به فيكتب عليه كتابا فيقول تروني أخذت منه ثمن هذا لا ولكنه يجيء فيسألني فينزو دم وجهه في وجهي فأكره رده فأتاه مولى لقريش بابن مولاه وهو غلام فقال إن أبا هذا قد هلك وقد أردنا تزويجه فقال ما عندي ولكن خذ ما شئت في أمانتي فلما مات سعيد بن العاص جاء الرجل إلى عمرو بن سعيد فقال إني أتيت أباك بابن فلان وأخبره بالقصة فقال له عمرو فكم أخذت قال عشرة آلاف فأقبل عمرو على القوم فقال من رأى أعجز من هذا يقول له سعيد خذ ما شئت في أمانتي فيأخذ عشرة آلاف لو أخذت مائة ألف لأديتها عنك","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":10,"spl":"وصية سعيد بن العاص — أبو قطيفة يهجو عبد الملك بن مروان"},
{"id":"b1-18","bab":"الجزء 1","sec":"أبو قطيفة يهجو عبد الملك بن مروان","page":"ج1 ص4","text":"أخبرني عمي قال حدثنا الكراني قال حدثنا العمري عن ابن الكلبي قال قال أبو قطيفة وكانت أمه وأم خالد بن الوليد بن عقبة عمة أروى بنت أبي عقيل بن مسعود بن عامر بن معتب\n(أنا ابن أبي معيط حين أنمى ... لأكرم ضئضىء وأعز جيل)\n(وأنمى للعقائل من قصي ... ومخزوم فما أنا بالضئيل)\n(وأروى من كريز قد نمتني ... وأروى الخير بنت أبي عقيل)\n(كلا الحيين من هذا وهذا ... لعمر أبيك في الشرف الطويل)\n(فعدد مثلهن أبا ذباب ... ليعلم ما تقول ذوو العقول)\n(فما الزرقاء لي أما فأخزى ... ولا لي في الأزارق من سبيل)\nال يعني بأبي الذباب عبد الملك والزرقاء إحدى أمهاته من كندة وكان يعير بها أخبرني الحسن بن علي قال أخبرني محمد بن زكريا قال حدثنا قعنب بن المحرز قال حدثنا المدائني قال بلغ أبا قطيفة أن عبد الملك بن مروان يتنقصه فقال\n(نبئت أن ابن العملس عابني ... ومن ذامن الناس البريء المسلم)\n(من أنتم من انتم خبرونا من أنتم ... فقد جعلت أشياء تبدو وتكتم)\nفبلغ ذلك عبد الملك فقال ما ظننت أنا نجهل والله لولا رعايتي لحرمته لألحقته بما يعلم ولقطعت جلده بالسياط أخبرني أحمد بن جعفر جحظة قال حدثنا حماد بن إسحاق عن أبيه عن العتبي قال\nطلق أبو قطيفة امرأته فتزوجها رجل من أهل العراق ثم ندم بعد أن رحل بها الرجل وصارت له فقال\n(فيا أسفا لفرقة أم عمرو ... ورحلة أهلها نحو العراق)\n(فليس إلى زيارتها سبيل ... ولا حتى القيامة من تلاقي)\n(وعل الله يرجعها إلينا ... بموت من حليل أو طلاق)\n(فأرجع شامتا وتقر عيني ... ويجمع شملنا بعد افتراق)","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":10,"spl":"وصية سعيد بن العاص — أبو قطيفة يهجو عبد الملك بن مروان"},
{"id":"b1-19","bab":"الجزء 1","sec":"مقتل سعيد بن عثمان","page":"ج1 ص42","text":"أخبرني عمي ومحمد بن جعفر قالا حدثنا الحسن بن عليل العنزي قال حدثنا محمد بن علي بن أبي حسان عن هشام بن محمد عن خالد بن سعيد عن أبيه قال استعمل معاوية سعيد بن عثمان على خراسان فلما عزله قدم المدينة بمال وسلاح وثلاثين عبدا من السغد فأمرهم أن يبنوا له دارا فبينا هو جالس فيها ومعه ابن سيحان وابن زينة وخالد بن عقبة وأبو قطيفة إذ تآمروا بينهم فقتلوه فقال أبو قطيفة يرثيه وقيل إنها لخالد بن عقبة\n(يا عين جودي بدمع منك تهتانا ... وابكي سعيد بن عثمان بن عفانا)\n(إن ابن زينة لم تصدق مودته ... وفر عنه ابن أرطاة بن سيحانا)","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":11,"spl":"مقتل سعيد بن عثمان — سلامة القس ترثي معبدا"},
{"id":"b1-20","bab":"الجزء 1","sec":"ذكر معبد وبعض أخباره","page":"ج1 ص43","text":"هو معبد بن وهب وقيل ابن قطني مولى ابن قطر وقيل ابن قطن مولى العاص بن وابصة المخزومي وقيل بل مولى معاوية بن أبي سفيان أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عبد الرحمن بن عبد الله الزهري قال معبد المغني ابن وهب مولى عبد الرحمن بن قطر وأخبرني الحسين بن يحيى عن حماد عن أبيه قال قال ابن الكلبي معبد مولى ابن قطر والقطريون موالي معاوية بن أبي سفيان وأخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة قال حدثنا أبو غسان قال معبد بن وهب مولى ابن قطن وهم موالي آل وابصة من بني مخزوم وكان أبوه أسود وكان هو خلاسيا مديد القامة أحول وذكر ابن خرداذبه أنه غنى في أول دولة بني أمية وأدرك دولة بني العباس وقد أصابه الفالج وارتعش وبطل فكان إذا غنى يضحك منه ويهزأ به وابن خرداذبه قليل التصحيح لما يرويه ويضمنه كتبه والصحيح أن معبدا مات في أيام\nالوليد بن يزيد بدمشق وهو عنده وقد قيل إنه أصابه الفالج قبل موته وارتعش وبطل صوته فأما إدراكه دولة بني العباس فلم يروه أحد سوى ابن خرداذبه ولا قاله ولا رواه عن أحد وإنما جاء به مجازفة","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":11,"spl":"مقتل سعيد بن عثمان — سلامة القس ترثي معبدا"},
{"id":"b1-21","bab":"الجزء 1","sec":"سلامة القس ترثي معبدا","page":"ج1 ص44","text":"أخبرني محمد بن العباس اليزيدي قال حدثنا عمر بن شبة قال حدثني أيوب ابن عمر أبو سلمة المديني قال حدثنا عبد الله بن عمران بن أبي فروة قال حدثني كردم بن معبد المغني مولى ابن قطن قال مات أبي وهو في عسكر الوليد بن يزيد وأنا معه فنظرت حين أخرج نعشه إلى سلامة القس جارية يزيد بن عبد الملك وقد أضرب الناس عنه ينظرون إليها وهي آخذة بعمود السرير وهي تبكي أبي وتقول\n(قد لعمري بت ليلي ... كأخي الداء الوجيع)\n(ونجي الهم مني ... بات أدنى من ضجيعي)\n(كلما أبصرت ربعا ... خاليا فاضت دموعي)\n(قد خلا من سيد كان ... لنا غير مضيع)\n(لا تلمنا إن خشعنا ... أو هممنا بخشوع)\nقال كردم وكان يزيد أمر أبي أن يعلمها هذا الصوت فعلمها إياه فندبته به يومئذ قال فلقد رأيت الوليد بن يزيد والغمر أخاه متجردين في قميصين ورداءين يمشيان بين يدي سريره حتى أخرج من دار الوليد لأنه تولى أمره وأخرجه من داره إلى موضع قبره فأما نسبة هذا الصوت فإن الشعر للأحوص والغناء لمعبد ذكره يونس ولم يجنسه وذكر الهشامي أنه ثاني ثقيل بالوسطى قال وفيه لحبابة خفيف ثقيل ولابن المكي ثقيل أول نشيد وفيه لسلامة القس عن إسحاق لحن من القدر الأوسط من الثقيل الأول بالوسطى في مجراها أخبرني الحسين بن يحيى عن حماد عن أبيه قال قال أبو عبيدة ذكر مولى لآل الزبير وكان منقطعا إلى جعفر ومحمد ابني سليمان بن علي أن معبدا عاش حتى كبر وانقطع صوته فدعاه رجل من ولد عثمان فلما غنى الشيخ لم يطرب القوم وكان فيهم فتيان نزول من ولد أسيد بن أبي العيص بن أمية فضحكوا منه وهزئوا به فأنشأ يغني\n(فضحتم قريشا بالفرار وأنتم ... قمدون سودان عظام المناكب)\n(فأما القتال لا قتال لديكم ... ولكن سيرا في عراض المواكب)\nوهذا شعر هجوا به قديما فقاموا إليه ليتناولوه فمنعهم العثماني من ذلك وقال ضحكتم منه حتى إذا أحفظتموه أردتم أن تتناولوه لا والله لا يكون ذلك قال إسحاق فحدثني ابن سلام قال أخبرني من رآه على هذه الحال فقال له أصرت إلى ما أرى فأشار إلى حلقه وقال إنما كان هذا فلما ذهب ذهب كل شيء","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":11,"spl":"مقتل سعيد بن عثمان — سلامة القس ترثي معبدا"},
{"id":"b1-22","bab":"الجزء 1","sec":"معبد أمير الغناء","page":"ج1 ص46","text":"قال إسحاق كان معبد من أحسن الناس غناء وأجودهم صنعة وأحسنهم حلقا وهو فحل المغنين وإمام أهل المدينة في الغناء وأخذ عن سائب خاثر ونشيط مولى عبد الله بن جعفر وعن جميلة مولاة بهز بطن من سليم وكان زوجها مولى لبني الحارث بن الخزرج فقيل لها مولاة الأنصار لذلك وفي معبد يقول الشاعر\n(أجاد طويس والسريجي بعده ... وما قصبات السبق إلا لمعبد)\nال إسحاق قال ابن الكلبي عن أبيه كان ابن أبي عتيق خرج إلى مكة فجاء معه ابن سريج إلى المدينة فأسمعوه غناء معبد وهو غلام وذلك في أيام مسلم بن عقبة المري وقالوا ما تقول فيه فقال إن عاش كان مغني بلاده ولمعبد صنعة لم يسبقه إليها من تقدم ولا زاد عليه فيها من تأخر وكانت صناعته التجارة في أكثر أيام رقه وربما رعى الغنم لمواليه وهو مع ذلك يختلف إلى نشيط\nالفارسي وسائب خاثر مولى عبد الله بن جعفر حتى اشتهر بالحذق وحسن الغناء وطيب الصوت وصنع الألحان فأجاد واعترف له بالتقدم على أهل عصره أخبرني الحسين بن يحيى قال قال حماد قرأت على أبي قال الجمحي بلغني أن معبدا قال والله لقد صنعت ألحانا لا يقدر شبعان ممتلىء ولا سقاء يحمل قربة على الترنم بها ولقد صنعت ألحانا لا يقدر المتكىء أن يترنم بها حتى يقعد مستوفزا ولا القاعد حتى يقوم قال إسحاق وبلغني أن معبدا أتى ابن سريج وابن سريج لا يعرفه فسمع منه ما شاء ثم عرض نفسه عليه وغناه وقال له كيف كنت تسمع جعلت فداءك فقال له لو شئت كنت قد كفيت بنفسك الطلب من غيرك قال وسمعت من لا أحصي من أهل العلم بالغناء يقولون لم يكن فيمن غنى أحد أعلم بالغناء من معبد قال وحدثني أيوب بن عباية قال دخلت على الحسن بن مسلم أبي العراقيب وعنده جاريته عاتكة فتحدث فذكر معبدا فقال أدركته يلبس ثوبين ممشقين وكان إذا غنى علا منخراه فقالت عاتكة يا سيدي أو أدركت معبدا قال إي والله وأقدم من معبد فقالت استحييت لك من هذا الكبر أخبرني الحسين بن يحيى قال نسخت من كتاب حماد قرأت على أبي أخبرني محمد بن سلام قال حدثني جرير قال قال معبد قدمت مكة فقيل لي إن ابن صفوان قد سبق بين المغنين جائزة فأتيت بابه فطلبت الدخول فقال لي\nآذنه قد تقدم إلي ألا آذن لأحد عليه ولا أؤذنه به قال فقلت دعني أدنو من الباب فأغني صوتا قال أما هذا فنعم فدنوت من الباب فغنيت صوتا فقالوا معبد وفتحوا لي فأخذت الجائزة يومئذ أخبرني الحسين قال نسخت من كتاب حماد قال أبي وذكر عورك وهو الحسن بن عتبة اللهبي أن الوليد بن يزيد كان يقول ما أقدر على الحج فقيل له وكيف ذاك قال يستقبلني أهل المدينة بصوتي معبد\n(القصر فالنخل فالجماء بينهما ... )\nقتيلة يعني حنه\n(يوم تبدي لنا قتيلة عن جيد ... تليع تزينه الأطواق)","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":12,"spl":"معبد أمير الغناء — كيف يغني معبد","partialRef":{"sid":"b1-1","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b1-23","bab":"الجزء 1","sec":"كيف يغني معبد","page":"ج1 ص48","text":"قال إسحاق قيل لمعبد كيف تصنع إذا أردت أن تصوغ الغناء قال أرتحل قعودي وأوقع بالقضيب على رحلي وأترنم عليه بالشعر حتى يستوي لي الصوت فقيل له ما أبين ذلك في غنائك\nقال إسحاق وقال مصعب الزبيري قال يحيى بن عباد بن حمزة بن عبد الله بن الزبير حدثني أبي قال قال معبد كنت غلاما مملوكا لآل قطن مولى بني مخزوم وكنت أتلقى الغنم بظهر الحرة وكانوا تجارا أعالج لهم التجارة في ذلك فآتي صخرة بالحرة ملقاة بالليل فأستند إليها فأسمع وأنا نائم صوتا يجري في مسامعي فأقوم من النوم فأحكيه فهذا كان مبدأ غنائي أخبرني الحسين بن يحيى قال نسخت من كتاب حماد قال أبي قال محمد بن سعيد الدوسي عن أبيه ومحمد بن يزيد عن سعيد الدوسي عن الربيع بن أبي الهيثم قال كنا جلوسا مع عبد الله بن جعفر بن أبي طالب فقال إنسان لمالك أنشدك الله أنت أحسن غناء أم معبد فقال مالك والله ما بلغت شراكه قط والله لو لم يغن معبد إلا قوله\n(لعمر أبيها لا تقول حليلتي ... ألا فر عني مالك بن أبي كعب)\n(وهم يضربون الكبش تبرق بيضه ... ترى حوله الأبطال في حلق شهب)\nكان حسبه قال وكان مالك إذا غنى غناء معبد يخفف منه ثم يقول أطال الشعر معبد ومططه وحذفته أنا وتمام هذا الصوت","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":12,"spl":"معبد أمير الغناء — كيف يغني معبد"},
{"id":"b1-24","bab":"الجزء 1","sec":"صوت من غير المائة المختارة","page":"ج1 ص50","text":"(لعمر أبيها لا تقول حليلتي ... ألا فر عني مالك بن أبي كعب)\n(وهم يضربون الكبش تبرق بيضه ... ترى حوله الأبطال في حلق شهب)\n(إذا أنفدوا الزق الروي وصرعوا ... نشاوى فلم أقطع بقولي لهم حسبي)\n(بعثت إلى حانوتها فسبأتها ... بغير مكاس في السوام ولا غضب)\nروضه من الطويل والشعر لمالك بن أبي كعب بن القين الخزرجي أحد بني سلمة هكذا ذكر إسحاق وغيره يذكر أنه من مراد ولهذا الشعر خبر طويل يذكر بعد هذا والغناء في البيتين الأولين لمعبد ثقيل أول بالوسطى ومن الناس من ينسبه إلى ابن سريج ولمالك في الثالث والرابع من الأبيات لحن من الثقيل الأول بالسبابة في مجرى البنصر عن إسحاق ومن الناس من ينسب هذا اللحن إلى معبد ويقول إن مالكا أخذ لحنه منه فحذف بعض نغمه وانتحله وإن اللحن لمعبد في الأبيات الأربعة وقد ذكر أن هذا الشعر لرجل من مراد وروي له فيه حديث طويل وقد أخرج خبره في ذلك وخبر مالك بن أبي كعب الخزرجي أبي كعب بن مالك صاحب رسول الله في موضع آخر أفرد له إذ كانت له أخبار\nكثيرة ولأجله لا تصلح أن تذكر هاهنا رجع الخبر إلى معبد أخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة قال حدثنا أبو غسان عن يونس الكاتب قال أقبلت من عند معبد فلقيني ابن محرز ببطحان فقال من أين أقبلت قلت من عند أبي عباد فقال ما أخذت عنه قلت غنى صوتا فأخذته قال وما هو قلت\n(ماذا تأمل واقف جملا ... في ربع دار عابه قدمه)\nلشعر لخالد بن المهاجر بن خالد بن الوليد فقال لي ادخل معي دار ابن هرمة وألقه علي فدخلت معه فما زلت أردده عليه حتى غناه ثم قال إرجع معي إلى أبي عباد فرجعنا فسمعه منه ثم لم تفترق حتى صنع فيه ابن محرز لحنا آخر","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":13,"spl":"صوت من غير المائة المختارة — غناء معبد يصدم ابن سريج والغريض"},
{"id":"b1-25","bab":"الجزء 1","sec":"نسبة هذا الصوت","page":"ج1 ص51","text":"صوت\n(ماذا تأمل واقف جملا ... في ربع دار عابه قدمه)\n(أقوى وأقفر غير منتصب ... لبد الرمادة ناصع حممه)\nغناه معبد ولحنه ثقيل أول بالسبابة في مجرى الوسطى وفيه خفيف ثقيل أول بالوسطى ينسب إلى الغريض وإلى ابن محرز وذكر عمرو بن بانة أن الثقيل الأول للغريض وذكر حبش أن فيه لمالك ثاني ثقيل بالوسطى وفيه رمل بالوسطى ينسب إلى سائب خاثر وذكر حبش أنه لإسحاق","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":13,"spl":"صوت من غير المائة المختارة — غناء معبد يصدم ابن سريج والغريض"},
{"id":"b1-26","bab":"الجزء 1","sec":"غناء معبد يصدم ابن سريج والغريض","page":"ج1 ص52","text":"أخبرني الحسين بن يحيى قال نسخت من كتاب حماد قال أبي قال ابن الكلبي قدم ابن سريج والغريض المدينة يتعرضان لمعروف أهلها ويزوران من بها من صديقهما من قريش وغيرهم فلما شارفاها تقدما ثقلهما ليرتادا منزلا حتى إذا كانا بالمغسلة وهي جبانة على طرف المدينة يغسل فيها الثياب إذا هما بغلام ملتحف بإزار وطرفه على رأسه بيده حبالة يتصيد بها الطير وهو يتغنى ويقول\n(القصر فالنخل فالجماء بينهما ... أشهى إلى النفس من أبواب جيرون)\nإذا الغلام معبد قال فلما سمع ابن سريج والغريض معبدا مالا إليه واستعاداه الصوت فأعاده فسمعا شيئا لم يسمعا بمثله قط فأقبل أحدهما على صاحبه فقال هل سمعت كاليوم قط قال لا والله فما رأيك قال ابن سريج هذا غناء غلام يصيد الطير فكيف بمن في الجوبة يعني المدينة قال أما أنا فثكلته والدته إن لم أرجع قال فكرا راجعين\nقال وقال معبد قدمت مكة فذهب بي بعض القرشيين إلى الغريض فدخلنا عليه وهو متصبح فانتبه من صحبته وقعد فسلم عليه القرشي وسأله فقال له هذا معبد قد أتيتك به وأنا أحب أن تسمع منه قال هات فغنيته أصواتا فقال بمدرى معه في رأسه ثم قال إنك يا معبد لمليح الغناء قال فأحفظني ذلك فجثوت على ركبتي ثم غنيته من صنعتي عشرين صوتا لم يسمع بمثلها قط وهو مطرق واجم قد تغير لونه حسدا وخجلا","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":13,"spl":"صوت من غير المائة المختارة — غناء معبد يصدم ابن سريج والغريض"},
{"id":"b1-27","bab":"الجزء 1","sec":"معبد وحكم الوادي والعبد الأسود","page":"ج1 ص53","text":"قال إسحاق وأخبرت عن حكم الوادي قال كنت أنا وجماعة من المغنين نختلف إلى معبد نأخذ عنه ونتعلم منه فغنانا يوما صوتا من صنعته وأعجب به وهو\n(القصر فالنخل فالجماء بينهما ... )\nاستحسناه وعجبنا منه وكنت في ذلك اليوم أول من أخذه عنه واستحسنه مني فأعجبتني نفسي فلما انصرفت من عند معبد عملت فيه لحنا آخر وبكرت على معبد مع أصحابي وأنا معجب بلحني فلما تغنينا أصواتا قلت له إني قد عملت بعدك في الشعر الذي غنيتناه لحنا واندفعت فغنيته صوتي فوجم معبد ساعة يتعجب مني ثم قال قد كنت أمس أرجى مني لك اليوم وأنت اليوم عندي أبعد من الفلاح قال حكم فأنسيت يعلم الله صوتي ذلك منذ تلك الساعة فما ذكرته إلى وقتي هذا\nقال إسحاق وقال معبد بعث إلي بعض أمراء الحجاز وقد كان جمع له الحرمان أن أشخص إلى مكة فشخصت قال فتقدمت غلامي في بعض تلك الأيام واشتد علي الحر والعطش فانتهيت إلى خباء فيه أسود وإذا حباب ماء قد بردت فملت إليه فقلت يا هذا اسقني من هذا الماء فقال لا فقلت فأذن لي في الكن ساعة قال لي فأنخت ناقتي ولجأت إلى ظلها فاستترت به وقلت لو أحدثت لهذا الأمير شيئا من الغناء أقدم به عليه ولعلي إن حركت لساني أن يبل حلقي ريقي فيخفف عني بعض ما أجده من العطش فترنمت بصوتي\n(القصر فالنخل فالجماء بينهما ... )\nلما سمعني الأسود ما شعرت به إلا وقد احتملني حتى أدخلني خباءه ثم قال أي بأبي أنت وأمي هل لك في سويق السلت بهذا الماء البارد فقلت قد منعتني أقل من ذلك وشربة ماء تجزئني قال فسقاني حتى رويت وجاء الغلام فأقمت عنده إلى وقت الرواح فلما أردت الرحلة قال أي بأبي أنت وأمي الحر شديد ولا آمن عليك مثل الذي أصابك فأذن لي في أن أحمل معك قربة من ماء على عنقي وأسعى بها معك فكلما عطشت سقيتك صحنا وغنيتني صوتا قال قلت ذاك لك فوالله ما فارقني يسقيني وأغنيه حتى بلغت المنزل نسخت من كتاب جعفر بن قدامة بخطه حدثني حماد بن إسحاق عن أبيه\nعن الزبير عن جرير قال","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":14,"spl":"معبد وحكم الوادي والعبد الأسود — نسبة هذين الصوتين وأخبارهما","partialRef":{"sid":"b1-1","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b1-28","bab":"الجزء 1","sec":"التقاء معبد وابن سريج ببطن مر","page":"ج1 ص55","text":"كان معبد خارجا إلى مكة في بعض أسفاره فسمع في طريقه غناء في بطن مر فقصد الموضع فإذا رجل جالس على حرف بركة فارق شعره حسن الوجه عليه دراعة قد صبغها بزعفران وإذا هو يتغنى صوت\n(حن قلبي من بعد ما قد أنابا ... ودعا الهم شجوه فأجابا)\n(ذاك من منزل لسلمى خلاء ... لابس من خلائه جلبابا)\n(عجت فيه وقلت للركب عوجوا ... طمعا أن يرد ربع جوابا)\n(فاستثار المنسي من لوعة الحب ... وأبدى الهموم والأوصابا)\nقرع معبد بعصاه وغنى\n(منع الحياة من الرجال ونفعها ... حدق تقلبها النساء مراض)\n(وكأن أفئدة الرجال إذا رأوا ... حدق النساء لنبلها أغراض)\nفقال له ابن سريج بالله أنت معبد قال نعم وبالله أنت ابن سريج قال نعم ووالله لو عرفتك ما غنيت بين يديك","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":14,"spl":"معبد وحكم الوادي والعبد الأسود — نسبة هذين الصوتين وأخبارهما"},
{"id":"b1-29","bab":"الجزء 1","sec":"نسبة هذين الصوتين وأخبارهما","page":"ج1 ص56","text":"صوت\n(حن قلبي من بعد ما قد أنابا ... ودعا الهم شجوه فأجابا)\n(فاستثار المنسي من لوعة الحب ... وأبدى الهموم والأوصابا)\n(ذاك من منزل لسلمى خلاء ... مكتس من عفائه جلبابا)\n(عجت فيه وقلت للركب عوجوا ... طمعا أن يرد ربع جوابا)\n(ثانيا من زمام وجناء عنس ... قانيا لونها يخال خضابا)\n(جدها الفالج الأشم من البخت ... وخالاتها انتخبن عرابا)\nلشعر لعمر بن أبي ربيعة والغناء لابن سريج وله فيه لحنان رمل بالسبابة في مجرى البنصر عن إسحاق وخفيف ثقيل أول بالبنصر عن عمرو صوت\n(منع الحياة من الرجال ونفعها ... حدق تقلبها النساء مراض)\n(وكأن أفئدة الرجال إذا رأوا ... حدق النساء لنبلها أغراض)\nلشعر للفرزدق والغناء لمعبد ثقيل أول عن الهشامي أخبرني محمد بن مزبد بن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه عن سياط قال حدثني يونس الكاتب قال","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":14,"spl":"معبد وحكم الوادي والعبد الأسود — نسبة هذين الصوتين وأخبارهما"},
{"id":"b1-30","bab":"الجزء 1","sec":"معبد مع الجواري في السفينة","page":"ج1 ص57","text":"كان معبد قد علم جارية من جواري الحجاز الغناء تدعى ظبية وعني بتخريجها فاشتراها رجل من أهل العراق فأخرجها إلى البصرة وباعها هناك فاشتراها رجل من أهل الأهواز فأعجب بها وذهبت به كل مذهب وغلبت عليه ثم ماتت بعد أن أقامت عنده برهة من الزمان وأخذ جواريه أكثر غنائها عنها فكان لمحبته إياها وأسفه عليها لا يزال يسأل عن أخبار معبد وأين مستقره ويظهر التعصب والميل إليه والتقديم لغنائه على سائر أغاني أهل عصره إلى أن عرف ذلك منه وبلغ معبدا خبره فخرج من مكة حتى أتى البصرة فلما وردها صادف الرجل قد خرج عنها في ذلك اليوم إلى الأهواز فاكترى سفينة وجاء معبد يلتمس سفينة ينحدر فيها إلى الأهواز فلم يجد غير سفينة الرجل وليس يعرف أحد منهما صاحبه فأمر الرجل الملاح أن يجلسه معه في مؤخر السفينة ففعل وانحدروا فلما صاروا في فم نهر الأبلة تغدوا وشربوا وأمر جواريه فغنين ومعبد ساكت وهو في ثياب السفر وعليه فرو وخفان غليظان وزي جاف من زي أهل الحجاز إلى أن غنت إحدى الجواري صوت\n(بانت سعاد وأمسى حبلها انصرما ... واحتلت الغور فالأجزاع من إضما)\n(إحدى بلي هام الفؤاد بها ... إلا السفاه وإلا ذكرة حلما)\nال حماد والشعر للنابغة الذبياني والغناء لمعبد خفيف ثقيل أول بالبنصر وفيه لغيره ألحان قديمة ومحدثة فلم تجد أداءه فصاح بها معبد يا جارية إن غناءك هذا ليس بمستقيم قال فقال له مولاها وقد غضب وأنت ما يدريك الغناء ما هو ألا تمسك وتلزم شأنك فأمسك ثم غنت أصواتا من غناء غيره وهو ساكت لا يتكلم حتى غنت صوت\n(بابنة الأزدي قلبي كئيب ... مستهام عندها ما ينيب)\n(ولقد لاموا فقلت دعوني ... إن من تنهون عنه حبيب)\n(إنما أبلى عظامي وجسمي ... حبها والحب شيء عجيب)\n(أيها العائب عندي هواها ... أنت تفدي من أراك تعيب)\nالشعر لعبد الرحمن بن أبي بكر والغناء لمعبد ثقيل أول بالسبابة في مجرى البنصر قال فأخلت ببعضه فقال لها معبد يا جارية لقد أخللت بهذا الصوت إخلالا شديدا فغضب الرجل وقال له ويلك ما أنت والغناء ألا تكف عن هذا الفضول فأمسك وغنى الجواري مليا ثم غنت إحداهن صوت\n(خليلي عوجا فأبكيا ساعة معي ... على الربع نقضي حاجة ونودع)\n(ولا تعجلاني أن ألم بدمنة ... لعزة لاحت لي ببيداء بلقع)\n(وقولا لقلب قد سلا راجع الهوى ... وللعين أذري من دموعك أو دعي)\n(فلا عيش إلا مثل عيش مضى لنا ... مصيفا أقمنا فيه من بعد مربع)\nلشعر لكثير والغناء لمعبد خفيف ثقيل بالسبابة في مجرى الوسطى وفيه رمل للغريض","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":15,"spl":"معبد مع الجواري في السفينة"},
{"id":"b1-31","bab":"الجزء 1","sec":"إعجاب الجواري بغناء معبد","page":"ج1 ص59","text":"قال فلم تصنع فيه شيئا فقال لها معبد يا هذه أما تقوين على أداء صوت واحد فغضب الرجل وقال له ما أراك تدع هذا الفضول بوجه ولا حيلة وأقسم بالله لئن عاودت لأخرجنك من السفينة فأمسك معبد حتى إذا سكتت الجواري سكتة اندفع يغني الصوت الأول حتى فرغ منه فصاح الجواري يا رجل فأعده فقال لا والله ولا كرامة ثم اندفع يغني الثاني فقلن لسيدهن ويحك هذا والله أحسن الناس غناء فسله أن يعيده علينا ولو مرة واحدة لعلنا نأخذه عنه فإنه إن فاتنا لم نجد مثله أبدا فقال قد سمعتن سوء رده عليكن وأنا خائف مثله منه وقد أسلفناه الإساءة فاصبرن حتى نداريه ثم غنى الثالث فزلزل عليهم الأرض فوثب الرجل فخرج إليه وقبل رأسه وقال يا سيدي أخطأنا عليك ولم نعرف موضعك فقال له فهبك لم تعرف موضعي قد كان ينبغي لك أن تتثبت ولا تسرع إلي بسوء العشرة وجفاء القول فقال له قد أخطأت وأنا أعتذر إليك مما جرى وأسألك أن تنزل إلي وتختلط بي فقال أما الآن فلا فلم يزل يرفق به حتى نزل إليه فقال له الرجل ممن أخذت هذا الغناء قال من بعض أهل الحجاز فمن أين أخذه من جارية كانت لي ابتاعها رجل من أهل البصرة من مكة وكانت قد أخذت عن أبي عباد معبد وعني\nبتخريجها فكانت تحل مني محل الروح من الجسد ثم استأثر الله عز و جل بها وبقي هؤلاء الجواري وهن من تعليمها فأنا إلى الآن أتعصب لمعبد وأفضله على المغنين جميعا وأفضل صنعته على كل صنعة فقال له معبد أو إنك لأنت هو أفتعرفني قال لا قال فصك معبد بيده صلعته ثم قال فأنا والله معبد وإليك قدمت من الحجاز ووافيت البصرة ساعة نزلت السفينة لأقصدك بالأهواز ووالله لا قصرت في جواريك هؤلاء ولأجعلن لك في كل واحدة منهن خلفا من الماضية فأكب الرجل والجواري على يديه ورجليه يقبلونها ويقولون كتمتنا نفسك طول هذا اليوم حتى جفوناك في المخاطبة وأسأنا عشرتك وأنت سيدنا ومن نتمنى على الله أن نلقاه ثم غير الرجل زيه وحاله وخلع عليه عدة خلع وأعطاه في وقته ثلثمائة دينار وطيبا وهدايا بمثلها وانحدر معه إلى الأهواز فأقام عنده حتى رضي حذق جواريه وما أخذنه عنه ثم ودعه وانصرف إلى الحجاز","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":16,"spl":"إعجاب الجواري بغناء معبد"},
{"id":"b1-32","bab":"الجزء 1","sec":"معبد يغني للوليد بن يزيد","page":"ج1 ص60","text":"أخبرني الحسن بن علي الخفاف وعبد الباقي بن قانع قالا حدثنا محمد بن زكريا الغلابي قال حدثني مهدي بن سابق قال حدثني سليمان بن غزوان مولى هشام قال حدثني عمر القاري بن عدي قال قال الوليد بن يزيد يوما لقد اشتقت إلى معبد فوجه البريد إلى المدينة\nفأتى بمعبد وأمر الوليد ببركة قد هيئت له فملئت بالخمر والماء وأتي بمعبد فأمر به فأجلس والبركة بينهما وبينهما ستر قد أرخي فقال له غنني يا معبد صوت\n(لهفي على فتية ذل الزمان لهم ... فما أصابهم إلا بما شاؤوا)\n(ما زال يعدو عليهم ريب دهرهم ... حتى تفانوا وريب الدهر عداء)\n(أبكى فراقهم عيني وأرقها ... إن التفرق للأحباب بكاء)\nلغناء لمعبد خفيف ثقيل وفيه ليحيى المكي رمل ولسليمان هزج كلها رواية الهشامي قال فغناه إياه فرفع الوليد الستر ونزع ملاءة مطيبة كانت عليه وقذف نفسه في تلك البركة فنهل فيها نهلة ثم أتي بأثواب غيرها وتلقوه بالمجامر والطيب ثم قال غنني صوت\n(يا ربع مالك لا تجيب متيما ... قد عاج نحوك زائرا ومسلما)\n(جادتك كل سحابة هطالة ... حتى ترى عن زهرة متبسما)\nلغناء لمعبد ثاني ثقيل بالوسطى والخنصر عن ابن المكي وفيه لعلوية ثاني ثقيل آخر بالبنصر في مجراها عنه قال فغناه فدعا له بخمسة عشر ألف دينار فصبها بين يديه ثم قال انصرف إلى أهلك واكتم ما رأيت\nوأخبرني بهذا الخبر عمي فجاء ببعض معانيه وزاد فيه ونقص قال حدثني هارون بن محمد بن عبد الملك الزيات قال حدثني سليمان بن سعد الحلبي قال سمعت القاري بن عدي يقول اشتاق الوليد بن يزيد إلى معبد فوجه إليه إلى المدينة فأحضر وبلغ الوليد قدومه فأمر ببركة بين يدي مجلسه فملئت ماء ورد قد خلط بمسك وزعفران ثم فرش للوليد في داخل البيت على حافة البركة وبسط لمعبد مقابله على حافة البركة ليس معهما ثالث وجيء بمعبد فرأى سترا مرخى ومجلس رجل واحد فقال له الحجاب يا معبد سلم على أمير المؤمنين واجلس في هذا الموضع فسلم فرد عليه الوليد السلام من خلف الستر ثم قال له حياك الله يا معبد أتدري لم وجهت إليك قال الله أعلم وأمير المؤمنين قال ذكرتك فأحببت أن أسمع منك قال معبد أأغني ما حضر أم ما يقترحه أمير المؤمنين قال بل غنني\n(ما زال يعدو عليهم ريب دهرهم ... حتى تفانوا وريب الدهر عداء)\nغناه فما فرغ منه حتى رفع الجواري السجف ثم خرج الوليد فألقى نفسه في البركة فغاص فيها ثم خرج منها فاستقبله الجواري بثياب غير الثياب الأولى ثم شرب وسقى معبدا ثم قال له غنني يا معبد\n(يا ربع مالك لا تجيب متيما ... قد عاج نحوك زائرا ومسلما)\n(جادتك كل سحابة هطالة ... حتى ترى عن زهرة متبسما)\n(لو كنت تدري من دعاك أجبته ... وبكيت من حرق عليه إذا دما)\nال فغناه وأقبل الجواري فرفعن الستر وخرج الوليد فألقى نفسه في البركة فغاص فيها ثم خرج فلبس ثيابا غير تلك ثم شرب وسقى معبدا ثم قال له غنني فقال بماذا يا أمير المؤمنين قال غنني\n(عجبت لما رأتني ... أندب الربع المحيلا)\n(واقفا في الدار أبكي ... لا أرى إلا الطلولا)\n(كيف تبكي لأناس ... لا يملون الذميلا)\n(كلما قلت اطمأنت ... دارهم قالوا الرحيلا)\nقال فلما غناه رمى نفسه في البركة ثم خرج فردوا عليه ثيابه ثم شرب وسقى معبدا ثم أقبل عليه الوليد فقال له يا معبد من أراد أن يزداد عند الملوك حظوة فليكتم أسرارهم فقلت ذلك ما لا يحتاج أمير المؤمنين إلى إيصائي به فقال يا غلام احمل إلى معبد عشرة آلاف دينار تحصل له في بلده وألفي دينار لنفقة طريقه فحملت إليه كلها وحمل على البريد من وقته إلى المدينة","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":17,"spl":"معبد يغني للوليد بن يزيد"},
{"id":"b1-33","bab":"الجزء 1","sec":"معبد والرجل الشامي","page":"ج1 ص63","text":"قال إسحاق وقال معبد أرسل إلي الوليد بن يزيد فأشخصت إليه فبينا أنا يوما في بعض حمامات الشأم إذ دخل علي رجل له هيبة ومعه غلمان له فاطلى واشتغل به صاحب الحمام عن سائر الناس فقلت والله لئن لم أطلع هذا على بعض ما عندي لأكونن بمزجر الكلب فاستدبرته حيث يراني ويسمع مني ثم ترنمت فالتفت إلي وقال للغلمان قدموا إليه جميع ما هاهنا فصار جميع ما\nكان بين يديه عندي قال ثم سألني أن أسير معه إلى منزله فأجبته فلم يدع من البر والإكرام شيئا إلا فعله ثم وضع النبيذ فجعلت لا آتي بحسن إلا خرجت إلى ما هو أحسن منه وهو لا يرتاح ولا يحفل لما يرى مني فلما طال عليه أمري قال يا غلام شيخنا شيخنا فأتي بشيخ فلما رآه هش إليه فأخذ الشيخ العود ثم اندفع يغني\n(سلور في القدر ويلي علوه ... جاء القط أكله ويلي علوه)\nلسلور السمك الجري بلغة أهل الشأم قال فجعل صاحب المنزل يصفق ويضرب برجله طربا وسرورا قال ثم غناه\n(وترميني حبيبة بالدراقن ... وتحسبني حبيبة لا أراها)\nلدراقن اسم الخوخ بلغة أهل الشأم قال فكاد أن يخرج من جلده طربا قال وانسللت منهم فانصرفت ولم يعلم بي فما رأيت مثل ذلك اليوم قط غناء أضيع ولا شيخا أجهل","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":18,"spl":"معبد والرجل الشامي — معبد مع المغنين في مكة"},
{"id":"b1-34","bab":"الجزء 1","sec":"ابن عائشة يقتبس من غناء معبد","page":"ج1 ص64","text":"قال إسحاق وذكر لي شيخ من أهل المدينة عن هارون بن سعد أن ابن عائشة كان يلقي عليه وعلى ربيحة الشماسية فدخل معبد فألقى عليهما صوتا\nفاندفع ابن عائشة يغنيه وقد أخذه منه فغضب معبد وقال أحسنت يابن عاهرة الدار تفاخرني فقال لا والله جعلني الله فداءك يا أبا عباد ولكني أقتبس منك وما أخذته إلا عنك ثم قال أنشدك الله يا ابن شماس هل قلت لك قد جاء أبو عباد فاجمع بيني وبينه أقتبس منه قال اللهم نعم أخبرني الحسين بن يحيى عن حماد عن أبيه قال قيل لابن عائشة وقد غنى صوتا أحسن فيه فقال أصبحت أحسن الناس غناء فقيل له وكيف أصبحت أحسن الناس غناء قال وما يمنعني من ذلك وقد أخذت من أبي عباد أحد عشر صوتا وأبو عباد مغني أهل المدينة والمقدم فيهم أخبرنا وكيع قال حدثنا حماد بن إسحاق قال حدثني أبي قال حدثني أيوب ابن عباية عن رجل من هذيل قال","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":18,"spl":"معبد والرجل الشامي — معبد مع المغنين في مكة"},
{"id":"b1-35","bab":"الجزء 1","sec":"معبد مع المغنين في مكة","page":"ج1 ص65","text":"قال معبد غنيت فأعجبني غنائي وأعجب الناس وذهب لي به صيت وذكر فقلت لآتين مكة فلأسمعن من المغنين بها ولأغنينهم ولأتعرفن إليهم فابتعت حمارا فخرجت عليه إلى مكة فلما قدمتها بعت حماري وسألت عن المغنين أين يجتمعون فقيل بقعيقعان في بيت فلان فجئت إلى منزله بالغلس فقرعت\nالباب فقال من هذا فقلت انظر عافاك الله فدنا وهو يسبح ويستعيذ كأنه يخاف ففتح فقال من أنت عافاك الله قلت رجل من أهل المدينة قال فما حاجتك قلت أنا رجل أشتهي الغناء وأزعم أني أعرف منه شيئا وقد بلغني أن القوم يجتمعون عندك وقد أحببت أن تنزلني في جانب منزلك وتخلطني بهم فإنه لا مؤونة عليك ولا عليهم مني فلوى شيئا ثم قال انزل على بركة الله قال فنقلت متاعي فنزلت في جانب حجرته ثم جاء القوم حين أصبحوا واحدا بعد واحد حتى اجتمعوا فأنكروني وقالوا من هذا الرجل قال رجل من أهل المدينة خفيف يشتهي الغناء ويطرب عليه ليس عليكم منه عناء ولا مكروه فرحبوا بي وكلمتهم ثم انبسطوا وشربوا وغنوا فجعلت أعجب بغنائهم وأظهر ذلك لهم ويعجبهم مني حتى أقمنا أياما وأخذت من غنائهم وهم لا يدرون أصواتا وأصواتا وأصواتا ثم قلت لابن سريج أي فديتك أمسك علي صوتك\n(قل لهند وتربها ... قبل شحط النوى غدا)\nقال أو تحسن شيئا قلت تنظر وعسى أن أصنع شيئا واندفعت فيه فغنيته فصاح وصاحوا وقالوا أحسنت قاتلك الله قلت فأمسك علي صوت كذا فأمسكوه علي فغنيته فازدادوا عجبا وصياحا فما تركت واحدا منهم إلا غنيته من غنائه أصواتا قد تخيرتها قال فصاحوا حتى علت أصواتهم وهرفوا بي\nوقالوا لأنت أحسن بأداء غنائنا عنا منا قال قلت فأمسكوا علي ولا تضحكوا بي حتى تسمعوا من غنائي فأمسكوا علي فغنيت صوتا من غنائي فصاحوا بي ثم غنيتهم آخر وآخر فوثبوا إلي وقالوا نحلف بالله إن لك لصيتا واسما وذكرا وإن لك فيما هاهنا لسهما عظيما فمن أنت قلت أنا معبد فقبلوا رأسي وقالوا لفقت علينا وكنا نتهاون بك ولا نعدك شيئا وأنت أنت فأقمت عندهم شهرا آخذ منهم ويأخذون مني ثم انصرفت إلى المدينة","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":18,"spl":"معبد والرجل الشامي — معبد مع المغنين في مكة"},
{"id":"b1-36","bab":"الجزء 1","sec":"نسبة هذا الصوت","page":"ج1 ص66","text":"صوت\n(قل لهند وتربها ... قبل شحط النوى غدا)\n(إن تجودي فطالما ... بت ليلي مسهدا)\n(أنت في ود بيننا ... خير ما عندنا يدا)\n(حين تدلي مضفرا ... حالك اللون أسودا)\nلشعر لعمر بن أبي ربيعة والغناء لابن سريج عن حماد ولم يجنسه وفيه لمالك خفيف ثقيل أول بالبنصر في مجراها عن إسحاق وقال الهشامي فيه لابن محرز خفيف ثقيل بالوسطى","topic":"خبر أبي قطيفة ونسبه","topicNo":1,"sp":19,"spl":"نسبة هذا الصوت"},
{"id":"b2-1","bab":"الجزء 1","sec":"ومن الثلاثة الأصوات المختارة صوت فيه أربعة ألحان من رواية علي بن يحيى","page":"ج1 ص67","text":"(تشكى الكميت الجري لما جهدته ... وبين لو يسطيع أن يتكلما)\n(لذلك أدني دون خيلي مكانه ... وأوصي به ألا يهان ويكرما)\n(فقلت له إن ألق للعين قرة ... فهان علي أن تكل وتسأما)\n(عدمت إذا وفري وفارقت مهجتي ... لئن لم أقل قرنا إن الله سلما)\nروضه من الطويل قوله لئن لم أقل قرنا يعني أنه يجد في سيره حتى يقيل بهذا الموضع وهو قرن المنازل وكثيرا ما يذكره في شعره الشعر لعمر بن أبي ربيعة المخزومي والغناء في هذا اللحن المختار لابن سريج ثاني ثقيل مطلق في مجرى الوسطى وفيه لإسحاق أيضا ثاني ثقيل بالبنصر عن عمرو بن بانة وفيه ثقيل أول يقال إنه ليحيى المكي وفيه خفيف رمل يقال إنه لأحمد بن موسى المنجم وفيه للمعتضد ثاني ثقيل آخر في نهاية الجودة وقد كان عمرو بن بانة صنع فيه لحنا فسقط لسقوط صنعته أخبرني جحظة قال حدثني أبو عبد الله الهشامي قال صنع عمرو بن بانة لحنا في تشكى الكميت الجري فأخبرني بعض عجائزنا بذلك قالت فأردنا أن نعرضه على متيم لنعلم ما عندها فيه فقلنا لبعض من أخذه عن عمرو غن تشكى الكميت الجري في اللحن الجديد فقالت متيم أيش هذا اللحن الجديد والكميت المحدث قلنا لحن صنعه عمرو بن بانة فغنته الجارية فقالت متيم لها اقطعي اقطعي حسبك حسبك\nهذا والله لحمار حنين المكسور أشبه منه بالكميت","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":0,"spl":"ومن الثلاثة الأصوات المختارة صوت فيه أربعة ألحان من رواية علي بن يحيى"},
{"id":"b2-2","bab":"الجزء 1","sec":"ذكر خبر عمر بن أبي ربيعة ونسبه","page":"ج1 ص70","text":"هو عمر بن عبد الله بن أبي ربيعة واسم أبي ربيعة حذيفة بن المغيرة بن عبد الله بن عمر بن مخزوم بن يقظة بن مرة بن كعب بن لؤي بن غالب بن فهر وقد تقدم باقي النسب في نسب أبي قطيفة ويكنى عمر بن أبي ربيعة أبا الخطاب وكان أبو ربيعة جده يسمى ذا الرمحين سمي بذلك لطوله كان يقال كأنه يمشي علي رمحين أخبرني بذلك الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عمي ومحمد بن الضحاك عن أبيه الضحاك عن عثمان بن عبد الرحمن اليربوعي وقيل إنه قاتل يوم عكاظ برمحين فسمي ذا الرمحين لذلك وأخبرني بذلك أيضا علي بن صالح بن الهيثم قال حدثني أبو هفان عن إسحاق بن إبراهيم الموصلي عن مصعب الزبيري والمدائني والمسيبي ومحمد بن سلام قالوا وفيه يقول عبد الله بن الزبعرى\n(ألا لله قوم ولدت ... أخت بني سهم)\n(هشام وأبو عبد ... مناف مدره الخصم)\n(وذو الرمحين أشباك ... على القوة والحزم)\n(فهذان يذودان ... وذا من كثب يرمي)\n(أسود تزدهي الأقران ... مناعون للهضم)\n(وهم يوم عكاظ منعوا ... الناس من الهزم)\n(وهم من ولدوا أشبوا ... بسر الجسب الضخم)\n(فإن أحلف وبيت الله ... لا أحلف على إثم)\n(لما من إخوة بين ... قصور الشأم والردم)\n(بأزكى من بني ريطة ... أو أوزن في الحلم)\nبو عبد مناف الفاكه بن المغيرة وريطة هذه التي عناها هي أم بني المغيرة وهي بنت سعيد بن سعد بن سهم ولدت من المغيرة هشاما وهاشما وأبا ربيعة والفاكه وأخبرني أحمد بن سليمان بن داود الطوسي والحرمي بن أبي العلاء قالا\nحدثنا الزبير بن بكار قال حدثنا محمد بن يحيى عن عبد العزيز بن أبي ثابت قال أخبرني محمد بن عبد العزيز عن ابن أبي نهشل عن أبيه قال قال لي أبو بكر بن عبد الرحمن بن الحارث بن هشام وجئته أطلب منه مغرما يا خال هذه أربعة آلاف درهم وأنشد هذه الأبيات الأربعة وقل سمعت حسان ينشدها رسول الله فقلت أعوذ بالله أن أفتري على الله ورسوله ولكن إن شئت أن أقول سمعت عائشة تنشدها فعلت فقال لا إلا أن تقول سمعت حسان ينشدها رسول الله ورسول الله جالس فأبى علي وأبيت عليه فأقمنا لذلك لا نتكلم عدة ليال فأرسل إلي فقال قل أبياتا تمدح بها هشاما يعني ابن المغيرة وبني أمية فقلت سمهم لي فسماهم وقال اجعلها في عكاظ واجعلها لأبيك فقلت\n(ألا لله قوم ولدت ... أخت بني سهم)\nلأبيات قال ثم جئت فقلت هذه قالها أبي فقال لا ولكن قل قالها ابن الزبعرى قال فهي إلى الآن منسوبة في كتب الناس إلى ابن الزبعرى قال الزبير وأخبرني محمد بن الحسن المخزومي قال أخبرني محمد بن طلحة أن عمر بن أبي ربيعة قائل هذه الأبيات\n(ألا لله قوم ولدت ... أخت بني سهم)\nخبرني أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالا\nحدثنا عمر بن شبة قال حدثني محمد بن يحيى قال حدثني عبد العزيز بن عمران قال حدثني محمد بن عبد العزيز عن ابن أبي نهشل عن أبيه بمثل ما رواه الزبير عنه وزاد فيه عمر بن شبة قال محمد بن يحيى وأخت بني سهم التي عناها ريطة بنت سعيد بن سهم بن عمرو بن هصيص بن كعب بن لؤي بن غالب وهي أم بني المغيرة بن عبد الله بن عمر بن مخزوم وهم هشام وهاشم وأبو ربيعة والفاكه وعدة غيرهم لم يعقبوا وإياهم يعني أبو ذؤيب بقوله","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":1,"spl":"ذكر خبر عمر بن أبي ربيعة ونسبه"},
{"id":"b2-3","bab":"الجزء 1","sec":"عبد الله بن أبي ربيعة يكسو الكعبة من ماله","page":"ج1 ص73","text":"(صخب الشوارب لا يزال كأنه ... عبد لآل أبي ربيعة مسبع)\nرب بعزهم المثل قال وكان اسم عبد الله بن أبي ربيعة في الجاهلية بحيرا فسماه رسول الله عبد الله وكانت قريش تلقبه العدل لأن قريشا كانت تكسو الكعبة في الجاهلية بأجمعها من أموالها سنة ويكوسوها هو من ماله سنة فأرادوا بذلك أنه وحده عدل لهم جميعا في ذلك وفيه يقول ابن الزبعرى\n(بحير بن ذي الرمحين قرب مجلسي ... وراح علي خيره غير عاتم)\nقد قيل إن العدل هو الوليد بن المغيرة وكان عبد الله بن أبي ربيعة تاجرا موسرا وكان متجره إلى اليمن وكان من\nأكثرهم مالا وأمه أسماء بنت مخربة وقيل مخرمة وكانت عطارة يأتيها العطر من اليمن وقد تزوجها هشام بن المغيرة أيضا فولدت له أبا جهل والحارث ابني هشام فهي أمهما وأم عبد الله وعياش ابني أبي ربيعة أخبرني الحرمي والطوسي قالا حدثنا الزبير قال حدثني عمي عن الواقدي قال كانت أسماء بنت مخربة تبيع العطر بالمدينة فقالت الربيع بنت معوذ بن عفراء الأنصارية وكان أبوها قتل أبا جهل بن هشام يوم بدر واحتز رأسه عبد الله ابن مسعود وقيل بل عبد الله بن مسعود هو الذي قتله فذكرت أن أسماء بنت مخربة دخلت عليها وهي تبيع عطرا لها في نسوة قالت فسألت عنا فانتسبنا لها فقالت أأنت ابنة قاتل سيده تعني أبا جهل قلت بل أنا بنت قاتل عبده قالت حرام علي أن أبيعك من عطري شيئا قلت وحرام علي أن أشتري منه شيئا فما وجدت لعطر نتنا غير عطرك ثم قمت لا والله ما رأيت عطرا أطيب من عطرها ولكني أردت أن أعيبه لأغيظها","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":2,"spl":"عبد الله بن أبي ربيعة يكسو الكعبة من ماله — نسبة ما في هذه الأخبار من الغناء"},
{"id":"b2-4","bab":"الجزء 1","sec":"رأي النبي في حبش بني المغيرة","page":"ج1 ص74","text":"وكان لعبد الله بن أبي ربيعة عبيد من الحبشة يتصرفون في جميع المهن وكان عددهم كثيرا فروي عن سفيان بن عيينة أنه قيل لرسول الله حين خرج إلى حنين هل لك في حبش بني المغيرة تستعين بهم فقال لا خير في الحبش إن جاعوا سرقوا وإن شبعوا زنوا وإن فيهم لخلتين حسنتين إطعام\nالطعام والبأس يوم البأس واستعمل رسول الله عبد الله بن أبي ربيعة على الجند ومخاليفها فلم يزل عاملا عليها حتى قتل عمر بن الخطاب رضي الله عنه هذا من رواية الزبير عن عمه قال وحدثني ابن الماجشون عن عمه أن عثمان بن عفان رحمه الله استعمله أيضا عليها وأم عمر بن أبي ربيعة أم ولد يقال لها مجد سبيت من حضرموت ويقال من حمير قال أبو محلم ومحمد بن سلام هي من حمير ومن هناك أتاه الغزل يقال غزل يمان ودل حجازي وقال عمر بن شبة أم عمر بن أبي ربيعة أم ولد سوداء من حبش يقال لهم فرسان وهذا غلط من أبي زيد تلك أم أخيه الحارث بن عبد الله الذي يقال له القباع وكانت نصرانية وكان الحارث بن عبد الله شريفا كريما دينا وسيدا من سادات قريش قال الزبير بن بكار ذكره عبد الملك بن مروان يوما وقد ولاه عبد الله بن الزبير فقال أرسل عوفا وقعد لا حر بوادي عوف فقال له يحيى بن الحكم ومن الحارث بن السوداء فقال له عبد الملك ما ولدت والله أمة خيرا\nمما ولدت أمه وأخبرني علي بن صالح عن أبي هفان عن إسحاق بن إبراهيم عن الزبير والمدائني والمسيبي أن أمه ماتت نصرانية وكانت تسر ذلك منه فحضر الأشراف جنازتها وذلك في عهد عمر بن الخطاب رحمة الله عليه فسمع الحارث من النساء لغطا فسأل عن الخبر فعرف أنها ماتت نصرانية وأنه وجد الصليب في عنقها وكانت تكتمه ذلك فخرج إلى الناس فقال انصرفوا رحمكم الله فإن لها أهل دين هم أولى بها منا ومنكم فاستحسن ذلك منه وعجب الناس من فعله","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":2,"spl":"عبد الله بن أبي ربيعة يكسو الكعبة من ماله — نسبة ما في هذه الأخبار من الغناء"},
{"id":"b2-5","bab":"الجزء 1","sec":"نسبة ما في هذه الأخبار من الغناء","page":"ج1 ص76","text":"صوت\n(ألا لله قوم ولدت ... أخت بني سهم)\n(هشام وأبو عبد ... مناف مدره الخصم)\n(وذو الرمحين أشباك ... على القوة والحزم)\n(فهذان يذودان ... وذا من كثب يرمي)\nروضه من مكفوف الهزج الغناء لمعبد خفيف رمل من رواية حماد أخبرني محمد بن خلف وكيع قال قال إسماعيل بن مجمع أخبرنا المدائني عن رستم بن صالح قال","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":2,"spl":"عبد الله بن أبي ربيعة يكسو الكعبة من ماله — نسبة ما في هذه الأخبار من الغناء"},
{"id":"b2-6","bab":"الجزء 1","sec":"رأي يزيد بن عبد الملك في غناء معبد وابن سريج","page":"ج1 ص76","text":"قال يزيد بن عبد الملك يوما لمعبد يا أبا عباد إني أريد أن أخبرك عن نفسي وعنك فإن قلت فيه خلاف ما تعلم فلا تتحاش أن ترده علي فقد أذنت لك قال يا أمير المؤمنين لقد وضعك ربك بموضع لا يعصيك إلا ضال ولا يرد عليك إلا مخطئ قال إن الذي أجده في غنائك لا أجده في غناء ابن سريج أجد في غنائك متانة وفي غنائه انخناثا ولينا قال معبد والذي أكرم أمير المؤمنين بخلافته وارتضاه لعباده وجعله أمينا على أمة نبيه ما عدا صفتي وصفة ابن سريج وكذا يقول ابن سريج وأقول ولكن إن رأى أمير المؤمنين أن يعلمني هل وضعني ذاك عنده فعل قال لا والله ولكني أوثر الطرب على كل شيء قال يا سيدي فإذا كان ابن سريج يذهب إلى الخفيف من الغناء وأذهب أنا إلى الكامل التام فأغرب أنا ويشرق هو فمتى نلتقي قال أفتقدر أن تحكي رقيق ابن سريج قال نعم فصنع من وقته لحنا من الخفيف في\n(ألا لله قوم ولدت ... أخت بني سهم)\nلأربعة الأبيات فغناه فصاح يزيد أحسنت والله يا مولاي أعد فداك أبي وأمي فأعاد فرد عليه مثل قوله الأول فأعاد ثم قال أعد فداك أبي وأمي فأعاد فاستخفه الطرب حتى وثب وقال لجواريه افعلن كما أفعل وجعل يدور في الدار ويدرن معه وهو يقول\n(يا دار دوريني ... يا قرقر امسكيني)\n(آليت منذ حين ... حقا لتصرميني)\n(ولا تواصليني ... بالله فارحميني)\n(لم تذكري يميني ... )\nال فلم يزل يدور كما يدور الصبيان ويدرن معه حتى خر مغشيا عليه ووقعن فوقه ما يعقل ولا يعقلن فابتدره الخدم فأقاموه وأقاموا من كان على ظهره من جواريه وحملوه وقد جادت نفسه أو كادت","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":3,"spl":"رأي يزيد بن عبد الملك في غناء معبد وابن سريج — ولدا عمر جوان وأمة الواحد","partial":1},
{"id":"b2-7","bab":"الجزء 1","sec":"ولدا عمر جوان وأمة الواحد","page":"ج1 ص77","text":"رجع الخبر إلى ذكر عمر بن أبي ربيعة وكان لعمر بن أبي ربيعة ابن صالح يقال له جوان وفيه يقول العرجي\n(شهيدي جوان على حبها ... أليس بعدل عليها جوان)\nأخبرني الحرمي قال حدثنا الزبير بن بكار قال حدثنا يحيى بن محمد بن عبد الله بن ثوبان قال جاء جوان بن عمر بن أبي ربيعة إلى زياد بن عبد الله الحارثي وهو إذ ذاك أمير على الحجاز فشهد عنده بشهادة فتمثل\n(شهيدي جوان على حبها ... أليس بعدل عليها جوان)\nهذا الشعر للعرجي ثم قال قد أجزنا شهادتك وقبله وقال غير الزبير إنه جاء إلى العرجي فقال له يا هذا ما لي ومالك تشهرني في شعرك متى أشهدتني على صاحبتك هذه ومتى كنت أنا أشهد في مثل هذا قال وكان أمرأ صالحا\nوأخبرني الحرمي قال حدثنا الزبير قال حدثني بكار بن عبد الله قال استعمل بعض ولاة مكة جوان بن عمر على تبالة فحمل على خثعم في صدقات أموالهم حملا شديدا فجعلت خثعم سنة جوان تاريخا فقال ضبارة بن الطفيل\n(أتلبسنا ليلى على شعث بنا ... من العام أو يرمى بنا الرجوان)\nصوت\n(رأتني كأشلاء اللجام وراقها ... أخو غزل ذو لمة ودهان)\n(ولو شهدتني في ليال مضين لي ... لعامين مرا قبل عام جوان)\n(رأتنا كريمي معشر حم بيننا ... هوى فحفظناه بحسن صيان)\n(نذود النفوس الحائمات عن الصبا ... وهن بأعناق إليه ثواني)\nكر حبش أن الغناء في هذه الأبيات للغريض ثاني ثقيل بالبنصر وذكر الهشامي أنه لقراريط قالوا وكان لعمر أيضا بنت يقال لها أمة الواحد وكانت مسترضعة في هذيل وفيها يقول عمر بن أبي ربيعة وقد خرج يطلبها فضل الطريق\n(لم تدر وليغفر لها ربها ... ما جشمتنا أمة الواحد)\n(جشمت الهول براذيننا ... نسأل عن بيت أبي خالد)\n(نسأل عن شيخ بني كاهل ... أعيا خفاء نشدة الناشد)\nخبرني بذلك محمد بن خلف بن المرزبان عن أبي بكر العامري أخبرنا أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة قال حدثني يعقوب بن القاسم قال حدثني أسامة بن زيد بن الحكم بن عوانة عن عوانة بن الحكم قال أراه عن الحسن قال ولد عمر بن أبي ربيعة ليلة قتل عمر بن الخطاب رحمة الله عليه فأي حق رفع وأي باطل وضع قال عوانة ومات وقد قارب السبعين أو جاوزها أخبرني الجوهري والمهلبي قالا حدثنا عمر بن شبة قال حدثني يعقوب بن القاسم قال حدثنا عبد الله بن الحارث عن ابن جريج عن عطاء قال كان عمر بن أبي ربيعة أكبر مني كأنه ولد في أول الإسلام","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":3,"spl":"رأي يزيد بن عبد الملك في غناء معبد وابن سريج — ولدا عمر جوان وأمة الواحد"},
{"id":"b2-8","bab":"الجزء 1","sec":"عمر ينشد ابن العباس أمن آل نعم في المسجد الحرام","page":"ج1 ص81","text":"أخبرني الجوهري والمهلبي قالا حدثنا عمر بن شبة قال حدثني هارون بن عبد الله الزهري قال حدثنا ابن أبي ثابت وحدثني به علي بن صالح بن الهيثم عن أبي هفان عن إسحاق عن المسيبي والزبيري والمدائني ومحمد بن سلام قالوا قال أيوب بن سيار وأخبرني به الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني محمد بن الحسن المخزومي عن عبد العزيز بن عمران عن أيوب بن سيار عن عمر الركاء قال بينا ابن عباس في المسجد الحرام وعنده نافع بن الأزرق وناس من الخوارج يسألونه إذ أقبل عمر بن أبي ربيعة في ثوبين مصبوغين موردين أو ممصرين حتى دخل وجلس فأقبل عليه ابن عباس فقال أنشدنا فأنشده\n(أمن آل نعم أنت غاد فمبكر ... غداة غد أم رائح فمهجر)\nتى أتى على آخرها فأقبل عليه نافع بن الأزرق فقال الله يا ابن عباس إنا نضرب إليك أكباد الإبل من أقاصي البلاد نسألك عن الحلال والحرام فتتثاقل عنا ويأتيك غرلام مترف من مترفي قريش فينشدك\n(رأت رجلا أما إذا الشمس عارضت ... فيخزى وأما بالعشي فيخسر)\nقال ليس هكذا قال قال فكيف قال فقال قال\n(رأت رجلا أما إذا الشمس عارضت ... فيضحى وأما بالعشي فيخصر)\nقال ما أراك إلا وقد حفظت البيت قال أجل وإن شئت أن أنشدك القصيدة أنشدتك إياها قال فإني أشاء فأنشده القصيدة حتى أتى على آخرها وفي غير رواية عمر بن شبة أن ابن عباس أنشدها من أولها إلى آخرها ثم أنشدها من آخرها إلى أولها مقلوبة وما سمعها قط إلا تلك المرة صفحا قال وهذا غاية الذكاء فقال له بعضهم ما رأيت أذكى منك قط فقال لكني ما رأيت قط أذكى من علي بن أبي طالب عليه السلام وكان ابن عباس يقول ما سمعت شيئا قط إلا رويته وإني لأسمع صوت النائحة فأسد أذني كراهة أن أحفظ ما تقول قال ولامه بعض أصحابه في حفظ هذه القصيدة أمن آل نعم فقال إنا نستجيدها وقال الزبير في خبره عن عمه فكان ابن عباس بعد ذلك كثيرا ما يقول هل أحدث هذا المغيري شيئا بعدنا قال وحدثني عبد الله بن نافع بن ثابت قال كان عبد الله بن الزبير إذا سمع قول عمر بن أبي ربيعة\n(فيضحى وأما بالعشي فيخصر ... )\nقال لا بل\n(فيخزى وأما بالعشي فيخسر ... )\nال عمر بن شبة وأبو هفان والزبير في حديثهم ثم أقبل على ابن أبي ربيعة فقال\nأنشد فأنشده\n(تشط غدا دار جيراننا ... )\nسكت فقال ابن عباس\n(وللدار بعد غد أبعد ... )\nفقال له عمر كذلك قلت أصلحك الله أفسمعته قال لا ولكن كذلك ينبغي","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":4,"spl":"عمر ينشد ابن العباس أمن آل نعم في المسجد الحرام","partial":1},
{"id":"b2-9","bab":"الجزء 1","sec":"اختلاف الآراء في شعر عمر","page":"ج1 ص83","text":"أخبرنا الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني يعقوب ابن إسحاق قال العرب تقر لقريش بالتقدم في كل شيء عليها إلا في الشعر فإنها كانت لا تقر لها به حتى كان عمر بن أبي ربيعة فأقرت لهما الشعراء بالشعر أيضا ولم تنازعها شيئا قال الزبير وسمعت عمي مصعبا يحدث عن جدي أنه قال مثل هذا القول قال وحدثني عدة من أهل العلم أن النصيب قال لعمر بن أبي ربيعة أوصفنا لربات الحجال قال المدائني قال سليمان بن عبد الملك لعمر بن أبي ربيعة ما\nيمنعك من مدحنا قال إني لا أمدح الرجال إنما أمدح النساء قال وكان ابن جريج يقول ما دخل على العواتق في حجالهن شيء أضر عليهن من شعر عمر بن أبي ربيعة قال الزبير وحدثني عمي عن جدي وذكره أيضا إسحاق فيما رويناه عن أبي هفان عنه عن المدائني قال قال هشام بن عروة لا ترووا فتياتكم شعر عمر بن أبي ربيعة لا يتورطن في الزنا تورطا وأنشد\n(لقد أرسلت جاريتي ... وقلت لها خذي حذرك)\n(وقولي في ملاطفة ... لزينب نولي عمرك)\nخبرنا علي بن صالح قال حدثني أبو هفان عن إسحاق عن الزبيري قال حدثني أبي عن سمرة الدوماني من حمير قال إني لأطوف في بالبيت فإذا أنا بشيخ في الطواف فقيل لي هذا عمر بن أبي ربيعة فقبضت على يده وقلت له يابن أبي ربيعة قال ما تشاء قلت أكل ما قلته من شعرك فعلته قال إليك عني قلت أسألك بالله قال نعم وأستغفر الله قال إسحاق وحدثني الهيثم بن عدي عن حماد الرواية أنه سئل عن شعر عمر بن أبي ربيعة فقال ذاك الفستق المقشر\nأخبرني الحرمي قال حدثنا الزبير عن عمه قال سمع الفرزدق شيئا من نسيب عمر فقال هذا الذي كانت الشعراء تطلبه فأخطأته وبكت الديار ووقع هذا عليه قال وكان بالكوفة رجل من الفقهاء تجتمع إليه الناس فيتذاكرون العلم فذكر يوما شعر عمر بن أبي ربيعة فهجنه فقالوا له بمن ترضى ومر بهم حماد الراوية فقال قد رضيت بهذا فقالوا له ما تقول فيمن يزعم أن عمر بن أبي ربيعة لم يحسن شيئا فقال أين هذا اذهبوا بنا إليه قالوا نصنع به ماذا قال ننزو على أمه لعلها تأتي بمن هو أمثل من عمر قال إسحاق وقال أبو المقوم الأنصاري ما عصي الله بشيء كما عصي بشعر عمر بن أبي ربيعة قال إسحاق وحدثني قيس بن داود قال حدثني أبي قال سمعت عمر بن أبي ربيعة يقول لقد كنت وأنا شاب أعشق ولا أعشق فاليوم صرت إلى مداراة الحسان إلى الممات ولقد لقيتني فتاتان مرة فقالت لي إحداهما ادن مني يابن أبي ربيعة أسر إليك شيئا فدنوت منها ودنت الأخرى فجعلت تعضني فما شعرت بعض هذه من لذة سرار هذه قال إسحاق وذكر عبد الصمد بن المفضل الرقاشي عن محمد بن فلان الزهري سقط اسمه عن إسحاق عن عبد الله بن مسلمة بن أسلم قال لقيت جريرا فقلت له يا أبا حزرة إن شعرك رفع إلى المدينة وأنا أحب أن تسمعني منه شيئا فقال إنكم يا أهل المدينة يعجبكم النسيب وإن أنسب الناس المخزومي يعني ابن أبي ربيعة\nقال إسحاق وذكر محمد بن إسماعيل الجعفري عن أبيه عن خاله عبد العزيز بن عبد الله بن عياش بن أبي ربيعة قال أشرف عمر بن أبي ربيعة على أبي قبيس وبنو أخيه معه وهم محرمون فقال لبعضهم خذ بيدي فأخذ بيده وقال ورب هذه البنية ما قلت لامرأة قط شيئا لم تقله لي وما كشفت ثوبا عن حرام قط قال ولما مرض عمر مرضه الذي مات فيه جزع أخوه الحارث جزعا شديدا فقال له عمر أحسبك إنما تجزع لما تظنه بي والله ما أعلم أني ركبت فاحشة قط فقال ما كنت أشفق عليك إلا من ذلك وقد سليت عني قال إسحاق حدثني مصعب الزبيري قال قال مصعب بن عروة بن الزبير خرجت أنا وأخي عثمان إلى مكة معتمرين أو حاجين فلما طفنا في بالبيت مضينا إلى الحجر نصلي فيه فإذا شيخ قد فرج بيني وبين أخي فأوسعنا له فلما قضى صلاته أقبل علينا فقال من أنتما فأخبرناه فرحب بنا وقال يا ابني أخي إني موكل بالجمال أتبعه وإني رأيتكما فراقني حسنكما وجمالكما فاستمتعا بشبابكما قبل أن تندما عليه ثم قام فسألنا عنه فإذا هو عمر بن أبي ربيعة أخبرنا الحرمي قال حدثنا الزبير قال حدثني محمد بن الضحاك قال عاش عمر بن أبي ربيعة ثمانين سنة فتك منها أربعين سنة ونسك أربعين سنة قال الزبير وحدثني إبراهيم بن حمزة ومحمد بن ثابت عن المغيرة بن عبد الرحمن عن أبيه قال","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":5,"spl":"اختلاف الآراء في شعر عمر"},
{"id":"b2-10","bab":"الجزء 1","sec":"اختلاف الآراء في شعر عمر","page":"ج1 ص83","text":"حججت مع أبي وأنا غلام وعلي جمة فلما قدمت مكة جئت عمر بن أبي ربيعة فسلمت عليه وجلست معه فجعل يمد الخصلة من شعري ثم يرسلها فترجع على ما كانت عليه ويقول واشباباه حتى فعل ذلك مرارا ثم قال لي يابن أخي قد سمعتني أقول في شعري قالت لي وقلت لها وكل مملوك لي حر إن كنت كشفت عن فرج حرام قط فقمت وأنا متشكك في يمينه فسألت عن رقيقه فقيل لي أما في الحوك فله سبعون عبدا سوى غيرهم أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثتني ظبية مولاة فاطمة بنت عمر بن مصعب قالت مررت بجدك عبد الله بن مصعب وأنا داخلة منزله وهو بفنائه ومعي دفتر فقال ما هذا معك ودعاني فجئته وقلت شعر عمر بن أبي ربيعة فقال ويحك تدخلين على النساء بشعر عمر بن أبي ربيعة إن لشعره لموقعا من القلوب ومدخلا لطيفا لو كان شعر يسحر لكان هو فارجعي به قالت ففعلت قال إسحاق وأخبرني الهيثم بن عدي قال قدمت امرأة مكة وكانت من أجمل النساء فبينا عمر بن أبي ربيعة يطوف إذ نظر إليها فوقعت في قلبه فدنا منها فكلمها فلم تلتفت إليه فلما كان في الليلة الثانية جعل يطلبها حتى أصابها فقالت له إليك عني يا هذا فإنك في حرم الله وفي أيام عظيمة الحرمة فألح عليها يكلمها حتى خافت أن يشهرها فلما كان في الليلة الأخرى قالت لأخيها اخرج معي يا أخي فأرني المناسك فإني لست أعرفها فأقبلت وهو معها فلما رآها عمر أراد أن يعرض لها فنظر إلى أخيها معها فعدل عنها فتمثلت المرأة بقول النابعة\n(تعدو الذئاب على من لا كلاب له ... وتتقي صولة المستأسد الحامي)\nال إسحاق فحدثني السندي مولى أمير المؤمنين أن المنصور قال وقد حدث بهذا الخبر وددت أنه لم تبق فتاة من قريش في خدرها إلا سمعت بهذا الحديث قال إسحاق قال لي الأصمعي عمر حجة في العربية ولم يؤخذ عليه إلا قوله\n(ثم قالوا تحبها قلت بهرا ... عدد الرمل والحصى والتراب)\nله في ذلك مخرج إذ قد أتى به على سبيل الاخبار قال ومن الناس من يزعم أنه إنما قال\n(قيل لي هل تحبها قلت بهرا ... )\nنسبة ما مضى من في هذه الأخبار من الأشعار التي قالها عمر بن أبي ربيعة وغنى فيها المغنون إذ كانت لم تنسب هناك لطول شرحها منها ما يغنى فيه من قوله\nصوت\n(أمن آل نعم أنت غاد فمبكر ... غداة غد أم رائح فمهجر)\n(لحاجة نفس لم تقل في جوابها ... فتبلغ عذرا والمقالة تعذر)\n(أشارت بمدراها وقالت لأختها ... أهذا المغيري الذي كان يذكر)\n(فقالت نعم لا شك غير لونه ... سرى الليل يطوي نصه والتهجر)\n(رأت رجلا أما إذا الشمس عارضت ... فيضحى وأما بالعشي فيخصر)\n(أخا سفر جواب أرض تقاذفت ... به فلوات فهو أشعث أغبر)\n(وليلة ذي دوران جشمتني السرى ... وقد يجشم الهول المحب المغرر)\n(فقلت أباديهم فإما أفوتهم ... وإما ينال السيف ثأرا فيثأر)\nذه الأبيات جمعت على غير توال لأنه إنما ذكر منها ما فيه صنعة غنى في الأول والثاني من الأبيات ابن سريج خفيف رمل بالبنصر عن أحمد بن المكي\nوذكر حبش أن فيهما لمعبد لحنا من الثقيل الأول بالبنصر وغنى ابن سريج في الثالث والرابع أيضا خفيف ثقيل بالوسطى وذكر حبش أن فيهما لحنا من الهزج بالوسطى لحكم وغنى ابن سريج في الخامس والسادس لحنا من الرمل بالوسطى عن عمرو بن بانة وذكر يونس أن في السابع والثامن لابن سريج لحنا ولم يذكر طريقته وذكر حبش أن فيهما لمالك لحنا من الثقيل الثاني بالبنصر أخبرني محمد بن خلف بن المرزبان قال أخبرني محمد بن إسحاق قال أخبرني محمد بن حبيب عن هشام بن الكلبي أن عمر بن أبي ربيعة أتى عبد الله بن عباس وهو في المسجد الحرام فقال متعني الله بك إن نفسي قد تاقت إلى قول الشعر ونازعتني إليه وقد قلت منه شيئا أحببت أن تسمعه وتستره علي فقال أنشدني فأنشده\n(أمن آل نعم أنت غاد فمبكر ... )\nقال له أنت شاعر يابن أخي فقل ما شئت قال وأنشد عمر هذه القصيدة طلحة بن عبد الله بن عوف الزهري وهو راكب فوقف وما زال شانقا ناقته حتى كتبت له\nأخبرني محمد بن خلف بن المرزبان قال حدثني الحسين بن إسماعيل قال حدثنا ابن عائشة عن أبيه قال كان جرير إذا أنشد شعر عمر بن أبي ربيعة قال هذا شعر تهامي إذا أنجد وجد البرد حتى أنشد قوله\n(رأت رجلا أما إذا الشمس عارضت ... فيضحى وأما بالعشي فيخصر)\n(قليلا على ظهر المطية ظله ... سوى ما نفى عنه الرداء المحبر)","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":6,"spl":"اختلاف الآراء في شعر عمر","partialRef":{"sid":"b2-8","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b2-11","bab":"الجزء 1","sec":"اختلاف الآراء في شعر عمر","page":"ج1 ص83","text":"(وأعجبها من عيشها ظل غرفة ... وريان ملتف الحدائق أخضر)\n(ووال كفاها كل شيء يهمها ... فليست لشيء آخر الليل تسهر)\nقال جرير ما زال هذا القرشي يهذي حتى قال الشعر أخبرني محمد بن خلف قال أخبرني أبو عبد الله اليمامي قال حدثني الأصمعي قال قال لي الرشيد أنشدني أحسن ما قيل في رجل قد لوحه السفر فأنشدته قول عمر بن أبي ربيعة\n(رأت رجلا أما إذا الشمس عارضت ... فيضحى وأما بالعشي فيخصر)\n(أخا سفر جواب أرض تقاذفت ... به فلوات فهو أشعث أغبر)\nلأبيات كلها قال فقال لي الرشيد أنا والله ذلك الرجل قال وهذا بعقب قدومه من بلاد الروم أخبرني الفضل بن الحباب الجمحي أبو خليفة في كتابه إلي قال حدثنا محمد ابن سلام قال أخبرني شعيب بن صخر قال\nكان بين عائشة بنت طلحة وبين زوجها عمر بن عبيد الله بن معمر كلام فسهرت ليلة فقالت إن ابن أبي ربيعة لجاهل بليلتي هذه حيث يقول\n(ووال كفاها كل شيء يهمها ... فليست لشيء آخر الليل تسهر)\nخبرني علي بن صالح قال حدثنا أبو هفان قال حدثني إسحاق عن المدائني قال عرض يزيد بن معاوية جيش أهل الحرة فمر به رجل من أهل الشام معه ترس خلق سمج فنظر إليه يزيد وضحك وقال له ويحك ترس عمر بن أبي ربيعة كان أحسن من ترسك يريد قول عمر\n(فكان مجني دون من كنت أتقي ... ثلاث شخوص كاعبان ومعصر)\nخبرنا جعفر بن قدامة قال حدثني محمد بن عبد الله بن مالك الخزاعي قال سمع أبو الحارث جميز مغنية تغني\n(أشارت بمدراها وقالت لأختها ... أهذا المغيري الذي كان يذكر)\nقال جميز امرأته طالق إن كانت أشارت إليها بمدراها إلا لتفقأ بها عينه هلا أشارت إليه بنقانق مطرف بالخردل أو سنبوسجة مغموسة في الخل أو\nلوزينجة شرقة بالدهن فإن ذلك أنفع له وأطيب لنفسه وأدل على مودة صاحبته أخبرني الحرمي قال حدثنا الزبير قال حدثني عبد العزيز بن أبي أويس عن عطاف بن خالد الوابصي عن عبد الرحمن بن حرملة قال أنشد سعيد بن المسيب قول عمر بن أبي ربيعة\n(وغاب قمير كنت أرجو غيوبه ... وروح رعيان ونوم سمر)\nقال ما له قاتله الله لقد صغر ما عظم الله يقول الله عز و جل ( والقمر قدرناه منازل حتى عاد كالعرجون القديم","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":7,"spl":"اختلاف الآراء في شعر عمر"},
{"id":"b2-12","bab":"الجزء 1","sec":"شعر عمر في فاطمة الكندية","page":"ج1 ص93","text":"ومنها ما فيه غناء لم ينسب في موضعه من الأخبار فنسب هاهنا صوت\n(تشط غدا دار جيراننا ... وللدار بعد غد أبعد)\n(إذا سلكت غمر ذي كندة ... مع الصبح قصد لها الفرقد)\n(عراقية وتهامي الهوى ... يغور بمكة أو ينجد)\n(وحث الحداة بها عيرها ... سراعا إذا ما ونت تطرد)\n(هنالك إما تعزي الفؤاد ... وإما على إثرها تكمد)\n(وليست ببدع إذا دارها ... نأت والعزاء إذا أجلد)\n(صرمت وواصلت حتى علمت ... أين المصادر والمورد)\n(وجربت من ذاك حتى عرفت ... ما أتوقى وما أحمد)\n(فلما دنونا لجرس النباح ... والضوء والحي لم يرقدوا)\n(نأينا عن الحي حتى إذا ... تودع من نارها الموقد)\n(بعثنا لها باغيا ناشدا ... وفي الحي بغية من ينشد)\n(أتتنا تهادى على رقبة ... من الخوف أحشاؤها ترعد)\n(تقول وتظهر وجدا بنا ... ووجدي وإن أظهرت أوجد)\n(لمما شقائي تعلقتكم ... وقد كان لي عندكم مقعد)\n(وكفت سوابق من عبرة ... على الخد يجري بها الإثمد)\n(فإن التي شيعتنا الغداة ... مع الفجر قلبي بها مقصد)\n(كأن أقاحي مولية ... تحدر من ماء مزن ندي)\nنى معبد في الأول والثاني والثالث من الأبيات خفيف ثقيل من أصوات قليلات الأشباه عن إسحاق وغنى فيها أشعب المعروف بالطامع ثاني ثقيل بالوسطى عن الهشامي وللغريض في الأبيات الأربعة الأول ثاني ثقيل بالوسطى عن عمرو ولابن سريج في الرابع عشر وهو\n(وكفت سوابق من عبرة ... )\nم الأول والتاسع رمل بالوسطى عن ابن المكي ولمالك ويقال إنه لمعبد خفيف ثقيل في الرابع عشر والثالث عشر والأول عن الهشامي وفي السابع والثامن والأول لابن جامع ثقيل أول بالوسطى عن الهشامي وفي الأول والحادي عشر لابن سريج رمل بالبنصر في مجراها عن إسحاق وفيهما ثاني ثقيل بالسبابة في مجرى البنصر عن إسحاق ولم ينسبه إلى أحد وذكر أحمد بن المكي أنه لأبيه وفي الرابع والخامس رمل لمعبد عن ابن المكي وقيل إنه من منحول أبيه إلى معبد وفي الثالث عشر والسادس ليونس خفيف رمل عن الهشامي وفي الأول والثاني عشر ثاني ثقيل تشترك فيه الأصابع عن ابن المكي وقال أيضا فيه للأبجر لحن آخر من الثقيل الثاني ولمعبد في الرابع والسادس ثاني ثقيل آخر عنه وفيهما أيضا رمل لابن سريج عنه وعن حبش ولإسحاق في الأول والثاني رمل من كتابه ولعلية بنت المهدي في الثالث عشر والأول ثقيل أول ولابن\nمسجح في الثاني عشر والأول رمل ويقال إنه للرطاب وذكر حبش أنه لابن سريج وفي الخمسة الأبيات الأولى متوالية خفيف رمل بالوسطى ينسب إلى معبد وإلى يحيى المكي وزعم حبش أن فيها رملا بالوسطى لابن محرز والذي ذكره يونس في كتابه أن في\n(تشط غدا دار جيراننا ... )\nخمسة ألحان اثنان لمعبد واثنان لمالك وواحد ليونس وذكر أحمد بن عبيد أن الذي عرف صحته من الغناء فيه سبعة ألحان ثقيل أول وثاني ثقيل وخفيف ثقيل ورمل وخفيفه أخبرني بعض أصحابنا عن أبي عبد الله بن المرزبان أن الذي أحصي فيه إلى وقته ستة عشر لحنا والذي وجدته فيه مما جمعته هاهنا سوى ما لم يذكر يونس طريقته تسعة عشر لحنا منها في الثقيل الأول لحنان وفي خفيف الثقيل لحنان وفي الثقيل الثاني ستة وفي الرمل سبعة وفي خفيف الرمل لحنان وهذا الشعر يقوله عمر بن أبي ربيعة في امرأة من ولد الأشعث بن قيس حجت فهويها وراسلها فواصلته ودخل إليها وتحدث معها وخطبها فقالت أما\nهاهنا فلا سبيل إلى ذلك ولكن إن قدمت إلى بلدي خاطبا تزوجتك فلم يفعل أخبرني بهذا الخبر الحرمي بن أبي العلاء قال حدثنا الزبير قال حدثنا محمد ابن الحسن المخزومي عن محرز بن جعفر مولى أبي هريرة عن أبيه قال سمعت بديحا يقول حجت بنت محمد بن الأشعث الكندية فراسلها عمر بن أبي ربيعة ووعدها أن يتلقاها مساء الغد وجعل الآية بينه وبينها أن تسمع ناشدا ينشد إن لم يمكنه أن يرسل رسولا يعلمها بمصيره إلى المكان الذي وعدها قال بديح فلم أشعر به إلا متلثما فقال لي يا بديح ائت بنت محمد ابن الأشعث فأخبرها أني قد جئت لموعدها فأبيت أن أذهب وقلت مثلي لا يعين على مثل هذا فغيب بغلته عني ثم جاءني فقال لي قد أضللت بغلتي فانشدها لي في زقاق الحاج فذهبت فنشدتها فخرجت علي بنت محمد بن الأشعث وقد فهمت الآية فأتته لموعده وذلك قوله\n(وآية ذلك أن تسمعي ... إذا جئتكم ناشدا ينشد)","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":8,"spl":"شعر عمر في فاطمة الكندية","partialRef":{"sid":"b2-8","gi":5,"vi":0,"side":0},"partial":1},
{"id":"b2-13","bab":"الجزء 1","sec":"شعر عمر في فاطمة الكندية","page":"ج1 ص93","text":"قال بديح فلما رأيتها مقبلة عرفت أنه قد خدعني بنشدي البغلة فقلت له يا عمر لقد صدقت التي قالت لك\n(فهذا سحرك النسوان ... قد خبرنني خبرك)\nد سحرتني وأنا رجل فكيف برقة قلوب النساء وضعف رأيهن وما آمنك بعدها ولو دخلت الطواف ظننت أنك دخلته لبلية قال وحدثها بحديثي فما زالا\nليلتهما يفصلان حديثهما بالضحك مني قال الزبير فحدثني أبو الهندام مولى الربعيين عن أبي الحارث بن عبد الله الربعي قال لقي ابن أبي عتيق بديحا فقال له يا بديح أخدعك ابن أبي ربيعة أنه قرشي فقال بديح نعم وقد أخطأه ذلك عند القسري وصواحبه فقال ابن أبي عتيق ويحك يا بديح إن من تغابى لك ليغبى عنك فقد ضمت عليه قبضتك إن كان لك ذهن أما رأيت لمن كانت العاقبة والله ما بالى ابن أبي ربيعة أوقع عليهن أم وقعن عليه أخبرني عمي قال حدثنا محمد بن سعد الكراني قال حدثنا العمري عن كعب ابن بكر المحاربي أن فاطمة بنت محمد بن الأشعث حجت فراسلها عمر بن أبي ربيعة فواعدته أن تزوره فأعطى الرسول الذي بشره بزيارتها مائة دينار أخبرني علي بن صالح عن أبي هفان عن إسحاق عن رجاله المذكورين قالوا حجت بنت لمحمد بن الأشعث هكذا قال إسحاق وهو عندي الصحيح وكانت معها أمها وقد سمعت بعمر بن أبي ربيعة فأرسلت إليه فجاءها فاستنشدته فأنشدها\n(تشط غدا دار جيراننا ... وللدار بعد غد أبعد)\nذكر القصة بطولها قال وقد كانت لما جاءها أرسلت بينها وبينه سترا رقيقا تراه\nمن ورائه ولا يراها فجعل يحدثها حتى استنشدته فأنشدها هذه القصيدة فاستخفها الشعر فرفعت السجف فرأى وجها حسنا في جسم ناحل فخطبها وأرسل إلى أمها بخمسمائة دينار فأبت وحجبته وقالت للرسول تعود إلينا فكأن الفتاة غمها ذلك فقالت لها أمها قد قتلك الوجد به فتزوجيه قالت لا والله لا يتحدث أهل العراق عني أني جئت ابن أبي ربيعة أخطبه ولكن إن أتاني إلى العراق تزوجته قال ويقال إنها راسلته وواعدته أن تزوره فأجمر بيته وأعطى المبشر مائة دينار فأتته وواعدته إذا صدر الناس أن يشيعها وجعلت علامة ما بينهما أن يأتيها رسوله ينشدها ناقة له فلما صدر الناس فعل ذلك عمر وفيه يقول وقد شيعها صوت\n(قال الخليط غدا تصدعنا ... أو بعده أفلا تشيعنا)\n(أما الرحيل فدون بعد غد ... فمتى تقول الدار تجمعنا)\n(لتشوقنا هند وقد علمت ... علما بأن البين يفزعنا)\n(عجبا لموقفنا وموقفها ... وبسمع تربيها تراجعنا)\n(ومقالها سر ليلة معنا ... نعهد فإن البين فاجعنا)\n(قلت العيون كثيرة معكم ... وأظن أن السير مانعنا)\n(لا بل نزوركم بأرضكم ... فيطاع قائلكم وشافعنا)\n(قالت أشيء أنت فاعله ... هذا لعمرك أم تخادعنا)\n(بالله حدث ما تؤمله ... واصدق فإن الصدق واسعنا)\n(إضرب لنا أجلا نعد له ... إخلاف موعده تقاطعنا)\nلغناء لابن سريج ثقيل أول مطلق في مجرى البنصر عن إسحاق وذكر عمرو أنه للغريض بالوسطى وفيه لابن سريج خفيف رمل عن الهشامي وذكر حبش أنه لموسى شهوات","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":9,"spl":"شعر عمر في فاطمة الكندية"},
{"id":"b2-14","bab":"الجزء 1","sec":"شعر عمر في زينب الجمحية","page":"ج1 ص100","text":"ومنها مما لم ينسب أيضا صوت\n(لقد أرسلت جاريتي ... وقلت لها خذي حذرك)\n(وقولي في ملاطفة ... لزينب نولي عمرك)\n(فهزت رأسها عجبا ... وقالت من بذا أمرك)\n(أهذا سحرك النسوان ... قد خبرنني خبرك)\nنى فيها ابن سريج خفيف رمل بالبنصر عن عمرو وقال قوم إنه للغريض وفيها لمالك خفيف ثقيل عن ابن المكي وفي هذا الشعر ألحان كثيرة والشعر فيها على غير هذه القافية لأن هذه الأبيات لعمر من قصيدة رائية موصولة الراءات بألف إلا أن المغنين غيروا هذه الأبيات في هذين اللحنين\nفجعلوا مكان الألف كافا وإنما هي\n(لقد أرسلت جاريتي ... وقلت لها خذي حذرا)\nأول القصيدة صوت\n(تصابى القلب وادكرا ... صباه ولم يكن ظهرا)\n(لزينب إذ تجد لنا ... صفاء لم يكن كدرا)\n(أليست بالتي قالت ... لمولاة لها ظهرا)\n(أشيري بالسلام له ... إذا هو نحونا خطرا)\n(لقد أرسلت جاريتي ... وقلت لها خذي حذرا)\n(وقولي في ملاطفة ... لزينب نولي عمرا)\n(فهزت رأسها عجبا ... وقالت من بذا أمرا)\n(أهذا سحرك النسوان ... قد خبرنني الخبرا)\nنى ابن سريج في الثالث والرابع والخامس والأول خفيف ثقيل أول بإطلاق الوتر في مجرى البنصر من رواية إسحاق وذكر عمرو بن بانة في نسخته الأولى أنه لابن سريج وأبو إسحاق ينسبه في نسخته الثانية إلى دحمان وللغريض في الأول من الأبيات لحن من القدر الأوسط من الثقيل الأول بالوسطى في مجراها أضاف إليه بيتين ليسا من هذه القصيدة وهما\n(طربت ورد من تهوى ... جمال الحي فابتكرا)\n(فقل للمالكية لا ... تلومي القلب إن جهرا)\nذكر يونس أن لمعبد في هذا الشعر الذي أوله\n(تصابى القلب وادكرا ... )\nلحنين لم يذكر جنسيهما وذكر الهشامي أن أحدهما خفيف ثقيل والآخر رمل وفي الأبيات التي غنى فيها الغريض رمل لدحمان عن الهشامي قال ويقال إنه لابنة الزبير وزينب التي ذكرها عمر بن أبي ربيعة هاهنا يقال لها زينب بنت موسى أخت قدامة بنت موسى الجمحي أخبرني بذلك محمد بن خلف بن المرزبان عن أبي بكر العامري وأخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عبد الرحمن بن عبد الله بن عبد العزيز الزهري قال حدثني عمي عمران بن عبد العزيز قال شبب عمر بن أبي ربيعة بزينب بنت موسى الجمحية في قصيدته التي يقول فيها صوت\n(يا خليلي من ملام دعاني ... وألما الغداة بالأظعان)\n(لا تلوما في آل زينب إن القلب ... رهن بآل زينب عاني)\n(ما أرى ما بقيت أن أذكر الموقف ... منها بالخيف إلا شجاني)\nغنى في هذه الأبيات الغريض خفيف رمل بالبنصر عن عمرو\n(لم تدع للنساء عندي حظا ... غير ما قلت مازحا بلساني)\n(هي أهل الصفاء والود مني ... وإليها الهوى فلا تعذلاني)\n(حين قالت لأختها ولأخرى ... من قطين مولد حدثاني)\n(كيف لي اليوم أن أرى عمر المرسل ... سرا في القول أن يلقاني)\n(قالتا نبتغي رسولا إليه ... ونميت الحديث بالكتمان)\n(إن قلبي بعد الذي نلت منها ... كالمعمى عن سائر النسوان)\nال وكان سبب ذكره لها أن ابن أبي عتيق ذكرها عنده يوما فأطراها ووصف من عقلها وأدبها وجمالها ما شغل قلب عمر وأماله إليها فقال فيها الشعر وشبب بها فبلغ ذلك ابن أبي عتيق فلامه فيه وقال له أتنطق الشعر في ابنة عمي فقال عمر صوت\n(لا تلمني عتيق حسبي الذي بي ... إن بي يا عتيق ما قد كفاني)\n(لا تلمني وأنت زينتها لي ... أنت مثل الشيطان للإنسان)\n(إن بي داخلا من الحب قد أبلى ... عظامي مكنونه وبراني)\n(لو بعينيك يا عتيق نظرنا ... ليلة السفح قرت العينان)\n(إذا بدا الكشح والوشاح من الدر ... وفصل فيه من المرجان)\n(قد قلى قلبي النساء سواها ... غير ما قلت مازحا بلساني)\nأول هذه القصيدة\n(إنني اليوم عاد لي أحزاني ... وتذكرت ما مضى من زماني)\n(وتذكرت ظبية أم رئم ... هاج لي الشوق ذكرها فشجاني)\nنى أبو العبيس بن حمدون في لا تلمني عتيق لحنا من الثقيل الأول المطلق وفيه رمل طنبوري مجهول أخبرني الحرمي قال حدثنا الزبير قال أخبرني عبد الملك بن عبد العزيز عن يوسف بن الماجشون قال أنشد عمر بن أبي ربيعة قوله\n(يا خليلي من ملام دعاني ... وألما الغداة بالأظعان)\n(لا تلوما في آل زينب إن القلب ... رهن بآل زينب عاني)","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":10,"spl":"شعر عمر في زينب الجمحية","partial":1},
{"id":"b2-15","bab":"الجزء 1","sec":"شعر عمر في زينب الجمحية","page":"ج1 ص100","text":"لقصيدة قال فبلغ ذلك أبا وداعة السهمي فأنكره وغضب وبلغ ذلك ابن أبي عتيق وقيل له إن أبا وداعة قد اعترض لابن أبي ربيعة من دون زينب بنت موسى وقال لا أقر لابن أبي ربيعة أن يذكر امرأة من بني هصيص في شعره فقال ابن أبي عتيق لا تلوموا أبا وداعة أن ينعظ من سمرقند على أهل عدن\nقال الزبير وحدثني عبد الرحمن بن عبد الله بن عبد العزيز الزهري قال حدثني عمي عمران بن عبد العزيز قال شبب عمر بن أبي ربيعة بزينب بنت موسى في أبياته التي يقول فيها\n(لا تلوما في آل زينب إن القلب ... رهن بآل زينب عاني)\nفقال له ابن أبي عتيق أما قلبك فقد غيب عنا وأما لسانك فشاهد عليك قال عبد الرحمن بن عبد الله قال عمران بن عبد العزيز عذل ابن أبي عتيق عمر في ذكره زينب في شعره فقال عمر\n(لا تلمني عتيق حسبي الذي بي ... إن بي يا عتيق ما قد كفاني)\n(لا تلمني وأنت زينتها لي ... )\nال فبدره ابن أبي عتيق فقال\n(أنت مثل الشيطان للإنسان ... )\nفقال ابن أبي ربيعة هكذا ورب البيت قلته فقال ابن أبي عتيق إن شيطانك ورب القبر ربما ألم بي فيجد عندي من عصيانه خلاف ما يجد عندك من طاعته فيصيب مني وأصيب منه أخبرني الحرمي قال حدثنا الزبير قال حدثني عبد الملك بن عبد العزيز قال حدثني قدامة بن موسى قال خرجت بأختي زينب إلى العمرة فلما كنت بسرف لقيني عمر بن أبي\nربيعة على فرس فسلم علي فقلت له إلى أين أراك متوجها يا أبا الخطاب فقال ذكرت لي امرأة من قومي برزة الجمال فأردت الحديث معها فقلت هل علمت أنها أختي فقال لا واستحيا وثنى عنق فرسه راجعا إلى مكة أخبرني محمد بن خلف بن المرزبان قال حدثنا أحمد بن الهيثم قال حدثنا العمري عن لقيط بن بكر المحاربي قال أنشدني ابن أبي عتيق قول عمر صوت\n(من لسقيم يكتم الناس ما به ... لزينب نجوى صدره والوساوس)\n(أقول لمن يبغي الشفاء متى تجىء ... بزينب تدرك بعض ما أنت لامس)\n(فإنك إن لم تشف من سقمي بها ... فإني من طب الأطباء آيس)\n(ولست بناس ليلة الدار مجلسا ... لزينب حتى يعلو الرأس رامس)\n(خلاء بدت قمراؤه وتكشفت ... دجنته وغاب من هو حارس)\n(وما نلت منها محرما غير أننا ... كلانا من الثوب المورد لابس)\n(نجيين نقضي اللهو في غير مأثم ... وإن رغمت م الكاشحين المعاطس)\nقال فقال ابن أبي عتيق أمنا يسخر ابن أبي ربيعة فأي محرم بقي ثم أتى عمر فقال له يا عمر ألم تخبرني أنك ما أتيت حراما قط قال بلى قال فأخبرني عن قولك\n(كلانا من الثوب المورد لابس ... )\nما معناه قال والله لأخبرنك خرجت أريد المسجد وخرجت زينت تريده فالتقينا فاتعدنا لبعض الشعاب فلما توسطنا الشعب أخذتنا السماء فكرهت أن يرى بثيابها بلل المطر فيقال لها ألا استترت بسقائف المسجد أن كنت فيه فأمرت غلماني فسترونا بكساء خز كان علي فذلك حين أقول\n(كلانا من الثوب المطارف لابس ... )\nقال له ابن أبي عتيق يا عاهر هذا البيت يحتاج إلى حاضنة الغناء في هذه الأبيات التي أولها\n(من لسقيم يكتم الناس ما به ... )\nرذاذ ثقيل أول وكان بعض المحدثين ممن شاهدناه يدعي أنه له ولم يصدق أخبرني الحرمي قال حدثنا الزبير قال حدثني عبد الملك بن عبد العزيز عن يوسف بن الماجشون قال قال عمر بن أبي ربيعة في زينب بنت موسى","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":11,"spl":"شعر عمر في زينب الجمحية — الصبي العاشق","partialRef":{"sid":"b2-14","gi":7,"vi":1,"side":1},"partial":1},
{"id":"b2-16","bab":"الجزء 1","sec":"الصبي العاشق","page":"ج1 ص108","text":"صوت\n(طال من آل زينب الإعراض ... للتعدي وما بها الإبغاض)\n(ووليدين كان علقها القلب ... إلى أن علا الرؤوس بياض)\n(حبلها عندنا متين وحبلي ... عندها واهن القوى أنقاض)\nلغناء في هذه الأبيات لابن محرز خفيف رمل بالبنصر عن عمرو وقال الهشامي فيه لابن جامع خفيف رمل آخر أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير قال عبد الرحمن بن عبد الله وحدثني إبراهيم بن محمد بن عبد العزيز عن أبيه قال لما قال عمر بن أبي ربيعة في زينب\n(لم تدع للنساء عندي نصيبا ... غير ما قلت مازحا بلساني)\nقال له ابن أبي عتيق رضيت لها بالمودة وللنساء بالدهفشة قال والدهفشة التجميش والخديعة بالشيء اليسير وقال غير الزبير في هذا الخبر الدهقشة مكان الدهفشة","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":11,"spl":"شعر عمر في زينب الجمحية — الصبي العاشق"},
{"id":"b2-17","bab":"الجزء 1","sec":"عمر يقول في زينت","page":"ج1 ص109","text":"صوت\n(أيها الكاشح المعير بالصرم ... تزحزح فما لها الهجران)\n(لا مطاع في آل زينب فارجع ... أو تكلم حتى يمل اللسان)\n(نجعل الليل موعدا حين نمسي ... ثم يخفي حديثنا الكتمان)\n(كيف صبري عن بعض نفسي وهل يصبر ... عن بعض نفسه الإنسان)\n(ولقد أشهد المحدث عند القصر ... فيه تعفف وبيان)\n(في زمان من المعيشة لدن ... قد مضى عصره وهذا زمان)\nلغناء في هذه الأبيات لابن سريج رمل بالوسطى عن عمرو ودنانير وذكر يونس\nأن فيه لحنا لابن محرز ولحنا لابن عباد الكاتب أول لحن ابن عباد الكاتب\n(لا مطاع في آل زينب ... )\nأول لحن ابن محرز\n(ولقد أشهد المحدث ... )\nومما غني فيه لابن محرز من أشعار عمر بن أبي ربيعة في زينب بنت موسى قوله صوت\n(يا من لقلب متيم كلف ... يهذي بخود مريضة النظر)\n(تمشي الهوينى إذا مشت فضلا ... وهي كمثل العسلوج في الشجر)\nلغريض في هذين البيتين خفيف رمل بالوسطى ولابن سريج رمل بالبنصر عن الهشامي وحبش","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":12,"spl":"عمر يقول في زينت — عمر يغالي في مدح نفسه على لسان زينب","partial":1},
{"id":"b2-18","bab":"الجزء 1","sec":"براعة الوصف عند عمر","page":"ج1 ص110","text":"(ما زال طرفي يحار إذ برزت ... حتى رأيت النقصان في بصري)\n(أبصرتها ليلة ونسوتها ... يمشين بين المقام والحجر)\n(ما إن طمعنا بها ولا طمعت ... حتى التقينا ليلا على قدر)\n(بيضا حسانا خرائدا قطفا ... يمشين هونا كمشية البقر)\n(قد فزن بالحسن والجمال معا ... وفزن رسلا بالدل والخفر)\n(ينصتن يوما لها إذا نطقت ... كيما يشرفنها على البشر)\n(قالت لترب لها تحدثها ... لنفسدن الطواف في عمر)\n(قومي تصدي له ليعرفنا ... ثم اغمزيه يا أخت في خفر)\n(قالت لها قد غمزته فأبى ... ثم اسبطرت تسعى على أثري)\n(من يسق بعد المنام ريقتها ... يسق بمسك وبارد خصر)\nنى في هذا الشعر الغريض خفيف رمل بالوسطى عن عمرو وغنى فيه\nابن سريج رملا بالبنصر عن الهشامي وحبش ومنها","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":12,"spl":"عمر يقول في زينت — عمر يغالي في مدح نفسه على لسان زينب"},
{"id":"b2-19","bab":"الجزء 1","sec":"خيال زينب الجمحية يقض مضجع عمر","page":"ج1 ص112","text":"صوت\n(ألا يا بكر قد طرقا ... خيال هاج لي الأرقا)\n(لزينب إنها همي ... فكيف بحبلها خلقا)\n(خدلجة إذا انصرفت ... رأيت وشاحها قلقا)\n(وساقا تملأ الخلخال ... فيه تراه مختنقا)\n(إذا ما زينب ذكرت ... سكبت الدمع متسقا)\n(كأن سحابة تهمي ... بماء حملت غدقا)\nلغناء لحنين رمل عن الهشامي وفيه لابن عباد خفيف ثقيل ويقال إنه ليونس ومما قاله فيها أيضا وغنى فيه","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":12,"spl":"عمر يقول في زينت — عمر يغالي في مدح نفسه على لسان زينب"},
{"id":"b2-20","bab":"الجزء 1","sec":"عمر يغالي في مدح نفسه على لسان زينب","page":"ج1 ص113","text":"صوت\n(ألمم بزينب إن البين قد أفدا ... قل الثواء لئن كان الرحيل غدا)\n(قد حلفت ليلة الصورين جاهدة ... وما على المرء إلا الحلف مجتهدا)\n(لأختها ولأخرى من مناصفها ... لقد وجدت به فوق الذي وجدا)\n(لو جمع الناس ثم اختير صفوهم ... شخصا من الناس لم أعدل به أحدا)\nلغناء لابن سريج رمل بالسبابة والبنصر في الأول والثاني عن يحيى المكي وله فيه أيضا خفيف رمل بالوسطى في الثاني والثالث والرابع عن عمرو ولمعبد ثقيل أول في الأول والثاني عن الهشامي وفيه خفيف ثقيل ينسب إلى الغريض ومالك أخبرني علي بن صالح قال حدثنا أبو هفان عن إسحاق عن مصعب الزبيري قال اجتمع نسوة فذكرن عمر بن أبي ربيعة وشعره وظرفه ومجلسه وحديثه فتشوقن إليه وتمنينه فقالت سكينة أنا لكن به فبعثت إليه رسولا أن يوافي الصورين ليلة سمتها فوافاهن على رواحله فحدثهن حتى طلع الفجر وحان انصرافهن فقال لهن والله إني لمحتاج إلى زيارة قبر النبي والصلاة في مسجده ولكني لا أخلط بزيارتكن شيئا ثم انصرف إلى مكة وقال في ذلك\n(ألمم بزينب إن البين قد أفدا ... )\nوذكر الأبيات المتقدمة أخبرني عمي قال حدثنا الكراني قال حدثنا العمري عن لقيط قال أنشد جرير قول عمر بن أبي ربيعة","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":12,"spl":"عمر يقول في زينت — عمر يغالي في مدح نفسه على لسان زينب","partial":1},
{"id":"b2-21","bab":"الجزء 1","sec":"عمر يصيب شعره ما أخطأ الآخرون","page":"ج1 ص114","text":"صوت\n(سائلا الربع بالبلي وقولا ... هجت شوقا لي الغداة طويلا)\n(أين حي حلوك إذ أنت محفوف ... بهم آهل أراك جميلا)\n(قال ساروا فأمعنوا واستقلوا ... وبرغمي لو استطعت سبيلا)\n(سئمونا وما سئمنا مقاما ... وأحبوا دماثة وسهولا)\nقال جرير إن هذا الذي كنا ندور عليه فأخطأناه وأصابه هذا القرشي وفي هذه الأبيات رملان أحدهما لابن سريج بالسبابة في مجرى الوسطى والآخر لإسحاق مطلق في مجرى البنصر جميعا من روايته وذكر عمرو أن فيها رملا ثالثا بالوسطى لابن جامع وقال الهشامي فيها ثلاثة أرمال لابن سريج وابن جامع وإبراهيم ولأبي العبيس بن حمدون فيها ثاني ثقيل وفيها هزج\nلإبراهيم الموصلي من جامع أغانيه أخبرني الحرمي قال حدثنا الزبير قال وجدت كتابا بخط محمد بن الحسن ذكر فيه أن فليح بن إسماعيل حدثه عن معاذ صاحب الهروي أن النصيب قال عمر بن أبي ربيعة أوصفنا لربات الحجال أخبرني الطوسي قال حدثنا الزبير قال حدثتني ظمياء مولاة فاطمة بنت عمر بن مصعب قالت سمعت جدك يقول وقد أنشد قول عمر بن أبي ربيعة","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":13,"spl":"عمر يصيب شعره ما أخطأ الآخرون — ابن أبي عتيق يقول رأيه في شعر عمر"},
{"id":"b2-22","bab":"الجزء 1","sec":"سلام بن الغساني يغني لعمر","page":"ج1 ص115","text":"صوت\n(يا ليتني قد أجزت الحبل نحوكم ... حبل المعرف أو جاوزت ذا عشر)\n(إن الثواء بأرض لا أراك بها ... فاستيقنيه ثواء حق ذي كدر)\n(وما مللت ولكن زاد حبكم ... وما ذكرتك إلا ظلت كالسدر)\n(ولا جذلت بشيء كان بعدكم ... ولا منحت سواك الحب من بشر)\nلغناء في هذه الأربعة الأبيات لسلام بن الغساني رمل بالسبابة في مجرى\nالوسطى عن إسحاق وفيه لابن جامع وقفا النجار لحنان من كتاب إبراهيم ولم يجنسهما وتمام الأبيات\n(أذري الدموع كذي سقم يخامره ... وما يخامرني سقم سوى الذكر)\n(كم قد ذكرتك لو أجدى تذكركم ... يا أشبه الناس كل الناس بالقمر)\nالت فقال جدك إن لشعر عمر بن أبي ربيعة لموقعا في القلب ومخالطة للنفس ليسا لغيره ولو كان شعر يسحر لكان شعره سحرا أخبرني الحرمي قال حدثنا الزبير قال حدثني عمامة بن عمر قال رأيت عامر بن صالح بن عبد الله بن عروة بن الزبير يسأل المسور بن عبد الملك عن شعر عمر بن أبي ربيعة فجعل يذكر له شيئا لا يعرفه فيسأله أن يكتبه إياه فيفعل فرأيته يكتب ويده ترعد من الفرح","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":13,"spl":"عمر يصيب شعره ما أخطأ الآخرون — ابن أبي عتيق يقول رأيه في شعر عمر"},
{"id":"b2-23","bab":"الجزء 1","sec":"ابن أبي عتيق يقول رأيه في شعر عمر","page":"ج1 ص116","text":"أخبرني الحرمي قال حدثنا الزبير قال حدثني عبد الملك بن عبد العزيز بن الماجشون عن عمه يوسف قال ذكر شعر الحارث بن خالد وشعر عمر بن أبي ربيعة عن ابن أبي عتيق في مجلس رجل من ولد خالد بن العاصي بن هشام فقال صاحبنا يعني الحارث\nابن خالد أشعرهما فقال له ابن أبي عتيق بعض قولك يابن أخي لشعر عمر بن أبي ربيعة نوطة في القلب وعلوق بالنفس ودرك للحاجة ليست لشعر وما عصي الله جل وعز بشعر أكثر مما عصي بشعر ابن أبي ربيعة فخذ عني ما أصف لك أشعر قريش من دق معناه ولطف مدخله وسهل مخرجه ومتن حشوه وتعطفت حواشيه وأنارت معانيه وأعرب عن حاجته فقال المفضل للحارث أليس صاحبنا الذي يقول\n(إني وما نحروا غداة منى ... عند الجمار يؤودها العقل)\n(لو بدلت أعلى مساكنها ... سفلا وأصبح سفلها يعلو)\n(فيكاد يعرفها الخبير بها ... فيرده الإقواء والمحل)\n(لعرفت مغناها بما احتملت ... مني الضلوع لأهلها قبل)\nقال له ابن أبي عتيق يابن أخي استر على نفسك واكتم على صاحبك\nولا تشاهد المحافل بمثل هذا أما تطير الحارث عليها حين قلب ربعها فجعل عاليه سافله ما بقي إلا أن يسأل الله تبارك وتعالى لها حجارة من سجيل ابن أبي ربيعة كان أحسن صحبة للربع من صاحبك وأجمل مخاطبة حيث يقول\n(سائلا الربع بالبلي وقولا ... هجت شوقا لي الغداة طويلا)\nذكر الأبيات الماضية قال فانصرف الرجل خجلا مذعنا أخبرني علي بن صالح قال حدثني أبو هفان عن إسحاق عن رجاله المسمين وأخبرني به الحرمي عن الزبير عن عمه عن جده قالوا كان الحارث بن عبد الله بن أبي ربيعة أخو عمر بن أبي ربيعة رجلا صالحا دينا من سروات قريش وإنما لقب القباع لأن عبد الله بن الزبير كان ولاه البصرة فرأى مكيالا لهم فقال إن مكيالكم هذا لقباع قال وهو الشيء الذي له قعر فلقب بالقباع وأخبرني محمد بن خلف بن المرزبان وأحمد بن عبد العزيز الجوهري\nوحبيب بن نصر المهلبي قالوا حدثنا عمر بن شبة قال حدثني عبد الله بن محمد الطائي قال حدثنا خالد بن سعيد قال","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":13,"spl":"عمر يصيب شعره ما أخطأ الآخرون — ابن أبي عتيق يقول رأيه في شعر عمر"},
{"id":"b2-24","bab":"الجزء 1","sec":"أبو الأسود الدؤلي يهجو الحارث بن عبد الله","page":"ج1 ص119","text":"استعمل ابن الزبير الحارث بن عبد الله بن أبي ربيعة على البصرة فأتوه بمكيال لهم فقال لهم إن مكيالكم هذا لقباع فغلب عليه وقال أبو الأسود الدؤلي وقد عتب عليه يهجوه ويخاطب ابن الزهير\n(أمير المؤمنين جزيت خيرا ... أرحنا من قباع بني المغيره)\n(بلوناه ولمناه فأعيا ... علينا ما يمر لنا مريره)\n(على أن الفتى نكح أكول ... وولاج مذاهبه كثيره)\nالوا وكان الحارث ينهى أخاه عن قول الشعر فيأبى أن يقبل منه فأعطاه ألف دينار على ألا يقول شعرا فأخذ المال وخرج إلى أخواله بلحج وأبين مخافة أن يهيجه مقامه بمكة على قول الشعر فطرب يوم فقال صوت\n(هيهات من أمة الوهاب منزلنا ... إذا حللنا بسيف البحر من عدن)\n(واحتل أهلك أجيادا وليس لنا ... إلا التذكر أو حظ من الحزن)\n(لو أنها أبصرت بالجزع عبرته ... من أن يغرد قمري على فنن)\n(إذا رأت غير ما ظنت بصاحبها ... وأيقنت أن لحجا ليس من وطني)\n(ما أنس لا أنس يوم الخيف موقفها ... وموقفي وكلانا ثم ذو شجن)\n(وقولها للثريا وهي باكية ... والدمع منها على الخدين ذو سنن)\n(بالله قولي له في غير معتبة ... ماذا أردت بطول المكث في اليمن)\n(إن كنت حاولت دنيا أو ظفرت بها ... فما أخذت بترك الحج من ثمن)\nال فسارت القصيدة حتى سمعها أخوه الحارث فقال هذا والله شعر عمر قد فتك وغدر قال وقال ابن جريج ما ظننت أن الله عز و جل ينفع أحدا بشعر عمر بن أبي ربيعة حتى سمعت وأنا باليمن منشدا ينشد قوله\n(بالله قولي له في غير معتبة ... ماذا أردت بطول المكث في اليمن)\n(إن كنت حاولت دنيا أو ظفرت بها ... فما أخذت بترك الحج من ثمن)\nحركني ذلك على الرجوع إلى مكة فخرجت مع الحاج وحججت غنى في أبيات عمر هذه ابن سريج ولحنه رمل بالبنصر في مجراها عن إسحاق وفيها للغريض ثقيل أول بالوسطى عن عمرو","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":14,"spl":"أبو الأسود الدؤلي يهجو الحارث بن عبد الله — الوليد بن عبد الملك يسأل عمر عن سبب الأثر الذي"},
{"id":"b2-25","bab":"الجزء 1","sec":"الوليد بن عبد الملك يسأل عمر عن سبب الأثر الذي في منكبه","page":"ج1 ص121","text":"أخبرني علي بن صالح قال حدثنا أبو هفان قال حدثني إسحاق عن السعدي قال قدم الوليد بن عبد الملك مكة فأراد أن يأتي الطائف فقال هل لي في رجل علم بأموال الطائف فيخبرني عنها فقالوا عمر بن أبي ربيعة قال لا حاجة لي به ثم عاد فسأل فذكروه له فرده ثم عاد فسأل فذكروه له ثم رده ثم عاد فسأل فذكروه له فقال هاتوه فركب معه يحدثه ثم حرك عمر رداءه ليصلحه على كتفه فرأى على منكبه أثرا فقال ما هذا الأثر فقال كنت عند جارية إذ جاءتني جارية برسالة من عند جارية أخرى فجعلت تسارني فغارت التي كنت أحدثها فعضت منكبي فما وجدت ألم عضها من لذة ما كانت تلك تنفث في أذني حتى بلغت ما ترى والوليد يضحك فلما رجع عمر قيل له ما الذي كنت تضحك أمير المؤمنين به فقال ما زلنا في حديث الزنا حتى رجعنا أخبرني الحرمي قال حدثنا الزبير قال حدثني محمد بن عبد الله البكري وغيره عن عبد الجبار بن سعيد المساحقي عن أبيه قال دخلت مسجد رسول الله مع نوفل بن مساحق فإنه لمعتمد على\nيدي إذ مررنا بسعيد بن المسيب في مجلسه وحوله جلساؤه فسلمنا عليه فرد علينا ثم قال لنوفل يا أبا سعيد من أشعر صحابنا أم صاحبكم يريد عبد الله ابن قيس أو عمر بن أبي ربيعة فقال نوفل حين يقولان ماذا يا أبا محمد قال حين يقول صاحبنا\n(خليلي ما بال المطايا كأنما ... نراها على الأدبار بالقوم تنكص)\n(وقد قطعت أعناقهن صبابة ... فأنفسنا مما يلاقين شخص)\n(وقد أتعب الحادي سراهن وانتحى ... بهن فما يألو عجول مقلص)\n(يزدن بنا قربا فيزداد شوقنا ... إذا زاد طول العهد والبعد ينقص)\nويقول صاحبك ما شئت فقال له نوفل صاحبكم أشعر في الغزل وصاحبنا أكثر أفانين شعر فقال سعيد صدقت فلما انقضى ما بينهما من ذكر الشعر جعل سعيد يستغفر الله ويعقد بيده حتى وفى مائة فقال البكري في حدثيه عن عبد الجبار قال مسلم فلما انصرفنا قلت لنوفل أتراه استغفر الله من إنشاد الشعر في مسجد رسول الله فقال كلا هو كثير الإنشاد والاستنشاد للشعر فيه ولكن أحسب ذلك للفخر بصاحبه","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":14,"spl":"أبو الأسود الدؤلي يهجو الحارث بن عبد الله — الوليد بن عبد الملك يسأل عمر عن سبب الأثر الذي"},
{"id":"b2-26","bab":"الجزء 1","sec":"الوليد بن يزيد يفضل غزل عمر على غزل جميل بن معمر","page":"ج1 ص122","text":"أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال قال أبو عبيدة\nحدثنا عوانة بن الحكم وأبو يعقوب الثقفي أن الوليد بن يزيد بن عبد الملك قال لأصحابه ذات ليلة أي بيت قالته العرب أغزل فقال بعضهم قول جميل\n(يموت الهوى مني إذا ما لقيتها ... ويحيا إذا فارقتها فيعود)\nقال آخر قول عمر بن أبي ربيعة\n(كأنني حين أمسي لا تكلمني ... ذو بغية يبتغي ما ليس موجودا)\nقال الوليد حسبك والله بهذا أخبرني الحرمي قال حدثنا الزبير بن بكار قال حدثني محمد بن إسماعيل ابن إبراهيم بن عبد الحميد عن شيخ من أهله عن أبي الحارث مولى هشام بن الوليد بن المغيرة قال وهو الذي يقول فيه عمر بن أبي ربيعة\n(يا أبا الحارث قلبي طائر ... فأتمر أمر رشيد مؤتمن)\nال شهدت عمر بن أبي ربيعة وجميل بن عبد الله بن معمر العذري وقد اجتمعا بالأبطح فأنشد جميل قصيدته التي يقول فيها\n(لقد فرح الواشون أن صرمت حبلي ... بثينة أو أبدت لنا جانب البخل)\n(يقولون مهلا يا جميل وإنني ... لأقسم مالي عن بثينة من مهل)\nحتى أتى على آخرها ثم قال لعمر يا أبا الخطاب هل قلت في هذا الروي شيئا قال نعم قال فأنشدنيه فأنشده قوله\n(جرى ناصح بالود بيني وبينها ... فقربني يوم الحصاب إلى قتلي)\n(فطارت بحد من فؤادي وقارنت ... قرينتها حبل الصفاء إلى حبلي)\n(فلما تواقفنا عرفت الذي بها ... كمثل الذي بي حذوك النعل بالنعل)\n(فقلن لها هذا عشاء وأهلنا ... قريب ألما تسأمي مركب البغل)\n(فقالت فما شئتن قلن لها انزلي ... فللأرض خير من وقوف على رحل)\n(نجوم دراري تكنفن صورة ... من البدر وافت غير هوج ولا عجل)\n(فسلمت واستأنست خيفة أن يرى ... عدو مقامي أو يرى كاشح فعلي)\n(فقالت وأرخت جانب الستر إنما ... معي فتكلم غير ذي رقبة أهلي)\n(فقلت لها ما بي لهم من ترقب ... ولكن سري ليس يحمله مثلي)\n(فلما اقتصرنا دونهن حديثنا ... وهن طبيبات بحاجة ذي الشكل)\n(عرفن الذي تهوى فقلن ائذني لنا ... نطف ساعة في برد ليل وفي سهل)\n(فقالت فلا تلبثن قلن تحدثي ... أتيناك وانسبن انسياب مها الرمل)\n(وقمن وقد أفهمن ذا اللب أنما ... أتين الذي يأتين من ذاك من أجلي)\nقال جميل هيهات يا أبا الخطاب لا أقول والله مثل هذا سجيس الليالي والله ما يخاطب النساء مخاطبتك أحد وقام مشمرا قال أبو عبد الله الزبير قال عمي مصعب كان عمر يعارض جميلا فإذا قال هذا قصيدة قال هذا مثلها فيقال إنه في الرائية والعينية أشعر من جميل وإن جميلا أشعر منه في اللامية وكلاهما قد قال بيتا نادرا ظريفا قال جميل\n(خليلي فيما عشتما هل رأيتما ... قتيلا بكى من حب قاتله قبلي)\nقال عمر\n(فقالت وأرخت جانب الستر إنما ... معي فتكلم غير ذي رقبة أهلي)","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":15,"spl":"الوليد بن يزيد يفضل غزل عمر على غزل جميل بن معمر — الفرزدق يشهد لعمر"},
{"id":"b2-27","bab":"الجزء 1","sec":"الفرزدق يشهد لعمر","page":"ج1 ص125","text":"أخبرني علي بن صالح قال حدثنا أبو هفان عن إسحاق عن المدائني قال سمع الفرزدق عمر بن أبي ربيعة ينشد قوله\n(جرى ناصح بالود بيني وبينها ... فقربني يوم الحصاب إلى قتلي)\nولما بلغ قوله\n(فقمن وقد أفهمن ذا اللب أنما ... أتين الذي يأتين من ذاك من أجلي)\nاح الفرزدق هذا والله الذي أرادته الشعراء فأخطأته وبكت على الديار","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":15,"spl":"الوليد بن يزيد يفضل غزل عمر على غزل جميل بن معمر — الفرزدق يشهد لعمر"},
{"id":"b2-28","bab":"الجزء 1","sec":"نسبة ما في هذه الأشعار من الغناء","page":"ج1 ص126","text":"منها في قصيدة جميل التي أنشدها عمر واستنشده ماله في وزنها صوت\n(خليلي فيما عشتما هل رأيتما ... قتيلا بكى من حب قاتله قبلي)\n(أبيت مع الهلاك ضيفا لأهلها ... وأهلي قريب موسعون ذوو فضل)\n(أفق أيها القلب اللجوج عن الجهل ... ودع عنك جملا لا سبيل إلى جمل)\n(فلو تركت عقلي معي ما طلبتها ... ولكن طلابيها لما فات من عقلي)\nلغناء للغريض ثاني ثقيل بالوسطى عن عمرو في الأول والثاني من الأبيات وذكر الهشامي الأبيات كلها ووصف أن الثقيل الثاني الذي يغنى به فيها لمعبد وذكر يحيى المكي أن لابن محرز في الثالث وما بعده من الأبيات ثاني ثقيل بالخنصر والبنصر وفي هذه الأبيات التي أولها الثالث هزج بالبنصر يمان عن عمرو وفي الرابع والخامس لابن طنبورة خفيف رمل عن الهشامي وفيها لإسحاق ثقيل أول عن الهشامي أيضا وذكر حماد عن أبيه أن لنافع الخير مولى\nعبد الله بن جعفر في هذه الأبيات لحنا ولم يحبسنه وذكر حبش أن الثقيل الأول لابن طنبورة ومنها في شعر جميل أيضا صوت\n(لقد فرح الواشون أن صرمت حبلي ... بثينة أو أبدت لنا جانب البخل)\n(فلو تركت عقلي معي ما طلبتها ... ولكن طلابيها لما فات من عقلي)\nلغناء لابن مسجح ثقيل أول بالوسطى عن الهشامي ومنها في شعر عمر بن أبي ربيعة المذكور في أول الخبر صوت\n(فقالت وأرخت جانب الستر إنما ... معي فتحدث غير ذي رقبة أهلي)\n(فقلت لها ما بي لهم من ترقب ... ولكن سري ليس يحمله مثلي)\n(جرى ناصح بالود بيني وبينها ... فقربني يوم الحصاب إلى قتلي)\nنى في هذه الأبيات ابن سريج ولحنه رمل مطلق في مجرى البنصر عن إسحاق وعمرو وذكر يونس أن فيه لحنا لمالك لم يجنسه وذكر الهشامي أن\nلحن مالك خفيف ثقيل وذكر حبش أن لمعبد فيه لحنا من الثقيل الأول بالبنصر ولابن سريج ثاني ثقيل بالوسطى وليس حبش ممن يعتمد في هذا على روايته أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال أدركت مشيخة من قريش لا يزنون بعمر بن أبي ربيعة شاعرا من أهل دهره في النسيب ويستحسنون منه ما كانوا يستقبحونه من غيره من مدح نفسه والتحلي بمودته والإبتيار في شعره والابتيار أن يفعل الإنسان الشيء فيذكره ويفخر به والابتهار أن يقول ما لم يفعل أخبرني محمد بن خلف قال أخبرني عبد الله بن عمر وغيره عن إبراهيم بن المنذر الحزامي عن عبد العزيز بن عمران قال قال ابن أبي عتيق لعمر وقد أنشده قوله صوت\n(بينما ينعتنني أبصرنني ... دون قيد الميل يعدو بي الأغر)\n(قالت الكبرى أتعرفن الفتى ... قالت الوسطى نعم هذا عمر)\n(قالت الصغرى وقد تيمتها ... قد عرفناه وهل يخفى القمر)\nلغناء في هذه الأبيات لابن سريج خفيف رمل بالبنصر فقال له ابن أبي عتيق وقد أنشدها أنت لم تنسب بها وإنما نسبت بنفسك كان ينبغي أن\nتقول قلت لها فقالت لي فوضعت خدي فوطئت عليه أخبرني الحرمي قال حدثنا الزبير بن بكار قال","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":16,"spl":"نسبة ما في هذه الأشعار من الغناء — تفضيل شعر عمر على شعراء عصره"},
{"id":"b2-29","bab":"الجزء 1","sec":"تفضيل شعر عمر على شعراء عصره","page":"ج1 ص129","text":"لم يذهب على أحد من الرواة أن عمر كان عفيفا يصف ولا يقف ويحوم ولا يرد أخبرني محمد بن خلف قال حدثنا أحمد بن منصور عن ابن الأعرابي وحدثني علي بن صالح قال حدثنا أبو هفان عن إسحاق الموصلي عن رجاله قالوا قالوا كان ابن أبي ربيعة قد حج في سنة من السنين فلما انصرف من الحج ألفى الوليد بن عبد الملك وقد فرش له في ظهر الكعبة وجلس فجاءه عمر فسلم عليه وجلس إليه فقال له أنشدني شيئا من شعرك فقال يا أمير المؤمنين أنا شيخ كبير وقد تركت الشعر ولي غلامان هما عندي بمنزلة الولد وهما يرويان كل ما قلت وهما لك قال ائتني بهما ففعل فأنشده قوله\n(أمن آل نعم أنت غاد فمبكر ... )\nطرب الوليد واهتز لذلك فلم يزالا ينشدانه حتى قام فأجزل صلته ورد الغلامين إليه حدثني علي بن صالح بن الهيثم الأنباري الكاتب الملقب كيلجة قال حدثني أبو هفان قال حدثنا إسحاق بن إبراهيم الموصلي عن مصعب بن عبد الله الزبيري وأخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار عن عمه مصعب أنه قال","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":16,"spl":"نسبة ما في هذه الأشعار من الغناء — تفضيل شعر عمر على شعراء عصره","partialRef":{"sid":"b2-8","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b2-30","bab":"الجزء 1","sec":"خصائص شعر عمر ومميزاته","page":"ج1 ص130","text":"راق عمر بن أبي ربيعة الناس وفاق نظراءه وبرعهم بسهولة الشعر وشدة الأسر وحسن الوصف ودقة المعنى وصواب المصدر والقصد للحاجة واستنطاق الربع وإنطاق القلب وحسن العزاء ومخاطبة النساء وعفة المقال وقلة الانتقال وإثبات الحجة وترجيح الشك في موضع اليقين وطلاوة الاعتذار وفتح الغزل ونهج العلل وعطف المساءة على العذال وأحسن التفجع وبخل المنازل واختصر الخبر وصدق الصفاء إن قدح أورى وإن اعتذر أبرا وإن تشكى أشجى وأقدم عن خبرة ولم يعتذر بغرة وأسر النوم وغم الطير وأغذ السير وحيرماء الشباب وسهل وقول وقاس الهوى فأربى وعصى وأخلى وحالف بسمعه وطرفه وأبرم نعت الرسل وحذر وأعلن الحب وأسر وبطن به وأظهر وألح وأسف وأنكح النوم وجنى الحديث وضرب ظهره لبطنه وأذل صعبه وقنع بالرجاء من الوفاء وأعلى قاتله واستبكى عاذله ونفض النوم وأغلق رهن منى وأهدر قتلاه وكان بعد هذا كله فصيحا فمن سهولة شعره وشدة أسره قوله صوت\n(فلما تواقفنا وسلمت أشرقت ... وجوه زهاها الحسن أن تتقنعا)\n(تبالهن بالعرفان لما رأينني ... وقلن امرؤ باغ أكل وأوضعا)\nلغناء لابن عباد رمل عن الهشامي وفيه لابن جامع لحن غير مجنس عن إبراهيم ومن حسن وصفه قوله\n(لها من الريم عيناه وسنته ... ونخوة السابق المختال إذ صهلا)\nمن دقة معناه وصواب مصدره قوله صوت\n(عوجا نحي الطلل المحولا ... والربع من أسماء والمنزلا)\n(بسابغ البوباة لم يعده ... تقادم العهد بأن يؤهلا)\nلغناء لابن سريج ثاني ثقيل بالسبابة في مجرى الوسطى عن إسحاق قال إسحاق ابن إبراهيم يعني أنه لم يؤهل فيعدوه تقادم العهد وقال الزبير قال بعض المدنيين يحييه بأن يؤهل أي يدعو له بذلك ومن قصده للحاجة قوله","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":17,"spl":"خصائص شعر عمر ومميزاته — المقال المبكي والقلب المتكلم"},
{"id":"b2-31","bab":"الجزء 1","sec":"الثريا وسهيل","page":"ج1 ص131","text":"صوت\n(أيها المنكح الثريا سهيلا ... عمرك الله كيف يلتقيان)\n(هي شامية إذا ما استقلت ... وسهيل إذا استقل يماني)\nيروى هي غورية الغناء للغريض خفيف ثقيل بالبنصر عن عمرو وابن المكي ومن استنطاقه الربع قوله صوت\n(سائلا الربع بالبلي وقولا ... هجت شوقا لي الغداة طويلا)\n(أين حي حلوك إذ أنت محفوف ... بهم آهل أراك جميلا)\n(قال ساروا فأمعنوا واستقلوا ... وبرغمي لو قد وجدت سبيلا)\nيروى\n(وبكرهي لو استطعت سبيلا ... )\n(سئمونا وما سئمنا جوارا ... وأحبوا دماثة وسهولا)\nيه رملان أحدهما لابن سريج بالسبابة في مجرى الوسطى عن إسحاق والآخر لإسحاق مطلق في مجرى البنصر وفيه لأبي العبيس بن حمدون ثاني ثقيل وقد شرحت نسبته مع خبره في موضع آخر قال إسحاق أنشد جرير هذه الأبيات فقال إن هذا الذي كنا ندور عليه فأخطأناه","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":17,"spl":"خصائص شعر عمر ومميزاته — المقال المبكي والقلب المتكلم","partial":1},
{"id":"b2-32","bab":"الجزء 1","sec":"المقال المبكي والقلب المتكلم","page":"ج1 ص133","text":"(قال لي فيها عتيق مقالا ... فجرت مما يقول الدموع)\n(قال لي ودع سليمى ودعها ... فأجاب القلب لا أستطيع)\nلغناء للهذلي ثاني ثقيل بالوسطى عن الهشامي قال وفيه ليحيى المكي ثقيل أول نسب إلى معبد وهو من منحوله ومن حسن عزائه قوله صوت\n(أألحق إن دار الرباب تباعدت ... أو انبت حبل أن قلبك طائر)\n(أفق قد أفاق العاشقون وفارقوا الهوى ... واستمرت بالرجال المرائر)\n(زع النفس واستبق الحياء فإنما ... تباعد أو تدني الرباب المقادر)\n(أمت حبها واجعل قديم وصالها ... وعشرتها كمثل من لا تعاشر)\n(وهبها كشيء لم يكن أو كنازح ... به الدار أو من غيبته المقابر)\n(وكالناس علقت الرباب فلا تكن ... أحاديث من يبدو ومن هو حاضر)\nالغناء في بعض هذه الأبيات وأوله زع النفس لابن سريج ثقيل أول بالبنصر عن عمرو وفيه لعمر الوادي رمل بالبنصر عن ابن المكي وفيه ل قدار لحن من كتاب إبراهيم غير مجنس وهذه الأبيات يرويها بعض أهل الحجاز لكثير ويرويها الكوفيون للكميت بن معروف الأسدي وذكر بعضها الزبير بن بكار عن أبي عبيدة لكثير في أخباره ومن حسن غزله في مخاطبة النساء قال مصعب الزبيري وقد أجمع أهل بلدنا ممن له علم بالشعر أن هذه الأبيات أغزل ما سمعوا قوله","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":17,"spl":"خصائص شعر عمر ومميزاته — المقال المبكي والقلب المتكلم"},
{"id":"b2-33","bab":"الجزء 1","sec":"عمر يتودد للرباب","page":"ج1 ص134","text":"صوت\n(تقول غداة التقينا الرباب ... أياذا أفلت أفول السماك)\n(وكفت سوابق من عبرة ... كما ارفض نظم ضعيف السلاك)\n(فقلت لها من يطع في الصديق ... أعداءه يجتنبه كذاك)\n(أغرك أني عصيت الملام ... فيك وأن هوانا هواك)\n(وألا أرى لذة في الحياة ... تقر بها العين حتى أراك)\n(فكان من الذنب لي عندكم ... مكارمتي واتباعي رضاك)\n(فليت الذي لام في حبكم ... وفي أن تزاري بقرن وقاك)\n(هموم الحياة وأسقامها ... وإن كان حتف جهيز فداك)\nلغناء لابن سريج ثاني ثقيل بالوسطى وذكر إبراهيم أن فيه لحنا لحكم وقيل إن فيه لحنا آخر لابن جامع ومن عفة مقاله قوله صوت\n(طال ليلي واعتادني اليوم سقم ... وأصابت مقاتل القلب نعم)\n(حرة الوجه والشمائل والجوهر ... تكليمها لمن نال غنم)\n(وحديث بمثله تنزل العصم ... يشوب ذلك حلم)\n(هكذا وصف ما بدا لي منها ... ليس لي بالذي تغيب علم)\n(إن تجودي أو تبخلي فبحمد ... لست يا نعم فيهما من يذم)\nلغناء لابن سريج رمل عن الهشامي ومن قلة انتقاله قوله صوت\n(أيها القائل غير الصواب ... أمسك النصح وأقلل عتابي)\n(واجتنبني واعلمن أن ستعصى ... ولخير لك طول اجتنابي)\n(إن تقل نصحا فعن ظهر غش ... دائم الغمر بعيد الذهاب)\n(ليس بي عي بما قلت إني ... عالم أفقه رجع الجواب)\n(إنما قرة عيني هواها ... فدع اللوم وكلني لما بي)\n(لا تلمني في الرباب وأمست ... عدلت للنفس برد الشراب)\n(هي والله الذي هو ربي ... صادقا أحلف غير الكذاب)\n(أكرم الأحياء طرا علينا ... عند قرب منهم واجتناب)\n(خاطبتني ساعة وهي تبكي ... ثم عزت خلتي في الخطاب)\n(وكفى بي مدرها لخصوم ... لسواها عند حد تبابي)\nلغناء لكردم ثقيل أول بالسبابة في مجرى الوسطى عن إسحاق في الأول والخامس ثم الثاني والثالث وفيه لمعبد خفيف ثقيل بالبنصر عن يحيى المكي ومن إثباته الحجة قوله\n(خليلي بعض اللوم لا ترحلا به ... رفيقكما حتى تقولا على علم)\n(خليلي من يكلف بآخر كالذي ... كلفت به يدمل فؤادا على سقم)\n(خليلي ما كانت تصاب مقاتلي ... ولا غرتي حتى وقعت على نعم)\n(خليلي حتى لف حبلي بخادع ... موقى إذا يرمى صيود إذا يرمي)\n(خليلي لو يرقى خليل من الهوى ... رقيت بما يدني النوار من العصم)\n(خليلي إن باعدت لانت وإن ألن ... تباعد فلم أنبل بحرب ولا سلم)","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":18,"spl":"عمر يتودد للرباب — الاعتذار اللطيف"},
{"id":"b2-34","bab":"الجزء 1","sec":"المعاصم الفضة والوجه النضير","page":"ج1 ص137","text":"صوت\n(نظرت إليها بالمحصب من منى ... ولي نظر لولا التحرج عارم)\n(فقلت أشمس أم مصابيح بيعة ... بدت لك خلف السجف أم أنت حالم)\n(بعيدة مهوى القرط إما لنوفل ... أبوها وإما عبد شمس وهاشم)\n(ومد عليها السجف يوم لقيتها ... على عجل تباعها والخوادم)\n(فلم أستطعها غير أن قد بدا لنا ... عشية راحت وجهها والمعاصم)\n(معاصم لم تضرب على البهم بالضحى ... عصاها ووجه لم تلحه السمائم)\n(نضار ترى فيه إساريع مائه ... صبيح تغاديه الأكف النواعم)\n(إذا ما دعت أترابها فاكتنفنها ... تمايلن أو مالت بهن المآكم)\n(طلبن الصبا حتى إذا ما أصبنه ... نزعن وهن المسلمات الظوالم)\nالغناء لمعبد ثقيل أول بالسبابة في مجرى البنصر عن إسحاق وابن المكي وفيها لابن سريج رمل بالسبابة في مجرى البنصر عن إسحاق أيضا وفيها للغريض خفيف ثقيل بالوسطى عن الهشامي","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":18,"spl":"عمر يتودد للرباب — الاعتذار اللطيف"},
{"id":"b2-35","bab":"الجزء 1","sec":"الاعتذار اللطيف","page":"ج1 ص138","text":"ومن طلاوة اعتذاره قوله صوت\n(عاود القلب بعض ما قد شجاه ... من حبيب أمسى هوانا هواه)\n(يا لقومي فكيف أصبر عمن ... لا ترى النفس طيب عيش سواه)\n(أرسلت إذ رأت بعادي ألا ... يقبلن بي محرشا إن أتاه)\n(دون أن يسمع المقالة منا ... وليطعني فإن عندي رضاه)\n(لا تطع بي فدتك نفسي عدوا ... لحديث على هواه افتراه)\n(لا تطع بي من لو رآني وإياك ... أسيري ضرورة ما عناه)\n(ما ضراري نفسي بهجري من ليس ... مسيئا ولا بعيدا ثراه)\n(واجتنابي بيت الحبيب وما الخلد ... بأشهى إلي من أن أراه)\nلغناء لمعبد خفيف ثقيل بالخنصر في مجرى الوسطىعن إسحاق وفيه لابن جامع ثاني ثقيل بالوسطى عن عمرو وقال عمرو فيه خفيف ثقيل بالوسطى\nللهذلي وفيه لابن محرز ثاني ثقيل بالوسطى عن عمرو وابتداؤه نشيد أوله ما ضراري نفسي وقال الهشامي وفيه لعلية بنت المهدي وسعيد بن جابر لحنان من الثقيل الثاني","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":18,"spl":"عمر يتودد للرباب — الاعتذار اللطيف"},
{"id":"b2-36","bab":"الجزء 1","sec":"الدليل الصادق","page":"ج1 ص139","text":"(وآية ذلك أن تسمعي ... إذا جئتكم ناشدا ينشد)\n(فرحنا سراعا وراح الهوى ... دليلا إليها بنا يقصد)\n(فلما دنونا لجرس النباح ... والصوت والحي لم يرقدوا)\n(بعثنا لها باغيا ناشدا ... وفي الحي بغية من ينشد)\nقد نسبت هذه الأبيات إلى من غنى فيها مع\n(تشط غدا دار جيراننا ... )\nمن فتحه الغزل قوله\n(إذا أنت لم تعشق ولم تدر ما الهوى ... فكن حجرا من يابس الصخر جلمدا)\nمن عطفه المساءة على العذال قوله\nصوت\n(لا تلمني عتيق حسبي الذي بي ... إن بي يا عتيق ما قد كفاني)\n(لا تلمني وأنت زينتها لي ... أنت مثل الشيطان للإنسان)\nلغناء لأبي العبيس بن حمدون ثقيل أول مطلق من مجموع أغانيه وفيه رمل طنبوري محدث وفيه هزج لأبي عيسى بن المتوكل","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":19,"spl":"الدليل الصادق — الهجر القاسي","partialRef":{"sid":"b2-8","gi":5,"vi":0,"side":0},"partial":1},
{"id":"b2-37","bab":"الجزء 1","sec":"الهجر القاسي","page":"ج1 ص140","text":"ومن حسن تفجعه قوله صوت\n(هجرت الحبيب اليوم من غير ما اجترم ... وقطعت من ذي ودك الحبل فانصرم)\n(أطعت الوشاة الكاشحين ومن يطع ... مقالة واش يقرع السن من ندم)\n(أتاني رسول كنت أحسب أنه ... شفيق علينا ناصح كالذي زعم)\n(فلما تباثثنا الحديث وصرحت ... سرائره عن بعض ما كان قد كتم)\n(تبين لي أن المحرش كاذب ... فعندي لك العتبى على رغم من رغم)\n(فملآن لمت النفس بعد الذي مضى ... وبعد الذي آلت وآليت من قسم)\n(ظلمت ولم تعتب وكان رسولها ... إليك سريعا بالرضا لك إذ ظلم)\nلغناء لابن سريج رمل مطلق في مجرى البنصر عن إسحاق وقال يونس فيه لابن سريج لحنان وذكر الهشامي أن لحنه الآخر ثقيل أول وأن لعلوية فيه رملا آخر ومن تبخيله المنازل قوله صوت\n(عرفت مصيف الحي والمتربعا ... ببطن حليات دوارس بلقعا)\n(إلى السرح من وادي المغمس بدلت ... معالمها وبلا ونكباء زعزعا)\n(فيبخلن أو يخبرن بالعلم بعدما ... نكأن فؤادا كان قدما مفجعا)\nلغناء للغريض ثاني ثقيل بالوسطى ومن اختصاره الخبر قوله\nصوت\n(أمن آل نعم أنت غاد فمبكر ... غداة غد أم رائح فمهجر)\n(بحاجة نفس لم تقل في جوابها ... فتبلغ عذرا والمقالة تعذر)\n(أشارت بمدراها وقالت لتربها ... أهذا المغيري الذي كان يذكر)\n(لئن كان إياه لقد حال بعدنا ... عن العهد والإنسان قد يتغير)\nالغناء لابن سريج رمل بالسبابة في مجرى البنصر وله في بيتين آخرين من هذه القصيدة وهما\n(وليلة ذي دوران جشمتني السرى ... وقد يجشم الهول المحب المغرر)\n(فقلت أباديهم فإما أفوتهم ... وإما ينال السيف ثأرا فيثأر)\nمل آخر بالوسطى عن عمرو قال الزبير حدثني إسحاق الموصلي قال قلت لأعرابي ما معنى قول ابن أبي ربيعة\n(بحاجة نفس لم تقل في جوابها ... فتبلغ عذرا والمقالة تعذر)\nقال قام كما جلس\nومن صدقه الصفاء قوله\n(كل وصل أمسى لديك لأنثى ... غيرها وصلها إليها أداء)\n(كل أنثى وإن دنت لوصال ... أو نأت فهي للرباب الفداء)","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":19,"spl":"الدليل الصادق — الهجر القاسي"},
{"id":"b2-38","bab":"الجزء 1","sec":"تذلله في الحب","page":"ج1 ص143","text":"وقوله صوت\n(أحب لحبك من لم يكن ... صفيا لنفسي ولا صاحبا)\n(وأبذل مالي لمرضاتكم ... وأعتب من جاءكم عاتبا)\n(وأرغب في ود من لم أكن ... إلى وده قبلكم راغبا)\n(ولو سلك الناس في جانب ... من الأرض واعتزلت جانبا)\n(ليممت طيتها إنني ... أرى قربها العجب العاجبا)\nلغناء لابن القفاص رمل عن الهشامي ويحيى المكي وفيه للربعي لحن من كتاب إبراهيم غير مجنس صوت\n(طال ليلي وتعناني الطرب ... واعتراني طول هم ووصب)\n(أرسلت أسماء في معتبة ... عتبتها وهي أحلى من عتب)\n(أن أتى منها رسول موهنا ... وجد الحي نياما فانقلب)\n(ضرب الباب فلم يشعر به ... أحد يفتح بابا إذ ضرب)\n(قال أيقاظ ولكن حاجة ... عرضت تكتم منا فاحتجب)\n(ولعمدا ردني فاجتهدت ... بيمين حلفة عند الغضب)\n(يشهد الرحمن لا يجمعنا ... سقف بيت رجبا بعد رجب)\n(قلت حلا فاقبلي معذرتي ... ما كذا يجزي محب من أحب)\n(إن كفي لك رهن بالرضا ... فاقبلي يا هند قالت قد وجب)\nلغناء لمالك خفيف ثقيل بالسبابة في مجرى الوسطى عن إسحاق وفيه لدحمان ثقيل أول بالبنصر عن عمرو وفيه لمعبد لحن من كتاب يونس لم يجنسه وذكر الهشامي أنه خفيف ثقيل وفيه لابن سريج رمل عن الهشامي قال من حكينا عنه في صدر أخبار عمر روايته التي رواها علي بن صالح عن أبي هفان عن إسحاق عن رجاله والحرمي عن الزبير عن عمه كان عمر بن أبي ربيعة يهوى امرأة يقال لها أسماء فكان الرسول يختلف بينهما زمانا وهو لا يقدر عليها ثم ودعته أن تزوره فتأهب لذلك وانتظرها فأبطأت عنه حتى غلبته عينه فنام وكانت عنده جارية له تخدمه فلم تلبث أن\nجاءت ومعها جارية لها فوقفت حجرة وأمرت الجارية أن تضرب الباب فضربته فلم يستيقظ فقالت لها تطلعي فانظري ما الخبر فقالت لها هو مضطجع وإلى جنبه امرأة فحلفت لا تزوره حولا فقال في ذلك\n(طال ليلي وتعناني الطرب ... )\nال أبو هفان في حديثه وبعث إليها امرأة كانت تختلف بينه وبين معارفه وكانت جزلة من النساء فصدقتها عن قصته وحلفت لها أنه لم يكن عنده إلا جاريته فرضيت وإياها يعني عمر بقوله\n(فأتتها طبة عالمة ... تخلط الجد مرارا باللعب)\n(تغلظ القول إذا لانت لها ... وتراخي عند سورات الغضب)\n(لم تزل تصرفها عن رأيها ... وتأناها برفق وأدب)","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":20,"spl":"تذلله في الحب — الوليد بن يزيد يطرب لقصيدة عمر","partial":1},
{"id":"b2-39","bab":"الجزء 1","sec":"الوليد بن يزيد يطرب لقصيدة عمر","page":"ج1 ص145","text":"قال إسحاق في خبره وحدثني ابن كناسة قال أخبرني حماد الراوية قال استنشدني الوليد بن يزيد فانشدته نحوا من ألف قصيدة فما استعادني إلا\nقصيدة عمر بن أبي ربيعة\n(طال ليلي وتعناني الطرب ... )\nلما انشدته قوله\n(فأتتها طبة عالمة ... تخلط الجد مرارا باللعب)\nلى قوله\n(إن كفي لك رهن بالرضا ... فاقبلي يا هند قالت قد وجب)\nفقال الوليد ويحك يا حماد اطلب لي مثل هذه أرسلها إلى سلمى يعني امرأته سلمى بنت سعيد بن خالد بن عمرو بن عثمان وكان طلقها ليتزوج أختها ثم تتبعتها نفسه قال إسحاق وحدثني جماعة منهم الحرمي والزبيري وغيرهما أن عمر أنشد ابن أبي عتيق هذه القصيدة فقال له ابن أبي عتيق الناس يطلبون خليفة مذ قتل عثمان في صفة قوادتك هذه يدبر أمورهم فما يجدونه","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":20,"spl":"تذلله في الحب — الوليد بن يزيد يطرب لقصيدة عمر","partialRef":{"sid":"b2-38","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b2-40","bab":"الجزء 1","sec":"رجع إلى خبر عمر الطويل لقاء فترحيب فصفاء","page":"ج1 ص146","text":"(فالتقينا فرحبت حين سلمت ... وكفت دمعا من العين مارا)\n(ثم قالت عند العتاب رأينا ... منك عنا تجلدا وازورارا)\n(قلت كلالاه ابن عمك بل خفنا ... )\n(أمورا كنا بها أغمارا ... )\n(فجعلنا الصدود لما خشينا ... قالة الناس للهوى أستارا)\n(ليس كالعهد إذ عهدت ولكن ... أوقد الناس بالنميمة نارا)\n(فلذاك الإعراض عنك وما آثر ... )\n(قلبي عليك أخرى اختيارا ... )\n(ما أبالي إذا النوى قربتكم ... فدنوتم من حل أو من سارا)\n(فالليالي إذا نأيت طوال ... وأراها إذا قربت قصارا)\nومن تشكيه الذي أشجى فيه قوله صوت\n(لعمرك ما جاورت غمدان طائعا ... وقصر شعوب أن أكون به صبا)\n(ولكن حمى أضرعتني ثلاثة ... مجرمة ثم استمرت بنا غبا)\n(وحتى لو ان الخلد تعرض إن مشت ... إلى الباب رجلي ما نقلت لها إربا)\n(فإنك لو أبصرت يوم سويقة ... مناخي وحبسي العيس دامية حدبا)\n(ومصرع إخوان كأن أنينهم ... أنين المكاكي صادفت بلدا خصبا)\n(إذا لاقشعر الرأس منك صبابة ... ولاستفرغت عيناك من سكبة غربا)\nنى في الأول والثاني من هذه الأبيات معبد ولحنه خفيف ثقيل أول بالوسطى عن عمرو وفيهما لمالك ثقيل أول عن الهشامي ونسبه يونس إلى مالك ولم يجنسه ومن إقدامه عن خبرة ولم يعتذر بغرة قوله\n(صرمت وواصلت حتى عرفت ... أين المصادر والمورد)\n(وجربت من ذاك حتى عرفت ... ما أتوقى وما أعمد)\nمن أسره النوم قوله\n(نام صحبي وبات نومي أسيرا ... أرقب النجم موهنا أن يغورا)\nمن غمه الطير قوله\n(فرحنا وقلنا للغلام اقض حاجة ... لنا ثم أدركنا ولا تتغبر)\n(سراعا نغم الطير إن سنحت لنا ... وإن تلقنا الركبان لا نتخبر)\nتغبر من قولهم غبر فلان أي لبث","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":21,"spl":"رجع إلى خبر عمر الطويل لقاء فترحيب فصفاء — الغاية والهدف","partial":1},
{"id":"b2-41","bab":"الجزء 1","sec":"الغاية والهدف","page":"ج1 ص149","text":"(قلت سيرا ولا تقيما ببصرى ... وحفير فما أحب حفيرا)\n(وإذا ما مررتما بمعان ... فأقلا به الثواء وسيرا)\n(إنما قصرنا إذا حسر السير ... بعيرا أن نستجد بعيرا)\nمن تحييره ماء الشباب قوله صوت\n(أبرزوها مثل المهاة تهادى ... بين خمس كواعب أتراب)\n(ثم قالوا تحبها قلت بهرا ... عدد القطر والحصى والتراب)\n(وهي مكنونة تحير منها ... في أديم الخدين ماء الشباب)\nلغناء لمحمد بن عائشة خفيف ثقيل بالبنصر وفيه لمالك خفيف ثقيل آخر عن الهشامي وقيل بل هو هذا ومن تقويله وتسصله قوله\n(قالت على رقبة يوما لجارتها ... ما تأمرين فإن القلب قد تبلا)\n(وهل لي اليوم من أخت مواخية ... منكن أشكو إليها بعض ما فعلا)\n(فراجعتها حصان غير فاحشة ... برجع قول ولب لم يكن خطلا)\n(لا تذكري حبه حتى أراجعه ... إني سأكفيكه إن لم أمت عجلا)\n(فاقنى حياءك في ستر وفي كرم ... فلست أول أنثى علقت رجلا)\nأما ما قاس فيه الهوى فقوله\n(وقربن أسباب الهوى لمتيم ... يقيس ذراعا كلما قسن إصبعا)\nومن عصيانه وإخلائه قوله\n(وأنص المطي يتبعن بالركب ... سراعا نواعم الاظعان)\n(فنصيد الغرير من بقر الوحش ... ونلهو بلذة الفتيان)\n(في زمان لو كنت فيه ضجيعي ... غير شك عرفت لي عصياني)\n(وتقلبت في الفراش ولا تدرين ... إلا الظنون أين مكاني)\nمن مخالفته بسمعه وطرفه قوله\n(سمعي وطرفي حليفاها على جسدي ... فكيف أصبر عن سمعي وعن بصري)\n(لو طاوعاني على ألا أكلمها ... إذا لقضيت من أوطارها وطري)\nمن إبرامه نعت الرسل قوله\n(فبعثت كاتمة الحديث ... رفيقة بجوابها)\n(وحشية إنسية ... خراجة من بابها)\n(فرقت فسهلت المعارض ... من سبيل نقابها)\nمن تحذيره قوله صوت\n(لقد أرسلت جاريتي ... وقلت لها خذي حذرك)\n(وقولي في ملاطفة ... لزينب نولي عمرك)\n(فإن داويت ذا سقم ... فأخزى الله من كفرك)\n(فهزت رأسها عجبا ... وقالت من بذا أمرك)\n(أهذا سحرك النسوان ... قد خبرنني خبرك)\n(وقلن إذا قضى وطرا ... وأدرك حاجة هجرك)\nنى ابن سريج في هذه الأبيات ولحنه خفيف ثقيل ولابن المكي فيها هزج بالوسطى وفيها رمل ذكر ذكاء وجه الرزة عن أحمد بن أبي العلاء عن مخارق أنه لابن جامع وذكر قمري أنه له وأن ذكاء أبطل في هذه الحكاية","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":21,"spl":"رجع إلى خبر عمر الطويل لقاء فترحيب فصفاء — الغاية والهدف"},
{"id":"b2-42","bab":"الجزء 1","sec":"تحذير النساء من رواية شعر عمر","page":"ج1 ص151","text":"قال الزبير حدثني عمي قال حدثني أبي قال قال شيخ من قريش لا ترووا نساءكم شعر عمر بن أبي ربيعة لا يتورطن في الزنا تورطا وأنشد\n(لقد أرسلت جاريتي ... وقلت لها خذي حذرك)\nلأبيات ومن إعلانه الحب وإسراره قوله\n(شكوت إليها الحب أعلن بعضه ... وأخفيت منه في الفؤاد غليلا)\nمما بطن به وأظهر قوله\n(حبكم يا آل ليلى قاتلي ... ظهر الحب بجسمي وبطن)\n(ليس حب فوق ما أحببتكم ... غير أن أقتل نفسي أو أجن)\nمما ألح فيه وأسف قوله\n(ليت حظي كطرفة العين منها ... وكثير منها القليل المهنا)\n(أو حديث على خلاء يسلي ... ما يجن الفؤاد منها ومنا)\n(كبرت رب نعمة منك يوما ... أن أراها قبل الممات ومنا)","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":22,"spl":"تحذير النساء من رواية شعر عمر — عمر ينظر إلى رجل يكلم امرأة في الطواف فيعيب عليه ذلك وينكر"},
{"id":"b2-43","bab":"الجزء 1","sec":"العاشقة المتسللة","page":"ج1 ص152","text":"ومن إنكاحه النوم قوله صوت\n(حتى إذا ما الليل جن ظلامه ... ونظرت غفلة كاشح أن يعقلا)\n(واستنكح النوم الذين نخافهم ... وسقى الكرى بوابهم فاستثقلا)\n(خرجت تأطر في الشباب كأنها ... أيم يسيب على كثيب أهيلا)\nالغناء لمعبد خفيف ثقيل مطلق في مجرى الوسطى عن إسحاق وفيه ألحان لغيره وقد نسبت في غير هذا الموضع مع قوله\n(ودع لبابة قبل أن تترحلا ... )\nمن جنيه الحديث قوله\n(وجوار مساعفات على اللهو ... مسرات باطن الأضغان)\n(صيد للرجال يرشقن بالطرف ... حسان كخذل الغزلان)\n(قد دعاني وقد دعاهن للهو ... شجون مهمة الأشجان)\n(فاجتنينا من الحديث ثمارا ... ما جنى مثلها لعمرك جاني)\nمن ضربه الحديث ظهره لبطنه قوله\n(في خلاء من الأنيس وأمن ... فبثثنا غليلنا واشتفينا)\n(وضربنا الحديث ظهرا لبطن ... وأتينا من أمرنا ما اشتهينا)\n(فمكثنا بذاك عشر ليال ... في قضاء لديننا واقتضينا)\nومن إذلاله صعب الحديث قوله\n(فلمنا أفضنا في الهوى نستبينه ... وعاد لنا صعب الحديث ذلولا)\n(شكوت إليها الحب أظهر بعضه ... وأخفيت منه في الفؤاد غليلا)\nمن قناعته بالرجاء من الوفاء قوله\n(فعدي نائلا وإن لم تنيلي ... إنه ينفع المحب الرجاء)\nال الزبير هذا أحسن من قول كثير\n(ولست براض من خليل بنائل ... قليل ولا أرضى له بقليل)\nمن إعلائه قاتله قوله\n(فبعثت جاريتي وقلت لها اذهبي ... فاشكي إليها ما علمت وسلمي)\n(قولي يقول تحرجي في عاشق ... كلف بكم حتى الممات متيم)","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":22,"spl":"تحذير النساء من رواية شعر عمر — عمر ينظر إلى رجل يكلم امرأة في الطواف فيعيب عليه ذلك وينكر","partial":1},
{"id":"b2-44","bab":"الجزء 1","sec":"الهوى المتجدد","page":"ج1 ص154","text":"(ويقول إنك قد علمت بأنكم ... أصبحتم يا بشر أوجه ذي دم)\n(فكي رهينته فإن لم تفعلي ... فاعلي على قتل ابن عمك واسلمي)\n(فتضاحكت عجبا وقالت حقه ... ألا يعلمنا بما لم نعلم)\n(علمي به والله يغفر ذنبه ... فيما بدا لي ذو هوى متقسم)\n(طرف ينازعه إلى الأدنى الهوى ... ويبت خلة ذي الوصال الأقدم)\nومن تنفيضه النوم قوله\n(فلما فقدت الصوت منهم وأطفئت ... مصابيح شبت بالعشاء وأنور)\n(وغاب قمير كنت أرجو غيوبه ... وروح رعيان ونوم سمر)\n(ونفضت عني النوم أقبلت مشية الحباب ... وركني خشية القوم أزور)\nمن إغلاقه رهن منى وإهداره قتلاه قوله\n(فكم من قتيل ما يباء به دم ... ومن غلق رهنا إذا لفه منى)\n(ومن مالىء عينيه من شيء غيره ... إذا راح نحو الجمرة البيض كالدمى)\nكان بعد هذا كله فصيحا شاعرا مقولا","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":22,"spl":"تحذير النساء من رواية شعر عمر — عمر ينظر إلى رجل يكلم امرأة في الطواف فيعيب عليه ذلك وينكر"},
{"id":"b2-45","bab":"الجزء 1","sec":"عمر ينظر إلى رجل يكلم امرأة في الطواف فيعيب عليه ذلك وينكره","page":"ج1 ص155","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير قال حدثني عمي وأخبرنا به علي بن صالح عن أبي هفان عن إسحاق عن رجاله أن عمر بن أبي ربيعة نظر إلى رجل يكلم امرأة في الطواف فعاب ذلك عليه وأنكره فقال له إنها ابنة عمي قال ذاك أشنع لأمرك فقال إني خطبتها إلى عمي فأبى علي إلا بصداق أربعمائة دينار وأنا غير مطيق ذلك وشكا إليه من حبها وكلفه بها أمرا عظيما وتحمل به على عمه فسار معه إليه فكلمه فقال له هو مملق وليس عندي ما أصلح به أمره فقال له عمر وكم الذي تريده\nمنه قال أربعمائة دينار فقال له هي علي فزوجه ففعل ذلك وقد كان عمر حين أسن حلف ألا يقول بيت شعر إلا أعتق رقبة فانصرف عمر إلى منزله يحدث نفسه فجعلت جارية له تكلمه فلا يرد عليها جوابا فقالت له إن لك لأمرا وأراك تريد أن تقول شعرا فقال صوت\n(تقول وليدتي لما رأتني ... طربت وكنت قد أقصرت حينا)\n(أراك اليوم قد أحدثت شوقا ... وهاج لك الهوى داء دفينا)\n(وكنت زعمت أنك ذو عزاء ... إذا ما شئت فارقت القرينا)","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":22,"spl":"تحذير النساء من رواية شعر عمر — عمر ينظر إلى رجل يكلم امرأة في الطواف فيعيب عليه ذلك وينكر"},
{"id":"b2-46","bab":"الجزء 1","sec":"بعض ما قاله عمر من شعر بعد أن أسن","page":"ج1 ص156","text":"(بربك هل أتاك لها رسول ... فشاقك أم لقيت لها خدينا)\n(فقلت شكا إلي أخ محب ... كبعض زماننا إذ تعلمينا)\n(فقص علي ما يلقى بهند ... فذكر بعض ما كنا نسينا)\n(وذو الشوق القديم وإن تعزى ... مشوق حين يلقى العاشقينا)\n(وكم من خلة أعرضت عنها ... لغير قلى وكنت بها ضنينا)\n(أردت بعادها فصددت عنها ... ولو جن الفؤاد بها جنونا)\nم دعا تسعة من رقيقه فأعتقهم لكل بيت واحد الغناء لابن سريج رمل بالبنصر عن عمرو والهشامي وفيه ثقيل أول يقال إنه للغريض وذكر عبد الله بن موسى أن فيه لدحمان خفيف رمل أخبرني الحرمي قال حدثنا أحمد بن عبيد أبو عصيدة قال ذكر ابن الكلبي أن عمر بن أبي ربيعة كان يساير عروة بن الزبير ويحادثه فقال له وأين زين المواكب يعني ابنه محمد بن عروة وكان يسمى بذلك لجماله فقال له عروة هو أمامك فركض يطلبه فقال له عروة يا أبا الخطاب أولسنا أكفاء كراما لمحادثتك ومسايرتك فقال بلى بأبي أنت وأمي ولكني مغرى بهذا الجمال أتبعه حيث كان ثم التفت إليه وقال\n(إني امرؤ مولع بالحسن اتبعه ... لاحظ لي فيه إلا لذة النظر)\nم مضى حتى لحقه فسار معه وجعل عروة يضحك من كلامه تعجبا منه أخبرني محمد بن خلف بن المرزبان قال حدثنا أحمد بن زهير قال حدثنا\nمصعب بن عبد الله قال رأى عمر بن أبي ربيعة رجلا يطوف بالبيت قد بهر الناس بجماله وتمامه فسأل عنه فقيل له هذا مالك بن أسماء بن خارجة فجاءه فسلم عليه وقال له يابن أخي ما زلت أتشوقك منذ بلغني قولك\n(إن لي عند كل نفحة بستان ... من الورد أو من الياسمينا)\n(نظرة والتفاتة أتمنى ... أن تكوني حللت فيما يلينا)\nيروى\n(أترجى أن تكوني حللت ... )\nمر يتعرض لامرأة أبي الأسود الدؤلي في الطواف أخبرني محمد بن خلف بن المرزبان قال حدثنا عبد الله بن محمد قال حدثنا العباس بن هشام عن أبيه قال أخبرني مولى لزياد قال حج أبو الأسود الدؤلي ومعه امرأته وكانت جميلة فبينا هي تطوف بالبيت إذ عرض لها عمر بن أبي ربيعة فأتت أبا الأسود فأخبرته فأتاه أبو الأسود فعاتبه فقال له عمر ما فعلت شيئا فلما عادت إلى المسجد عاد فكلمها فأخبرت أبا الأسود فأتاه في المسجد وهو مع قوم جالس فقال له\n(وإني ليثنيني عن الجهل والخنا ... وعن شتم أقوام خلائق أربع)\n(حياء وإسلام وبقيا وأنني ... كريم ومثلي قد يضر وينفع)\n(فشتان ما بيني وبينك إنني ... على كل حال أتسقيم وتظلع)\nقال له عمر لست أعود يا عم لكلامها بعد هذا اليوم ثم عاود فكلمها فأتت أبا الأسود فأخبرته فجاء إليه فقال له\n(أنت الفتى وابن الفتى وأخو الفتى ... وسيدنا لولا خلائق أربع)\n(نكول عن الجلى وقرب من الخنا ... وبخل عن الجدوى وأنك تبع)\nم خرجت وخرج معها أبو الأسود مشتملا على سيف فلما رآهما عمر أعرض عنها فتمثل أبو الأسود\n(تعدو الذئاب على من لا كلاب له ... وتتقي صولة المستأسد الحامي)\nخبرني ابن المرزبان قال حدثنا أحمد بن الهيثم الفراسي قال حدثنا العمري قال أخبرنا الهيثم بن عدي قال قدم الفرزدق المدينة وبها رجلان يقال لأحدهما صويم وللآخر ابن أسماء وصفا له فقصدهما وكان عندهما قيان فسلم عليهما وقال لهما من أنتما فقال أحدهما أنا فرعون وقال الآخر أنا هامان قال فأين منزلكما في النار حتى أقصدكما فقالا نحن جيران الفرزدق الشاعر فضحك ونزل فسلم عليهما وسلما عليه وتعاشروا مدة ثم سألهما أن يجمعا بينه وبين عمر بن أبي ربيعة ففعلا واجتمعا وتحادثا وتناشدا إلى أن أنشد عمر قصيدته التي يقول فيها\n(فلما التقينا واطمأنت بنا النوى ... وغيب عنا من نخاف ونشفق)\nتى انتهى إلى قوله","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":23,"spl":"بعض ما قاله عمر من شعر بعد أن أسن — الفرزدق يعترف بأن عمر أغزل الناس","partial":1},
{"id":"b2-47","bab":"الجزء 1","sec":"الفرزدق يعترف بأن عمر أغزل الناس","page":"ج1 ص160","text":"(فقمن لكي يخليننا فترقرقت ... مدامع عينيها وظلت تدفق)\n(وقالت أما ترحمنني لا تدعنني ... لدى غزل جم الصبابة يخرق)\n(فقلن اسكتي عنا فلست مطاعة ... وخلك منا فاعلمي بك أرفق)\nصاح الفرزدق أنت والله يا أبا الخطاب أغزل الناس لا يحسن والله الشعراء أن يقولوا مثل هذا النسيب ولا أن يرقوا مثل هذه الرقية وودعه وانصرف أخبرني الحرمي قال حدثنا الزبير قال حدثني عبد الجبار بن سعيد المساحقي عن المغيرة بن عبد الرحمن عن أبيه أنه حج مع أبيه الحارث بن عبد الله بن عياش بن أبي ربيعة فأتى عمر بن أبي ربيعة وقد أسن وشاخ فسلم عليه وسأله ثم قال له أي شيء أحدثت بعدي يا أبا الخطاب فأنشده","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":23,"spl":"بعض ما قاله عمر من شعر بعد أن أسن — الفرزدق يعترف بأن عمر أغزل الناس"},
{"id":"b2-48","bab":"الجزء 1","sec":"مما قاله عمر في شيخوخته","page":"ج1 ص160","text":"(يقولون إني لست أصدقك الهوى ... وإني لا أرعاك حين أغيب)\n(فما بال طرفي عف عما تساقطت ... له أعين من معشر وقلوب)\n(عشية لا يستنكف القوم أن يروا ... سفاه امرىء ممن يقال لبيب)\n(ولا فتنة من ناسك أومضت له ... بعين الصبا كسلى القيام لعوب)\n(تروح يرجو أن تحط ذنوبه ... فآب وقد زيدت عليه ذنوب)\n(وما النسك أسلاني ولكن للهوى ... على العين مني والفؤاد رقيب)","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":24,"spl":"مما قاله عمر في شيخوخته — عمر ينزل عند عبد الله بن هلال في الكوفة"},
{"id":"b2-49","bab":"الجزء 1","sec":"عمر والكساء والبردين","page":"ج1 ص161","text":"أخبرني هاشم بن محمد الخزاعي قال حدثنا عيسى بن إسماعيل عن القحذمي قال واعد عمر بن أبي ربيعة نسوة من قريش إلى العقيق ليتحدثن معه فخرج إليهن ومعه الغريض فتحدثوا مليا ومطروا فقام عمر والغريض وجاريتان للنسوة فأظلوا عليهن بمطرفه وبردين له حتى استترن من المطر إلى أن سكن ثم انصرفن فقال له الغريض قل في هذا شعرا حتى أغني فيه فقال عمر صوت\n(ألم تسأل المنزل المقفرا ... بيانا فيكتم أو يخبرا)\n(ذكرت به بعض ما قد شجاك ... وحق لذي الشجو أن يذكرا)\n(مقام المحبين قد ظاهرا ... كساء وبردين أن يمطرا)\n(وممشى الثلاث به موهنا ... خرجن إلى زائر زورا)\n(إلى مجلس من وراء القباب ... سهل الربا طيب أعفرا)\n(غفلن عن الليل حتى بدت ... تباشير من واضح أسفرا)\n(فقمن يعفين آثارنا ... بأكسية الخز أن تقفرا)\n(مهاتان شيعتا جؤذرا ... أسيلا مقلده أحورا)\n(وقمن وقلن لو ان النهار ... مد له الليل فاستأخرا)\n(قضينا به بعض أشجاننا ... وكان الحديث به أجدرا)\nكر ابن المكي أن الغناء في الخمسة الأبيات الأولى لابن سريج ثاني ثقيل بالسبابة في مجرى البنصر وذكر الهشامي أن هذا اللحن للغريض وأن لحن ابن سريج رمل بالوسطى قال ولدحمان فيه أيضا ثاني ثقيل آخر بالوسطى وفيها لابن الهربذ خفيف رمل بالسبابة في مجرى الوسطى وقال حبش فيها لمعبد خفيف ثقيل بالوسطى أخبرنا محمد بن خلف بن المرزبان قال حدثني أبو العباس المديني قال أخبرنا ابن عائشة قال حضر ابن أبي عتيق عمر بن أبي ربيعة وهو ينشد قوله\n(ومن كان محزونا بإهراق عبرة ... وهى غربها فليأتنا نبكه غدا)\n(نعنه على الإثكال إن كان ثاكلا ... وإن كان محروبا وإن كان مقصدا)","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":24,"spl":"مما قاله عمر في شيخوخته — عمر ينزل عند عبد الله بن هلال في الكوفة"},
{"id":"b2-50","bab":"الجزء 1","sec":"ابن أبي عتيق وخالد بن عبد الله القسري يأتيان عمر","page":"ج1 ص162","text":"قال فلما أصبح ابن أبي عتيق أخذ معه خالدا الخريت وقال له قم بنا إلى عمر فمضيا إليه فقال له ابن أبي عتيق قد جئناك لموعدك قال وأي موعد بيننا قال قولك فليأتنا نبكه غدا قد جئناك والله لا نبرح أو تبكي إن كنت صادقا في قولك أو ننصرف على أنك غير صادق ثم مضى وتركه قال ابن عائشة خالد الخريت هو خالد بن عبد الله القسري\nأخبرني هاشم بن محمد الخزاعي قال حدثنا دماذ عن الهيثم بن عدي عن عبد الله بن عياش الهمداني قال\nلقيت عمر بن أبي ربيعة فقلت له يا أبا الخطاب أكل ما قلته في شعرك فعلته قال نعم وأستغفر الله","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":24,"spl":"مما قاله عمر في شيخوخته — عمر ينزل عند عبد الله بن هلال في الكوفة"},
{"id":"b2-51","bab":"الجزء 1","sec":"عمر ينزل عند عبد الله بن هلال في الكوفة","page":"ج1 ص163","text":"أخبرني علي بن صالح عن أبي هفان عن إسحاق عن عبد الله بن مصعب قال قدم عمر بن أبي ربيعة الكوفة فنزل على عبد الله بن هلال الذي كان يقال\nله صاحب إبليس وكان له قينتان حاذقتان وكان عمر يأتيهما فيسمع منهما فقال في ذلك\n(يا أهل بابل ما نفست عليكم ... من عيشكم إلا ثلاث خلال)\n(ماء الفرات وطيب ليل بارد ... وغناء مسمعتين لابن هلال)","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":24,"spl":"مما قاله عمر في شيخوخته — عمر ينزل عند عبد الله بن هلال في الكوفة"},
{"id":"b2-52","bab":"الجزء 1","sec":"عمر وبعض الشعراء يصفون البرق","page":"ج1 ص164","text":"أخبرني علي بن صالح عن أبي هفان عن إسحاق عن رجاله أن عمر بن أبي ربيعة والحارث بن خالد وأبا ربيعة المصطلقي ورجلا من بني مخزوم وابن أخت الحارث بن خالد خرجوا يشيعون بعض خلفاء بني أمية فلما انصرفوا نزلوا بسرف فلاح لهم برق فقال الحارث كلنا شاعر فهلموا نصف البرق فقال أبو ربيعة\n(أرقت لبرق آخر الليل لامع ... جرى من سناه ذو الربا فينابع)\nقال الحارث\n(أرقت له ليل التمام ودونه ... مهامه موماة وأرض بلاقع)\nفقال المخزومي\n(يضيء عضاه الشوك حتى كأنه ... مصابيح أو فجر من الصبح ساطع)\nقال عمر\n(أيا رب لا آلو المودة جاهدا ... لأسماء فاصنع بي الذي أنت صانع)\nم قال ما لي وللبرق والشوك","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":25,"spl":"عمر وبعض الشعراء يصفون البرق — عمر يقول الشعر في ليلى البكرية"},
{"id":"b2-53","bab":"الجزء 1","sec":"هند وأسماء وخالد القسري وعمر","page":"ج1 ص164","text":"أخبرني عمي قال حدثنا الكراني قال حدثنا العمري عن الهيثم بن عدي قال كان عمر بن أبي ربيعة وخالد القسري معه وهو خالد الخريت ذات يوم يمشيان فإذا هما بهند وأسماء اللتين كان يشبب بهما عمر بن أبي ربيعة تتماشيان فقصداهما وجلسا معهما مليا فأخذتهم السماء ومطروا ثم ذكر مثل خبر تقدم ورويته آنفا عن هاشم بن محمد الخزاعي وذكر الأبيات الماضية ولم يذكر فيها خبر الغريض وحكى أنه قال في ذلك","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":25,"spl":"عمر وبعض الشعراء يصفون البرق — عمر يقول الشعر في ليلى البكرية"},
{"id":"b2-54","bab":"الجزء 1","sec":"عمر يذكر البرق والمطر والفتاة والكساء","page":"ج1 ص165","text":"صوت\n(أفي رسم دار دمعك المترقرق ... سفاها وما استنطاق ما ليس ينطق)\n(بحيث التقى جمع ومفضى محسر ... مغاني قد كادت على العهد تخلق)\n(ذكرت به ما قد مضى من زماننا ... وذكرك رسم الدار مما يشوق)\n(مقاما لنا عند العشاء ومجلسا ... به لم يكدره علينا معوق)\n(وممشى فتاة بالكساء تكننا ... به تحت عين برقها يتألق)\n(يبل أعالي الثوب قطر وتحته ... شعاع بدا يعشي العيون ويشرق)\n(فأحسن شيء بدء أول ليلنا ... وآخره حزن إذا نتفرق)\nكر يحيى بن المكي أن الغناء في ستة أبيات متوالية من هذا الشعر لمعبد خفيف ثقيل بالسبابة والوسطى وذكر الهشامي أنه من منحول يحيى","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":25,"spl":"عمر وبعض الشعراء يصفون البرق — عمر يقول الشعر في ليلى البكرية"},
{"id":"b2-55","bab":"الجزء 1","sec":"عمر يقول الشعر في ليلى البكرية","page":"ج1 ص166","text":"أخبرنا الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال أخبرني مصعب قال لقي عمر بن أبي ربيعة ليلى بنت الحارث بن عمرو البكرية وهي تسير على بغلة لها وقد كان نسب بها فقال جعلني الله فداك عرجي هاهنا أسمعك بعض ما قلته فيك قالت أوقد فعلت قال نعم فوقفت وقالت هات فأنشدها صوت\n(ألا ياليل إن شفاء نفسي ... نوالك إن بخلت فنولينا)\n(وقد حضر الرحيل وحان منا ... فراقك فانظري ما تأمرينا)\nفقالت آمرك بتقوى الله وإيثار طاعته وترك ما أنت عليه ثم صاحت ببغلتها ومضت وفي هذين البيتين لابن سريج خفيف ثقيل بالوسطى عن يحيى المكي وذكر الهشامي أنه من منحوله إلى ابن سريج وفيهما رمل طنبوري لأحمد بن صدقة","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":25,"spl":"عمر وبعض الشعراء يصفون البرق — عمر يقول الشعر في ليلى البكرية"},
{"id":"b2-56","bab":"الجزء 1","sec":"ليلى بنت الحارث البكرية تعنف عمر لتشبيبه بالنساء","page":"ج1 ص167","text":"أخبرني بذلك جحظة عنه وأخبرني بهذا الخبر عبد الله بن محمد الرازي قال حدثنا أحمد بن الحارث الخراز عن ابن الأعرابي أن ليلى هذه كانت جالسة في المسجد الحرام فرأت عمر بن أبي ربيعة فوجهت إليه مولى لها فجاءها به فقالت له يابن أبي ربيعة حتى متى لا تزال سادرا في حرم الله تشبب بالنساء وتشيد بذكرهن أما تخاف الله قال دعيني من ذاك واسمعي ما قلت قالت ما قلت فأنشدها الأبيات المذكورة فقالت له القول الذي تقدم أنها أجابته به قال وقال لها اسمعي أيضا ما قلت فيك ثم أنشدها قوله\n(أمن الرسم وأطلال الدمن ... عاد لي وجدي وعاودت الحزن)\n(إن حبي آل ليلى قاتلي ... ظهر الحب بجسمي وبطن)\n(يا أبا الحارث قلبي طائر ... فأتمر أمر رشيد مؤتمن)\n(التمس للقلب وصلا عندها ... إن خير الوصل ما ليس يمن)\n(علق القلب وقد كان صحا ... من بني بكر غزالا قد شدن)\n(أحور المقلة كالبدر إذا ... قلد الدر فقلبي ممتحن)\n(ليس حب فوق ما أحببتكم ... غير أن أقتل نفسي أو أجن)\n(خلقت للقلب مني فتنة ... هكذا يخلق معروض الفتن)\nال وفيها يقول\n(إن ليلى وقد بلغت المشيبا ... لم تدع للنساء عندي نصيبا)\n(هاجر بيتها لأنفي عنها ... قول ذي العيب إن أراد عيوبا)","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":26,"spl":"ليلى بنت الحارث البكرية تعنف عمر لتشبيبه بالنساء — عمر يشبب بالنوار"},
{"id":"b2-57","bab":"الجزء 1","sec":"اجتماع المغنين على شعر عمر","page":"ج1 ص168","text":"الغناء في الأبيات الأولى النونية لابن سريج ثاني ثقيل بالوسطى عن عمرو وفيها لابن عائشة ثقيل أول يقال إنه أول ثقيل غناه كان يغني الخفيف فعيب بذلك فصنع هذا اللحن وفيه لعبد الله بن يونس الأبلي رمل عن الهشامي والغناء في\n(إن ليلى وقد بلغت المشيبا ... )\nلابن سريج رمل بالوسطى عن عمر وفيه لكردم ثقيل أول بالوسطى عن عمرو أيضا وذكر إبراهيم أن فيه لحنا لعطرد ولم يجنسه","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":26,"spl":"ليلى بنت الحارث البكرية تعنف عمر لتشبيبه بالنساء — عمر يشبب بالنوار","partialRef":{"sid":"b2-56","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b2-58","bab":"الجزء 1","sec":"عمر يشبب بالنوار","page":"ج1 ص169","text":"أخبرني محمد بن خلف بن المرزبان قال حدثني محمد بن منصور الأزدي قال حدثني أبي عن الهيثم بن عدي قال بينما عمر بن أبي ربيعة منصرف من المزدلفة يريد منى إذ بصر بامرأة في رحالة ففتن وسمع عجوزا معها تناديها يا نوار استتري لا يفضحك ابن أبي ربيعة فاتبعها عمر وقد شغلت قلبه حتى نزلت بمنى في مضرب قد ضرب لها فنزل إلى جنب المضرب ولم يزل يتلطف حتى جلس معها وحادثها وإذا أحسن الناس وجها وأحلاه منطقا فزاد ذلك في إعجاب عمر بها ثم أراد معاودتها فتعذر ذلك عليه وكان آخر عهده فقال فيها صوت\n(علق النوار فؤاده جهلا ... وصبا فلم تترك له عقلا)\n(وتعرضت لي في المسير فما ... أمسى الفؤاد يرى لها مثلا)\n(ما نعجة من وحش ذي بقر ... تغذو بسقط صريمة طفلا)\n(بألذ منها إذ تقول لنا ... وأردت كشف قناعها مهلا)\n(دعنا فإنك لا مكارمة ... تجزي ولست بواصل حبلا)\n(وعليك من تبل الفؤاد وإن ... أمسى لقلبك ذكره شغلا)\n(فأجبتها إن المحب مكلف ... فدعي العتاب وأحدثي بذلا)\nلغناء لابن محرز خفيف ثقيل بالسبابة في مجرى البنصر عن إسحاق وفيه ثاني ثقيل بالبنصر ينسب إلى ابن عائشة","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":26,"spl":"ليلى بنت الحارث البكرية تعنف عمر لتشبيبه بالنساء — عمر يشبب بالنوار"},
{"id":"b2-59","bab":"الجزء 1","sec":"قصة عمر مع أم الحكم الأموية وما قاله فيها من الشعر","page":"ج1 ص170","text":"أخبرني محمد بن خلف قال حدثني أبو عبد الله السدوسي عن عيسى بن إسماعيل العتكي عن هشام بن الكلبي عن أبيه قال\nحجت امرأة من بني أمية يقال لها أم الحكم فقدمت قبل أوان الحج معتمرة فبينا هي تطوف على بغلة لها إذ مرت على عمر بن أبي ربيعة في نفر من بني مخزوم وهم جلوس يتحدثون وقد فرعهم طولا وجهرهم جمالا وبهرهم شارة وعارضة وبيانا فمالت إليهم ونزلت عندهم فتحدثت معهم طويلا ثم انصرفت ولم يزل عمر يتردد إليها إلى أن انقضت أيام الحج فرحلت إلى الشأم وفيها يقول عمر\n(تأوب ليلى بنصب وهم ... وعاودت ذكرى لأم الحكم)\n(فبت أراقب ليل التمام ... من نام من عاشق لم أنم)\n(فإنما تريني على ما عزا ... ضعيف القيام شديد السقم)\n(كثير التقلب فوق الفراش ... ما إن تقل قيامي قدم)\n(بآنسة طيب نشرها ... هضيم الحشا عذبة المبتسم)\nفي أول الأبيات الثلاثة غناء وقبلها وهو أول الصوت صوت\n(وفتيان صدق صباح الوجوه ... لا يجدون لشيء ألم)\n(من آل المغيرة لا يشهدون ... عند المجازر لحم الوضم)\nلغناء في هذه الأبيات لمالك خفيف ثقيل الثاني بالبنصر وهو الذي يقال له الماخوري عن عمرو وفيه ثاني ثقيل ينسب إلى ابن سريج والغريض ودحمان وفيه لابن المكي خفيف رمل رسول سكينة بنت الحسين ( ع\nإلى عمر أخبرني علي بن صالح قال حدثنا أبو هفان عن إسحاق عن أبي عبد الله الزبيري قال اجتمع نسوة من أهل المدينة من أهل الشرف فتذاكرن عمر بن أبي ربيعة وشعره وظرفه وحسن حديثه فتشوقن إليه وتمنينه فقالت سكينة بنت الحسين عليهما السلام أنا لكن به فأرسلت إليه رسولا وواعدته الصورين وسمت له الليلة والوقت وواعدت صواحباتها فوافاهن عمر على راحلته فحدثهن حتى أضاء الفجر وحان انصرافهن فقال لهن والله إني لمحتاج إلى زيارة قبر رسول\nالله والصلاة في مسجده ولكن لا أخلط بزيارتكن شيئا ثم انصرف إلى مكة وقال صوت\n(قالت سكينة والدموع ذوارف ... منها على الخدين والجلباب)\n(ليت المغيري الذي لم أجزه ... فيما أطال تصيدي وطلابي)\n(كانت ترد لنا المنى أيامنا ... إذ لا نلام على هوى وتصابي)\n(خبرت ما قالت فبت كأنما ... ترمي الحشا بنوافذ النشاب)\n(أسكين ما ماء الفرات وطيبه ... مني على ظمأ وفقد شراب)\n(بألذ منك وإن نأيت وقلما ... ترعى النساء أمانة الغياب)\nلغناء للهذلي رمل بالوسطى عن الهشامي وفيه للغريض خفيف ثقيل بالوسطى عن حبش قال وقال فيها","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":27,"spl":"قصة عمر مع أم الحكم الأموية وما قاله فيها من الشعر — عمر يقول الشعر في سكينة"},
{"id":"b2-60","bab":"الجزء 1","sec":"عمر يقول الشعر في سكينة","page":"ج1 ص172","text":"صوت\n(أحب لحبك من لم يكن ... صفيا لنفسي ولا صاحبا)\n(وأبذل نفسي لمرضاتكم ... وأعتب من جاءكم عاتبا)\n(وأرغب في ود من لم أكن ... إلى وده قبلكم راغبا)\n(ولو سلك الناس في جانب ... من الأرض واعتزلت جانبا)\n(ليممت طيتها إنني ... أرى قربها العجب العاجبا)\n(فما نعجة من ظباء الأراك ... تقرو دميث الربا عاشبا)\n(بأحسن منها غداة الغميم ... وقد أبدت الخد والحاجبا)\n(غداة تقول على رقبة ... لخادمها يا احبسي الراكبا)\n(فقالت لها فيم هذا الكلام ... وأبدت لها عابسا قاطبا)\n(فقالت كريم أتى زائرا ... يمر بكم هكذا جانبا)\n(شريف أتى ربعنا زائرا ... فأكره رجعته خائبا)\nنى في الأول والثاني والرابع والخامس من هذه الأبيات ابن القفاص المكي ولحنه رمل من رواية الهشامي وحدثني وكيع وابن المرزبان وعمي قالوا حدثنا عبد الله بن أبي سعد قال حدثنا إبراهيم بن المنذر الحزامي قال حدثنا محمد بن معن الغفاري قال حدثني سفيان بن عيينة قال\nبينا أنا ومسعر بن كدام مع إسماعيل بن أمية بفناء الكعبة إذا بعجوز قد طلعت علينا عوراء متكئة على عصا يصفق أحد لحييها على الآخر فوقفت على إسماعيل فسلمت عليه فرد عليها السلام وسألها فأحفى المسألة ثم انصرفت فقال إسماعيل لا إله إلا الله ماذا تفعل الدنيا بأهلها ثم أقبل علينا فقال أتعرفان هذه قلنا لا والله ومن هي قال هذه بغوم ابن أبي ربيعة التي يقول فيها\n(حبذا أنت يا بغوم وأسماء ... وعيص يكننا وخلاء)\nانظرا كيف صارت وما كان بمكة امرأة أجمل منها قال فقال له مسعر لا ورب هذه البنية ما أرى أنه كان عند هذه خير قط وفي هذه الأبيات يقول عمر","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":27,"spl":"قصة عمر مع أم الحكم الأموية وما قاله فيها من الشعر — عمر يقول الشعر في سكينة"},
{"id":"b2-61","bab":"الجزء 1","sec":"عمر والبغوم وأسماء والرباب","page":"ج1 ص174","text":"صوت\n(صرمت حبلك البغوم وصدت ... عنك في غير ريبة أسماء)\n(والغواني إذا رأينك كهلا ... كان فيهن عن هواك التواء)\n(حبذا أنت يا بغوم وأسما ... ء وعيص يكننا وخلاء)\n(ولقد قلت ليلة الجزل لما ... أخضلت ريطتي علي السماء)\n(ليت شعري وهل يردن ليت ... هل لهذا عند الرباب جزاء)\n(كل وصل أمسى لدي لأنثى ... غيرها وصلها إليها أداء)\n(كل خلق وإن دنا لوصال ... أو نأى فهو للرباب الفداء)\n(فعدي نائلا وإن لم تنيلي ... إنما ينفع المحب الرجاء)\nمعبد في ولقد قلت ليلة الجزل والذي بعده خفيف ثقيل مطلق في مجرى الوسطى عن يونس وإسحاق ودنانير وهو من مشهور غنائه أخبرني الحرمي قال حدثنا الزبير قال حدثتني ظبية مولاة فاطمة بنت عمر بن مصعب عن ذهيبة مولاة محمد بن مصعب بن الزبير قالت","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":28,"spl":"عمر والبغوم وأسماء والرباب — القسم الكاذب"},
{"id":"b2-62","bab":"الجزء 1","sec":"البغوم وأسماء تغنيان لعمر","page":"ج1 ص175","text":"كنت عند أمة الواحد أو أمة المجيد بنت عمر بن أبي ربيعة في الجنبذ الذي في بيت سكينة بنت خالد بن مصعب أنا وأبوها عمر وجاريتان له تغنيان يقال لإحداهما البغوم والأخرى أسماء وكانت أمة المجيد بنت عمر تحت محمد ابن مصعب بن الزبير قالت فقال عمر بن أبي ربيعة وهو معهم في الجنبذ هذه الأبيات فلما انتهى إلى قوله\n(ولقد قلت ليلة الجزل لما ... أخضلت ريطتي علي السماء)\nرجت البغوم ثم رجعت إليه فقالت ما رأيت أكذب منك يا عمر تزعم أنك\nبالجزل وأنت في جنبذ محمد بن مصعب وتزعم أن السماء أخضلت ريطتك وليس في السماء قزعة قال هكذا يستقيم هذا الشأن وأخبرني علي بن صالح عن أبي هفان عن إسحاق عن المسيبي ومحمد بن سلام أن عمر أنشد ابن أبي عتيق قوله\n(حبذا أنت يا بغوم وأسماء ... وعيص يكننا وخلاء)\nقال له ما أبقيت شيئا يتمنى يا أبا الخطاب إلا مرجلا يسخن لكم فيه الماء للغسل أخبرني ابن المرزبان قال حدثني إسماعيل بن جعفر عن محمد بن حبيب عن ابن الأعرابي قال حجت أم محمد بنت مروان بن الحكم فلما قضت نسكها أتت عمر بن أبي ربيعة وقد أخفت نفسها في نسوة فحدثها مليا فلما انصرفت أتبعها عمر رسولا عرف موضعها وسأل عنها حتى أثبتها فعادت إليه بعد ذلك فأخبرها بمعرفته إياها فقالت نشدتك الله أن تشهرني بشعرك وبعثت إليه بألف دينار فقبلها وابتاع بها حللا وطيبا فأهداه إليها فردته فقال لها والله لئن لم تقبليه\nلأنهبنه فيكون مشهورا فقبلته ورحلت فقال فيها صوت\n(أيها الراكب المجد ابتكارا ... قد قضى من تهامة الأوطارا)\n(من يكن قلبه صحيحا سليما ... ففؤادي بالخيف أمسى معارا)\n(ليت ذا الدهر كان حتما علينا ... كل يومين حجة واعتمارا)\nلغناء لابن محرز ولحنه من القدر الأوسط من الثقيل الأول بالخنصر في مجرى الوسطى عن إسحاق وفيه أيضا له خفيف ثقيل بالوسطى عن ابن المكي وفيه لذكاء وجه الرزة المعتمدي ثقيل أول من جيد الغناء وفاخر الصنعة ليس لأحد من طبقته وأهل صنعته مثله وأنشد ابن أبي عتيق قول عمر هذا فقال الله أرحم بعباده أن يجعل عليهم ما سألته ليتم لك فسقك","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":28,"spl":"عمر والبغوم وأسماء والرباب — القسم الكاذب"},
{"id":"b2-63","bab":"الجزء 1","sec":"القسم الكاذب","page":"ج1 ص177","text":"أخبرني ابن المرزبان قال أخبرني أحمد بن يحيى القرشي عن أبي الحسن الأزدي عن جماعة من الرواة أن عمر كان يهوى حميدة جارية ابن تفاحة وفيها يقول صوت\n(حمل القلب من حميدة ثقلا ... إن في ذاك للفؤاد لشغلا)\n(إن فعلت الذي سألت فقولي ... حمد خيرا وأتبعي القول فعلا)\n(وصليني فأشهد الله أني ... لست أصفي سواك ما عشت وصلا)\nالغناء لمعبد خفيف ثقيل بالوسطى عن يحيى المكي والهشامي وفيها يقول صوت\n(يا قلب هل لك عن حميدة زاجر ... أم أنت مدكر الحياء فصابر)\n(فالقلب من ذكرى حميدة موجع ... والدمع منحدر وعظمي فاتر)\n(قد كنت أحسب أنني قبل الذي ... فعلت على ما عند حمدة قادر)\n(حتى بدا لي من حميدة خلتي ... بين وكنت من الفراق أحاذر)\nالغناء لمعبد خفيف ثقيل بالسبابة في مجرى البنصر عن إسحاق","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":28,"spl":"عمر والبغوم وأسماء والرباب — القسم الكاذب"},
{"id":"b2-64","bab":"الجزء 1","sec":"عمر وبعض جواري بني أمية في موسم الحج وما دار بينهم من حديث","page":"ج1 ص178","text":"أخبرني الحسن بن علي الخفاف قال حدثني محمد بن القاسم بن مهرويه قال حدثني أبو مسلم المستملي عن ابن أخي زرقان عن أبيه قال أدركت مولى لعمر بن أبي ربيعة شيخا كبيرا فقلت له حدثني عن عمر بحديث غريب فقال نعم كنت معه ذات يوم فاجتاز به نسوة من جواري بني أمية قد حججن فتعرض لهن وحادثهن وناشدهن مدة أيام حجهن ثم قالت له إحداهن يا أبا الخطاب إنا خارجات في غد فابعث مولاك هذا إلى منزلنا ندفع إليه تذكرة تكون عندك تذكرنا بها فسر بذلك ووجه بي إليهن في السحر\nفوجدتهن يركبن فقلن لعجوز معهن يا فلانة ادفعي إلى مولىأبي الخطاب التذكرة التي أتحفناه بها فأخرجت إلي صندوقا لطيفا مقفلا مختوما فقلن ادفعه إليه وارتحلن فجئته به وأنا أظن أنه قد أودع طيبا أو جوهرا ففتحه عمر فإذا هو مملوء من المضارب وهي الكيرنجات وإذا على كل واحد منها اسم رجل من مجان مكة وفيها اثنان كبيران عظيمان على أحدهما الحارث بن خالد وهو يومئذ أمير مكة وعلى الآخر عمر بن أبي ربيعة فضحك وقال تماجن علي ونفذ لهن ثم أصلح مأدبة ودعا كل واحد ممن له اسم في تلك المضارب فلما أكلوا واطمأنوا للجلوس قال هات يا غلام تلك الوديعة فجئته بالصندوق ففتحه ودفع إلى الحارث الكيرنج الذي عليه اسمه فلما أخذه وكشف عنه غطاءه فرع وقال ما هذا أخزاك الله فقال له رويدا اصبر حتى ترى ثم أخرج واحدا واحدا فدفعه إلى من عليه اسمه حتى فرقها فيهم ثم أخرج الذي باسمه وقال هذا لي فقالوا له ويحك ما هذا فحدثهم بالخبر فعجبوا منه وما زالوا يتمازحون بذلك دهرا طويلا ويضحكون منه","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":29,"spl":"عمر وبعض جواري بني أمية في موسم الحج وما دار بينهم من حديث — حكاية عمر مع البنات اللاتي ين"},
{"id":"b2-65","bab":"الجزء 1","sec":"المرأة التي تأمر تربها بالتصدي لعمر في طوافه","page":"ج1 ص179","text":"قال وحدثني هذا المولى قال كنت مع عمر وقد أسن وضعف فخرج يوما يمشي متوكئا على يدي حتى مر بعجوز جالسة فقال لي هذه فلانة وكانت إلفا\nلي وعدل إليها فسلم عليها وجلس عندها وجعل يحادثها ثم قال هذه التي أقول فيها صوت\n(أبصرتها ليلة ونسوتها ... يمشين بين المقام والحجر)\n(بيضا حسانا نواعما قطفا ... يمشين هونا كمشية البقر)\n(قالت لترب لها تلاطفها ... لنفسدن الطواف في عمر)\n(قومي تصدي له ليعرفنا ... ثم اغمزيه يا أخت في خفر)\n(قالت لها قد غمزته فأبى ... ثم اسبطرت تشتد في أثري)\n(بل يا خليلي عادني ذكري ... بل اعترتني الهموم بالسهر)\nلغناء لابن سريج في السادس والأول والثاني خفيف ثقيل بالوسطى عن عمرو وفيها لسنان الكاتب رمل بالوسطى عنه وعن يونس وفيه للأبجر خفيف رمل بالوسطى عنه وفي\nقالت لترب لها تلاطفها\nعبد الله بن العباس خفيف رمل بالبنصر عن الهشامي وفيه للدلال خفيف ثقيل عنه أيضا ولأبي سعيد مولى فائد في الأول والثاني ثقيل أول عن الهشامي أيضا ومن الناس من ينسب لحنه إلى سنان الكاتب وينسب لحن سنان إليه","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":29,"spl":"عمر وبعض جواري بني أمية في موسم الحج وما دار بينهم من حديث — حكاية عمر مع البنات اللاتي ين"},
{"id":"b2-66","bab":"الجزء 1","sec":"حكاية عمر مع البنات اللاتي ينظرن إليه من ثقب المضرب","page":"ج1 ص180","text":"قال وجلس معها يحادثها فأطلعت رأسها إلى البيت وقالت يا بناتي هذا أبو الخطاب عمر بن أبي ربيعة عندي فإن كنتن تشتهين أن ترينه فتعالين فجئن إلى مضرب قد حجزن به دون بابها فجعلن يثقبنه ويضعن أعينهن عليه يبصرن فاستسقاها عمر فقالت له أي الشراب أحب إليك قال الماء فأتي بإناء فيه ماء فشرب منه ثم ملأ فمه فمجه عليهن في وجوههن من وراء الحاجز فصاح الجواري وتهاربن وجعلن يضحكن فقالت له العجوز ويلك لا تدع مجونك وسفهك مع هذه السن فقال لا تلوميني فما ملكت نفسي لما سمعت من حركاتهن أن فعلت ما رأيت","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":29,"spl":"عمر وبعض جواري بني أمية في موسم الحج وما دار بينهم من حديث — حكاية عمر مع البنات اللاتي ين"},
{"id":"b2-67","bab":"الجزء 1","sec":"عمر يرتحل إلى العراق في طلب امرأة رآها في الطواف ثم يعود خائبا","page":"ج1 ص181","text":"أخبرني محمد بن خلف بن المرزبان قال حدثني أحمد بن منصور بن أبي العلاء الهمداني قال حدثني علي بن طريف الأسدي قال سمعت أبي يقول بينما عمر بن أبي ربيعة يطوف بالبيت إذ رأى امرأة من أهل العراق فأعجبه جمالها فمشى معها حتى عرف موضعها ثم أتاها فحادثها وناشدها وناشدته وخطبها فقالت إن هذا لا يصلح هاهنا ولكن إن جئتني إلى بلدي وخطبتني إلى أهلي تزوجتك فلما ارتحلوا جاء إلى صديق له من بني سهم وقال له إن لي إليك حاجة أريد أن تساعدني عليها فقال له نعم فأخذ بيده ولم يذكر له ما هي ثم أتى منزله فركب نجيبا له وأركبه نجيبا آخر وأخذ معه ما يصلحه\nوسارا لا يشك السهمي في أنه يريد سفر يوم أو يومين فما زال يحفد حتى لحق بالرفقة ثم سار بسيرهم يحادث المرأة طول طريقه ويسايرها وينزل عندها إذا نزلت حتى ورد العراق فأقام أياما ثم راسلها يتنجزها وعدها فأعلمته أنها كانت متزوجة ابن عم لها وولدت منه أولادا ثم مات وأوصى بهم وبماله إليها ما لم تتزوج وأنها تخاف فرقة أولادها وزوال النعمة وبعثت إليه بخمسة آلاف درهم واعتذرت فردها عليها ورحل إلى مكة وقال في ذلك قصيدته التي أولها صوت\n(نام صحبي ولم أنم ... من خيال بنا ألم)\n(طاف بالركب موهنا ... بين خاخ إلى إضم)\n(ثم نبهت صاحبا ... طيب الخيم والشيم)\n(أريحيا مساعدا ... غير نكس ولا برم)\n(قلت يا عمرو شفني ... لاعج الحب والألم)\n(إيت هندا فقل لها ... ليلة الخيف ذي السلم)\nلغناء لمالك خفيف رمل بالسبابة في مجرى الوسطى عن إسحاق ويونس وفيه لعبد الله بن العباس الربيعي خفيف رمل من رواية عمرو بن بانة وذكر حبش أن لحن عبد الله بن العباس رمل آخر عن الهشامي","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":30,"spl":"عمر يرتحل إلى العراق في طلب امرأة رآها في الطواف ثم يعود خائبا — حنين عمر إلى الماضي"},
{"id":"b2-68","bab":"الجزء 1","sec":"جرير يشهد لعمر بالشعر","page":"ج1 ص182","text":"أخبرني محمد بن خلف قال حدثنا الحسين بن إسماعيل عن ابن عائشة عن أبيه قال كان جرير إذا أنشد شعر عمر بن أبي ربيعة قال شعر تهامي إذا أنجد وجد البرد حتى أنشد قوله\n(رأت رجلا أما إذا الشمس عارضت ... فيضحى وأما بالعشي فيخصر)\nلأبيات فقال مازال هذا يهذي حتى قال الشعر","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":30,"spl":"عمر يرتحل إلى العراق في طلب امرأة رآها في الطواف ثم يعود خائبا — حنين عمر إلى الماضي"},
{"id":"b2-69","bab":"الجزء 1","sec":"حنين عمر إلى الماضي","page":"ج1 ص183","text":"أخبرني حبيب بن نصر المهلبي قال حدثنا الزبير بن بكار قال حدثني عمي عن عثمان بن إبراهيم الخاطبي وأخبرني به محمد بن خلف بن المرزبان قال حدثني إسحاق بن إبراهيم عن محمد بن أبان قال أخبرني العتبي عن أبي زيد الزبيري عن عثمان بن إبراهيم الخاطبي قال أتيت عمر بن أبي ربيعة بعد أن نسك بسنين وهو في مجلس قومه من بني\nمخزوم فانتظرت حتى تفرق القوم ثم دنوت منه ومعي صاحب لي ظريف وكان قد قال لي تعال حتى نهيجه على ذكر الغزل فننظر هل بقي في نفسه منه شيء فقال له صاحبي يا أبا الخطاب أكرمك الله لقد أحسن العذري وأجاد فيما قال فنظر عمر إليه ثم قال له وماذا قال قال حيث يقول\n(لو جد بالسيف رأسي في مودتها ... لمر يهوي سريعا نحوها راسي)\nال فارتاح عمر إلى قوله وقال هاه لقد أجاد وأحسن فقلت ولله در جنادة العذري فقال عمر حيث يقول ماذا ويحك فقلت حيث يقول\n(سرت لعينك سلمى بعد مغفاها ... فبت مستنبها من بعد مسراها)\n(وقلت أهلا وسهلا من هداك لنا ... إن كنت تمثالها أو كنت إياها)\n(من حبها أتمنى أن يلاقيني ... من نحو بلدتها ناع فينعاها)\n(كيما أقول فراق لا لقاء له ... وتضمر النفس يأسا ثم تسلاها)\n(ولو تموت لراعتني وقلت ألا ... يا بؤس للموت ليت الموت أبقاها)\nال فضحك عمر ثم قال وأبيك لقد أحسن وأجاد وما أبقى ولقد هيجتما علي ساكنا وذكرتماني ما كان عني غائبا ولأحدثنكما حديثا حلوا","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":30,"spl":"عمر يرتحل إلى العراق في طلب امرأة رآها في الطواف ثم يعود خائبا — حنين عمر إلى الماضي"},
{"id":"b2-70","bab":"الجزء 1","sec":"عمر يجتمع متنكرا مع هند بنت الحارث المرية ورفيقاتها","page":"ج1 ص184","text":"بينا أنا منذ أعوام جالس إذ أتاني خالد الخريت فقال لي يا أبا الخطاب مرت بي أربع نسوة قبيل العشاء يردن موضع كذا وكذا لم أر مثلهن في بدو ولا\nحضر فيهن هند بنت الحارث المرية فهل لك أن تأتيهن متنكرا فتسمع من حديثهن وتتمتع بالنظر إليهن ولا يعلمن من أنت فقلت له ويحك وكيف لي أن أخفي نفسي قال تلبس لبسة أعرابي ثم تجلس على قعود ثم ائتهن فسلم عليهن فلا يشعرن إلا بك قد هجمت عليهن ففعلت ما قال وجلست على قعود ثم أتيتهن فسلمت عليهن ثم وقفت بقربهن فسألنني أن أنشدهن وأحدثهن فأنشدتهن لكثير وجميل والأحوص ونصيب وغيرهم فقلن لي ويحك يا أعرابي ما أملحك وأظرفك لو نزلت فتحدثت معنا يومنا هذا فإذا أمسيت انصرفت في حفظ الله قال فأنخت بعيري ثم تحدثت معهن وأنشدتهن فسررن بي وجذلن بقربي وأعجبهن حديثي قال ثم إنهن تغامزن وجعل بعضهن يقول لبعض كأنا نعرف هذا الأعرابي ما أشبهه بعمر بن أبي ربيعة فقالت إحداهن فهو والله عمر فمدت هند يدها فانتزعت عمامتي فألقتها عن رأسي ثم قالت لي هيه يا عمر أتراك خدعتنا منذ اليوم بل نحن والله خدعناك واحتلنا عليك بخالد فأرسلناه إليك لتأتينا في أسوإ هيئة ونحن كما ترى قال عمر ثم أخذنا في الحديث فقالت هند ويحك يا عمر اسمع مني لو رأيتني منذ أيام وأصبحت عند أهلي فأدخلت رأسي في جيبي فنظرت إلى حري فإذا هو ملء الكف ومنية المتمني فناديت يا عمراه يا عمراه قال عمر فصحت يا لبيكاه يا لبيكاه ثلاثا ومددت في الثالثة صوتي فضحكت وحادثتهن ساعة ثم ودعتهن وانصرفت فذلك قولي\nصوت\n(عرفت مصيف الحي والمتربعا ... ببطن حليات دوارس بلقعا)\n(إلى السفح من وادي المغمس بدلت ... معالمه وبلا ونكباء زعزعا)\n(لهند وأتراب لهند إذ الهوى ... جميع وإذ لم نخش أن يتصدعا)\n(وإذ نحن مثل الماء كان مزاجه ... كما صفق الساقي الرحيق المشعشعا)\n(وإذ لا نطيع الكاشحين ولا نرى ... لواش لدينا يطلب الصرم موضعا)\nلغناء للغريض ثاني ثقيل بالوسطى عن الهشامي ومن نسخة عمرو الثانية وفيه لابن جامع وابن عباد لحنان من كتاب إبراهيم وفيها يقول وفيه غناء صوت\n(فلما تواقفنا وسلمت أشرقت ... وجوه زهاها الحسن أن تتقنعا)\n(تبالهن بالعرفان لما رأينني ... وقلن امرؤ باغ أكل وأوضعا)\n(وقربن أسباب الهوى لمتيم ... يقيس ذراعا كلما قسن إصبعا)\nلغناء لابن عباد رمل عن الهشامي وفيه لابن جامع لحن من كتاب إبراهيم غير مجنس هذه الأبيات مقرونة بالأولى والصنعة في جميعها مختلفة يغني المغنون بعض هذه وبعض تلك ويخلطونهما والصنعة لمن قدمت ذكره وهي قصيدة طويلة ذكرت منها ما فيه صنعة\nومما قاله في هند هذه وغني فيه قوله صوت\n(ألم تسأل الأطلال والمنزل الخلق ... ببرقة ذي ضال فيخبر إن نطق)\n(ذكرت به هندا فظلت كأنني ... أخو نشوة لاقى الحوانيت فاغتبق)\nلغناء لعطرد ولحنه من القدر الأوسط من الثقيل الأول بالخنصر في مجرى البنصر عن إسحاق وفيه لمعبد ثقيل أول بالوسطى عن الهشامي وذكر حبش أن فيه للغريض ثاني ثقيل بالوسطى ومنها","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":31,"spl":"عمر يجتمع متنكرا مع هند بنت الحارث المرية ورفيقاتها"},
{"id":"b2-71","bab":"الجزء 1","sec":"من بديع شعره في هند","page":"ج1 ص187","text":"صوت\n(أصبح القلب مهيضا ... راجع الحب الغريضا)\n(وأجد الشوق وهنا ... أن رأى برقا وميضا)\n(ثم بات الركب نواما ... ولم أطعم غموضا)\n(ذاك من هند قديما ... تركها القلب مهيضا)\n(وتبدت ثم أبدت ... واضح اللون نحيضا)\n(وعذاب الطعم غرا ... كأقاحي الرمل بيضا)\nلغناء لابن محرز خفيف ثقيل بالسبابة في مجرى البنصر وفيه لحكم هزج بالوسطى عن عمرو وقيل إنه يمان ومن الناس من ينسب لحن ابن محرز إلى ابن مسجح ومنها صوت\n(أربت إلى هند وتربين مرة ... لها إذ تواقفنا بفرع المقطع)\n(لتعريج يوم أو لتعريس ليلة ... علينا بجمع الشمل قبل التصدع)\n(فقلن لها لولا ارتقاب صحابة ... لنا خلفنا عجنا ولم نتورع)\n(وقالت فتاة كنت أحسب أنها ... مغفلة في مئزر لم تدرع)\n(لهن وما شاورنها ليس ما أرى ... بحسن جزاء للحبيب المودع)\n(فقلن لها لا شب قرنك فافتحي ... لنا باب ما يخفى من الأمر نسمع)\nهي أبيات الغناء للغريض ولحنه من القدر الأوسط من الثقيل الأول بالخنصر في مجرى البنصر عن إسحاق وذكر ابن المكي أنه لابن سريج ومنها صوت\n(لما ألمت بأصحابي وقد هجعوا ... حسبت وسط رحال القوم عطارا)\n(فقلت من ذا المحيي وانتبهت له ... ومن محدثنا هذا الذي زارا)\n(ألا انزلوا نعمت دار بقربكم ... أهلا وسهلا بكم من زائر زارا)\n(فبدل الربع ممن كان يسكنه ... عفر الظباء به يمشين أسطارا)\nلغناء لابن سريج رمل بالخنصر في مجرى البنصر عن إسحاق وفيه ليونس خفيف ثقيل وفيه لأبي فارة هزج بالنبصر وأول هذه القصيدة التي فيها ذكر هند قوله","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":32,"spl":"من بديع شعره في هند — هند التي لا شبيه لها"},
{"id":"b2-72","bab":"الجزء 1","sec":"هند التي لا شبيه لها","page":"ج1 ص190","text":"(يا صاحبي قفا نستخبر الدارا ... أقوت وهاجت لنا بالنعف تذكارا)\n(وقد أرى مرة سربا بها حسنا ... مثل الجآذر لم يمسسن أبكارا)\n(فيهن هند وهند لا شبيه لها ... فيمن أقام من الأحياء أو سارا)\n(تقول ليت أبا الخطاب وافقنا ... كي نلهو اليوم أو ننشد أشعارا)\n(فلم يرعهن إلا العيس طالعة ... بالقوم يحملن ركبانا وأكوارا)\n(وفارس يحمل البازي فقلن لها ... هاهم أولاء وما أكثرن إكثارا)\n(لما وقفنا وعننا ركائبنا ... بدلن بالعرف بعد الرجع إنكارا)\nمنها صوت\n(الم تربع على الطلل ... ومغنى الحي كالخلل)\n(لهند إن هندا حبها ... قد كان من شغلي)\n(فلما أن عرفت الدار ... عجت لرسمها جملي)\n(وقلت لصحبتي عوجوا ... فعاجوا هزة الإبل)\n(وقالوا قف ولا تعجل ... وإن كنا على عجل)\n(قليل في هواك اليوم ... ما تلقى من العمل)\nلغناء لابن سريج ثاني ثقيل مطلق في مجرى الوسطى عن إسحاق وفيه له أيضا رمل عن الهشامي وحبش ومنها صوت\n(هاج ذا القلب منزل ... بالبليين محول)\n(غيرت آيه الصبا ... وجنوب وشمأل)\n(إن هندا قد ارسلت ... وأخو الشوق مرسل)\n(أرسلت تستحثني ... وتفدي وتعذل)\n(أينا بات ليله ... بين غصنين يوبل)\n(تحت عين يكننا ... برد عصب مهلهل)\nفي هذه الأبيات خفيف ثقيل مطلق في مجرى البنصر ذكر إسحاق أنه لمالك وذكر عمرو أنه لابن محرز وذكر يونس أن فيها لحنا لابن محرز ولحنا لمالك وقال عمر في نسخته الثانية أنه لابن زرزر الطائفي خفيف ثقيل بالوسطى وروت مثل ذلك دنانير عن فليح وفيها لابن سريج رمل بالسبابة في مجرى البنصر عن إسحاق وفيها لعبد الله بن موسى الهادي ثاني ثقيل من مجموعة ورواية الهشامي وفيه لحكم هزج بالخنصر والبنصر عن ابن المكي وفيه للحجبي رمل عن الهشامي وفيه ثقيل أول نسبه ابن المكي إلى ابن محرز وذكر الهشامي أنه منحول وفيه خفيف رمل ذكر الهشامي أنه لحن ابن محرز ومنها صوت\n(يا صاح هل تدري وقد جمدت عيني ... بما ألقى من الوجد)\n(لما رأيت ديارها درست ... وتبدلت اعلامها بعدي)\n(وذكرت مجلسها ومجلسنا ... ذات العشاء بمهبط النجد)\n(ورسالة منها تعاتبني ... فرددت معتبة على هند)\nالغناء ليحيى المكي رمل بالوسطى وفيه لغيره ألحان أخر ومنها","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":32,"spl":"من بديع شعره في هند — هند التي لا شبيه لها"},
{"id":"b2-73","bab":"الجزء 1","sec":"عمر يتغزل بهند","page":"ج1 ص193","text":"صوت\n(ليت هندا أنجزتنا ما تعد ... وشفت أنفسنا مما تجد)\n(واستبدت مرة واحدة ... إنما العاجز من لا يستبد)\n(ولقد قالت لجارات لها ... ذات يوم وتعرت تبترد)\nيروى\n(زعموها سألت جاراتها ... )\n(أكما ينعتني تبصرنني ... عمركن الله أم لا يقتصد)\n(فتضاحكن وقد قلن لها ... حسن في كل عين من تود)\n(حسدا حملنه من أجلها ... وقديما كان في الناس الحسد)\nلغناء لابن سريج رمل بالخنصر في مجرى البنصر عن إسحاق وفيه لحن لمالك من كتاب يونس غير مجنس وفيه لابن سريج خفيف رمل بالبنصر عن\nعمرو وذكره إسحاق في خفيف الثقيل بالخنصر في مجرى البنصر ولم ينسبه إلى أحد وفيه ثاني ثقيل يقال إنه لحن لمالك ويقال إنه لمتيم ومنها صوت\n(هاج القريض الذكر ... لما غدوا فانشمروا)\n(على بغال شحج قد ضمهن السفر ... )\n(فيهن هند ليتني ... ما عمرت أعمر)\n(حتى إذا ما جاءها ... حتف أتاني القدر)\nابن سريج فيه لحنان رمل مطلق في مجرى البنصر عن إسحاق وخفيف رمل عن الهشامي ومنها صوت\n(يا من لقلب دنف مغرم ... هام إلى هند ولم يظلم)\n(هام إلى ريم هضيم الحشا ... عذب الثنايا طيب المبسم)\n(لم أحسب الشمس بليل بدت ... قبلي لذي لحم ولا ذي دم)\n(قالت ألا إنك ذو ملة ... يصرفك الأدنى عن الأقدم)\n(قلت لها بل أنت معتلة ... في الوصل يا هند لكي تصرمي)\nلغناء لابن سريج رمل بالسبابة في مجرى الوسطى عن إسحاق وفيه لبديح لحن قديم وقيل إن فيه رملا آخر لعمارة مولاة عبد الله بن جعفر ومنها","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":33,"spl":"عمر يتغزل بهند — الحب المقيم","partial":1},
{"id":"b2-74","bab":"الجزء 1","sec":"الحب المقيم","page":"ج1 ص195","text":"صوت\n(تصابى وما بعض التصابي بطائل ... وعاود من هند جوى غير زائل)\n(عشية قالت صدعت غربة النوى ... فما من تلاق قد أرى دون قابل)\n(وما أنس م الأشياء لا أنس مجلسا ... لنا مرة منها بقرن المنازل)\n(بنخلة بين النخلتين يكننا ... من العين عند العين برد المراجل)\nلغناء للغريض ثقيل أول بالبنصر عن عمرو وفيه للعماني خفيف ثقيل عن دنانير والهشامي ومنها صوت\n(لج قلبي في التصابي ... وازدهى عني شبابي)\n(ودعاني لهوى هند ... فواد غير نابي)\n(قلت لما فاضت العينان ... دمعا ذا انسكاب)\n(إن جفتني اليوم هند ... بعد ود واقتراب)\n(فسبيل الناس طرا ... لفناء وذهاب)\nلغناء لأهل مكة رمل بالوسطى","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":33,"spl":"عمر يتغزل بهند — الحب المقيم"},
{"id":"b2-75","bab":"الجزء 1","sec":"عمر وفاطمة بنت عبد الملك بن مروان","page":"ج1 ص196","text":"أخبرني محمد بن خلف بن المرزبان قال حدثني أبو علي الأسدي وهو بشر بن موسى بن صالح قال حدثني أبي موسى بن صالح عن أبي بكر القرشي قال كان عمر بن أبي ربيعة جالسا بمنى في فناء مضربه وغلمانه حوله إذ أقبلت امرأة برزة عليها أثر النعمة فسلمت فرد عل يها عمر السلام فقالت له أنت عمر بن أبي ربيعة فقالت لها أنا هو فما حاجتك قالت له حياك الله وقربك هل لك في محادثة أحسن الناس وجها وأتمهم خلقا وأكملهم أدبا وأشرفهم حسبا قال ما أحب إلي ذلك قالت على شرط قال قولي قالت تمكنني من عينيك حتى أشدهما وأقودك حتى إذا توسطت الموضع الذي أريد حللت الشد ثم أفعل ذلك بك عند إخراجك حتى انتهي بك إلى مضربك قال\nشأنك ففعلت ذلك به قال عمر فلما انتهت بي إلى المضرب الذي أرادت كشفت عن وجهي فإذا أنا بامرأة على كرسي لم أر مثلها قط جمالا وكمالا فسلمت وجلست فقالت أأنت عمر بن أبي ربيعة قلت أنا عمر قالت أنت الفاضح للحرائر قلت وما ذاك جعلني الله فداءك قالت ألست القائل صوت\n(قالت وعيش أخي ونعمة والدي ... لأنبهن الحي إن لم تخرج)\n(فخرجت خوف يمينها فتبسمت ... فعلمت أن يمينها لم تحرج)\n(فتناولت رأسي لتعرف مسه ... بمخضب الأطراف غير مشنج)\n(فلثمت فاها آخذا بقرونها ... شرب النزيف ببرد ماء الحشرج)\nلغناء لمعبد ثقيل أول بالبنصر عن يونس وعمرو ثم قالت قم فاخرج عني ثم قامت من مجلسها وجاءت المرأة فشدت عيني ثم أخرجتني حتى انتهت بي إلى مضربي وانصرفت وتركتني فحللت\nعيني وقد دخلني من الكآبة والحزن ما الله به أعلم وبت ليلتي فلما أصبحت إذا أنا بها فقالت هل لك في العود فقلت شأنك ففعلت بي مثل فعلها بالأمس حتى انتهت بي إلى الموضع فلما دخلت إذا بتلك الفتاة على كرسي فقالت إيه يا فضاح الحرائر قلت بماذا جعلني الله فداءك قالت بقولك صوت\n(وناهدة الثديين قلت لها اتكي ... على الرمل من جبانة لم توسد)\n(فقالت على اسم الله أمرك طاعة ... وإن كنت قد كلفت ما لم أعود)\n(فلما دنا الإصباح قالت فضحتني ... فقم غير مطرود وإن شئت فازدد)\nلغناء لأهل مكة ثقيل أول عن الهشامي ثم قالت قم فاخرج عني فقمت فخرجت ثم رددت فقالت لي لولا وشك الرحيل وخوف الفوت ومحبتي لمناجاتك والاستكثار من محادثتك لأقصيتك هات الآن كلمني وحدثني وأنشدني فكلمت آدب الناس وأعلمهم بكل شيء ثم نهضت وأبطأت العجوز وخلا لي البيت فأخذت أنظر فإذا أنا بتور فيه خلوق فأدخلت يدي فيه ثم خبأتها\nفي ردني وجاءت تلك العجوز فشدت عيني ونهضت بي تقودني حتى إذا صرت على باب المضرب أخرجت يدي فضربت بها على المضرب ثم صرت إلى مضربي فدعوت غلماني فقلت أيكم يقفني على باب مضرب عليه خلوق كأنه أثر كف فهو حر وله خمسائمة درهم فلم ألبث أن جاء بعضهم فقال قم فنهضت معه فإذا أنا بالكف طرية وإذا المضرب مضرب فاطمة بنت عبد الملك ابن مروان فأخذت في أهبة الرحيل فلما نفرت نفرت معها فبصرت في طريقها بقباب ومضرب وهيئة جميلة فسألت عن ذلك فقيل لها هذا عمر بن أبي ربيعة فساءها أمره وقالت للعجوز التي كانت ترسلها إليه قولي له نشدتك الله والرحم أن تصحبني ويحك ما شأنك وما الذي تريد انصرف ولا تفضحني وتشيط بدمك فسارت العجوز إليه فأدت إليه ما قالت لها فاطمة فقال لست بمنصرف أو توجه إلي بقميصها الذي يلي جلدها فأخبرتها ففعلت ووجهت إليه بقميص من ثيابها فزاده ذلك شغفا ولم يزل يتبعهم لا يخالطهم حتى إذا صاروا على أميال من دمشق انصرف وقال في ذلك\n(ضاق الغداة بحاجتي صدري ... ويئست بعد تقارب الأمر)\n(وذكرت فاطمة التي علقتها ... عرضا فيا لحوادث الدهر)\nفي هذه القصيدة مما يغنى فيه قوله\nصوت\n(ممكورة ردع العبير بها ... جم العظام لطيفة الخصر)\n(وكأن فاها عند رقدتها ... تجري عليه سلافة الخمر)\nلغناء لإبراهيم بن المهدي ثاني ثقيل من جامعه وفيه لمتيم رمل من جامعها أيضا وتمام الأبيات وليست فيه صنعة\n(فسبت فؤادي إذ عرضت لها ... يوم الرحيل بساحة القصر)\n(بمزين ردع العبير به ... حسن الترائب واضح النحر)\n(وبجيد آدم شادن خرق ... يرعى الرياض ببلدة قفر)\n(لما رأيت مطيها حزقا ... خفق الفؤاد وكنت ذا صبر)\n(وتبادرت عيناي بعدهم ... وانهل دمعهما على ا لصدر)\n(ولقد عصيت ذوي القرابة فيكم ... طرا وأهل الود والصهر)\n(حتى لقد قالوا وما كذبوا ... أجننت أم بك داخل السحر)","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":34,"spl":"عمر وفاطمة بنت عبد الملك بن مروان"},
{"id":"b2-76","bab":"الجزء 1","sec":"عمر وفاطمة بنت عبد الملك بن مروان","page":"ج1 ص196","text":"أخبرنا محمد بن خلف بن المرزبان قال حدثني إسحاق عن محمد بن أبان قال حدثني الوليد بن هشام القحذمي عن أبي معاذ القرشي قال لما قدمت فاطمة بنت عبد الملك بن مروان مكة جعل عمر بن أبي ربيعة يدور حولها ويقول فيها الشعر ولا يذكرها باسمها فرقا من عبد الملك بن مروان ومن الحجاج لأنه كان كتب إليه يتوعده إن ذكرها أو عرض باسمها فلما قضت حجها وارتحلت أنشأ يقول صوت\n(كدت يوم الرحيل أقضي حياتي ... ليتني مت قبل يوم الرحيل)\n(لا أطيق الكلام من شدة الخوف ... ودمعي يسيل كل مسيل)\n(ذرفت عينها وفاضت دموعي ... وكلانا يلقى بلب أصيل)\n(لو خلت خلتي أصبت نوالا ... أو حديثا يشفي من التنويل)\n(ولظل الخلخال فوق الحشايا ... مثل أثناء حية مقتول)\n(فلقد قالت الحبيبة لولا ... كثرة الناس جدت بالتقبيل)\nنى فيه ابن محرز ولحنه ثقيل أول من أصوات قليلة الأشباه عن إسحاق وفيه لعبادل خفيف ثقيل بالبنصر عن عمرو ويقال إنه للهذلي وفيه لعبيد الله بن أبي غسان ثاني ثقيل عن الهشامي أخبرني محمد بن خلف بن المرزبان قال أخبرني أبو علي الحسن بن لصباح عن محمد بن حبيب أنه أخبره أن عمر بن أبي ربيعة قال في فاطمة بنت عبد الملك بن مروان\nصوت\n(يا خليلي شفني الذكر ... وحمول الحي إذ صدروا)\n(ضربوا حمر القباب لها ... وأديرت حولها الحجر)\n(سلكوا شعب النقاب بها ... زمرا تحتثها زمر)\n(وطرقت الحي مكتتما ... ومعي عضب به أثر)\n(وأخ لم أخش نبوته ... بنواحي أمرهم خبر)\n(فإذا ريم على فرش ... في حجال الخز مختدر)\n(حوله الأحراس ترقبه ... نوم من طول ما سهروا)\n(شبه القتلى وما قتلوا ... ذاك إلا أنهم سمروا)\n(فدعت بالويل ثم دعت ... حرة من شأنها الخفر)\n(ثم قالت للتي معها ... ويح نفسي قد أتى عمر)\n(ما له قد جاء يطرقنا ... ويرى الأعداء قد حضروا)\n(لشقائي كان علقنا ... ولحيني ساقه القدر)\n(قلت عرضي دون عرضكم ... ولمن ناواكم الحجر)\nذا البيت الأخير مما فيه غناء مع\n(وطرقت الحي مكتتما ... )\nلغريض وفي\n(يا خليلي شفني الذكر ... )\nفي\n(قلت عرضي دون عرضكم ... )\nفي\n(ثم قالت للتي معها ... )\nفي\n(ما له قد جاء يطرقنا ... )\nاني ثقيل بالوسطى عن عمرو وفي\n(ضربوا حمر القباب لها ... )\nما بعده أربعة متوالية خفيف رمل بالوسطى للهذلي\nوفي وطرقت وبعده فإذا ريم وبعده حوله الأحراس والبيتين اللذين بعده لابن سريج خفيف ثقيل بالوسطى عن عمرو وفيها بعينها ثقيل أول يقال إنه للأبجر وينسب إلى غيره عن الهشامي أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال أخبرني عبد الملك بن عبد العزيز عن رجل من قريش قال بينا عمر بن أبي ربيعة يطوف بالبيت إذ رأى عائشة بنت طلحة بن عبيد الله وكانت من أجمل أهل دهرها وهي تريد الركن تستلمه فبهت لما رآها ورأته وعلمت أنها قد وقعت في نفسه فبعثت إليه بجارية لها وقالت قولي له اتق الله ولا تقل هجرا فإن هذا مقام لا بد فيه مما رأيت فقال للجارية أقرئيها السلام وقولي لها ابن عمك لا يقول إلا خيرا وقال فيها صوت\n(لعائشة ابنة التيمي عندي ... حمى في القلب ما يرعى حماها)\n(يذكرني ابنة التيمي ظبي ... يرود بروضة سهل رباها)\n(فقلت له وكاد يراع قلبي ... فلم أر قط كاليوم اشتباها)\n(سوى حمش بساقك مستبين ... وأن شواك لم يشبه شواها)\n(وأنك عاطل عار وليست ... بعارية ولا عطل يداها)\n(وأنك غير أفرع وهي تدلي ... على المتنين أسحم قد كساها)\n(ولو قعدت ولم تكلف بود ... سوى ما قد كلفت به كفاها)\n(أظل إذا أكلمها كأني ... أكلم حية غلبت رقاها)\n(تبيت إلي بعد النوم تسري ... وقد أمسيت لا أخشى سراها)\nلغناء في البيتين الأولين من هذه الأبيات لأبي فارة ثقيل أول وفيهما لعبد الله بن العباس الربيعي خفيف ثقيل جميعا عن الهشامي وذكر إسحاق أن هذا الصوت مما ينسب إلى معبد وهو يشبه غناءه إلا أنه لم يروه عن ثبت ولم يذكر طريقته قال وقال فيها أشعارا كثيرة فبلغ ذلك فتيان بني تيم أبلغهم إياه فتى منهم وقال لهم يا بني تيم من مرة هالله ليقذفن بنو مخزوم بناتنا بالعظائم وتغفلون فمشى ولد أبي بكر وولد طلحة بن عبيد الله إلى عمر بن أبي ربيعة فأعلموه بذلك وأخبروه بما بلغهم فقال لهم والله لا أذكرها في شعر أبدا ثم قال بعد ذلك فيها وكنى عن اسمها قصيدته التي أولها صوت","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":35,"spl":"عمر وفاطمة بنت عبد الملك بن مروان","partial":1},
{"id":"b2-77","bab":"الجزء 1","sec":"عمر وفاطمة بنت عبد الملك بن مروان","page":"ج1 ص196","text":"(يا أم طلحة إن البين قد أفدا ... قل الثواء لئن كان الرحيل غدا)\n(أمسى العراقي لا يدري إذا برزت ... من ذا تطوف بالأركان أو سجدا)\nلغناء لمعبد ثقيل أول بالبنصر عن عمرو ويونس قال ولم يزل عمر ينسب بعائشة أيام الحج ويطوف حولها ويتعرض لها وهي تكره أن يرى وجهها حتى وافقها وهي ترمي الجمار سافرة فنظر إليها فقالت أما والله لقد كنت لهذا منك كارهة يا فاسق فقال\nصوت\n(إني وأول ما كلفت بذكرها ... عجب وهل في الحب من متعجب)\n(نعت النساء فقلت لست بمبصر ... شبها لها أبدا ولا بمقرب)\n(فمكثن حينا ثم قلن توجهت ... للحج موعدها لقاء الأخشب)\n(أقبلت أنظر ما زعمن وقلن لي ... والقلب بين مصدق ومكذب)\n(فلقيتها تمشي تهادى موهنا ... ترمي الجمار عشية في موكب)\n(غراء يعشي الناظرين بياضها ... حوراء في غلواء عيش معجب)\n(إن التي من أرضها وسمائها ... جلبت لحينك ليتها لم تجلب)\nالغناء لمعبد في الأول والثاني والرابع والسابع ثقيل أول بالوسطى عن عمرو وفيها للغريض خفيف ثقيل عن الهشامي يبدأ فيه بالثالث أخبرني علي بن صالح قال حدثنا أبو هفان عن إسحاق قال أخبرني مصعب الزبيري أن عمر بن أبي ربيعة لقي عائشة بنت طلحة بمكة وهي تسير على بغلة لها فقال لها قفي حتى أسمعك ما قلت فيك قالت أوقد قلت يا فاسق قال نعم فوقفت فأنشدها صوت\n(يا ربة البغلة الشهباء هل لك في ... أن تنشري ميتا لا ترهقي حرجا)\nيروى\n(هل لكم ... في عاشق دنف)\n(قالت بدائك مت أو عش تعالجه ... فما نرى لك فيما عندنا فرجا)\n(قد كنت حملتنا غيظا نعالجه ... فإن تقدنا فقد عنيتنا حججا)\n(حتى لو أستطيع مما قد فعلت بنا ... أكلت لحمك من غيظ وما نضجا)\nلغناء لابن سريج ثقيل أول مطلق في مجرى البنصر عن إسحاق وفيه لابن سريج ثلاثة ألحان ذكرها إسحاق ولم يجنس منها إلا واحدا وذكر الهشامي أن أحدها خفيف رمل بالوسطى وذكر عمرو أن الثالث هزج بالوسطى ولإسحاق فيها هزج من مجموع صنعته فقالت لا ورب هذه البنية ما عنيتنا طرفة عين قط ثم قالت لبغلتها عدس وسارت وتمام هذه الأبيات\n(فقلت لا والذي حج الحجيج له ... ما مح حبك من قلبي ولا نهجا)\n(ولا رأى القلب من شيء يسر به ... مذ بان منزلكم منا ولا ثلجا)\n(ضنت بنائلها عنه فقد تركت ... في غير ذنب أبا الخطاب مختلجا)\nال فلم تزل عائشة تداريه وترفق به خوفا من أن يتعرض لها حتى قضت حجها وانصرفت إلى المدينة فقال في ذلك\n(إن من تهوى مع الفجر ظعن ... للهوى والقلب متباع الوطن)\n(بانت الشمس وكانت كلما ... ذكرت للقلب عاودت الددن)\nصوت\n(يا أبا الحارث قلبي طائر ... فأتمر أمر رشيد مؤتمن)\n(نظرت عيني إليها نظرة ... تركت قلبي لديها مرتهن)\n(ليس حب فوق ما أحببتها ... غير أن أقتل نفسي أو أجن)\nيها ثاني ثقيل بالوسطى نسبه عمرو بن بانة إلى ابن سريج ونسبه ابن المكي إلى الغريض وفيها رمل لأهل مكة ومما يغنى فيه من أشعاره في عائشة بنت طلحة قوله في قصيدته التي أولها صوت\n(من لقلب أمسى رهينا معنى ... مستكينا قد شفه ما أجنا)\n(إثر شخص نفسي فدت ذاك شخصا ... نازح الدار بالمدينة عنا)\n(ليت حظي كطرفة العين منها ... وكثير منها القليل المهنا)\nلغناء لإبراهيم خفيف ثقيل بالسبابة في مجرى البنصر عن إسحاق أخبرني الحسن بن علي الخفاف ومحمد بن خلف قالا حدثنا محمد بن زكريا الغلابي قال حدثني محمد بن عبد الرحمن التيمي عن هشام بن سليمان بن عكرمة بن خالد المخزومي قال كان عمر بن أبي ربيعة يهوى كلثم بنت سعد المخزومية فأرسل إليها رسولا فضربتها وحلقتها وأحلفتها ألا تعاود ثم أعادها ثانية ففعلت بها مثل ذلك فتحاماها رسله فابتاع أمة سوداء لطيفة رقيقة وأتى بها إلى منزله فأحسن إليها وكساها وآنسها وعرفها خبره وقال لها إن أوصلت لي رقعة إلى كثلم فقرأتها فأنت حرة ولك","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":36,"spl":"عمر وفاطمة بنت عبد الملك بن مروان"},
{"id":"b2-78","bab":"الجزء 1","sec":"عمر وفاطمة بنت عبد الملك بن مروان","page":"ج1 ص196","text":"معيشتك ما بقيت فقالت اكتب لي مكاتبة واكتب حاجتك في آخرها ففعل ذلك فأخذتها ومضت بها إلى باب كلثم فاستأذنت فخرجت إليها أمة لها فسألتها عن أمرها فقالت مكاتبة لبعض أهل مولاتك جئت أستعينها في مكاتبتي وحادثتها وناشدتها حتى ملأت قلبها فدخلت إلى كلثم وقالت إن بالباب مكاتبة لم أر قط أجمل منها ولا أكمل ولا آدب فقالت ائذني لها فدخلت فقالت من كاتبك قالت عمر بن أبي ربيعة الفاسق فاقرئي مكاتبتي فمدت يدها لتأخذها فقالت لها لي عليك عهد الله أن تقرئيها فإن كان منك إلى شيء مما أحبه وإلا لم يلحقني منك مكروه فعاهدتها وفطنت وأعطتها الكتاب فإذا أوله\n(من عاشق صب يسر الهوى ... قد شفه الوجد إلى كلثم)\n(رأتك عيني فدعاني الهوى ... إليك للحين ولم أعلم)\n(قتلتنا يا حبذا أنتم ... في غير ما جرم ولا مأثم)\n(والله قد أنزل في وحيه ... مبينا في آيه المحكم)\n(من يقتل النفس كذا ظالما ... ولم يقدها نفسه يظلم)\n(وأنت ثأري فتلافي دمي ... ثم اجعليه نعمة تنعمي)\n(وحكمي عدلا يكن بيننا ... أو أنت فيما بيننا فاحكمي)\n(وجالسيني مجلسا واحدا ... من غير ما عار ولا محرم)\n(وخبريني ما الذي عندكم ... بالله في قتل امرئ مسلم)\nقال فلما قرأت الشعر قالت لها إنه خداع ملق وليس لما شكاه أصل قالت يا مولاتي فما عليك من امتحانه قالت قد أذنت له وما زال حتى ظفر ببغيته فقولي له إذا كان المساء فليجلس في موضع كذا وكذا حتى يأتيه رسولي فانصرفت الجارية فأخبرته فتأهب لها فلما جاءه رسولها مضى معه حتى دخل إليها وقد تهيأت أجمل هيئة وزينت نفسها ومجلسها وجلست له من وراء ستر فسلم وجلس فتركته حتى سكن ثم قالت له أخبرني عنك يا فاسق ألست القائل\n(هلا استحيت فترحمي صبا ... صديان لم تدعي له قلبا)\n(جشم الزيارة في مودتكم ... وأراد ألا ترهقي ذنبا)\n(ورجا مصالحة فكان لكم ... سلما وكنت ترينه حربا)\n(يا أيها المعطي مودته ... من لا يراك مساميا خطبا)\n(لا تجعلن أحدا عليك إذا ... أحببته وهويته ربا)\n(وصل الحبيب إذا شغفت به ... واطو الزيارة دونه غبا)\n(فلذاك أحسن من مواظبة ... ليست تزيدك عنده قربا)\n(لا بل يملك عند دعوته ... فيقول هاه وطالما لبى)\nقال لها جعلت فداك إن القلب إذا هوي نطق اللسان بما يهوى فمكث عندها شهرا لا يدري أهله أين هو ثم استأذنها في الخروج فقالت له بعد أن فضحتني لا والله لا تخرج إلا بعد أن تتزوجني ففعل وتزوجها فولدت منه ابنين أحدهما جوان وماتت عنده\nأخبرني حبيب بن نصر المهلبي قال حدثنا الزبير بن بكار قال حدثني عبد الجبار بن سعيد قال حدثني إبراهيم بن يعقوب بن أبي عبد الله عن أبيه عن جده أن عمر رأى لبابة بنت عبد الله بن العباس امرأة الوليد بن عتبة بن أبي سفيان تطوف بالبيت فرأى أحسن خلق الله فكاد عقله يذهب فسأل عنها فأخبر بنسبها فنسب بها وقال فيها صوت\n(ودع لبابة قبل أن تترحلا ... واسأل فإن قلاله أن تسألا)\n(إلبث بعمرك ساعة وتأنها ... فلعل ما بخلت به أن يبذلا)\n(قال ائتمر ما شئت غير مخالف ... فيما هويت فإننا لن نعجلا)\n(لسنا نبالي حين تقضي حاجة ... ما بات أو ظل المطي معقلا)\n(حتى إذا ما الليل جن ظلامه ... ورقبت غفلة كاشح أن يمحلا)\n(خرجت تأطر في الثياب كأنها ... أيم يسيب على كثيب أهيلا)\n(رحبت حين رأيتها فتبسمت ... لتحيتي لما رأتني مقبلا)\n(وجلا القناع سحابة مشهورة ... غراء تعشي الطرف أن يتأملا)\n(فلبثت أرقيها بما لو عاقل ... يرقى به ما اسطاع ألا ينزلا)\nغنى في هذه الأبيات معبد خفيف ثقيل مطلق في مجرى الوسطى عن إسحاق ابتداؤه نشيد وفيها لابن سريج ثقيل أول بالوسطى في مجراها عن إسحاق أيضا وفيها لابن سريج في الأول والرابع من الأبيات رمل عن ابن المكي ولابي دلف القاسم بن عيسى في هذين البيتين خفيف ثقيل بالسبابة والبنصر وابتداؤه نشيد من رواية ابن المكي وفيه لمحمد بن الحسن بن مصعب هزج أخبرني محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه قال لما حج الغمر بن يزيد بن عبد الملك دخل إليه معبد فغناه\n(ودع لبابة قبل أن تترحلا ... )","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":37,"spl":"عمر وفاطمة بنت عبد الملك بن مروان","partialRef":{"sid":"b2-43","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b2-79","bab":"الجزء 1","sec":"عمر وفاطمة بنت عبد الملك بن مروان","page":"ج1 ص196","text":"لم يزل يردده عليه ثم أخرجه معه لما رحل عن المدينة فغناه في المنزل به حتى أراد الرحيل فحمله على بغلة له وذهب غلام له يتبعه فقال إلى أين فقال أمضي معه حتى أجيء بالبغلة فقال هيهات ارجع يا بني ذهبت والله لبابة ببغلة مولاك وقد روي هذا الخبر لغير الغمر بن يزيد","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":38,"spl":"عمر وفاطمة بنت عبد الملك بن مروان — نسب الثريا بنت علي"},
{"id":"b2-80","bab":"الجزء 1","sec":"نسب الثريا بنت علي","page":"ج1 ص212","text":"وهذه الأبيات التي فيها الغناء المختار وهو\n(تشكى الكميت الجري لما جهدته ... )\nقولها عمر بن أبي ربيعة في الثريا بنت علي بن عبد الله بن الحارث بن أمية\nالأصغر بن عبد شمس بن عبد مناف وهم الذين يقال لهم العبلات سموا بذلك لجدة لهم يقال لها عبلة بنت عبيد بن خالد بن خازل بن قيس بن مالك بن حنظلة ابن مالك بن زيد مناة بن تميم وهي من بطن من تميم يقال لهم البراجم غير براجم بني أسد أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال كانت عبلة بنت عبيد بن خالد بن خازل بن قيس بن حنظلة عند رجل من بني جشم بن معاوية فبعثها بأنحاء سمن تبيعها له بعكاظ فباعت السمن وراحلتين كان عليهما وشربت بثمنها الخمر فلما نفد ثمنها رهنت ابن أخيه وهربت فطلقها وقالت في شربها الخمر\n(شربت براحلتي محجن ... فيا ويلتي محجن قاتلي)\n(وبابن أخيه على لذة ... ولم أحتفل عذل العاذل)\nال فتزوجها عبد شمس بن عبد مناف فولدت له أمية الأصغر وعبد أمية ونوفلا وهم العبلات وقد ذكر الزبير بن بكار عن عمه أن الثريا بنت عبد الله بن محمد بن عبد الله بن الحارث بن أمية الأصغر وأنها أخت محمد بن عبد الله المعروف بأبي جراب العبلي الذي قتله داود بن علي وهو الذي يقول فيه ابن زياد المكي\n(ثلاث حوائج ولهن جئنا ... فقم فيهن يابن أبي جراب)\n(فإنك ماجد في بيت مجد ... بقية معشر تحت التراب)\nقال وله يقول ابن زياد المكي أيضا\n(إذا مت لم توصل بعرف قرابة ... ولم يبق في الدنيا رجاء لسائل)\nقال الزبير وهذا أشبه من أن تكون بنت عبد الله بن الحارث وعبد الله إنما أدرك سلطان معاوية وهو شيخ كبير وورث بقعدده في النسب دار عبد شمس ابن عبد مناف وحج معاوية في خلافته فجعل ينظر إلى الدار فخرج إليه عبد الله بن الحارث بمحجن ليضربه به وقال لا أشبع الله بطنك أما تكفيك الخلافة حتى تطلب هذه الدار فخرج معاوية يضحك قال مؤلف هذا الكتاب وهذا غلط من الزبير عندي والثريا أن تكون بنت عبد الله بن الحارث أشبه من أن تكون أخت الذي قتله داود بن علي لأنها ربت الغريض المغني وعلمته النوح بالمراثي على من قتله يزيد بن معاوية من أهلها يوم الحرة وإذا كانت قد ربت الغريض حتى كبر وتعلم النوح على قتلى الحرة وهو رجل وهي وقعة كانت بعقب موت معاوية فقد كانت في حياة معاوية امرأة كبيرة وبين ذلك وبين من قتله داود بن علي من بني أمية نحو ثمانين سنة وقد شبب بها عمر بن أبي ربيعة في حياة معاوية وأنشد عبد الله بن عباس شعره فيها فكيف تكون أخت الذي قتله داود بن علي وقد أدركت عبد الله بن عباس وهي امرأة كبيرة وقد اعترف الزبير أيضا في خبره بأن عبد الله بن الحارث أدرك خلافة معاوية وهو شيخ كبير فقول من قال إنها بنته أصوب من قول من قرنها بمن قتله داود بن علي وهذا القول الذي قلته قول ابن الكلبي وأبي اليقظان\nأخبرني به الحسن بن علي عن أحمد بن الحارث عن المدائني عن أبي اليقظان قال وحدثني به جماعة من أهل العلم بنسب قريش","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":38,"spl":"عمر وفاطمة بنت عبد الملك بن مروان — نسب الثريا بنت علي","partialRef":{"sid":"b1-1","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b2-81","bab":"الجزء 1","sec":"الثريا تختبر عمر في مدى حبه إياها","page":"ج1 ص215","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني مسلمة ابن إبراهيم بن هشام المخزومي عن أيوب بن مسلمة أنه أخبره أن عمر بن أبي ربيعة كان مسهبا بالثريا بنت علي بن عبد الله بن الحارث بن أمية الأصغر وكانت عرضة ذلك جمالا وتماما وكانت تصيف بالطائف وكان عمر يغدو عليها كل غداة إذا كانت بالطائف على فرسه فيسأل الركبان الذين يحملون الفاكهة من الطائف عن الأخبار قبلهم فلقي يوما بعضهم فسأله عن أخبارهم فقال ما استطرفنا خبرا إلا أنني سمعت عند رحيلنا صوتا وصياحا عاليا على امرأة من قريش اسمها اسم نجم في السماء وقد سقط عني اسمه فقال عمر الثريا قال نعم وقد كان بلغ عمر قبل ذلك أنها عليلة فوجه فرسه على وجهه إلى الطائف يركضه ملء فروجه وسلك طريق كداء وهي أخشن الطرق وأقربها حتى انتهى إلى الثريا وقد توقعته وهي تتشوف له وتشرف فوجدها سليمة عميمة ومعها أختاها رضيا وأم عثمان فأخبرها الخبر فضحكت وقالت أنا والله أمرتهم لأختبر مالي عندك فقال عمر في ذلك هذا الشعر\n(تشكى الكميت الجري لما جهدته ... وبين لو يسطيع أن يتكلما)\n(فقلت له إن ألق للعين قرة ... فهان علي أن تكل وتسأما)\n(لذلك أدني دون خيلي رباطه ... وأوصي به ألا يهان ويكرما)\n(عدمت إذا وفري وفارقت مهجتي ... لئن لم أقل قرنا إن الله سلما)\nال مسلمة بن إبراهيم قلت لأيوب بن مسلمة أكانت الثريا كما يصف عمر بن أبي ربيعة فقال وفوق الصفة كانت والله كما قال عبد الله بن قيس\n(حبذا الحج والثريا ومن بالخيف ... من أجلها وملقى الرحال)\n(يا سليمان إن تلاق الثريا ... تلق عيش الخلود قبل الهلال)\n(درة من عقائل البحر بكر ... لم تشنها مثاقب اللآل)\n(تعقد المئزر السخام من الخز ... على حقو بادن مكسال)","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":39,"spl":"الثريا تختبر عمر في مدى حبه إياها — شعر عمر في رملة الخزاعية"},
{"id":"b2-82","bab":"الجزء 1","sec":"شعر عمر في رملة الخزاعية","page":"ج1 ص216","text":"قال إسحاق في خبره عمن أسند إليه أخبار عمر بن أبي ربيعة وذكر مثله الزبير بن بكار فيما حدثنا به عنه الحرمي بن أبي العلاء قال حدثني مؤمن بن عمر ابن أفلح مولى فاطمة بنت الوليد بن عبد شمس بن المغيرة بن عبد الله بن عمر ابن مخزوم قال حدثني بلال مولى ابن أبي عتيق أن الحارث بن عبد الله بن عياش بن أبي ربيعة قدم للحج فأتاه ابن أبي عتيق\nفسلم عليه وأنا معه فلما قضى سلامه ومساءلته عن حجه وسفره قال له كيف تركت أبا الخطاب عمر بن أبي ربيعة قال تركته في بلهنية من العيش قال وأنى ذلك قال حجت رملة بنت عبد الله بن خلف الخزاعية فقال فيها صوت\n(أصبح القلب في الحبال رهينا ... مقصدا يوم فارق الظاعنينا)\n(قلت من أنتم فصدت وقالت ... أمبد سؤالك العالمينا)\n(نحن من ساكني العراق وكنا ... قبله قاطنين مكة حينا)\n(قد صدقناك إذ سألت فمن أنت ... عسى أن يجر شأن شؤونا)\n(ونرى أننا عرفناك بالنعت ... بظن وما قتلنا يقينا)\n(بسواد الثنيتين ونعت ... قد نراه لناظر مستبينا)","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":39,"spl":"الثريا تختبر عمر في مدى حبه إياها — شعر عمر في رملة الخزاعية"},
{"id":"b2-83","bab":"الجزء 1","sec":"هجران الثريا عمر بعد أن بلغها شعره في رملة","page":"ج1 ص217","text":"غنى معبد في البيتين الأولين خفيف ثقيل أول بالوسطى في مجراها عن إسحاق وغنى في الثاني وما بعده ابن سريج خفيف ثقيل أول بالسبابة في مجرى البنصر عنه أيضا وذكر حبش أن فيه للغريض أيضا لحنا من الثقيل الأول بالبنصر قال فبلغ ذلك الثريا بلغتها إياه أم نوفل وكانت غضبى عليه وقد كان انتشر خبره عن الثريا حتى بلغها من جهة أم نوفل وأنشدتها قوله\n(أصبح القلب في الحبال رهينا ... مقصدا يوم فارق الظاعنينا)\nفقالت إنه لوقاح صنع بلسانه ولئن سلمت له لأردن من شأوه ولأثنين من عنانه ولأعرفنه نفسه فلما بلغت إلى قوله\n(قلت من أنتم فصدت وقالت ... أمبد سؤالك العالمينا)\nقالت إنه لسأل ملح قبحا له ولقد أجابته إن وفت فلما بلغت إلى قوله\n(نحن من ساكني العراق وكنا ... قلبه قاطنين مكة حينا)\nالت غمزته الجهمة فلما بلغت إلى قوله\n(قد صدقناك إذ سألت فمن أنت ... عسى أن يجر شأن شؤونا)\nقالت رمته الورهاء بآخر ما عندها في مقام واحد وهجرت عمر أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عمي مصعب أن رملة بنت عبد الله بن خلف حجت فتعرض لها عمر بن أبي ربيعة فقال فيها\n(أصبح القلب في الحبال رهينا ... مقصدا يوم فارق الظاعنينا)\nقال في هذه القصيدة\n(فرأت حرصي الفتاة فقالت ... خبريه من أجل من تكتمينا)\n(نحن من ساكني العراق وكنا ... قلبه قاطنين مكة حينا)\n(قد صدقناك إذ سألت فمن أنت ... عسى أن يجر شأن شؤونا)\nقال الزبير ورملة هذه أم طلحة بن عمر بن عبيد الله بن معمر التيمي وهي أخت طلحة الطلحات بن عبد الله بن خلف الخزاعي","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":40,"spl":"هجران الثريا عمر بعد أن بلغها شعره في رملة — ابن أبي عتيق يسعى للصلح بين عمر والثريا"},
{"id":"b2-84","bab":"الجزء 1","sec":"كثير يغضب إثر سماعه شعر عمر في رملة","page":"ج1 ص219","text":"قال فبلغت هذه الأبيات كثيرا فغضب لذلك وقال وأنا والله لا أتمارى أن سيجر شأن شؤونا ثم ذكر نسوة من قريش فساقهن في شعره من الحج حتى بلغ بهن إلى ملل ثم أشفق فجاز ولم يزد على ذلك وهو قوله في قصيدته التي أولها\n(ما عناك الغداة من أطلال ... دارسات المقام مذ أحوال)\nصوت\n(قم تأمل فأنت أبصر مني ... هل ترى بالغميم من أجمال)\n(قاضيات لبانة من مناخ ... وطواف وموقف بالجبال)\n(قلن عسفان ثم رحن سراعا ... هابطات عشية من غزال)\n(واردات الكديد مجترعات ... جزن وادي الحجون بالأثقال)\n(قصد لفت وهن متسقات ... كالعدولي لاحقات التوالي)\n(طالعات الغميس من عبود ... سالكات الخوي من أملال)\n(فسقى الله منتوى أم عمرو ... حيث أمت بها صدور الرحال)\n(حبذا هن من لبانة قلبي ... وجديد الشباب من سربالي)\n(رب يوم أتيتهن جميعا ... عند بيضاء رخصة مكسال)\n(غير أني امرؤ تعممت حلما ... يكره الجهل والصبا أمثالي)\nغنى ابن سريج في الثلاثة الأبيات الأول خفيف ثقيل بالوسطى عن عمرو ويونس وذكر الهشامي أن فيها للحجبي رملا بالبنصر قالوا فلما هجرت الثريا عمر قال في ذلك\n(من رسولي إلى الثريا فإني ... ضقت ذرعا بهجرها والكتاب)","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":40,"spl":"هجران الثريا عمر بعد أن بلغها شعره في رملة — ابن أبي عتيق يسعى للصلح بين عمر والثريا"},
{"id":"b2-85","bab":"الجزء 1","sec":"ابن أبي عتيق يسعى للصلح بين عمر والثريا","page":"ج1 ص220","text":"فبلغ ابن أبي عتيق قوله فمضى حتى أصلح بينهما وهذه الأبيات تذكر مع ما فيها من الغناء ومع خبر إصلاح ابن أبي عتيق بينهما بعد انقضاء خبر رملة التي ذكرها عمر في شعره قال مصعب بن عبد الله في خبره وكانت رملة جهمة الوجه عظيمة الأنف حسنة الجسم وتزوجها عمر بن عبيد الله بن معمر وتزوج عائشة بنت طلحة بن عبيد الله وجمع بينهما فقال يوما لعائشة فعلت في محاربة الخوارج\nمع أبي فديك كذا وصنعت كذا يذكر له شجاعته وإقدامه فقالت له عائشة أنا أعلم أنك أشجع الناس وأعرف لك يوما هو أعظم من هذا اليوم الذي ذكرته قال وما هو قالت يوم اجتليت رملة وأقدمت على وجهها وأنفها قال مصعب وحدثني يعقوب بن إسحاق قال لما بلغ الثريا قول عمر بن أبي ربيعة في رملة\n(وجلا بردها وقد حسرته ... نور بدر يضيء للناظرينا)\nالت أف له ما أكذبه أو ترتفع حسناء بصفته لها بعد رملة","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":40,"spl":"هجران الثريا عمر بعد أن بلغها شعره في رملة — ابن أبي عتيق يسعى للصلح بين عمر والثريا"},
{"id":"b2-86","bab":"الجزء 1","sec":"خبر عمر مع المرأة الجمحية","page":"ج1 ص221","text":"وذكر ابن أبي حسان عن الرياشي عن العباس بن بكار عن ابن دأب أن هذا الشعر قاله عمر في امرأة من بني جمح كان أبوها من أهل مكة فولدت له جارية لم يولد مثلها بالحجاز حسنا فقال أبوها كأني بها وقد كبرت فشبب بها عمر بن أبي ربيعة وفضحها ونوه باسمها كما فعل بنساء قريش والله لا أقمت بمكة فباع ضيعة له بالطائف ومكة ورحل بابنته إلى البصرة فأقام بها وابتاع هناك ضيعة ونشأت ابنته من أجمل نساء زمانها ومات أبوها فلم تر أحدا من بني جمح حضر جنازته ولا وجدت لها مسعدا ولا عليها داخلا فقالت لداية لها سوداء من نحن ومن أي البلاد نحن فخبرتها فقالت لا جرم والله لا أقمت في هذا\nالبلد الذي أنا فيه غريبة فباعت الضيعة والدار وخرجت في أيام الحج وكان عمر يقدم فيعتمر في ذي القعدة ويحل ويلبس تلك الحلل والوشي ويركب النجائب المخضوبة بالحناء عليها القطوع والديباج ويسبل لمته ويلقى العراقيات فيما بينه وبين ذات عرق محرمات ويتلقى المدنيات إلى مر ويتلقى الشاميات إلى الكديد فخرج يوما للعراقيات فإذا قبة مكشوفة فيها جارية كأنها القمر تعادلها جارية سوداء كالسبجة فقال للسوداء من أنت ومن أين أنت يا خالة فقالت لقد أطال الله تعبك إن كنت تسأل هذا العالم من هم ومن أين هم قال فأخبريني عسى أن يكون لذلك شأن قالت نحن من أهل العراق فأما الأصل والمنشأ فمكة وقد رجعنا إلى الأصل ورحلنا إلى بلدنا فضحك فلما نظرت إلى سواد ثنيتيه قالت قد عرفناك قال ومن أنا قالت عمر بن أبي ربيعة قال وبم عرفتني قالت بسواد ثنيتيك وبهيئتك التي ليست إلا لقريش فأنشأ يقول\n(قلت من أنتم فصدت وقالت ... أمبد سؤالك العالمينا)\nذكر الأبيات فلم يزل عمر بها حتى تزوجها وولدت له قال فلما صرمت الثريا عمر قال فيها صوت\n(من رسولي إلى الثريا فإني ... ضقت ذرعا بهجرها والكتاب)\n(سلبتني مجاجة المسك عقلي ... فسلوها ماذا أحل اغتصابي)\n(وهي مكنونة تحير منها ... في أديم الخدين ماء الشباب)\n(أبرزوها مثل المهاة تهادى ... بين خمس كواعب أتراب)\n(ثم قالوا تحبها قلت بهرا ... عدد القطر والحصى والتراب)\nلغناء لابن عائشة خفيف ثقيل أول بالبنصر عن عمرو وذكر حبش أنه لمالك","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":41,"spl":"خبر عمر مع المرأة الجمحية"},
{"id":"b2-87","bab":"الجزء 1","sec":"نجاح الصلح الذي سعى به ابن أبي عتيق","page":"ج1 ص223","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني مؤمن بن عمر بن أفلح مولى فاطمة بنت الوليد قال أخبرني بلال مولى ابن أبي عتيق قال أنشد ابن أبي عتيق قول عمر\n(من رسولي إلى الثريا فإني ... ضقت ذرعا بهجرها والكتاب)\nفقال ابن أبي عتيق إياي أراد وبي نوه لا جرم والله لا أذوق أكلا حتى أشخص فأصلح بينهما ونهض ونهضت معه فجاء إلى قوم من بني الديل بن بكر لم تكن تفارقهم نجائب لهم فره يكرهونها فاكترى منهم راحلتين وأغلى لهم فقلت له استوضعهم أو دعني أماكسهم فقد اشتطوا عليك فقال ويحك أما علمت أن المكاس ليس من أخلاق الكرام ثم ركب إحداهما وركبت الأخرى فسار\nسيرا شديدا فقلت أبق على نفسك فإن ما تريد ليس يفوتك فقال ويحك\n(أبادر حبل الود أن يتقضبا ... )\nما حلاوة الدنيا إن تم الصدع بين عمر والثريا فقدمنا مكة ليلا غير محرمين فدق على عمر بابه فخرج إليه وسلم عليه ولم ينزل عن راحلته فقال له اركب أصلح بينك وبين الثريا فأنا رسولك الذي سألت عنه فركب معنا وقدمنا الطائف وقد كان عمر أرضى أم نوفل فكانت تطلب لها الحيل لإصلاحها فلا يمكنها فقال ابن أبي عتيق للثريا هذا عمر قد جشمني السفر من المدينة إليك فجئتك به معترفا لك بذنب لم يجنه معتذرا إليك من إساءته إليك فدعيني من التعداد والترداد فإنه من الشعراء الذين يقولون ما لا يفعلون فصالحته أحسن صلح وأتمه وأجمله وكررنا إلى مكة فلم ينزلها ابن أبي عتيق حتى رحل وزاد عمر في أبياته\n(أزهقت أم نوفل إذ دعتها ... مهجتي ما لقاتلي من متاب)\n(حين قالت لها أجيبي فقالت ... من دعاني قالت أبو الخطاب)\n(فاستجابت عند الدعاء كما لبى ... رجال يرجون حسن الثواب)\nقال الزبير وما دعتها أم نوفل إلا لابن أبي عتيق ولو دعتها لعمر ما أجابت قال وسألت عمي عن أم نوفل فقال هي أم ولد عبد الله بن الحارث أبي الثريا وسألته عن قوله\n(كما لبى رجال يرجون حسن الثواب ... )\nقال كررت في التلبية كما يفعل المحرم فقالت لبيك لبيك\nوأخبرني حبيب بن نصر قال حدثنا الزبير بن بكار عن عمه أن بعض المكيين قال كانت الثريا تصب عليها جرة ماء وهي قائمة فلا يصيب ظاهر فخذيها منه شيء من عظم عجيزتها وأخبرني حبيب بن نصر قال حدثنا عمر بن شبة قال حدثنا أبو غسان محمد ابن يحيى بخبر الثريا هذا مع عمر فذكر نحوا مما ذكره الزبير وقال فيه لما أناخ ابن أبي عتيق بباب الثريا أرسلت إليه ما حاجتك قال أنا رسول عمر بن أبي ربيعة وأنشدها الشعر فقالت ابن أبي ربيعة فارغ ونحن في شغل وقد تعبت فانزل بنا فقال ما أنا إذا برسول ثم كر راجعا إلى ابن أبي ربيعة بمكة فأخبره الخبر فأصلح بينهما حدثني أحمد بن عبيد الله بن عمار قال حدثني يعقوب بن نعيم قال حدثني إبراهيم بن إسحاق العنزي قال حدثني عبد الله بن إبراهيم الجمحي وأخبرني به الحسين بن يحيى عن حماد عن أبيه عن أيوب بن عباية وأخبرني به الحرمي بن أبي العلاء قال حدثنا الزبير عن مؤمن بن عمر بن أفلح بن عبد العزيز بن عمران قالوا قدم عمر بن أبي ربيعة المدينة فنزل على ابن أبي عتيق وهو عبد الله بن محمد بن عبد الرحمن بن أبي بكر فلما استلقى قال أوه\n(من رسولي إلى الثريا فإني ... ضقت ذرعا بهجرها والكتاب)","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":42,"spl":"نجاح الصلح الذي سعى به ابن أبي عتيق","partial":1},
{"id":"b2-88","bab":"الجزء 1","sec":"ابن أبي عتيق يبلغ رسالة نصيب إلى سلمى في طريقه إلى الثريا","page":"ج1 ص225","text":"فقال ابن أبي عتيق كل مملوك لي حر إن بلغها ذاك غيري فخرج حتى\nإذا كان بالمصلى مر بنصيب وهو واقف فقال يا أبا محجن قال لبيك قال أتودع إلى سلمى شيئا قال نعم قال وما ذاك قال تقول لها يابن الصديق إنك مررت بي فقلت لي أتودع إليها شيئا فقلت\n(أتصبر عن سلمى وأنت صبور ... وأنت بحسن العزم منك جدير)\n(وكدت ولم أخلق من الطير إن بدا ... سنى بارق نحو الحجاز أطير)\nقال فمر بسلمى وهي في قرية يقال لها القسرية فأبلغها الرسالة فزفرت زفرة كادت أن تفرق أضلاعها فقال ابن أبي عتيق كل مملوك لي حر إن لم يكن جوابك أحسن من رسالته ولو سمعك الآن لنعق وصار غرابا ثم مضى إلى الثريا فأبلغ الكتاب فقالت له أما وجد رسولا أصغر منك انزل فأرح فقال لست إذا برسول وسألها أن ترضى عنه ففعلت وقال الزبير في خبره فقال لها أنا رسول ابن أبي ربيعة إليك وأنشدها الأبيات وقال لها خشيت أن تضيع هذه الرسالة قالت أدى الله عنك أمانتك قال فما جواب ما تجشمته إليك قالت تنشده قوله في رملة\n(وجلا بردها وقد حسرته ... ضوء بدر أضاء للناظرينا)\nقال أعيذك بالله يابنة أخي أن تغلبيني بالمثل السائر قالت وما هو قال حريص لا يرى عمله قالت فما تشاء قال تكتبين إليه بالرضا عنه كتابا يصل على يدي ففعلت فأخذ الكتاب ورجع من فوره حتى قدم مكة فأتى عمر فقال له من أين أقبلت قال من حيث أرسلتني قال وأنى ذلك قال من عند الثريا أفرخ روعك هذا كتابها بالرضا عنك إليك","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":43,"spl":"ابن أبي عتيق يبلغ رسالة نصيب إلى سلمى في طريقه إلى الثريا — عمر ينشد ابن أبي عتيق شعره في "},
{"id":"b2-89","bab":"الجزء 1","sec":"حسن بن حسن بن علي يطلب إلى ابن عائشة أن يغني له","page":"ج1 ص226","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه عن أيوب بن عباية قال اجتمع ابن عائشة ويونس ومالك عند حسن بن حسن بن علي عليهم السلام فقال الحسن لابن عائشة غنني من رسولي إلى الثريا فسكت عنه فلم يجبه فقال له جليس له أيقول لك غنني فلا تجيبه فسكت فقال له الحسن ما لك ويحك أبك خبال كان والله ابن أبي عتيق أجود منك بما عنده فإنه لما سمع هذا الشعر قال لابن أبي ربيعة أنا رسولك إليها فمضى نحو الثريا حتى أدى رسالته وأنت معنا في المجلس تبخل أن تغنيه لنا فقال له لم أذهب حيث ظننت إنما كنت أتخير لك أي الصوتين أغني أقوله\n(من رسولي إلى الثريا فإني ... ضافني الهم واعترتني الهموم)\n(يعلم الله أنني مستهام ... بهواكم وأنني مرحوم)\nم قوله\n(من رسولي إلى الثريا فإني ... ضقت ذرعا بهجرها والكتاب)\nفقال له الحسن أسأنا بك الظن أبا جعفر غن بهما جميعا فغناهما فقال له الحسن لولا أنك تغضب إذا قلنا لك أحسنت لقلت لك أحسنت والله قال ولم يزل يرددهما بقية يومه","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":43,"spl":"ابن أبي عتيق يبلغ رسالة نصيب إلى سلمى في طريقه إلى الثريا — عمر ينشد ابن أبي عتيق شعره في "},
{"id":"b2-90","bab":"الجزء 1","sec":"عمر ينشد ابن أبي عتيق شعره في الثريا","page":"ج1 ص227","text":"أخبرنا الحرمي بن أبي العلاء قال حدثنا الزبير قال حدثني يعقوب بن إسحاق الربعي عن أبيه قال\nأنشد عمر بن أبي ربيعة ابن أبي عتيق قوله\n(لم تر العين للثريا شبيها ... بمسيل التلاع يوم التقينا)\nلما بلغ إلى قوله\n(ثم قالت لأختها قد ظلمنا ... إن رددناه خائبا واعتدينا)\nال أحسنت والهدايا وأجادت ثم أنشده ابن أبي عتيق متمثلا قول الشاعر\n(أريني جوادا مات هزلا لعلني ... أرى ما ترين أو بخيلا مخلدا)\nلما بلغ عمر إلى قوله في الشعر\n(في خلاء من الأنيس وأمن ... )\nقال ابن أبي عتيق أمكنت للشارب الغدر من عال بعدها فلا انجبر فلما بلغ إلى قوله\n(فمكثنا كذاك عشرا تباعا ... في قضاء لديننا واقتضينا)\nقال أما والله ما قضيتها ذهبا ولا فضة ولا اقتضيتها إياه فلا عرفكما الله قبيحا فلما بلغ إلى قوله\n(كان ذا في مسيرنا إذ حججنا ... علم الله فيه ما قد نوينا)\nال إن ظاهر أمرك ليدل على باطنه فأرود التفسير ولئن مت لأموتن معك أف للدنيا بعدك يا أبا الخطاب فقال له عمر بل عليها بعدك العفاء يا أبا محمد قال فلقي الحارث بن خالد ابن أبي عتيق فقال قد بلغني ما دار بينك وبين ابن أبي ربيعة فكيف لم تتحللا مني فقال له ابن أبي عتيق يغفر الله لك يا أبا عمرو إن ابن أبي ربيعة يبرئ القرح ويضع الهناء مواضع النقب وأنت جميل الخفض فضحك الحارث بن خالد وقال حبك الشيء يعمي ويصم فقال هيهات أنا بالحسن عالم نظار","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":43,"spl":"ابن أبي عتيق يبلغ رسالة نصيب إلى سلمى في طريقه إلى الثريا — عمر ينشد ابن أبي عتيق شعره في ","partialRef":{"sid":"b2-43","gi":3,"vi":0,"side":0},"partial":1},
{"id":"b2-91","bab":"الجزء 1","sec":"خبر السواد في ثنيتي عمر","page":"ج1 ص229","text":"وأما خبر السواد في ثنيتي عمر فإن الزبير بن بكار ذكره عن عمه مصعب في خبره أن امرأة غارت عليه فاعترضته بمسواك كان في يدها فضربت به ثنيتيه فاسودتا وذكر إسحاق الموصلي عن أبي عبد الله المسيبي وأبي الحسن المدائني أنه\nأتى الثريا يوما ومعه صديق له كان يصاحبه ويتوصل بذكره في الشعر فلما كشفت الثريا الستر وأرادت الخروج إليه رأت صاحبه فرجعت فقال لها إنه ليس ممن أحتشمه ولا أخفي عنه شيئا واستلقى فضحك وكان النساء إذ ذاك يتختمن في أصابعهن العشر فخرجت إليه فضربته بظاهر كفها فأصابت الخواتيم ثنيتيه العلييين فنغضتا وكادتا تسقطان فقدم البصرة فعولجتا له فثبتتا واسودتا فقال الحزين الكناني يعيره بذلك وكان عدوه وقد بلغه خبره\n(ما بال سنيك أم ما بال كسرهما ... أهكذا كسرا في غير ما باس)\n(أم نفحة من فتاة كنت تألفها ... أم نالها وسط شرب صدمة الكاس)\nال ولقيه الحزين الكناني يوما فأنشده هذين البيتين فقال له عمر اذهب اذهب ويلك فإنك لا تحسن أن تقول صوت\n(ليت هندا أنجزتنا ما تعد ... وشفت أنفسنا مما تجد)\n(واستبدت مرة واحدة ... إنما العاجز من لا يستبد)\nابن سريج في هذا الشعر رمل بالخنصر في مجرى البصر عن إسحاق\nوخفيف رمل أيضا في هذه الإصبع وهذا المجرى عن ابن المكي ولمالك فيه ثقيل أول عن الهشامي ولمتيم ثاني ثقيل عن ابن المعتز وذكر أحمد ابن أبي العلاء عن مخارق أن خفيف الرمل ليحيى المكي صنعه وحكى فيه لحن هذا الصوت\n(اسلمي يا دار من هند ... )\nبر الثريا مع الحارث القباع حدثني علي بن صالح قال حدثني أبو هفان عن إسحاق الموصلي عن رجاله المذكورين أن الثريا واعدت عمر بن أبي ربيعة أن تزوره فجاءت في الوقت الذي ذكرته فصادفت أخاه الحارث قد طرقه وأقام عنده ووجه به في حاجة له ونام مكانه وغطى وجهه بثوبه فلم يشعر إلا بالثريا قد ألقت نفسها عليه تقبله فانتبه وجعل يقول اعزبي عني فلست بالفاسق أخزاكما الله فلما علمت بالقصة انصرفت ورجع عمر فأخبره الحارث بخبرها فاغتم لما فاته منها وقال أما والله لا تمسك النار أبدا وقد ألقت نفسها عليك فقال له الحارث عليك وعليها لعنة الله وأخبرني بهذه القصة الحرمي ابن أبي العلاء عن الزبير بن بكار عن يعقوب ابن إسحاق الربعي عن الثقة عنده عن ابن جريج عن عثمان بن حفص الثقفي\nأن الحارث بن عبد الله زار أخاه ثم ذكر نحوا من الذي ذكره إسحاق وقال فيه فبلغ عمر خبرها فجاء إلى أخيه الحارث وقال له جعلت فداءك ما لك ولأمة الوهاب ابنتك أتتك مسلمة عليك فلعنتها وزجرتها وتهددتها وها هي تيك باكية فقال وإنها لهي قال ومن تراها تكون قال فانكسر الحارث عنه وعن لومه","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":44,"spl":"خبر السواد في ثنيتي عمر — خبر زواج الثريا","partial":1},
{"id":"b2-92","bab":"الجزء 1","sec":"خبر زواج الثريا","page":"ج1 ص232","text":"أخبرني علي بن صالح قال حدثني أبو هفان عن إسحاق بن إبراهيم عن جعفر ابن سعيد عن أبي سعيد مولى فائد هكذا قال إسحاق وأخبرني الحرمي بن أبي العلاء قال حدثنا الزبير قال حدثني جعفر بن سعيد عن أبي عبيدة بن محمد بن عمار ورواه أيضا حماد بن إسحاق عن أبيه عن جعفر بن سعيد فقال فيه عن أبي عبيدة العماري ولم يذكر أبا سعيد مولى فائد قالوا تزوج سهيل بن عبد العزيز بن مروان الثريا وقال الزبير بل تزوجها أبو الأبيض سهيل بن عبد الرحمن بن عوف فحملت إليه وهو بمصر والصواب قول من قال سهيل بن عبد العزيز لأنه كان هناك منزله ولم يكن لسهيل بن عبد الرحمن هناك موضع فقال عمر صوت\n(أيها المنكح الثريا سهيلا ... عمرك الله كيف يلتقيان)\n(هي شامية إذا ما استقلت ... وسهيل إذا استقل يماني)\nلغناء للغريض خفيف ثقيل بالبنصر وفيه لعبد الله بن العباس ثاني ثقيل بالبنصر وأول هذه القصيدة\n(أيها الطارق الذي قد عناني ... بعد ما نام سامر الركبان)\n(زار من نازح بغير دليل ... يتخطى إلي حتى أتاني)","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":44,"spl":"خبر السواد في ثنيتي عمر — خبر زواج الثريا"},
{"id":"b2-93","bab":"الجزء 1","sec":"عمر يعلم بزواج الثريا وهو في اليمن","page":"ج1 ص233","text":"وذكر الرياشي عن ابن زكريا الغلابي عن محمد بن عبد الرحمن التيمي عن أبيه عن هشام بن سليمان بن عكرمة بن خالد المخزومي قال كان عمر بن أبي ربيعة قد ألح على الثريا بالهوى فشق ذلك على أهلها ثم إن مسعدة بن عمرو أخرج عمر إلى اليمن في أمر عرض له وتزوجت الثريا وهو غائب فبلغه تزويجها وخروجها إلى مصر فقال\n(أيها المنكح الثريا سهيلا ... عمرك الله كيف يلتقيان)\nذكر الأبيات وقال في خبره ثم حمله الشوق على أن سار إلى المدينة فكتب إليها\n(كتبت إليك من بلدي ... كتاب موله كمد)\n(كئيب واكف العينين ... بالحسرات منفرد)\n(يؤرقه لهيب الشوق ... بين السحر والكبد)\n(فيمسك قلبه بيد ... ويمسح عينه بيد)\nكتبه في قوهية وشنفه وحسنه وبعث به إليها فلما قرأته بكت بكاء شديدا ثم تمثلت\n(بنفسي من لا يستقل بنفسه ... ومن هو إن لم يحفظ الله ضائع)\nكتبت إليه تقول\n(أتاني كتاب لم ير الناس مثله ... أمد بكافور ومسك وعنبر)\n(وقرطاسه قوهية ورياطه ... بعقد من الياقوت صاف وجوهر)\n(وفي صدره مني إليك تحية ... لقد طال تهيامي بكم وتذكري)\n(وعنوانه من مستهام فؤاده ... إلى هائم صب من الحزن مسعر)\nال مؤلف هذا الكتاب وهذا الخبر عندي مصنوع وشعره مضعف يدل على ذلك ولكني ذكرته كما وقع إلي قال أبو سعيد مولى فائد ومن ذكر خبره مع الثريا فمات عنها سهيل أو طلقها فخرجت إلى الوليد بن عبد الملك وهو خليفة بدمشق في دين عليها فبينا\nهي عند أم البنين بنت عبد العزيز بن مروان إذ دخل عليها الوليد فقال من هذه فقالت الثريا جاءتني تطلب إليك في قضاء دين عليها وحوائج لها فأقبل عليها الوليد فقال أتروين من شعر عمر بن أبي ربيعة شيئا قالت نعم أما إنه ي كان عفيفا عفيف الشعر أروي قوله صوت\n(ما على الرسم بالبليين لو بين ... رجع السلام أو لو أجابا)\n(فإلى قصر ذي العشيرة فالصائف ... أمسى من الأنيس يبابا)\n(وبما قد أرى به حي صدق ... ظاهري العيش نعمة وشبابا)\n(إذ فؤادي يهوى الرباب وأنى الدهر ... حتى الممات أنسى الربابا)\n(وحسانا جواريا خفرات ... حافظات عند الهوى الأحسابا)\n(لا يكثرن في الحديث ولا يتبعن ... ينعقن بالبهام الظرابا)\nقضى حوائجها وانصرفت بما أرادت منه فلما خلا الوليد بأم البنين قال لها لله در\nالثريا أتدرين ما أرادت بإنشادها ما أنشدتني من شعر عمر قالت لا قال إني لما عرضت لها به عرضت لي بأن أمي أعرابية وأم الوليد وسليمان ولادة بنت العباس بن جزي بن الحارث بن زهير بن جذيمة العبسي الغناء في الأبيات التي أنشدتها الثريا الوليد بن عبد الملك لمالك بن أبي السمح خفيف ثقيل بإطلاق الوتر في مجرى البنصر وفيها لابن سريج رمل بالخنصر في مجرى البنصر وفيه لإبراهيم خفيف ثقيل بالسبابة في مجرى البنصر عن إسحاق وذكر حبش أيضا أن فيها لابن مسجح خفيف رمل بالوسطى وذكر عمرو بن بانة أن لابن محرز فيها خفيف ثقيل بالوسطى ومما يغنى فيه من أشعار عمر بن أبي ربيعة التي قالها في الثريا من القصيدة التي أولها من رسولي صوت\n(وتبدت حتى إذا جن قلبي ... حال دوني ولائد بالثياب)\n(يا خليلي فاعلما أن قلبي ... مستهام بربة المحراب)\nلغناء لابن سريج ثاني ثقيل بالوسطى عن عمرو ومنها صوت\n(أقتليني قتلا سريعا مريحا ... لا تكوني علي سوط عذاب)\n(شف عنها محقق جندي ... فهي كالشمس من خلال السحاب)\nالغناء للغريض ثاني ثقيل بالبنصر عن عمرو ومنها صوت\n(قال لي صاحبي ليعلم ما بي ... أتحب البتول أخت الرباب)\n(قلت وجدي بها كوجدك بالماء ... إذا ما منعت برد الشراب)\nالغناء لمالك رمل مطلق في مجرى الوسطى عن إسحاق ومنها صوت\n(أذكرتني من بهجة الشمس لما ... برزت من دجنة وسحاب)\n(أزهقت أم نوفل إذ دعتها ... مهجتي ما لقاتلي من متاب)\n(حين قالت لها أجيبي فقالت ... من دعاني قالت أبو الخطاب)\nلغناء للغريض خفيف رمل عن الهشامي وحماد بن إسحاق ومنها صوت\n(مرحبا ثم مرحبا بالتي قالت ... غداة الوداع عند الرحيل)\n(للثريا قولي له أنت همي ... ومنى النفس خاليا وخليلي)\nلغناء لابن محرز ثقيل مطلق في مجرى البنصر عن إسحاق وفيه لابن سريج خفيف رمل بالوسطى عن عمرو ومنها\nصوت\n(زعموا بأن البين بعد غد ... فالقلب مما أزمعوا يجف)\n(تشكو ويشكو ما أشت بنا ... كل لوشك البين يعترف)\n(حلفوا لقد قطعوا ببينهم ... وحلفت ألفا مثل ما حلفوا)","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":45,"spl":"عمر يعلم بزواج الثريا وهو في اليمن"},
{"id":"b2-94","bab":"الجزء 1","sec":"عمر يعلم بزواج الثريا وهو في اليمن","page":"ج1 ص233","text":"لغناء للغريض خفيف ثقيل بالوسطى ومنها صوت\n(فلوت رأسها ضرارا وقالت ... لا وعيشي ولو رأيتك متا)\n(حين آثرت بالمودة غيري ... وتناسيت وصلنا ومللتا)\n(قد وجدناك إذ خبرت ملولا ... طرفا لم تكن كما كنت قلتا)\nلغناء لمالك رمل ثقيل أول بالوسطى عن عمرو وفيه لابن سريج خفيف ثقيل عن الهشامي وكذا روته دنانير عن فليح وقد نسب قوم لحن مالك إلى الغريض ومنها صوت\n(يا خليلي سائلا الأطلالا ... ومحلا بالروضتين أحالا)\nويروى\n(بالبليين إن أحرن سؤالا ... )\n(وسفاه لولا الصبابة حبسي ... في رسوم الديار ركبا عجالا)\n(بعدما أقفرت من آل الثريا ... وأجدت فيها النعاج ظلالا)\nالغناء لابن سريج هزج خفيف مطلق في مجرى البنصر عن إسحاق وفيه لحكم الوادي ثقيل أول من جامع أغانيه وذكر ابن دينار أن فيه لابن عائشة لحنا لم يذكر طريقته وذكر إبراهيم أن فيه لدحمان لحنا ولم يجنسه وقال حبش فيه لإسحاق ثقيل أول بالوسطى","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":46,"spl":"عمر يعلم بزواج الثريا وهو في اليمن — عمر يتبع الثريا في أثناء ارتحالها إلى الشام مع زوجها","partial":1},
{"id":"b2-95","bab":"الجزء 1","sec":"عمر يتبع الثريا في أثناء ارتحالها إلى الشام مع زوجها","page":"ج1 ص239","text":"أخبرني محمد بن خلف بن المرزبان قال حدثنا أبو عبد الله التميمي يعني أبا العيناء عن القحذمي عن أبي صالح السعدي قال\nلما تزوج سهيل بن عبد العزيز الثريا ونقلها إلى الشأم بلغ عمر بن أبي ربيعة الخبر فأتى المنزل الذي كانت الثريا تنزله فوجدها قد رحلت منه يومئذ فخرج في أثرها فلحقها على مرحلتين وكانت قبل ذلك مهاجرته لأمر أنكرته عليه فلما أدركهم نزل عن فرسه ودفعه إلى غلامه ومشى متنكرا حتى مر بالخيمة فعرفته الثريا وأثبتت حركته ومشيته فقالت لحاضنتها كلميه فسلمت عليه وسألته عن حاله وعاتبته على ما بلغ الثريا عنه فاعتذر وبكى فبكت الثريا فقالت ليس\nهذا وقت العتاب مع وشك الرحيل فحادثها إلى وقت طلوع الفجر ثم ودعها وبكيا طويلا وقام فركب فرسه ووقف ينظر إليهم وهم يرحلون ثم أتبعهم بصره حتى غابوا وأنشأ يقول\n(يا صاحبي قفا نستخبر الطللا ... عن حال من حله بالأمس ما فعلا)\n(فقال لي الربع لما أن وقفت به ... إن الخليط أجد البين فاحتملا)\n(وخادعتك النوى حتى رأيتهم ... في الفجر يحتث حادي عيسهم زجلا)\n(لما وقفنا نحييهم وقد صرخت ... هواتف البين واستولت بهم أصلا)\n(صدت بعادا وقالت للتي معها ... بالله لوميه في بعض الذي فعلا)\n(وحدثيه بما حدثت واستمعي ... ماذا يقول ولا تعيي به جدلا)\n(حتى يرى أن ما قال الوشاة له ... فينا لديه إلينا كله نقلا)\n(وعرفيه به كالهزل واحتفظي ... في بعض معتبة أن تغضبي الرجلا)\n(فإن عهدي به والله يحفظه ... وإن أتى الذنب ممن يكره العذلا)\n(لو عندنا اغتيب أو نيلت نقيصته ... ما آب مغتابه من عندنا جذلا)\n(قلت اسمعي فلقد أبلغت في لطف ... وليس يخفى على ذي اللب من هزلا)\n(هذا أرادت به بخلا لأعذرها ... وقد أرى أنها لن تعدم العللا)\n(ما سمي القلب إلا من تقلبه ... ولا الفؤاد فؤادا غير أن عقلا)\n(أما الحديث الذي قالت أتيت به ... فما عبأت به إذ جاءني حولا)\n(ما إن أطعت بها بالغيب قد علمت ... مقاله الكاشح الواشي إذا محلا)\n(إني لأرجعه فيها بسخطته ... وقد يرى أنه قد غرني زللا)\nهي قصيدة طويلة مذكورة في شعره","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":46,"spl":"عمر يعلم بزواج الثريا وهو في اليمن — عمر يتبع الثريا في أثناء ارتحالها إلى الشام مع زوجها"},
{"id":"b2-96","bab":"الجزء 1","sec":"الغريض يطلب شعرا ينوح به على الثريا","page":"ج1 ص241","text":"أخبرني أحمد بن عبد العزيز الجوهري وحبيب بن نصر ومحمد بن خلف بن المرزبان قالوا حدثنا عمر بن شبة قال أخبرنا محمد بن يحيى قال زعم عبيد بن يعلى قال حدثني كثير بن كثير السهمي قال لما ماتت الثريا أتاني الغريض فقال لي قل أبيات شعر أنح بها على الثريا فقلت صوت\n(ألا يا عين مالك تدمعينا ... أمن رمد بكيت فتكحلينا)\n(أم أنت حزينة تبكين شجوا ... فشجوك مثله أبكى العيونا)\nنى الغريض في هذين البيتين لحنا من خفيف الثقيل الأول بالوسطى عن عمرو ويحيى المكي والهشامي وغيرهم أخبرني حبيب بن نصر المهلبي قال حدثنا الزبير بن بكار قال حدثني عبد الجبار بن سعيد المساحقي قال حدثني إبراهيم بن يعقوب بن أبي عبد الله عن أبيه\nعن جده عن ثعلبة بن عبد الله بن صعير أن عمر بن أبي ربيعة نظر في الطواف إلى امرأة شريفة فرأى أحسن خلق الله صورة فذهب عقله عليها وكلمها فلم تجبه فقال فيها\n(الريح تسحب أذيالا وتنشرها ... يا ليتني كنت ممن تسحب الريح)\n(كيما تجر بنا ذيلا فتطرحنا ... على التي دونها مغبرة سوح)\n(أنى بقربكم أم كيف لي بكم ... هيهات ذلك ما أمست لنا روح)\n(فليت ضعف الذي ألقى يكون بها ... بل ليت ضعف الذي ألقى تباريح)\n(إحدى بنيات عمي دون منزلها ... أرض بقيعانها القيصوم والشيح)\nفبلغها شعره فجزعت منه فقيل لها اذكريه لزوجك فإنه سينكر عليه قوله فقالت كلا والله لا أشكوه إلا إلى الله ثم قالت اللهم إن كان نوه باسمي ظالما فاجعله طعاما للريح فضرب الدهر من ضربه ثم إنه غدا يوما على فرس فهبت ريح فنزل فاستتر بسلمة فعصفت الريح فخدشه غصن منها فدمي وورم به ومات من ذلك","topic":"ذكر خبر عمر بن أبي ربيعة ونسبه","topicNo":2,"sp":47,"spl":"الغريض يطلب شعرا ينوح به على الثريا"},
{"id":"b3-1","bab":"الجزء 1","sec":"أخبار ابن سريج ونسبه نسب ابن سريج","page":"ج1 ص243","text":"هو عبيد بن سريج ويكنى أبا يحيى مولى بني نوفل بن عبد مناف وذكر ابن الكلبي عن أبيه وأبي مسكين أنه مولى لبني الحارث بن عبد المطلب وأخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا محمد بن يحيى أبو غسان قال ابن سريج مولى لبني الحارث بن عبد المطلب وأخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا محمد بن يحيى أبو غسان قال ابن سريج مولى لبني ليث ومنزله مكة وأخبرني الحسين بن يحيى عن حماد بن إسحاق عن أبيه قال سألت الحسن بن عتبة اللهبي عن ابن سريج فقال هو مولى لبني عائذ بن عبد الله بن عمر بن مخزوم وفي بني عائذ يقول الشاعر\n(فإن تصلح فإنك عائذي ... وصلح العائذي إلى فساد)\nال إسحاق وقال سلمة بن نوفل بن عمارة بن سريج مولى عبد الرحمن ابن أبي حسين بن الحارث بن نوفل أو ابن عامر بن الحارث بن نوفل بن عبد مناف\nأخبرني أحمد بن عبد العزيز عن أبي أيوب المديني قال ذكر إبراهيم بن زياد بن عنبسة بن سعيد بن العاص","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":0,"spl":"أخبار ابن سريج ونسبه نسب ابن سريج — بعض من أوصافه"},
{"id":"b3-2","bab":"الجزء 1","sec":"بعض من أوصافه","page":"ج1 ص244","text":"أن ابن سريج كان آدم أحمر ظاهر الدم سناطا في عينيه قبل بلغ خمسا وثمانين سنة وصلع فكان يلبس جمة مركبة وكان أكثر ما يرى مقنعا وكان منقطعا إلى عبد الله بن جعفر وقال ابن الكلبي عن أبيه قال كان ابن سريج مخنثا أحول أعمش يلقب وجه الباب وصلع فكان يلبس جمة وكان لا يغني إلا مقنعا يسبل القناع على وجهه وقال ابن الكلبي عن أبيه وأبي مسكين كان ابن سريج أحسن الناس غناء وكان يغني مرتجلا ويوقع بقضيب وغنى في زمن عثمان بن عفان رضي الله عنه ومات في خلافة هشام بن عبد الملك قال إسحاق وكان الحسن بن عتبة اللهبي يروي مثل ذلك فيه وذكر أن قبره بنخلة قريبا من بستان ابن عامر قال إسحاق وحدثني الهيثم بن عدي عن صالح بن حسان قال كان عبيد بن\nسريج من أهل مكة وكان أحسن الناس غناء قال إسحاق قال عمارة بن أبي طرفة الهذلي سمعت ابن جريج يقول عبيد بن سريج من أهل مكة مولى آل خالد ابن أسيد قال إسحاق وحدثني إبراهيم بن زياد عن أيوب بن سلمة المخزومي قال كان في عين ابن سريج قبل حلو لا يبلغ أن يكون حولا وغنى في خلافة عثمان رضي الله عنه ومات بعد قتل الوليد بن يزيد وكان له صلع في جبهته وكان يلبس جمة مركبة فيكون فيها أحسن شيء وكان يلقب وجه الباب ولا يغضب من ذلك وكان أبوه تركيا وقال أبو أيوب المديني كان ابن سريج فيما روينا عن جماعة من المكيين مولى بني جندع بن ليث بن بكر وكان إذا غنى سدل قناعه على وجهه حتى لا يرى حوله وكان يوقع بقضيب وقيل إنه كان يضرب بالعود وكانت علته التي مات منها الجذام قال إسحاق وحدثني أبي قال أخبرني من رأى عود ابن سريج وكان على صنعة عيدان الفرس وكان ابن سريج أول من ضرب به على الغناء العربي بمكة وذلك أنه رآه مع العجم الذين قدم بهم ابن الزبير لبناء الكعبة فأعجب أهل مكة غناؤهم فقال ابن سريج أنا أضرب بهم على غنائه فضرب به فكان أحذق الناس قال إسحاق وذكر الزبيري أن أم ابن سريج مولاة لآل المطلب يقال لها رائقة وقيل بل أمه هند أخت رائقة فمن ثم قيل إنه مولى بني المطلب بن حنطب وكان ابن سريج بعد وفاة عبد الله بن جعفر قد انقطع إلى الحكم بن\nالمطلب بن عبد الله بن المطلب بن حنطب أحد بني مخزوم وكان من سادة قريش ووجوهها وأخذ ابن سريج الغناء عن ابن مسجح","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":0,"spl":"أخبار ابن سريج ونسبه نسب ابن سريج — بعض من أوصافه"},
{"id":"b3-3","bab":"الجزء 1","sec":"المغنون الأربعة المعدودون أصولا للغناء العربي","page":"ج1 ص246","text":"قال إسحاق وأصل الغناء أربعة نفر مكيان ومدنيان فالمكيان ابن سريج وابن محرز والمدنيان معبد ومالك\nقال إسحاق وقال سلمة بن نوفل بن عمارة أخبرني بذلك من شئت من مشيختنا أن يوما شهر فيه ابن سريج بالغناء في ختان ابن مولاه عبد الله بن عبد الرحمن بن أبي حسين قال لأم الغلام خفضي عليك بعض الغرم والكلفة فوالله لألهين نساءك حتى لا يدرين ما جئت به ولا ما عزمت عليه\nقال إسحاق وسألت هشام بن المرية وكان قد عمر وكان عالما بالغناء فلا يبارى فيه فقلت له من أحذق الناس بالغناء فقال لي أتحب الإطالة أم الاختصار فقلت أحب الاختصار الذي يأتي على سؤالي قال ما خلق الله تعالى بعد داود النبي عليه الصلاة و السلام أحسن صوتا من ابن سريج ولا صاغ الله عز و جل أحدا أحذق منه بالغناء ويدلك على ذلك أن معبدا كان إذا أعجبه\nغناؤه قال أنا اليوم سريجي قال وأخبرني إبراهيم يعني أباه قال أدركت يونس بن محمد الكاتب فحدثني عن الأربعة ابن سريج وابن محرز والغريض ومعبد فقلت له من أحسن الناس غناء فقال أبو يحيى قلت عبيد بن سريج قال نعم قلت وكيف ذاك قال إن شئت فسرت لك وإن شئت أجملت قلت أجمل قال كأنه خلق من كل قلب فهو يغني لكل إنسان ما يشتهي أخبرني أحمد بن جعفر جحظة قال قال حماد بن إسحاق أخبرني أبي عن الفضل بن يحيى بن خالد بن برمك قال سألت إبراهيم الموصلي ليلة وقد أخذ منه النبيذ من أحسن الناس غناء فقال لي من الرجال أم من النساء فقلت من الرجال فقال ابن محرز قلت ومن النساء قال ابن سريج ثم قال لي إن كان ابن سريج إلا كأنه خلق من كل قلب فهو يغني له ما يشتهي أخبرني جحظة قال حدثني علي بن يحيى المنجم قال أرسلني محمد بن الحسين بن مصعب إلى إسحاق أسأله عن لحنه ولحن ابن سريج في\n(تشكى الكميت الجري لما جهدته ... )\nيهما أحسن فصرت إليه فسألته عن ذلك فقال لي يا أبا الحسن والله لقد أخذت بخطام راحلته فزعزعتها وأنختها وقمت بها فما بلغته فرجعت إلى محمد بن الحسين فأخبرته فقال والله إنه ليعلم أن لحنه أحسن من لحن ابن\nسريج ولقد تحامل لابن سريج على نفسه ولكن لا يدع تعصبه للقدماء وقد أخبرنا يحيى بن علي بن يحيى هذا الخبر عن أبيه فذكر نحو ما ذكره جحظة في خبره ولم يقل أرسلني محمد بن الحسين إلى إسحاق وقال جحظة في خبره قال علي بن يحيى وقد صدق محمد بن الحسين لأنه قلما غني في صوت واحد لحنان فسقط خيرهما والذي في أيدي الناس الآن من اللحنين لحن إسحاق وقد ترك لحن ابن سريج فقل من يسمعه إلا من العجائز المتقدمات ومشايخ المغنين هذا أو نحوه وأخبرني يحيى بن علي قال حدثنا أبو أيوب المديني عن إبراهيم بن علي بن هشام قال يقولون إن ابتداء غناء إسحاق الذي في\n(تشكى الكميت الجري لما جهدته ... )\nنما أخذه من صوت الأبجر\n(يقولون ما أبكاك والمال غامر ... )\nنسبة هذا الصوت صوت\n(يقولون ما أبكاك والمال غامر ... عليك وضاحي الجلد منك كنين)\n(فقلت لهم لا تسألوني وانظروا ... إلى الطرب النزاع كيف يكون)\nغناه الأبحر ثقيلا أول بالبنصر عن عمرو ودنانير وذكر الهشامي أن فيه لعزة المرزوقية ثاني ثقيل بالوسطى","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":1,"spl":"المغنون الأربعة المعدودون أصولا للغناء العربي — اشتغال ابن سريج بالغناء بعد أن كان نائحا","partialRef":{"sid":"b1-1","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b3-4","bab":"الجزء 1","sec":"اشتغال ابن سريج بالغناء بعد أن كان نائحا","page":"ج1 ص248","text":"أخبرني رضوان بن أحمد الصيدلاني قال حدثنا يوسف بن إبراهيم قال حدثني إبراهيم بن المهدي قال حدثني إسماعيل بن جامع عن سياط قال كان ابن سريج أول من غنى الغناء المتقن بالحجاز بعد طويس وكان مولده في خلافة عمر بن الخطاب وأدرك يزيد بن عبد الملك وناح عليه ومات في خلافة هشام قال وكان قبل أن يغني نائحا ولم يكن مذكورا حتى ورد الخبر مكة بما فعله مسرف بن عقبة بالمدينة فعلا على أبي قبيس وناح بشعر هو اليوم داخل في أغانيه وهو\n(يا عين جودي بالدموع السفاح ... وابكي على قتلى قريش البطاح)\nاستحسن الناس ذلك منه وكان أول ما ندب به","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":1,"spl":"المغنون الأربعة المعدودون أصولا للغناء العربي — اشتغال ابن سريج بالغناء بعد أن كان نائحا"},
{"id":"b3-5","bab":"الجزء 1","sec":"سكينة بنت الحسين وابن سريج","page":"ج1 ص249","text":"قال بن جامع وحدثني جماعة من شيوخ أهل مكة أنهم حدثوا أن سكينة بنت الحسين عليهما السلام بعثت إلى ابن سريج بشعر أمرته أن يصوغ فيه لحنا يناح به فصاغ فيه وهو الآن داخل في غنائه والشعر\n(يا أرض ويحك اكرمي أمواتي ... فلقد ظفرت بسادتي وحماتي)\nقدمه ذلك عند أهل الحرمين على جميع ناحة مكة والمدينة والطائف قال وحدثني ابن جامع وابن أبي الكنات جميعا أن سكينة بعثت إليه بمملوك لها يقال له عبد الملك وأمرته أن يعلمه النياحة فلم يزل يعلمه مدة طويلة ثم توفي عمها أبو القاسم محمد بن الحنفية عليه السلام وكان ابن سريج عليلا علة صعبة فلم يقدر على النياحة فقال لها عبدها عبد الملك أنا أنوح لك نوحا أنسيك به نوح ابن سريج قالت أو تحسن ذاك قال نعم فأمرته فناح فكان نوحه في الغاية من الجودة وقال النساء هذا نوح غريض فلقب عبد الملك الغريض وأفاق ابن سريج من علته بعد أيام وعرف خبر وفاة ابن الحنفية فقال لهم فمن ناح عليه قالوا عبد الملك غلام سكينة قال فهل جوز الناس نوحه قالوا نعم وقدمه بعضهم عليك فحلف ابن سريج ألا ينوح بعد ذلك اليوم وترك النوح وعدل إلى الغناء فلم ينح حتى ماتت حبابة وكانت قد أخذت عنه وأحسنت إليه فناح عليها ثم ناح بعدها على يزيد بن عبد الملك ثم لم ينح بعده حتى هلك قال ولما عدل ابن سريج عن النوح إلى الغناء عدل معه الغريض إليه فكان لا يغني صوتا إلا عارضه فيه","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":2,"spl":"سكينة بنت الحسين وابن سريج — ابن سريج وعطاء بن أبي رباح"},
{"id":"b3-6","bab":"الجزء 1","sec":"ابن سريج وعطاء بن أبي رباح","page":"ج1 ص250","text":"أخبرني رضوان بن أحمد الصيدلاني قال حدثنا يوسف بن إبراهيم قال\nحدث إسحاق بن إبراهيم الموصلي أبا إسحاق إبراهيم بن المهدي وأنا حاضر أن يحيى المكي حدثه أن عطاء بن أبي رباح لقي ابن سريج بذي طوى وعليه ثياب مصبغة وفي يده جرادة مشدودة الرجل بخيط يطيرها ويجذبها به كلما تخلفت فقال له عطاء يا فتان ألا تكف عما أنت عليه كفى الله الناس مؤنتك فقال ابن سريج وما على الناس من تلويني ثيابي ولعبي بجرادتي فقال له تفتنهم أغانيك الخبيثة فقال له ابن سريج سألتك بحق من تبعته من أصحاب رسول الله وبحق رسول الله عليك إلا ما سمعت مني بيتا من الشعر فإن سمعت منكرا أمرتني بالإمساك عما أنا عليه وأنا أقسم بالله وبحق هذه البنية لئن أمرتني بعد استماعك مني بالإمساك عما أنا عليه لأفعلن ذلك فأطمع ذلك عطاء في ابن سريج وقال قل فاندفع يغني بشعر جرير صوت\n(إن الذين غدوا بلبك غادروا ... وشلا بعينك لا يزال معينا)\n(غيضن من عبراتهن وقلن لي ... ماذا لقيت من الهوى ولقينا)\nحن ابن سريج هذا ثقيل أول بالوسطى عن ابن المكي والهشامي وله أيضا فيه رمل ولإسحاق فيه رمل آخر بالوسطى وفيه هزج بالوسطى ينسب إلى ابن سريج والغريض قال فلما سمعه عطاء اضطرب إضطرابا شديدا ودخلته أريحية فحلف ألا يكلم أحدا بقية يومه إلا بهذا الشعر وصار إلى مكانه من المسجد الحرام فكان كل من يأتيه سائلا عن حلال أو حرام أو خبر من الأخبار لا\nيجيبه إلا بأن يضرب إحدى يديه على الأخرى وينشد هذا الشعر حتى صلى المغرب ولم يعاود ابن سريج بعد هذا ولا تعرض له","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":2,"spl":"سكينة بنت الحسين وابن سريج — ابن سريج وعطاء بن أبي رباح"},
{"id":"b3-7","bab":"الجزء 1","sec":"ابن سريج ويزيد بن عبد الملك","page":"ج1 ص252","text":"أخبرني جعفر بن قدامة قال حدثني حماد بن إسحاق عن أبيه وأخبرني الحسن بن علي قال حدثني الفضل بن محمد اليزيدي قال حدثني إسحاق عن ابن جامع عن سياط عن يونس الكاتب قال لما قال عمر بن أبي ربيعة\n(نظرت إليها بالمحصب من منى ... ولي نظر لولا التحرج عارم)\nني فيه ابن سريج قال وحج يزيد بن عبد الملك في تلك السنة بالناس وخرج عمر بن أبي ربيعة ومعه ابن سريج على نجيبين رحالتاهما ملبستان بالديباج وقد خضبا النجيبين ولبسا حلتين فجعلا يتلقيان الحاج ويتعرضان للنساء إلى أن أظلم الليل فعدلا إلى كثيب مشرف والقمر طالع يضيء فجلسا على الكثيب وقال عمر لابن سريج غنني صوتك الجديد فاندفع يغنيه فلم يستتمه إلا وقد طلع عليه رجل راكب على فرس عتيق فسلم ثم قال أيمكنك أعزك الله أن ترد هذا الصوت قال نعم ونعمة عين على أن تنزل وتجلس معنا قال أنا أعجل من ذلك فإن أجملت وأنعمت أعدته وليس عليك من وقوفي شيء ولا مؤنة فأعاده فقال له بالله أنت ابن سريج قال نعم قال حياك الله وهذا عمر بن أبي ربيعة قال نعم قال حياك الله يا أبا الخطاب فقال له وأنت فحياك الله قد\nعرفتنا فعرفنا نفسك قال لا يمكنني ذلك فغضب ابن سريج وقال والله لو كنت يزيد بن عبد الملك لما زاد فقال له أنا يزيد بن عبد الملك فوثب إليه عمر فأعظمه ونزل ابن سريج إليه فقبل ركابه فنزع حلته وخاتمه فدفعهما إليه ومضى يركض حتى لحق ثقله فجاء بهما ابن سريج إلى عمر فأعطاه إياهما وقال له إن هذين بك أشبه منهما بي فأعطاه عمر ثلثمائة دينار وغدا فيهما إلى المسجد فعرفهما الناس وجعلوا يتعجبون ويقولون كأنهما والله حلة يزيد بن عبد الملك وخاتمه ثم يسألون عمر عنهما فيخبرهم أن يزيد بن عبد الملك كساه ذلك","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":3,"spl":"ابن سريج ويزيد بن عبد الملك"},
{"id":"b3-8","bab":"الجزء 1","sec":"ابن سريج يغني في طريق الحاج","page":"ج1 ص253","text":"وأخبرني بهذا الخبر جعفر بن قدامة أيضا قال وحدثني ابن عبد الله بن أبي سعيد قال حدثني علي بن الصباح عن ابن الكلبي قال حج عمر بن أبي ربيعة في عام من الأعوام على نجيب له مخضوب بالحناء مشهر الرحل بقراب مذهب ومعه عبيد بن سريج على بغلة له شقراء ومعه غلامه جناد يقود فرسا له أدهم أغر محجلا وكان عمر بن أبي ربيعة يسميه الكوكب في عنقه طوق ذهب وجناد هذا هو الذي يقول فيه صوت\n(فقلت لجناد خذ السيف واشتمل ... عليه برفق وارقب الشمس تغرب)\n(وأسرج لي الدهماء واعجل بممطري ... ولا تعلمن خلقا من الناس مذهبي)\nالغناء لزرزر غلام المارقي خفيف ثقيل وهو أجود صوت صنعه قال ومع عمر جماعة من حشمه وغلمانه ومواليه وعليه حلة موشية يمانية وعلى ابن سريج ثوبان هرويان مرتفعان فلم يمروا بأحد إلا عجب من حسن هيئتهم وكان عمر من أعطر الناس وأحسنهم هيئة فخرجوا من مكة يوم التروية بعد العصر يريدون منى فمروا بمنزل رجل من بني عبد مناف بمنى قد ضربت عليه فساطيطه وخيمه ووافى الموضع عمر فأبصر بنتا للرجل قد خرجت من قبتها وستر جواريها دون القبة لئلا يراها من مر فأشرف عمر على النجيب فنظر إليها وكانت من أحسن النساء وأجملهن فقال لها جواريها هذا عمر بن أبي ربيعة فرفعت رأسها فنظرت إليه ثم سترتها الجواري وولائدها عنه وبطن دونها بسجف القبة حتى دخلت ومضى عمر إلى منزله وفساطيطه بمنى وقد نظر من الجارية إلى ما تيمه ومن جمالها إلى ما حيره فقال فيها\n(نظرت إليها بالمحصب من منى ... ولي نظر لولا التحرج عارم)\n(فقلت أشمس أم مصابيح بيعة ... بدت لك خلف السجف أم أنت حالم)\n(بعيدة مهوى القرط إما لنوفل ... أبوها وإما عبد شمس وهاشم)\n(ومد عليها السجف يوم لقيتها ... على عجل تباعها والخوادم)\n(فلم استطعها غير أن قد بدا لنا ... على الرغم منها كفها والمعاصم)\n(معاصم لم تضرب على البهم بالضحى ... عصاها ووجه لم تلحه السمائم)\n(نضير ترى فيه أساريع مائه ... صبيح تغاديه الأكف النواعم)\n(إذا ما دعت أترابها فاكتنفنها ... تمايلن أو مالت بهن المآكم)\n(طلبن الصبا حتى إذا ما أصبنه ... نزعن وهن المسلمات الظوالم)\nم قال عمر لابن سريج يا أبا يحيى إني تفكرت في رجوعنا مع العشية إلى مكة مع كثرة الزحام والغبار وجلبة الحاج فثقل علي فهل لك أن تروح رواحا طيبا معتزلا فنرى فيه من راح صادرا إلى المدينة من أهلها ونرى أهل العراق وأهل الشام ونتعلل في عشيتنا وليلتنا ونستريح قال وأنى ذلك يا أبا الخطاب قال على كثيب أبي شحوة المشرق على بطن يأجج بين منى وسرف فنبصر مرور الحاج بنا ونراهم ولا يرونا قال ابن سريج طيب والله يا سيدي فدعا بعض خدمه فقال اذهبوا إلى الدار بمكة فاعملوا لنا سفرة واحملوها مع شراب إلى الكثيب حتى إذا أبردنا ورمينا الجمرة صرنا إليكم قال والكثيب على خمسة أميال من مكة مشرف على طريق المدينة وطريق الشام وطريق العراق وهو كثيب شامخ مستدق أعلاه منفرد عن الكثبان فصارا إليه فأكلا وشربا فلما انتشيا أخذ ابن سريج الدف فنقره وجعل يغني وهم ينظرون إلى الحاج فلما أمسيا رفع ابن سريج صوته يغني في الشعر الذي قاله عمر فسمعه الركبان فجعلوا يصيحون به يا صاحب الصوت أما تتقي الله قد حبست الناس عن مناسكهم فيسكت قليلا حتى إذا مضوا رفع صوته وقد أخذ فيه الشراب فيقف آخرون إلى أن مرت قطعة من الليل فوقف عليه في الليل رجل على فرس عتيق عربي مرح مستن\nفهو كأنه ثمل حتى وقف بأصل الكثيب وثنى رجله على قربوس سرجه ثم نادى يا صاحب الصوت أيسهل عليك أن ترد شيئا مما سمعته قال نعم ونعمة عين فأيها تريد قال تعيد علي\n(ألا يا غراب البين مالك كلما ... نعبت بفقدان علي تحوم)\n(أبالبين من عفراء أنت مخبري ... عدمتك من طير فأنت مشوم)\nقال والغناء لابن سريج فأعاده ثم قال ابن سريج ازدد إن شئت فقال غني\n(أمسلم إني يابن كل خليفة ... ويا فارس الهيجا ويا قمر الأرض)\n(شكرتك إن الشكر حبل من التقى ... وما كل من أقرضته نعمة يقضي)\n(ونوهت لي باسمي وما كان خاملا ... ولكن بعض الذكر أنبه من بعض)\nغناه فقال له الثالث ولا أستزيدك فقال قل ما شئت فقال تغنيني\n(يا دار أقوت بالجزع فالكثب ... بين مسيل العذيب فالرحب)\n(لم تتقنع بفضل مئزرها ... دعد ولم تسق دعد في العلب)","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":4,"spl":"ابن سريج يغني في طريق الحاج"},
{"id":"b3-9","bab":"الجزء 1","sec":"ابن سريج يغني في طريق الحاج","page":"ج1 ص253","text":"فغناه فقال له ابن سريج أبقيت لك حاجة قال نعم تنزل إلي لأخاطبك شفاها بما أريد فقال له عمر انزل إليه فنزل فقال له لولا أني أريد وداع الكعبة وقد تقدمني ثقلي وغلماني لأطلت المقام معك ولنزلت عندكم ولكني أخاف أن يفضحني الصبح ولو كان ثقلي معي لما رضيت لك بالهوينى ولكن خذ حلتي هذه وخاتمي ولا تخدع عنهما فإن شراءهما ألف وخمسمائة دينار وذكر باقي الخبر مثل ما ذكره حماد بن إسحاق","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":5,"spl":"ابن سريج يغني في طريق الحاج — ابن الزبير يؤخذ بغناء ابن سريج"},
{"id":"b3-10","bab":"الجزء 1","sec":"نسبة ما في هذا الخبر من الأغاني","page":"ج1 ص257","text":"صوت\n(نظرت إليها بالمحصب من منى ... ولي نظر لولا التحرج عارم)\n(فقلت أشمس أم مصابيح بيعة ... بدت لك خلف السجف أم أنت حالم)\n(بعيدة مهوى القرط إما لنوفل ... أبوها وإما عبد شمس وهاشم)\nلشعر لعمر بن أبي ربيعة والغناء لمعبد ثقيل أول بالسبابة في مجرى البنصر عن إسحاق وفيه لابن سريج رمل بالسبابة في مجرى البنصر عنه وقد نسب في مواضع من هذا الكتاب صوت\n(ألا يا غراب البين مالك كلما ... نعبت بفقدان علي تحوم)\n(أبالبين من عفراء أنت مخبري ... عدمتك من طير فأنت مشوم)\nلشعر لقيس بن ذريح وقيل إنه لغيره والغناء لابن سريج رمل بالوسطى عن الهشامي\nصوت\n(أمسلم إني يابن كل خليفة ... ويا فارس الهيجا ويا قمر الأرض)\n(شكرتك إن الشكر حبل من التقى ... وما كل من أوليته نعمة يقضي)\n(ونوهت لي باسمي وما كان خاملا ... ولكن بعض الذكر أنبه من بعض)\nلشعر لأبي نخيلة الحماني والغناء لابن سريج ثاني ثقيل بالوسطى وقد أخرج هذا الصوت مع سائر أخبار أبي نخيلة في موضع آخر","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":5,"spl":"ابن سريج يغني في طريق الحاج — ابن الزبير يؤخذ بغناء ابن سريج"},
{"id":"b3-11","bab":"الجزء 1","sec":"مكانة ابن سريج بين المغنين","page":"ج1 ص257","text":"حدثني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني محمد ابن سلام الجمحي قال حدثني عمر بن أبي خليفة قال كان أبي نازلا في علو فكان المغنون يأتونه قال فقلت فأيهم كان أحسن غناء قال لا أدري إلا أني كنت أراهم إذا جاء ابن سريج سكتوا","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":5,"spl":"ابن سريج يغني في طريق الحاج — ابن الزبير يؤخذ بغناء ابن سريج"},
{"id":"b3-12","bab":"الجزء 1","sec":"ابن الزبير يؤخذ بغناء ابن سريج","page":"ج1 ص258","text":"أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثني إسحاق بن إبراهيم الموصلي قال حدثني الزبيري يعني عبد الله بن مصعب عن عمرو بن الحارث قال إسحاق وحدثنيه المدائني ومحمد بن سلام عن المحرز ابن جعفر عن عمر بن سعد مولى الحارث بن هشام قال خرج ابن الزبير ليلة إلى أبي قبيس فسمع غناء فلما انصرف رآه أصحابه وقد حال لونه فقالوا إن بك لشرا قال إنه ذاك قالوا ما هو قال لقد سمعت صوتا إن كان من الجن إنه لعجب وإن كان من الإنس فما انتهى منتهاه\nشيء قال فنظروا فإذا هو ابن سريج يتغنى صوت\n(أمن رسم دار بوادي غدر ... لجارية من جواري مضر)\n(خدلجة الساق ممكورة ... سلوس الوشاح كمثل القمر)\n(تزين النساء إذا ما بدت ... ويبهت في وجهها من نظر)\nالشعر ليزيد بن معاوية والغناء لابن سريج رمل بالبنصر عن يونس وحبش قال إسحاق وذكر المدائني في خبره أن عمر بن عبد العزيز مر أيضا فسمع صوت ابن سريج وهو يتغنى\n(بت الخليط قوى الحبل الذي قطعوا ... )\nقال عمر لله در هذا الصوت لو كان بالقرآن قال المدائني وبلغني من وجه آخر أنه سمعه يغني\n(قرب جيراننا جمالهم ... ليلا فأضحوا معا قد ارتفعوا)\n(ما كنت أدري بوشك بينهم ... حتى رأيت الحداة قد طلعوا)\nقال هذه المقالة","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":5,"spl":"ابن سريج يغني في طريق الحاج — ابن الزبير يؤخذ بغناء ابن سريج","partial":1},
{"id":"b3-13","bab":"الجزء 1","sec":"نسبة هذين الصوتين","page":"ج1 ص259","text":"صوت\n(بت الخليط قوى الحبل الذي قطعوا ... إذ ودعوك فولوا ثم ما رجعوا)\nوآذنوك ببين من وصالهم ... فما سلوت ولا يسليك ما صنعوا يابن الطويل وكم آثرت من حسن ... فينا وأنت بما حملت مضطلع نحظى ونبقى بخير ما بقيت لنا ... فإن هلكت فما في ملجأ طمع\nالشعر للأحوص والغناء لابن سريج رمل بالسبابة في مجرى البنصر عن إسحاق وذكر حبش أن فيه رملا بالوسطى عن الهشامي","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":6,"spl":"نسبة هذين الصوتين — صوت من المائة المختارة من رواية جحظة"},
{"id":"b3-14","bab":"الجزء 1","sec":"نسبة الصوت الآخر","page":"ج1 ص259","text":"صوت\n(قرب جيراننا جمالهم ... ليلا فأضحوا معا قد ارتفعوا)\n(ما كنت أدري بوشك بينهم ... حتى رأيت الحداة قد طلعوا)\n(على مصكين من جمالهم ... وعنتريسين فيهما خضع)\n(يا قلب صبرا فإنه سفه ... بالحر أن يستفزه الجزع)\nلغناء لان سريج ثقيل أول من أصوات قليلة الأشباه عن إسحاق وفيه رمل بالسبابة في مجرى الوسطى ذكره إسحاق ولم ينسبه إلى أحد وذكر أيضا فيه خفيف رمل بالسبابة في مجرى الوسطى ولم ينسبه وذكر الهشامي أن الرمل للغريض وخفيف الرمل لابن المكي وذكرت دنانير والهشامي أن فيه لمعبد ثاني ثقيل وذكر عمرو بن بانة أن الثقيل الأول للغريض وذكر عبد الله بن موسى أن لحن ابن سريج خفيف ثقيل","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":6,"spl":"نسبة هذين الصوتين — صوت من المائة المختارة من رواية جحظة"},
{"id":"b3-15","bab":"الجزء 1","sec":"عدد الأصوات التي غنى فيها ابن سريج","page":"ج1 ص260","text":"أخبرني رضوان بن أحمد الصيدلاني قال حدثني يوسف بن إبراهيم قال\nحضرت أبا إسحاق إبراهيم بن المهدي وعنده إسحاق الموصلي فقال إسحاق غنى ابن سريج ثمانية وستين صوتا فقال له أبو إسحاق ما تجاوز قط ثلاثة وستين صوتا فقال بلى ثم جعلا ينشدان أشعار الصحيح منها حتى بلغا ثلاثة وستين صوتا وهما يتفقان على ذلك ثم أنشد إسحاق بعد ذلك أشعار خمسة أصوات أيضا فقال أبو إسحاق صدقت هذا من غنائه ولكن لحن هذا الصوت نقله من لحنيه في الشعر الفلاني ولحن الثاني من لحنه الفلاني حتى عد له الخمسة الأصوات فقال له إسحاق صدقت ثم قال له إبراهيم إن ابن سريج كان رجلا عاقلا أديبا وكان يغني الناس بما يشتهون فلا يغنيهم صوتا مدح به أعداؤهم ولا صوتا عليهم فيه عار أو غضاضة ولكنه يعدل بتلك الألحان إلى أشعار في أوزانها فالصوتان واحد لا ينبغي أن نعدهما اثنين عند التحصيل منا لغنائه فصدقه إسحاق فقال له إبراهيم فأيها أولى عندك بالتقدمة فقال\n(وإذا ما عثرت في مرطها ... نهضت باسمي وقالت يا عمر)\nقال له إبراهيم أحسبك يا أبا محمد متعت بك ما أردت إلا مساعدتي فقال لا والله ما إلى هذا قصدت وإن كنت أهوى كل ما قربني من محبتك فقال له هذا أحب أغانيه إلي وما أحسبه في مكان أحسن منه عندي ولا كان ابن سريج يتغناه أحسن مما يتغناه جواري ولئن كان كذلك فما هو عندي في حسن التجزئة والقسمة وصحتهما مثل لحنه في","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":6,"spl":"نسبة هذين الصوتين — صوت من المائة المختارة من رواية جحظة"},
{"id":"b3-16","bab":"الجزء 1","sec":"صوت من المائة المختارة من رواية جحظة","page":"ج1 ص261","text":"(حييا أم يعمرا ... قبل شحط من النوى)\n(أجمع الحي رحلة ... ففؤادي كذي الأسى)\n(قلت لا تعجلوا الرواح ... فقالوا ألا بلى)\nلغناء لابن سريج من القدر الأوسط من الثقيل الأول مطلق في مجرى الوسطى وفيه للهذلي خفيف ثقيل بالبنصر عن ابن المكي وفيه لمالك ثقيل أول بالبنصر عن عمرو وفيه لحنان من الثقيل الثاني أحدهما لإسحاق والآخر لأبيه ونسبه قوم إلى ابن محرز ولم يصح ذلك قال فاجتمعا معا على أنه أول أغانيه وأحقها بالتقديم وأمرني أبو إسحاق بتدوين ما يجري بينهما ويتفقان عليه فكتبت هذا الشعر ثم اتفقا على أن الذي يليه\n(وإذا ما عثرت في مرطها ... نهضت باسمي وقالت يا عمر)\nأثبته أيضا ثم تناظرا في الثالث فاجتمعا على أنه\n(فتركته جزر السباع ينشنه ... ما بين قلة رأسه والمعصم)\nفقال إسحاق لو قدمناه على الأغاني التي تقدمته كلها لكان يستحق ذلك فقال أبو إسحاق ما سمعته منذ عرفته إلا أبكاني لأني إذا سمعته أو ترنمت به وجدت غمرا على فؤادي لا يسكن حتى أبكي فقال إسحاق إن مذهبه فيه ليوجب ذلك فدونته ثالثا ثم اتفقا على الرابع وأنه\n(فلم أر كالتجمير منظر ناظر ... ولا كليالي الحج أفتن ذا هوى)\nتحدثا بأحاديث لهذا الصوت مشهورة ثم تناظرا في الخامس فاتفقا على أنه\n(عوجي علينا ربة الهودج ... إنك إلا تفعلي تحرجي)\nفأثبته ثم تناظرا في السادس واتفقا على أنه\n(ألا هل هاجك الأظعان ... إذ جاوزن مطلحا)\nأثبته ثم تناظرا في السابع فاتفقا على أنه\n(غيضن من عبراتهن وقلن لي ... ماذا لقيت من الهوى ولقينا)\nأثبته وتناظرا في الثامن فاتفقا على أنه\n(تنكر الإثمد لا تعرفه ... غير أن تسمع منه بخبر)\nأثبته وتناظرا في التاسع فاتفقا على أنه\n(ومن أجل ذات الخال أعملت ناقتي ... أكلفها سير الكلال مع الظلع)","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":6,"spl":"نسبة هذين الصوتين — صوت من المائة المختارة من رواية جحظة"},
{"id":"b3-17","bab":"الجزء 1","sec":"نسبة هذه الأصوات وأجناسها","page":"ج1 ص263","text":"منها صوت\n(وإذا ما عثرت في مرطها ... نهضت باسمي وقالت يا عمر)\nلشعر لعمر بن أبي ربيعة والغناء لابن سريج خفيف رمل بالوسطى عن الهشامي ومنها صوت\n(فتركته جزر السباع ينشن ... ما بين قلة رأسه والمعصم)\nالشعر لعنترة بن شداد العبسي والغناء لابن سريج ثقيل أول بالوسطى عن عمرو ومنها صوت\n(فلم أر كالتجمير منظر ناظر ... ولا كليالي الحج أفتن ذا هوى)\nلشعر لعمر بن أبي ربيعة والغناء لابن سريج رمل بالوسطى عن عمرو ومنها صوت\n(عوجي علينا ربة الهودج ... إنك إلا تفعلي تحرجي)\nلشعر للعرجي والغناء لابن سريج ثقيل بالوسطى عن عمرو ومنها صوت\n(ألا هل هاجك الأظعان ... إذ جاوزن مطلحا)\nلشعر لعمر والغناء لابن سريج ثقيل أول مطلق في مجرى البنصر عن إسحاق وفيه للغريض لحنان ثقيل ثقيل أول بالوسطى في مجراها عن إسحاق وخفيف ثقيل بالوسطى عن عمرو وفيه لمعبد ثقيل أول ثالث بالخنصر في مجرى الوسطى عن إسحاق ومنها صوت\n(غيضن من عبراتهن وقلن لي ... ماذا لقيت من الهوى ولقينا)\nالشعر لجرير والغناء لابن سريج رمل بالبنصر وفيه لإسحاق رمل بالوسطى وفيه للهذلي ثاني ثقيل بالوسطى عن الهشامي ومنها صوت\n(تنكر الإثمد لا تعرفه ... غير أن تسمع منه بخبر)\nلشعر لعبد الرحمن بن حسان والغناء لابن سريج رمل بالوسطى ومنها صوت\n(ومن أجل ذات الخال أعملت ناقتي ... أكلفها سير الكلال مع الظلع)\nلشعر لعمر بن أبي ربيعة والغناء لابن سريج رمل بالبنصر وفيه لإسحاق رمل بالوسطى","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":7,"spl":"نسبة هذه الأصوات وأجناسها — نسبة هذه الأغاني كلها"},
{"id":"b3-18","bab":"الجزء 1","sec":"مالك ومعبد يحتكمان إلى ابن سريج في صوتين لهما","page":"ج1 ص265","text":"أخبرني رضوان بن أحمد قال حدثنا يوسف بن إبراهيم قال حدثني أبو إسحاق إبراهيم بن المهدي قال حدثني الزبير بن دحمان أن أباه حدثه\nأن معبدا تغنى\n(آب ليلي بهموم وفكر ... من حبيب هاج حزني والسهر)\n(يوم أبصرت غرابا واقعا ... شر ما طار على شر الشجر)\nعارضه مالك فغنى في أبيات من هذا الشعر وهي\n(وجرت لي ظبية يتبعها ... لين الأظلاف من حور البقر)\n(كلما كفكفت مني عبرة ... فاضت العين بمنهل درر)\nال فتلاحيا جميعا فيما صنعناه من هذين الصوتين فقال كل واحد منهما لصاحبه أنا أجود صنعة منك فتنافرا إلى ابن سريج فمضيا إليه بمكة فلما قدماها سألا عنه فأخبرا أنه خرج يتطرف بالحناء في بعض بساتينها فاقتفيا أثره حتى وقفا عليه وفي يده الحناء فقالا له إنا خرجنا إليك من المدينة لتحكم بيننا في صوتين صنعناهما فقال لهما ليغن كل واحد منكما صوته فابتدأ معبد يغني لحنه فقال له أحسنت والله على سوء اختيارك للشعر يا ويحك ما حملك على أن ضيعت هذه الصنعة الجيدة في حزن وسهر وهموم وفكر أربعة ألوان من الحزن في بيت واحد وفي البيت الثاني شران في مصراع واحد وهو قولك\n(شر ما طار على شر الشجر ... )\nم قال لمالك هات ما عندك فغناه مالك فقال له أحسنت والله ما شئت فقال له مالك هذا وإنما هو ابن شهره فكيف تراه يا أبا يحيى يكون إذا حال عليه الحول قال دحمان فحدثني معبد أن ابن سريج غضب عند ذلك غضبا شديدا ثم رمى بالحناء من يديه وأصابعه وقال له يا مالك إلي تقول ابن شهره اسمع مني ابن ساعته ثم قال يا أبا عباد أنشدني القصيدة التي تغنيتما فيها فأنشدته القصيدة حتى انتهيت إلى قوله\n(تنكر الإثمد لا تعرفه ... غير أن تسمع منه بخبر)\nفصاح بأعلى صوته هذا خليلي وهذا صاحبي ثم تغنى فيه فانصرفنا مفلولين مفضوحين من غير أن نقيم بمكة ساعة واحدة","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":7,"spl":"نسبة هذه الأصوات وأجناسها — نسبة هذه الأغاني كلها","partial":1},
{"id":"b3-19","bab":"الجزء 1","sec":"نسبة هذه الأغاني كلها","page":"ج1 ص267","text":"صوت\n(آب ليلي بهموم وفكر ... من حبيب هاج حزني والسهر)\n(يوم أبصرت غرابا واقعا ... شر ما طار على شر الشجر)\n(ينتف الريش على عبرية ... مرة المقضم من دوح العشر)\nلشعر لعبد الرحمن بن حسان بن ثابت يقوله في رملة بنت معاوية بن أبي سفيان وله معها ومع أبيها وأخيها في تشبيبه بها أخبار كثيرة ستذكر في موضعها إن شاء الله ومن الناس من ينسب هذا الشعر إلى عمر بن أبي ربيعة وهو غلط وقد بين ذلك مع أخبار عبد الرحمن في موضعه والغناء لمعبد خفيف ثقيل أول بالوسطى عن يحيى المكي وذكر عمرو بن بانة أنه للغريض وله لحن آخر في هذه الطريقة صوت\n(وجرت لي ظبية يتبعها ... لين الأظلاف من حور البقر)\n(خلفها أطلس عسال الضحى ... صادفته يوم طل وخصر)\nلغناء لمالك خفيف ثقيل بالبنصر في مجراها عن إسحاق\nصوت\n(إن عينيها لعينا جؤذر ... أهدب الأشفار من حور البقر)\n(تنكر الإثمد لا تعرفه ... غير أن تسمع منه بخبر)\nالغناء لابن سريج رمل بالسبابة عن عمرو ويحيى المكي","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":7,"spl":"نسبة هذه الأصوات وأجناسها — نسبة هذه الأغاني كلها"},
{"id":"b3-20","bab":"الجزء 1","sec":"نقائض الغريض وابن سريج","page":"ج1 ص268","text":"أخبرني الحسين بن يحيى قال قال حماد قال أبي قال محمد بن سعيد لما ضاد ابن سريج الغريض وناوأه جعل ابن سريج لا يغني صوتا إلا عارضه فيه الغريض فغنى فيه لحنا غيره وكانت ببعض أطراف مكة دار يأتيانها في كل جمعة ويجتمع لهما ناس كثير فيوضع لكل واحد منهما كرسي يجلس عليه ثم يتناقضان الغناء ويترادانه قال فلما رأى ابن سريج موقع الغريض وغنائه من الناس لقربه من النوح وشبهه به مال إلى الأرمال والأهزاج فاستحفها الناس فقال له الغريض يا أبا يحيى قصرت الغناء وحذفته وأفسدته فقال له نعم يا مخنث جعلت تنوح على أبيك وأمك ألي تقول هذا والله لأغنين غناء ما غنى أحد أثقل منه ولا أجود ثم تغنى\n(تشكى الكميت الجري لما جهدته ... )\nال حماد وقرأت على أبي عن هشام بن المرية قال كان ابن أبي عتيق\nيسوق في كل عام عن ابن سريج بدنة وينحرها عنه ويقول هذا أقل حقه علينا","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":8,"spl":"نقائض الغريض وابن سريج — أبو السائب المخزومي وأغاني ابن سريج","partialRef":{"sid":"b1-1","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b3-21","bab":"الجزء 1","sec":"معبد يعترف لابن سريج بالسبق","page":"ج1 ص268","text":"قال حماد قال أبي وقال مخلد بن خداش المهلبي كنا بالمدينة في مجلس لنا ومعنا معبد فقدم قادم من مكة إلى المدينة فدخل علينا ليلا فجلس معبد يسائله عن الأخبار وهو يخبره ولا نسمع ما يقول فالتفت إلينا معبد فقال أصبحت أحسن الناس غناء فقيل له أو لم تكن كذلك قال لا حيث كان ابن سريج حيا إن هذا أخبرني أن ابن سريج قد مات ثم كان بعد ذلك إذا غنى صوتا فأعجبه غناؤه قال أصبحت اليوم سريجيا","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":8,"spl":"نقائض الغريض وابن سريج — أبو السائب المخزومي وأغاني ابن سريج"},
{"id":"b3-22","bab":"الجزء 1","sec":"أبو السائب المخزومي وأغاني ابن سريج","page":"ج1 ص269","text":"قال حماد حدثني أبي قال حدثني أبو الحسن المدائني قال قال معبد أتيت أبا السائب المخزومي وكان يصلي في كل يوم وليلة ألف ركعة فلما رآني تجوز وقال ما معك من مبكيات ابن سريج قلت قوله\n(ولهن بالبيت العتيق لبانة ... والبيت يعرفهن لو يتكلم)\n(لو كان حيا قبلهن ظعائنا ... حيا الحطيم وجوههن وزمزم)\n(لبثوا ثلاث منى بمنزل غبطة ... وهم على سفر لعمرك ما هم)\n(متجاورين بغير دار إقامة ... لو قد أجد تفرق لم يندموا)\nقال لي غنه فغنيته ثم قام يصلي فأطال ثم تجوز إلي فقال ما معك من مطرباته ومشجياته فقلت قوله\n(لسنا نبالي حين ندرك حاجة ... ما بات أو ظل المطي معقلا)\nقال لي غنه فغنيته ثم صلى وتجوز إلي وقال ما معك من مرقصاته فقلت\n(فلم أر كالتجمير منظر ناظر ... ولا كليالي الحج أفتن ذا هوى)\nقال كما أنت حتى أتحرم لهذا بركعتين","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":8,"spl":"نقائض الغريض وابن سريج — أبو السائب المخزومي وأغاني ابن سريج"},
{"id":"b3-23","bab":"الجزء 1","sec":"تفضيل عطاء بن أبي رباح ابن سريج على الغريض","page":"ج1 ص270","text":"قال حماد وأخبرني أبي عن إبراهيم بن المنذر الحزامي وذكر أبو أيوب المديني عن الحزامي قال حدثني عبد الرحمن بن إبراهيم المخزومي قال أرسلتني أمي وأنا غلام أسأل عطاء بن أبي رباح عن مسألة فوجدته في دار يقال لها دار المعلى وقال أبو أيوب في خبره دار المقل وعليه ملحفة معصفرة وهو جالس على منبر وقد ختن ابنه والطعام يوضع بين يديه وهو يأمر به أن يفرق في الخلق فلهوت مع الصبيان ألعب بالجوز حتى أكل القوم وتفرقوا وبقي مع عطاء خاصته فقالوا يا أبا محمد لو أذنت لنا فأرسلنا إلى الغريض وابن سريج فقال ما شئتم فأرسلوا إليهما فلما أتيا قاموا معهما وثبت عطاء في مجلسه فلم يدخل فدخلوا بهما بيتا في الدار فتغنيا وأنا أسمع فبدأ ابن سريج فنقر بالدف وتغنى بشعر كثير\n(بليلى وجارات لليلى كأنها ... نعاج الملا تحدى بهن الأباعر)\n(أمنقطع يا عز ما كان بيننا ... وشاجرني يا عز فيك الشواجر)\n(إذا قيل هذا بيت عزة قادني ... إليه الهوى واستعجلتني البوادر)\n(أصد وبي مثل الجنون لكي يرى ... رواة الخنا أني لبيتك هاجر)\nكأن القوم قد نزل عليهم السبات وأدركهم الغشي فكانوا كالأموات ثم أصغوا إليه بآذانهم وشخصت إليه أعينهم وطالت أعناقهم ثم غنى الغريض بصوت أنسيته بلحن آخر ثم غنى ابن سريج وأوقع بالقضيب وأخذ الغريض الدف فغنى بشعر الأخطل\n(فقلت اصبحونا لا أبا لأبيكم ... وما وضعوا الأثقال إلا ليفعلوا)\n(وقلت اقتلوها عنكم بمزاجها ... فأكرم بها مقتولة حين تقتل)\n(أناخوا فجروا شاصيات كأنها ... رجال من السودان لم يتسربلوا)\nوالله ما رأيتهم تحركوا ولا نطقوا إلا مستمعين لما يقول ثم غنى الغريض بشعر آخر وهو\n(هل تعرف الرسم والأطلال والدمنا ... زدن الفؤاد على ما عنده حزنا)\n(دار لصفراء إذ كانت تحل بها ... وإذ ترى الوصل فيما بيننا حسنا)\n(إذ تستبيك بمصقول عوارضه ... ومقلتي جؤذر لم يعد أن شدنا)\nثم غنيا جميعا بلحن واحد فلقد خيل لي أن الأرض تميد وتبينت ذلك في عطاء أيضا وغنى الغريض في شعر عمر بن أبي ربيعة وهو قوله\n(كفى حزنا أن تجمع الدار شملنا ... وأمسي قريبا لا أزورك كلثما)\n(دعي القلب لا يزدد خبالا مع الذي ... به منك أو داوي جواه المكتما)\n(ومن كان لا يعدو هواه لسانه ... فقد حل في قلبي هواك وخيما)\n(وليس بتزويق اللسان وصوغه ... ولكنه قد خالط اللحم والدما)\nغنى ابن سريج أيضا\n(خليلي عوجا نسأل اليوم منزلا ... أبى بالبراق العفر أن يتحولا)\n(ففرع النبيت فالشرى خف أهله ... وبدل أرواحا جنوبا وشمألا)\n(أرادت فلم تسطع كلاما فأومأت ... إلينا ولم تأمن رسولا فترسلا)\n(بأن بت عسى أن يستر الليل مجلسا ... لنا أو تنام العين عنا فتقبلا)\nغنى الغريض أيضا\n(يا صاحبي قفا نقض لبانة ... وعلى الظعائن قبل بينكما اعرضا)\n(لا تعجلاني أن أقول بحاجة ... رفقا فقد زودت زادا مجرضا)\n(ومقالها بالنعف نعف محسر ... لفتاتها هل تعرفين المعرضا)\n(هذا الذي أعطى مواثق عهده ... حتى رضيت وقلت لي لن ينقضا)\nوأغاني أنسيتها وعطاء يسمع على منبره ومكانه وربما رأيت رأسه قد مال وشفتيه تتحركان حتى بلغته الشمس فقام يريد منزله فما سمع السامعون شيئا أحسن منهما وقد رفعا أصواتهما وتغنيا بهذا ولما بلغت الشمس عطاء قام وهم على طريقة واحدة في الغناء فاطلع في كوة البيت فلما رأوه قالوا يا أبا محمد أيهما أحسن غناء قال الرقيق الصوت يعني ابن سريج","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":9,"spl":"تفضيل عطاء بن أبي رباح ابن سريج على الغريض"},
{"id":"b3-24","bab":"الجزء 1","sec":"نسبة ما في هذه الأخبار من الأصوات","page":"ج1 ص273","text":"صوت\n(ولهن بالبيت العتيق لبانة ... والبيت يعرفهن لو يتكلم)\n(لو كان حيا قبلهن ظعائنا ... حيا الحطيم وجوههن وزمزم)\n(وكأنهن وقد حسرن لواغبا ... بيض بأكناف الحطيم مركم)\n(لبثوا ثلاث منى بمنزل غبطة ... وهم على سفر لعمرك ما هم)\n(متجاورين بغير دار إقامة ... لو قد أجد رحيلهم لم يندموا)\nعروضه من الكامل الشعر لابن أذينة والغناء لابن سريج ثاني ثقيل مطلق\nفي مجرى البنصر عن إسحاق وأخبار ابن أذينة تأتي بعد هذا في موضعها إن شاء الله ومنها الصوت الذي أوله في الخبر\n(لسنا نبالي حين ندرك حاجة ... )\nوت\n(ودع لبابة قبل أن تترحلا ... واسأل فإن قليله أن تسألا)\n(وانظر بعينك ليلة وتأنها ... فلعل ما بخلت به أن يبذلا)\n(لسنا نبالي حين ندرك حاجة ... ما راح أو ظل المطي معقلا)\n(حتى إذا ما الليل جن ظلامه ... ورجوت غفلة حارس أن يعقلا)\n(خرجت تأطر في الثياب كأنها ... أيم يسيب على كثيب أهيلا)\nلشعر لعمر بن أبي ربيعة والغناء لابن سريج ثقيل أول بالوسطى في مجراها وفيه لمعبد لحن من خفيف الثقيل الأول بإطلاق الوتر في مجرى الوسطى وهو من مختار أغانيه ونادرها وصدور صنعته وما يقدم على كثير منها","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":10,"spl":"نسبة ما في هذه الأخبار من الأصوات","partialRef":{"sid":"b3-22","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b3-25","bab":"الجزء 1","sec":"الغمر بن يزيد وشعر عمر بن أبي ربيعة","page":"ج1 ص274","text":"أخبرني أحمد بن محمد بن إسحاق الحرمي قال حدثنا الزبير بن بكار قال حدثني عبد الرحمن بن عبد الله الزهري عن عبد الله بن عمران بن أبي فروة قال كنت أسير مع الغمر بن يزيد فاستنشدني فأنشدته لعمر بن أبي ربيعة\n(ودع لبابة قبل أن تترحلا ... واسأل فإن قليله أن تسألا)\n(قال ائتمر ما شئت غير مخالف ... فيما هويت فإننا لن نعجلا)\n(نجزي أيادي كنت تبذلها لنا ... حق علينا واجب أن نفعلا)\n(حتى إذا ما الليل جن ظلامه ... ورجوت غفلة حارس أن يعقلا)\n(خرجت تأطر في الثياب كأنها ... أيم يسيب على كثيب أهيلا)\n(رحبت لما أقبلت فتعللت ... لتحيتي لما رأتني مقبلا)\n(فجلا القناع سحابة مشهورة ... غراء تعشي الطرف أن يتأملا)\n(فظللت أرقيها بما لو عاقل ... يرقى به ما اسطاع ألا ينزلا)\n(تدنو فأطمع ثم تمنع بذلها ... نفس أبت للجود أن تتبخلا)\nال فأمر غلامه فحملني على بغلته التي كانت تحته فلما أراد الانصراف طلب الغلام مني البغلة فقلت لا أعطيكها هو أكرم وأشرف من أن يحملني عليها ثم ينتزعها مني فقال للغلام دعه يا بني ذهبت والله لبابة ببغلة مولاك أخبرني الحسين بن يحيى عن حماد عن أبيه وأخبرنيه الحسن بن علي عن هارون بن الزيات عن حماد عن أبيه قال حدثني عثمان بن حفص الثقفي عن إبراهيم بن عبد السلام بن أبي الحارث عن ابن تيزن المغني قال قال أبو نافع الأسود وكان آخر من بقي من غلمان ابن سريج إذا أعجزك أن تطرب القرشي فغنه غناء ابن سريج في شعر عمر بن أبي ربيعة فإنك ترقصه قال وأبو نافع هذا أحذق غلمان ابن سريج ومن أخذ عنه وكان أحسن رواته صوتا ومنها صوت\n(بليلى وجارات لليلى كأنها ... نعاج الملا تحدى بهن الأباعر)\n(أمنقطع يا عز ما كان بيننا ... وشاجرني يا عز فيك الشواجر)\n(إذا قيل هذا بيت عزة قادني ... إليه الهوى واستعجلتني البوادر)\n(أصد وبي مثل الجنون لكي يرى ... رواة الخنا أني لبيتك هاجر)\n(ألا ليت حظي منك يا عز أنني ... إذا بنت باع الصبر لي عنك تاجر)\nروضه من الطويل الشعر لكثير والغناء لمعبد ثقيل أول بالبنصر على مذهب إسحاق من رواية عمرو وفيه لابن سريج لحن أوله أصد وبي مثل الجنون خفيف رمل بالخنصر في مجرى الوسطى عن إسحاق ومنها صوت\n(أناخوا فجروا شاصيات كأنها ... رجال من السودان لم يتسربلوا)\n(فقلت اصبحوني لا أبا لأبيكم ... وما وضعوا الأثقال إلا ليفعلوا)\n(تمر بها الأيدي سنيحا وبارحا ... وترفع باللهم حي وتنزل)\nروضه من الطويل الشاصيات الشائلات قوائمها من امتلائها يعني الزقاق يقال شصا يشصو وشصا ببصره إذا رفعه كالشاخص وأنشد\n(وربرب خماص ... يطعن بالصياصي)\n(ينظر من خصاص ... بأعين شواصي)\n(كفلق الرصاص ... تسمو إلى القناص)\nالشعر للأخطل وذكره يأتي في غير هذا الموضع من قصيدة يمدح بها خالد بن عبد الله بن أسيد بن أبي العيص بن أمية والغناء لمالك وله فيه لحنان أحدهما في الأول والثاني رمل بالبنصر في مجراها عن إسحاق والآخر في الثالث والأول والثاني خفيف رمل بالوسطى عن عمرو وفيه لابن سريج رمل بالوسطى عن عمرو وفيه لابن محرز خفيف ثقيل أول بالبنصر في مجراها وفيه رمل آخر لإبراهيم عن عمرو أيضا ومنها صوت\n(هل تعرف الرسم والأطلال والدمنا ... )\nذكر الأبيات الثلاثة وقد تقدمت عروضه من البسيط الشعر لذي الإصبع العدواني والغناء لابن عائشة ثاني ثقيل بالبنصر ومنها صوت\n(كفى حزنا أن تجمع الدار شملنا ... )\nوت","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":11,"spl":"الغمر بن يزيد وشعر عمر بن أبي ربيعة — وهو من المائة المختارة في رواية جحظة عن أصحابه","partialRef":{"sid":"b3-23","gi":3,"vi":0,"side":0},"partial":1}]);
window.__BOOK__['p01'].push([{"id":"b3-26","bab":"الجزء 1","sec":"وهو من المائة المختارة في رواية جحظة عن أصحابه","page":"ج1 ص277","text":"(دعي القلب لا يزدد خبالا مع الذي ... به منك أو داوي جواه المكتما)\n(ومن كان لا يعدو هواه لسانه ... فقد حل في قلبي هواك وخيما)\n(وليس بتزويق اللسان وصوغه ... ولكنه قد خالط اللحم والدما)\nروضه من الطويل الشعر للأحوص وقيل إنه لسعيد بن عبد الرحمن\nابن حسان والغناء لمعبد ثقيل أول بإطلاق الوتر في مجرى البنصر وذكر يونس أن لمالك لحنا فيه\n(أكلثم فكي عانيا بك مغرما ... وشدي قوى حبل لنا قد تصرما)\n(فإن تسعفيه مرة بنوالكم ... فقد طالما لم ينج منك مسلما)\n(كفى حزنا أن تجمع الدار شملنا ... وأمسي قريبا لا أزورك كلثما)\nبعده هذه الأبيات التي مضت","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":11,"spl":"الغمر بن يزيد وشعر عمر بن أبي ربيعة — وهو من المائة المختارة في رواية جحظة عن أصحابه"},
{"id":"b3-27","bab":"الجزء 1","sec":"إجماع المغنين على تفضيل لحن ابن سريج وليس بتزويق اللسان","page":"ج1 ص278","text":"أخبرني الحسين بن يحيى قال قال حماد وذكر الثقفي عن دحمان قال تذاكرنا ونحن في المسجد أنا والربيع بن أبي الهيثم الغناء أيه أحسن فجعل يقول وأقول فلا نجتمع على شيء فقلت اذهب بنا إلى مالك بن أبي السمح فذهبنا إليه فوجدناه في المسجد فقال ما جاء بكما فأخبرناه فقال قد جرى هذا بيني وبين معبد وقال وقلت فجاءني معبد يوما وأنا في المسجد وقال قد جئتك بشيء لا ترده فقلت وما هو قال لحن ابن سريج\n(وليس بتزويق اللسان وصوغه ... ولكنه قد خالط اللحم والدما)\nم قال لي معبد أسمعكه قلت نعم وأريته أني لم أسمعه قبل فقال اسمعه مني فغنى فيه ونحن في المسجد فما سمعت شيئا قط أحسن منه فافترقنا وقد اجتمعنا عليه وقرأت في فصل لإبراهيم بن المهدي إلى إسحاق الموصلي وكتبت رقعتي هذه وأنا في غمرة من الحمى تصدف عن المفترضات ولولا خوفي في تشنيعك وتجنيك لم يكن في للإجابة فضل غير أني قد تكلفت الجواب على ما\nالله به عالم من صعوبة علتي وما أقاسيه من الحرارة الحادثة بي\n(وليس بتزويق اللسان وصوغه ... ولكنه قد خالط اللحم والدما)","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":12,"spl":"إجماع المغنين على تفضيل لحن ابن سريج وليس بتزويق اللسان — تفضيل غناء ابن سريج على غناء معب"},
{"id":"b3-28","bab":"الجزء 1","sec":"تفضيل غناء ابن سريج على غناء معبد ومالك","page":"ج1 ص279","text":"وقال إسحاق حدثني شيخ من موالي المنصور قال قدم علينا فتيان من بني أمية يريدون مكة فسمعوا معبدا ومالكا فأعجبوا بهما ثم قدموا مكة فسألوا عن ابن سريج فوجدوه مريضا فأتوا صديقا له فسألوه أن يسمعهم غناءه فخرج معهم حتى دخلوا عليه فقالوا نحن فتيان من قريش أتيناك مسلمين عليك وأحببنا أن نسمع منك فقال أنا مريض كما ترون فقالوا إن الذي نكتفي منك به يسير وكان ابن سريج أديبا طاهر الخلق عارفا بأقدار الناس فقال يا جارية هاتي جلبابي وعودي فأتته خادمه بخامة فسدلها على وجهه وكان يفعل ذلك إذا تغنى لقبح وجهه ثم أخذ العود فغناهم فأرخى ثوبه على عينيه وهو يغني حتى إذا اكتفوا ألقى عوده وقال معذرة فقالوا نعم قد قبل الله عذرك فأحسن الله إليك ومسح ما بك وانصرفوا يتعجبون مما سمعوا فمروا بالمدينة منصرفين فسمعوا من معبد ومالك فجعلوا لا يطربون لهما ولا يعجبون بهما كما كانوا يطربون فقال أهل المدينة نحلف بالله لقد سمعتم بعدنا ابن سريج قالوا أجل لقد سمعناه فسمعنا ما لم نسمع مثله قط ولقد نغص علينا ما بعده ذكر العتابي أن زكريا بن يحيى حدثه قال حدثني عبد الله بن محمد بن عثمان العثماني عن بعض أهل الحجاز قال التقى قنديل الجصاص وأبو الجديد بشعب الصفراء فقال قنديل لأبي الجديد من أين وإلى أين قال مررت برقطاء\nالحبطية رائحة تترنم برمل ابن سريج في شعر ابن عمارة السلمي صوت\n(سقى مأزمي نجد إلى بئر خالد ... فوادي نصاع فالقرون إلى عمد)\n(وجادت بروق الرائحات بمزنة ... تسح شآبيبا بمرتجز الرعد)\n(منازل هند إذ تواصلني بها ... ليالي تسبيني بمستطرف الود)\n(ينير ظلام الليل من حسن وجهها ... وتهدي بطيب الريح من جاء من نجد)\nالغناء لابن سريج رمل بالبنصر عن الهشامي فزففت خلفها زفيف النعامة فما انجلت غشاوتي إلا وأنا بالمشاش حسير فأودعتها قلبي وخلفته لديها وأقبلت أهوي كالرخمة بغير قلب فقال لي قنديل ما دفع أحد من المزدلفة أسعد منك سمعت شعر ابن عمارة في غناء ابن سريج من رقطاء الحبطية لقد أوتيت جزءا من النبوة قال وكانت رقطاء هذه من أضرب الناس فدخل رجل من أهل المدينة منزلها فغنته صوتا فقال له بعض من حضر هل رأيت قط أو ترى أفصح من وتر هذه فطرب المدني وقال علي العهد إن لم يكن وترها من معي\nبشكست النحوي فكيف لا يكون فصيحا وبشكست هذا كان نحويا بالمدينة وقتل مع الشراة الخارجين مع أبي حمزة صاحب عبد الله بن يحيى الكندي الشاري المعروف بطالب الحق","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":12,"spl":"إجماع المغنين على تفضيل لحن ابن سريج وليس بتزويق اللسان — تفضيل غناء ابن سريج على غناء معب"},
{"id":"b3-29","bab":"الجزء 1","sec":"غناء ابن سريج مخلوق من قلوب الناس جميعا","page":"ج1 ص281","text":"قال محمد بن الحسن وحدث عن إسحاق عن أبيه أنه كان يقول غناء كل مغن مخلوق من قلب رجل واحد وغناء ابن سريج مخلوق من قلوب الناس جميعا وكان يقول الغناء على ثلاثة أضرب فضرب مله مطرب يحرك ويستخف وضرب ثان له شجا ورقة وضرب ثالث حكمة وإتقان صنعة قال وكل هذا مصنوع في غناء ابن سريج قال العتابي وحدثني زكريا بن يحيى عن عبد الله بن محمد العثماني قال ذكر بعض أصحابنا الحجازيين قال التقى ابن سلمة الزهري والأخضر الجدي ببئر الفصح فقال ابن سلمة هل لك في الاجتماع نستمتع بك فقال له الأخضر لقد كنت إلى ذلك مشتاقا قال فقعدا يتحدثان فمر بهما أبو السائب فقال يا مطرب الحجاز ألشيء كان اجتماعكما فقالا لغير موعد كان ذلك أفتؤنسنا قال فقعدوا يتحدثون\nفلما مضى بعض الليل قال الأخضر لابن سلمة يا أبا الأزهر قد ابهار الليل وساعدك القمر فأوقع بقهقهة ابن سريج وأصب معناك فاندفع يغني صوت\n(تجنت بلا جرم وصدت تغضبا ... وقالت لتربيها مقالة عاتب)\n(سيعلم هذا أنني بنت حرة ... سأمنع نفسي من ظنون كواذب)\n(فقولي له عنا تنح فإننا ... أبيات فحش طاهرات المناسب)\nالغناء لابن سريج ولم يذكر طريقته قال فجعل أبو السائب يزفن ويقول أبشر حبيبي فلأنت أفضل من شهداء قزوين قال ثم قال ابن سلمة للأخضر نعم المساعد على هم الليل أنت فأوقع بنوح ابن سريج ولا تعد معناك فاندفع يغني صوت\n(فلما التقينا بالحجون تنفست ... تنفس محزون الفؤاد سقيم)\n(وقالت وما يرقا من الخوف دمعها ... أقاطنها أم أنت غير مقيم)\n(فإنا غدا تحدى بنا العيس بالضحى ... وأنت بما نلقاه غير عليم)\n(فقطع قلبي قولها ثم أسبلت ... محاجر عيني دمعها بسجوم)\nقال فجعل أبو السائب يتأفف ويقول أعتق ما أملك إن لم تكن فردوسية الطينة وإنها بعلمها لأفضل من آسية امرأة فرعون","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":13,"spl":"غناء ابن سريج مخلوق من قلوب الناس جميعا — غناء ابن سريج في موسم الحج"},
{"id":"b3-30","bab":"الجزء 1","sec":"تغني الذلفاء بلحن ابن سريج","page":"ج1 ص282","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه عن الهيثم بن عدي قال بلغني أن أبا دهبل الجمحي قال كنت أنا وأبو السائب المخزومي عند مغنية بالمدينة يقال لها الذلفاء فغنتنا بشعر جميل بن معمر العذري واللحن لابن سريج صوت\n(لهن الوجى لم كن عونا على النوى ... ولا زال منها ظالع وكسير)\n(كأني سقيت السم يوم تحملوا ... وجد بهم حاد وحان مسير)\nقال أبو السائب يا أبا دهبل نحن والله على خطر من هذا الغناء فنسأل الله السلامة وأن يكفينا كل محذور فما آمن أن يهجم بي على أمر يهتكني قال وجعل يبكي","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":13,"spl":"غناء ابن سريج مخلوق من قلوب الناس جميعا — غناء ابن سريج في موسم الحج"},
{"id":"b3-31","bab":"الجزء 1","sec":"غناء ابن سريج في موسم الحج","page":"ج1 ص283","text":"أخبرنا محمد بن خلف وكيع قال حدثنا الزبير بن بكار عن بكار بن رباح عن إسحاق بن مقمة عن أمه قالت سمعت ابن سريج على أخشب منى غداة النفر وهو يغني\n(جددي الوصل يا قريب وجودي ... لمحب فراقه قد ألما)\n(ليس بين الحياة والموت إلا ... أن يردوا جمالهم فتزما)\nنسبة هذا الصوت تأتي بعد هذه الأخبار قالت فما تشاء أن تسمع من خباء ولا مضرب حنينا ولا أنينا إلا سمعته ذكر يوسف بن إبراهيم أنه حضر إسحاق بن إبراهيم الموصلي ليلة وهو يذاكر إبراهيم بن المهدي إلا أن قال إسحاق في بعض مخاطبته إياه هذا صوت قد تمعبد فيه ابن سريج فقال له إبراهيم ما ظننت أنك يا أبا محمد مع علمك وتقدمك تقول مثل هذا في ابن سريج فكيف يجوز أن تقول تمعبد ابن سريج وإنما معبد إذا أحسن قال أصبحت سريجيا قد أغنى الله ابن سريج عن هذا ورفع قدره عن مثله وأعيذك بالله أن تستشعر مثله في ابن سريج قال فما رأيت إسحاق دفع ذلك ولا أباه ولا زاد على أن قال هي كلمة يقولها الناس لم أقلها اعتقادا لها فيه وإنما تكلمت بها على العادة","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":13,"spl":"غناء ابن سريج مخلوق من قلوب الناس جميعا — غناء ابن سريج في موسم الحج"},
{"id":"b3-32","bab":"الجزء 1","sec":"تفوق ابن سريج على سائر المغنين","page":"ج1 ص284","text":"أخبرني محمد بن خلف وكيع قال حدثنا محمد بن إسماعيل قال حدثنا محمد بن سلام قال قال لي شعيب بن صخر كان معبد إذا غنى فأجاد قال أنا اليوم سريجي حدثني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني محمد ابن سلام قال حدثنا شعيب بن صخر قال كان نعمان المغني عندي نازلا وكان يغني وكنت أراه يأتيه قوم قال أبو عبد الله فقلت له فأيهم كان أحذق قال\nلا أدري إلا أنهم كانوا إذا جاء ابن سريج سكتوا أخبرني الحسين بن يحيى عن حماد عن أبيه قال حدثني الهيثم بن عياش قال حدثني عبد الرحمن بن عيينة قال بينما نحن بمنى ونحن نريد الغدو إلى عرفات إذ أتانا الأحوص فقال أبيت بكم الليلة قلنا بالرحب والسعة فلما جنه الليل لم يلبث أن غاب عنا ثم عاد ورأسه يقطر ماء قلت ما لك قال صوت\n(تعرض سلماك لما حرمت ... ضل ضلالك من محرم)\n(تريد به البر يا ليته ... كفافا من البر والمأثم)\nلغناء لابن سريج ولم يجنسه قال قلت زنيت ورب الكعبة قال قل ما بدا لك ثم لقي ابن سريج فقال إني قد قلت بيتين حسنين أحب أن تغنيني بهما قال ما هما فأنشده إياهما فغنى بهما من ساعته ففتن من حضر ممن سمع صوته أخبرني الحسين بن يحيى عن حماد عن أبيه قال حدثني إسحاق بن يحيى ابن طلحة قال","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":14,"spl":"تفوق ابن سريج على سائر المغنين — قدوم جرير المدينة وارتحاله إلى مكة ليسمع ابن سريج"},
{"id":"b3-33","bab":"الجزء 1","sec":"قدوم جرير المدينة وارتحاله إلى مكة ليسمع ابن سريج","page":"ج1 ص285","text":"قدم جرير بن الخطفي المدينة ونحن يومئذ شباب نطلب الشعر فاحتشدنا له ومعنا أشعب فبينا نحن عنده إذ قام لحاجة وأقمنا لم نبرح وجاء\nالأحوص بن محمد الشاعر من قباء على حمار فقال أين هذا فقلنا قام لحاجة فما حاجتك إليه قال أريد والله أن أعلمه أن الفرزدق أشعر منه وأشرف قلنا ويحك لا تعرض له وانصرف فانصرف وخرج فجاء جرير فلم يكن بأسرع من أن أقبل الأحوص الشاعر فأقبل عليه فقال السلام عليك يا جرير قال جرير وعليك السلام فقال الأحوص يابن الخطفي الفرزدق أشرف منك وأشعر قال جرير من هذا أخزاه الله قلنا الأحوص بن محمد بن عاصم بن ثابت بن أبي الأقلح فقال نعم هذا الخبيث ابن الطيب أأنت القائل\n(يقر بعيني ما يقر بعينها ... وأحسن شيء ما به العين قرت)\nال نعم قال فإنه يقر بعينها أن يدخل فيها مثل ذراع البكر أفيقر ذلك بعينك قال وكان الأحوص يرمي بالحلاق فانصرف فبعث إليهم بتمر وفاكهة وأقبلنا على جرير نسائله وأشعب عند الباب وجرير في مؤخر البيت فألح عليه أشعب يسأل فقال والله إني لأراك أقبحهم وجها وأراك ألأمهم حسبا فقد أبرمتني منذ اليوم قال إني والله أنفعهم وخيرهم لك فانتبه جرير وقال ويحك كيف ذاك قال إني أملح شعرك وأجيد مقاطعه ومبادئه فقال قل ويحك فاندفع أشعب فنادى بلحن ابن سريج\n(يا أخت ناجية السلام عليكم ... قبل الرحيل وقبل عذل العذل)\n(لو كنت أعلم أن آخر عهدكم ... يوم الرحيل فعلت ما لم أفعل)\nطرب جرير وجعل يزحف نحوه حتى ألصق بركبته ركبته وقال لعمري لقد صدقت إنك لأنفعهم لي وقد حسنته وأجدته وزينته أحسنت والله ثم وصله\nوكساه فلما رأينا إعجاب جرير بذلك الصوت قال له بعض أهل المجلس فكيف لو سمعت واضع هذا الغناء قال أو إن له لواضعا غير هذا فقلنا نعم قال فأين هو قلنا بمكة قال فلست بمفارق حجازكم حتى أبلغه فمضى ومضى معه جماعة ممن يرغب في طلب الشعر في صحابته وكنت فيهم فأتيناه جمعيا فإذا هو في فتية من قريش كأنهم المها مع ظرف كثير فأدنوا ورحبوا وسألوا عن الحاجة فأخبرناهم الخبر فرحبوا بجرير وأدنوه وسروا بمكانه وأعظم عبيد بن سريج موضع جرير وقال سل ما تريد جعلت فداءك قال أريد أن تغنيني لحنا سمعته بالمدينة أزعجني إليك قال وما هو قال\n(يا أخت ناجية السلام عليكم ... قبل الرحيل وقبل عذل العذل)\nفغناه ابن سريج وبيده قضيب يوقع به وينكت فوالله ما سمعت شيئا قط أحسن من ذلك فقال جرير لله دركم يا أهل مكة ما أعطيتم والله لو أن نازعا نزع إليكم ليقيم بين أظهركم فيسمع هذا صباح مساء لكان أعظم الناس حظا ونصيبا فكيف ومع هذا بيت الله الحرام ووجوهكم الحسان ورقة ألسنتكم وحسن شارتكم وكثرة فوائدكم","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":14,"spl":"تفوق ابن سريج على سائر المغنين — قدوم جرير المدينة وارتحاله إلى مكة ليسمع ابن سريج"},
{"id":"b3-34","bab":"الجزء 1","sec":"الوليد بن عبد الملك وابن سريج","page":"ج1 ص287","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه عن جده إبراهيم قال كتب الوليد بن عبد الملك إلى عامل مكة أن أشخص إلي ابن سريج فأشخصه فلما قدم مكث أياما لا يدعو به ولا يلتفت إليه قال ثم إنه ذكره فقال ويلكم أين ابن سريج قالوا هو حاضر قال علي به فقالوا أجب أمير المؤمنين فتهيأ ولبس وأقبل حتى دخل عليه فسلم فأشار إليه أن اجلس فجلس\nبعيدا فاستدناه فدنا حتى كان منه قريبا وقال ويحك يا عبيد لقد بلغني عنك ما حملني على الوفادة بك من كثرة أدبك وجودة اختيارك مع ظرف لسانك وحلاوة مجلسك فقال جعلت فداءك يا أمير المؤمنين تسمع بالمعيدي خير من أن تراه قال الوليد إني لأرجو ألا تكون أنت ذاك ثم قال هات ما عندك فاندفع ابن سريج فغنى بشعر الأحوص\n(أمنزلتي سلمى على القدم اسلما ... فقد هجتما للشوق قلبا متيما)\n(وذكرتما عصر الشباب الذي مضى ... وجدة وصل حبله قد تجذما)\n(وإني إذا حلت ببيش مقيمة ... وحل بوج جالسا أو تتهما)\n(يمانية شطت فأصبح نفعها ... رجاء وظنا بالمغيب مرجما)\n(أحب دنو الدار منها وقد أبى ... بها صدع شعب الدار إلا تثلما)\n(بكاها وما يدري سوى الظن من بكى ... أحيا يبكي أم ترابا وأعظما)\n(فدعها وأخلف للخليفة مدحة ... تزل عنك بؤسى أو تفيدك أنعما)\n(فإن بكفيه مفاتيح رحمة ... وغيث حيا يحيا به الناس مرهما)\n(إمام أتاه الملك عفوا ولم يثب ... على ملكه مالا حراما ولا دما)\n(تخيره رب العباد لخلقه ... وليا وكان الله بالناس أعلما)\n(فلما قضاه الله لم يدع مسلما ... لبيعته إلا أجاب وسلما)\n(ينال الغنى والعز من نال وده ... ويرهب موتا عاجلا من تشأما)\nقال الوليد أحسنت والله وأحسن الأحوص علي بالأحوص ثم قال يا عبيد هيه فغناه بشعر عدي بن الرقاع العاملي يمدح الوليد صوت\n(طار الكرى وألم الهم فاكتنعا ... وحيل بيني وبين النوم فامتنعا)\n(كان الشباب قناعا أستكن به ... وأستظل زمانا ثمت انقشعا)\n(فاستبدل الرأس شيبا بعد داجية ... فينانة ما ترى في صدغها نزعا)\n(فإن تكن ميعة من باطل ذهبت ... وأعقب الله بعد الصبوة الورعا)\n(فقد أبيت أراعي الخود راقدة ... على الوسائد مسرورا بها ولعا)\n(براقة الثغر تشفي القلب لذتها ... إذا مقبلها في ريقها كرعا)\n(كالأقحوان بضاحي الروض صبحه ... غيث أرش بتنضاح وما نقعا)\n(صلى الذي الصلوات الطيبات له ... والمؤمنون إذا ما جمعوا الجمعا)\n(على الذي سبق الأقوام ضاحية ... بالأجر والحمد حتى صاحباه معا)\n(هو الذي جمع الرحمن أمته ... على يديه وكانوا قبله شيعا)\n(عذنا بذي العرش أن نحيا ونفقده ... وأن نكون لراع بعده تبعا)\n(إن الوليد أمير المؤمنين له ... ملك عليه أعان الله فارتفعا)\n(لا يمنع الناس ما أعطى الذين هم ... له عبد ولا يعطون ما منعا)\nفقال له الوليد صدقت يا عبيد أنى لك هذا قال هو من عند الله قال الوليد لو غير هذا قلت لأحسنت أدبك قال ابن سريج ذلك فضل الله يؤتيه من يشاء قال الوليد يزيد في الخلق ما يشاء قال ابن سريج هذا من فضل ربي ليبلوني أأشكر أم أكفر قال الوليد لعلمك والله أكبر وأعجب إلي من غنائك غنني فغناه بشعر عدي بن الرقاع العاملي يمدح الوليد\n(عرف الديار توهما فاعتادها ... من بعد ما شمل البلى أبلادها)\n(ولرب واضحة العوارض طفلة ... كالريم قد ضربت بها أوتادها)\n(إني إذا ما لم تصلني خلتي ... وتباعدت مني اغتفرت بعادها)\n(صلى الإله على امرىء ودعته ... وأتم نعمته عليه وزادها)\n(وإذا الربيع تتابعت أنواؤه ... فسقى خناصرة الأحص فجادها)\n(نزل الوليد بها فكان لأهلها ... غيثا أغاث أنيسها وبلادها)\n(أو لا ترى أن البرية كلها ... ألقت خزائمها إليه فقادها)\n(ولقد أراد الله إذ ولاكها ... من أمة إصلاحها ورشادها)\n(أعمرت أرض المسلمين فأقبلت ... وكففت عنها من يروم فسادها)\n(وأصبت في أرض العدو مصيبة ... عمت أقاصي غورها ونجادها)\n(ظفرا ونصرا ما تناول مثله ... أحد من الخلفاء كان أرادها)\n(فإذا نشرت له الثناء وجدته ... جمع المكارم طرفها وتلادها)","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":15,"spl":"الوليد بن عبد الملك وابن سريج"},
{"id":"b3-35","bab":"الجزء 1","sec":"الوليد يأمر بإحضار الأحوص وعدي بن الرقاع","page":"ج1 ص291","text":"فأشار الوليد إلى بعض الخدم فغطوه بالخلع ووضعوا بين يديه كيسا من الدنانير وبدرا من الدراهم ثم قال الوليد بن عبد الملك يا مولى بني نوفل بن الحارث لقد أوتيت أمرا جليلا فقال ابن سريج يا أمير المؤمنين لقد آتاك الله ملكا عظيما وشرفا عاليا وعزا بسط يدك فيه فلم يقبضه عنك ولا يفعل إن شاء الله فأدام الله لك ما ولاك وحفظك فيما استرعاك فإنك أهل لما أعطاك ولا نزعه منك إذ رآك له موضعا قال يا نوفلي وخطيب أيضا قال ابن سريج عنك نطقت وبلسانك تكلمت وبعزك بينت وقد كان أمر بإحضار الأحوص بن محمد الأنصاري وعدي بن الرقاع العاملي فلما قدما عليه أمر بإنزالهما حيث ابن سريج فأنزلا منزلا إلى جنب ابن سريج فقالا والله لقرب أمير المؤمنين كان أحب إلينا من قربك يا مولى بني نوفل وإن في قربك لما يلذنا ويشغلنا عن كثير مما نريد فقال لهما ابن سريج أو قلة شكر فقال له عدي كأنك يابن اللخناء تمن علينا علي وعلي إن جمعنا وإياك سقف بيت أو صحن دار إلا عند أمير المؤمنين وأما الأحوص فقال أو لا تحتمل لأبي يحيى الزلة\nوالهفوة وكفارة يمين خير من عدم المحبة وإعطاء النفس سؤلها خير من لجاج في غير منفعة فتحول عدي وبقي عنده الأحوص وبلغ الوليد ما جرى بينهم فدعا ابن سريج وأدخله بيتا وأرخى دونه سترا ثم أمره إذا فرغ الأحوص وعدي من كلمتيهما أن يغني فلما دخلا وأنشداه مدائح فيه رفع ابن سريج صوته من حيث لا يرونه وضرب بعوده فقال عدي يا أمير المؤمنين أتأذن لي أن أتكلم فقال قل يا عاملي قال أمثل هذا عند أمير المؤمنين ويبعث إلى ابن سريج يتخطى به رقاب قريش والعرب من تهامة إلى الشأم ترفعه أرض وتخفضه أخرى فيقال من هذا فيقال عبيد بن سريج مولى بني نوفل بعث أمير المؤمنين إليه ليسمع غناءه فقال ويحك يا عدي أو لا تعرف هذا الصوت قال لا والله ما سمعته قط ولا سمعت مثله حسنا ولولا أنه في مجلس أمير المؤمنين لقلت طائفة من الجن يتغنون فقال اخرج عليهم فخرج فإذا ابن سريج فقال عدي حق لهذا أن يحمل حق لهذا أن يحمل ثلاثا ثم أمر لهما بمثل ما أمر به لابن سريج وارتحل القوم وكان الذي غناه ابن سريج من شعر عمر بن أبي ربيعة\n(بالله يا ظبي بني الحارث ... هل من وفى بالعهد كالناكث)\n(لا تخدعني بالمنى باطلا ... وأنت بي تلعب كالعابث)\n(حتى متى أنت لنا هكذا ... نفسي فداء لك يا حارثي)\n(يا منتهى همي ويا منيتي ... ويا هوى نفسي ويا وارثي)","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":16,"spl":"الوليد يأمر بإحضار الأحوص وعدي بن الرقاع — عودة الناس عن لوم ابن سريج على صنعة الغناء بعد "},
{"id":"b3-36","bab":"الجزء 1","sec":"عودة الناس عن لوم ابن سريج على صنعة الغناء بعد سماع صوته","page":"ج1 ص292","text":"ال وبلغني أن رجلا من الأشراف من قريش من موالي ابن سريج عاتبه يوما على الغناء وأنكره عليه وقال له لو أقبلت على غيره من الآداب لكان أزين\nبمواليك وبك فقال جعلت فداك امرأته طالق إن أنت لم تدخل الدار فقال الشيخ ويحك ما حملك على هذا قال جعلت فداك قد فعلت فالتفت النوفلي إلى بعض من كان معه متعجبا مما فعل فقال له القوم قد طلقت امرأته إن أنت لم تدخل الدار فدخل ودخل القوم معه فلما توسطوا الدار قال امرأته طالق إن أنت لم تسمع غنائي قال اعزب عني يا لكع ثم بدر الشيخ ليخرج فقال له أصحابه أتطلق امرأته وتحمل وزر ذلك قال فوزر الغناء أشد قالوا كلا ما سوى الله عز و جل بينهما فأقام الشيخ مكانه ثم اندفع ابن سريج يغني في شعر عمر بن أبي ربيعة في زينب\n(أليست بالتي قالت ... لمولاة لها ظهرا)\n(أشيري بالسلام له ... إذا هو نحونا خطرا)\n(وقولي في ملاطفة ... لزينب نولي عمرا)\n(أهذا سحرك النسوان ... قد خبرنني الخبرا)\nقال للجماعة هذا والله حسن ما بالحجاز مثله ولا في غيره وانصرفوا أخبرني الحسين بن يحيى عن حماد عن أبيه عن الأصمعي قال قال عبد الله ابن عمير الليثي لابن سريج لو تركت الغناء وعاتبه على ذلك فقال جعلت فداك لو سمعته ما تركته ثم قال امرأته طالق ثلاثا إن لم تدخل الدار حتى تسمع غنائي فالتفت عبد الله إلى رفيق له كان معه فقال ما تنتظر أدخل بنا وإلا طلقت امرأة الرجل فدخلا مع ابن سريج فغنى بشعر الأحوص صوت\n(لقد شاقك الحي إذ ودعوا ... فعينك في إثرهم تدمع)\n(وناداك للبين غربانه ... فظلت كأنك لا تسمع)\nم قال امرأته طالق إن أنت لم تستحسنه لأتركنه فتبسم عبد الله وخرج","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":16,"spl":"الوليد يأمر بإحضار الأحوص وعدي بن الرقاع — عودة الناس عن لوم ابن سريج على صنعة الغناء بعد "},
{"id":"b3-37","bab":"الجزء 1","sec":"نسبة ما في هذه الأخبار من الأصوات","page":"ج1 ص294","text":"منها الصوت الذي أوله في الخبر\n(جددي الوصل يا قريب وجودي ... )\nوله صوت\n(إن طيف الخيال حين ألما ... هاج لي ذكرة وأحدث هما)\n(جددي الوصل يا قريب وجودي ... لمحب فراقه قد ألما)\n(ليس بين الحياة والموت إلا ... أن يردوا جمالهم فتزما)\n(ولقد قلت مخفيا لغريض ... هل ترى ذلك الغزال الأحما)\n(هل ترى مثله من الناس شخصا ... أكمل الناس صورة وأتما)\nروضه من الخفيف الشعر لعمر بن أبي ربيعة والغناء لابن سريج ثقيل أول بالوسطى عن الهشامي وفيه للغريض أيضا ثقيل أول بالسبابة في مجرى البنصر عن إسحاق أخبرني الحسن بن علي قال حدثنا أحمد بن سعيد الدمشقي قال حدثنا الزبير قال أنشد جعفر بن محمد بن زيد بن علي بن الحسين عليهم السلام قول عمر\n(ليس بين الحياة والموت إلا ... أن يردوا جمالهم فتزما)\nطرب وارتاح وجعل يقول لقد عجلوا البين أفلا يوكون قربة أفلا يودعون صديقا أفلا يشدون رحلا حتى جرت دموعه وحدثنا الحرمي بن أبي العلاء عن الزبير فذكر مثله ومنها صوت\n(يا أخت ناجية السلام عليكم ... قبل الرحيل وقبل عذل العذل)\n(لو كنت أعلم أن آخر عهدكم ... يوم الرحيل فعلت ما لم أفعل)\nعروضه من الكامل الشعر لجرير والغناء لابن سريج ثقيل أول بالسبابة في مجرى الوسطى عن ابن المكي وذكر إسحاق في هذه الطريقة ولم ينسبه إلى أحد وفيه للغريض ثاني ثقيل بالوسطى عن ابن المكي أيضا ومما يشك فيه أنه لمعبد أو لكردم ابنه في البيت الثاني والأول ثاني ثقيل ولعريب في هذين البيتين لحن من رواية ابن المعتز غير مجنس ومنها صوت\n(أمنزلتي سلمى على القدم أسلما ... فقد هجتما للشوق قلبا متيما)\n(وذكرتما عصر الشباب الذي مضى ... وجدة وصل حبله قد تجذما)\nعروضه من الطويل والشعر للأحوص والغناء لكردم ثاني ثقيل بالوسطى وقيل إن هذا الثقيل الثاني لمحمد الرف وإن فيه لحنا من الثقيل الأول لكردم ومنها صوت\n(عرف الديار توهما فاعتادها ... من بعد ما شمل البلى أبلادها)\n(إلا رواكد كلهن قد اصطلى ... حمراء أكثر أهلها إيقادها)\nروضه من الكامل الشعر لعدي بن الرقاع العاملي والغناء لابن محرز ثقيل أول مطلق في مجرى البنصر عن إسحاق وفيه لمالك ثقيل أول بالبنصر عن عمرو وفيه لحن لإبراهيم وفي هذه الأخبار أنه لابن سريج وذكر حماد في كتاب ابن محرز أنه مما ينسب إلى ابن مسجح أو إلى ابن محرز ومنها صوت\n(بالله يا ظبي بني الحارث ... هل من وفى بالعهد كالناكث)\n(لا تخدعني بالمنى باطلا ... وأنت بي تلعب كالعابث)\nعروضه من السريع الشعر لعمر بن أبي ربيعة والغناء لابن سريج ولحنه خفيف ثقيل أول بالوسطى وذكر عمرو بن بانة أنه لسياط وذكر الهشامي وبذل أن فيه لإبراهيم الموصلي لحنا آخر وفيه خفيف رمل بالبنصر ذكر حبش أنه لإبراهيم بن المهدي وغيره ينسبه إلى إسحاق ومنها\nصوت وهو الذي أوله في الخبر أليست بالتي قالت لمولاة لها ظهرا\n(تصابى القلب فادكرا ... هواه ولم يكن ظهرا)\n(لزينب إذ تجد لنا ... صفاء لم يكن كدرا)\n(أليست بالتي قالت ... لمولاة لها ظهرا)\n(أشيري بالسلام له ... إذا هو نحونا نظرا)\n(وقولي في ملاطفة ... لزينب نولي عمرا)\n(فهزت رأسها عجبا ... وقالت من بذا أمرا)\n(أهذا سحرك النسوان ... قد خبرنني الخبرا)\n(طربت ورد من تهوى ... جمال الحي فابتكرا)\n(فقل للبربرية لا ... تلومي القلب إن جهرا)\n(بطرت وهكذا الإنسان ... ذو بطر إذا ظفرا)\n(فأين العهد والميثاق ... لا تخبر بنا بشرا)\nروضه من الوافر الشعر لعمر بن أبي ربيعة والغناء لابن سريج في الثالث والرابع والخامس والأول خفيف ثقيل أول مطلق في مجرى البنصر عن إسحاق وللغريض في السابع والثامن والأول لحن من القدر الأوسط من الثقيل الأول بالوسطى في مجراها عن إسحاق ولمعبد في هذه الأبيات كلها لحن عن يونس ودنانير ولم يجنساه وذكر الهشامي أنه خفيف ثقيل وفي السابع والثامن والتاسع رمل لدحمان ويقال إنه للزبير ابنه ولمالك لحن أوله\nصوت\n(لقد أرسلت جاريتي ... وقلت لها خذي حذرك)\n(وقولي في ملاطفة ... لزينب نولي عمرك)\n(فهزت رأسها عجبا ... وقالت من بذا أمرك)\n(أهذا سحرك النسوان ... قد خبرنني خبرك)","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":17,"spl":"نسبة ما في هذه الأخبار من الأصوات","partialRef":{"sid":"b3-31","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b3-38","bab":"الجزء 1","sec":"نسبة ما في هذه الأخبار من الأصوات","page":"ج1 ص294","text":"لحن مالك هذا خفيف ثقيل بالوسطى من رواية ابن المكي وهذا يروي الشعر ويجعل قوافيه كلها على الكاف وفي هذه الأبيات بعينها على هذه القافية خفيف رمل ينسب إلى ابن سريج وإلى الغريض وذكر حبش أن فيه لمعبد لحنا من الرمل أوله الثالث من الأبيات الأول المذكورة","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":18,"spl":"نسبة ما في هذه الأخبار من الأصوات — نسبة هذا الصوت"},
{"id":"b3-39","bab":"الجزء 1","sec":"رجع الخبر إلى سياقة أحاديث ابن سريج ابن سريج أحسن الناس غناء","page":"ج1 ص298","text":"أخبرنا يحيى بن علي ووكيع وجحظة قالوا حدثنا حماد بن إسحاق عن أبيه قال قال لي الفضل بن يحيى سألت أباك ليلة وقد أخذ منه الشراب عن أحسن الناس غناء فقال لي من النساء أم من الرجال قلت من الرجال قال ابن محرز فقلت فمن النساء قال ابن سريج قال إسحاق لي ويقال أحسن الرجال غناء من تشبه بالنساء وأحسن النساء غناء من تشبه بالرجال قال يحيى بن علي خاصة ثم كان ابن سريج كأنه خلق من قلب كل واحد فهو يغني له بما يشتهي أخبرني الحسين بن يحيى قال قال حماد قرأت على أبي عن الهيثم بن عدي قال قال ابن سريج مررت ببعض أندية مكة وفيه جماعة فحصرت فقلت\nكيف أجوزهم مع تعبي وما أنا فيه فسمعتهم يقولون قد جاء ابن سريج فقال بعضهم ممن لم يعرفني ومن ابن سريج فقال الذي ينغني\n(ألا هل هاجك الأظعان ... إذ جاوزن مطلحا)\nال ابن سريج فلما سمعت ذلك قويت نفسي واشتدت منتي ومررت بها أخطر في مصبغاتي فلما حاذيتهم قاموا بأجمعهم فسلموا علي ثم قالوا لأحداثهم امشوا مع أبي يحيى","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":18,"spl":"نسبة ما في هذه الأخبار من الأصوات — نسبة هذا الصوت"},
{"id":"b3-40","bab":"الجزء 1","sec":"ابن سريج يغني فتية من بني مروان","page":"ج1 ص299","text":"وقد حدثني عمي بهذا الخبر فقال حدثني أبو أيوب المديني قال حدثني محمد بن سلام عن جرير قال قال لي ابن سريج دعاني فتية من بني مروان فدخلت إليهم وأنا في ثياب الحجاز الغلاظ الجافية وهم في القوهي والوشي يرفلون كأنهم الدنانير الهرقلية فغنيتهم وأنا محتقر لنفسي عندهم لحنا لي وهو صوت\n(أبالفرع لم تظعن مع الحي زينب ... بنفسي عن النأي الحبيب المغيب)\n(بوجهك عن مس التراب مضنة ... فلا تبعدي إذ كل حي سيعطب)\nولحن ابن سريج هذا رمل بالخنصر في مجرى البنصر قال فتضاءلوا في عيني حتى ساويتهم في نفسي لما رأيتهم عليه من الإعظام لي ثم غنيتهم\n(ودع لبابة قبل أن تترحلا ... واسأل فإن قلاله أن تسألا)\nطربوا وعظموني وتواضعوا لي حتى صرت في نفسي بمنزلتهم لما رأيتهم عليه وصاروا في عيني بمنزلتي ثم غنيتهم\n(ألا هل هاجك الأظعان ... إذ جاوزن مطلحا)\nطربوا ومثلوا بين يدي ورموا بحللهم كلها علي حتى غطوني بها فمثلت لي نفسي أنها نفس الخليفة وأنهم لي خول فما رفعت طرفي إليهم بعد ذلك تيها وقد مضت نسبة ودع لبابة في أخبار عمر بن أبي ربيعة وغيره وأما\n(ألا هل هاجك الأظعان ... )\nنذكر نسبته","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":18,"spl":"نسبة ما في هذه الأخبار من الأصوات — نسبة هذا الصوت","partialRef":{"sid":"b3-16","gi":5,"vi":0,"side":0},"partial":1},
{"id":"b3-41","bab":"الجزء 1","sec":"نسبة هذا الصوت","page":"ج1 ص300","text":"صوت\n(ألا هل هاجك الأظعان ... إذ جاوزن مطلحا)\n(نعم ولوشك بينهم ... جرى لك طائر سنحا)\n(أجزن الماء من ركك ... وضوء الفجر قد وضحا)\n(فقلن مقيلنا قرن ... نباكر ماءه صبحا)\n(تبعتهم بطرف العين ... حتى قيل لي افتضحا)\n(يودع بعضنا بعضا ... وكل بالهوى جرحا)\n(فمن يفرح ببينهم ... فغيري إذ غدوا فرحا)\nروضه من الوافر الشعر لأبي دهبل الجمحي والغناء لمالك وله فيه لحنان ثقيل أول بالبنصر عن إسحاق وخفيف ثقيل بالوسطى عن عمرو ولمعبد فيه ثقيل أول بالخنصر في مجرى الوسطى ولابن سريج في الخامس وما بعده ثقيل أول مطلق في مجرى البنصر عن إسحاق وفيه للغريض ثاني ثقيل بالوسطى عن حبش","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":18,"spl":"نسبة ما في هذه الأخبار من الأصوات — نسبة هذا الصوت"},
{"id":"b3-42","bab":"الجزء 1","sec":"جرير يمدح غناء ابن سريج","page":"ج1 ص301","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه قال قدم جرير المدينة أو مكة فجلس مع قوم فجعلوا يعرضون عليه غناء رجل رجل من المغنين حتى غنوه لابن سريج فطرب وقال هذا أحسن ما أسمعتموني من الغناء كله قالوا وكيف قلت ذاك يا أبا حزرة قال مخرج كل ما أسمعتموني من الغناء من الرأس ومخرج هذا من الصدر أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني أبي قال حدثني إبراهيم بن محمد الشافعي قال جاء سندة الخياط المغني إلى الأفلح المخزومي وكان يوصف بعقل وفضل فقال له من أين أقبلت وإلى أين تمضي فقال إليك قصدت من\nمجلس لبعض القرشيين أقبلت محاكما إليك قال فيماذا قال كنت عند هذا الرجل وحضرت مجلسه رقطاء الحبطيين وصفراء العلقميين فتناولتا بينهما رمل ابن سريج\n(ليت شعري كيف أبقى ساعة ... مع ما ألقى إذا الليل حضر)\n(من يذق نوما ويهدأ ليله ... فلقد بدلت بالنوم السهر)\n(قلت مهلا إنها جنتة ... إن تخالطها تفز منها بشر)\nغنتاه جميعا واختلفنا في تفضيلهما ففضل كل فريق منا إحداهما فرضينا جميعا بحكمك فاحكم بيننا وبينهما فوجم ساعة وأهل الحجاز إذا أرادوا أن يحكموا تأملوا ساعة ثم حكموا فإذا حكم المحكم مضى حكمه كائنا ما كان ففضل من فضله وأسقط من أسقطه إذا تراضى الخصمان به فكره الأفلح أن يرضي قوما ويسخط آخرين فقال لسندة صفهما أنت لي كيف كانتا إذ غنتاه واشرح لي مذهبهما فيه كما سمعت وأنا أحكم بعد ذلك فقال سندة أما جارية الحبطيين فإنها كانت تلوك لحنه كما يلوك الفرس العتيق لجامه ثم تلقيه في هامة لدنة ثم تخرجه من منخر أغن والله ما ابتدأته فتوسطته وأنا أعقل ولا فرغت منه فأفقت إلا وأنا أظن أني رأيته في نومي وأما صفراء العلقميين فإنها أحسنهما حلقا وأصحهما صوتا وألينهما تثنيا والله ما سمعها أحد قط فانتفع بنفسه ولا دينه هذا ما عندي فاحكم أنت يا أخا بني مخزوم فقال قد حكمت بأنهما بمنزلة العينين في الرأس فبأيهما نظرت أبصرت ولو كان في\nالدنيا من عبيد بن سريج خلف لكانتا قال فانصرفوا جميعا راضين بحكمه أخبرني الحسين عن حماد عن أبيه عن محمد بن سلام قال سألت جريرا المديني عن ابن سريج فقال أتذكره ويحك باسمه ولا تقول سيد من غنى وواحد من ترنم قال حماد وحدثني أبي عن هارون بن مسلم عن محمد بن زهير السعدي الكوفي عن أبي بكر بن عياش عن الحسن بن عمرو الفقيمي قال دخلت على الشعبي فبينا أنا عنده في غرفته إذ سمعت صوت غناء فقلت أهذا في جوارك فأشرف بي على منزله فإذا بغلام كأنه فلقة قمر يتغنى قال إسحاق وهذا الغناء لابن سريج\n(وقمير بدا ابن خمس وعشرين ... له قالت الفتاتان قوما)\nال فقال لي الشعبي أتعرف هذا قلت لا فقال هذا الذي أتي الحكم صبيا هذا ابن سريج وأخبرني يحيى بن علي بن يحيى قال حدثني أبو أيوب المديني قال حدثني الهشامي الربعي عن إسحاق الموصلي قال تغنى ابن سريج في شعر لعمر بن أبي ربيعة وهو صوت\n(خانك من تهوى فلا تخنه ... وكن وفيا إن سلوت عنه)\n(واسلك سبيل وصله وصنه ... إن كان غدارا فلا تكنه)\n(عسى تباريح تجيء منه ... فيرجع الوصل ولم تشنه)\nال المكيون قال ابن سريج ما تغنيت بهذا الشعر قط إلا ظننت أني أحل محل الخليفة قال مؤلف هذا الكتاب أبو الفرج الأصفهاني وجدت في هذا الشعر لحنين أحدهما ثقيل أول والآخر رمل مجهولين جميعا فلا أدري أيهما لحنه","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":19,"spl":"جرير يمدح غناء ابن سريج"},
{"id":"b3-43","bab":"الجزء 1","sec":"ابن سريج يعدد صفات المغني المحسن والمصيب","page":"ج1 ص304","text":"ونسخت من كتاب العتابي أخبرني عون بن محمد قال حدثني عبد الله بن العباس بن الفضل بن الربيع عن جده الفضل عن ابن جامع عن سياط عن يونس الكاتب عن مالك بن أبي السمح قال سألت ابن سريج عن قول الناس فلان يصيب وفلان يخطئ وفلان يحسن وفلان يسيء فقال المصيب المحسن من المغنين هو الذي يشبع الألحان ويملأ الأنفاس ويعدل الأوزان ويفخم الألفاظ ويعرف الصواب ويقيم الإعراب ويستوفي النغم الطوال ويحسن مقاطيع النغم القصار ويصيب أجناس الإيقاع ويختلس مواقع النبرات ويستوفي ما يشاكلها في الضرب من النقرات فعرضت ما قال على معبد فقال لو جاء في الغناء قرآن ما جاء إلا هكذا أخبرني الحسن بن علي الخفاف قال حدثني أحمد بن سعيد الدمشقي قال حدثني الزبير بن بكار عن ظبية أن يزيد بن عبد الملك قال لحبابة يوما أتعرفين أحدا هو أطرب مني قالت نعم مولاي الذي باعني فأمر بإشخاصه فأشخص إليه مقيدا وأعلم\nبحاله فأذن في إدخاله فمثل بين يديه وحبابة وسلامة تغنيان فغنته سلامة لحن الغريض في\n(تشط غدا دار جيراننا ... )\nطرب وتحرك في أقياده ثم غنته حبابة لحن ابن سريج المجرد في هذا الشعر فوثب وجعل يحجل في قيده ويقول هذا وأبيكما ما لا تعذلاني فيه حتى دنا من الشمعة فوضع لحيته عليها فاحترقت وجعل يصيح الحريق الحريق يا أولاد الزنا فضحك يزيد وقال هذا والله أطرب الناس حقا ووصله وسرحه إلى بلده","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":20,"spl":"ابن سريج يعدد صفات المغني المحسن والمصيب — نسبة هذا الصوت","partialRef":{"sid":"b2-8","gi":5,"vi":0,"side":0},"partial":1},
{"id":"b3-44","bab":"الجزء 1","sec":"ابن سريج يطلب إلى عطاء وابن جريج أن يسمعاه","page":"ج1 ص305","text":"أخبرني الحسن بن علي قال حدثنا فضل اليزيدي عن إسحاق أن ابن سريج كان جالسا فمر به عطاء وابن جريج فحلف عليهما بالطلاق أن يغنيهما على أنهما إن نهياه عن الغناء بعد أن يسمعا منه تركه فوقفا له وغناهما\n(إخوتي لا تبعدوا أبدا ... وابلى والله قد بعدوا)\nغشي على ابن جريج وقام عطاء فرقص ونسبة هذا الصوت وخبره يذكر في موضع آخر أخبرني الحسن بن علي قال حدثنا فضل اليزيدي عن إسحاق أن ابن سريج كان عند بستان ابن عامر يغني\n(لمن نار بأعلى الخيف ... دون البئر ما تخبو)\n(أرقت لذكر موقعها ... فحن لذكرها القلب)\n(إذا ما أخمدت ألقي ... عليها المندل الرطب)\nجعل الحاج يركب بعضهم بعضا حتى جاء إنسان من آخر القطرات فقال يا هذا قد قطعت على الحاج وحبستهم والوقت قد ضاق فاتق الله وقم عنهم فقام وسار الناس","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":20,"spl":"ابن سريج يعدد صفات المغني المحسن والمصيب — نسبة هذا الصوت"},
{"id":"b3-45","bab":"الجزء 1","sec":"استحق جائزة سليمان بن عبد الملك لسبقه في الغناء","page":"ج1 ص305","text":"أخبرني الحسن قال حدثني محمد بن زكريا قال حدثني يزيد بن محمد عن إسحاق الموصلي\nأن سليمان بن عبد الملك لما حج سبق بين المغنين بدرة فجاء ابن سريج وقد أغلق الباب فلم يأذن له الحاجب فأمسك حتى سكتوا وغنى\n(سرى همي وهم المرء يسري ... )\nأمر سليمان بدفع البدرة إليه","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":20,"spl":"ابن سريج يعدد صفات المغني المحسن والمصيب — نسبة هذا الصوت","partial":1},
{"id":"b3-46","bab":"الجزء 1","sec":"نسبة هذا الصوت","page":"ج1 ص306","text":"صوت\n(سرى همي وهم المرء يسري ... وغاب النجم إلا قيس فتر)\n(أراقب في المجرة كل نجم ... تعرض للمجرة كيف يجري)\n(لهم لا أزال له مديما ... كأن القلب أسعر حر جمر)\n(على بكر أخي ولى حميدا ... وأي العيش يصفو بعد بكر)\nلشعر لعروة بن أذينة والغناء لابن سريج ثاني ثقيل بالوسطى وفيه لأبي عباد رمل بالوسطى وذكر الهشامي أن هذا اللحن لصاحب الحرون","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":20,"spl":"ابن سريج يعدد صفات المغني المحسن والمصيب — نسبة هذا الصوت"},
{"id":"b3-47","bab":"الجزء 1","sec":"مرض ابن سريج وموته","page":"ج1 ص307","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه قال قال ابن مقمة دخلت على ابن سريج في مرضه الذي مات فيه فقلت كيف أصبحت يا أبا يحيى فقال أصبحت والله كما قال الشاعر\n(كأني من تذكر ما ألاقي ... إذا ما أظلم الليل البهيم)\n(سقيم مل منه أقربوه ... وأسلمه المداوي والحميم)\nم مات قال إسحاق قال ابن مقمة لما احتضر ابن سريج نظر إلى ابنته تبكي فبكى وقال إن من أكبر همي أنت وأخشى أن تضيعي بعدي فقالت لا تخف فما غنيت شيئا إلا وأنا أغنيه فقال هاتي فاندفعت تغني أصواتا وهو مصغ إليها فقال قد أصبت ما في نفسي وهونت علي امرك ثم دعا سعيد بن مسعود الهذلي فزوجه إياها فأخذ عنها أكثر غناء أبيها وانتحله فهو الآن ينسب إليه قال إسحاق فقال كثر بن كثير السهمي يرثيه\n(ما اللهو بعد عبيد حين يخبره ... من كان يلهو به منه بمطلب)\n(لله قبر عبيد ما تضمن من ... لذاذة العيش والإحسان والطرب)\n(لولا الغريض ففيه من شمائله ... مشابه لم أكن فيها بذي أرب)\nال إسحاق وحدثني هشام بن المرية أن قادما قدم المدينة فسار معبدا بشيء فقال معبد أصبحت أحسن الناس غناء فقلنا أو لم تكن كذلك فقال ألا تدرون ما أخبرني به هذا قالوا لا قال أعلمني أن عبيد بن سريج مات ولم أكن أحسن الناس غناء وهو حي وفي ابن سريج يقول عمر بن أبي ربيعة صوت\n(قالت وعيناها تجودانها ... صوحبت والله لك الراعي)\n(يابن سريج لا تذع سرنا ... قد كنت عندي غير مذياع)\nنى فيه ابن سريج من رواية يونس قال أبو أيوب المديني توفي ابن سريج بالعلة التي أصابته من الجذام بمكة في خلافة سليمان بن عبد الملك أو في آخر خلافة الوليد بمكة ودفن في موضع بها يقال له دسم","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":21,"spl":"مرض ابن سريج وموته"},
{"id":"b3-48","bab":"الجزء 1","sec":"رجلان يسألان الوقوف على قبر ابن سريج","page":"ج1 ص308","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال أخبرني هارون ابن أبي بكر قال حدثني إسحاق بن يعقوب العثماني مولى آل عثمان عن أبيه قال إنا لبفناء دار عمرو بن عثمان بالأبطح في صبح خامسة من الثمان يعني أيام الحج قال كنت جالسا أيام الحج فما إن دريت إلا برجل على راحلة على رحل\nجميل وأداة حسنة معه صاحب له على راحلة قد جنب إليها فرسا وبغلا فوقفا علي وسألاني فانتسبت لهما عثمانيا فنزلا وقالا رجلان من أهلك لهما حاجة ونحب أن تقضيها قبل أن نشده بأمر الحج فقلت ما حاجتكما قالا نريد إنسانا يقفنا على قبر عبيد بن سريج قال فنهضت معهما حتى بلغت بهما محلة بني أبي قارة من خزاعة بمكة وهم موالي عبيد بن سريج فالتمست لهما إنسانا يصحبهما حتى يقفهما على قبره بدسم فوجدت ابن أبي دباكل فأنهضته معهما فأخبرني بعد أنه لما وقفهما على قبره نزل أحدهما عن راحلته فحسر عمامته عن وجهه فإذا هو عبد الله بن سعيد بن عبد الملك بن مروان فعقر ناقته واندفع يندبه بصوت شجي كليل حسن ويقول\n(وقفنا على قبر بدسم فهاجنا ... وذكرنا بالعيش إذ هو مصحب)\n(فجالت بأرجاء الجفون سوافح ... من الدمع تستتلي الذي يتعقب)\n(إذا أبطأت عن ساحة الحد ساقها ... دم بعد دمع إثره يتصبب)\n(فإن تسعدا نندب عبيدا بعولة ... وقل له منا البكا والتحوب)\nثم نزل صاحبه فعقر ناقته وقال له القرشي خذ في صوت أبي يحيى فاندفع يتغنى\n(أسعداني بعبرة أسراب ... من دموع كثيرة التسكاب)\n(إن أهل الحصاب قد تركوني ... مولها مولعا بأهل الحصاب)\n(أهل بيت تتابعوا للمنايا ... ما على الموت بعدهم من عتاب)\n(فارقوني وقد علمت يقينا ... ما لمن ذاق ميتة من إياب)\n(كم بذاك الحجون من أهل صدق ... وكهول أعفة وشباب)\n(سكنوا الجزع جزع بيت أبي موسى ... إلى النخل من صفي السباب)\n(فلي الويل بعدهم وعليهم ... صرت فردا وملني أصحابي)\nال ابن أبي دباكل فوالله ما تمم صاحبه منها ثلاثا حتى غشي على صاحبه وأقبل يصلح السرج على بغلته وهو غير معرج عليه فسألته من هو فقال رجل من جذام قلت بمن تعرف قال بعبد الله بن المنتشر قال ولم يزل القرشي على حاله ساعة ثم أفاق ثم جعل الجذامي ينضح الماء على وجهه ويقول كالمعاتب له أنت أبدا مصبوب على نفسك ومن كلفك ما ترى ثم قرب إليه الفرس فلما علاه استخرج الجذامي من خرج على بغل قدحا وإداوة ماء فجعل في القدح ترابا من تراب قبر ابن سريج وصب عليه ماء من الإداوة ثم قال هاك فاشرب هذه السلوة فشرب ثم فعل هو مثل ذلك وركب على البغل وأردفني فخرجا والله ما يعرضان بذكر شيء مما كنا فيه ولا أرى في وجوههما شيئا مما كنت أرى قبل ذلك فلما اشتمل علينا أبطح مكة قالا انزل يا خزاعي فنزلت وأومأ الفتى إلى الجذامي بكلام فمد يده إلي وفيها شيء فأخذته فإذا هو عشرون دينارا ومضيا فانصرفت إلى قبره ببعيرين فاحتملت عليهما أداة الراحلتين اللتين عقراهما فبعتها بثلاثين دينارا","topic":"أخبار ابن سريج ونسبه","topicNo":3,"sp":22,"spl":"رجلان يسألان الوقوف على قبر ابن سريج"},
{"id":"b4-1","bab":"الجزء 1","sec":"صوت من المائة المختارة","page":"ج1 ص311","text":"وهو الثالث من الثلاثة المختارة\n(أهاج هواك المنزل المتقادم ... نعم وبه ممن شجاك معالم)\n(مضارب أوتاد وأشعث داثر ... مقيم وسفع في المحل جواثم)\nعروضه من الطويل الشعر لنصيب والغناء في اللحن المختار لابن محرز ثاني ثقيل بإطلاق الوتر في مجرى البنصر وله فيه أيضا هزج بالسبابة في مجرى البنصر وذكر جحظة عن أصحابه أنه هو المختار وحكى عن أصحابه أنه ليس في الغناء كله نغمة إلا وهي في الثلاثة الأصوات المختارة التي ذكرها ومن قصيدة نصيب هذه مما يغني فيه قوله\n(لقد راعني للبين نوح حمامة ... على غصن بان جاوبتها حمائم)\n(هواتف أما من بكين فعهده ... قديم وأما شجوهن فدائم)\nلغناء لابن سريج ثاني ثقيل مطلق في مجرى البنصر عن يونس ويحيى المكي وإسحاق وأظنه مع البيتين الأولين وأن الجميع لحن واحد ولكنه تفرق لصعوبة اللحن وكثرة ما فيه من العمل فجعلا صوتين","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":0,"spl":"صوت من المائة المختارة — ذكر نصيب وأخباره"},
{"id":"b4-2","bab":"الجزء 1","sec":"ذكر نصيب وأخباره","page":"ج1 ص312","text":"هو نصيب بن رباح مولى عبد العزيز بن مروان وكان لبعض العرب من بني كنانة السكان بودان فاشتراه عبد العزيز منهم وقيل بل كانوا أعتقوه فاشترى عبد العزيز ولاءه منهم وقيل بل كاتب مواليه فأدى عنه مكاتبته وقال ابن دأب كان نصيب من قضاعة ثم من بلي وكانت أمه سوداء فوقع عليها سيدها فحبلت بنصيب فوثب عليه عمه بعد وفاة أبيه فباعه من عبد العزيز وقال أبو اليقظان كان أبوه من كنانة من بني ضمرة وكان شاعرا فحلا فصيحا مقدما في النسيب والمديح ولم يكن له حظ في الهجاء وكان عفيفا وكان يقال إنه لم ينسب قط إلا بامرأته أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال كتب إلي عبد الله بن عبد العزيز بن محجن بن نصيب بن رباح يذكر عن عمته غرضة بنت النصيب أن النصيب كان ابن نوبيين سبيين كانا لخزاعة ثم اشترت سلامة أم نصيب امرأة من خزاعة ضمرية حاملا بالنصيب فأعتقت ما في بطنها أخبرني الحسين بن يحيى عن حماد عن أبيه عن محمد بن كناسة قال\nكان نصيب من أهل ودان عبدا لرجل من كنانة هو وأهل بيته وكان أهل البادية يدعونه النصيب تفخيما له ويروون شعره وكان عفيفا كبير النفس مقدما عند الملوك يجيد مديحهم ومراثيهم أخبرني الحسين عن حماد عن أبيه عن ابن الكلبي قال كان نصيب من بلي بن عمرو بن الحاف بن قضاعة وكانت أمه أمة سوداء وقع فحملت ثم مات فباعه عمه أخو أبيه من عبد العزيز بن مروان","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":0,"spl":"صوت من المائة المختارة — ذكر نصيب وأخباره"},
{"id":"b4-3","bab":"الجزء 1","sec":"النصيب يقول شعرا ثم ينسبه إلى شعراء","page":"ج1 ص313","text":"قال حماد وأخبرني أبي عن أيوب بن عباية وأخبرنا الحرمي عن الزبير عن عمه وعن إسحاق بن إبراهيم جميعا عن أيوب بن عباية قال حدثني رجل من خزاعة من أهل كلية وهي قرية كان فيها النصيب وكثير قال بلغني أن النصيب قال قلت الشعر وأنا شاب فأعجبني قولي فجعلت آتي مشيخة من بني ضمرة بن بكر بن عبد مناة وهم موالي النصيب ومشيخة من خزاعة فأنشدهم القصيدة من شعري ثم أنسبها إلى بعض شعرائهم الماضين فيقولون أحسن والله هكذا يكون الكلام وهكذا يكون الشعر فلما سمعت ذلك منهم علمت أني محسن فأزمعوا وأزمعت الخروج إلى عبد العزيز بن مروان وهو يومئذ بمصر فقلت لأختي أمامة وكانت عاقلة جلدة أي أخية إني قد قلت شعرا وأنا أريد عبد العزيز بن مروان وأرجو أن يعتقك الله عز و جل به وأمك ومن كان مرقوقا من أهل قرابتي قالت إنا لله وإنا إليه راجعون يابن أم أتجتمع عليك الخصلتان السواد وأن تكون ضحكة للناس قال قلت\nفاسمعي فأنشدتها فسمعت فقالت بأبي أنت أحسنت والله في هذا والله رجاء عظيم فاخرج على بركة الله فخرجت على قعود لي حتى قدمت المدينة فوجدت بها الفرزدق في مسجد رسول الله فعرجت إليه فقلت أنشده وأستنشده وأعرض عليه شعري فأنشدته فقال لي ويلك أهذا شعرك الذي تطلب به الملوك قلت نعم قال فلست في شيء إن استطعت أن تكتم هذا على نفسك فافعل فانفضخت عرقا فحصبني رجل من قريش كان قريبا من الفرزدق وقد سمع إنشادي وسمع ما قال لي الفرزدق فأومأ إلي فقمت إليه فقال ويحك أهذا شعرك الذي أنشدته الفرزدق قلت نعم فقال قد والله أصبت والله لئن كان هذا الفرزدق شاعرا لقد حسدك فإنا لنعرف محاسن الشعر فامض لوجهك ولا يكسرنك قال فسرني قوله وعلمت أنه قد صدقني فيما قال فاعتزمت على المضي قال فمضيت فقدمت مصر وبها عبد العزيز ابن مروان فحضرت بابه مع الناس فنحيت عن مجلس الوجوه فكنت وراءهم ورأيت رجلا جاء على بغلة حسن الشارة سهل المدخل يؤذن له إذا جاء فلما انصرف إلى منزله انصرفت معه أماشي بغلته فلما رآني قال ألك حاجة قلت نعم أنا رجل من أهل الحجاز شاعر وقد مدحت الأمير وخرجت إليه راجيا معروفه وقد ازدريت فطردت من الباب ونحيت عن الوجوه قال فأنشدني فأنشدته فأعجبه شعري فقال ويحك أهذا شعرك فإياك أن تنتحل فإن الأمير راوية عالم بالشعر وعنده رواة فلا تفضحني ونفسك فقلت والله ما هو إلا شعري فقال ويحك فقل أبياتا تذكر فيها حوف مصر وفضلها على غيرها والقني بها غدا فغدوت عليه من غد فأنشدته قولي\n(سرى الهم تثنيني إليك طلائعه ... بمصر وبالخوف اعترتني روائعه)\n(وبات وسادي ساعد قل لحمه ... عن العظم حتى كاد تبدو أشاجعه)\nال وذكرت فيها الغيث فقلت\n(وكم دون ذاك العارض البارق الذي ... له اشتقت من وجه أسيل مدامعه)\n(تمشي به أفناء بكر ومذحج ... وأفناء عمرو وهو خصب مرابعه)\n(فكل مسيل من تهامة طيب ... دميث الربا تسقي البحار دوافعه)\n(أعني على برق أريك وميضه ... تضيء دجنات الظلام لوامعه)\n(إذا اكتحلت عينا محب بضوئه ... تجافت به حتى الصباح مضاجعه)\n(هنيئا لأم البختري الروى به ... وإن أنهج الحبل الذي أنا قاطعه)\n(وما زلت حتى قلت إني لخالع ... ولائي من مولى نمتني قوارعه)\n(ومانح قوم أنت منهم مودتي ... ومتخذ مولاك مولى فتابعه)","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":1,"spl":"النصيب يقول شعرا ثم ينسبه إلى شعراء"},
{"id":"b4-4","bab":"الجزء 1","sec":"عبد العزيز بن مروان يقول لأيمن بن خريم والله لنصيب أشعر منك","page":"ج1 ص315","text":"قال أنت والله شاعر احضر بالباب حتى أذكرك للأمير قال فجلست على الباب ودخل فما ظننت أنه أمكنه أن يذكرني حتى دعي بي فدخلت فسلمت على عبد العزيز فصعد في بصره وصوب ثم قال أنت شاعر ويلك قلت نعم أيها الأمير قال فأنشدني فأنشدته فأعجبه شعري وجاء الحاجب\nفقال أيها الأمير هذا أيمن بن خريم الأسدي بالباب فقال ائذن له فدخل فاطمأن فقال له الأمير يا أيمن بن خريم كم ترى ثمن هذا العبد فنظر إلي فقال والله لنعم الغادي في أثر المخاض هذا أيها الأمير أرى ثمنه مائة دينار قال فإن له شعرا وفصحاحة فقال لي أيمن أتقول الشعر قلت نعم قال قيمته ثلاثون دينارا قال يا أيمن أرفعه وتخفضه أنت قال لكونه أحمق أيها الأمير ما لهذا وللشعر أمثل هذا يقول الشعر أو يحسن شعرا فقال أنشده يا نصيب فأنشدته فقال له عبد العزيز كيف تسمع يا أيمن قال شعر أسود هو أشعر أهل جلدته قال هو والله أشعر منك قال أمني أيها الأمير قال إي والله منك قال والله أيها الأمير إنك لملول طرف قال كذبت والله ما أنا كذلك ولو كنت كذلك ما صبرت عليك تنازعني التحية وتؤاكلني الطعام وتتكىء على وسائدي وفرشي وبك ما بك يعني وضحا كان بأيمن قال ائذن لي أن أخرج إلى بشر بالعراق واحملني على البريد قال قد أذنت لك وأمر به فحمل على البريد قال قد أذنت له وأمر به فحمل على البريد إلى بشر فقال أيمن بن خريم\n(ركبت من المقطم في جمادى ... إلى بشر بن مروان البريدا)\n(ولو أعطاك بشر ألف ألف ... رأى حقا عليه أن يزيدا)\n(أمير المؤمنين أقم ببشر ... عمود الحق إن له عمودا)\n(ودع بشرا يقومهم ويحدث ... لأهل الزيغ إسلاما جديدا)\n(كأن التاج تاج بني هرقل ... جلوه لأعظم الأيام عيدا)\n(على ديباج خدي وجه بشر ... إذا الألوان خالفت الخدودا)\nقال أيوب يعني بقوله\n(إذا الألوان خالفت الخدودا ... )\nنه عرض بكلف كان في وجه عبد العزيز\n(وأعقب مدحتي سرجا مليحا ... وأبيض جوزجانيا عقودا)\n(وإنا قد وجدنا أم بشر ... كأم الأسد مذكارا ولودا)\nال فأعطاه بشر مائة ألف درهم","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":2,"spl":"عبد العزيز بن مروان يقول لأيمن بن خريم والله لنصيب أشعر منك — عبد الله بن أبي فروة أول من ","partial":1},
{"id":"b4-5","bab":"الجزء 1","sec":"عبد الله بن أبي فروة أول من وصل النصيب بعبد العزيز بن مروان","page":"ج1 ص317","text":"أخبرني الحرمي قال حدثنا الزبير قال حدثني عبد الرحمن بن عبد الله الزهري عن عبد الله بن عمران بن أبي فروة قال أول من نوه باسم نصيب وقدم به على عبد العزيز بن مروان عبد الله بن أبي فروة قدم به عليه وهو وصيف حين بلغ وأول ما قال الشعر قال أصلح الله الأمير جئتك بوصيف نوبي يقول الشعر وكان نصيب ابن نوبيين فأدخله عليه فأعجبه شعره وكان معه أيمن بن خريم الأسدي فقال عبد العزيز إذا دعوت بالغداء فأدخلوه علي في جبة صوف محتزما بعقال فإذا قلت قوموه فقوموه وأخرجوه وردوه علي في جبة وشي ورداء وشي فلما جلس للغداء ومعه أيمن بن خريم\nأدخل نصيب في جبة صوف محتزما بعقال فقال قوموا هذا الغلام فقالوا عشرة عشرون ثلاثون دينارا فقال ردوه فأخرجوه ثم ردوه في جبة وشي ورداء وشي فقال أنشدنا فأنشدهم فقال قوموه قالوا ألف دينار فقال أيمن والله ما كان قط أقل في عيني منه الآن وإنه لنعم راعي المخاض فقال له فكيف شعره قال هو أشعر أهل جلدته فقال له عبد العزيز هو والله أشعر منك قال أمني أيها الأمير قال نعم فقال أيمن إنك لملول طرف فقال له والله ما أنا بملول وأنا أنازعك الطعام منذ كذا وكذا تضع يدك حيث أضعها وتلتقي يدك مع يدي على مائدة كل ذلك احتملك وكان بأيمن بياض فقال له أيمن ائذن لي أن أخرج إلى بشر فأذن له فخرج وقال أبياته التي أولها\n(ركبت من المقطم في جمادى ... )\nقد مضت الأبيات قال فلما جاز بعبد الملك بن مروان قال أين تريد قال أريد أخاك بشرا قال أتجوزني قال إي والله أجوزك إلى من قدم إلي وطلبني قال فلم فارقت صاحبك قال رأيتكم يا بني مروان تتخذون للفتى من فتيانكم مؤدبا وشيخكم والله محتاج إلى خمسة مؤدبين فسر ذلك عبد الملك وكان عازما على أن يخلعه ويعقد لابنه الوليد","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":2,"spl":"عبد العزيز بن مروان يقول لأيمن بن خريم والله لنصيب أشعر منك — عبد الله بن أبي فروة أول من ","partialRef":{"sid":"b4-4","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b4-6","bab":"الجزء 1","sec":"عبد العزيز بن مروان يبتاع نصيبا ويعتقه","page":"ج1 ص318","text":"خبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال يقال إن نصيبا أضل إبلا له فخرج في بغائها فلم يصبها وخاف مواليه أن يرجع إليهم فأتى عبد العزيز بن مروان فمدحه وذكر له قصته فأخلف عليه ما ضل لمواليه وابتاعه وأعتقه أخبرنا الحرمي قال حدثنا الزبير قال حدثنا عبد الله بن إبراهيم الهلالي ثم الدوسي قال\nأراد النصيب الخروج إلى عبد العزيز بن مروان وهو عبد لبني محرز الضمري فقالت أمه له إنك سترقد ويأخذك ابن محرز يذهب بك فذهب ولم يبال بقولها حتى إذا كان بمكان ماء يعرف بالدو فبينا هو راقد إذ هجم عليه ابن محرز فقال حين رآه\n(إني لأخشى من قلاص ابن محرز ... إذا وخدت بالدو وخذ النعائم)\n(يرعن بطين القوم أية روعة ... ضحيا إذا استقبلنه غير نائم)\nأطلقوه فرجع فأتى أمه فقالت أخبرتك يا بني أنه ليس عندك أن تعجز القوم فإن كنت يا بني قد غلبتني أنك ذاهب فخذ بنت الفلانة فإني رأيتها وطئت أفحوص بيضات قطاة فلم تفلقهن فركبها فهي التي بلغته ابن مروان قال أبو عبد الله بن الزبير عندنا أن التي اعتقته امرأة من بني ضمرة ثم من بني حنبل حدثنا محمد بن العباس اليزيدي قال حدثنا الخليل بن أسد قال حدثنا عبد الله بن صالح بن مسلم قال حدثنا كليب بن إسماعيل مولى بني أمية وكان حدثا أي حسن الحديث قال بلغني أن نصيبا كان حبشيا يرعى إبلا لمواليه فأضل منها بعيرا فخرج في طلبه حتى أتى الفسطاط وبه إذ ذاك عبد العزيز بن مروان وهو ولي عهد عبد الملك بن مروان فقال نصيب ما بعد عبد العزيز واحد أعتمده لحاجتي فأتى الحاجب فقال استأذن لي على الأمير فإني قد هيأت له مديحا فدخل الحاجب فقال أصلح الله الأمير بالباب رجل أسود يستأذن عليك بمديح قد هيأه لك\nفظن عبد العزيز أنه ممن يهزأ به ويضحكهم فقال مره بالحضور ليوم حاجتنا إليه فغدا نصيب وراح إلى باب عبد العزيز أربعة أشهر وأتاه آت من عبد الملك فسره فأمر بالسرير فأبرز للناس وقال علي بالأسود وهو يريد أن يضحك منه الناس فدخل فلما كان حيث يسمع كلامه قال\n(لعبد العزيز على قومه ... وغيرهم نعم غامره)\n(فبابك ألين أبوابهم ... ودارك مأهولة عامره)\n(وكلبك آنس بالمعتفين ... من الأم بالإبنة الزائره)\n(وكفك حين ترى السائلين ... أندى من الليلة الماطره)\n(فمنك العطاء ومني الثناء ... بكل محبرة سائره)\nقال أعطوه أعطوه فقال إني مملوك فدعا الحاجب فقال اخرج فابلغ في قيمته فدعا المقومين فقال قوموا غلاما أسود ليس به عيب قالوا مائة دينار قال إنه راع للإبل يبصرها ويحسن القيام عليها قالوا حينئذ مائتا دينار قال إنه يبري القسي ويثقفها ويرمي النبل ويريشها قالوا أربعمائة دينار قال إنه راوية للشعر بصير به قالوا ستمائة دينار قال إنه شاعر لا يلحق حذقا قالوا ألف دينار قال عبد العزيز ادفعوا إليه قال أصلح الله الأمير ثمن بعيري الذي أضللت قال وكم ثمنه قال خمسة وعشرون دينارا قال ادفعوا إليه قال أصلح الله الأمير جائزتي لنفسي عن مديحي إياك قال اشتر نفسك ثم عد إلينا فأتى الكوفة وبها بشر بن مروان فاستأذن عليه فاستصعب الدخول إليه وخرج بشر بن مروان متنزها فعارضه فلما ناكبه أي صار حذاء منكبه ناداه\n(يا بشر يابن الجعفرية ما ... خلق الإله يديك للبخل)\n(جاءت به عجز مقابلة ... ما هن من جرم ولا عكل)\nال فأمر له بشر بعشرة آلاف درهم الجعفرية التي عناها نصيب أم بشر ابن مروان وهي قطية بنت بشر بن عامر ملاعب الأسنة بن مالك بن جعفر بن كلاب أخبرنا اليزيدي عن الخراز عن المدائني عن عبد الله بن مسلم وعامر بن حفص وغيرهما أن مروان بن الحكم مر ببادية بني جعفر فرأى قطية بنت بشر تنزع بدلو على إبل لها وتقول\n(ليس بنا فقر إلى التشكي ... جربة كحمر الأبك)\nم يقول\n(عامان ترقيق وعام تمما ... لم يترك لحما ولم يترك دما)\n(ولم يدع في رأس عظم ملدما ... إلا رذايا ورجالا رزما)","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":3,"spl":"عبد العزيز بن مروان يبتاع نصيبا ويعتقه"},
{"id":"b4-7","bab":"الجزء 1","sec":"عبد العزيز بن مروان يبتاع نصيبا ويعتقه","page":"ج1 ص318","text":"فخطبها مروان فتزوجها فولدت له بشر بن مروان أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثنا أحمد بن معاوية عن إسحاق بن أيوب عن خليل بن عجلان في خبر النصيب مثل ما ذكره الزبير وإسحاق سواء أخبرني عمي قال حدثنا الكراني قال حدثنا العمري عن العتبي قال دعا النصيب مواليه أن يستلحقوه فأبى وقال والله لأن أكون مولى لائقا أحب إلي من أن أكون دعيا لاحقا وقد علمت أنكم تريدون بذلك مالي ووالله لا أكسب شيئا أبدا إلا كنت أنا وأنتم فيه سواء كأحدكم لا استأثر عليكم منه بشيء أبدا قال وكان كذلك معهم حتى مات إذا أصاب شيئا قسمه فيهم فكان فيه كأحدهم","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":4,"spl":"عبد العزيز بن مروان يبتاع نصيبا ويعتقه — النصيب يعتق ذوي قرابته"},
{"id":"b4-8","bab":"الجزء 1","sec":"النصيب يلتقي الفرزدق عند سليمان بن عبد الملك","page":"ج1 ص322","text":"خبرني الحرمي قال حدثنا الزبيري وحدثنا محمد بن العباس اليزيدي قال حدثنا أحمد بن أبي خيثمة قال حدثنا الزبير قال حدثنا محمد بن إسماعيل الجعفري قال دخل النصيب على سليمان بن عبد الملك وعنده الفرزدق فاستنشد الفرزدق وهو يرى أنه سينشده مديحا له فأنشده قوله يفتخر\n(وركب كأن الريح تطلب عندهم ... لها ترة من جذبها بالعصائب)\n(سروا يركبون الريح وهي تلفهم ... على شعب الأكوار من كل جانب)\n(إذا استوضحوا نارا يقولون ليتها ... وقد خصرت أيديهم نار غالب)\nال وعمامته على رأسه مثل المنسف فغاظ سليمان وكلح في وجهه وقال لنصيب قم فأنشد مولاك ويلك فقام نصيب فأنشده قوله\n(أقول لركب صادرين لقيتهم ... قفا ذات أوشال ومولاك قارب)\n(قفوا خبروني عن سليمان إنني ... لمعروفه من أهل ودان طالب)\n(فعاجوا فأثنوا بالذي أنت أهله ... ولو سكتوا أثنت عليك الحقائب)\n(وقالوا عهدناه وكل عشية ... بأبوابه من طالب العرف راكب)\n(هو البدر والناس الكواكب حوله ... ولا تشبه البدر المضيء الكواكب)\nقال له سليمان أحسنت والله يا نصيب وأمر له بجائزة ولم يصنع ذلك بالفرزدق فقال الفرزدق وقد خرج من عنده\n(وخير الشعر أكرمه رجالا ... وشر الشعر ما قال العبيد)\nخبرنا الحرمي قال حدثنا الزبير قال حدثني عبد الرحمن بن عبد الله الزهري عن عمه موسى بن عبد العزيز قال حمل عبد العزيز بن مروان النصيب بالمقطم مقطم مصر على بختي قد رحله بغبيط فوقه وألبسه مقطعات وشي ثم أمره أن ينشد فاجتمع حوله السودان وفرحوا به فقال لهم أسررتكم قالوا إي والله قال والله ما لما يسوءكم من أهل جلدتكم أكثر","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":4,"spl":"عبد العزيز بن مروان يبتاع نصيبا ويعتقه — النصيب يعتق ذوي قرابته"},
{"id":"b4-9","bab":"الجزء 1","sec":"جرير يعترف بشاعرية النصيب","page":"ج1 ص324","text":"أخبرنا أبو خليفة عن محمد بن سلام قال حدثني أبو العراف قال مر جرير بنصيب وهو ينشد فقال له اذهب فأنت أشعر أهل جلدتك قال وجلدتك يا أبا حزرة أخبرنا الحسين بن يحيى عن حماد عن أبيه قال حدثني أيوب بن عباية قال بلغني أن النصيب كان إذا قدم على هشام بن عبد الملك أخلى له مجلسه واستنشده مراثي بني أمية فإذا أنشده بكى وبكى معه فأنشده يوما قصيدة له مدحه بها يقول فيها\n(إذا استبق الناس العلا سبقتهم ... يمينك عفوا ثم صلت شمالها)\nفقال له هشام يا أسود بلغت غاية المدح فسلني فقال يدك بالعطية أجود وأبسط من لساني بمسألتك فقال هذا والله أحسن من الشعر وحباه وكساه وأحسن جائزته","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":4,"spl":"عبد العزيز بن مروان يبتاع نصيبا ويعتقه — النصيب يعتق ذوي قرابته"},
{"id":"b4-10","bab":"الجزء 1","sec":"النصيب يعتق ذوي قرابته","page":"ج1 ص325","text":"أخبرني الحسين بن يحيى قال أخبرنا حماد بن إسحاق عن أبيه عن أيوب بن عباية قال أصاب نصيب من عبد العزيز بن مروان معروفا فكتمه ورجع إلى المدينة في هيئة بذة فقالوا لم يصب بمدحه شيئا فمكث مدة ثم ساوم بأمه فابتاعها وأعتقها ثم ابتاع أم أمه بضعف ما ابتاع به أمه فأعتقها وجاءه ابن خالة له اسمه سحيم فسأله أن يعتقه فقال له ما معي والله شيء ولكني إذا خرجت أخرجتك معي لعل الله أن يعتقك فلما أراد الخروج دفع غلاما له إلى مولى سحيم يرعى إبله وأخرجه معه فسأل في ثمنه فأعطاه وأعتقه فمر به يوما وهو يزفن ويزمر مع السودان فأنكر ذلك عليه وزجره فقال له إن كنت أعتقتني لأكون كما تريد فهذا والله ما لا يكون أبدا وإن كنت أعتقتني لتصل رحمي وتقضي حقي فهذا والله الذي أفعله هو الذي أريده أزفن وأزمر وأصنع ما شئت فانصرف النصيب وهو يقول\n(إني أراني لسحيم قائلا ... إن سحيما لم يثبني طائلا)\n(نسيت إعمالي لك الرواحلا ... وضربي الأبواب فيك سائلا)\n(عند الملوك أستثيب النائلا ... حتى إذا آنست عتقا عاجلا)\n(وليتني منك القفا والكاهلا ... أخلقا شكسا ولونا حائلا)","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":4,"spl":"عبد العزيز بن مروان يبتاع نصيبا ويعتقه — النصيب يعتق ذوي قرابته"},
{"id":"b4-11","bab":"الجزء 1","sec":"النصيب يستعجل جائزة عند عبد العزيز بن مروان","page":"ج1 ص326","text":"قال إسحاق وأبطأت جائزة النصيب عند عبد العزيز فقال\n(وإن وراء ظهري يابن ليلى ... أناسا ينظرون متى أؤوب)\n(أمامة منهم ولمأقييها ... غداة البين في أثري غروب)\n(تركت بلادها ونأيت عنها ... فأشبه ما رأيت بها السلوب)\n(فأتبع بعضنا بعضا فلسنا ... نثيبك لكن الله المثيب)\nعجل جائزته وسرحه قال إسحاق فحدثني ابن كناسة قال ليلى أم عبد العزيز كلبية وبلغني عنه أنه قال لا أعطي شاعرا شيئا حتى يذكرها في مدحي لشرفها فكان الشعراء يذكرونها باسمها في أشعارهم أخبرني الحسين عن حماد عن أبيه عن ابن عباية قال وقفت سوداء بالمدينة على نصيب وهو ينشد الناس فقالت بأبي أنت يابن عمي وأمي ما أنت والله علي بخزي فضحك وقال والله لمن يخزيك من بني عمك أكثر ممن يزينك قال إسحاق وحدثني ابن عباية وغيره أن ابنا لنصيب خطب بعد وفاة سيده الذي أعتقه بنتا له من أخيه فأجابه إلى ذلك وعرف أباه فقال له اجمع وجوه الحي لهذا الحال فجمعهم فلما حضروا أقبل نصيب على أخي سيده فقال أزوجت ابني هذا من ابنة أخيك قال نعم فقال لعبيد له سود خذوا برجل ابني هذا فجروه فاضربوه ضربا مبرحا ففعلوا وضربوه ضربا مبرحا وقال لأخي سيده لولا أني أكره أذاك لألحقتك به ثم نظر إلى شاب من أشراف الحي فقال زوج هذا ابنة أخيك وعلي ما يصلحهما في مالي ففعل\nأخبرني الحسن بن علي قال حدثنا أحمد بن الحارث عن المدائني قال دخل نصيب على عبد الملك فتغدى معه ثم قال هل لك فيما نتنادم عليه فقال تؤمنني ففعل فقال لوني حائل وشعري مفلفل وخلقتي مشوهة ولم أبلغ ما بلغت من إكرامك إياي بشرف أب أو أم أو عشيرة وإنما بلغته بعقلي ولساني فأنشدك الله يا أمير المؤمنين أن تحول بيني وبين ما بلغت به هذه المنزلة منك فأعفاه","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":5,"spl":"النصيب يستعجل جائزة عند عبد العزيز بن مروان — أوصاف نصيب الجسدية"},
{"id":"b4-12","bab":"الجزء 1","sec":"سبب تسمية النصيب بهذا الاسم","page":"ج1 ص327","text":"أخبرني أبو الحسن الأسدي قال حدثني محمد بن صالح بن النطاح قال بلغني عن خلاد بن مرة عن أبي بكر بن مزيد قال لقيت النصيب يوما بباب هشام فقلت له يا أبا محجن لم سميت نصيبا ألقولك في شعرك عاينها النصيب فقال لا ولكني ولدت عند أهل بيت من ودان فقال سيدي إيتونا بمولودنا هذا لننظر إليه فلما رآني قال إنه لمنصب الخلق فسميت النصيب ثم اشتراني عبد العزيز بن مروان فأعتقني أخبرني الحسين بن يحيى عن حماد عن أبيه عن محمد بن كناسة أبي يحيى الأسدي قال قال أبو عبد الله بن أبي إسحاق البصري لإن وليت العراق لأستكتبن نصيبا لفصاحته وتخلصه إلى جيد الكلام أخبرني الأسدي قال حدثني محمد بن صالح عن أبيه عن محمد بن عبد العزيز الزهري قال حدثني نصيب قال دخلت على عبد العزيز بن مروان فقال أنشدني قولك\n(إذا لم يكن بين الخليلين ردة ... سوى ذكر شيء قد مضى درس الذكر)\nقلت ليس هذا لي هذا لأبي صخر الهذلي ولكني الذي أقول\n(وقفت بذي دوران أنشد ناقتي ... وما إن بها لي من قلوص ولا بكر)\nقال لي عبد العزيز لك جائزة على صدق حديثك وجائزة على شعرك فأعطاني على صدق حديثي ألف دينار وعلى شعري ألف دينار","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":5,"spl":"النصيب يستعجل جائزة عند عبد العزيز بن مروان — أوصاف نصيب الجسدية"},
{"id":"b4-13","bab":"الجزء 1","sec":"أوصاف نصيب الجسدية","page":"ج1 ص328","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه عن عثمان بن حفص عن أبيه قال رأيت النصيب وكان أسود خفيف العارضين ناتىء الحنجرة أخبرني الحرمي بن أبي العلاء قال حدثني الزبير قال حدثني إبراهيم بن يزيد السعدي عن جدته جمال بنت عون بن مسلم عن أبيها عن جدها قال رأيت رجلا أسود مع امرأة بيضاء فجعلت أعجب من سواده وبياضها فدنوت منه وقلت من أنت قال أنا الذي أقول\n(ألا ليت شعري ما الذي تحدثين بي ... غدا غربة النأي المفرق والبعد)\n(لدى أم بكر حين تقترب النوى ... بنا ثم يخلو الكاشحون بها بعدي)\n(أتصرمني عند الألى هم لنا العدا ... فتشمتهم بي أم تدوم على العهد)\nال فصاحت بل والله تدوم على العهد فسألت عنهما فقيل هذا نصيب وهذه أم بكر","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":5,"spl":"النصيب يستعجل جائزة عند عبد العزيز بن مروان — أوصاف نصيب الجسدية"},
{"id":"b4-14","bab":"الجزء 1","sec":"عبد الله بن جعفر يسخو في عطائه للنصيب","page":"ج1 ص329","text":"أخبرني أبو الحسن الأسدي قال حدثنا محمد بن صالح بن النطاح قال حدثني أبو اليقظان عن جويرية بن أسماء قال أتى النصيب عبد الله بن جعفر فحمله وأعطاه وكساه فقال له قائل يا أبا جعفر أعطيت هذا العبد الأسود هذه العطايا فقال والله لئن كان أسود إن ثناءه لأبيض وإن شعره لعربي ولقد استحق بما قال أكثر مما نال وما ذاك إنما هي رواحل تنضى وثياب تبلى ودراهم تفنى وثناء يبقى ومدائح تروى أخبرني الحسين بن يحيى عن حماد عن أبيه عن المدائني قال قال أبو الأسود امتدح نصيب عبد الله بن جعفر وذكر مثله أخبرني الحسن بن علي قال حدثنا الخراز عن المدائني قال قيل لنصيب إن هاهنا نسوة يردن أن ينظرن إليك ويسمعن منك شعرك قال وما يصنعن بي يرين جلدة سوداء وشعرا أبيض ولكن ليسمعن شعري من وراء ستر أخبرني الحسين بن يحيى عن حماد عن أبيه عن عثمان بن حفص عن رجل ذكره قال أتاني منقذ الهلالي ليلا فضرب علي الباب فقلت من هذا فقال منقذ الهلالي فخرجت إليه فزعا فقال البشرى فقلت وأي بشرى أتتني بك في هذا الليل فقال خير أتاني أهلي بدجاجة مشوية بين رغيفين فتعشيت بها ثم\nأتوني بقنينة من نبيذ قد التقى طرفاها صفاء ورقة فجعلت أشرب وأترنم بقول نصيب\n(بزينب ألمم قبل أن يظعن الركب ... )\nفكرت في إنسان يفهم حسنه ويعرف فضله فلم أجد غيرك فأتيتك مخبرا بذلك فقلت ما جاء بك إلا هذا فقال أولا يكفى ثم انصرف أخبرني الحسين بن يحيى عن حماد عن أبيه قال قال مسلمة لنصيب أنت لا تحسن الهجاء فقال بلى والله أتراني لا أحسن أن أجعل مكان عافاك الله أخزاك الله قال فإن فلانا قد مدحته فحرمك فاهجه قال لا والله ما ينبغي أن أهجوه وإنما ينبغي أن أهجو نفسي حين مدحته فقال مسلمة هذا والله أشد من الهجاء","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":6,"spl":"عبد الله بن جعفر يسخو في عطائه للنصيب — قصة النصيب مع ابنة العجوز في الجحفة","partial":1},
{"id":"b4-15","bab":"الجزء 1","sec":"عمر بن عبد العزيز يطلب إلى النصيب إنشاده","page":"ج1 ص330","text":"أخبرني الحسين قال قال حماد قرأت على أبي عن ابن عباية عن الضحاك الحزامي قال دخل نصيب مسجد رسول الله وعمر بن عبد العزيز رضي الله عنه يومئذ أمير المدينة وهو جالس بين قبر النبي ومنبره فقال أيها الأمير ائذن لي أن أنشدك من مراثي عبد العزيز فقال لا تفعل فتحزنني ولكن أنشدني قولك قفا أخوي فإن شيطانك كان\nلك فيها ناصحا حين لقنك إياها فأنشده صوت\n(قفا أخوي إن الدار ليست ... كما كانت بعهدكما تكون)\n(ليالي تعلمان وآل ليلى ... قطين الدار فاحتمل القطين)\n(فعوجا فانظرا أتبين عما ... سألناها به أم لا تبين)\n(فظلا واقفين وظل دمعي ... على خدي تجود به الجفون)\n(فلولا إذ رأيت اليأس منها ... بدا أن كدت ترشقك العيون)\n(برحت فلم يلمك الناس فيها ... ولم تغلق كما غلق الرهين)\nي البيتين الأولين من هذه الأبيات والأخيرين لابن سريج خفيف رمل بالوسطى عن عمرو وفيه للغريض خفيف ثقيل أول بالوسطى عن عمرو ويونس","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":6,"spl":"عبد الله بن جعفر يسخو في عطائه للنصيب — قصة النصيب مع ابنة العجوز في الجحفة"},
{"id":"b4-16","bab":"الجزء 1","sec":"قصة النصيب مع ابنة العجوز في الجحفة","page":"ج1 ص331","text":"أخبرني الحسين عن حماد عن أبيه عن أيوب بن عباية قال كان نصيب ينزل على عجوز بالجحفة إذا قدم من الشام وكان لها بنية صفراء وكان يستحليها فإذا قدم وهب لها دراهم وثيابا وغير ذلك فقدم عليهما قدمة وبات بهما فلم يشعر إلا بفتى قد جاءها ليلا فركضها برجله فقامت معه فأبطأت ثم عادت وعاد إليها بعد ساعة فركضها برجله فقامت معه فأبطأت ثم عادت فلما أصبح نصيب رأى أثر معتركهما ومغتسلهما فلما أراد أن يرتحل قالت\nله العجوز وبنتها بأبي أنت عادتك فقال لها\n(أراك طموح العين ميالة الهوى ... لهذا وهذا منك ود ملاطف)\n(فإن تحملي ردفين لا أك منهما ... فحبي فرد لست ممن يرادف)\nلم يعطها شيئا ورحل قال أيوب وكانت بملل امرأة ينزل بها الناس فنزل بها أبو عبيدة بن عبد الله ابن زمعة وعمران بن عبد الله بن مطيع ونصيب فلما رحلوا وهب لها القرشيان ولم يكن مع نصيب شيء فقال لها اختاري إن شئت أن أضمن لك مثل ما أعطياك إذا قدمت وإن شئت قلت فيك أبياتا تنفعك قالت بل الشعر أحب إلي فقال\n(ألا حي قبل البين أم حبيب ... وإن لم تكن منا غدا بقريب)\n(لئن لم يكن حبيك حبا صدقته ... فما أحد عندي إذا بحبيب)\n(تهام أصابت قلبه مللية ... غريب الهوى يا ويح كل غريب)\nشهرها بذلك فأصابت بقوله ذلك فيها خيرا","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":6,"spl":"عبد الله بن جعفر يسخو في عطائه للنصيب — قصة النصيب مع ابنة العجوز في الجحفة"},
{"id":"b4-17","bab":"الجزء 1","sec":"النصيب يعاهد الله ألا يقول نسيبا","page":"ج1 ص332","text":"قال أيوب ودخل النصيب على عمر بن عبد العزيز رحمة الله عليه بعد ما ولي الخلافة فقال له إيه يا أسود أنت الذي تشهر النساء بنسيبك فقال إني قد تركت ذلك يا أمير المؤمنين وعاهدت الله عز و جل ألا أقول نسيبا وشهد له\nبذلك من حضر وأثنوا عليه خيرا فقال أما إذ كان الأمر هكذا فسل حاجتك فقال بنيات لي نفضت عليهن سوادي فكسدن أرغب بهن عن السودان ويرغب عنهن البيضان قال فتريد ماذا قال تفرض لهن ففعل قال ونفقة لطريقي قال فأعطاه حلية سيفه وكساه ثوبيه وكانا يساويان ثلاثين درهما أخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة عن إسحاق الموصلي عن ابن كناسة قال اجتمع النصيب والكميت وذو الرمة فأنشدهما الكميت قوله\n(هل أنت عن طلب الأيفاع منقلب ... )\nتى بلغ إلى قوله فيها\n(أم هل ظعائن بالعلياء نافعة ... وإن تكامل فيها الأنس والشنب)\nعقد نصيب واحدة فقال له الكميت ماذا تصحي قال خطأك باعدت في القول ما الأنس من الشنب ألا قلت كما قال ذو الرمة\n(لمياء في شفتيها حوة لعس ... وفي اللثاث وفي أنيابها شنب)\nم أنشدهما قوله\n(أبت هذه النفس إلا ادكارا ... )\nتى بلغ إلى قوله\n(إذا ما الهجارس غنينها ... تجاوبن بالفلوات الوبارا)\nقال له النصيب وبالوبار لا تسكن الفلوات ثم أنشد حتى بلغ منها\n(كأن الغطامط من غليها ... أراجيز أسلم تهجو غفارا)\nقال النصيب ما هجت أسلم غفارا قط فانكسر الكميت وأمسك","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":7,"spl":"النصيب يعاهد الله ألا يقول نسيبا — النصيب يمدح عبد الرحمن بن الضحاك","partial":1},
{"id":"b4-18","bab":"الجزء 1","sec":"النصيب يمدح عبد الرحمن بن الضحاك","page":"ج1 ص334","text":"أخبرني الحسين بن يحيى عن حماد بن إسحاق عن أبيه عن ابن الكلبي أن نصيبا مدح عبد الرحمن بن الضحاك بن قيس الفهري فأمر له بعشر قلائص وكتب بها إلى رجلين من الأنصار واعتذر إليه وقال له والله ما أملك إلا رزقي وإني لأكره أن أبسط يدي في أموال هؤلاء القوم فخرج حتى أتى الأنصاريين فأعطاهما الكتاب مختوما فقرآه وقالا قد أمر لك بثمان قلائص ودفعا ذلك إليه ثم عزل وولي مكانه رجل من بني نصر بن هوازن فأمر بأن يتتبع ما أعطى ابن الضحاك ويرتجع فوجد باسم نصيب عشر قلائص فأمر بمطالبته بها فقال والله ما دفع إلي إلا ثماني قلائص فقال والله ما تخرج من الدار حتى تؤدي عشر قلائص أو أثمانها فلم يخرج حتى قبض ذلك منه فلما قدم على هشام سمر عنده ليلة وتذاكروا النصري فأنشده قوله فيه\n(أفي قلائص جرب كن من عمل ... أردى وتنزع من أحشائي الكبد)\n(ثمانيا كن في أهلي وعندهم ... عشر فأي كتاب بعدنا وجدوا)\n(أخانني أخوا الأنصار فانتقصا ... منها فعندهما الفقد الذي فقدوا)\n(وإن عاملك النصري كلفني ... في غير نائرة دينا له صعد)\n(أذنب غيري ولم أذنب يكلفني ... أم كيف أقتل لا عقل ولا قود)\nال فقال هشام لا جرم والله لا يعمل لي النصري عملا أبدا فكتب بعزله عن المدينة أخبرني محمد بن خلف بن المرزبان قال أخبرنا الزبير بن بكار إجازة عن هارون بن عبد الله الزبيري عن شيخ من الجفر قال قدم علينا النصيب فجلس في هذا المجلس وأومأ إلى مجلس حذاءه فاستنشدناه فأنشدنا قوله\n(ألا يا عقاب الوكر وكر ضرية ... سقتك الغوادي من عقاب ومن وكر)\n(تمر الليالي ما مررن ولا أرى ... مرور الليالي منسياتي ابنة النضر)\n(وقفت بذي دوران أنشد ناقتي ... ومالي لديها من قلوص ولا بكر)\n(وما أنشد الرعيان إلا تعلة ... بواضحة الأنياب طيبة النشر)\n(أما والذي نادى من الطور عبده ... وعلم أيام المناسك والنحر)\n(لقد زادني للجفر حبا وأهله ... ليال أقامتهن ليلى على الجفر)","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":7,"spl":"النصيب يعاهد الله ألا يقول نسيبا — النصيب يمدح عبد الرحمن بن الضحاك"},
{"id":"b4-19","bab":"الجزء 1","sec":"النصيب يصف ابنة عم له نوبية","page":"ج1 ص336","text":"أخبرني الحرمي قال حدثنا الزبير قال أخبرني عمر بن إبراهيم السعدي عن يوسف بن يعقوب بن العلاء بن سليمان عن سلمة بن عبد الله بن أبي مسروح قال قال عبد الملك بن مروان لنصيب أنشدني فأنشده قصيدته التي يقول فيها\n(ومضمر الكشح يطويه الضجيع به ... طي الحمائل لا جاف ولا فقر)\n(وذي روادف لا يلفى الإزار بها ... يلوى ولو كان سبعا حين يأتزر)\nقال له عبد الملك يا نصيب من هذه قال بنت عم لي نوبية لو رأيتها ما شربت من يدها الماء فقال له لو غير هذا قلت لضربت الذي فيه عيناك أخبرني محمد بن خلف بن المرزبان قال حدثنا الحارث بن محمد بن أسامة قال حدثنا المدائني قال كان عبد العزيز بن مروان اشترى نصيبا وأهله وولده فأعتقهم وكان نصيب يرحل إليه في كل عام مستميحا فيجيزه ويحسن صلته فقال فيه نصيب\n(يقول فيحسن القول ابن ليلى ... ويفعل فوق أحسن ما يقول)\n(فتى لا يرزأ الخلان إلا ... مودتهم ويرزؤه الخليل)\n(فبشر أهل مصر فقد أتاهم ... مع النيل الذي في مصر نيل)","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":8,"spl":"النصيب يصف ابنة عم له نوبية — النصيب يشبب بجارية سقته ماء"},
{"id":"b4-20","bab":"الجزء 1","sec":"شاعر من أهل الحجاز يهجو النصيب","page":"ج1 ص337","text":"أخبرني هاشم بن محمد بن هارون بن عبد الله بن مالك الخزاعي أبو دلف قال حدثنا عبد الرحمن ابن أخي الأصمعي عن عمه قال كان نصيب يكنى أبا الحجناء فهجاه شاعر من أهل الحجاز فقال\n(رأيت أبا الحجناء في الناس حائرا ... ولون أبي الحجناء لون البهائم)\n(تراه على ما لاحه من سواده ... وإن كان مظلوما له وجه ظالم)\nقيل لنصيب ألا تجيبه فقال لا ولو كنت هاجيا لأحد لأجبته ولكن الله أوصلني بهذا الشعر إلى خير فجعلت على نفسي ألا أقوله في شر وما وصفني إلا بالسواد وقد صدق أفلا أنشدكم ما وصفت به نفسي قالوا بلى فأنشدهم قوله\n(ليس السواد بناقصي ما دام لي ... هذا اللسان إلى فؤاد ثابت)\n(من كان ترفعه منابت أصله ... فبيوت أشعاري جعلن منابتي)\n(كم بين أسود ناطق ببيانه ... ماضي الجنان وبين أبيض صامت)\n(إني ليحسدني الرفيع بناؤه ... من فضل ذاك وليس بي من شامت)\nيروى مكان من فضل ذاك فضل البيان وهو أجود أخبرني عمي ومحمد بن خلف قالا حدثنا عبد الله بن أبي سعد قال حدثني سعيد بن يحيى الأموى قال حدثني عمي عن محمد بن سعد قال قال قائل للنصيب أيها العبد مالك وللشعر فقال أما قولك عبد فما\nولدت إلا وأنا حر ولكن أهلي ظلموني فباعوني وأما السواد فأنا الذي أقول\n(وإن أك حالكا لوني فإني ... لعقل غير ذي سقط وعاء)\n(وما نزلت بي الحاجات إلا ... وفي عرضي من الطمع الحياء)","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":8,"spl":"النصيب يصف ابنة عم له نوبية — النصيب يشبب بجارية سقته ماء"},
{"id":"b4-21","bab":"الجزء 1","sec":"النصيب يشبب بجارية سقته ماء","page":"ج1 ص338","text":"أخبرني محمد بن مزيد قال حدثنا حماد عن أبيه قال حدثت عن السدوسي قال وقف نصيب على أبيات فاستسقى ماء فخرجت إليه جارية بلبن أو ماء فسقته وقالت شبب بي فقال وما اسمك فقالت هند ونظر إلى جبل وقال ما اسم هذا العلم قالت قنا فأنشأ يقول\n(أحب قنا من حب هند ولم أكن ... أبالي أقربا زاده الله أم بعدا)\n(ألا إن بالقيعان من بطن ذي قنا ... لنا حاجة مالت إليه بنا عمدا)\n(أروني قنا أنظر إليه فإنني ... أحب قنا إني رأيت به هندا)\nال فشاعت هذه الأبيات وخطبت هذه الجارية من أجلها وأصابت بقول نصيب فيها خيرا كثيرا أخبرني هاشم بن محمد الخزاعي قال حدثنا عيسى بن إسماعيل بن نبيه قال حدثنا محمد بن سلام قال دخل نصيب على يزيد بن عبد الملك فقال له حدثني يا نصيب ببعض ما مر عليك فقال نعم يا أمير المؤمنين علقت جارية حمراء فمكثت زمانا تمنيني بالأباطيل فلما ألححت عليها قالت إليك عني فوالله لكأنك من طوارق\nالليل فقلت لها وأنت والله لكأنك من طوارق النهار فقالت ما أظرفك يا أسود فغاظني قولها فقلت لها هل تدرين ما الظرف إنما الظرف العقل ثم قالت لي انصرف حتى أنظر في أمرك فأرسلت إليها هذه الأبيات\n(فإن أك حالكا فالمسك أحوى ... وما لسواد جلدي من دواء)\n(ولي كرم عن الفحشاء ناء ... كبعد الأرض من جو السماء)\n(ومثلي في رجالكم قليل ... ومثلك ليس يعدم في النساء)\n(فإن ترضي فردي قول راض ... وإن تأبي فنحن على السواء)\nال فلما قرأت الشعر قالت المال والشعر يأتيان على غيرهما فتزوجتني","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":8,"spl":"النصيب يصف ابنة عم له نوبية — النصيب يشبب بجارية سقته ماء"},
{"id":"b4-22","bab":"الجزء 1","sec":"الأصمعي ينشد شعرا للنصيب","page":"ج1 ص339","text":"أخبرنا هاشم بن محمد قال حدثنا الرياشي قال أنشدنا الأصمعي لنصيب وكان يستجيد هذه الأبيات ويقول إذا أنشدها قاتل الله نصيبا ما أشعره\n(فإن يك من لوني السواد فإنني ... لكا لمسك لا يروى من المسك ذائقه)\n(وما ضر أثوابي سوادي وتحتها ... لباس من العلياء بيض بنائقه)\n(إذا المرء لم يبذل من الود مثل ما ... بذلت له فاعلم بأني مفارقه)\nأخبرني الفضل بن الحباب أبو خليفة قال حدثنا محمد بن سلام عن خلف أن نصيبا أنشد جريرا شيئا من شعره فقال له كيف ترى يا أبا حزرة فقال له أنت أشعر أهل جلدتك أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني محمد ابن إسماعيل عن عبد العزيز بن عمران بن محمد عن المسور بن عبد الملك قال قال نصيب لعبد الرحمن بن أزهر أنشدت الوليد بن عبد الملك فقال لي أنت أشعر أهل جلدتك والله ما زاد عليها فقال لي عبد الرحمن يا أبا محجن أفرضيت منه أن جعلك أشعر السودان فقط فقال له وددت والله يابن أخي أنه أعطاني أكثر من هذا ولكنه لم يفعل ولست بكاذبك","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":9,"spl":"الأصمعي ينشد شعرا للنصيب — النصيب يصنف شعره وشعر معاصريه"},
{"id":"b4-23","bab":"الجزء 1","sec":"النصيب يصنف شعره وشعر معاصريه","page":"ج1 ص340","text":"أخبرني محمد بن الحسن بن دريد قال حدثنا أبو حاتم قال أخبرنا أبو عبيدة قال قال لي محمد بن عبد ربه دخلت مسجد الكوفة فرأيت رجلا لم أر قط مثله ولا أشد سوادا منه ولا أنقى ثيابا منه ولا أحسن زيا فسألت عنه فقيل هذا نصيب فدنوت منه فحدثته ثم قلت له أخبرني عنك وعن أصحابك فقال جميل إمامنا وعمر بن أبي ربيعة أوصفنا لربات الحجال وكثير أبكانا على الدمن وأمدحنا للملوك وأما أنا فقد قلت ما سمعت فقلت له إن الناس يزعمون أنك لا تحسن أن تهجو فضحك ثم قال أفتراهم يقولون إني لا أحسن أن أمدح فقلت لا فقال أفما تراني أحسن أن أجعل مكان عافاك الله أخزاك\nالله قال قلت بلى قال فإني رأيت الناس رجلين إ ما رجل لم أسأله شيئا فلا ينبغي أن أهجوه فأظلمه وإما رجل سألته فمنعني فنفسي كانت أحق بالهجاء إذ سولت لي أن أسأله وأن أطلب ما لديه","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":9,"spl":"الأصمعي ينشد شعرا للنصيب — النصيب يصنف شعره وشعر معاصريه"},
{"id":"b4-24","bab":"الجزء 1","sec":"نصيب وكثير والأحوص ينزلون في مجلس امرأة من بني أمية","page":"ج1 ص341","text":"أخبرني محمد بن خلف بن المرزبان قال حدثني عبد الله بن إسماعيل بن أبي عبيد الله كاتب المهدي قال وجدت في كتاب أبي بخطه حدثني أبو يوسف التجيبي قال حدثني إسماعيل بن المختار مولى آل طلحة وكان شيخا كبيرا قال\nحدثني النصيب أبو محجن أنه خرج هو وكثير والأحوص غب يوم أمطرت فيه السماء فقال هل لكم في أن نركب جميعا فنسير حتى نأتي العقيق فنمتع فيه أبصارنا فقالوا نعم فركبوا أفضل ما يقدرون عليه من الدواب ولبسوا أحسن ما يقدرون عليه من الثياب وتنكروا ثم ساروا حتى أتوا العقيق فجعلوا يتصفحون ويرون بعض ما يشتهون حتى رفع لهم سواد عظيم فأموه حتى أتوه فإذا وصائف ورجال من الموالي ونساء بارزات فسألنهم أن ينزلوا فاستحيوا أن يجيبوهن من أول وهلة فقالوا لا نستطيع أو نمضي في حاجة لنا فحلفنهم أن يرجعوا إليهن ففعلوا وأتوهن فسألنهم النزول فنزلوا ودخلت امرأة من النساء فاستأذنت لهم فلم تلبث أن جاءت المرأة فقالت ادخلوا فدخلنا على امرأة جميلة برزة على فرش لها فرحبت وحيت وإذا كراسي موضوعة فجلسنا جميعا في صف واحد كل إنسان على كرسي فقالت إن أحببتم أن ندعو بصبي لنا فنصيحه ونعرك أذنه فعلنا وإن شئتم بدأنا بالغداء فقلنا بل تدعين بالصبي ولن يفوتنا الغداء\nفأومأت بيدها إلى بعض الخدم فلم يكن إلا كلا ولا حتى جاءت جارية جميلة قد سترت بمطرف فأمسكوه عليها حتى ذهب بهرها ثم كشف عنها وإذا جارية ذات جمال قريبة من جمال مولاتها فرحبت بهم وحيتهم فقالت لها مولاتها خذي ويحك من قول النصيب عافى الله أبا محجن\n(ألا هل من البين المفرق من بد ... وهل مثل أيام بمنقطع السعد)\n(تمنيت أيامي أولئك والمنى ... على عهد عاد ما تعيد ولا تبدي)\nغنته فجاءت به كأحسن ما سمعته قط بأحلى لفظ وأشجى صوت ثم قالت لها خذي أيضا من قول أبي محجن عافى الله أبا محجن\n(أرق المحب وعاده سهده ... لطوارق الهم التي ترده)\n(وذكرت من رقت له كبدي ... وأبى فليس ترق لي كبده)\n(لا قومه قومي ولا بلدي ... فنكون حينا جيرة بلده)\n(ووجدت وجدا لم يكن أحد ... قبلي من اجل صبابة يجده)\n(إلا ابن عجلان الذي تبلت ... هند ففات بنفسه كمده)\nال فجاءت به أحسن من الأول فكدت أطير سرورا ثم قالت لها ويحك خذي من قول أبي محجن عافى الله أبا محجن\n(فيا لك من ليل تمتعت طوله ... وهل طائف من نائم متمتع)\n(نعم إن ذا شجو متى يلق شجوه ... ولو نائما مستعتب أو مودع)\n(له حاجة قد طالما قد أسرها ... من الناس في صدر بها يتصدع)\n(تحملها طول الزمان لعلها ... يكون لها يوما من الدهر منزع)\n(وقد قرعت في أم عمرو لي العصا ... قديما كما كانت لذي الحلم تقرع)\nال فجاءت والله بشيء حيرني وأذهلني طربا لحسن الغناء وسرورا باختيارها الغناء في شعري وما سمعت فيه من حسن الصنعة وجودتها وإحكامها ثم قالت لها خذي أيضا من قول أبي محجن عافى الله أبا محجن\n(يا أيها الركب إني غير تابعكم ... حتى تلموا وأنتم بي ملمونا)\n(فما أرى مثلكم ركبا كشكلكم ... يدعوهم ذو هوى إلا يعوجونا)\n(أم خبروني عن دائي بعلمكم ... وأعلم الناس بالداء الأطبونا)","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":10,"spl":"نصيب وكثير والأحوص ينزلون في مجلس امرأة من بني أمية — غضب الأحوص وكثير لأن المرأة لم تهتم "},
{"id":"b4-25","bab":"الجزء 1","sec":"غضب الأحوص وكثير لأن المرأة لم تهتم بهما","page":"ج1 ص344","text":"قال نصيب فوالله لقد زهيت بما سمعت زهوا خيل إلي أني من قريش وأن الخلافة لي ثم قالت حسبك يا بنية هات الطعام يا غلام فوثب الأحوص وكثير وقالا والله لا نطعم لك طعاما ولا نجلس لك في مجلس فقد أسأت عشرتنا واستخففت بنا وقدمت شعر هذا على أشعارنا واستمعت الغناء فيه وإن في أشعارنا لما يفضل شعره وفيها من الغناء ما هو أحسن من هذا فقالت على معرفة كل ما كان مني فأي شعركما أفضل من شعره أقولك يا أحوص\n(يقر بعيني ما يقر بعينها ... وأحسن شيء ما به العين قرت)\nو قولك يا كثير في عزة\n(وما حسبت ضمرية جدوية ... سوى التيس ذي القرنين أن لها بعلا)\nم قولك فيها\n(إذا ضمرية عطست فنكها ... فإن عطاسها طرف السفاد)\nال فخرجنا مغضبين واحتبستني فتغديت عندها وأمرت لي بثلثمائة دينار\nوحلتين وطيب ثم دفعت إلي مائتي دينار وقالت ادفعها إلى صاحبيك فإن قبلاها وإلا فهي لك فأتيتهما منازلهما فأخبرتهما القصة فأما الأحوص فقبلها وأما كثير فلم يقبلها وقال لعن الله صاحبتك وجائزتها ولعنك معها فأخذتها وانصرفت فسألت النصيب ممن المرأة فقال من بني أمية ولا أذكر اسمها ما حييت لأحد","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":10,"spl":"نصيب وكثير والأحوص ينزلون في مجلس امرأة من بني أمية — غضب الأحوص وكثير لأن المرأة لم تهتم "},
{"id":"b4-26","bab":"الجزء 1","sec":"رثاء نصيب عبد العزيز بن مروان وقد مات بسكر من قرى الصعيد","page":"ج1 ص345","text":"أخبرني عيسى بن يحيى الوراق عن أحمد بن الحارث الخراز قال حدثنا المدائني قال وقع الطاعون بمصر في ولاية عبد العزيز بن مروان إياها فخرج هاربا منه فنزل بقرية من الصعيد يقال لها سكر فقدم عليه حين نزلها رسول لعبد الملك فقال له عبد العزيز ما اسمك فقال طالب بن مدرك فقال أوه ما أراني راجعا إلى الفسطاط أبدا ومات في تلك القرية فقال نصيب يرثيه\n(أصبت يوم الصعيد من سكر ... مصيبة ليس لي بها قبل)\n(تالله أنسى مصيبتي أبدا ... ما أسمعتني حنينها الإبل)\n(ولا التبكي عليه أعوله ... كل المصيبات بعده جلل)\n(لم يعلم النعش ما عليه من العرف ... ولا الحاملون ما حملوا)\n(حتى أجنوه في ضريحهم ... حين انتهى من خليلك الأمل)\nنى في هذه الأبيات ابن سريج ولحنه رمل بالسبابة في مجرى الوسطى عن إسحاق وذكر الهشامي أن له فيه لحنا من الهزج وذكر ابن بانة أن الرمل لابن الهربذ","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":11,"spl":"رثاء نصيب عبد العزيز بن مروان وقد مات بسكر من قرى الصعيد — نصيب يمدح إبراهيم بن هشام فلا ي"},
{"id":"b4-27","bab":"الجزء 1","sec":"نصيب ينشد عبد الملك بن مروان رثاء في أخيه عبد العزيز","page":"ج1 ص346","text":"أخبرني محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه عن مصعب الزبيري عن مشيخة من أهل الحجاز\nأن نصيبا دخل على عبد الملك بن مروان فقال له أنشدني بعض ما رثيت به أخي فأنشده قوله\n(عرفت وجربت الأمور فما أرى ... كماض تلاه الغابر المتأخر)\n(ولكن أهل الفضل من أهل نعمتي ... يمرون أسلافا أمامي وأغبر)\n(فإن أبكه أعذر وإن أغلب الأسى ... بصبر فمثلي عندما اشتد يصبر)\n(وكانت ركابي كلما شئت تنتحي ... إليك فتقضي نحبها وهي ضمر)\n(ترى الورد يسرا والثواء غنيمة ... لديك وتثنى بالرضا حين تصدر)\n(فقد عريت بعد ابن ليلى فإنما ... ذراها لمن لاقت من الناس منظر)\n(ولو كان حيا لم يزل بدفوفها ... مراد لغربان الطريق ومنقر)\n(فإن كن قد نلن ابن ابن ليلى فإنه ... هو المصطفى من أهله المتخير)\nفلما سمع عبد الملك قوله\n(فإن أبكه أعذر وإن أغلب الأسى ... بصبر فمثلي عندما اشتد يصبر)\nال له ويلك أنا كنت أحق بهذه الصفة في أخي منك فهلا وصفتني بها وجعل يبكي","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":11,"spl":"رثاء نصيب عبد العزيز بن مروان وقد مات بسكر من قرى الصعيد — نصيب يمدح إبراهيم بن هشام فلا ي"},
{"id":"b4-28","bab":"الجزء 1","sec":"نصيب وعبد الله بن إسحاق البصري","page":"ج1 ص347","text":"أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه عن أبي يحيى محمد بن كناسة قال قال لي عبد الله بن إسحاق البصري لو وليت العراق لاستكتبت نصيبا قالت لماذا قال لفصاحته وحسن تخلصه إلى جيد الكلام ألم تسمع قوله\n(فلا النفس ملتها ولا العين تنتهي ... إليها سوام الطرف عنها فترجع)\n(رأتها فما ترتد عنها سآمة ... ترى بدلا منها به النفس تقنع)","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":11,"spl":"رثاء نصيب عبد العزيز بن مروان وقد مات بسكر من قرى الصعيد — نصيب يمدح إبراهيم بن هشام فلا ي"},
{"id":"b4-29","bab":"الجزء 1","sec":"نصيب يمدح إبراهيم بن هشام فلا يعجبه المديح","page":"ج1 ص347","text":"أخبرني الحرمي عن الزبير عن محمد بن الحسن قال دخل نصيب على إبراهيم بن هشام فأنشده مديحا له فقال إبراهيم ما هذا بشيء أين هذا من قول أبي دهبل لصاحبنا ابن الأزرق حيث يقول\n(إن تغد من منقلي نخلان مرتحلا ... يرحل من اليمن المعروف والجود)\nال فغضب نصيب ونزع عمامته وبرك عليها وقال لئن تأتونا برجال مثل ابن الأزرق نأتكم بمثل مديح أبي دهبل أو أحسن إن المديح والله إنما يكون على قدر الرجال قال فأطرق ابن هشام وعجبوا من إقدام نصيب عليه ومن حلم ابن هشام وهو غير حليم","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":11,"spl":"رثاء نصيب عبد العزيز بن مروان وقد مات بسكر من قرى الصعيد — نصيب يمدح إبراهيم بن هشام فلا ي"},
{"id":"b4-30","bab":"الجزء 1","sec":"نصيب وأم بكر الخزاعية","page":"ج1 ص348","text":"أخبرني الحرمي قال حدثنا الزبير قال حدثني عبد الرحمن بن عبد الله الزهري أن نصيبا كان ربما قدم من الشام فيطرح في حجر أم بكر الخزاعية أربعمائة دينار وأن عبد الملك بن مروان ظهر على تعلقه بها ونسيبه فيها فنهاه عن ذلك حتى كف","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":12,"spl":"نصيب وأم بكر الخزاعية — نصيب والحكم بن المطلب"},
{"id":"b4-31","bab":"الجزء 1","sec":"نصيب ينشد شعرا في مديح ابن هشام في مجلس ثقيف","page":"ج1 ص348","text":"أخبرني محمد بن يزيد قال حدثنا حماد بن إسحاق عن أبيه عن عثمان بن حفص الثقفي عن أبيه قال رأيت النصيب بالطائف فجاءنا وجلس في مجلسنا وعليه قميص قوهي ورداء وحبرة فجعل ينشدنا مديحا لابن هشام ثم قال إن الوادي مسبعة فمن أهل المجلس قالوا ثقيف فعرف أنا نبغض ابن هشام ويبغضنا فقال إنا لله أبعد ابن ليلى أمتدح ابن جيداء فقال له أهل المجلس يا أبا محجن أتطلب القريض أحيانا فيعسر عليك فقال إي والله لربما فعلت فآمر براحلتي فيشد بها رحلي ثم أسير في الشعاب الخالية وأقف في الرباع المقوية فيطربني ذلك ويفتح لي الشعر والله إني على ذلك ما قلت بيتا قط تستحي الفتاة الحيية من إنشاده في ستر أبيها قال إسحاق قال عثمان بن حفص فوصفه أبي وقال كأني أراه صدعا خفيف العارضين ناتىء الحنجرة","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":12,"spl":"نصيب وأم بكر الخزاعية — نصيب والحكم بن المطلب"},
{"id":"b4-32","bab":"الجزء 1","sec":"نصيب وابن أبي عتيق","page":"ج1 ص349","text":"أخبرني محمد بن مزيد قال حدثنا حماد عن أبيه عن محمد بن كناسة قال أنشد نصيب قوله\n(وكدت ولم أخلق من الطير إن بدا ... لها بارق نحو الحجاز أطير)\nسمعه ابن أبي عتيق فقال يابن أم هل غاق فإنك تطير يعني أنه غراب أسود أخبرني الحرمي قال حدثنا الزبير قال أخبرني أحمد بن محمد الأسدي أسد قريش قال قال ابن أبي عتيق لنصيب إني خارج أفترسل إلى سعدى بشيء قال نعم بيتي شعر قال قل فقال\n(أتصبر عن سعدى وأنت صبور ... وأنت بحسن الصبر منك جدير)\n(وكدت ولم أخلق من الطير إن بدا ... سنى بارق نحو الحجاز أطير)\nال فأنشد ابن أبي عتيق سعدى البيتين فتنفست تنفسة شديدة فقال ابن أبي عتيق أوه أجبته والله بأجود من شعره ولو سمعك خليلك لنعق وطار إليك","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":12,"spl":"نصيب وأم بكر الخزاعية — نصيب والحكم بن المطلب"},
{"id":"b4-33","bab":"الجزء 1","sec":"نصيب والحكم بن المطلب","page":"ج1 ص350","text":"أخبرني علي بن صالح بن الهيثم الكاتب قال حدثني أبو هفان عن إسحاق الموصلي عن المسيبي قال قال أبو النجم أتيت الحكم بن المطلب فمدحته وخرج إلى السعاية فخرجنا معه ومعه عدة من الشعراء فبينا هو مع أصحابه يوما واقف إذا براكب يوضع في السراب وإذا هو نصيب فتقدم إليه فمدحه فأمر بإنزاله فمكث أياما حتى أتاه فقال إني قد خلفت صبية صغارا وعيالا ضعافا فقال له ادخل\nالحظيرة فخذ منها سبعين فريضة فقال له جعلني الله فداك قد أحسنت ومعي ابن لي أخاف أن يثلمها علي قال فادخل فخذ له سبعين فريضة أخرى فانصرف بمائة وأربعين فريضة أخبرنا الحرمي بن أبي العلاء عن الزبير عن محمد بن الضحاك عن عثمان عن أبيه قال قيل لنصيب هرم شعرك قال لا والله ما هرم ولكن العطاء هرم ومن يعطيني مثل ما أعطاني الحكم بن المطلب خرجت إليه وهو ساع على بعض صدقات المدينة فلما رأيته قلت\n(أبا مروان لست بخارجي ... وليس قديم مجدك بانتحال)\n(أغر إذا الرواق انجاب عنه ... بدا مثل الهلال على المثال)\n(تراءاه العيون كما تراءى ... عشية فطرها وضح الهلال)\nال فأعطاني أربعمائة ضائنة ومائة لقحة وقال ارفع فراشي فرفعته فأخذت من تحته مائتي دينار","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":12,"spl":"نصيب وأم بكر الخزاعية — نصيب والحكم بن المطلب"},
{"id":"b4-34","bab":"الجزء 1","sec":"نصيب وكثير عند أبي عبيدة بن عبد الله بن زمعة","page":"ج1 ص351","text":"أخبرني عيسى بن الحسين الوراق قال حدثنا الزبير قال حدثني أسعد بن عبد\nالله المري عن إبراهيم بن سعيد بن بشر بن عبد الله بن عقيل الخارجي عن أبيه قال والله إني لمع أبي عبيدة بن عبد الله بن زمعة في حواء له إذ جاءه كثير فحياه فاحتفى به ودعا بالغداء فشرعنا فيه وشرع معنا كثير وجاء رجل فسلم فرددنا عليه السلام واستدنيناه فإذا نصيب في بزة جميلة قد وافى الحج قادما من الشام فأكب على أبي عبيدة فعانقه وسأله ثم دعاه إلى الغداء فأكل مع القوم فرفع كثير يده وأقلع عن الطعام وأقبل عليه أبو عبيدة والقوم جميعا يسألونه أن يأكل فأبى فتركوه وأقبل كثير على نصيب فقال والله يا أبا محجن إن أثر أهل الشام عليك لجميل لقد رجعت هذه الكرة ظاهر الكبر قليل الحياء فقال له نصيب لكن أثر الحجاز عليك يا أبا صخر غير جميل لقد رجعت وإنك لزائد النقص كثير الحماقة فقال كثير أنا والله أشعر العرب حيث أقول لمولاتك\n(إذا أمسبت بطن مجاح دوني ... وعمق دون عزة فالبقيع)\n(فليس بلائمي أحد يصلي ... إذا أخذت مجاريها الدموع)\nقال له نصيب أنا والله أشعر منك حيث أقول لابنة عمك\n(خليلي إن حلت كلية فالربا ... فذا أمج فالشعب ذا الماء والحمض)\n(فأصبح من حوران رحلي بمنزل ... يبعده من دونها نازح الأرض)\n(وأيأستما أن يجمع الدهر بيننا ... فخوضا لي السم المصرح بالمحض)\n(ففي ذاك من بعض الأمور سلامة ... وللموت خير من حياة على غمض)\nال فاقتحم إليه كثير وثبت له النصيب فلما نالته رجلاه رمحه نصيب بساقه رمحة طاح منها بعيدا عنه فما زال راقدا حتى أيقظناه عشيا لرمي الجمار أخبرني الحرمي بن أبي العلاء عن الزبير عن محمد بن موسى بن طلحة عن عبد الله بن عمر بن عثمان النحوي عن أنيس بن ربيعة الأسلمي أنه قال غدوت يوما إلى أبي عبيدة بن عبد الله بن زمعة وهو محتل بالرحبة فألفيت عنده جماعة منا ومن غيرنا فأتاه آت فقال له ذاك النصيب منذ ثلاث بالفرش من ملل متلدد كأنه واله في أثر قوم ظاعنين فنهض أبو عبيدة ونهضنا معه فإذا نصيب على المنحر من صفر فلما عايننا وعرف أبا عبيدة هبط فسأله عن أمره فأخبره أنه تبع قوما سائرين وأنه وجد آثارهم ومحلهم بالفرش فاستولهه ذلك فضحك به أبو عبيدة والقوم وقالوا له إنما يهتر إذا\nعشق من انتسب عذريا فأما أنت فما لك ولهذا فاستحيا وسكن وسأله أبو عبيدة هل قلت في مقامك شعرا قال نعم وأنشد\n(لعمري لئن أمسيت بالفرش مقصدا ... ثوياك عبود وعدنة أو صفر)\n(ففرع صبا أو تيمم مصعدا ... لربع قديم العهد ينتكف الأثر)\n(دعا أهله بالشام برق فأوجفوا ... ولم أر متبوعا أضر من المطر)\n(لتستبدلن قلبا وعينا سواهما ... وإلا أتى قصدا حشاشتك القدر)\n(خليلي فيما عشتما أو رأيتما ... هل اشتاق مضرور إلى من به أضر)\n(نعم ربما كان الشقاء متيحا ... يغطي على سمع ابن آدم والبصر)\nال فانصرف به أبو عبيدة إلى منزله وأطعمه وكساه وحمله وانصرف وهو يقول\n(أصاب دواء علتك الطبيب ... وخاض لك السلو ابن الربيب)\n(وأبصر من رقاك منفثات ... وداؤك كان أعرف بالطبيب)","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":13,"spl":"نصيب وكثير عند أبي عبيدة بن عبد الله بن زمعة — هشام بن محمد يكرم نصيبا"},
{"id":"b4-35","bab":"الجزء 1","sec":"نصيب ويزيد بن عبد الملك","page":"ج1 ص354","text":"أخبرني محمد بن الحسن بن دريد قال حدثنا أبو حاتم عن الأصمعي قال دخل نصيب على يزيد بن عبد الملك ذات يوم فأنشده قصيدة امتدحه بها فطرب لها يزيد واستحسنها فقال له أحسنت يا نصيب سلني ما شئت فقال يدك يا أمير المؤمنين بالعطاء أبسط من لساني بالمسألة فأمر به فملىء فمه جوهرا فلم يزل به غنيا حتى مات","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":13,"spl":"نصيب وكثير عند أبي عبيدة بن عبد الله بن زمعة — هشام بن محمد يكرم نصيبا"},
{"id":"b4-36","bab":"الجزء 1","sec":"هشام بن محمد يكرم نصيبا","page":"ج1 ص355","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير قال حدثنا أبو غزبة عن عبد الرحمن بن أبي الزناد قال دخل نصيب على إبراهيم بن هشام وهو وال على المدينة فأنشده قوله\n(يابن الهشامين لا بيت كبيتهما ... إذا تسامت إلى أحسابها مضر)\nفقال له إبراهيم قم يا أبا محجن إلى تلك الراحلة المرحولة فخذها برحلها فقام إليها نصيب متباطئا والناس يقولون ما رأينا عطية أهنأ من هذه ولا أكرم ولا أعجل\nولا أجزل فسمعهم نصيب فأقبل عليهم وقال والله إنكم قلما صاحبتم الكرام وما راحلة ورحل حتى ترفعوهما فوق قدرهما","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":13,"spl":"نصيب وكثير عند أبي عبيدة بن عبد الله بن زمعة — هشام بن محمد يكرم نصيبا"},
{"id":"b4-37","bab":"الجزء 1","sec":"هشام بن عبد الملك يعفو عن نصيب ويصله","page":"ج1 ص356","text":"أخبرني الحرمي وعيسى بن الحسين قالا حدثنا الزبير عن عبد الله بن محمد ابن عبد الله بن عمرو بن عثمان بن عفان عن أبيه قال استبطأ هشام بن عبد الملك حين ولي الخلافة نصيبا ألا يكون جاءه وافدا عليه مادحا له ووجد عليه وكان نصيب مريضا فبلغه ذلك حين برأ فقدم عليه وعليه أثر المرض وعلى راحلته أثر النصب فأنشده قصيدته التي يقول فيها\n(حلفت بمن حجت قريش لبيته ... وأهدت له بدنا عليها القلائد)\n(لئن كنت طالت غيبتي عنك إنني ... بمبلغ حولي في رضاك لجاهد)\n(ولكنني قد طال سقمي وأكثرت ... علي العهاد المشفقات العوائد)\n(صريع فراش لا يزلن يقلن لي ... بنصح وإشفاق متى أنت قاعد)\n(فلما زجرت العيس أسرت بحاجتي ... إليك وذلت للسان القصائد)\n(وإني فلا تستبطني بمودتي ... ونصحي وإشفاقي إليك لعامد)\n(فلا تقصني حتى أكون بصرعة ... فييأس ذو قربى ويشمت حاسد)\n(أنلني وقربني فإني بالغ ... رضاك بعفو من نداك وزائد)\n(أبت نائما أما فؤادي فهمه ... قليل وأما مس جلدي فبارد)\n(وقد كان لي منكم إذا ما لقيتكم ... ليان ومعروف وللخير قائد)\n(إليك رحلت العيس حتى كأنها ... قسي السرى ذبلا برتها الطرائد)\n(وحتى هواديها دقاق وشكوها ... صريف وباقي النقي منها شرائد)\n(وحتى ونت ذات المراح فأذعنت ... إليك وكل الراسمات الحوافد)\nال فرق له هشام وبكى وقال له ويحك يا نصيب لقد أضررنا بك وبرواحلك ووصله وأحسن صلته واحتفل به","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":14,"spl":"هشام بن عبد الملك يعفو عن نصيب ويصله — نصيب عند عبد الواحد النصري أمير المدينة"},
{"id":"b4-38","bab":"الجزء 1","sec":"نصيب عند عبد الواحد النصري أمير المدينة","page":"ج1 ص357","text":"أخبرنا الحرمي عن الزبير عن عمه عن أيوب بن عباية قال قدم نصيب على عبد الواحد النصري وهو أمير المدينة بفرش من أمير المؤمنين يضعه في قومه من بني ضمرة فأدخلهم عليه ليفرض لهم وفيهم أربعة غلمة لم يحتلموا فردهم النصري فكلمه نصيب كلاما غليظا إدلالا بمنزلته عند الخليفة فأشار إليه إبراهيم بن عبد الله بن مطيع أن اسكت وكف واخرج فإني كافيك فلما خرج إبراهيم لقيه نصيب فقال له أشرت إلي فكرهت أن أغضبك\nفما كرهت لي من مراجعته والصلابة له ومن ورائي المستعتب من أمير المؤمنين فقال إبراهيم هو رجل عربي حديد غلق وخشيت إن جاذبته شيئا ألا يرجع عنه وأن يمضي عليه ويلج فيه وهو مالك للأمر وله فيه سلطان فأردت أن تخرج قبل أن يلج ويظهر منه ما لا يرجع عنه فيمضى عليه ويلج فيه فتنتظر لتصادف منه طيب نفس فتكلمه ونرفدك عنده فقال نصيب\n(يومان يوم لرزيق فسل ... ويومه الآخر سمح فضل)\nنا جعلت فداءك فاعل ذلك فإذا رأيت القول فأشر إلي حتى أكلمه قال ودخل إليه نصيب عشيات كل ذلك يشير إليه ابن مطيع ألا يكلمه حتى صادف عشية من العشيات منه طيب نفس فأشار إليه أن كلمه فكلمه نصيب فأصاب مختله بكلامه ثم قال إني قد قلت شعرا فاسمعه أيها الأمير وأجزه ثم قال\n(أهاج البكا ربع بأسفل ذي السدر ... عفاه اختلاف العصر بعدك والقطر)\n(نعم فثناني الوجد فاشتقت للذي ... ذكرت وليس الشوق إلا مع الذكر)\n(حلفت برب الموضعين لربهم ... وحرمة ما بين المقام إلى الحجر)\n(لئن حاجتي يوما قضيت ورشتني ... بنفحة عرف من يديك أبا بشر)\n(لتعترفن الدهر مني مودة ... ونصحا على نصح وشكرا على شكر)\n(سقى الله صوب المزن أرضا عمرتها ... بري وأسقاها بلاد بني نصر)\n(بوجهك فاستعملت ما دمت خائفا ... لربك تقضي راشدا آخر الدهر)\n(لتنقذ أصحابي وتستر عورة ... بدت لك من صحبي فإنك ذو ستر)\n(فما بأمير المؤمنين إلى التي ... سألت فأعطاني لقومي من فقر)\n(وقد خرجت منه إليك فلا تكن ... بموضع بيضات الأنوق من الوكر)\nقال فقال عثمان بن حيان المري وهو عنده وكان قد جاءه بالقود من ابن حزم قد احتلم الآن القوم أيها الأمير واستوجبوا الفرض ورفده ابن مطيع فأحسن واشتد عليه أن شركه ابن حيان في رفده وتشييعه وقال النصري لابن مطيع وابن حيان صدقتما ما قد احتلموا واستوجبوا الفرض افرض لهم يا فلان لكاتب من كتابه ففرض لهم","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":14,"spl":"هشام بن عبد الملك يعفو عن نصيب ويصله — نصيب عند عبد الواحد النصري أمير المدينة"},
{"id":"b4-39","bab":"الجزء 1","sec":"حديث نصيب عن نفسه أنه عشق أمة لبني مدلج وشعره فيها","page":"ج1 ص359","text":"أخبرني محمد بن خلف بن المرزبان قال حدثني جعفر بن علي اليشكري\nقال حدثني الرياشي عن العتبي قال دخل نصيب على عبد العزيز بن مروان فقال له عبد العزيز وقد طال الحديث بينهما هل عشقت قط قال نعم أمة لبني مدلج قال فكنت تصنع ماذا قال كانوا يحرسونها مني فكنت أقنع أن أراها في الطريق وأشير إليها بعيني أو حاجبي وفيها أقول\n(وقفت لها كيما تمر لعلني ... أخالسها التسليم إن لم تسلم)\n(ولما رأتني والوشاة تحدرت ... مدامعها خوفا ولم تتكلم)\n(مساكين أهل العشق ما كنت أشتري ... جميع حياة العاشقين بدرهم)\nقال عبد العزيز ويحك فما فعلت قال بيعت فأولدها سيدها قال فهل في نفسك منها شيء قال نعم عقابيل أحزان","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":15,"spl":"حديث نصيب عن نفسه أنه عشق أمة لبني مدلج وشعره فيها — نصيب ونسوة كن يتناشدن الشعر في المسجد"},
{"id":"b4-40","bab":"الجزء 1","sec":"عبد العزيز بن مروان يحمل دينا عن نصيب","page":"ج1 ص360","text":"أخبرني الحرمي قال حدثنا الزبير قال حدثني بهلول بن سليمان بن قرضاب البلوي أن إبلا لنصيب أجدبت وحالت وكان لرجل من أسلم عليه ثمانية آلاف درهم قال فأخبرني أبي وعمي أنه وفد على عبد العزيز بن مروان فقال له\nجعلني الله فداءك إني حملت دينا في إبل ابتعتها مجدبات حيال وقد قلت فيها شعرا قال أنشده فأنشده\n(فلما حملت الدين فيها وأصبحت ... حيالا مسنات الهوى كدت أندم)\n(على حين أن راث الربيع ولم يكن ... لها بصعيد من تهامة مقضم)\n(ثمانية للأسلمي وما دنا ... لفحش ولا تدنو إلى الفحش أسلم)\nقال له عبد العزيز فما دينك ويحك قال ثمانية آلاف فأمر له بثمانية آلاف درهم فلما رجع أنشد الأسلمي الشعر فترك ماله عليه وقال الثمانية الآلاف لك","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":15,"spl":"حديث نصيب عن نفسه أنه عشق أمة لبني مدلج وشعره فيها — نصيب ونسوة كن يتناشدن الشعر في المسجد"},
{"id":"b4-41","bab":"الجزء 1","sec":"نصيب ونسوة كن يتناشدن الشعر في المسجد الحرام","page":"ج1 ص361","text":"أخبرني محمد بن مزيد قال حدثنا الزبير بن بكار قال حدثني الموصلي عن ابن أبي عبيدة قال أتى نصيب مكة فأتى المسجد الحرام ليلا فبينما هو كذلك إذ طلع ثلاث نسوة فجلسن قريبا منه وجعلن يتحدثن ويتذاكرن الشعر والشعراء وإذا هن من أفصح النساء وآدبهن فقالت إحداهن قاتل الله جميلا حيث يقول\n(وبين الصفا والمروتين ذكرتكم ... بمختلف ما بين ساع وموجف)\n(وعند طوافي قد ذكرتك ذكرة ... هي الموت بل كادت على الموت تضعف)\nقالت الأخرى بل قاتل الله كثير عزة حيث يقول\n(طلعن علينا بين مروة والصفا ... يمرن على البطحاء مور السحائب)\n(فكدن لعمر الله يحدثن فتنة ... لمختشع من خشية الله تائب)\nقالت الأخرى قاتل الله ابن الزانية نصيبا حيث يقول\n(ألام على ليلى ولو أستطيعها ... وحرمة ما بين البنية والستر)\n(لملت على ليلى بنفسي ميلة ... ولو كان في يوم التحالق والنحر)\nقام نصيب إليهن فسلم عليهن فرددن عليه السلام فقال لهن إني رأيتكن تتحادثن شيئا عندي منه علم فقلن ومن أنت فقال اسمعن أولا فقلن هات فأنشدهن قصيدته التي أولها\n(ويوم ذي سلم شاقتك نائحة ... ورقاء في فنن والريح تضطرب)\nقلن له نسألك بالله وبحق هذه البنية من أنت فقال أنا ابن المظلومة المقذوفة بغير جرم نصيب فقمن إليه فسلمن عليه ورحبن به واعتذرت إليه القائلة وقالت والله ما أردت سوءا وإنما حملني الاستحسان لقولك على ما سمعك فضحك وجلس إليهن فحادثهن إلى أن انصرفن","topic":"ذكر نصيب وأخباره","topicNo":4,"sp":15,"spl":"حديث نصيب عن نفسه أنه عشق أمة لبني مدلج وشعره فيها — نصيب ونسوة كن يتناشدن الشعر في المسجد"},
{"id":"b5-2","bab":"الجزء 1","sec":"أخبار ابن محرز ونسبه نسب ابن محرز — أخذه عن الفرس والروم","page":"ج1 ص362 – ج1 ص363","text":"هو مسلم بن محرز فيما روى ابن المكي ويكنى أبا الخطاب مولى بني عبد الدار بن قصي وقال ابن الكلبي اسمه سلم قال ويقال اسمه عبد الله وكان أبوه من سدنة الكعبة أصله من الفرس وكان أصفر أحنى طويلا\nوأخبرني الحرمي قال حدثنا الزبير قال حدثني أخي هارون عن عبد الملك ابن الماجشون قال اسم ابن محرز سلم وهو مولى بني مخزوم وذكر إسحاق أنه كان يسكن المدينة مرة ومكة مرة فإذا أتى المدينة أقام بها ثلاثة أشهر يتعلم الضرب من عزة الميلاء ثم يرجع إلى مكة فيقيم بها ثلاثة أشهر ثم شخص إلى فارس فتعلم ألحان الفرس وأخذ غناءهم ثم صار إلى الشام فتعلم ألحان الروم وأخذ غناءهم فأسقط من ذلك ما لا يستحسن من نغم الفريقين وأخذ محاسنها فمزج بعضها\nببعض وألف منها الأغاني التي صنعها في أشعار العرب فأتى بما لم يسمع مثله وكان يقال له صناج العرب","topic":"أخبار ابن محرز ونسبه","topicNo":5,"sp":0,"spl":"أخبار ابن محرز ونسبه نسب ابن محرز — أخذه عن الفرس والروم — أخبار في حسن غنائه"},
{"id":"b5-3","bab":"الجزء 1","sec":"ابن محرز أول من غنى الرمل","page":"ج1 ص363","text":"أخبرني عمي قال حدثني أبو أيوب المديني عن حماد بن إسحاق عن أبيه قال قال أبي أول من غنى الرمل ابن محرز وما غني قبله فقلت له ولا بالفارسية قال ولا بالفارسية وأول من غنى رملا بالفارسية سلمك في أيام الرشيد استحسن لحنا من ألحان ابن محرز فنقل لحنه إلى الفارسية وغنى فيه","topic":"أخبار ابن محرز ونسبه","topicNo":5,"sp":0,"spl":"أخبار ابن محرز ونسبه نسب ابن محرز — أخذه عن الفرس والروم — أخبار في حسن غنائه"},
{"id":"b5-4","bab":"الجزء 1","sec":"بعده عن الناس وخمول ذكره إلا غناءه","page":"ج1 ص364","text":"قال أبو أيوب وقال إسحاق كان ابن محرز قليل الملابسة للناس فأخمل ذلك ذكره فما يذكر منه إلا غناؤه وأخذت أكثر غنائه جارية كانت لصديق له من أهل مكة كانت تألفه فأخذه الناس عنها ومات بداء كان به وسقط إلى فارس فأخذ غناء الفرس وإلى الشام فأخذ غناء الروم فتخير من نغمهم ما تغنى به غناءه وكان يقدم بما يصيبه فيدفعه إلى صديقه ذاك فينفقه كيف شاء لا يسأله عن\nشيء منه حتى إذا كاد أن ينفد جهزه وأصلح من أمره وقال له إذا شئت فارحل فيرحل ثم يعود فلم يزل كذلك حتى مات قال وهو أول من غنى بزوج من الشعر وعمل ذلك بعده المغنون اقتداء به وكان يقول الأفراد لا تتم بها الألحان وذكر أنه أول ما أخذ الغناء أخذه عن ابن مسجح قال إسحاق وكانت العلة التي مات به الجذام فلم يعاشر الخلفاء ولا خالط الناس لأجل ذلك قال أبو أيوب قال إسحاق قدم ابن محرز يريد العراق فلما نزل القادسية لقيه حنين فقال له كم منتك نفسك من العراق قال ألف دينار قال فهذه خمسمائة دينار فخذها وانصرف واحلف ألا لا تعود","topic":"أخبار ابن محرز ونسبه","topicNo":5,"sp":0,"spl":"أخبار ابن محرز ونسبه نسب ابن محرز — أخذه عن الفرس والروم — أخبار في حسن غنائه"},
{"id":"b5-5","bab":"الجزء 1","sec":"أخبار في حسن غنائه","page":"ج1 ص365","text":"وقال إسحاق وقلت ليونس من أحسن الناس غناء قال ابن محرز قلت وكيف قلت ذاك قال إن شئت فسرت وإن شئت أجملت قلت أجمل قال كأنه خلق من كل قلب فهو يغني لكل إنسان بما يشتهي وهذه الحكاية بعينها قد حكيت في ابن سريج ولا أدري أيهما الحق قال إسحاق وأخبرني الفضل بن يحيى بن خالد أنه سأل بعض من يبصر الغناء من أحسن الناس غناء فقال أمن الرجال أم من النساء فقلت من الرجال فقال ابن محرز فقلت فمن النساء فقال ابن سريج قال وكان إسحاق يقول الفحول ابن سريج ثم ابن محرز ثم معبد ثم الغريض\nثم مالك أخبرني الحسين بن يحيى قال قال حماد قرأت على أبي حدثنا بعض أهل المدينة وأخبرني بهذا الخبر الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني أخي هارون عن عبد الملك بن الماجشون قال كان ابن محرز أحسن الناس غناء فمر بهند بنت كنانة بن عبد الرحمن بن نضلة بن صفوان بن أمية بن محرث الكناني حليف قريش فسألته أن يجلس لها ولصواحب لها ففعل وقال أغنيكن صوتا أمرني الحارث بن خالد بن العاص ابن هشام أن أغنيه عائشة بنت طلحة بن عبيد الله في شعر له قاله فيها وهو يومئذ أمير مكة قلن نعم فعناهن صوت\n(فوددت إذ شحطوا وشطت دارهم ... وعدتهم عنا عواد تشغل)\n(أنا نطاع وأن تنقل أرضنا ... أو أن أرضهم إلينا تنقل)\n(لترد من كثب إليك رسائلي ... بجوابها ويعود ذاك المرسل)\nروضه من الكامل الغناء في هذه الأبيات خفيف رمل مطلق في مجرى البنصر ذكر عمرو بن بانة أنه لابن محرز وذكر إسحاق أنه لابن سريج","topic":"أخبار ابن محرز ونسبه","topicNo":5,"sp":0,"spl":"أخبار ابن محرز ونسبه نسب ابن محرز — أخذه عن الفرس والروم — أخبار في حسن غنائه"},
{"id":"b5-6","bab":"الجزء 1","sec":"ابن محرز وحنين الحيري","page":"ج1 ص367","text":"وقال أبو أيوب المديني في خبره بلغني أن ابن محرز لما شخص يريد العراق لقيه حنين فقال له غنني صوتا من غنائك فغناه صوت\n(وحسن الزبرجد في نظمه ... على واضح الليت زان العقودا)\n(يفصل ياقوته دره ... وكالجمر أبصرت فيه الفريدا)\nروضه من المتقارب الشعر لعمر بن أبي ربيعة والغناء لابن محرز ثاني ثقيل بالسبابة في مجرى البنصر قال فقال له حنين حينئذ كم أملت من العراق قال ألف دينار فقال له هذه خمسمائة دينار فخذها وانصرف ولما شاع ما فعل لامه أصحابه عليه فقال والله لو دخل العراق لما كان لي معه فيه خبز آكله ولا طرحت وسقطت إلى آخر الدهر وهذا الصوت أعني\n(وحسن الزبرجد في نظمه ... )\nن صدور أغاني ابن محرز وأوائلها وما لا يتعلق بمذهبه فيه ولا يتشبه به أحد ومما يغنى فيه من قصيدة نصيب التي أولها\n(أهاج هواك المنزل المتقادم ... )\nصوت\n(لقد راعني للبين نوح حمامة ... على غصن بان جاوبتها حمائم)\n(هواتف أما من بكين فعهده ... قديم وأما شجوهن فدائم)\nلغناء لابن سريج من رواية يونس وعمرو وابن المكي وهو ثاني ثقيل بالبنصر وهو من جيد الألحان وحسن الأغاني وهو مما عارض ابن سريج فيه ابن محرز وانتصف منه","topic":"أخبار ابن محرز ونسبه","topicNo":5,"sp":1,"spl":"ابن محرز وحنين الحيري — ذكر الأصوات التي رواها جحظة عن أصحابه وحكى أنها من الثلاثة المختار","partialRef":{"sid":"b1-1","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b5-7","bab":"الجزء 1","sec":"ذكر الأصوات التي رواها جحظة عن أصحابه وحكى أنها من الثلاثة المختارة","page":"ج1 ص368","text":"صوت\n(إلى جيداء قد بعثوا رسولا ... ليحزنها فلا صحب الرسول)\n(كأن العام ليس بعام حج ... تغيرت المواسم والشكول)\nلشعر للعرجي والغناء لإبراهيم الموصلي ولحنه المختار ماخوري بالوسطى وهو من خفيف الثقيل الثاني على مذهب إسحاق وفيه لابن سريج ثاني ثقيل بالسبابة في مجرى البنصر وذكر عمرو بن بانة أن الماخوري لابن سريج","topic":"أخبار ابن محرز ونسبه","topicNo":5,"sp":1,"spl":"ابن محرز وحنين الحيري — ذكر الأصوات التي رواها جحظة عن أصحابه وحكى أنها من الثلاثة المختار"},
{"id":"b6-2","bab":"الجزء 1","sec":"أخبار العرجي ونسبه نسب العرجي من قبل أبويه — خبر أم أبان جدة أبيه عمر","page":"ج1 ص368 – ج1 ص369","text":"هو عبد الله بن عمر بن عمرو بن عثمان بن عفان بن أبي العاصي بن أمية بن عبد شمس وقد شرح هذا النسب في نسب أبي قطيفة وأم عفان وجميع بني أبي العاصي آمنة بنت عبد العزى بن حرثان بن عوف بن عبيد بن عويج بن عدي بن كعب وأم عثمان أروى بنت كريز بن ربيعة بن حبيب بن عبد شمس وأمها البيضاء أم حكيم بنت عبد المطلب بن هاشم بن عبد مناف وهي أخت عبد الله بن عبد المطلب أبي رسول الله لأمه وأبيه ولدا في بطن واحد وأم عمرو بن عثمان أم أبان بنت جندب الدوسية\nأخبرني الحرمي بن أبي العلاء والطوسي قالا حدثنا الزبير بن بكار قال حدثني علي بن صالح عن يعقوب بن محمد عن عبد العزيز بن عمر بن عبد العزيز قال حدثني محرز بن جعفر عن أبيه عن جده قال قدم جندب بن عمرو بن حممة الدوسي المدينة مهاجرا في خلافة عمر بن\nالخطاب ثم مضى إلى الشأم وخلف ابنته أم أبان عند عمر وقال له يا أمير المؤمنين إن وجدت لها كفئا فزوجه بها ولو بشراك نعله وإلا فأمسكها حتى تلحقها بدار قومها بالسراة فكانت عند عمر واستشهد أبوها فكانت تدعو عمر أباها ويدعوها ابنته قال فإن عمر على المنبر يوما يكلم الناس في بعض الأمر إذ خطر على قلبه ذكرها فقال من له في الجميلة الحسيبة بنت جندب بن عمرو بن حممة وليعلم امرؤ من هو فقام عثمان فقال أنا يا أمير المؤمنين فقال أنت أنا لعمر الله كم سقت إليها قال كذا وكذا قال قد زوجتكها فعجله فإنها معدة قال ونزل عن المنبر فجاء عثمان رضي الله عنه بمهرها فأخذه عمر في ردنه فدخل به عليها فقال يا بنية مدي حجرك ففتحت حجرها فألقى فيه المال ثم قال يا بنية قولي اللهم بارك لي فيه فقالت اللهم بارك لي فيه وما هذا يا أبتاه قال مهرك فنفحت به وقالت واسوأتاه فقال احتبسي منه لنفسك ووسعي منه لأهلك وقال لحفصة يا بنتاه أصلحي من شأنها وغيري بدنها واصبغي ثوبها ففعلت ثم أرسل بها مع نسوة إلى عثمان فقال عمر لما فارقته إنها أمانة في عنقي أخشى أن تضيع بيني وبين عثمان فلحقهن فضرب على عثمان بابه ثم قال خذ أهلك بارك الله لك فيهم فدخلت على عثمان فأقام عندها مقاما طويلا لا يخرج إلى حاجة فدخل عليه سعيد بن العاص فقال له يا أبا عبد الله لقد أقمت عند هذه الدوسية مقاما ما كنت تقيمه عند النساء فقال أما إنه ما بقيت خصلة كنت أحب أن تكون في امرأة إلا صادفتها فيها ما خلا خصلة واحدة\nقال وما هي قال إني رجل قد دخلت في السن وحاجتي في النساء الولد وأحسبها حديثة لا ولد فيها اليوم قال فتبسمت فلما خرج سعيد من عنده قال لها عثمان ما أضحكك قالت قد سمعت قولك في الولد وإني لمن نسوة ما دخلت امرأة منهن على سيد قط فرأت حمراء حتى تلد سيد من هو منه قال فما رأت حمراء حتى ولدت عمرو بن عثمان وأم عمر بن عمرو بن عثمان أم ولد وأم العرجي آمنة بنت عمر بن عثمان وقال إسحاق بنت سعيد بن عثمان وهي لأم ولد","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":0,"spl":"أخبار العرجي ونسبه نسب العرجي من قبل أبويه — خبر أم أبان جدة أبيه عمر — سبب تلقبه بالعرجي "},
{"id":"b6-3","bab":"الجزء 1","sec":"سبب تلقبه بالعرجي ونحوه نحو عمر بن أبي ربيعة في شعره","page":"ج1 ص371","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عمي\nأنه إنما لقب العرجي لأنه كان يسكن عرج الطائف وقيل بل سمي بذلك لماء كان له ومال عليه بالعرج وكان من شعراء قريش ومن شهر بالغزل منها ونحا نحو عمر بن أبي ربيعة في ذلك وتشبه به فأجاد وكان مشغوفا باللهو والصيد حريصا عليهما قليل المحاشاة لأحد فيهما ولم يكن له نباهة في أهله وكان أشقر أزرق جميل الوجه وجيداء التي شبب بها هي أم محمد بن هشام بن إسماعيل المخزومي وكان ينسب بها ليفضح ابنها لا لمحبة كانت بينهما فكان ذلك سبب حبس محمد إياه وضربه له حتى مات في السجن\nوأخبرني محمد بن مزيد إجازة عن حماد بن إسحاق فذكر أن حمادا حدثه عن إسحاق عن أبيه عن بعض شيوخه\nأن العرجي كان أزرق كوسجا ناتىء الحنجرة وكان صاحب غزل\nوفتوة وكان يسكن بمال له في الطائف يسمى العرج فقيل له العرجي ونسب إلى ماله وكان من الفرسان المعدودين مع مسلمة بن عبد الملك بأرض الروم وكان له معه بلاء حسن ونفقة كثيرة قال إسحاق قد ذكر عتبة بن إبراهيم اللهبي أن العرجي فيما بلغه باع أموالا عظاما كانت له وأطعم ثمنها في سبيل الله حتى نفد ذلك كله وكان قد اتخذ غلامين فإذا كان الليل نصب قدره وقام الغلامان يوقدان فإذا نام واحد قام الآخر فلا يزالان كذلك حتى يصبحا يقول لعل طارقا يطرق","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":0,"spl":"أخبار العرجي ونسبه نسب العرجي من قبل أبويه — خبر أم أبان جدة أبيه عمر — سبب تلقبه بالعرجي "},
{"id":"b6-4","bab":"الجزء 1","sec":"العرجي خليفة عمر بن أبي ربيعة","page":"ج1 ص372","text":"أخبرني حبيب بن نصر قال حدثنا أحمد بن أبي خيثمة قال حدثني مصعب وأخبرنا الحرمي عن الزبير عن عمه مصعب وعن محمد بن الضحاك بن عثمان عن أبيه قال دخل حديث بعضهم في بعض وأخبرني محمد بن مزيد عن حماد عن أبيه عن مصعب قال كانت حبشية من مولدات مكة ظريفة صارت إلى المدينة فلما أتاهم موت عمر بن أبي ربيعة اشتد جزعها وجعلت تبكي وتقول من لمكة وشعابها وأباطحها ونزهها ووصف نسائها وحسنهن وجمالهن ووصف ما فيها فقيل لها خفضي عليك فقد نشأ فتى من ولد عثمان رضي الله عنه يأخذ مأخذه ويسلك مسلكه فقالت أنشدوني من شعره فأنشدوها فمسحت عينها وضحكت وقالت الحمد لله الذي لم يضيع حرمه","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":1,"spl":"العرجي خليفة عمر بن أبي ربيعة"},
{"id":"b6-5","bab":"الجزء 1","sec":"العرجي وكلابة مولاة عبد الله بن القاسم العبلي","page":"ج1 ص373","text":"أخبرني الحرمي بن أبي العلاء قال حدثني الزبير بن بكار قال حدثني عمي مصعب وأخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه عن عورك اللهبي أن مولاة لثقيف يقال لها كلابة كانت عند عبد الله بن القاسم الأموي العبلي وكان يبلغها تشبيب العرجي بالنساء وذكره لهن في شعره وكانت كلابة تكثر أن تقول لشد ما اجترأ العرجي على نساء قريش حين يذكرهن في شعره ولعمري ما لقي أحدا فيه خير ولئن لقيته لأسودن وجهه فبلغه ذلك عنها قال إسحاق في خبره وكان العبلي نازلا على ماء لبني نصر بن معاوية يقال له الفتق على ثلاثة أميال من مكة على طريق من جاء من نجران أو تبالة إلى مكة والعرج أعلاها قليلا مما يلي الطائف فبلغ العرجي أنه خرج إلى مكة فأتى قصره فأطاف به فخرجت إليه كلابة وكان خلفها في أهله فصاحت به إليك ويلك وجعلت ترميه بالحجارة وتمنعه أن يدنو من القصر فاستسقاها ماء فأبت أن تسقيه وقالت لا يوجد والله أثرك عندي أبدا فيلصق بي منك شر فانصرف وقال ستعلمين وقال صوت\n(حور بعثن رسولا في ملاطفة ... ثقفا إ ذا غفل النساءة الوهم)\n(إلي أن إيتنا هدأ إذا غفلت ... أحراسنا وافتضحنا إن هم علموا)\n(فجئت أمشي على هول أجشمه ... تجشم المرء هولا في الهوى كرم)\n(إذا تخوفت من شيء أقول له ... قد جف فامض بشيء قدر القلم)\n(أمشي كما حركت ريح يمانية ... غصنا من البان رطبا طله الديم)\n(في حلة من طراز السوس مشربة ... تعفو بهدابها ما أثرت قدم)\n(خلت سبيلي كما خليت ذا عذر ... إذا رأته عتاق الخيل ينتحم)\n(وهن في مجلس خال وليس له ... عين عليهن أخشاها ولا ندم)\n(حتى جلست إزاء الباب مكتتما ... وطالب الحاج تحت الليل مكتتم)\n(أبدين لي أعينا نجلا كما نظرت ... أدم هجان أتاها مصعب قطم)\n(قالت كلابة من هذا فقلت لها ... أنا الذي أنت من أعدائه زعموا)\n(أنا امرؤ جد بي حب فأحرضني ... حتى بليت وحتى شفني السقم)\n(لا تكليني إلى قوم لو انهم ... من بغضنا أطعموا لحمي إذا طعموا)\n(وأنعمي نعمة تجزي بأحسنها ... فطالما مسني من أهلك النعم)\n(ستر المحبين في الدنيا لعلهم ... أن يحدثوا توبة فيها إذا أثموا)\n(هذي يميني رهن بالوفاء لكم ... فارضي بها ولأنف الكاشح الرغم)\n(قالت رضيت ولكن جئت في قمر ... هلا تلبثت حتى تدخل الظلم)\n(فبت أسقى بأكواس أعل بها ... من بارد طاب منها الطعم والنسم)\n(حتى بدا ساطع للفجر نحسبه ... سنى حريق بليل حين يضطرم)\n(كغرة الفرس المنسوب قد حسرت ... عنه الجلال تلالا وهو يلتجم)\n(ودعتهن ولا شيء يراجعني ... إلا البنان وإلا الأعين السجم)\n(إذا أردن كلامي عنده اعترضت ... من دونه عبرات فانثنى الكلم)\n(تكاد إذ رمن نهضا للقيام معي ... أعجازهن من الأنصاف تنقصم)\nقال فسمع ابن القاسم العبلي بالشعر يغني به وكان العرجي قد أعطاه جماعة من المغنين وسألهم أن يغنوا فيه فصنعوا في أبيات منه عدة ألحان وقال والله لا أجد لهذه الأمة شيئا أبلغ من إيقاعها تحت التهمة عند ابن القاسم ليقطع مأكلتها من ماله قال فلما سمع العبلي بالشعر يغنى به أخرج كلابة واتهمها ثم أرسل بها بعد زمان على بعير بين غزارتي بعر فأحلفها بمكة بين الركن والمقام أن العرجي كذب فيما قاله فحلفت سبعين يمينا فرضي عنها وردها فكان بعد ذلك إذا سمع قول العرجي\n(فطالما مسني من أهلك النعم ... )\nقال كذب والله ما مسه ذلك قط وقال إسحاق وقد قيل إن صاحب هذه القصيدة والقصة أبو حراب العبلي وأن كلابة كانت أمة لسعدة بنت عبد الله بن عمرو بن عثمان وكان العرجي قد خطبها وسميت به ثم خطبها يزيد بن عبد الملك أو الوليد بن يزيد فزوجته فقال العرجي هذا الشعر فيها غنى في قوله\n(أمشي كما حركت ريح يمانية ... )\nلي بن هشام هزجا مطلقا بالبنصر وفيه للمسدود هزج آخر طنبوري ذكر ذلك جحظة وفي\n(لا تكليني إلى قوم لو انهم ... )","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":2,"spl":"العرجي وكلابة مولاة عبد الله بن القاسم العبلي","partial":1},
{"id":"b6-6","bab":"الجزء 1","sec":"العرجي وكلابة مولاة عبد الله بن القاسم العبلي","page":"ج1 ص373","text":"رمل لابن سريج عن ابن المكي وإسحاق في السبابة في مجرى الوسطى وفي قالت كلابة والذي بعده لعبيد الله بن أبي غسان لحن من خفيف الرمل ولنبيه في أنا امرؤ جد بي وما بعده هزج بالوسطى ولدحمان في حور بعثن وما بعده هزج بالوسطى وروى عنه الهشامي فيه ثقيلا أول ولأبي عيسى بن المتوكل في وأنعمي نعمة وبيتين بعده ثقيل أول وأخبرني بخبر العرجي وكلابة هذه الحرمي بن أبي العلاء عن الزبير بن بكار عن عمه مصعب وأخبرني به وكيع عن أبي أيوب المديني عن مصعب وذكر نحوا مما ذكره إسحاق وزعما أن كلابة كانت قيمة لأبي حراب العبلي وهو محمد بن عبد الله بن محمد بن عبد الله بن الحارث بن أمية الأصغر بن عبد شمس","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":3,"spl":"العرجي وكلابة مولاة عبد الله بن القاسم العبلي — العرجي يواقع امرأة في عرج الطائف"},
{"id":"b6-7","bab":"الجزء 1","sec":"أيوب بن مسلمة وأشعب يتذكران شعرا للعرجي","page":"ج1 ص377","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال أخبرني مسلمة ابن إبراهيم بن هشام قال كنت عند أيوب بن مسلمة ومعنا أشعب فذكر قول العرجي\n(أين ما قلت مت قبلك أينا ... أين تصديق ما وعدت إلينا)\n(فلقد خفت منك أن تصرمي الحبل ... وأن تجمعي مع الصرم بينا)\n(ما تقولين في فتى هام إذ هام ... بمن لا ينال جهلا وحينا)\n(فاجعلي بيننا وبينك عذلا ... لا تحيفي ولا يحيف علينا)\n(واعلمي أن في القضاء شهودا ... أو يمينا فأحضري شاهدينا)\n(خلتي لو قدرت منك على ما ... قلت لي في الخلاء حين التقينا)\n(ما تحرجت من دمي علم الله ... ولو كنت قد شهدت حنينا)\nال فقال أيوب لأشعب ما تظن أنها وعدته قال أخبرك يقينا لا ظنا أنها وعدته أن تأتيه في شعب من شعاب العرج يوم الجمعة إذا نزل الرجال إلى الطائف للصلاة فعرض لها عارض شغل فقطعها عن موعده قال فمن كان الشاهدان قال كسير وعوير وكل غير خير فند أبو زيد مولى عائشة بنت سعد وزور الفرق مولى الأنصار قال فمن العدل الحكم قال حصين بن غرير الحميري قال فما حكم به قال أدت إليه حقه وسقطت المؤنة عنه قال يا أشعب لقد أحكمت صناعتك قال سل علامة عن علمه","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":3,"spl":"العرجي وكلابة مولاة عبد الله بن القاسم العبلي — العرجي يواقع امرأة في عرج الطائف"},
{"id":"b6-8","bab":"الجزء 1","sec":"شعره في عاتكة زوجة طريح بن إسماعيل الثقفي","page":"ج1 ص379","text":"أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه عن عورك اللهبي قال قال العرجي في امرأة من بني حبيب بطن من بني نصر بن معاوية يقال لها عاتكة وكانت زوجة طريح بن إسماعيل الثقفي\n(يا دار عاتكة التي بالأزهر ... أو فوقه بقفا الكثيب الأحمر)\n(لم ألق أهلك بعد عام لقيتهم ... يا ليت أن لقاءهم لم يقدر)\nصوت\n(بفناء بيتك وابن مشعب حاضر ... في سامر عطر وليل مقمر)\n(مستشعرين ملاحفا هروية ... بالزعفران صباغها والعصفر)\n(فتلازما عند الفراق صبابة ... أخذ الغريم بفضل ثوب المعسر)\nالأزهر على ثلاثة أميال من الطائف وابن مشعب الذي عناه مغن من أهل مكة كان في زمن ابن سريج والغناء في هذه الأبيات له رمل بالوسطى قال إسحاق كان ابن مشعب من أحسن الناس وجها وغناء ومات في تلك الأيام فأدخل الناس غناءه في غناء ابن سريج والغريض قال وهذا الصوت ينسبه من لا يعلم إلى ابن محرز يعني\n(بفناء بيتك وابن مشعب حاضر ... )\nال وهو الذي غنى\n(أقفر ممن يحله السند ... فالمنحنى فالعقيق فالجمد)\n(ويحي غدا إن غدا علي بما ... أحذر من فرقة الحبيب غد)\nالناس ينسبونه إلى ابن سريج","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":3,"spl":"العرجي وكلابة مولاة عبد الله بن القاسم العبلي — العرجي يواقع امرأة في عرج الطائف","partial":1},
{"id":"b6-9","bab":"الجزء 1","sec":"العرجي يواقع امرأة في عرج الطائف","page":"ج1 ص380","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير قال حدثنا محمد بن ثابت بن إبراهيم الأنصاري قال حدثني ابن مخارق قال واعد العرجي هوى له شعبا من شعاب عرج الطائف إذا نزل رجالها يوم\nالجمعة إلى مسجد الطائف فجاءت على أتان لها معها جارية لها وجاء العرجي على حمار معه غلام له فواقع المرأة وواقع الغلام الجارية ونزا الحمار على الأتان فقال العرجي هذا يوم قد غاب عذاله أخبرني عمي قال حدثنا الكراني قال حدثنا النضر بن عمرو عن ابن داحة قال كان العرجي يستقي على إبله في شملتين ثم يغتسل ويلبس حلتين بخمسمائة دينار ثم يقول\n(يوما لأصحابي ويوما للمال ... مدرعة يوما ويوما سربال)\nخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه عن بعض رجاله أن العرجي كان غازيا فأصابت الناس مجاعة فقال للتجار أعطوا الناس وعلي ما تعطون فلم يزل يعطيهم ويطعم الناس حتى أخصبوا فبلغ ذلك عشرين ألف دينار فألزمها العرجي نفسه وبلغ الخبر عمر بن عبد العزيز فقال بيت المال أحق بهذا فقضى التجار ذلك المال من بيت المال","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":3,"spl":"العرجي وكلابة مولاة عبد الله بن القاسم العبلي — العرجي يواقع امرأة في عرج الطائف"},
{"id":"b6-10","bab":"الجزء 1","sec":"العرجي وأم الأوقص","page":"ج1 ص381","text":"أخبرني الحرمي قال حدثنا الزبير عن عمه وأخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه عن الزبيري وغيره\nأن العرجي خرج إلى جنبات الطائف متنزها فمر ببطن النقيع فنظر إلى أم الأوقص وهو محمد بن عبد الرحمن المخزومي القاضي وكان يتعرض لها فإذا رآها رمت بنفسها وتسترت منه وهي امرأة من بني تميم فبصر بها في نسوة جالسة وهن يتحدثن فعرفها وأحب أن يتأملها من قرب فعدل عنها ولقي أعرابيا من بني نصر على بكر له ومعه وطبا لبن فدفع إليه دابته وثيابه وأخذ قعوده ولبنه ولبس ثيابه ثم أقبل على النسوة فصحن به يا أعرابي أمعك لبن قال نعم ومال إليهن وجلس يتأمل أم الأوقص وتواثب من معها إلى الوطبين وجعل العرجي يلحظها وينظر أحيانا إلى الأرض كأنه يطلب شيئا وهن يشربن من اللبن فقالت له امرأة منهن أي شيء تطلب يا أعرابي في الأرض أضاع منك شيء قال نعم قلبي فلما سمعت التميمية كلامه نظرت إليه وكان أزرق فعرفته فقالت العرجي بن عمر ورب الكعبة ووثبت وسترها نساؤها وقلن انصرف عنا لا حاجة بنا إلى لبنك فمضى منصرفا وقال في ذلك\n(أقول لصاحبي ومثل ما بي ... شكاه المرء ذو الوجد الأليم)\n(إلى الأخوين مثلهما إذا ما ... تأوبه مؤرقة الهموم)\n(لحيني والبلاء لقيت ظهرا ... بأعلى النقع أخت بني تميم)\n(فلما أن رأت عيناي منها ... أسيل الخد في خلق عميم)\n(وعيني جؤذر خرق وثغرا ... كلون الأقحوان وجيد ريم)\n(حنا أترابها دوني عليها ... حنو العائدات على السقيم)\nال إسحاق في خبره فقال رجل من بني جمح يقال له ابن عامر للأوقص وقضى عليه بقضية فتظلم منه والله لو كنت أنا عبد الله بن عمر العرجي لكنت قد أسرفت علي فضربه الأوقص سبعين سوطا","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":4,"spl":"العرجي وأم الأوقص — ابن أبي عتيق وشعر العرجي"},
{"id":"b6-11","bab":"الجزء 1","sec":"أبو السائب المخزومي وشعر العرجي","page":"ج1 ص383","text":"أخبرني حبيب بن نصر المهلبي قال حدثنا أحمد بن زهير قال حدثنا مصعب بن عبد الله عن أبيه قال أتاني أبو السائب المخزومي ليلة بعد ما رقد السامر فأشرفت عليه فقال سهرت وذكرت أخا لي أستمتع به فلم أجد سواك فلو مضينا إلى العقيق فتناشدنا وتحدثنا فمضينا فأنشدته في بعض ذلك بيتين للعرجي\n(باتا بأنعم ليلة حتى بدا ... صبح تلوح كالأغر الأشقر)\n(فتلازما عند الفراق صبابة ... أخذ الغريم بفضل ثوب المعسر)\nقال أعده علي فأعدته فقال أحسن والله امرأته طالق إن نطق بحرف غيره حتى يرجع إلى بيته قال فلقينا عبد الله بن حسن بن حسن فلما صرنا إليه وقف بنا وهو منصرف من ماله يريد المدينة فسلم ثم قال كيف أنت يا أبا السائب فقال\n(فتلازما عند الفراق صبابة ... أخذ الغريم بفضل ثوب المعسر)\nالتفت إلي فقال متى أنكرت صاحبك فقلت منذ الليلة فقال إنا لله وأي كهل أصيبت منه قريش ثم مضينا فلقينا محمد بن عمران التيمي قاضي المدينة يريد مالا له على بغلة له ومعه غلام على عنقه مخلاة فيها قيد البغلة فسلم ثم قال كيف أنت يا أبا السائب فقال\n(فتلازما عند الفراق صبابة ... أخذ الغريم بفضل ثوب المعسر)\nفالتفت إلي فقال متى أنكرت صاحبك قلت آنفا فلما أراد المضي قلت أفتدعه هكذا والله ما آمن أن يتهور في بعض آبار العقيق قال صدقت يا غلام قال قيد البغلة فأخذ القيد فوضعه في رجله وهو ينشد البيت ويشير بيده إليه يري أنه يفهم عنه قصته ثم نزل الشيخ وقال لغلامه يا غلام احمله على بغلتي وألحقه بأهله فلما كان بحيث علمت أنه قد فاته أخبرته بخبره فقال قبحك الله ماجنا فضحت شيخا من قريش وغررتني","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":4,"spl":"العرجي وأم الأوقص — ابن أبي عتيق وشعر العرجي"},
{"id":"b6-12","bab":"الجزء 1","sec":"ابن أبي عتيق وشعر العرجي","page":"ج1 ص384","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عروة بن عبد الله بن عروة بن الزبير عن عروة بن أذينة قال أنشد ابن جندب الهذلي ابن أبي عتيق قول العرجي\n(وما أنس م الأشياء لا انس قولها ... لخادمها قومي اسألي لي عن الوتر)\n(فقالت يقول الناس في ست عشرة ... فلا تعجلي منه فإنك في أجر)\n(فما ليلة عندي وإن قيل جمعة ... ولا ليلة الأضحى ولا ليلة الفطر)\n(بعادلة الاثنين عندي وبالحرى ... يكون سواء منهما ليلة القدر)\nقال ابن أبي عتيق أشهدكم أنها حرة من مالي إن أجاز ذلك أهلها هذه والله أفقه من ابن شهاب","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":4,"spl":"العرجي وأم الأوقص — ابن أبي عتيق وشعر العرجي"},
{"id":"b6-13","bab":"الجزء 1","sec":"شعر العرجي في زوجته أم عثمان","page":"ج1 ص384","text":"أخبرني حبيب بن نصر قال حدثنا عمر بن شبة قال حدثنا إسحاق بن إبراهيم الموصلي قال تزوج العرجي أم عثمان بنت بكير بن عمرو بن عثمان بن عفان وأمها سكينة بنت مصعب بن الزبير فقال فيها\n(إن عثمان والزبير أحلا ... دارها باليفاع إذ ولداها)\n(إنها بنت كل أبيض قرم ... نال في المجد من قصي ذراها)\n(سكن الناس بالظواهر منها ... وتبوا لنفسه بطحاها)\nال إسحاق ولما تزوج الرشيد زوجته العثمانية أعجب بها فكان كثيرا ما يتمثل بهذه الأبيات","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":5,"spl":"شعر العرجي في زوجته أم عثمان — حبس العرجي"},
{"id":"b6-14","bab":"الجزء 1","sec":"العرجي وأبو عدي العبلي","page":"ج1 ص385","text":"أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه قال\nحدثت أن أبا عدي العبلي خرج يريد واديا نحو الطائف يقال له جلدان فمر بعبد الله بن عمر العرجي وهو نازل هناك بواد يقال له العرج فأرسل إليه غلاما له فأعلمه بمكانه فأتاه الغلام فقال له هذا أبو عدي فأمر أن ينزله في مسجد الخيف فأنزله وأبطأ عليه في الخروج فقال للغلام ويحك ما يحبس مولاك قال عنده ابن وردان مولى معاوية وهما يأكلان القسب والجلجلان ثم بعث إليه بخبز ولبن وبعث لرواحله بحمض وقدم إلى رواحل ابن وردان القت والشعير فكتب إليه أبو عدي\n(أبا عمر لم تنزل الركب إذ أتوا ... منازلهم والركب يحفون بالركب)\n(رفعت لئام الناس فوق كرامهم ... وآثرتهم بالجلجلان وبالقسب)\n(فأما بعيرانا فبالحمض غذيا ... وأوثر عباد بن وردان بالقضب)\nكتب إليه العرجي\n(أتانا فلم نشعر به غير أنه ... له لحية طالت على حمق القلب)\n(كراية بيطار بأعلى حديدة ... إذا نصبت لم تكسب الحمد بالنصب)\n(أتانا على سغب يعرض بالقرى ... وهل فوق قرص من قرى صاحب السغب)\nال فارتحل أبو عدي مغضبا وقال مزحت معه فهجاني وأنشأ يقول في العرجي\n(سرت ناقتي حتى إذا ملت السرى ... وعارضها عرج الجبانة والخصب)\n(طواها الكرى بعد السرى بمعرس ... جديب وشيخ بئس مستعرض الركب)\n(وهمت بتعريس فحلت قيودها ... إلى رجل بالعرج ألأم من كلب)\n(تمطى قليلا ثم جاء بصربة ... وقرص شعير مثل كركرة السقب)\n(فقلت له أردد قراك مذمما ... فلست إليه بالفقير ولا صحبي)\n(جزى الله خيرا خيرنا عند بيته ... وأنحرنا للكوم في اليوم ذي السغب)\n(لقد علمت فهر بأنك شرها ... وآكل فهر للخبيث من الكسب)\n(وتلبس للجارات إتبا ومئزرا ... ومرطا فبئس الشيخ يرفل في الإتب)\n(يدخن بالعود اليلنجوج مرة ... وبالضرو والسوداء والمائع الرطب)\n(فإن قلت عثمان بن عفان والدي ... فقد كان عثمان بريئا من الوشب)\n(وقدما يجيء الحي بالنسل ميتا ... ويأتي كريم الناس بالوكل الثلب)\n(له لحية قد مزقت فكأنها ... مقمة حشاش محالفه العشب)\nلما بلغ ذلك العرجي أتى عمه علي بن عبد الله بن علي العبلي فشق قميصه بين يديه وشكاه إليه فبعث إلى أبي عدي فنهاه عنه وقال لئن عدت لا كلمتك أبدا فكف عنه","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":5,"spl":"شعر العرجي في زوجته أم عثمان — حبس العرجي"},
{"id":"b6-15","bab":"الجزء 1","sec":"كان العرجي من أفرس الناس وأرماهم","page":"ج1 ص388","text":"أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه عن سليمان بن عثمان بن يسار رجل من أهل مكة وكان هيبا أديبا قال كان للعرجي حائط يقال له العرج في وسط بلاد بني نصر بن معاوية فكانت إبلهم وغنمهم تدخل فيه فيعقر كل ما دخل منها فكانت تضر به ويضر بأهلها ويشكونه ويشكوهم وكان من أفرس الناس وأرماهم وأبراهم لسهم فكان ربما برى مائة سهم من الرمان ثم يقول والله لا أنقلب حتى أقتل بها مائة خلفة من إبل بني نصر فيفعل ذلك","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":5,"spl":"شعر العرجي في زوجته أم عثمان — حبس العرجي"},
{"id":"b6-16","bab":"الجزء 1","sec":"حبس العرجي","page":"ج1 ص388","text":"قال إسحاق فحدثني ابن غرير قال لما حبس العرجي وضرب وأقيم على البلس قال\n(معي ابن غرير واقفا في عباءة ... لعمري لقد قرت عيون بني نصر)\nقال فتى من بني نصر يجيبه وكان حاضرا لضربه وإقامته\n(أجل قد أقر الله فيك عيوننا ... فبئس الفتى والجار في سالف الدهر)\nوقال إسحاق في خبره قال رجل للعرجي جئتك أخطب إليك مودتك قال بل خذها زنا فإنها أحلى وألذ","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":5,"spl":"شعر العرجي في زوجته أم عثمان — حبس العرجي"},
{"id":"b6-17","bab":"الجزء 1","sec":"امرأة تمثلت بشعر العرجي وقد ليمت على رفثها في الحج","page":"ج1 ص389","text":"أخبرني محمد بن خلف وكيع قال حدثنا إسماعيل بن مجمع عن المدائني عن عبد الله بن سلم قال\nقال عبد الله بن عمر العمري خرجت حاجا فرأيت امرأة جميلة تتكلم بكلام أرفثت فيه فأدنيت ناقتي منها ثم قلت لها يا أمة الله ألست حاجة أما\nتخافين الله فسفرت عن وجه يبهر الشمس حسنا ثم قالت تأمل يا عم فإنني ممن عنى العرجي بقوله صوت\n(أماطت كساء الخز عن حر وجهها ... وأدنت على الخدين بردا مهلهلا)\n(من اللاء لم يحججن يبغين حسبة ... ولكن ليقتلن البريء المغفلا)\nال فقلت لها فإني أسأل الله ألا يعذب هذا الوجه بالنار قال وبلغ ذلك سعيد بن المسيب فقال أما والله لو كان من بعض بغضاء العراق لقال لها أعزبي قبحك الله ولكنه ظرف عباد أهل الحجاز وقد رويت هذه الحكاية عن أبي حازم الأعرج وهو سلمة بن دينار وقد روى أبو حازم عن أبي هريرة وسهل بن سعد وغيرهما وروى عنه مالك وابن أبي أيوب والحكاية عنه في هذا أصح منها عن عبد الله العمري حدثنا بهذا وكيع والغناء في هذه الأبيات لعرار المكي ثاني ثقيل وفيه خفيف ثقيل لمعبد وفيها لعبد الله بن العباس الربيعي ثقيل أول ويقال إن خفيف الثقيل لابن سريج ويقال للغريض","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":6,"spl":"امرأة تمثلت بشعر العرجي وقد ليمت على رفثها في الحج — هجاء العرجي محمد بن هشام المخزومي وتش"},
{"id":"b6-18","bab":"الجزء 1","sec":"غناء عبد الله بن العباس الربيعي في شعر العرجي","page":"ج1 ص390","text":"أخبرني الحسن بن علي قال حدثنا عبد الله بن أبي سعد قال حدثني أبو توبة قال\nقال عبد الله بن العباس دعاني المتوكل فلما جلست مجلس المنادمة قال لي يا عبد الله تغن فغنيته في شعر مدحته به فقال أين هذا من غنائك في\n(أماطت كساء الخز عن حر وجهها ... )\nمن صنعتك في\n(أقفر ممن يحله سرف ... )\nقلت يا أمير المؤمنين إن صنعتي حينئذ كانت وأنا شاب عاشق فإن استطعت رد شبابي وعشقي صنعت مثل تلك الصنعة فقال هيهات وقد لعمري صدقت ووصلني والأبيات التي فيها الغناء المذكور من شعر العرجي يقوله في جيداء أم محمد بن هشام بن إسماعيل المخزومي وكان يهجوه ويشبب بأمه وبامرأته وكان محمد تياها شديد الكبر جبارا فلم يزل يتطلب عليه العلل حتى حبسه وقيده بعد أن ضربه بالسوط وأقامه على البلس للناس واختلف الرواة في السبب الذي اعتل به عليه وقد ذكرت ذلك في رواياتهم","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":6,"spl":"امرأة تمثلت بشعر العرجي وقد ليمت على رفثها في الحج — هجاء العرجي محمد بن هشام المخزومي وتش","partialRef":{"sid":"b6-17","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b6-19","bab":"الجزء 1","sec":"هجاء العرجي محمد بن هشام المخزومي وتشبيبه بأمه","page":"ج1 ص391","text":"أخبرني بخبره أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة وأخبرنا أحمد بن محمد بن إسحاق قال أخبرنا الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عمي مصعب ومحمد بن الضحاك الحزامي عن الضحاك بن عثمان وذكره حماد بن إسحاق عن أبيه عن أيوب بن\nعباية ونسخته أيضا من رواية محمد بن حبيب قالوا كان محمد بن هشام خال هشام بن عبد الملك فلما ولي الخلافة ولاه مكة وكتب إليه أن يحج بالناس فهجاه العرجي بأشعار كثيرة منها قوله فيه\n(كأن العام ليس بعام حج ... تغيرت المواسم والشكول)\n(إلى جيداء قد بعثوا رسولا ... ليخبرها فلا صحب الرسول)\nيروى ليحزنها وهكذا يغنى ومنها قوله\n(ألا قل لمن أمسى بمكة قاطنا ... ومن جاء من عمق ونقب المشلل)\n(دعوا الحج لا تستهلكوا نفقاتكم ... فما حج هذا العام بالمتقبل)\n(وكيف يزكى حج من لم يكن له ... إمام لدى تجميره غير دلدل)\n(يظل يرائي بالصيام نهاره ... ويلبس في الظلماء سمطي قرنفل)\nلم يزل محمد يطلب عليه العلل حتى وجدها فحبسه قال الزبير في خبره عن عمه ومحمد بن الضحاك وقال إسحاق في خبره عن\nأيوب بن عباية كان العرجي يشبب بأم محمد بن هشام وهي من بني الحارث بن كعب ويقال لها جيداء صوت\n(عوجي علينا ربة الهودج ... إنك إن لا تفعلي تحرجي)\n(إني أتيحت لي يمانية ... إحدى بني الحارث من مذحج)\n(نلبث حولا كاملا كله ... ما نلتقي إلا على منهج)\n(في الحج إن حجت وماذا منى ... وأهله إن هي لم تحجج)\n(أيسر ما نال محب لدى ... بين حبيب قوله عرج)\n(نقض إليكم حاجة أو نقل ... هل لي مما بي من مخرج)","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":6,"spl":"امرأة تمثلت بشعر العرجي وقد ليمت على رفثها في الحج — هجاء العرجي محمد بن هشام المخزومي وتش"},
{"id":"b6-20","bab":"الجزء 1","sec":"تعليق عطاء بن أبي رباح على هذا الشعر","page":"ج1 ص393","text":"قال إسحاق في خبره فحدثني حمزة بن عتبة اللهبي قال أنشد عطاء بن أبي رباح قول العرجي\n(في الحج إن حجت وماذا منى ... وأهله إن هي لم تحجج)\nقال الخير والله كله بمنى وأهله حجت أو لم تحج قال ولقي ابن سريج\nعطاء وهو راكب بمنى على بغلته فقال له سألتك بالله إلا وقفت لي حتى أسمعك شيئا قال ويحك دعني فإني عجل قال امرأته طالق لئن لم تقف مختارا للوقوف لأمسكن بلجام بغلتك ثم لا أفارقها ولو قطعت يدي حتى أغنيك وأرفع صوتي لا أسره قال هات وعجل فغناه\n(في الحج إن حجت وماذا منى ... وأهله إن هي لم تحجج)\nقال الخير كله والله بمنى لا سيما وقد غيبها الله عن مشاعره خل سبيل البغلة أخبرنا محمد بن خلف وكيع قال حدثني عبد الله بن أبي سعد قال حدثنا إبراهيم بن المنذر قال حدثني حمزة بن عتبة اللهبي عن عبد الوهاب بن مجاهد أو غيره قال كنت مع عطاء بن أبي رباح فجاءه رجل فأنشده قول العرجي\n(إني أتيحت لي يمانية ... إحدى بني الحارث من مذحج)\n(نلبث حولا كاملا كله ... لا نلتقي إلا على منهج)\n(في الحج إن حجت وماذا منى ... وأهله إن هي لم تحجج)\nقال عطاء خير كثير بمنى إذ غيبها الله عن مشاعره","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":7,"spl":"تعليق عطاء بن أبي رباح على هذا الشعر — حقد محمد بن هشام على العرجي وحبسه حتى مات"},
{"id":"b6-21","bab":"الجزء 1","sec":"تشبيبه بزوجة محمد بن هشام","page":"ج1 ص394","text":"قال وقال في زوجته جبرة المخزومية يعني زوجة محمد بن هشام صوت\n(عوجي علي فسلمي جبر ... فيم الصدود وأنتم سفر)\n(ما نلتقي إلا ثلاث منى ... حتى يفرق بيننا النفر)\n(الحول بعد الحول يتبعه ... ما الدهر إلا الحول والشهر)\nال حماد بن إسحاق في خبره حدثني ابن أبي الحويرث الثقفي عن ابن عم لعمارة بن حمزة قال حدثنا سليمان الخشاب عن داود المكي قال كنا في حلقة ابن جريج وهو يحدثنا وعنده جماعة فيهم عبد الله بن المبارك وعدة من العراقيين إذ مر به ابن تيزن المغني وقد ائتزر بمئزر على صدره وهي إزرة الشطار عندنا فدعاه ابن جريج فقال له أحب أن تسمعني قال إني مستعجل فألح عليه فقال امرأته طالق إن غناك أكثر من ثلاثة أصوات فقال له ويحك ما أعجلك إلى اليمين غنني الصوت الذي غناه ابن سريج في اليوم الثاني من أيام منى على جمرة العقبة فقطع طريق الذاهب والجائي حتى تكسرت المحامل فغناه\n(عوجي علي فسلمي جبر ... )\nقال له ابن جريج أحسنت والله ثلاث مرات ويحك أعده قال من الثلاثة فإني قد حلفت قال أعده فأعاده فقال أحسنت فأعده من الثلاثة فأعاده وقام ومضى وقال لولا مكان هؤلاء الثقلاء عندك لأطلت معك حتى تقضي وطرك فالتفت ابن جريج إلى أصحابه فقال لعلكم أنكرتم ما فعلت فقالوا\nإنا لننكره عندنا بالعراق ونكرهه قال فما تقولون في الرجز يعني الحداء قالوا لا بأس به عندنا قال فما الفرق بينه وبين الغناء","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":7,"spl":"تعليق عطاء بن أبي رباح على هذا الشعر — حقد محمد بن هشام على العرجي وحبسه حتى مات","partial":1},
{"id":"b6-22","bab":"الجزء 1","sec":"حقد محمد بن هشام على العرجي وحبسه حتى مات","page":"ج1 ص395","text":"قال إسحاق في خبره بلغني أن محمد بن هشام كان يقول لأمه جيداء بنت عفيف أنت غضضت مني بأنك أمي وأهلكتني وقتلتني فتقول له ويحك وكيف ذاك قال لو كانت أمي من قريش ما ولي الخلافة غيري قالوا فلم يزل محمد بن هشام مضطغنا على العرجي من هذه الأشعار التي يقولها فيه ومتطلبا سبيلا عليه حتى وجده فيه فأخذه وقيده وضربه وأقامه للناس ثم حبسه وأقسم لا يخرج من الحبس ما دام لي سلطان فمكث في حبسه نحوا من تسع سنين حتى مات فيه","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":7,"spl":"تعليق عطاء بن أبي رباح على هذا الشعر — حقد محمد بن هشام على العرجي وحبسه حتى مات"},
{"id":"b6-23","bab":"الجزء 1","sec":"روايات أخرى في سبب الخصومة بين محمد بن هشام والعرجي","page":"ج1 ص396","text":"وذكر إسحاق في خبره عن أيوب بن عباية ووافقه عمر بن شبة ومحمد بن حبيب أن السبب في ذلك أن العرجي لاحى مولى كان لأبيه فأمضه العرجي فأجابه المولى بمثل ما قاله له فأمهله حتى إذا كان الليل أتاه مع جماعة من مواليه وعبيده فهجم عليه في منزله وأخذه وأوثقه كتافا ثم أمر عبيده أن ينكحوا امرأته بين يديه ففعلوا ثم قتله وأحرقه بالنار فاستعدت امرأته على العرجي محمد بن هشام فحبسه\nوذكر الزبير في خبره عن الضحاك بن عثمان أن العرجي كان وكل بحرمه مولى له يقوم بأمورهن فبلغه أنه يخالف إليهن فلم يزل يرصده حتى\nوجده يحدث بعضهن فقتله وأحرقه بالنار فاستعدت عليه امرأة المولى محمد بن هشام المخزومي وكان واليا على مكة في خلافة هشام وكان العرجي قد هجاه قبل ذلك هجاء كثيرا لما ولاه هشام الحج فأحفظه فلما وجد عليه سبيلا ضربه وأقامه على البلس للناس وسجنه حتى مات في سجنه وذكر الزبير أيضا في خبره عن عمه وغيره أن أشعب كان حاضرا للعرجي وهو يشتم مولاه هذا وأنه طال شتمه إياه فلما أكثر رد المولى عليه فاختلط من ذلك فقال لأشعب اشهد على ما سمعت قال أشعب وعلام أشهد قد شتمته ألفا وشتمك واحدة والله لو أن أمك أم الكتاب وأمه حمالة الحطب ما زاد على هذا","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":8,"spl":"روايات أخرى في سبب الخصومة بين محمد بن هشام والعرجي — شعر للعرجي قاله في تعذيب محمد بن هشا"},
{"id":"b6-24","bab":"الجزء 1","sec":"شعر للعرجي قاله في تعذيب محمد بن هشام له","page":"ج1 ص397","text":"قال الزبير وحدثني حمزة بن عتبة اللهبي قال لما أخذ محمد بن هشام المخزومي العرجي أخذه وأخذ معه الحصين بن غرير الحميري فجلدهما وصب على رؤوسهما الزيت وأقامهما في الشمس على البلس في الحناطين بمكة فجعل العرجي ينشد\n(سينصرني الخليفة بعد ربي ... ويغضب حين يخبر عن مساقي)\n(علي عباءة بلقاء ليست ... مع البلوى تغيب نصف ساقي)\n(وتغضب لي بأجمعها قصي ... قطين البيت والدمث الرقاق)\nثم يصيح يا غرير أجياد يا غرير أجياد فيقول له الحميري المجلود معه ألا\nتدعنا ألا ترى ما نحن فيه من البلاء يعني بقوله يا غرير الحصين بن غرير الحميري المجلود معه وكان صديقا للعرجي وخليطا وذكر إسحاق تمام هذه الأبيات وأولها\n(وكم من كاعب حوراء بكر ... ألوف الستر واضحة التراقي)\n(بكت جزعا وقد سمرت كبول ... وجامعة يشد بها خناقي)\n(على دهماء مشرفة سموق ... ثناها القمح مزلقة التراقي)\n(علي عباءة بلقاء ليست ... مع البلوى تغيب نصف ساقي)\n(كأن على الخدود وهن شعث ... سجال الماء يبعث في السواقي)\n(فقلت تجلدا وحلفت صبرا ... أبالي اليوم ما دفعت مآقي)\n(سينصرني الخليفة بعد ربي ... ويغضب حين يخبر عن مساقي)\n(وتغضب لي بأجمعها قصي ... قطين البيت والدمث الرقاق)\n(بمجتمع السيول إذا تنحى ... لئام الناس في الشعب العماق)\nال فكان إذا أنشد هذا البيت التفت إلى ابن غرير فصاح به يا غرير أجياد يا غرير أجياد يعني بني مخزوم وكانت منازلهم في أجياد فعيرهم بأنهم ليسوا من أهل الأبطح وقال الزبير في خبره ووافقه إسحاق فذكر أن رجلا مر بالعرجي وهو واقف على البلس ومعه ابن غرير وقد جلدا وحلقا وصب الزيت على رؤوسهما وألبسا\nعباءتين واجتمع الناس ينظرون إليهما قال وكان الرجل صديقا للعرجي وكان فأفاء فوقف عليه فأراد أن يتوجع لما ناله ويدعو له فلجلج لما كان في لسانه كما يفعل الفأفاء فقال له ابن غرير عني لا خرجت من فيك أبدا فقال له الرجل فمكانك إذا لا برحت منه أبدا قال ومر به صبيان يلقطون النوى فوقفوا ينظرون إليه فالتفت إلى ابن غرير وقال له ما أعرف في الدنيا سخلين أشأم مني ومنك إن هؤلاء الصبيان لأهلهم عليهم في كل يوم على كل واحد منهم مد نوى فقد تركوا لقطهم للنوى وقد وقفوا ينظرون إلي وإليك وينصرفون بغير شيء فيضربون فيكون شؤمنا قد لحقهم قال وقال العرجي في حبسه صوت\n(أضاعوني وأي فتى أضاعوا ... ليوم كريهة وسداد ثغر)\n(وصبر عند معترك المنايا ... وقد شرعت أسنتها بنحري)\n(أجرر في الجوامع كل يوم ... فيا لله مظلمتي وصبري)\n(كأني لم أكن فيهم وسيطا ... ولم تك نسبتي في آل عمرو)","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":8,"spl":"روايات أخرى في سبب الخصومة بين محمد بن هشام والعرجي — شعر للعرجي قاله في تعذيب محمد بن هشا"},
{"id":"b6-25","bab":"الجزء 1","sec":"أبو حنيفة وجار له كان يغني بشعر العرجي","page":"ج1 ص399","text":"أخبرني محمد بن زكريا الصحاف قال حدثنا قعنب بن المحرز الباهلي\nعن الأصمعي قال كان لأبي حنيفة جار بالكوفة يغني فكان إذا انصرف وقد سكر يغني في غرفته ويسمع أبو حنيفة غناءه فيعجبه وكان كثيرا ما يغني\n(أضاعوني وأي فتى أضاعوا ... ليوم كريهة وسداد ثغر)\nلقيه العسس ليلة فأخذوه وحبس ففقد أبو حنيفة صوته تلك الليلة فسأل عنه من عد فأخبر فدعا بسواده وطويلته فلبسهما وركب إلى عيسى بن موسى فقال له إن لي جارا أخذه عسسك البارحة فحبس وما علمت منه إلا خيرا فقال عيسى سلموا إلى أبي حنيفة كل ما أخذه العسس البارحة فأطلقوا جميعا فلما خرج الفتى دعا به أبو حنيفة وقال له سرا ألست كنت تغني يا فتى كل ليلة\n(أضاعوني وأي فتى أضاعوا ... )\nهل أضعناك قال لا والله أيها القاضي ولكن أحسنت وتكرمت أحسن الله جزاءك قال فعد إلى ما كنت تغنيه فإني كنت آنس به ولم أر به بأسا قال أفعل","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":9,"spl":"أبو حنيفة وجار له كان يغني بشعر العرجي — اقتصاص الوليد بن يزيد من محمد وإبراهيم ابني هشام","partialRef":{"sid":"b6-24","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b6-26","bab":"الجزء 1","sec":"عبد الله بن علي كان كثير التمثل في حبسه بقول العرجي أضاعوني","page":"ج1 ص400","text":"وقال إسحاق في خبره لما حبس المنصور عبد الله بن علي كان يكثر التمثل بقول العرجي\n(أضاعوني وأي فتى أضاعوا ... ليوم كريهة وسداد ثغر)\nبلغ ذلك المنصور فقال هو أضاع نفسه بسوء فعله فكانت أنفسنا عندنا آثر من نفسه","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":9,"spl":"أبو حنيفة وجار له كان يغني بشعر العرجي — اقتصاص الوليد بن يزيد من محمد وإبراهيم ابني هشام"},
{"id":"b6-27","bab":"الجزء 1","sec":"الأصمعي وكناس بالبصرة كان يتمثل بهذا البيت","page":"ج1 ص401","text":"قال إسحاق وقال الأصمعي مررت بكناس بالبصرة يكنس كنيفا ويغني\n(أضاعوني وأي فتى أضاعوا ... ليوم كريهة وسداد ثغر)\nقلت له أما سداد الكنيف فأنت مليء به وأما الثغر فلا علم لي بك كيف أنت فيه وكنت حديث السن فأردت العبث به فأعرض عني مليا ثم أقبل علي فأنشد متمثلا\n(وأكرم نفسي إنني إن أهنتها ... وحقك لم تكرم على أحد بعدي)\nال فقلت له والله ما يكون من الهوان شيء أكثر مما بذلتها له فبأي شيء أكرمتها فقال بلى والله إن من الهوان لشرا مما أنا فيه فقلت وما هو فقال الحاجة إليك وإلى أمثالك من الناس فانصرفت عنه أخزى الناس قال\nمحمد بن مزيد فحدثني حماد قال قال لي أبي اختصر الأصمعي فيما أرى الجواب وستر أقبحه على نفسه وإلا فكناس كنيف قائم يكنسه ويعبث به هذا العبث فيرضى بهذا الجواب الذي لا يجيب بمثله الأحنف بن قيس لو كانت المخاطبة له","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":9,"spl":"أبو حنيفة وجار له كان يغني بشعر العرجي — اقتصاص الوليد بن يزيد من محمد وإبراهيم ابني هشام"},
{"id":"b6-28","bab":"الجزء 1","sec":"اقتصاص الوليد بن يزيد من محمد وإبراهيم ابني هشام","page":"ج1 ص402","text":"وقال إسحاق في خبره كان الوليد بن يزيد مضطغنا على محمد بن هشام لأشياء كانت تبلغ عنه في حياة هشام فلما ولي الخلافة قبض عليه وعلى أخيه إبراهيم بن هشام وأشخصا إليه إلى الشام ثم دعا بالسياط فقال له محمد أسألك بالقرابة قال وأي قرابة بيني وبينك وهل أنت إلا من أشجع قال فأسألك بصهر عبد الملك قال لم تحفظه فقال له يا أمير المؤمنين قد نهى رسول الله أن يضرب قرشي بالسياط إلا في حد قال ففي حد أضربك وقود أنت أول من سن ذلك على العرجي وهو ابن عمي وابن أمير المؤمنين عثمان فما رعيت حق جده ولا نسبه بهشام ولا ذكرت حينئذ هذا الخبر وأنا ولي ثأره اضرب يا غلام فضربهما ضربا مبرحا وأثقلا بالحديد ووجه بهما إلى يوسف بن عمر بالكوفة وأمره باستصفائهما وتعذيبهما حتى يتلفا وكتب إليه احبسهما مع ابن النصرانية يعني خالدا\nالقسري ونفسك نفسك إن عاش أحد منهم فعذبهم عذابا شديدا وأخذ منهم مالا عظيما حتى لم يبق فيهم موضع للضرب فكان محمد بن هشام مطروحا فإذا أرادوا أن يقيموه أخذوا بلحيته فجذبوه بها ولما اشتدت عليهما الحال تحامل إبراهيم لينظر في وجه محمد فوقع عليه فماتا جميعا ومات خالد القسري معهما في يوم واحد فقال الوليد بن يزيد لما حملهما إلى يوسف بن عمر\n(قد راح نحو العراق مشخلبه ... قصاره السجن بعده الخشبه)\n(يركبها صاغرا بلا قتب ... ولا خطام وحوله جلبه)\n(فقل لدعجاء إن مررت بها ... لن يعجز الله هارب طلبه)\n(قد جعل الله بعد غلبتكم ... لنا عليكم يا دلدل الغلبه)\n(لست إلى هاشم ولا أسد ... ولا إلى نوفل ولا الحجبه)\n(لكنما أشجع أبوك سل الكلبي ... لا ما يزوق الكذبة)","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":9,"spl":"أبو حنيفة وجار له كان يغني بشعر العرجي — اقتصاص الوليد بن يزيد من محمد وإبراهيم ابني هشام"},
{"id":"b6-29","bab":"الجزء 1","sec":"الرشيد وإسحاق حين غناه قول العرجي أضاعوني","page":"ج1 ص403","text":"قال إسحاق في خبره غنيت الرشيد يوما في عرض الغناء\n(أضاعوني وأي فتى أضاعوا ... ليوم كريهة وسداد ثغر)\nقال لي ما كان سبب هذا الشعر حتى قاله العرجي فأخبرته بخبره من أوله إلى أن مات فرأيته يتغيظ كلما مر منه شيء فأتبعته بحديث مقتل ابني هشام فجعل وجهه يسفر وغيظه يسكن فلما انقضى الحديث قال لي يا إسحاق والله لولا ما حدثتني به من فعل الوليد لما تركت أحدا من أماثل بني مخزوم إلا قتلته بالعرجي والصوت الآخر من رواية جحظة عن أصحابه صوت\n(إذا ما طواك الدهر يا أم مالك ... فشأن المنايا القاضيات وشانيا)\n(تمر الليالي والشهور وتنقضي ... وحبك ما يزداد إلا تماديا)\n(خليلي إن دارت على أم مالك ... صروف الليالي فابغيا لي ناعيا)\n(ولا تتركاني لا لخير معجل ... ولا لبقاء تنظران بقائيا)\nلشعر للمجنون ومن الناس من يروي البيت الأول منها لقيس بن الحدادية وهو جاهلي والغناء لابن محرز ثاني ثقيل بالوسطى وذكر حبش وابن المكي أن فيه لإسحاق لحنا آخر من الثقيل الثاني بالخنصر والبنصر إلى هنا انتهى الجزء الأول من كتاب الأغاني ويليه الجزء الثاني منه وأوله أخبار مجنون بني عامر ونسبه","topic":"أخبار العرجي ونسبه","topicNo":6,"sp":10,"spl":"الرشيد وإسحاق حين غناه قول العرجي أضاعوني"},
{"id":"b7-1","bab":"الجزء 2","sec":"بسم الله الرحمن الرحيم أخبار مجنون بني عامر ونسبه","page":"ج2 ص3","text":"هو على ما يقول من صحح نسبه وحديثه قيس وقيل مهدي والصحيح أنه قيس بن الملوح بن مزاحم بن عدس بن ربيعة بن جعدة بن كعب بن ربيعة بن عامر بن صعصعة ومن الدليل على أن اسمه قيس قول ليلى صاحبته فيه\n(ألا ليت شعري والخطوب كثيرة ... متى رحل قيس مستقل فراجع)\nأخبرني الحسن بن علي قال حدثنا أحمد بن زهير قال سمعت من لا أحصي يقول اسم المجنون قيس بن الملوح وأخبرني هاشم بن محمد الخزاعي قال حدثنا الرياشي وأخبرني الجوهري عن عمر بن شبة أنهما سمعا الآصمعي يقول وقد سئل عنه لم يكن مجنونا ولكن كانت به لوثة كلوثة أبي حية النميري","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":0,"spl":"بسم الله الرحمن الرحيم أخبار مجنون بني عامر ونسبه — اختلاف الرواة في وجود قيس وجنونه"},
{"id":"b7-2","bab":"الجزء 2","sec":"اختلاف الرواة في وجود قيس وجنونه","page":"ج2 ص4","text":"وأخبرني حبيب ابن نصر المهلبي وأحمد بن عبد عزيز الجوهري عن ابن شبة عن الحزامي قال حدثني أيوب بن عباية قال سألت بني عامر بطنا بطنا عن مجنون بني عامر فما وجدت أحدا يعرفه وأخبرني عمي قال حدثنا أحمد بن الحارث عن المدائني عن ابن دأب قال قلت لرجل من بني عامر أتعرف المجنون وتروي من شعره شيئا قال أوقد فرغنا من شعر العقلاء حتى نروي أشعار المجانين إنهم لكثير فقلت ليس هؤلاء أعني إنما أعني مجنون بني عامر الشاعر الذي قتله العشق فقال هيهات بنو عامر أغلظ أكبادا من ذاك إنما يكون هذا في هذه اليمانية الضعاف قلوبها السخيفة عقولها الصعلة رؤوسها فأما نزار فلا أخبرني هاشم بن محمد قال حدثنا الرياشي قال سمعت الآصمعي يقول رجلان ما عرفا في الدنيا قط إلا بالاسم مجنون بني عامر وابن القرية وإنما وضعهما الرواة وأخبرنا أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثني عبد الله بن\nأبي سعد عن الحزامي قال ولم أسمعه من الحزامي فكتبته عن ابن أبي سعد قال أحمد وحدثنا به ابن أبي سعد عن الحزامي قال حدثنا عبد الجبار بن سعيد بن سليمان بن نوفل بن مساحق عن أبيه عن جده قال سعيت على بني عامر فرأيت المجنون وأتيت به وأنشدني أخبرني علي بن سليمان الأخفش قال حدثنا أبو سعيد السكري قال حدثنا إسماعيل بن مجمع عن المدائني قال المجنون المشهور بالشعر عند الناس صاحب ليلى قيس بن معاذ من بني عامر ثم من بني عقيل أحد بني نمير بن عامر ابن عقيل قال ومنهم رجل آخر يقال له مهدي بن الملوح من بنى جعدة بن كعب بن ربيعة بن عامر بن صعصعة وأخبرني عمي عن الكراني قال حدثنا ابن أبي سعد عن علي بن الصباح عن ابن الكلبي قال حدثت أن حديث المجنون وضعه فتى من بني أمية كان يهوى ابنة عم له وكان يكره أن يظهر ما بينه وبينها فوضع حديث المجنون وقال الأشعار التي يرويها الناس للمجنون ونسبها إليه أخبرني الحسين بن يحيى وأبو الحسن الأسدي قال حدثنا حماد بن إسحاق عن أبيه قال اسم المجنون قيس بن معاذ أحد بني جعدة بن كعب بن ربيعة بن عامر بن صعصعة","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":0,"spl":"بسم الله الرحمن الرحيم أخبار مجنون بني عامر ونسبه — اختلاف الرواة في وجود قيس وجنونه"},
{"id":"b7-3","bab":"الجزء 2","sec":"اختلاف الآراء حول اسم المجنون","page":"ج2 ص6","text":"وأخبرني أبو سعد الحسن بن علي بن زكريا العدوي قال حدثنا حماد بن طالوت بن عباد أنه سأل الآصمعي عنه فقال لم يكن مجنونا بل كانت به لوثة أحدثها العشق فيه كان يهوى امرأة من قومه يقال لها ليلى واسمه قيس بن معاذ وذكر عمرو بن أبي عمرو الشيباني عن أبيه أن اسمه قيس بن معاذ وذكر شعيب بن السكن عن يونس النحوي أن اسمه قيس بن الملوح قال أبو عمرو الشيباني وحدثني رجل من أهل اليمن أنه رآه ولقيه وسأله عن اسمه ونسبه فذكر أنه قيس بن الملوح وذكر هشام بن محمد الكلبي أنه قيس بن الملوح وحدث أن أباه مات قبل اختلاطه فعقر على قبره ناقته وقال في ذلك\n(عقرت على قبر الملوح ناقتي ... بذي السرح لما أن جفاه الأقارب)\n(وقلت لها كوني عقيرا فإنني ... غدا راجل أمشي وبالأمس راكب)\n(فلا يبعدنك الله يابن مزاحم ... فكل بكأس الموت لاشك شارب)\nذكر إبراهيم بن المنذر الحزامي وأبو عبيدة معمر بن المثنى أن\nاسمه البحتري بن الجعد وذكر مصعب الزبيري والرياشي وأبو العالية أن اسمه الأقرع بن معاذ وقال خالد بن كلثوم اسمه مهدي بن الملوح وأخبرني الأخفش عن السكري عن أبي زياد الكلابي قال ليلى صاحبة المجنون هي ليلى بنت سعد بن مهدي بن ربيعة بن الحريش بن كعب بن ربيعة ابن عامر بن صعصعة أخبرني محمد بن خلف وكيع قال حدثنا أبو قلابة الرقاشي قال حدثني عبد الصمد بن المعدل قال سمعت الأصمعي وقد تذاكرنا مجنون بني عامر يقول لم يكن مجنونا وإنما كانت به لوثة وهو القائل\n(أخذت محاسن كل ما ... ضنت محاسنه بحسنه)\n(كاد الغزال يكونها ... لولاالشوى ونشوز قرنه)\nوأخبرني عمر بن عبد الله بن جميل العتكي قال حدثنا عمر بن شبة قال حدثنا الأصمعي قال سألت أعرابيا من بني عامر بن صعصعة عن المجنون العامري فقال عن أيهم تسألني فقد كان فينا جماعة رموا بالجنون فعن أيهم تسأل فقلت عن الذي كان يشبب بليلى فقال كلهم كان يشبب بليلى قلت فأنشدني لبعضهم فأنشدني لمزاحم بن الحارث المجنون\n(ألا أيها القلب الذي لج هائما ... بليلى وليدا لم تقطع تمائمه)\n(أفق قد أفاق العاشقون وقد أنى ... لك اليوم أن تلقى طبيبا تلائمه)\n(أجدك لا تنسيك ليلى ملمة ... تلم ولا عهد يطول تقادمه)\nلت فأنشدني لغيره منهم فأنشدني لمعاذ بن كليب المجنون\n(ألا طالما لاعبت ليلى وقادني ... إلى اللهو قلب للحسان تبوع)\n(وطال امتراء الشوق عيني كلما ... نزفت دموعا تستجد دموع)\n(فقد طال إمساكي على الكبد التي ... بها من هوى ليلى الغداة صدوع)\nلت فأنشدني لغير هذين ممن ذكرت فأنشدني لمهدي بن الملوح\n(لو أن لك الدنيا وما عدلت به ... سواها وليلى بائن عنك بينها)\n(لكنت إلى ليلى فقيرا وإنما ... يقود إليها ود نفسك حينها)\nقلت له فأنشدني لمن بقي من هؤلاء فقال حسبك فوالله إن في واحد من هؤلاء لمن يوزن بعقلائكم اليوم أخبرني محمد بن خلف وكيع قال حدثنا أحمد بن الحارث الخراز قال قال ابن الأعرابي كان معاذ بن كليب مجنونا وكان يحب ليلى وشركه في حبها مزاحم بن الحارث العقيلي فقال مزاحم يوما للمجنون\n(كلانا يا معاذ يحب ليلى ... بفي وفيك من ليلى التراب)\n(شركتك في هوى من كان حظي ... وحظك من مودتها العذاب)\n(لقد خبلت فؤادك ثم ثنت ... بقلبي فهو مخبول مصاب)\nال فيقال إنه لما سمع هذه الأبيات التبس وخولط في عقله وذكر أبو عمرو الشيباني أنه سمع في الليل هاتفا يهتف بهذه الأبيات فكانت سبب جنونه وذكر إبراهيم بن المنذر الحزامي عن أيوب بن عباية أن فتى من بني مروان كان يهوى امرأة منهم فيقول فيها الشعر وينسبه إلى المجنون وأنه عمل له أخبارا وأضاف إليها ذلك الشعر فحمله الناس وزادوا فيه","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":1,"spl":"اختلاف الآراء حول اسم المجنون"},
{"id":"b7-4","bab":"الجزء 2","sec":"إنكار وجود المجنون","page":"ج2 ص10","text":"وأخبرني عمي عن الكوراني عن العمري عن العتبي عن عوانة أنه قال المجنون اسم مستعار لا حقيقة له وليس له في بني عامر أصل ولا نسب فسئل من قال هذه الأشعار فقال فتى من بني أمية وقال الجاحظ ما ترك الناس شعرا مجهول القائل قيل في ليلى إلا نسبوه إلى المجنون ولا شعرا هذه سبيله قيل في لبنى إلا نسبوه إلى قيس بن ذريح وأخبرني محمد بن خلف وكيع قال حدثنا هارون بن محمد بن عبد الملك قال حدثني أبو أيوب المديني قال حدثني الحكم بن صالح قال قيل لرجل من بني عامر هل تعرفون فيكم المجنون الذي قتله العشق فقال هذا باطل إنما يقتل العشق هذه اليمانية الضعاف القلوب أخبرنا أحمد بن عمر بن موسى قال حدثنا إبراهيم بن المنذر الحزامي قال حدثني أيوب بن عباية قال حدثني من سأل بني عامر بطنا بطنا عن المجنون فما وجد فيهم أحدا يعرفه أخبرني محمد بن مزيد بن أبي الأزهر قال حدثنا أحمد بن الحارث عن ابن الأعرابي أنه ذكر عن جماعة من بن عامر أنهم سئلوا عن المجنون فلم يعرفوه وذكروا أن هذا الشعر كله مولد عليه أخبرني أحمد بن عبيد الله بن عمار قال حدثني أحمد بن سليمان بن أبي شيخ عن أبيه عن محمد بن الحكم عن عوانة قال ثلاثة لم يكونوا قط ولا عرفوا ابن أبي العقب صاحب قصيدة الملاحم وابن القرية ومجنون بنى عامر\nأخبرني أبو الحسن الأسدي قال حدثنا الرياشي قال سمعت الأصمعي يقول الذي ألقي على المجنون من الشعر وأضيف أليه أكثر مما قاله هو أخبرني عيسى بن الحسين الوراق قال حدثنا عمر بن شبة قال حدثني إسحاق قال أنشدت أيوب بن عباية هذين البيتين\n(وخبرتماني أن تيماء منزل ... لليلى إذا ما الصيف ألقى المراسيا)\n(فهذه شهور الصيف عنا قد انقضت ... فما للنوى ترمي بليلى المراميا)\nسألته عن قائلهما فقال جميل فقلت له إن الناس يروونهما للمجنون فقال ومن هو المجنون فأخبرته فقال ما لهذا حقيقة ولا سمعت به وأخبرني عمي عن عبد الله بن شبيب عن هارون بن موسى الفروي قال سألت أبا بكر العدوي عن هذين البيتين فقال هما لجميل ولم يعرف المجنون فقلت فهل معهما غيرهما قال نعم وأنشدني\n(وإني لأخشى أن أموت فجاءة ... وفي النفس حاجات إليك كما هيا)\n(وإني لينسيني لقاؤك كلما ... لقيتك يوماأن أبثك ما بيا)\n(وقالوا به داء عياءأصابه ... وقد علمت نفسي مكان دوائيا)\nوأنا أذكر مما وقع إلي من أخباره جملا مستحسنة متبرئا من العهدة فيها فإن أكثر أشعاره المذكورة في أخباره ينسبها بعض الرواة إلى غيره وينسبها من حكيت عنه إليه وإذا قدمت هذه الشريطة برئت من عيب طاعن ومتتبع للعيوب أخبرني بخبره في شغفه بليلى جماعة من الرواة ونسخت ما لم أسمعه من\nالروايات وجمعت ذلك في سياقة خبره ما اتسق ولم يختلف فإذا اختلف نسبت كل رواية إلى راويها","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":2,"spl":"إنكار وجود المجنون"},
{"id":"b7-5","bab":"الجزء 2","sec":"العاشقان الصغيران ليلى والمجنون","page":"ج2 ص12","text":"فممن أخبرني بخبره أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة عن رجاله وإبراهيم بن أيوب عن ابن قتيبة ونسخت أخباره من رواية خالد بن كلثوم وأبي عمرو الشيباني وابن دأب وهشام بن محمد الكلبي وإسحاق بن الجصاص وغيرهم من الرواة وقال أبو عمرو الشيباني وأبو عبيدة كان المجنون يهوى ليلى بنت مهدي بن سعد بن مهدي بن ربيعة بن الحريش بن كعب بن ربيعة بن عامر بن صعصعة وتكنى أم مالك وهما حينئذ صبيان فعلق كل واحد منهما صاحبه وهما يرعيان مواشي أهلهما فلم يزالا كذلك حتى كبرا فحجبت عنه قال ويدل على ذلك قوله صوت\n(تعلقت ليلى وهي ذات ذؤابة ... ولم يبد للأتراب من ثديها حجم)\n(صغيرين نرعى البهم ياليت أننا ... إلى اليوم لم نكبر ولم تكبرالبهم)\nفي هذين البيتين للأخضر الجدي لحن من الثقيل الثاني بالوسطى ذكره هارون بن محمد بن عبد الملك الزيات والهشامي أخبرنا الحسين بن يحيى عن حماد بن إسحاق عن أبيه عن أيوب بن عباية ونسخت هذا الخبر بعينه من خط هارون بن محمد بن عبد الملك الزيات قال حدثنا عبد الله بن عمرو بن أبي سعد قال حدثنا الحسن بن علي قال حدثني أبو عتاب البصري عن إبراهيم بن محمد الشافعي قال بينا ابن مليكة يؤذن إذ سمع الأخضر الجدي يغني من دار العاص بن وائل\n(وعلقتها غراء ذات ذوائب ... ولم يبد للأتراب من ثديها حجم)\n(صغيرين نرعى البهم ياليت أننا ... إلى اليوم لم نكبر ولم تكبر البهم)\nال فأراد أن يقول حي على الصلاة فقال حي على البهم حتى سمعه أهل مكة فغدا يعتذر إليهم وقال ابن الكلبي حدثني معروف المكي والمعلى بن هلال وإسحاق بن الجصاص قالوا\nكان سبب عشق المجنون ليلى أنه أقبل ذات يوم على ناقة له كريمة وعليه حلتان من حلل الملوك فمر بامرأة من قومه يقال لها كريمة وعندها جماعة نسوة يتحدثن فيهن ليلى فأعجبهن جماله وكماله فدعونه إلى النزول والحديث فنزل وجعل يحدثهن وأمر عبدا له كان معه فعقر لهن ناقته وظل يحدثهن بقية يومه فبينا هو كذلك إذ طلع عليهم فتى عليه بردة من برد الأعراب يقال له منازل يسوق معزى له فلما رأينه أقبلن عليه وتركن المجنون فغضب وخرج من عندهن وأنشأ يقول\n(أأعقر من جرا كريمة ناقتي ... ووصلي مفروش لوصل منازل)\n(إذا جاء قعقعن الحلي ولم أكن ... إذا جئت أرضى صوت تلك الخلاخل)\n(متى ما انتضلنا بالسهام نضلته ... وإن نرم رشقا عندها فهو ناضلي)\nقال فلما أصبح لبس حلته وركب ناقة له أخرى ومضى متعرضا لهن فألفى ليلى قاعدة بفناء بيتها وقد علق حبه بقلبها وهويته وعندها جويريات يتحدثن معها فوقف بهن وسلم فدعونه إلى النزول وقلن له هل لك في محادثة من لا يشغله عنك منازل ولا غيره فقال إي لعمري فنزل وفعل مثل ما فعله بالأمس فأرادت أن تعلم هل لها عنده مثل ما له عندها فجعلت تعرض عن حديثه ساعة بعد ساعة وتحدث غيره وقد كان علق بقلبه مثل حبها إياه وشغفته واستملحها فبينا هي تحدثه إذا أقبل فتى من الحي فدعته وسارته سرارا طويلا ثم قالت له انصرف ونظرت إلى وجه المجنون قد تغير وانتقع لونه وشق عليه فعلها\nفأنشأت تقول\n(كلانا مظهر للناس بغضا ... وكل عند صاحبه مكين)\n(تبلغنا العيون بما أردنا ... وفي القلبين ثم هوى دفين)\nفلما سمع البيتين شهق شهقة شديدة وأغمي عليه فمكث على ذلك ساعة ونضحوا الماء على وجهه حتى أفاق وتمكن حب كل واحد منهما في قلب صاحبه حتى بلغ منه كل مبلغ","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":3,"spl":"العاشقان الصغيران ليلى والمجنون"},
{"id":"b7-6","bab":"الجزء 2","sec":"المجنون يخطب ليلى وأهلها يزوجونها وردا","page":"ج2 ص15","text":"أخبرني الحسن بن علي قال حدثني هارون بن محمد بن عبدالملك قال حدثني عبد الرحمن بن إبراهيم عن هشام بن محمد بن موسى المكي عن محمد بن سعيد المخزومي عن أبي الهيثم العقيلي قال لما شهر أمر المجنون وليلى وتناشد الناس شعره فيها خطبها وبذل لها خمسين ناقة حمراء وخطبها ورد بن محمد العقيلي وبذل لها عشرا من الأبل وراعيها فقال أهلها نحن مخيروها بينكما فمن اختارت تزوجته ودخلوا إليها فقالوا والله لئن لم تختاري وردا لنمثلن بك فقال المجنون\n(ألا يا ليل إن ملكت فينا ... خيارك فانظري لمن الخيار)\n(ولا تستبدلي مني دنيا ... ولا برما إذا حب القتار)\n(يهرول في الصغير إذا رآه ... وتعجزه ملمات كبار)\n(فمثل تأيم منه نكاح ... ومثل تمول منه افتقار)\nفاختارت وردا فتزوجته على كره منها وأخبرني أحمد بن عبد العزيز وحبيب بن نصر قالا حدثنا عمر بن شبة قال ذكر الهيثم بن عدي عن عثمان بن عمارة بن حريم المري قال خرجت إلى أرض بني عامر لألقى المجنون فدللت عليه وعلى محلته فلقيت أباه شيخا كبيرا وحوله إخوة للمجنون مع أبيهم رجالا فسألتهم عنه فبكوه وقال الشيخ أما والله لهو كان آثر عندي من هؤلاء جميعا وإنه عشق امرأة من قومه والله ما كانت تطمع في مثله فلما فشا أمره وأمرها كره أبوها أن يزوجه إياها بعد ما ظهر من أمرهما فزوجها غيره وكان أول ما كلف بها يجلس إليها في نفر من قومها فيتحدثون كما يتحدث الفتيان وكان أجملهم وأظرفهم وأرواهم لأشعار العرب فيفيضون في الحديث فيكون أحسنهم فيه إفاضة فتعرض عنه وتقبل على غيره وقد وقع له في قلبها مثل ما وقع لها في قلبه فظنت به ما هو عليه من حبها فأقبلت عليه يوما وقد خلت فقالت صوت\n(كلانا مظهر للناس بغضا ... وكل عند صاحبه مكين)\n(وأسرار الملاحظ ليس تخفى ... إذا نطقت بما تخفي العيون)\nنت في الأول عريب خفيف رمل وقيل إن هذا الغناء لشارية والبيت\nالأخير ليس من شعره قال فخر مغشيا عليه ثم أفاق فاقدا عقله فكان لا يلبس ثوبا إلا خرقه ولا يمشي إلا عاريا ويلعب بالتراب ويجمع العظام حوله فإذا ذكرت له ليلى أنشأ يحدث عنها عاقلا ولا يخطىء حرفا وترك الصلاة فإذا قيل له مالك لا تصلي لم يرد حرفا وكنا نحبسه ونقيده فيعض لسانه وشفته حتى خشينا عليه فخلينا سبيله فهو يهيم","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":4,"spl":"المجنون يخطب ليلى وأهلها يزوجونها وردا"},
{"id":"b7-7","bab":"الجزء 2","sec":"المجنون الهائم وعمر بن عبد الرحمن بن عوف","page":"ج2 ص17","text":"قال الهيثم فولى مروان بن الحكم عمر بن عبد الرحمن بن عوف صدقات بني كعب وقشير وجعدة والحريش وحبيب وعبد الله فنظر إلى المجنون قبل أن يستحكم جنونه فكلمه وأنشده فأعجب به فسأله أن يخرج معه فأجابه إلى ذلك فلما أراد الرواح جاءه قومه فأخبروه خبره وخبر ليلى وأن أهلها استعدوا السلطان عليه فأهدر دمه إن أتاهم فأضرب عما وعده وأمر له بقلائص فلما علم بذلك وأتي بالقلائص ردها عليه وانصرف وذكر أبو نصر أحمد بن حاتم عن جماعة من الرواة أن المجنون هو الذي سأل عمر بن عبد الرحمن أن يخرج به قال له أكون معك في هذا الجمع الذي تجمعه غدا فأرى في أصحابك وأتجمل في عشيرتي بك وأفخر بقربك فجاءه رهط من رهط ليلى وأخبروه بقصته وأنه لا يريد التجمل به وإنما يريد أن يدخل عليهم بيوتهم ويفضحهم في امرأة منهم يهواها وأنهم قد شكوه إلى السلطان فأهدر دمه إن دخل عليهم فأعرض عما أجابه إليه من أخذه معه وأمر له\nبقلائص فردها وقال في ذلك\n(رددت قلائص القرشي لما ... بدا لي النقض منه للعهود)\n(وراحوا مقصرين وخلفوني ... إلى حزن أعالجه شديد)\nقال ورجع آيسا فعاد إلى حاله الأولى قال فلم تزل تلك حاله إلا أنه غير مستوحش إنما يكون في جنبات الحي منفردا عاريا لا يلبس ثوبا إلا خرقه ويهذي ويخطط في الأرض ويلعب بالتراب والحجارة ولا يجيب أحدا سأله عن شيء فإذا أحبوا أن يتكلم أو يثوب عقله ذكروا له ليلى فيقول بأبي هي وأمي ثم يرجع إليه عقله فيخاطبونه ويجيبهم ويأتيه أحداث الحي فيحدثونه عنها وينشدونه الشعر الغزل فيجيبهم جوابا صحيحا وينشدهم أشعارا قالها حتى سعى عليهم في السنة الثانية بعد عمر بن عبد الرحمن نوفل بن مساحق فنزل مجمعا من تلك المجامع فرآه يلعب بالتراب وهو عريان فقال لغلام له يا غلام هات ثوبا فأتاه به فقال لبعضهم خذ هذا الثوب فالقه على ذلك الرجل فقال له أتعرفه جعلت فداك قال لا قال هذا ابن سيد الحي لا والله ما يلبس الثياب ولا يزيد على ما تراه يفعله الآن واذا طرح عليه شيء خرقه ولو كان يلبس ثوبا لكان في مال أبيه ما يكفيه وحدثه عن أمره فدعا به وكلمه فجعل لا يعقل شيئا يكلمه به فقال له قومه إن أردت أن يجيبك جوابا صحيحا فاذكر له ليلى فذكرها له وسأله عن حبه إياها فأقبل عليه يحدثه بحديثها ويشكو إليه حبه إياها وينشده شعره فيها فقال له نوفل الحب صيرك إلى ما أرى قال نعم وسينتهي بي إلى ما هو أشد مما ترى فعجب منه وقال له أتحب أن أزوجكها قال نعم وهل إلى ذلك من سبيل قال انطلق معي حتى أقدم على أهلها بك وأخطبها عليك وأرغبهم في المهر لها قال أتراك فاعلا قال نعم قال انظر ما تقول قال لك علي أن أفعل بك ذلك ودعا له بثياب فألبسه إياها وراح\nمعه المجنون كأصح أصحابه يحدثه وينشده فبلغ ذلك رهطها فتلقوه في السلاح وقالوا له يابن مساحق لا والله لا يدخل المجنون منازلنا أبدا أو يموت فقد أهدر لنا السلطان دمه فأقبل بهم وأدبر فأبوا فلما رأى ذلك قال للمجنون انصرف فقال له المجنون والله ما وفيت لي بالعهد قال له انصرافك بعد أن آيسني القوم من إجابتك أصلح من سفك الدماء فقال الممجنون صوت\n(أيا ويح من أمسى تخلس عقله ... فأصبح مذهوبا به كل مذهب)\n(خليا من الخلان إلا معذرا ... يضاحكني من كان يهوى تجنبي)\nالغناء للحسين بن محرز ثقيل أول بالوسطى من جامع أغانيه\n(إذا ذكرت ليلى عقلت وراجعت ... روائع عقلي من هوى متشعب)\n(وقالوا صحيح ما به طيف جنة ... ولا الهم إلا بافتراء التكذب)\n(وشاهد وجدي دمع عيني وحبها ... برى اللحم عن أحناء عظمي ومنكبي)\nوت\n(تجنبت ليلى أن يلج بك الهوى ... وهيهات كان الحب قبل التجنب)\n(ألا إنما غادرت يا أم مالك ... صدى أينما تذهب به الريح يذهب)\nلغناء لإسحاق خفيف ثقيل أول بإطلاق الوتر في مجرى البنصر وفيه لابن جامع هزج من رواية الهشامي وهي قصيدة طويلة ومما يغنى فيه منها قوله صوت\n(فلم أر ليلى بعد موقف ساعة ... بخيف منى ترمي جمار المحصب)\n(ويبدي الحصى منها إذا قذفت به ... من البرد أطراف البنان المخضب)\n(فأصبحت من ليلى الغداة كناظر ... مع الصبح في أعقاب نجم مغرب)\n(ألا إنما غادرت يا أم مالك ... صدى أينما تذهب به الريح يذهب)\nيه ثقيل أول مطلق باستهلال ذكر ابن المكي أنه لأبيه يحيى وذكر الهشامي أنه للواثق وذكر حبش أنه لابن محرز وهو في جامع أغاني سليمان","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":5,"spl":"المجنون الهائم وعمر بن عبد الرحمن بن عوف"},
{"id":"b7-8","bab":"الجزء 2","sec":"المجنون الهائم وعمر بن عبد الرحمن بن عوف","page":"ج2 ص17","text":"منسوب إليه أنشدني الأخفش عن أبي سعيد السكري عن محمد بن حبيب للمجنون\n(فوالله ثم الله إني لدائب ... أفكر ما ذنبي إليها وأعجب)\n(ووالله ماأدري علام قتلتني ... وأي أموري فيك يا ليل أركب)\n(أأقطع حبل الوصل فالموت دونه ... أم أشرب رنقا منكم ليس يشرب)\n(أم أهرب حتى لا أرى لي مجاورا ... أم أصنع ماذا أم أبوح فأغلب)\n(فأيهما يا ليل ما ترتضينه ... فإني لمظلوم وإني لمعتب)","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":6,"spl":"المجنون الهائم وعمر بن عبد الرحمن بن عوف — المجنون في الحج اللهم زدني لليلى حبا"},
{"id":"b7-9","bab":"الجزء 2","sec":"المجنون في الحج اللهم زدني لليلى حبا","page":"ج2 ص21","text":"وأخبرني أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة قال ذكر هشام ابن الكلبي ووافقه في روايته أبو نصر أحمد بن حاتم وأخبرنا الحسن بن علي حدثنا ابن أبي سعد قال حدثني علي بن الصباح عن هشام بن الكلبي عن أبيه أن أبا المجنون وأمه ورجال عشيرته اجتمعوا إلى أبي ليلى فوعظوه وناشدوه الله والرحم وقالوا له إن هذا الرجل لهالك وقبل ذلك ففي أقبح من الهلاك بذهاب عقله وإنك فاجع به أباه وأهله فنشدناك الله والرحم أن تفعل ذلك\nفوالله ما هي أشرف منه ولا لك مثل مال أبيه وقد حكمك في المهر وإن شئت أن يخلع نفسه إليك من ماله فعل فأبى وحلف بالله وبطلاق أمها إنه لا يزوجه إياها أبدا وقال أفضح نفسي وعشيرتي وآتي ما لم يأته أحد من العرب وأسم ابنتي بميسم فضيحة فانصرفوا عنه وخالفهم لوقته فزوجها رجلا من قومها وأدخلها إليه فما أمسى إلا وقد بنى بها وبلغه الخبر فأيس منها حينئذ وزال عقله جملة فقال الحي لأبيه احجج به إلى مكة وادع الله عز و جل له ومره أن يتعلق بأستار الكعبة فيسأل الله أن يعافيه مما به ويبغضها إليه فلعل الله أن يخلصه من هذا البلاء فحج به أبوه فلما صاروا بمنى سمع صائحا في الليل يصيح يا ليلى فصرخ صرخة ظنوا أن نفسه قد تلفت وسقط مغشيا عليه فلم يزل كذلك حتى أصبح ثم أفاق حائل اللون ذاهلا فأنشأ يقول صوت\n(عرضت على قلبي العزاء فقال لي ... من الآن فايأس لا أعزك من صبر)\n(إذا بان من تهوى وأصبح نائيا ... فلا شيء أجدى من حلولك في القبر)\n(وداع دعا إذ نحن بالخيف من منىفهيج أطراب الفؤاد وما يدري ... )\n(دعا باسم ليلى غيرها فكأنما ... أطارا بليلى طائرا كان في صدري)\n(دعا باسم ليلى ضلل الله سعيه ... وليلى بأرض عنه نازحة قفر)\nلغناء لعريب خفيف ثقيل ثم قال له أبوه تعلق بأستار الكعبة واسأل الله أن يعافيك من حب ليلى فتعلق بأستار الكعبة وقال اللهم زدني لليلى حبا وبها كلفا ولا تنسني ذكرها أبدا فهام حينئذ وأختلط فلم يضبط قالوا فكان يهيم في البرية مع الوحش ولا يأكل إلا ما ينبت في البرية من بقل ولا يشرب إلا مع الظباء إذا وردت مناهلها وطال شعر جسده ورأسه وألفته الظباء والوحوش فكانت لا تنفر منه وجعل يهيم حتى يبلغ حدود الشأم فإذا ثاب إليه عقله سأل من يمر به من أحياء العرب عن نجد فيقال له وأين أنت من نجد قد شارفت الشام أنت في موضع كذا فيقول فأروني وجهة الطريق فيرحمونه ويعرضون عليه أن يحملوه أو يكسوه فيأبى فيدلونه على طريق نجد فيتوجه نحوه","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":6,"spl":"المجنون الهائم وعمر بن عبد الرحمن بن عوف — المجنون في الحج اللهم زدني لليلى حبا","partial":1},
{"id":"b7-10","bab":"الجزء 2","sec":"وريح الخزامى هل تهب على نجد","page":"ج2 ص23","text":"أخبرني عمي قال حدثني الكراني قال حدثنا العمري عن الهيثم بن عدي وأخبرنا حبيب بن نصر المهلبي وأحمد بن عبد العزيز الجوهري قالا حدثنا عمر بن شبة قال ذكر الهيثم بن عدي عن أبي مسكين قال خرج منا فتى حتى إذا كان ببئر ميمون إذا جماعة فوق بعض تلك الجبال وإذا معهم فتى أبيض طوال جعد كأحسن من رأيت من الرجال على هزال منه\nوصفرة وإذا هم متعلقون به فسألت عنه فقيل لي هذا قيس المجنون خرج به أبوه يستجير له بالبيت وهو على أن يأتي به قبر رسول اللهليدعو له هناك لعله يكشف ما به فإنه يصنع بنفسه صنيعا يرحمه منه عدوه يقول أخرجوني لعلني أتنسم صبا نجد فيخرجونه فيتوجهون به نحو نجد ونحن مع ذلك نخاف أن يلقي نفسه من الجبل فإن شئت الأجر دنوت منه فأخبرته أنك أقبلت من نجد فدنوت منه وأقبلوا عليه فقالوا له يا أبا المهدي هذا الفتى أقبل من نجد فتنفس تنفسة ظننت أن كبده قد انصدعت ثم جعل يسألني عن واد واد وموضع موضع وأنا أخبره وهو يبكي أحر بكاء وأوجعه للقلب ثم أنشأ يقول\n(ألا ليت شعري عن عوارضتي قنا ... لطول الليالي هل تغيرتا بعدي)\n(وهل جارتانا بالبتيل إلى الحمى ... على عهدنا أم لم تدوما على العهد)\n(وعن علويات الرياح أذا جرت ... بريح الخزامى هل تهب على نجد)\n(وعن أقحوان الرمل ما هو فاعل ... إذا هو أسرى ليلة بثرى جعد)\n(وهل أنفضن الدهر أفنان لمتي ... على لاحق المتنين مندلق الوخد)\n(وهل أسمعن الدهر أصوات هجمة ... تحدر من نشز خصيب إلى وهد)\nخبرني عمي قال حدثنا الكراني قال حدثنا العمري عن الهيثم بن عدي والعتبي قالا مر المجنون بزوج ليلى وهو جالس يصطلي في يوم شات وقد أتى ابن عم له في حي المجنون لحاجة فوقف عليه ثم أنشأ يقول صوت\n(بربك هل ضممت إليك ليلى ... قبيل الصبح أو قبلت فاها)\n(وهل رفت عليك قرون ليلى ... رفيف الأقحوانة في نداها)\nقال اللهم إذ حلفتني فنعم قال فقبض المجنون بكلتا يديه قبضتين من الجمر فما فارقهما حتى سقط مغشيا عليه وسقط الجمر مع لحم راحتيه وعض على شفته فقطعها فقام زوج ليلى مغموما بفعله متعجبا منه فمضى غنى في البيتين المذكورين في هذا الخبر الحسين بن محرز ولحنه رمل بالوسطى عن الهشامي أخبرني أحمد بن عبد العزيز وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة قال قال محمد بن الحكم عن عوانة إنه حدثه ووافقه ابن نصر وابن حبيب قالوا إن أهل المجنون خرجوا به معهم إلى وادي القرى قبل توحشه ليمتاروا\nخوفا عليه من أن يضيع أو يهلك فمروا في طريقهم بجبلي نعمان فقال له بعض فتيان الحي هذان جبلا نعمان وقد كانت ليلى تنزل بهما قال فأي الرياح يأتي من ناحيتهما قالوا الصبا قال فوالله لا أريم هذا الموضع حتى تهب الصبا فأقام ومضوا فامتاروا لأنفسهم ثم أتوا عليه فأقاموا معه ثلاثة أيام حتى هبت الصبا ثم انطلق معهم فأنشأ يقول صوت\n(أيا جبلي نعمان بالله خليا ... سبيل الصبا يخلص إلي نسيمها)\n(أجد بردها أو تشف مني حرارة ... على كبد لم يبق إلا صميمها)\n(فإن الصبا ريح إذا ما تنسمت ... على نفس محزون تجلت همومها)","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":7,"spl":"وريح الخزامى هل تهب على نجد"},
{"id":"b7-11","bab":"الجزء 2","sec":"المجنون والديار الخوالي","page":"ج2 ص26","text":"أخبرني علي بن سليمان الأخفش قال حدثني محمد بن الحسين بن الحرون قال حدثني الكسروي عن جماعة من الرواة قال لما منع أبو ليلى المجنون وعشيرته من تزويجه بها كان لا يزال يغشى بيوتهم ويهجم عليهم فشكوه إلى السلطان فأهدر دمه لهم فأخبروه بذلك فلم يرعه وقال الموت أروح لي فليتهم قتلوني فلما علموا بذلك وعرفوا أنه لا يزال يطلب غرة منهم حتى إذا تفرقوا دخل دورهم فارتحلوا عنها وأبعدوا وجاء المجنون عشية فأشرف على دورهم فإذا هي منهم بلاقع فقصد منزل ليلى\nالذي كان بيتها فيه فألصق صدره به وجعل يمرغ خديه على ترابه ويبكي ثم أنشأ يقول وذكر هذه الأبيات ابن حبيب وأبو نصر له بغير خبر\n(أيا حرجات الحي حيث تحملوا ... بذي سلم لا جادكن ربيع)\n(وخيماتك اللاتي بمنعرج اللوى ... بلين بلى لم تبلهن ربوع)\n(ندمت على ما كان مني ندامة ... كما يندم المغبون حين يبيع)\n(فقدتك من نفس شعاع فإنني ... نهيتك عن هذا وأنت جميع)\n(فقربت لي غير القريب وأشرفت ... إليك ثنايا ما لهن طلوع)\nذكر خالد بن جميل وخالد بن كلثوم في أخبارهما التي صنعاها أن ليلى وعدته قبل أن يختلط أن تستزيره ليلة إذا وجدت فرصة لذلك فمكث مدة يراسلها في الوفاء وهي تعده وتسوفه فأتى أهلها ذات يوم والحي خلوف فجلس إلى نسوة من أهلها حجرة منها بحيث تسمع كلامه فحادثهن طويلا ثم قال ألا\nأنشدكن أبياتا أحدثتها في هذه الأيام قلن بلى فأنشدهن صوت\n(يا للرجال لهم بات يعروني ... مستطرف وقديم كاد يبليني)\n(من عاذري من غريم غير ذي عسر ... يأبى فيمطلني ديني ويلويني)\n(لا يبعد النقد من حقي فينكره ... ولا يحدثني أن سوف يقضيني)\n(وما كشكري شكر لو يوافقني ... ولا مناي سواه لو يوافيني)\n(أطعته وعصيت الناس كلهم ... في أمره وهواه وهو يعصيني)\nال فقلن له ما أنصفك هذا الغريم الذي ذكرته وجعلن يتضاحكن وهو يبكي فاستحيت ليلى منهن ورقت له حتى بكت وقامت فدخلت بيتها وانصرف هو في الثلاثة الأبيات الأول من هذه الأبيات هزج طنبوري للمسدود قالا في خبرهما هذا وكان للمجنون ابنا عم يأتيانه فيحدثانه ويسليانه ويؤانسانه فوقف عليهما يوما وهما جالسان فقالا له يا أبا المهدي ألا تجلس قال لا بل أمضي إلى منزل ليلى فأترسمه وأرى آثارها فيه فأشفي بعض ما في صدري بها فقالا له فنحن معك فقال إذا فعلتما أكرمتما وأحسنتما فقاما معه حتى أتى دار ليلى فوقف بها طويلا يتتبع آثارها ويبكي ويقف في موضع موضع منها ويبكي ثم قال صوت\n(يا صاحبي ألما بي بمنزلة ... قد مر حين عليها أيما حين)\n(إني أرى رجعات الحب تقتلني ... وكان في دبدئها ما كان يكفيني)\n(لا خير في الحب ليست فيه قارعة ... كأن صاحبها في نزع موتون)\n(إن قال عذاله مهلا فلان لهم ... قال الهوى غير هذا القول يعنيني)\n(ألقى من اليأس تارات فتقتلني ... وللرجاء بشاشات فتحييني)\nلغناء لإبراهيم خفيف ثقيل من جامع غنائه","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":8,"spl":"المجنون والديار الخوالي"},
{"id":"b7-12","bab":"الجزء 2","sec":"إذا جاء قعقعن الحلي","page":"ج2 ص29","text":"وقال هشام بن الكلبي عن أبي مسكين إن جماعة من بني عامر حدثوه قالوا كان رجل من بني عامر بن عقيل يقال له قيس بن معاذ وكان يدعى المجنون وكان صاحب غزل ومجالسة للنساء فخرج على ناقة له يسير فمر بامرأة من بني عقيل يقال لها كريمة وكانت جميلة عاقلة معها نسوة فعرفنه ودعونه إلى النزول والحديث وعليه حلتان له فاخرتان وطيلسان وقلنسوه فنزل فظل يحدثهن وينشدهن وهن أعجب شيء به فيما يرى فلما أعجبه ذلك منهن عقر لهن ناقته وقمن إليها فجعلن يشوين ويأكلن إلى أن أمسى فأقبل غلام شاب حسن الوجه من حيهن فجلس إليهن فأقبلن عليه بوجوههن يقلن له كيف ظللت يا منازل اليوم فلما رأى ذلك من فعلهن غضب فقام وتركهن وهو يقول\n(أأعقر من جرا كريمة ناقتي ... ووصلي مفروش لوصل منازل)\n(إذا جاء قعقعن الحلي ولم أكن ... إذا جئت أرضي صوت تلك الخلاخل)\nال فقال له الفتى هلم نتصارع أو نتناضل فقال له إن شئت ذلك فقم إلى حيث لا تراهن ولا يرينك ثم ما شئت فافعل وقال\n(إذا ما انتضلنا في الخلاء نضلته ... وإن يرم رشقا عندها فهو ناضلي)\nقال ابن الكلبي في هذا الخبر فلما أصبح لبس حلته وركب ناقته ومضى متعرضا لهن فألفى ليلى جالسة بفناء بيتها وكانت معهن يومئذ جالسة وقد علق بقلبها وهويته وعندها جويريات يحدثنها فوقف بهن وسلم فدعونه إلى النزول وقلن له هل لك في محادثة من لا يشغله عنك منازل ولا غيره قال إي لعمري\nفنزل وفعل فعلته بالأمس فأرادت أن تعلم هل لها عنده مثل ما عندها فجعلت تعرض عن حديثه ساعة بعد ساعة وتحدث غيره وقد كان علق حبها بقلبه وشغفه واستملحها فبينما هي تحدثه إذ أقبل فتى من الحي فدعته فسارته سرارا طويلا ثم قالت له انصرف فانصرف ونظرت إلى وجه المجنون قد تغير وامتقع وشق عليه ما فعلت فأنشأت تقول\n(كلانا مظهر للناس بغضا ... وكل عند صاحبه مكين)\n(تبلغنا العيون مقالتينا ... وفي القلبين ثم هوى دفين)\nقد نسبت هذا الشعر متقدما فلما سمع هذين البيتين شهق شهقة عظيمة وأغمي عليه فمكث كذلك ساعة ونضحوا الماء على وجهه حتى أفاق وتمكن حب كل واحد منهما في قلب صاحبه وبلغ منه كل مبلغ حدثني عمي عن عبد الله بن أبي سعد عن إبراهيم بن محمد بن إسماعيل القرشي قال حدثنا أبو العالية عن أبي ثمامة الجعدي قال لا يعرف فينا مجنون إلا قيس بن الملوح","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":9,"spl":"إذا جاء قعقعن الحلي"},
{"id":"b7-13","bab":"الجزء 2","sec":"خبر اتصال المجنون بليلى","page":"ج2 ص30","text":"قال وحدثني بعض العشيرة قال قلت لقيس بن الملوح قبل أن يخالط ما أعجب شيء أصابك في وجدك بليلى قال طرقنا ذات ليلة أضياف ولم يكن عندنا لهم أدم فبعثني أبي إلى منزل أبي ليلى وقال لي اطلب لنا منه أدما فأتيته فوقفت على خبائه فصحت به فقال ما تشاء فقلت طرقنا ضيفان ولا أدم عندنا لهم فأرسلني أبي نطلب منك أدما فقال يا ليلى أخرجي إليه ذلك النحي فاملئي له إناءه من السمن فأخرجته ومعي قعب فجعلت تصب\nالسمن فيه ونتحدث فألهانا الحديث وهي تصب السمن وقد امتلأ القعب ولا نعلم جميعا وهو يسيل حتى استنقعت أرجلنا في السمن قال فأتيتهم ليلة ثانية أطلب نارا وأنا متلفع ببرد لي فأخرجت لي نارا في عطبة فأعطتنيها ووقفنا نتحدث فلما احترقت العطبة خرقت من بردي خرقة وجعلت النار فيها فكلما احترقت خرقت أخرى وأذكيت بها النار حتى لم يبق علي من البرد إلا ما وارى عورتي وما أعقل ما أصنع وأنشدني\n(أمستقبلي نفح الصبا ثم شائقي ... ببرد ثنايا أم حسان شائق)\n(كأن على أنيابها الخمر شجها ... بماء الندى من آخر الليل عاتق)\n(وما شمته إلا بعيني تفرسا ... كما شيم في أعلى السحابة بارق)\nمن الناس من يروي هذه الأبيات لنصيب ولكن هكذا روي في هذا الخبر أخبرنا محمد بن خلف وكيع عن عبد الملك بن محمد الرقاشي عن عبد الصمد بن المعذل قال سمعت الأصمعي يقول وقد تذاكرنا مجنون بني عامر قال هو قيس بن معاذ العقيلي ثم قال لم يكن مجنونا إنما كانت به لوثة وهو القائل\n(أخذت محاسن كل ما ... ضنت محاسنه بحسنه)\n(كاد الغزال يكونها ... لولاالشوى ونشوز قرنه)\nقال وهو القائل صوت\n(ولم أر ليلى بعد موقف ساعة ... بخيف منى ترمي جمار المحصب)\n(ويبدي الحصى منها إذا قذفت به ... من البرد أطراف البنان المخضب)\n(فأصبحت من ليلى الغداة كناظر ... مع الصبح في أعقاب نجم مغرب)\n(ألا إنما غادرت يا أم مالك ... صدى أينما تذهب به الريح يذهب)\nي هذه الأبيات لحن من الثقيل الأول ابتداؤه نشيد من صنعة الواثق وهو المشهور وذكره ابن المكي لأبيه يحيى وهو في جامع غناء سليم بن سلام له وذكره حبش في موضعين من كتابه فنسبه في طريقة الثقيل الأول في أحدهما إلى ابن محرز والآخر إلى يحيى المكي وزعم الهشامي أن فيه لسليم بن سلام لحنا آخر من الثقيل الأول أخبرنا الحسن بن علي قال حدثنا أحمد بن عبد الجبار الصوفي قال حدثني إبراهيم بن سعد الزهري قال أتاني رجل من عذرة لحاجة فجرى ذكر العشق والعشاق فقلت له أنتم أرق قلوبا أم بنو عامر قال إنا لأرق الناس قلوبا ولكن غلبتنا بنو عامر بمجنونها أخبرني أحمد بن عمر بن موسى بن زكويه القطان إجازة قال حدثنا إبراهيم بن المنذر الحزامي قال أخبرني عبد الجبار بن سليمان بن نوفل بن مساحق عن أبيه عن جده قال أنا رأيت مجنون بني عامر وكان جميل الوجه أبيض اللون قد علاه شحوب واستنشدته فأنشدني قصيدته التي يقول فيها\n(تذكرت ليلى والسنين الخواليا ... وأيام لا أعدي على اللهو عاديا)\nخبرني محمد بن الحسن الكندي خطيب مسجد القادسية قال حدثنا\nالرياشي قال سمعت أبا عثمان المازني يقول سمعت معاذا وبشر بن المفضل جميعا ينشدان هذين البيتين وينسبانهما لمجنون بني عامر\n(طمعت بليلى أن تريع وإنما ... تقطع أعناق الرجال المطامع)\n(وداينت ليلى في خلاء ولم يكن ... شهود على ليلى عدول مقانع)\nحدثني محمد بن يحيى الصولي قال حدثنا أبو خليفة الفضل بن الحباب عن ابن سلام قال قضى عبيد الله بن الحسن بن الحصين بن أبي الحر العنبري على رجل من قومه قضية أوجبها الحكم عليه وظن العنبري أنه تحامل عليه وانصرف مغضبا ثم لقيه في طريق فأخذ بلجام بغلته وكان شديدا أيدا ثم قال له إيه يا عبيد الله\n(طمعت بليلى أن تريع وإنما ... تقطع أعناق الرجال المطامع)\nفقال عبيد الله\n(وبايعت ليلى في خلاء ولم يكن ... شهود عدول عند ليلى مقانع)\nخل عن البغلة قال الصولي في خبره هذا والبيتان للبعيث هكذا قال فلا أدري أمن قوله هو أم حكاية عن أبي خليفة","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":10,"spl":"خبر اتصال المجنون بليلى"},
{"id":"b7-14","bab":"الجزء 2","sec":"ليلى للمجنون ابق الله وأتق على نفسك","page":"ج2 ص34","text":"أخبرنا محمد بن القاسم الأنباري عن عبد الله بن خلف الدلال قال حدثنا زكريا بن موسى عن شعيب بن السكن عن يونس النحوي قال لما اختلط عقل قيس بن الملوح وترك الطعام والشراب مضت أمه إلى ليلى فقالت لها إن قيسا قد ذهب حبك بعقله وترك الطعام والشراب فلو جئته وقتا لرجوت أن يثوب إليه بعض عقله فقالت ليلى أما نهارا فلا لأنني لا آمن قومي على نفسي ولكن ليلا فأتته ليلا فقالت له يا قيس إن أمك تزعم أنك جننت من أجلي وتركت المطعم والمشرب فاتق الله وأبق على نفسك فبكى وأنشأ يقول\n(قالت جننت على أيش فقلت لها ... الحب أعظم مما بالمجانين)\n(الحب ليس يفيق الدهر صاحبه ... وإنما يصرع المجنون في الحين)\nال فبكت معه وتحدثا حتى كاد الصبح أن يسفر ثم ودعته وانصرفت فكان آخر عهده بها","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":11,"spl":"ليلى للمجنون ابق الله وأتق على نفسك — هل جن قيس بن الملوح"},
{"id":"b7-15","bab":"الجزء 2","sec":"هل جن قيس بن الملوح","page":"ج2 ص35","text":"أخبرنا ابن المرزبان قال قال القحذمي لما قال المجنون\n(قضاها لغيري وابتلاني بحبها ... فهلا بشيء غير ليلى ابتلانيا)\nلب عقله الغناء لحكم ثقيل أول وقيل إنه لابن الهربذ وفيه لمتيم خفيف ثقيل أول من جامع أغانيها وحدثني جحظة بهذا الخبر عن ميمون بن هارون أنه بلغه أنه لما قال هذا البيت برص أخبرني الحسن بن علي قال حدثنا محمد بن طاهر القرشي عن ابن عائشة قال إنما سمي المجنون بقوله\n(ما بال قلبك يا مجنون قد خلعا ... في حب من لا ترى في نيله طمعا)\n(الحب والود نيطا بالفؤاد لها ... فأصبحا في فؤادي ثابتين معا)\nدثنا وكيع عن ابن يونس قال قال الأصمعي لم يكن المجنون مجنونا إنما جننه العشق وأنشد له\n(يسمونني المجنون حين يرونني ... نعم بي من ليلى الغداة جنون)\n(ليالي يزهى بي شباب وشرة ... وإذا بي من خفض المعيشة لين)\nخبرني محمد بن المرزبان عن إسحاق بن محمد بن أبان قال حدثني علي ابن سهل عن المدائنى أنه ذكر عنده مجنون بني عامر فقال لم يكن مجنونا وإنما قيل له المجنون بقوله\n(وإني لمجنون بليلى موكل ... ولست عزوفا عن هواها ولا جلدا)\n(إذا ذكرت ليلى بكيت صبابة ... لتذكارها حتى يبل البكا الخدا)\nخبرني عمر بن جميل العتكي قال حدثنا عمر بن شبة قال حدثنا عون ابن عبد الله العامري أنه قال ما كان والله المجنون الذي تعزونه إلينا مجنونا إنما كانت به لوثة وسهو أحدثهما به حب ليلى وأنشد له\n(وبي من هوى ليلى الذي لو أبثه ... جماعة أعدائي بكت لي عيونها)\n(أرى النفس عن ليلى أبت أن تطيعني ... فقد جن من وجدي بليلى جنونها)\nخبرني ابن المرزبان قال قال العتبي إنما سمي المجنون بقوله\n(يقول أناس عل مجنون عامر ... يروم سلوا قلت أنى لما بيا)\n(وقد لامني في حب ليلى أقاربي ... أخي وابن عمي وابن خالي وخاليا)\n(يقولون ليلى أهل بيت عداوة ... بنفسي ليلى من عدو وماليا)\n(ولو كان في ليلى شذا من خصومة ... للويت أعناق المطي الملاويا)\nأخبرني هاشم بن محمد الخزاعي عن عيسى بن إسماعيل قال قال ابن سلام لو حلفت أن مجنون بني عامر لم يكن مجنونا لصدقت ولكن توله لما زوجت ليلى وأيقن اليأس منها ألم تسمع إلى قوله\n(أيا ويح من أمسى تخلس عقله ... فأصبح مذهوبا به كل مذهب)\n(خليعا من الخلان إلا مجاملا ... يساعدني من كان يهوى تجنبي)\n(إذا ذكرت ليلى عقلت وراجعت ... عوازب قلبي من هوى متشعب)\nخبرني به الحسن بن علي عن دينار بن عامر التغلبي عن مسعود بن سعد عن ابن سلام ونحوه أخبرني محمد بن خلف بن المرزبان قال أنشدني صالح بن سعيد قال أنشدني يعقوب بن السكيت للمجنون\n(يسمونني المجنون حين يرونني ... نعم بي من ليلى الغداة جنون)\nقال وأنشدنا له أيضا صوت\n(وشغلت عن فهم الحديث سوى ... ما كان فيك فإنه شغلي)\n(وأديم لحظ محدثي ليرى ... أن قد فهمت وعندكم عقلي)","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":11,"spl":"ليلى للمجنون ابق الله وأتق على نفسك — هل جن قيس بن الملوح"},
{"id":"b7-16","bab":"الجزء 2","sec":"شجون المجنون مع أم مالك","page":"ج2 ص38","text":"أخبرني ابن المرزبان عن محمد بن الحسن بن دينار الأحول عن علي بن المغيرة الأثرم عن أبي عبيدة أن صاحبة مجنون بني عامر التي كلف بها ليلى بنت مهدي بن سعد بن مهدي بن ربيعة بن الحريش وكنيتها أم مالك وقد ذكر هذه الكنية المجنون في شعره فقال\n(تكاد بلاد الله يا أم مالك ... بما رحبت يوما علي تضيق)\nوقال أيضا\n(فإن الذي أملت من أم مالك ... أشاب قذالي واستهام فؤاديا)\n(خليلي أن دارت على أم مالك ... صروف الليالي فابغيا لي ناعيا)\nقال أبو عمرو الشيباني علق المجنون ليلى بنت مهدي بن سعد من بني الحريش وكنيتها أم مالك فشهر بها وعرف خبره فحجبت عنه فشق ذلك عليه فخطبها إلى أبيها فرده وأبى أن يزوجه إياها فاشتد به الأمر حتى جن وقيل له مجنون بني عامر فكان على حاله يجلس في نادي قومه فلا يفهم ما يحدث به ولا يعقله إلا إذا ذكرت ليلى وأنشد له أبو عمرو صوت\n(ألا ما لليلى لا ترى عند مضجعي ... بليل ولا يجري بذلك طائر)\n(بلى إن عجم للطير تجري إذا جرت ... بليلى ولكن ليس الطير زاجز)\n(أزالت عن العهد الذي كان بيننا ... بذي الأثل أم قد غيرتها المقادر)\n(فوالله ما في القرب لي منك راحة ... ولا البعد يسليني ولا أنا صابر)\n(ووالله ما أدري بأية حيلة ... وأي مرام أو خطار أخاطر)\n(وتالله إن الدهر في ذات بيننا ... علي لها في كل حال لجائر)\n(فلو كنت إذا أزمعت هجري تركتني ... جميع القوى والعقل مني وافر)\n(ولكن أيامي بحقل عنيزة ... وبالرضم أيام جناها التجاور)\n(وقد أصبح الود الذي كان بيننا ... أماني نفس والمؤمل حائر)\n(لعمري لقد رنقت يا أم مالك ... حياتي وساقتني إليك المقادر)\nقال أبو عمرو وأخبرني بعض الشاميين قال دخلت أرض بني عامر فسألت عنه المجنون الذي قتله الحب فخبروني عن أنه كان عاشقا لجارية منهم يقال لها ليلى ربا معها ثم حجبت عنه فاشتد ذلك عليه وذهب عقله فأتاه إخوان\nمن إخوانه يلومونه على ما يصنع بنفسه فقال صوت\n(يا صاحبي ألما بي بمنزلة ... قد مر حين عليها أيما حين)\n(في كل منزلة ديوان معرفة ... لم يبق باقية ذكر الدواوين)\n(إني أرى رجعات الحب تقتلني ... وكان في بدئها ما كان يكفيني)\nالغناء لابن جامع خفيف ثقيل","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":12,"spl":"شجون المجنون مع أم مالك"},
{"id":"b7-17","bab":"الجزء 2","sec":"قيس الهائم على وجهه","page":"ج2 ص40","text":"أخبرني هاشم الخزاعي عن العباس بن الفرج الرياشي قال ذكر العتبي عن أبيه قال كان المجنون في بدء أمره يرى ليلى ويألفها ويأنس بها ثم غيبت عن ناظره فكان أهله يعزونه عنها ويقولون نزوجك أنفس جارية في عشيرتك فيأبى إلا ليلى ويهذي بها ويذكرها فكان ربما استراح إلى أمانيهم وركن إلى قولهم وكان ربما هاج عليه الحزن والهم فلا يملك مما هو فيه أن يهيم على وجهه وذلك قبل أن يتوحش مع البهائم في القفار فكان قومه يلومونه ويعذلونه فأكثروا عليه في الملامة والعذل يوما فقال صوت\n(يا للرجال لهم بات يعروني ... مستطرف وقديم كان يعنيني)\n(على غريم مليء غيرذي عدم ... يأبى فيمطلني ديني ويلويني)\n(لا يذكر البعض من ديني فينكره ... ولا يحدثني أن سوف يقضيني)\n(وما كشكري شكر لو يوافقني ... ولا منى كمناه إذ يمنيني)\n(أطعته وعصيت الناس كلهم ... في أمره ثم يأبى فهو يعصيني)\n(خيري لمن يبتغي خيري ويأمله ... من دون شري وشري غير مأمون)\n(وما أشارك في رأيي أخا ضعف ... ولا أقول أخي من لا يواتيني)\nي هذه الأبيات هزج طنبوري للمسدود من جامعه وقال أبو عمرو الشيباني حدثني رباح العامري قال كان المجنون أول ما علق ليلى كثير الذكر لها والإتيان بالليل إليها والعرب ترى ذلك غير منكر أن يتحدث الفتيان إلى الفتيات فلما علم أهلها بعشقه لها منعوه من إتيانها وتقدموا إليه فذهب لذلك عقله ويئس منه قومه واعتنوا بأمره واجتمعوا إليه ولاموه وعذلوه على ما يصنع بنفسه وقالوا والله ما هي لك بهذه الحال فلو تناسيتها رجونا أن تسلوا قليلا فقال لما سمع مقالتهم وقد غلب عليه البكاء صوت\n(فواكبدا من حب من لا يحبني ... ومن زفرات مالهن فناء)\n(أريتك إن لم أعطك الحب عن يد ... ولم يك عندي إذ أبيت إباء)\n(أتاركتي للموت أنت فميت ... وماللنفوس الخائفات بقاء)\nم أقبل على القوم فقال إن الذي بي ليس بهين فأقلوا من ملامكم فلست بسامع فيها ولا مطيع لقول قائل أخبرني عمي ومحمد بن حبيب وابن المرزبان عن عبد الله بن أبي سعد عن عبد العزيز بن صالح عن أبيه عن ابن دأب عن رباح بن حبيب العامري أنه سأله عن حال المجنون وليلى فقال كانت ليلى من بني الحريش وهي\nبنت مهدي بن سعيد بن مهدي بن ربيعة بن الحريش وكانت من أجمل النساء وأظرفهن وأحسنهن جسما وعقلا وأفضلهن أدبا وأملحهن شكلا وكان المجنون كلفا بمحادثة النساء صبابهن فبلغه خبرها ونعتت له فصبا إليها وعزم على زيارتها فتأهب لذلك ولبس أفضل ثيابه ورجل جمته ومس طيبا كان عنده وارتحل ناقة له كريمة برحل حسن وتقلد سيفه وأتاها فسلم فردت عليه السلام وتحفت في المسألة وجلس إليها فحادثته وحادثها فأكثرا وكل واحد منهما مقبل على صاحبه معجب به فلم يزالا كذلك حتى أمسيا فانصرف إلى أهله فبات بأطول ليلة شوقا إليها حتى إذا أصبح عاد إليها فلم يزل عندها حتى أمسى ثم انصرف إلى أهله فبات بأطول من ليلته الأولى واجتهد أن يغمض فلم يقدر على ذلك فأنشأ يقول\n(نهاري نهار الناس حتى إذا بدا ... لي الليل هزتني إليك المضاجع)\n(أقضي نهاري بالحديث وبالمنى ... ويجمعني والهم بالليل جامع)\n(لقد ثبتت في القلب منك محبة ... كما ثبتت في الراحتين الأصابع)\nروضه من الطويل والغناء لإبراهيم الموصلي رمل بالوسطى عن\nعمرو قال وأدام زيارتها وترك من كان يأتيه فيتحدث إليه غيرها وكان يأتيها في كل يوم فلا يزال عندها نهاره أجمع حتى إذا أمسى انصرف فخرج ذات يوم يريد زيارتها فلما قرب من منزلها لقيته جارية عسراء فتطير منها وأنشأ يقول\n(وكيف يرجى وصل ليلى وقد جرى ... بجد القوى والوصل أعسر حاسر)\n(صديع العصا صعب المرام إذا انتحى ... لوصل امرىء جذت عليه الأواصر)\nم سار إليها في غد فحدثها بقصته وطيرته ممن لقيه وأنه يخاف تغير عهدها وانتكاثه وبكى فقالت لا ترع حاش لله من تغير عهدي لا يكون والله ذلك أبدا إن شاء الله فلم يزل عندها يحادثها بقية يومه ووقع له في قلبها مثل ما وقع لهافي قلبه فجاءها يوما كما كان يجيء وأقبل يحدثها فأعرضت عنه وأقبلت على غيره بحديثها تريد بذلك محنته وأن تعلم ما في قلبه فلما رأى ذلك جزع جزعا شديدا حتى بان في وجهه وعرف فيه فلما خافت عليه أقبلت عليه كالمسرة إليه فقالت\n(كلانا مظهر للناس بغضا ... وكل عند صاحبه مكين)","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":13,"spl":"قيس الهائم على وجهه"},
{"id":"b7-18","bab":"الجزء 2","sec":"قيس الهائم على وجهه","page":"ج2 ص40","text":"فسري عنه وعلم ما في قلبها فقالت له إنما أردت أن أمتحنك والذي لك عندي أكثر من الذي لي عندك وأعطي الله عهدا إن جالست بعد يومي هذا رجلا\nسواك حتى أذوق الموت إلا أن أكره على ذلك قال فانصرفت عنه وهو من أشد الناس سرورا وأقرهم عينا وقال\n(أظن هواها تاركي بمضلة ... من الأرض لا مال لدي ولا أهل)\n(ولا أحد أفضي إليه وصيتي ... ولا صاحب إلا المطية والرحل)\n(محا حبها حب الألى كن قبلها ... وحلت مكانا لم يكن حل من قبل)","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":14,"spl":"قيس الهائم على وجهه — زواج ليلى ودعاء المجنون بطلاقها"},
{"id":"b7-19","bab":"الجزء 2","sec":"زواج ليلى ودعاء المجنون بطلاقها","page":"ج2 ص44","text":"أخبرني جعفر بن قدامة عن أبي العيناء عن العتبي قال لما حجبت ليلى عن المجنون خطبها جماعة فلم يرضهم أهلها وخطبها رجل من ثقيف موسر فزوجوه وأخفوا ذلك عن المجنون ثم نمي إليه طرف منه لم يتحققه فقال\n(دعوت إلهي دعوة ما جهلتها ... وربي بما تخفي الصدور بصير)\n(لئن كنت تهدي برد أنيابها العلا ... لأفقر مني إنني لفقير)\n(فقد شاعت الأخبار أن قد تزوجت ... فهل يأتيني بالطلاق بشير)\nوقال أيضا\n(ألا تلك ليلى العامرية أصبحت ... تقطع إلا من ثقيف حبالها)\n(هم حبسوها محبس البدن وابتغى ... بها المال أقوام ألا قل مالها)\n(إذا التفتت والعيس صعر من البرى ... بنخلة جلت عبرة العين حالها)\nقال وجعل يمر ببيتها فلا يسأل عنها ولا يلتفت إليه ويقول إذا جاوزه صوت\n(ألا أيها البيت الذي لا أزوره ... وإن حله شخص إلي حبيب)\n(هجرتك إشفاقا وزرتك خائفا ... وفيك علي الدهر منك رقيب)\n(سأستعتب الأيام فيك لعلها ... بيوم سرور في الزمان تؤوب)\nلغناء لعريب ثاني ثقيل بالوسطى قال وبلغه أن أهلها يريدون نقلها إلى الثقفي فقال صوت\n(كأن القلب ليلة قيل يغدى ... بليلى العامرية أو يراح)\n(قطاة عزها شرك فباتت ... تجاذبه وقد علق الجناح)\nروضه من الوافر الغناء لابن المكي خفيف ثقيل أول بالوسطى في\nمجراها عن إسحاق وفيه خفيف ثقيل آخر لسليمان مطلق في مجرى البنصر وفيه لإبراهيم رمل بالوسطى في مجراها عن الهشامي قال فلما نقلت ليلى إلى الثقفي قال\n(طربت وشاقتك الحمول الدوافع ... غداة دعا بالبين أسفع نازع)\n(شحا فاه نعبا بالفراق كأنه ... حريب سليب نازح الدار جازع)\n(فقلت ألا قد بين الأمر فانصرف ... فقد راعنا بالبين قبلك رائع)\n(سقيت سموما من غراب فإنني ... تبينت ما خبرت مذ أنت واقع)\n(ألم تر أني لا محب ألومه ... ولا ببديل بعدهم أنا قانع)\n(ألم تر دار الحي في رونق الضحى ... بحيث انحنت للهضبتين الأجارع)\n(وقد يتناءى الإلف من بعد ألفة ... ويصدع ما بين الخليطين صادع)\n(وكم من هوى أو جيرة قد ألفتهم ... زمانا فلم يمنعهم البين مانع)\n(كأني غداة البين ميت جوبة ... أخو ظمأ سدت عليه المشارع)\n(تخلس من أوشال ماء صبابة ... فلا الشرب مبذول ولا هو ناقع)\n(وبيض تطلى بالعبير كأنها ... نعاج الملا جيبت عليها البراقع)\n(تحملن من وادي الأراك فأومضت ... لهن بأطراف العيون المدامع)\n(فما رمن ربع الدار حتى تشابهت ... هجائنها والجون منها الخواضع)\n(وحتى حملن الحور من كل جانب ... وخاضت سدول الرقم منها الأكارع)\n(فلما استوت تحت الخدور وقد جرى ... عبير ومسك بالعرانين رادع)\n(أشرن بأن حثو الجمال فقد بدا ... من الصيف يوم لافح الحر ماتع)\n(فلما لحقنا بالحمول تباشرت ... بنا مقصرات غاب عنها المطامع)\n(يعرضن بالدل المليح وإن يرد ... جناهن مشغوف فهن موانع)\n(فقلت لأصحابي ودمعي مسبل ... وقد صدع الشمل المشتت صادع)\n(أليلى بأبواب الخدور تعرضت ... لعيني أم قرن من الشمس طالع)","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":14,"spl":"قيس الهائم على وجهه — زواج ليلى ودعاء المجنون بطلاقها"},
{"id":"b7-20","bab":"الجزء 2","sec":"حمام الأيك يهيج أحزان المجنون","page":"ج2 ص47","text":"أخبرني عيسى بن الحسين الوراق قال حدثنا الهيثم بن فراس قال حدثني العمري عن الهيثم بن عدي أن أبا المجنون حج به ليدعو الله عز و جل في الموقف أن يعافيه فسار ومعه ابن عمه زياد بن كعب بن مزاحم فمر بحمامة تدعو على أيكة فوقف يبكي فقال له زياد أي شيء هذا ما يبكيك أيضا سر بنا نلحق الرفقة فقال\n(أأن هتفت يوما بواد حمامة ... بكيت ولم يعذرك بالجهل عاذر)\n(دعت ساق حر بعد ما علت الضحى ... فهاج لك الأحزان أن ناح طائر)\n(تغني الضحى والصبح في مرجحنة ... كثاف الأعالي تحتها الماء حائر)\n(كأن لم يكن بالغيل أو بطن أيكة ... أو الجزع من تول الأشاءة حاضر)\n(يقول زياد إذ رأى الحي هجروا ... أرى الحي قد ساروا فهل أنت سائر)\n(وإني وإن غال التقادم حاجتي ... ملم على أوطان ليلى فناظر)\nخبرني محمد بن مزيد بن أبي الأزهر عن الزبير عن محمد بن عبد الله البكري عن موسى بن جعفر بن أبي كثير وأخبرني عمي عن عبد الله بن شبيب عن هارون بن موسى الفروي عن موسى بن جعفر بن أبي كثير وأخبرني ابن المرزبان عن ابن الهيثم عن العمري عن العتبي قالوا جميعا","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":15,"spl":"حمام الأيك يهيج أحزان المجنون — يا جبل التوباد"},
{"id":"b7-21","bab":"الجزء 2","sec":"يا جبل التوباد","page":"ج2 ص48","text":"كان المجنون وليلى وهما صبيان يرعيان غنما لأهلهما عند جبل في بلادهما يقال له التوباد فلما ذهب عقله وتوحش كان يجيء إلى ذلك الجبل فيقيم به\nفإذا تذكر أيام كان يطيف هو وليلى به جزع جزعا شديدا واستوحش فهام على وجهه حتى يأتي نواحي الشأم فإذا ثاب إليه عقله رأى بلدا لا يعرفه فيقول للناس الذين يلقاهم بأبي أنتم أين التوباد من أرض بني عامر فيقال له وأين أنت من أرض بني عامر أنت بالشام عليك بنجم كذا فأمه فيمضي على وجهه نحو ذلك النجم حتى يقع بأرض اليمن فيرى بلادا ينكرها وقوما لا يعرفهم فيسألهم عن التوباد وأرض بني عامر فيقولون وأين أنت من أرض بني عامر عليك بنجم كذا و كذا فلا يزال كذلك حتى يقع على التوباد فإذا رآه قال في ذلك\n(وأجهشت للتوباد حين رأيته ... وكبر للرحمن حين رآني)\n(وأذريت دمع العين لما عرفته ... ونادى بأعلى صوته فدعاني)\n(فقلت له قد كان حولك جيرة ... وعهدي بذاك الصرم منذ الزمان)\n(فقال مضوا واستودعوني بلادهم ... ومن ذا الذي يبقى على الحدثان)\n(وإني لأبكي اليوم من حذري غدا ... فراقك والحيان مجتمعان)\n(سجالا وتهتانا ووبلا وديمة ... وسحا وتسجاما إلى هملان)\nخبرني عمي عن عبد الله بن شبيب عن هارون بن موسى الفروي عن موسى بن جعفر بن أبي كثير قال لما قال المجنون\n(خليلي لا والله لا أملك الذي ... قضى الله في ليلى ولا ما قضى ليا)\n(قضاها لغيري وابتلاني بحبها ... فهلا بشيء غير ليلى ابتلانيا)\nسلب عقله\nوحدثني جحظة عن ميمون بن هارون عن إسحاق الموصلي أنه لما قالهمابرص قال موسى بن جعفر في خبره المذكور وكان المجنون يسير مع أصحابه فسمع صائحا يصيح يا ليلى في ليلة ظلماء أو توهم ذلك فقال لبعض من معه أما تسمع هذا الصوت فقال ما سمعت شيئا قال بلى والله هاتف يهتف بليلى ثم أنشأ يقول\n(أقول لأدنى صاحبي كليمة ... أسرت من الأقصى أجب ذا المناديا)\n(إذا سرت في الأرض الفضاء رأيتني ... أصانع رحلي أن يميل حياليا)\n(يمينا إذا كانت يمينا وإن تكن ... شمالا ينازعني الهوى عن شماليا)\nوقال ابن شبيب وحدثني هارون بن موسى قال قلت لغرير بن طلحة الخزومي من أشعر الناس ممن قال شعرا في منى ومكة وعرفات فقال أصحابنا القرشيون ولقد أحسن المجنون حيث يقول\n(وداع دعا إذ نحن بالخيف من منى ... فهيج أحزان الفؤاد وما يدري)\n( دعا باسم ليلى غيرها فكأنما ... أطار بليلى طائرا كان في صدري\nقلت له هل تروي للمجنون غير هذا قال نعم وأنشدني له\n(أما والذي أرسى ثبيرا مكانه ... عليه السحاب فوقه يتنصب)\nحذف\n(وما سلك الموماة من كل جسرة ... طليح كجفن السيف تهوي فتركب)\n(لقد عشت من ليلى زمانا أحبها ... أخا الموت إذ بعض المحبين يكذب)\nخبرني محمد بن مزيد عن حماد بن أسحاق عن أبيه قال كانت كنية ليلى أم عمرو وأنشد للمجنون صوت\n(أبى القلب إلا حبه عامرية ... لها كنية عمرو وليس لها عمرو)\n(تكاد يدي تندى إذا ما لمستها ... وينبت في أطرافها الورق الخضر)\nالغناء لعريب ثقيل أول وقال حبش فيه لإسحاق خفيف ثقيل","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":15,"spl":"حمام الأيك يهيج أحزان المجنون — يا جبل التوباد"},
{"id":"b7-22","bab":"الجزء 2","sec":"ليلى المنيحة","page":"ج2 ص51","text":"أخبرني هاشم بن محمد الخزاعي عن دماذ عن أبي عبيدة قال خطب ليلى صاحبة المجنون جماعة من قومها فكرهتهم فخطبها رجل من ثقيف موسر فرضيته وكان جميلا فتزوجها وخرج بها فقال المجنون في ذلك\n(ألا إن ليلى كالمنيحة أصبحت ... تقطع إلا من ثقيف حبالها)\n(فقد حبسوها محبس البدن وابتغى ... بها الريح أقوام تساحت مالها)\n(خليلي هل من حيلة تعلمانها ... يدني لنا تكليم ليلى احتيالها)\n(فإن أنتما لم تعلماها فلستما ... بأول باغ حاجة لا ينالها)\n(كأن مع الركب الذين أغتدوا بها ... غمامة صيف زعزعتها شمالها)\n(نظرت بمفضى سيل جوشن إذ غدوا ... تخب بأطراف المخارم آلها)\n(بشافية الأحزان هيج شوقها ... مجامعة الألاف ثم زيالها)\n(إذا التفتت من خلفها وهي تعتلي ... بها العيس جلى عبرة العين حالها)\nخبرني علي بن سليمان الأخفش قال أنشدني أحمد بن يحيى ثعلب عن أبي نصر أحمد بن حاتم قال وأنشدناه المبرد للمجنون فقال صوت\n(وأحبس عنك النفس والنفس صبة ... بذكراك والممشى إليك قريب)\n(مخافة أن تسعى الوشاة بظنة ... وأحرسكم أن يستريب مريب)\n(فقد جعلت نفسي وأنت اجترمته ... وكنت أعز الناس عنك تطيب)\n(فلو شئت لم أغضب عليك ولم يزل ... لك الدهر منى ما حييت نصيب)\n(أما والذي يبلو السرائر كلها ... ويعلم ما تبدي به وتغيب)\n(لقد كنت ممن تصطفي النفس خلة ... لها دون خلان الصفاء حجوب)\nكر يحيى المكي أنه لابن سريج ثقيل أول وقال الهشامي إنه من منحول يحيى إليه أخبرني الحرمي بن أبي العلاء قال حدثني الحسن بن محمد بن طالب\nالديناري قال حدثني إسحاق الموصلي وأخبرني به محمد بن مزيد والحسين بن يحيى عن حماد بن إسحاق عن أبيه قال حدثني سعيد بن سليمان عن أبي الحسن الببغاء قال بينا أنا وصديق لي من قريش نمشي بالبلاط ليلا إذا بظل نسوة في القمر فسمعت إحداهن تقول أهو هو فقالت لها أخرى معها إي والله إنه لهو هو فدنت مني ثم قالت يا كهل قل لهذا الذي معك\n(ليست لياليك في خاخ بعائدة ... كما عهدت ولا أيام ذي سلم)\nفقلت أجب فقد سمعت فقال قد والله قطع بي وأرتج علي فأجب عني فقلت\n(فقلت لها يا عز كل مصيبة ... إذا وطنت يوما لها النفس ذلت)\nم مضينا حتى إذا كنا بمفرق طريقين مضى الفتى إلى منزله ومضيت إلى منزلي فإذا أنا بجويرية تجذب ردائي فالتفت فقالت لي المرأة التي كلمتها تدعوك فمضيت معها حتى دخلت دارا واسعة ثم صرت إلى بيت فيه حصير وقد ثنت لي وسادة فجلست عليها ثم جاءت جارية بوسادة مثنية فطرحتها ثم جاءت المرأة فجلست عليها فقالت لي أنت المجيب قلت نعم قالت ما كان أفظ لجوابك وأغلظه فقلت لها ما حضرني غيره فسكتت ثم قالت لا والله ما خلق الله خلقا أحب إلي من إنسان كان معك فقلت لها أنا الضامن لك عنه ما\nتحبين فقالت هيهات أن يقع بذلك وفاء فقلت أنا الضامن وعلي أن آتيك به في الليلة القابلة فانصرفت فإذا الفتى ببابي فقلت ما جاء بك قال ظننت أنها سترسل إليك وسألت عنك فلم أعرف لك خبرا فظننت أنك عندها فجلست أنتظرك فقلت له وقد كان الذي ظننت وقد وعدتها أن آتيك فأمضي بك إليها في الليلة المقبلة فلما أصبحنا تهيأنا وانتظرنا المساء فلما جاء الليل رحلنا إليها فإذا الجارية منتظرة لنا فمضت أمامنا حين رأتنا حتى دخلت تلك الدار ودخلنا معها فإذا رائحة طيبة ومجلس قد أعد ونضد فجلسنا على وسائد قد ثنيت لنا وجلست مليا ثم أقبلت عليه فعاتبته مليا ثم قالت صوت\n(وأنت الذي أخلفتني ما وعدتني ... وأشمت بي من كان فيك يلوم)\n(وأبرزتني للناس ثم تركتني ... لهم غرضا أرمى وأنت سليم)\n(فلو كان قول يكلم الجلد قد بدا ... بجلدي من قول الوشاة كلوم)\nذه الأبيات لأميمة امرأة ابن الدمينة وفيها غناء لإبراهيم الموصلي ذكره إسحاق ولم يجنسه وقال الهشامي هو خفيف رمل وفيه لعريب خفيف ثقيل أول ينسب إلى حكم الوادي وإلى يعقوب قال ثم سكتت وسكت الفتى هنيهة ثم قال\n(غدرت ولم أغدر وخنت ولم أخن ... وفي بعض هذا للمحب عزاء)\n(جزيتك ضعف الود ثم صرمتني ... فحبك من قلبي إليك أداء)\nفالتفتت إلي فقالت ألا تسمع ما يقول قد خبرتك فغمزته أن كف فكف ثم أقبلت عليه وقالت صوت\n(تجاهلت وصلي حين جدت عمايتي ... فهلا صرمت الحبل إذ أنا أبصر)\n(ولي من قوى الحبل الذي قد قطعته ... نصيب وإذ رأيي جميع موفر)\n(ولكنما آذنت بالصرم بغتة ... ولست على مثل الذي جئت أقدر)","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":16,"spl":"ليلى المنيحة"},
{"id":"b7-23","bab":"الجزء 2","sec":"ليلى المنيحة","page":"ج2 ص51","text":"لغناء لإبراهيم ثقيل أول بالوسطى عن عمرو فقال\n(لقد جعلت نفسي وأنت اجترمته ... وكنت أعز الناس عنك تطيب)\nال فبكت ثم قالت أو قد طابت نفسك لا والله ما فيك بعدها خير ثم التفتت إلي وقالت قد علمت أنك لا تفي بضمانك ولا يفي به عنك وهذا البيت الأخير للمجنون وإنما ذكر هذا الخبر هنا وليس من أخبار المجنون لذكره فيه","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":17,"spl":"ليلى المنيحة — رجع الخبر إلى سياقة أخبار المجنون"},
{"id":"b7-24","bab":"الجزء 2","sec":"رجع الخبر إلى سياقة أخبار المجنون","page":"ج2 ص55","text":"أخبرني عمي قال حدثنا الكراني عن العمري عن الهيثم بن عدي أن رهط المجنون اجتازوا في نجعة لهم بحي ليلى وقد جمعتهم نجعه فرأى أبيات أهل ليلى ولم يقدم على الإلمام بهم وعدل أهله إلى جهة أخرى فقال المجنون\n(لعمرك إن البيت بالقبل الذي ... مررت ولم ألمم عليه لشائق)\nحذف\n(وبالجزع من أعلى الجنيبة منزل ... شجا حزن صدري به متضايق)\n(كأني إذا لم ألق ليلى معلق ... بسبين أهفو بين سهل وحالق)\n(على أنني لو شئت هاجت صبابتي ... علي رسوم عي فيها التناطق)\n(لعمرك إن الحب يا أم مالك ... بقلبي براني الله منه للاصق)\n(يضم علي الليل أطراف حبكم ... كما ضم أطراف القميص البنائق)\nصوت\n(وماذا عسى الواشون أن يتحدثوا ... سوى أن يقولوا إنني لك عاشق)\n(نعم صدق الواشون أنت حبيبة ... إلي وإن لم تصف منك الخلائق)\nلغناء لمتيم ثقيل أول من جامعها وفيه لدعامة رمل عن حبش أخبرني أحمد بن جعفر جحظة قال حدثني أحمد بن الطيب قال قال ابن الكلبي دخلت ليلى على جارة لها من عقيل وفي يدها مسواك تستاك به فتنفست ثم قالت سقى الله من أهدى لي هذا المسواك فقالت لها جارتها من هو قالت قيس بن الملوح وبكت ثم نزعت ثيابها تغتسل فقالت ويحه لقد علق مني ما أهلكه من غير أن أستحق ذلك فنشدتك الله أصدق في صفتي أم كذب فقالت لا والله بل صدق قال وبلغ المجنون قولها فبكى ثم انشأ يقول\n(نبئت ليلى وقد كنا نبخلها ... قالت سقى المزن غيثا منزلا خربا)\n(وحبذا راكب كنا نهش به ... يهدي لنا من أراك الموسم القضبا)\n(قالت لجارتها يوما تسائلها ... لما استحمت وألقت عندها السلبا)\n(يا عمرك الله ألا قلت صادقة ... أصدقت صفة المجنون أم كذبا)\nيروى نشدتك الله ويروى أصادقا وصف المجنون أم كذبا وقال أبو نصر في أخباره لما زوجت ليلى بالرجل الثقفي سمع المجنون رجلا من قومها يقول لآخر أنت ممن يشيع ليلى قال ومتى تخرج قال غدا ضحوة أو الليلة فبكى المجنون ثم قال صوت\n(كأن القلب ليلة قيل يغدى ... بليلى العامرية أو يراح)\n(قطاة عزها شرك فباتت ... تجاذبه وقد علق الجناح)\nلغناء ليحيى المكي خفيف ثقيل بالوسطى عن عمرو وفيه رمل ينسب إلى إبراهيم وإلى أحمد بن يحيى المكي وقال حبش فيه خفيف ثقيل بالوسطى لسليم","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":17,"spl":"ليلى المنيحة — رجع الخبر إلى سياقة أخبار المجنون"},
{"id":"b7-25","bab":"الجزء 2","sec":"غريب الدار","page":"ج2 ص57","text":"وقال الهيثم بن عدي في خبره حدثني عبد الله بن عياش الهمداني قال حدثني رجل من بني عامر قال مطرنا مطرا شديدا في ربيع ارتبعناه ودام المطر ثلاثا ثم أصبحنا في اليوم الرابع على صحو وخرج الناس يمشون على الوادي فرأيت رجلا جالسا حجرة وحده فقصدته فإذا هو المجنون جالس وحده يبكي فوعظته وكلمته طويلا وهو ساكت لم يرفع رأسه إلي ثم أنشدني بصوت حزين لا أنساه أبدا وحرقته صوت\n(جرى السيل فاستبكاني السيل إذا جرى ... وفاضت له من مقلتي غروب)\n(وما ذاك إلا حين أيقنت أنه ... يكون بواد أنت فيه قريب)\n(يكون أجاجا دونكم فإذا انتهى ... إليكم تلقى طيبكم فيطيب)\n(أظل غريب الدار في أرض عامر ... ألا كل مهجور هناك غريب)\n(وإن الكثيب الفرد من أيمن الحمى ... إلي وإن لم آته لحبيب)\n(فلا خير في الدنيا إذا أنت لم تزر ... حبيبا ولم يطرب إليك حبيب)\nأول هذه القصيدة وفيه أيضا غناء صوت\n(ألا أيها البيت الذي لا أزوره ... وهجرانه مني إليه ذنوب)\n(هجرتك مشتاقا وزرتك خائفا ... وفيك علي الدهر منك رقيب)\n(سأستعطف الأيام فيك لعلها ... بيوم سرور في هواك تثيب)\nذه الأبيات في شعر محمد بن أمية مروية ورويت هاهنا للمجنون في هذه القصيدة وفيها لعريب ثقيل أول ولعبد الله بن العباس ثاني ثقيل ولأحمد بن المكي خفيف ثقيل\n(وأفردت إفراد الطريد وباعدت ... إلى النفس حاجات وهن قريب)\nصوت\n(جرى السيل فاستبكاني السيل إذا جرى ... وفاضت له من مقلتي غروب)\n(وما ذاك إلا حين أيقنت أنه ... يكون بواد أنت فيه قريب)\n(يكون أجاجا دونكم فإذا انتهى ... إليكم تلقى طيبكم فيطيب)\n(أظل غريب الدار في أرض عامر ... ألا كل مهجور هناك غريب)\n(وإن الكثيب الفرد من أيمن الحمى ... إلي وإن لم آته لحبيب)\n(فلا خير في الدنيا إذا أنت لم تزر ... حبيبا ولم يطرب إليك حبيب)\nأول هذه القصيدة وفيه أيضا غناء صوت\n(ألا أيها البيت الذي لا أزوره ... وهجرانه مني إليه ذنوب)\n(هجرتك مشتاقا وزرتك خائفا ... وفيك علي الدهر منك رقيب)\n(سأستعطف الأيام فيك لعلها ... بيوم سرور في هواك تثيب)\nذه الأبيات في شعر محمد بن أمية مروية ورويت هاهنا للمجنون في هذه القصيدة وفيها لعريب ثقيل أول ولعبد الله بن العباس ثاني ثقيل ولأحمد بن المكي خفيف ثقيل\n(وأفردت إفراد الطريد وباعدت ... إلى النفس حاجات وهن قريب)\n(لئن حال يأس دون ليلى لربما ... أتى اليأس دون الأمر فهو عصيب)\n(ومنيتني حتى إذا ما رأيتني ... على شرف للناظرين يريب)\n(صددت وأشمت العدو بصرمنا ... أثابك يا ليلى الجزاء مثيب)","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":18,"spl":"غريب الدار"},
{"id":"b7-26","bab":"الجزء 2","sec":"أبلغيها السلام وقولي لها هيهات","page":"ج2 ص59","text":"أخبرني هاشم بن محمد الخزاعي قال حدثنا محمد بن زكريا الغلابي قال حدثنا مهدي بن سابق قال حدثنا بعض مشايخ بني عامر أن المجنون مر في توحشه فصادف حي ليلى راحلا ولقيها فجأة فعرفها وعرفته فصعق وخر مغشيا على وجهه وأقبل فتيان من حي ليلى فأخذوه ومسحوا التراب عن وجهه وأسندوه إلى صدورهم وسألوا ليلى أن تقف له وقفة فرقت لما رأته به وقالت أما هذا فلا يجوز أن أفتضح به ولكن يا فلانة لأمة لها اذهبي إلى قيس فقولي له ليلى تقرأ عليك السلام وتقول لك أعزز علي بما أنت فيه ولو وجدت سبيلا إلى شفاء دائك لوقيتك بنفسي منه فمضت الوليدة إليه وأخبرته بقولها فأفاق وجلس وقال أبلغيها السلام وقولي لها هيهات إن دائي ودوائي أنت وإن حياتي ووفاتي لفي يديك ولقد وكلت بي شقاء لازما وبلاء طويلا ثم بكى وأنشأ يقول\n(أقول لأصحابي هي الشمس ضوءها ... قريب ولكن في تناولها بعد)\n(لقد عرضتنا الريح منها بنفحة ... على كبدي من طيب أرواحها برد)\n(فما زلت مغشيا علي وقد مضت ... أناة وما عندي جواب ولا رد)\n(أقلب بالأيدي وأهلي بعولة ... يفدونني لو يستطيعون أن يفدوا)\n(ولم يبق إلا الجلد والعظم عاريا ... ولا عظم لي إن دام ما بي ولا جلد)\n(أدنياي مالي في انقطاعي وغربتي ... إليك ثواب منك دين ولا نقد)\n(عديني بنفسي أنت وعدا فربما ... جلا كربة المكروب عن قلبه الوعد)\nوقد يبتلى قوم ولا كبليتي ... ولا مثل جدي في الشقاء بكم جد غزتني جنود الحب من كل جانب ... إذا حان من جند قفول أتى جند\nوقال أبو نصر أحمد بن حاتم كان أبو عمرو المدني يقول قال نوفل بن مساحق أخبرت عن المجنون أن سبب توحشه أنه كان يوما بضرية جالسا وحده إذ ناداه مناد من الجبل\n(كلانا يا أخي يحب ليلى ... بفي وفيك من ليلى التراب)\n(لقد خبلت فؤادك ثم ثنت ... بقلبي فهو مهموم مصاب)\n(شركتك في هوى من ليس تبدي ... لنا الأيام منه سوى اجتناب)","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":19,"spl":"أبلغيها السلام وقولي لها هيهات"},
{"id":"b7-27","bab":"الجزء 2","sec":"نوفل بن مساحق يروي أخبار المجنون","page":"ج2 ص60","text":"قال فتنفس الصعداء وغشي عليه وكان هذا سبب توحشه فلم ير له أثر حتى وجده نوفل بن مساحق قال نوفل قدمت البادية فسألت عنه فقيل لي\nتوحش ومالنا به عهد ولا ندري إلى أين صار فخرجت يوما أتصيد الأروى ومعي جماعة من أصحابي حتى إذا كنت بناحية الحمى إذا نحن بأراكة عظيمة قد بدا منها قطيع من الظباء فيها شخص إنسان يرى من خلل تلك الأراكة فعجب أصحابي من ذلك فعرفته وأتيته وعرفت أنه المجنون الذي أخبرت عنه فنزلت عن دابتي وتخففت من ثيابي وخرجت أمشي رويدا حتى أتيت الأراكة فارتقيت حتى صرت على أعلاها وأشرفت عليه وعلى الظباء فإذا به وقد تدلى الشعر على وجهه فلم أكد أعرفه إلا بتأمل شديد وهو يرتعي في ثمر تلك الأراكة فرفع رأسه فتمثلت ببيت من شعره\n(أتبكي على ليلى ونفسك باعدت ... مزارك من ليلى وشعباكما معا)\nال فنفرت الظباء واندفع في باقي القصيدة ينشدها فما أنسى حسن نغمته وحسن صوته وهو يقول\n(فما حسن أن تأتي الأمر طائعا ... وتجزع أن داعي الصبابة أسمعا)\n(بكت عيني اليسرى فلما زجرتها ... عن الجهل بعد الحلم أسبلتا معا)\n(وأذكر أيام الحمى ثم أنثني ... على كبدي من خشية أن تصدعا)\n(فليست عشيات الحمى برواجع ... عليك ولكن خل عينيك تدمعا)\n(معي كل غر قد عصى عاذلاته ... بوصل الغواني من لدن أن ترعرعا)\n(إذ راح يمشي في الرداءين أسرعت ... إليه العيون الناظرات التطلعا)\nقال ثم سقط مغشيا عليه فتمثلت بقوله\n(يا دار ليلى بسقط الحي قد درست ... إلا الثمام وإلا موقد النار)\n(ما تفتأ الدهر من ليلى تموت كذا ... في موقف وقفته أو على دار)\n(أبلى عظامك بعد اللحم ذكركها ... كما ينحت قدح الشوحط الباري)\nفرفع رأسه إلي وقال من أنت حياك الله فقلت أنا نوفل بن مساحق فحياني فقلت له ما أحدثت بعدي في يأسك منها فأنشدني يقول\n(ألا حجبت ليلى وآلى أميرها ... علي يمينا جاهدا لا أزورها)\n(وأوعدني فيها رجال أبوهم ... أبي وأبوها خشنت لي صدورها)\n(على غير جرم غير أني أحبها ... وأن فؤادي رهنها وأسيرها)\nقال ثم سنحت له ظباء فقام يعدو في أثرها حتى لحقها فمضى معها حدثني الحسن بن علي قال حدثنا عبد الله بن أبي سعد قال حدثني علي بن الصباح عن ابن الكلبي قال لما قال مجنون بني عامر\n(قضاها لغيري وابتلاني بحبها ... فهلا بشيء غير ليلى ابتلانيا)\nنودي في الليل أنت المتسخط لقضاء الله والمعترض في أحكامه واختلس عقله فتوحش منذ تلك الليلة وذهب مع الوحش على وجهه وهذه القصيدة التي قال فيها هذا البيت من أشهر أشعاره والصوت المذكور بذكره أخبار المجنون هاهنا منها وفيها أيضا عدة أبيات يغنى فيها فمن ذلك\nصوت\n(أعد الليالي ليلة بعد ليلة ... وقد عشت دهرا لا أعد اللياليا)\n(أراني إذا صليت يممت نحوها ... بوجهي وإن كان المصلى ورائيا)\n(وما بي إشراك ولكن حبها ... كعود الشجا أعيا الطبيب المداويا)\n(أحب من الأسماء ما وافق اسمها ... وأشبهه أو كان منه مدانياي)\nي هذه الأبيات هزج خفيف لمعان معزفي صوت\n(وخبرتماني أن تيماء منزل ... لليلى إذا ما الصيف ألقى المراسيا)\n(فهذي شهور الصيف عني قد انقضت ... فما للنوى ترمي بليلى المراميا)\nفي هذين البيتين لحن من الرمل صنعته عجوز عمير الباذغيسي على لحن إسحاق\n(أماوي إن المال غاد ورائح ... )\n(وله حديث قد ذكر في أخبار إسحاق ... )\nوهذا اللحن إلى الآن يغنى لأنه أشهر في أيدي الناس وإنما هو لحن إسحاق أخذ فجعل على هذه الأبيات وكيد بذلك\nصوت\n(فلو كان واش باليمامة بيته ... وداري بأعلى حضرموت أهتدي ليا)\n(وماذا لهم لا أحسن الله حالهم ... من الحظ في تصريم ليلى حباليا)\n(فأنت التي إن شئت أشقيت عيشتي ... وإن شئت بعد الله أنعمت باليا)\n(وأنت التي ما من صديق ولا عدا ... يرى نضو ما أبقيت إلا رثي ليا)\n(أمضروبة ليلى على أن أزورها ... ومتخذ ذنبا لها أن ترانيا)\nي\n(إذا سرت في الأرض الفضاء رأيتني ... أصانع رحلي أن يميل حياليا)\n(يمينا إذا كانت يمينا وإن تكن ... شمالا ينازعني الهوى عن شماليا)\n(أحب من ألاسماء ما وافق اسمها ... وأشبهه أو كان منه مدانيا)\n(هي السحر إلا أن للحسر رقية ... وإني لا ألفي لها الدهر راقيا)\nأنشد أبو نصر للمجنون وفيه غناء صوت\n(تكاد يدي تندى إذا ما لمستها ... وينبت في أطرافها الورق الخضر)","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":20,"spl":"نوفل بن مساحق يروي أخبار المجنون","partial":1},
{"id":"b7-28","bab":"الجزء 2","sec":"نوفل بن مساحق يروي أخبار المجنون","page":"ج2 ص60","text":"(أبى القلب إلا حبها عامرية ... لها كنية عمرو وليس لها عمرو)\nالغناء لعريب ثقيل أول وذكر الهشامي أن فيه لإسحاق خفيف ثقيل","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":21,"spl":"نوفل بن مساحق يروي أخبار المجنون — المجنون بعد موت أبيه كنت سيفا لا تفل مضاربه"},
{"id":"b7-29","bab":"الجزء 2","sec":"المجنون بعد موت أبيه كنت سيفا لا تفل مضاربه","page":"ج2 ص64","text":"أخبرني محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه\nعن الهيثم بن عدي قال أنشدني جماعة من بني عقيل للمجنون يرثي أباه ومات قبل اختلاطه وتوحشه فعقر على قبره ورثاه بهذه الأبيات\n(عقرت على قبر الملوح ناقتي ... بذي السرح لما أن جفته أقاربه)\n(وقلت لها كوني عقيرا فإنني ... غداة غد ماش وبالأمس راكبه)\n(فلا يبعدنك الله يابن مزاحم ... وكل امرىء للموت لا بد شاربه)\n(فقد كنت طلاع النجاد ومعطي الجياد ... وسيفا لا تفل مضاربه)\nخبرني حبيب بن نصر المهلبي قال حدثنا عبد الله بن شبيب عن الحزامي عن محمد بن معن قال بلغني أن رجلا من بني جعدة بن كعب كان أخا وخلا للمجنون مر به يوما وهو جالس يخط في الأرض ويعبث بالحصى فسلم عليه وجلس عنده فأقبل يخاطبه ويعظه ويسليه وهو ينظر إليه ويلعب بيده كما كان وهو مفكر قد غمره ما هو فيه فلما طال خطابه إياه قال يا أخي أما لكلامي جواب فقال له والله يا أخي ما علمت أنك تكلمني فاعذرني فإني كما ترى مذهوب العقل مشترك اللب وبكى ثم أنشأ يقول صوت\n(وشغلت عن فهم الحديث سوى ... ما كان منك فإنه شغلي)\n(وأديم لحظ محدثي ليرى ... أن قد فهمت وعندكم عقلي)\nلغناء لعلويه وقال الهيثم مر المجنون بواد في أيام الربيع وحمامه يتجاوب فأنشأ يقول\nصوت\n(ألا يا حمام الأيك ما لك باكيا ... أفارقت إلفا أم جفاك حبيب)\n(دعاك الهوى والشوق لما ترنمت ... هتوف الضحى بين الغصون طروب)\n(تجاوب ورقا قد أذن لصوتها ... فكل لكل مسعد ومجيب)\nلغناء لرذاذ ثقيل أول مطلق في مجرى الوسطى وقال خالد بن حمل حدثني رجال من بني عامر أن زوج ليلى وأباها خرجا في أمر طرق الحي إلى مكة فأرسلت ليلى بأمة لها إلى المجنون فدعته فأقام عندها ليلة فأخرجته في السحر وقالت له سر إلي في كل ليلة ما دام القوم سفرا فكان يختلف إليها حتى قدموا وقال فيها في آخر ليلة لقيها وودعته\n(تمتع بليلى إنما أنت هامة ... من الهام يدنو كل يوم حمامها)\n(تمتع إلى أن يرجع الركب إنهم ... متى يرجعوا يحرم عليك كلامها)","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":21,"spl":"نوفل بن مساحق يروي أخبار المجنون — المجنون بعد موت أبيه كنت سيفا لا تفل مضاربه"},
{"id":"b7-30","bab":"الجزء 2","sec":"مرض المجنون ولم تعده ليلى","page":"ج2 ص66","text":"وقال الهيثم مرض المجنون قبل أن يختلط فعاده قومه ونساؤهم ولم تعده ليلى فيمن عاده فقال صوت\n(ألا ما لليلى لا ترى عند مضجعي ... بليل ولا يجري بها لي طائر)\n(بلى إن عجم الطير تجري إذا جرت ... بليلى ولكن ليس للطير زاجر)\n(أحالت عن العهد الذي كان بيننا ... بذي الرمث أم قد غيبتها المقابر)\nلغناء لسليم ثاني ثقيل بالوسطى عن الهشامي\n(فوالله ما في القرب لي منك راحة ... ولا البعد يسليني ولا أنا صابر)\n(ووالله ما أدري بأية حيلة ... وأي مرام أو خطار أخاطر)\n(ووالله إن الدهر في ذات بيننا ... علي لها في كل أمر لجائر)\n(فلوكنت إذا أزمعت هجري تركتني ... جميع القوى والعقل مني وافر)\n(ولكن أيامي بحفل عنيزة ... وذي الرمث أيام جناها التجاور)\n(فقد أصبح الود الذي كان بيننا ... أماني نفس إن تخبر خابر)\n(لعمري لقد أرهقت يا أم مالك ... حياتي وساقتني إليك المقادر)\nخبرني عمي قال حدثني محمد بن عبد الله الأصبهاني المعروف بالحزنبل عن عمرو بن أبي عمرو الشيباني عن أبيه قال حدثني بعض بني عقيل قال قيل للمجنون أي شيء رأيته أحب إليك قال ليلى قيل دع ليلى فقد عرفنا ما لها عندك ولكن سواها قال والله ما أعجبني شيء قط فذكرت ليلى إلا سقط من عيني وأذهب ذكرها بشاشته عندي غير أني رأيت ظبيا مرة فتأملته وذكرت ليلى فجعل يزداد في عيني حسنا ثم إنه عارضه ذئب وهرب منه فتبعته حتى خفيا عني فوجدت\nالذئب قد صرعه وأكل بعضه فرميته بسهم فما أخطأت مقتله وبقرت بطنه فأخرجت ما أكل منه ثم جمعته إلى بقية شلوه ودفنته وأحرقت الذئب وقلت في ذلك\n(أبى الله أن تبقى لحي بشاشة ... فصبرا على ما شاءه الله لي صبرا)\n(رأيت غزالا يرتعي وسط روضة ... فقلت أرى ليلى تراءت لنا ظهرا)\n(فيا ظبي كل رغدا هنيئا ولا تخف ... فإنك لي جار ولا ترهب الدهرا)\n(وعندي لكم حصن حصين وصارم ... حسام إذا أعملته أحسن الهبرا)\n(فما راعني إلا وذئب قدانتحى ... فأعلق في أحشائه الناب والظفرا)\n(ففوقت سهمي في كتوم غمزتها ... فخالط سهمي مهجة الذئب والنحرا)\n(فأذهب غيظي قتله وشفى جوى ... بقلبي إن الحر قد يدرك الوترا)\nال أبو نصر بلغ المجنون قبل توحشه أن زوج ليلى ذكره وعضهه وسبه وقال أو بلغ من قدر قيس بن الملوح أن يدعي محبة ليلى وينوه باسمها فقال ليغيظه بذلك\n(فإن كان فيكم بعل ليلى فإنني ... وذي العرش قد قبلت فاها ثمانيا)\n(وأشهد عند الله أني رأيتها ... وعشرون منها أصبعا من ورائيا)\n(أليس من البلوى التي لا شوى لها ... بأن زوجت كلبا وما بذلت ليا)\nخبرني الحسن بن علي قال حدثنا عبد الله بن عمرو بن أبي سعد قال حدثنا علي بن الصباح عن ابن الكلبي قال خرج المجنون في عدة من قومه يريدون سفرا لهم فمروا في طريق يتشعب وجهتين إحداهما ينزلها رهط ليلى وفيها زيادة مرحلة فسألهم أن يعدلوا معه إلى تلك الوجهة فأبوا فمضى وحده وقال صوت\n(أأترك ليلى ليس بيني وبينها ... سوى ليلة إني إذا لصبور)\n(هبوني امرأ منكم أضل بعيره ... له ذمة إن الذمام كبير)\n(وللصاحب المتروك أعظم حرمة ... على صاحب من أن يضل بعير)\n(عفا الله عن ليلىالغداة فإنها ... إذا وليت حكما علي تجور)\nلغناء لابن سريج خفيف رمل بالوسطى عن عمرو وفيه للغريض ثاني ثقيل بالوسطى عن حبش وفيه لابن المارقي خفيف ثقيل عن الهشامي وفيه لعلويه رمل بالبنصر وذكر عمرو بن أبي عمرو الشيباني عن أبيه أن المجنون كان ذات ليلة جالسا مع أصحاب له من بني عمه وهو وله يتلظى ويتململ وهم يعظونه\nويحادثونه حتى هتفت حمامة من سرحة كانت بإزائهم فوثب قائما وقال صوت\n(لقد غردت في جنح ليل حمامة ... على إلفها تبكي وإني لنائم)\n(كذبت وبيت الله لو كنت عاشقا ... لما سبقتني بالبكاء الحمائم)\nم بكى حتى سقط على وجهه مغشيا عليه فما أفاق حتى حميت الشمس عليه من غد الغناء في هذين البيتين لعبد الله بن ذحمان ثقيل أول مطلق في مجرى الوسطى وذكر أبو نصر عن أصحابه أن رجلا مر بالمجنون وهو برمل يبرين يخطط فيه فوقف عليه متعجبا منه وكان لا يعرفه فقال له ما بك يا أخي فرفع رأسه إليه وأنشأ يقول\n(بي اليأس والداء الهيام أصابني ... فإياك عني لايكن بك ما بيا)\n(كان جفون العين تهمي دموعها ... غداةرأت أظعان ليلى غواديا)\n(غروب أمرتها نواضح بزل ... على عجل عجم يروين صاديا)","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":22,"spl":"مرض المجنون ولم تعده ليلى"},
{"id":"b7-31","bab":"الجزء 2","sec":"مرض المجنون ولم تعده ليلى","page":"ج2 ص66","text":"قال خالد بن جمل ذكر حماد الرواية أن نفرا من أهل اليمن مروا بالمجنون فوقفوا ينظرون إليه فأنشأ يقول\n(ألا أيها الركب اليمانون عرجوا ... علينا فقد أمسى هوانا يمانيا)\n(نسائلكم هل سال نعمان بعدنا ... وحب إلينا بطن نعمان واديا)\nيقول في هذه القصيدة صوت\n(ألا يا حمامي قصر ودان هجتما ... علي الهوى لما تغنيتما ليا)\n(فأبكيتماني وسط صحبي ولم أكن ... أبالي دموع العين لو كنت خاليا)\nنى في هذين البيتين علويه غناء لم ينسب\n(فوالله إني لا أحب لغير أن ... تحل بها ليلى البراق الأعاليا)\n(ألا يا خليلي حب ليلى مجشمي ... حياض المنايا أو مقيدي الأعاديا)\n(ويا أيها القمريتان تجاوبا ... بلحنيكما ثم اسجعا عللا نيا)\n(فإن أنتما استطربتما وأردتما ... لحاقا بأطراف الغضى فاتبعانيا)","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":23,"spl":"مرض المجنون ولم تعده ليلى"},
{"id":"b7-32","bab":"الجزء 2","sec":"نشيج العاشقين","page":"ج2 ص71","text":"قال أبو نصر وذكر خالد بن كلثوم أن زوج ليلى لما أراد الرحيل بها إلى بلده\nبلغ المجنون أنه غاد بها فقال صوت\n(أمزمعة للبين ليلى ولم تمت ... كأنك عما قد أظلك غافل)\n(ستعلم إن شطت بهم غربة النوى ... وزالوا بليلى أن لبك زائل)\nالغناء للزبير بن دحمان ثقيل بالوسطى قال أبو نصر قال خالد وحدثني جماعة من بني قشير أن المجنون سقم سقاما شديدا قبل اختلاطه حتى أشفى على الهلاك فدخل إليه أبوه يعلله فوجده ينشد هذه الأبيات ويبكي أحر بكاء وينشج أحر نشيج\n(ألا أيها القلب الذي لج هائما ... بليلى وليدا لم يقطع تمائمه)\n(أفق قد أفاق العاشقون وقد أني ... لحالك أن تلقى طبيبا تلائمه)\n(فمالك مسلوب العزاء كأنما ... ترى نأي ليلى مغرما أنت غارمه)\n(أجدك لا تنسيك ليلى ملمة ... تلم ولا ينسيك عهدا تقادمه)\nال ووقف مستترا ينظر إلى أظعان ليلى وقد رحل بها زوجها وقومها فلما رآهم يرتحلون بكى وجزع فقال له أبوه ويحك إنما جئنا بك متخفيا ليتروح بعض ما بك بالنظر إليهم فإذا فعلت ما أرى عرفت وقد أهدر السلطان دمك إن مررت بهم فأمسك أو فانصرف فقال مالي سبيل إلى النظر إليهم يرتحلون وأنا ساكن غير جازع ولا باك فانصرف بنا فانصرف وهو يقول صوت\n(ذد الدمع حتى يظعن الحي إنما ... دموعك إن فاضت عليك دليل)\n(كأن دموع العين يوم تحملوا ... جمان على جيب القميص يسيل)\nخبرني محمد بن خلف بن المرزبان قال أنشدني إسحاق بن محمد عن بعض أصحابه عن ابن الأعرابي للمجنون صوت\n(ألا ليت ليلى أطفأت حر زفرة ... أعالجها لا أستطيع لها ردا)\n(إذا الريح من نحو الحمى نسمت لنا ... وجدت لمسراها ومنسمها بردا)\n(على كبد قد كاد يبدي بها الهوى ... ندوبا وبعض القوم يحسبني جلدا)\nهذا البيت الثالث خاصة يروى لابن هرمة في بعض قصائده وهو من المائة المختارة التي رواها إسحاق أوله\n(أفاطم إن النأي يسلي من الهوى ... )\nقد أخرج في موضع آخر غنى في هذين البيتين عبد آل الهذلي ولحنه المختار على ما ذكره جحظة ثاني ثقيل وهما في هذه القصيدة\n(وإني يماني الهوى منجد النوى ... سبيلان ألقى من خلافهما جهدا)\n(سقى الله نجدا من ربيع وصيف ... وماذا يرجى من ربيع سقى نجدا)\n(بلى إنه قد كان للعيش قرة ... وللصحب والركبان منزلة حمدا)\n(أبى القلب أن ينفك من ذكر نسوة ... رقاق ولم يخلقن شؤما ولا نكدا)\n(إذا رحن يسحبن الذيول عشية ... ويقتلن بالألحاظ أنفسنا عمدا)\n(مشى عيطلات رجح بخصورها ... روادف وعثات ترد الخطا ردا)\n(وتهتز ليلى العامرية فوقها ... ولاثت بسب القز ذا غدر جعدا)\n(إذا حرك المدرى ضفائرها العلا ... مججن ندى الريحان والعنبر الوردا)\nأخبار الهذليين تذكر في غير هذا الموضع إن شاء الله لئلا تنقطع أخبار المجنون ولهما في المائة الصوت المختارة أغان تذكر أخبارها معا إن شاء الله أخبرني أحمد بن جعفر جحظة قال حدثني ميمون بن هارون قال ذكر الهيثم بن عدي وأخبرني محمد بن خلف بن المرزبان عن أحمد بن الهيثم عن العمري عن الهيثم بن عدي قال مر المجنون برجلين قد صادا ظبية فربطاها بحبل وذهبا بها فلما نظر إليها وهي تركض في حبالهما دمعت عيناه وقال لهما حلاها وخذا مكانها شاة من غنمي وقال ميمون في خبره وخذا مكانها قلوصا من إبلي فأعطاهما وحلاها فولت تعدو هاربة وقال المجنون للرجلين حين رآها في حبالهما\n(يا صاحبي اللذين اليوم قد أخذا ... في الحبل شبها لليلى ثم غلاها)\n(إني أرى اليوم في أعطاف شاتكما ... مشابها أشبهت ليلى فحلاها قال وقال فيها وقد نظر إليها وهي تعدو أشد عدو هاربة مذعورة)\n(أيا شبه ليلى لا تراعي فإنني ... لك اليوم من وحشية لصديق)\n(ويا شبه ليلى لو تلبثت ساعة ... لعل فؤادي من جواه يفيق)\n(تفر وقد أطلقتها من وثاقها ... فأنت لليلى لو علمت طليق)","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":24,"spl":"نشيج العاشقين","partial":1},
{"id":"b7-33","bab":"الجزء 2","sec":"قمر توسط جنح ليل مبرد","page":"ج2 ص75","text":"وذكر أبو نصر عن جماعة من الرواة وذكر أبو مسلم ومحمد بن الحسن الأحول أن ابن الأعرابي أخبرهما أن نسوة جلسن إلى المجنون فقلن له ما الذي دعاك إلى أن أحللت بنفسك ما ترى في هوى ليلى وإنما هي امرأة من النساء هل لك في أن تصرف هواك عنها إلى إحدانا فنساعفك ونجزيك بهواك ويرجع إليك ما عزب من عقلك وجسمك فقال لهن لو قدرت على صرف الهوى عنها إليكن لصرفته عنها وعن كل أحد بعدها وعشت في الناس سويا مستريحا فقلن له ما أعجبك منها فقال كل شيء رأيته وشاهدته وسمعته منها أعجبني والله ما رأيت شيئا منها قط إلا كان في عيني حسنا وبقلبي علقا ولقد جهدت أن يقبح منها عندي شيء أو يسمج أو يعاب لأسلو عنها فلم أجده فقلن له فصفها لنا فأنشأ يقول\n(بيضاء خالصة البياض كأنها ... قمر توسط جنح ليل مبرد)\n(موسومة بالحسن ذات حواسد ... إن الجمال مظنة للحسد)\n(وترى مدامعها ترقرق مقلة ... سوداء ترغب عن سواد الأثمد)\n(خود إذا كثر الكلام تعوذت ... بحمى الحياء وإن تكلم تقصد)\n(إذا رحن يسحبن الذيول عشية ... ويقتلن بالألحاظ أنفسنا عمدا)\n(مشى عيطلات رجح بخصورها ... روادف وعثات ترد الخطا ردا)\n(وتهتز ليلى العامرية فوقها ... ولاثت بسب القز ذا غدر جعدا)\n(إذا حرك المدرى ضفائرها العلا ... مججن ندى الريحان والعنبر الوردا)\nأخبار الهذليين تذكر في غير هذا الموضع إن شاء الله لئلا تنقطع أخبار المجنون ولهما في المائة الصوت المختارة أغان تذكر أخبارها معا إن شاء الله أخبرني أحمد بن جعفر جحظة قال حدثني ميمون بن هارون قال ذكر الهيثم بن عدي وأخبرني محمد بن خلف بن المرزبان عن أحمد بن الهيثم عن العمري عن الهيثم بن عدي قال مر المجنون برجلين قد صادا ظبية فربطاها بحبل وذهبا بها فلما نظر إليها وهي تركض في حبالهما دمعت عيناه وقال لهما حلاها وخذا مكانها شاة من غنمي وقال ميمون في خبره وخذا مكانها قلوصا من إبلي فأعطاهما وحلاها فولت تعدو هاربة وقال المجنون للرجلين حين رآها في حبالهما\n(يا صاحبي اللذين اليوم قد أخذا ... في الحبل شبها لليلى ثم غلاها)\n(إني أرى اليوم في أعطاف شاتكما ... مشابها أشبهت ليلى فحلاها قال وقال فيها وقد نظر إليها وهي تعدو أشد عدو هاربة مذعورة)\nقال ثم قال ابن الأعرابي هذا والله من حسن الكلام ومنقح الشعر وأنشد أبو نصر للمجنون أيضا وفيه غناء قال\n(كأن فؤادي في مخالب طائر ... إذا ذكرت ليلى يشد بها قبضا)\n(كأن فجاج الأرض حلقة خاتم ... علي فما تزداد طولا ولا عرضا)\nخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا أبو مسلم عن القحذمي قال قال رجل من عشيرة المجنون له إني أريد الإلمام بحي ليلى فهل تودعني إليها شيئا فقال نعم قف بحيث تسمعك ثم قل صوت\n(الله يعلم أن النفس هالكة ... باليأس منك ولكني أعنيها)\n(منيتك النفس حتى قد أضر بها ... واستيقنت خلفا مما أمنيها)\n(وساعة منك ألهوها وإن قصرت ... أشهى إلي من الدنيا وما فيها)\nقال فمضى الرجل ولم يزل يرقب خلوة حتى وجدها فوقف عليها ثم قال لها يا ليلى لقد أحسن الذي يقول\n(الله يعلم أن النفس هالكة ... باليأس منك ولكني أعنيها)\nوأنشد الأبيات فبكت بكاء طويلا ثم قالت أبلغه السلام وقل له\n(نفسي فداؤك لو نفسي ملكت إذا ... ما كان غيرك يجزيها ويرضيها)\n(صبرا على ما قضاه الله فيك على ... مرارة في اصطباري عنك أخفيها)\nقال فأبلغه الفتى البيتين وأخبره بحالها فبكى حتى سقط على وجهه مغشيا عليه ثم أفاق وهو يقول\n(عجبت لعروة العذري أضحى ... أحاديثا لقوم بعد قوم)\n(وعروة مات موتا مستريحا ... وها أنا ميت في كل يوم)\nخبرنا محمد بن يحيى الصولي قال أنشدنا أحمد بن يحيى ثعلب عن أبي نصر للمجنون صوت\n(أيا زينة الدنيا التي لا ينالها ... مناي ولا يبدو لقلبي صريمها)\n(بعيني قذاة من هواك لو أنها ... تداوى بمن تهوى لصح سقيمها)\n(وما صبرت عن ذكرك النفس ساعة ... وإن كنت أحيانا كثيرا ألومها)","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":25,"spl":"قمر توسط جنح ليل مبرد"},
{"id":"b7-34","bab":"الجزء 2","sec":"قمر توسط جنح ليل مبرد","page":"ج2 ص75","text":"خبرني الحسن بن علي قال حدثنا عبد الله بن أبي سعد قال حدثنا علي بن الصباح عن ابن الكلبي قال سأل الملوح أبو المجنون رجلا قدم من الطائف أن يمر بالمجنون فيجلس إليه فيخبره أنه لقي ليلى وجلس إليها ووصف له صفات منها ومن كلامها يعرفها المجنون وقال له حدثه بها فإذا رأيته قد اشرأب لحديثك واشتهاه فعرفه أنك ذكرته لها ووصفت ما به فشتمته وسبته وقالت إنه يكذب عليها ويشهرها بفعله وإنها ما اجتمعت معه قط كما يصف ففعل الرجل ذلك وجاء إليه فأخبره بلقائه إياها فأقبل عليه وجعل يسائله عنها فيخبره بما أمره به الملوح فيزداد نشاطا ويثوب إليه عقله إلى أن أخبره بسبها إياها وشتمها له فقال وهو غير مكترث لما حكاه عنها\nصوت\n(تمر الصبا صفحا بساكن ذي الغضى ... ويصدع قلبي أن يهب هبوبها)\n(إذا هبت الريح الشمال فإنما ... جواي بما تهدى إلي جنوبها)\n(قريبة عهد بالحبيب وإنما ... هوى كل نفس حيث كان حبيبها)\n(وحسب الليالي أن طرحنك مطرحا ... بدار قلى تمسي وأنت غريبها)\nحلال لليلى شتمنا وانتقصنا ... هنيئا ومغفور لليلى ذنوبها ذكر أبو أيوب المديني أن الغناء في هذا الشعر لابن سريج ولم يذكر طريقته وفيه لمتيم غناء ينسب وذكر الهيثم بن عدي أن المجنون قال وفيه غناء صوت\n(كأن لم تكن ليلى تزار بذي الأثل ... وبالجزع من أجزاع ودان فالنخل)\n(صديق لنا فيما نرى غير أنها ... ترى أن حبي قد أحل لها قتلي)","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":26,"spl":"قمر توسط جنح ليل مبرد — تبكي وتقول أنا ليلى"},
{"id":"b7-35","bab":"الجزء 2","sec":"تبكي وتقول أنا ليلى","page":"ج2 ص79","text":"أخبرني عمي قال حدثنا الكراني قال حدثنا العمري عن الهيثم بن عدي عن عثمان بن عمارة بن حريم عن أشياخ من بني مرة قالوا خرج منا رجل إلى ناحية الشام والحجاز وما يلي تيماء والسراة وأرض نجد في طلب بغية له فإذا هو بخيمة قد رفعت له وقد أصابه المطر فعدل إليها وتنحنح فإذا امرأة قد كلمته فقالت انزل فنزل قال وراحت إبلهم وغنمهم فإذا أمر عظيم فقالت سلوا هذا الرجل من أين أقبل فقلت من ناحية تهامة ونجد فقالت ادخل أيها الرجل فدخلت إلى ناحية من الخيمة فأرخت بيني وبينها سترا ثم قالت لي يا عبد الله أي بلاد نجد وطئت فقلت كلها قالت فبمن نزلت هناك قلت ببني عامر فتنفست الصعداء ثم قالت فبأي بني عامر نزلت فقلت بني الحريش فاستعبرت ثم قالت فهل سمعت بذكر فتى منهم يقال له قيس بن الملوح ويلقب بالمجنون قلت بلى والله وعلى أبيه نزلت وأتيته فنظرت إليه يهيم في تلك الفيافي ويكون مع الوحش لا يعقل ولا يفهم إلا أن تذكر له امرأة يقال لها ليلى فيبكي وينشد أشعارا قالها فيها قال فرفعت الستر بيني وبينها فإذا فلقة قمر لم ترعيني مثلها فبكت حتى ظننت والله أن قلبها قد انصدع فقلت أيتها المرأة اتقي الله فما قلت بأسا فمكثت طويلا على تلك الحال من البكاء والنحيب ثم قالت\n(ألا ليت شعري والخطوب كثيرة ... متى رحل قيس مستقل فراجع)\n(بنفسي من لا يستقل برحله ... ومن هو إن لم يحفظ الله ضائع)\nثم بكت حتى سقطت مغشيا عليها فقلت لها من أنت يا أمة الله وما قصتك قالت أنا ليلى صاحبته المشؤومة والله عليه غير المؤنسة له فما رأيت مثل حزنها ووجدها عليه قط","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":26,"spl":"قمر توسط جنح ليل مبرد — تبكي وتقول أنا ليلى"},
{"id":"b7-36","bab":"الجزء 2","sec":"نهاية عاشق","page":"ج2 ص80","text":"أخبرني أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة قال ذكر الهيثم بن عدي عن عثمان بن عمارة وأخبرني عثمان عن الكراني عن العمري عن لقيط وحدثنا إبراهيم بن أيوب عن عبد الله بن مسلم قال ذكر الهيثم بن عدي عن عثمان بن عمارة وذكر أبو نصر أحمد بن حاتم صاحب الأصمعي وأبو مسلم المستملي عن ابن الأعرابي يزيد بعضهم على بعض أن عثمان بن عمارة المري أخبرهم أن شيخا منهم من بني مرة حدثه أنه خرج إلى أرض بني عامر ليلقى المجنون قال فدللت على محلته فأتيتها فإذا أبوه شيخ كبير وإخوة له رجال وإذا نعم كثير وخير ظاهر فسألتهم عنه فاستعبروا جميعا وقال الشيخ والله لهو كان آثر في نفسي من هؤلاء وأحبهم إلي وإنه هوي امرأة من قومه والله ما كانت تطمع في مثله فلما أن فشا أمره وامرها كره أبوها أن يزوجها منه بعد ظهور الخبر فزوجها من غيره فذهب عقل ابني ولحقه خبل وهام في الفيافي وجدا عليها فحبسناه وقيدناه فجعل يعض لسانه وشفتيه حتى خفنا عليه أن يقطعها فخلينا سبيله فهو يهيم في هذه الفيافي مع الوحوش يذهب إليه كل يوم بطعامه فيوضع له حيث يراه فإذا تنحوا عنه جاء فأكل منه قال فسألتهم أن يدلوني عليه فدلوني على فتى من الحي كان صديقا له وقالوا إنه لا يأنس إلا به ولا يأخذ أشعاره عنه غيره فأتيته فسألته أن يدلني عليه فقال إن كنت تريد شعره فكل شعر إلى أمس عندي وأنا ذاهب إليه غدا فإن كان قال شيئا أتيتك به فقلت بل أريد أن تدلني عليه لآتيه فقال\nلي إنه إن نفر منك نفر مني فيذهب شعره فأبيت إلا أن يدلني عليه فقال اطلبه في هذه الصحارى فإذا رأيته فادن منه مستأنسا ولا تره أنك تهابه فإنه يتهددك ويتوعدك أن يرميك بشيء فلا يروعنك واجلس صارفا بصرك عنه والحظه أحيانا فإذا رأيته قد سكن من نفاره فأنشده شعرا غزلا وإن كنت تروي من شعر قيس بن ذريح شيئا فأنشده إياه فإنه معجب به فخرجت فطلبته يومي إلى العصر فوجدته جالسا على رمل قد خط فيه بأصبعه خطوطا فدنوت منه غير منقبض فنفر مني نفور الوحش من الإنس وإلى جانبه أحجار فتناول حجرا فأعرضت عنه فمكث ساعة كأنه نافر يريد القيام فلما طال جلوسي سكن وأقبل يخط بأصبعه فأقبلت عليه وقلت أحسن والله قيس بن ذريح حيث يقول\n(ألا يا غراب البين ويحك نبني ... بعلمك في لبنى وأنت خبير)\n(فإن أنت لم تخبر بشيء علمته ... فلا طرت إلا والجناح كسير)\n(ودرت بأعداد حبيبك فيهم ... كما قد تراني بالحبيب أدور)\nفأقبل علي وهو يبكي فقال أحسن والله وأنا أحسن منه قولا حيث أقول\n(كأن القلب ليلة قيل يغدى ... بليلى العامرية أو يراح)\n(قطاة عزها شرك فباتت ... تجاذبه وقد علق الجناح)\nفأمسكت عنه هنيهة ثم أقبلت عليه فقلت وأحسن والله قيس بن ذريح حيث يقول\n(وإني لمفن دمع عيني بالبكا ... حذارا لما قد كان أو هو كائن)\n(وقالوا غدا أو بعد ذاك بليلة ... فراق حبيب لم يبن وهو بائن)\n(وما كنت أخشى أن تكون منيتي ... بكفيك إلا أن من حان حائن)\nقال فبكى والله حتى ظننت أن نفسه قد فاضت وقد رأيت دموعه قد بلت الرمل الذي بين يديه ثم قال أحسن لعمر الله وأنا والله أشعر منه حيث أقول صوت\n(وأدنيتني حتى إذا ما سبيتني ... بقول يحل العصم سهل الأباطح)\n(تناءيت عني حين لا لي حيلة ... وخلفت ما خلفت بين الجوانح)\nيروى وغادرت ما غادرت ثم سنحت له ظبية فوثب يعدو خلفها حتى غاب عني وانصرفت وعدت من غد فطلبته فلم أجده وجاءت امرأة كانت تصنع له طعامه إلى الطعام فوجدته بحاله فلما كان في اليوم الثالث غدوت وجاء أهله معي فطلبناه يومنا فلم نجده وغدونا في اليوم الرابع نستقري أثره حتى وجدناه في واد كثير الحجارة خشن وهو ميت بين تلك الحجارة فاحتمله أهله فغسلوه وكفنوه ودفنوه","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":27,"spl":"نهاية عاشق"},
{"id":"b7-37","bab":"الجزء 2","sec":"ما علمنا أن الأمر يبلغ كل هذا","page":"ج2 ص82","text":"قال الهيثم فحدثني جماعة من بني عامر أنه لم تبق فتاة من بني جعدة ولا بني الحريش إلا خرجت حاسرة صارخة عليه تندبه واجتمع فتيان الحي يبكون عليه أحر بكاء وينشجون عليه أشد نشيج وحضرهم حي ليلى معزين وأبوها معهم فكان أشد القوم جزعا وبكاء عليه وجعل يقول ما علمنا أن الأمر يبلغ كل\nهذا ولكني كنت امرأ عربيا أخاف من العار وقبح الأحدوثة ما يخافه مثلي فزوجتها وخرجت عن يدي ولو علمت أن أمره يجري على هذا ما أخرجتها عن يده ولا احتملت ما كان علي في ذلك قال فما رئي يوم كان أكثر باكية وباكيا على ميت من يومئذ","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":28,"spl":"ما علمنا أن الأمر يبلغ كل هذا — نسبة ما في هذا الخبر من الأغاني"},
{"id":"b7-38","bab":"الجزء 2","sec":"نسبة ما في هذا الخبر من الأغاني","page":"ج2 ص83","text":"منها الصوت الذي أوله\n(ألا يا غراب البين ويحك نبني ... بعلمك في لبنى وأنت خبير)\nلغناء لابن محرز ثقيل أول بالوسطى عن الهشامي وذكر إبراهيم أن فيه لحنا لحكم وفي رواية ابن الأعرابي أنه أنشده مكان\n(ألا يا غراب البين ويحك نبني ... بعلمك في لبنى وأنت خبير)\nصوت\n(ألا يا غراب البين هل أنت مخبري ... بخير كما خبرت بالنأي والشر)\n(وخبرت أن قد جد بين وقربوا ... جمالا لبين مثقلات من الغدر)\n(وهجت قذى عين بلبنى مريضة ... إذا ذكرت فاضت مدامعها تجري)\n(وقلت كذاك الدهر ما زال فاجعا ... صدقت وهل شيء بباق على الدهر)\nلشعر لقيس بن ذريح والغناء لابن جامع ثقيل أول بالسبابة في مجرى البنصر عن إسحاق وفيه لبحر ثقيل أول بالوسطى عن عمرو وفيه لدحمان ثاني ثقيل عن الهشامي وعبد الله بن موسى\nومنها صوت الذي أوله\n(كأن القلب ليلة قيل يغدى ... بليلى العامرية أو يراح)\nمنها الصوت الذي أوله\n(وأدنيتني حتى إذا ما سبيتني ... بقول يحل العصم سهل الأباطح)\nالغناء لإبراهيم خفيف ثقيل بالوسطى عن الهشامي أخبرنا الحسين بن القاسم الكوكبي قال حدثنا الفضل الربعي عن محمد بن حبيب قال لما مات مجنون بني عامر وجد في أرض خشنة بين حجارة سود فحضر أهله وحضر معهم أبو ليلى المرأة التي كان يهواها وهو متذمم من أهله فلما رآه ميتا بكى واسترجع وعلم أنه قد شرك في هلاكه فبينما هم يقلبونه إذ وجدوا خرقة فيها مكتوب\n(ألا أيها الشيخ الذي ما بنا يرضى ... شقيت ولا هنيت من عيشك الغضا)\n(شقيت كما أشقيتني وتركتني ... أهيم مع الهلاك لا أطعم الغمضا)\nوت\n(كأن فؤادي في مخالب طائر ... إذا ذكرت ليلى يشد بها قبضا)\n(كأن فجاج الأرض حلقة خاتم ... علي فما تزداد طولا ولا عرضا)\nي هذين البيتين رمل ينسب إلى سليم وإلى ابن محرز وذكر حبش والهشامي أنه لإسحاق أخبرني محمد بن خلف قال حدثني أبو سعيد السكري عن محمد ابن\nحبيب قال حدثني بعض القشيريين عن أبيه قال مررت بالمجنون وهو مشرف على واد في أيام الربيع وذاك قبل أن يختلط وهو يتغنى بشعر لم أفهمه فصحت به يا قيس أما تشغلك ليلى عن الغناء والطرب فتنفس تنفسا ظننت أن حيازيمه قد انقدت ثم قال صوت\n(وما أشرف الأيفاع إلا صبابة ... ولا أنشد الأشعار إلا تداويا)\n(وقد يجمع الله الشتيتين بعدما ... يظنان جهد الظن أن لا تلاقيا)\n(لحى الله أقواما يقولون إنني ... وجدت طوال الدهر للحب شافيا)","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":28,"spl":"ما علمنا أن الأمر يبلغ كل هذا — نسبة ما في هذا الخبر من الأغاني"},
{"id":"b7-39","bab":"الجزء 2","sec":"والتقى القيسان ابن الملوح وابن ذريح","page":"ج2 ص85","text":"أخبرني محمد بن مزيد قال حدثنا الزبير بن بكار قال حدثنا إسماعيل بن أبي أويس قال اجتاز قيس بن ذريح بالمجنون وهو جالس وحده في نادي قومه وكان كل واحد منهما مشتاقا إلى لقاء الآخر وكان المجنون قبل توحشه لا يجلس إلا منفردا ولا يحدث أحدا ولا يرد على متكلم جوابا ولا على مسلم سلاما فسلم عليه قيس بن ذريح فلم يرد عليه السلام فقال له يا أخي أنا قيس بن ذريح فوثب إليه فعانقه وقال مرحبا بك يا أخي أنا والله مذهوب بي مشترك اللب فلا تلمني فتحدثا ساعة وتشاكيا وبكيا ثم قال له المجنون يا أخي إن حي ليلى منا قريب فهل لك أن تمضي إليها فتبلغها عني السلام فقال له أفعل فمضى قيس بن ذريح حتى أتى ليلى فسلم وانتسب فقالت له حياك الله ألك\nحاجة قال نعم ابن عمك أرسلني إليك بالسلام فأطرقت ثم قالت ما كنت أهلا للتحية لو علمت أنك رسوله قل له عني أرأيت قولك\n(أبت ليلة بالغيل يا أم مالك ... لكم غير حب صادق ليس يكذب)\n(ألا إنما أبقيت يا أم مالك ... صدى أينما تذهب به الريح يذهب)\nخبرني عن ليلة الغيل أي ليلة هي وهل خلوت معك في الغيل أو غيره ليلا أو نهارا فقال لها قيس يا ابنة عم إن الناس تأولوا كلامه على غير ما أراد فلا تكوني مثلهم إنما أخبر أنه رآك ليلة الغيل فذهبت بقلبه لا أنه عناك بسوء قال فأطرقت طويلا ودموعها تجري وهي تكفكفها ثم انتحبت حتى قلت تقطعت حيازيمها ثم قالت اقرأ على ابن عمي السلام وقل له بنفسي أنت والله إن وجدي بك لفوق ما تجد ولكن لا حيلة لي فيك فانصرف قيس إليه ليخبره فلم يجده أخبرني الحسن بن علي قال حدثني محمد بن القاسم بن مهرويه قال حدثني عمي عن ابن الصباح عن ابن الكلبي عن أبيه قال مر المجنون بعد اختلاطه بليلى وهي تمشي في ظاهر البيوت بعد فقد لها طويل فلما رآها بكى حتى سقط على وجهه مغشيا عليه فانصرفت خوفا من أهلها أن يلقوها عنده فمكث كذلك مليا ثم أفاق وأنشأ يقول\n(بكى فرحا بليلى إذ رآها ... محب لا يرى حسنا سواها)\n(لقد ظفرت يداه ونال ملكا ... لئن كانت تراه كما يراها)\nلغناء لابن المكي رمل بالبنصر وفيه لعريب ثقيل أول عن الهشامي وفيه خفيف رمل ليزيد حوراء وقد نسب لحنه إلى ابن المكي ولحن ابن المكي إليه صوت","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":29,"spl":"والتقى القيسان ابن الملوح وابن ذريح — من المائة المختارة من رواية علي بن يحيى"},
{"id":"b7-40","bab":"الجزء 2","sec":"من المائة المختارة من رواية علي بن يحيى","page":"ج2 ص87","text":"(رب ركب قد أناخوا عندنا ... يشربون الخمر بالماء الزلال)\n(عصف الدهر بهم فانقرضوا ... وكذاك الدهر حالا بعد حال)\nلشعر لعدي بن زيد العبادي والغناء لابن محرز ولحنه المختار خفيف رمل بإطلاق الوتر في مجرى الوسطى عن إسحاق وفيه خفيف رمل آخر بالبنصر ابتداؤه نشيد ذكر عمرو بن بانة أنه لابن طنبورة وذكر أحمد بن المكي أنه لأبيه وهذه الأبيات قالها عدي بن زيد العبادي على سبيل الموعظة للنعمان بن المنذر فيقال إنها كانت سبب دخوله في النصرانية حدثني بذلك أحمد بن عمران المؤدب قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا عبد الله بن عمرو قال حدثني علي بن الصباح عن ابن الكلبي قال خرج النعمان بن المنذر إلى الصيد ومعه عدي بن زيد فمروا بشجرة فقال له عدي بن زيد أيها الملك أتدري ما تقول هذه الشجرة قال\nلا قال تقول\n(رب ركب قد أناخوا عندنا ... يشربون الخمر بالماء الزلال)\n(عصف الدهر بهم فانقرضوا ... وكذاك الدهر حالا بعد حال)\nقال ثم جاوز الشجرة فمر بمقبرة فقال له عدي أيها الملك أتدري ما تقول هذه المقبرة قال لا قال تقول\n(أيها الركب المخبون ... على الأرض المجدون)\n(فكما أنتم كنا ... وكما نحن تكونون)\nفقال له النعمان إن الشجرة والمقبرة لا يتكلمان وقد علمت أنك إنما أردت عظتي فما السبيل التي تدرك بها النجاة قال تدع عبادة الأوثان وتعبد الله وتدين بدين المسيح عيسى بن مريم قال أوفي هذا النجاة قال نعم فتنصر يومئذ وقد قيل إن هذه القصة كانت لعدي مع النعمان الأكبر بن المنذر وإن النعمان الذي قتله هو ابن المنذر بن النعمان الأكبر الذي تنصر وخبر هذا يأتي مع أحاديث عدي","topic":"أخبار مجنون بني عامر ونسبه","topicNo":7,"sp":29,"spl":"والتقى القيسان ابن الملوح وابن ذريح — من المائة المختارة من رواية علي بن يحيى"},
{"id":"b8-1","bab":"الجزء 2","sec":"ذكر عدى بن زيد ونسبه وقصته ومقتله","page":"ج2 ص89","text":"هو عدي بن زيد بن حماد بن زيد بن أيوب بن محروف بن عامر بن عصية بن امرىء القيس بن زيد مناة بن تميم بن مر بن أد بن طابخة بن إلياس بن مضر بن نزار وكان أيوب هذا فيما زعم ابن الأعرابي أول من سمي من العرب أيوب شاعر فصيح من شعراء الجاهلية وكان نصرانيا وكذلك كان أبوه وأمه وأهله وليس ممن يعد في الفحول وهو قروي وكانوا قد أخذوا عليه أشياء عيب فيها وكان الأصمعي وأبو عبيدة يقولان عدي بن زيد في الشعراء بمنزلة سهيل في النجوم يعارضها ولا يجري معها مجراها وكذلك عندهم أمية بن أبي الصلت ومثلهما كان عندهم من الإسلاميين الكميت والطرماح قال العجاج كانا يسألاني عن الغريب فأخبرهما به ثم أراه في شعرهما وقد وضعاه\nفي غير مواضعه فقيل له ولم ذاك قال لأنهما قرويان يصفان ما لم يريا فيضعانه في غير موضعه وأنا بدوي أصف ما رأيت فأضعه في مواضعه وكذلك عندهم عدي وأمية","topic":"ذكر عدى بن زيد ونسبه وقصته ومقتله","topicNo":8,"sp":0,"spl":"ذكر عدى بن زيد ونسبه وقصته ومقتله — آل عدي في الحيرة"},
{"id":"b8-2","bab":"الجزء 2","sec":"آل عدي في الحيرة","page":"ج2 ص90","text":"قال ابن الأعرابي فيما أخبرني به علي بن سليمان الأخفش عن السكري عن محمد بن حبيب عنه وعن هشام بن الكلبي عن أبيه قال سبب نزول آل عدي بن زيد الحيرة أن جده أيوب بن محروف كان منزله اليمامة في بني امرىء القيس بن زيد مناة فأصاب دما في قومه فهرب فلحق بلبن قلام أحد بني الحارث بن كعب بالحيرة وكان بين أيوب بن محروف وبين أوس بن قلام هذا نسب من قبل النساء فلما قدم عليه أيوب بن محروف أكرمه وأنزله في داره فمكث معه ما شاء الله أن يمكث ثم أن أوسا قال له يا بن خال أتريد المقام عندي وفي داري فقال له أيوب نعم فقد علمت أني أن أتيت قومي وقد أصبت فيهم دما لم أسلم وما لي دار إلا دارك آخر الدهر قال أوس إني إن قد كبرت وأنا خائف أن أموت فلا يعرف ولدي لك من الحق مثل ما أعرف وأخشى أن يقع بينك وبينهم أمر يقطعون فيه الرحم فانظر أحب مكان في الحيرة إليك فأعلمني به لأقطعكه أو أبتاعه لك قال وكان لأيوب صديق في الجانب الشرقي من الحيرة وكان منزل أوس في الجانب الغربي فقال له قد أحببت أن يكون\nالمنزل الذي تسكننيه عند منزل عصام بن عبدة أحد بني الحارث بن كعب فابتاع له موضع داره بثلثمائة أوقية من الذهب وأنفق عليها مائتي أوقية ذهب وأعطاه مائتين من الإبل برعائها وفرسا وقينة فمكث في منزل أوس حتى هلك ثم تحول إلى داره التي في شرقي الحيرة فهلك بها وقد كان أيوب اتصل قبل مهلكه بالملوك الذين كانوا بالحيرة وعرفوا حقه وحق ابنه زيد بن أيوب وثبت أيوب فلم يكن منهم ملك يملك إلا ولولد أيوب منه جوائز وحملان","topic":"ذكر عدى بن زيد ونسبه وقصته ومقتله","topicNo":8,"sp":0,"spl":"ذكر عدى بن زيد ونسبه وقصته ومقتله — آل عدي في الحيرة"},
{"id":"b8-3","bab":"الجزء 2","sec":"مقتل زيد بن أيوب","page":"ج2 ص91","text":"ثم إن زيد بن أيوب نكح امرأة من آل قلام فولدت له حمادا فخرج زيد بن أيوب يوما من الأيام يريد الصيد في ناس من أهل الحيرة وهم منتدون بحفير المكان الذي يذكره عدي بن زيد في شعره فانفرد في الصيد وتباعد من أصحابه فلقيه رجل من بني امرىء القيس الذين كان لهم الثأر قبل أبيه فقال له وقد عرف فيه شبه أيوب ممن الرجل قال من بني تميم قال من أيهم قال مرئي قال له الأعرابي وأين منزلك قال الحيرة قال أمن بني أيوب أنت قال نعم ومن أين تعرف بني أيوب واستوحش من الأعرابي وذكر الثأر الذي هرب أبوه منه فقال له سمعت بهم ولم يعلمه أنه قد عرفه فقال له زيد بن أيوب فمن أي العرب أنت قال أنا امرؤ من طيىء فأمنه زيد وسكت عنه ثم إن الأعرابي اغتفل زيد بن أيوب فرماه بسهم فوضعه بين كتفيه ففلق قلبه فلم يرم حافر دابته حتى مات فلبث أصحاب زيد حتى إذا كان الليل طلبوه وقد افتقدوه وظنوا أنه قد أمعن في طلب الصيد فباتوا يطلبونه حتى يئسوا منه ثم غدوا في طلبه فاقتفوا أثره حتى وقفوا عليه ورأوا معه أثر راكب يسايره فاتبعوا الأثر حتى وجدوه قتيلا فعرفوا أن صاحب الراحلة قتله فاتبعوه وأغدوا السير فأدركوه مساء الليلة الثانية فصاحوا\nبه وكان من أرمى الناس فامتنع منهم بالنبل حتى حال الليل بينهم وبينه وقد أصاب رجلا منهم في مرجع كتفيه بسهم فلما أجنه الليل مات وأفلت الرامي فرجعوا وقد قتل زيد بن أيوب ورجلا آخر معه من بني الحارث بن كعب فمكث حماد في أخواله حتى أيفع ولحق بالوصفاء فخرج يوما من الأيام يلعب مع غلمان بني لحيان فلطم اللحياني عين حماد فشجه حماد فخرج أبو اللحياني فضرب حمادا فأتى حماد أمه يبكي فقالت له ما شأنك فقال ضربني فلان لأن ابنه لطمني فشججته فجزعت من ذلك وحولته إلى دار زيد بن أيوب وعلمته الكتابة في دار أبيه فكان حماد أول من كتب من بنى أيوب فخرج من أكتب الناس وطلب حتى صار كاتب الملك النعمان الأكبر فلبث كاتبا له حتى ولد له ابن من امرأة تزوجها من طيىء فسماه زيدا باسم أبيه وكان لحماد صديق من الدهاقين العظماء يقال له فروخ ماهان وكان محسنا إلى حماد فلما حضرت حمادا الوفاة أوصى بابنه زيد إلى الدهقان وكان من المرازبة فأخذه الدهقان إليه فكان عنده مع ولده وكان زيد قد حذق الكتابة والعربية قبل أن يأخذه الدهقان فعلمه لما أخذه الفارسية فلقنها وكان لبيبا فأشار الدهقان على كسرى أن يجعله على البريد في حوائجه ولم يكن كسرى يفعل ذلك إلا بأولاد المرازبة فمكث يتولى ذلك لكسرى زمانا ثم إن النعمان النصري اللخمي هلك فاختلف أهل الحيرة فيمن يملكونه إلى أن يعقد كسرى الأمر لرجل ينصبه فأشار عليهم المرزبان\nبزيد بن حماد فكان على الحيرة إلى أن ملك كسرى المنذر بن ماء السماء ونكح زيد بن حماد نعمة بنت ثعلبة العدوية فولدت له عديا وملك المنذر وكان لا يعصيه في شيء وولد للمرزبان ابن فسماه شاهان مرد فلما تحرك عدي بن زيد وأيفع طرحه أبوه في الكتاب حتى إذا حذق أرسله المرزبان مع ابنه شاهان مرد إلى كتاب الفارسية فكان يختلف مع ابنه ويتعلم الكتابة والكلام بالفارسية حتى خرج من أفهم الناس بها وأفصحهم بالعربية وقال الشعر وتعلم الرمي بالنشاب فخرج من الأساورة الرماة وتعلم لعب العجم على الخيل بالصوالجة وغيرها ثم إن المرزبان وفد على كسرى ومعه ابنه شاهان مرد فبينما هما واقفان بين يديه إذ سقط طائران على السور فتطاعما كما يتطاعم الذكر والأنثى فجعل كل واحد منقاره في منقار الآخر فغضب كسرى من ذلك ولحقته غيرة فقال للمرزبان وابنه ليرم كل واحد منكما واحدا من هذين الطائرين فإن قتلتماهما أدخلتكما بيت المال وملأت أفواهكما بالجوهر ومن أخطأ منكما عاقبته فاعتمد كل واحد منهما طائرا منهما ورميا فقتلاهما جميعا فبعثهما إلى بيت المال فملئت أفواهما جوهرا وأثبت شاهان مرد وسائر أولاد المرزبان في صحابته فقال فروخ ماهان عند ذلك للملك","topic":"ذكر عدى بن زيد ونسبه وقصته ومقتله","topicNo":8,"sp":1,"spl":"مقتل زيد بن أيوب"},
{"id":"b8-4","bab":"الجزء 2","sec":"عدي كاتب كسرى وموفده إلى ملك الروم","page":"ج2 ص94","text":"إن عندي غلاما من العرب مات أبوه وخلفه في حجري فربيته فهو أفصح الناس وأكتبهم بالعربية والفارسية والملك محتاج إلى مثله فإن رأى أن يثبته في ولدي فعل فقال ادعه فأرسل إلى عدي بن زيد وكان جميل الوجه فائق الحسن وكانت الفرس تتبرك بالجميل الوجه فلما كلمه وجده أظرف الناس وأحضرهم جوابا فرغب فيه وأثبته مع ولد المرزبان فكان عدي أول من كتب بالعربية في ديوان كسرى فرغب أهل الحيرة إلى عدي ورهبوه فلم يزل بالمدائن في ديوان كسرى يؤذن له عليه في الخاصة وهو معجب به قريب منه وأبوه زيد بن حماد يومئذ حي إلا أن ذكر عدي قد ارتفع وخمل ذكر أبيه فكان عدي إذا دخل على المنذر قام جميع من عنده حتى يعقد عدي فعلا له بذاك صيت عظيم فكان إذا أراد المقام بالحيرة في منزله ومع أبيه وأهله استأذن كسرى فأقام فيهم الشهر والشهرين وأكثر وأقل ثم إن كسرى أرسل عدي بن زيد إلى ملك الروم بهدية من طرف ما عنده فلما أتاه عدي بها أكرمه وحمله إلى عماله على البريد ليريه سعة أرضه وعظيم ملكه وكذلك كانوا يصنعون فمن ثم وقع عدي بدمشق وقال فيها الشعر فكان مما قاله بالشأم وهي أول شعر قاله فيما ذكر\n(رب دار بأسفل الجزع من دومة ... أشهى إلي من جيرون)\n(وندامى لا يفرحون بما نالوا ... ولا يرهبون صرف المنون)\n(قد سقيت الشمول في دار بشر ... قهوة مرة بماء سخين)\nثم كان أول ما قاله بعدها قوله\n(لمن الدار تعفت بخيم ... أصبحت غيرها طول القدم)\n(ما تبين العين من آياتها ... غير نؤي مثل خط بالقلم)\n(صالحا قد لفها فاستوسقت ... لف بازي حماما في سلم)\nال وفسد أمر الحيرة وعدي بدمشق حتى أصلح أبوه بينهم لأن أهل الحيرة حين كان عليهم المنذر أرادوا قتله لأنه كان لا يعدل فيهم وكان يأخذ من\nأموالهم ما يعجبه فلما تيقن أن أهل الحيرة قد أجمعوا على قتله بعث إلى زيد بن حماد بن زيد بن أيوب وكان قبله على الحيرة فقال له يا زيد أنت خليفة أبي وقد بلغني ما أجمع عليه أهل الحيرة فلا حاجة لي في ملككم دونكموه ملكوه من شئتم فقال له زيد إن الأمر ليس إلي ولكني أسبر لك هذا الأمر ولا آلوك نصحا فلما أصبح غدا إليه الناس فحيوه تحية الملك وقالوا له ألا تبعث إلى عبدك الظالم يعنون المنذر فتريح منه رعيتك فقال لهم أولا خير من ذلك قالوا أشر علينا قال تدعونه على حاله فإنه من أهل بيت ملك وأنا آتيه فأخبره أن أهل الحيرة قد اختاروا رجلا يكون أمر الحيرة إليه إلا أن يكون غزو أو قتال فلك اسم الملك وليس إليك سوى ذلك من الأمور قالوا رأيك أفضل فأتى المنذر فأخبره بما قالوا فقبل ذلك وفرح وقال إن لك يا زيد علي نعمة لا أكفرها ما عرفت حق سبد وسبد صنم كان لأهل الحيرة فولى أهل الحيرة زيدا على كل شيء سوى اسم الملك فإنهم أقروه للمنذر وفي ذلك يقول عدي\n(نحن كنا قد علمتم قبلكم ... عمد البيت وأوتاد الإصار)\nال ثم هلك زيد وابنه عدي يومئذ بالشأم وكانت لزيد ألف ناقة الحمالات كان أهل الحيرة أعطوه إياها حين ولوه ما ولوه فلما هلك أرادوا أخذها فبلغ ذلك المنذر فقال لا واللات والعزى لا يؤخذ مما كان في يد زيد ثفروق وأنا أسمع الصوت ففي ذلك يقول عدي بن زيد لابنه النعمان بن المنذر\n(وأبوك المرء لم يشنأ به ... يوم سيم الخسف منا ذو الخسار)\nال ثم إن عديا قدم المدائن على كسرى بهدية قيصر فصادف أباه والمرزبان الذي رباه قد هلكا جميعا فاستأذن كسرى في الإلمام بالحيرة فأذن له فتوجه إليها وبلغ المنذر خبره فخرج فتلقاه في الناس ورجع معه وعدي أنبل أهل الحيرة في أنفسهم ولو أراد أن يملكوه لملكوه ولكنه كان يؤثر الصيد واللهو واللعب على الملك فمكث سنين يبدو في فصلي السنة فيقيم في جفير ويشتو بالحيرة ويأتي المدائن في خلال ذلك فيخدم كسرى فمكث كذلك سنين وكان لا يؤثر على بلاد بني يربوع مبدى من مبادي العرب ولا ينزل في حي من أحياء بني تميم غيرهم وكان أخلاؤه من العرب كلهم بني جعفر وكانت إبله في بلاد بني ضبة وبلاد بني سعد و كذلك كان أبوه يفعل لا يجاوز هذين الحيين بإبله ولم يزل على حاله تلك حتى تزوج هند بنت النعمان بن المنذر وهي يومئذ جارية حين بلغت أو كادت وخبره يذكر في تزويجها بعد هذا قال ابن حبيب وذكر هشام بن الكلبي عن إسحاق بن الجصاص وحماد","topic":"ذكر عدى بن زيد ونسبه وقصته ومقتله","topicNo":8,"sp":2,"spl":"عدي كاتب كسرى وموفده إلى ملك الروم"},
{"id":"b8-5","bab":"الجزء 2","sec":"عدي كاتب كسرى وموفده إلى ملك الروم","page":"ج2 ص94","text":"الراوية وأبي محمد بن السائب قال كان لعدي بن زيد أخوان أحدهما اسمه عمار ولقبه أبي والآخر اسمه عمرو ولقبه سمي وكان لهم أخ من أمهم يقال له عدي بن حنظلة من طيىء وكان أبي يكون عند كسرى وكانوا أهل بيت نصارى يكونون مع الأكاسرة ولهم معهم أكل وناحية يقطعونهم القطائع ويجزلون صلاتهم وكان المنذر لما ملك جعل ابنه النعمان بن المنذر في حجر عدي بن زيد فهم الذين أرضعوه وربوه وكان للمنذر ابن آخر يقال له الأسود أمه مارية بنت الحارث بن جلهم من تيم الرباب فأرضعه ورباه قوم من أهل الحيرة يقال لهم بنو مر ينا ينتسبون إلى لخم وكانوا أشرافا وكان للمنذر سوى هذين من الولد عشرة وكان ولده يقال لهم الأشاهب من جمالهم فذلك قول أعشى بن قيس بن ثعلبة\n(وبنو المنذر الأشاهب في الحيرة ... يمشون غدوة كالسيوف)","topic":"ذكر عدى بن زيد ونسبه وقصته ومقتله","topicNo":8,"sp":3,"spl":"عدي كاتب كسرى وموفده إلى ملك الروم — دهاء عدي وسعيه في ولاية النعمان"},
{"id":"b8-6","bab":"الجزء 2","sec":"دهاء عدي وسعيه في ولاية النعمان","page":"ج2 ص98","text":"وكان النعمان من بينهم أحمر أبرش قصيرا وأمه سلمى بنت وائل بن عطية الصائغ من أهل فدك فلما احتضر المنذر وخلف أولاده العشرة وقيل بل كانوا ثلاثة عشر أوصى بهم إلى إياس بن قبيصة الطائي وملكه على الحيرة إلى\nأن يرى كسرى رأيه فمكث مملكا عليها أشهرا وكسرى في طلب رجل يملكه عليهم وهو كسرى بن هرمز فلم يجد أحدا يرضاه فضجر فقال لأبعثن إلى الحيرة اثني عشر الفا من الأساورة ولأملكن عليهم رجلا من الفرس ولآمرنهم أن ينزلوا على العرب في دورهم ويملكوا عليهم أموالهم ونساءهم وكان عدي بن زيد واقفا بين يديه فأقبل عليه وقال ويحك يا عدي من بقي من آل المنذر وهل فيهم أحد فيه خير فقال نعم أيها الملك السعيد إن في ولد المنذر لبقية وفيهم كلهم خير فقال ابعث إليهم فأحضرهم فبعث عدي إليهم فأحضرهم وأنزلهم جميعا عنده ويقال بل شخص عدي بن زيد إلى الحيرة حتى خاطبهم بما أراد وأوصاهم ثم قدم بهم على كسرى قال فلما نزلوا على عدي بن زيد أرسل إلى النعمان لست أملك غيرك فلا يوحشنك ما أفضل به إخوتك عليك من الكرامة فإني إنما أغترهم بذلك ثم كان يفضل إخوته جميعا عليه في النزل والإكرام والملازمة ويريهم تنقصا للنعمان وأنه غير طامع في تمام أمر على يده وجعل يخلو بهم رجلا رجلا فيقول أذا أدخلتكم على الملك فالبسوا أفخر ثيابكم وأجملها وإذا دعا لكم بالطعام لتأكلوا فتباطؤوا في الأكل وصغروا اللقم ونزروا ما تأكلون فأذا قال لكم أتكفونني العرب فقولوا نعم فإذا قال لكم فإن شذ أحدكم عن الطاعة وأفسد أتكفوننيه فقولوا لا إن بعضنا لا يقدر على بعض ليهابكم ولا يطمع في تفرقكم ويعلم أن للعرب منعة وبأسا فقبلوا منه وخلا بالنعمان فقال له البس ثياب السفر وادخل متقلدا بسيفك وإذا جلست للأكل فعظم اللقم وأسرع المضغ والبلع وزد في الأكل وتجوع قبل ذلك فإن كسرى يعجبه كثرة الأكل من العرب خاصة ويرى أنه لا خير في العربي إذا لم يكن أكولا شرها ولا سيما إذا رأى غير طعامه وما لا عهد له بمثله وإذا سألك هل تكفيني العرب فقل نعم فإذا قال لك فمن لي بإخوتك فقل له إن عجزت عنهم فإني عن غيرهم لأعجز قال وخلا ابن مرينا بالأسود فسأله عما أوصاه به\nعدي فأخبره فقال غشك والصليب والمعمودية وما نصحك ولئن أطعتني لتخالفن كل ما أمرك به ولتملكن ولئن عصيتني ليملكن النعمان ولا يغرنك ما أراكه من الإكرام والتفضيل على النعمان فإن ذلك دهاء فيه ومكر وإن هذه المعدية لا تخلو من مكر وحيلة فقال له إن عديا لم يألني نصحا وهو أعلم بكسرى منك وإن خالفته أوحشته وأفسد علي وهو جاء بنا ووصفنا وإلى قوله يرجع كسرى فلما أيس ابن مرينا من قبوله منه قال ستعلم ودعا بهم كسرى فلما دخلوا عليه أعجبه جمالهم وكمالهم ورأى رجالا قلما رأى مثلهم فدعا لهم بالطعام ففعلوا ما أمرهم به عدي فجعل ينظر إلى النعمان من بينهم ويتأمل أكله فقال لعدي بالفارسية إن يكن في أحد منهم خير ففي هذا فلما غسلوا أيديهم جعل يدعو بهم رجلا رجلا فيقول له أتكفيني العرب فيقول نعم أكفيكها كلها إلا إخوتي حتى انتهى إلى النعمان آخرهم فقال له أتكفيني العرب قال نعم قال كلها قال نعم قال فكيف لي بإخوتك قال إن عجزت عنهم فأنا عن غيرهم أعجز فملكه وخلع عليه وألبسه تاجا قيمته ستون ألف درهم فيه اللؤلؤ والذهب","topic":"ذكر عدى بن زيد ونسبه وقصته ومقتله","topicNo":8,"sp":3,"spl":"عدي كاتب كسرى وموفده إلى ملك الروم — دهاء عدي وسعيه في ولاية النعمان"},
{"id":"b8-7","bab":"الجزء 2","sec":"توعد ابن مرينا لعدي وتدبير المكيدة له","page":"ج2 ص100","text":"فلما خرج وقد ملك قال ابن مرينا للأسود دونك عقبى خلافك لي ثم إن عديا صنع طعاما في بيعة وأرسل إلى ابن مرينا أن ائتني بمن أحببت فإن لي حاجة فأتى في ناس فتغدوا في البيعة فقال عدي بن زيد لابن مرينا ياعدي إن أحق من عرف الحق ثم لم يلم عليه من كان مثلك وإني قد عرفت أن صاحبك الأسود بن المنذر كان أحب إليك أن يملك من صاحبي النعمان فلا تلمني على شيء كنت على مثله وأنا أحب ألا تحقد علي شيئا لو قدرت عليه ركبته وأنا أحب أن تعطيني من نفسك ما أعطيك من نفسي فإن نصيبي في هذا الأمر ليس بأوفر من نصيبك وقام إلى البيعة فحلف ألا يهجوه أبدا ولا يبغيه غائلة ولا يزوي عنه خيرا\nأبدا فلما فرغ عدي بن زيد قام عدى بن مرينا فحلف مثل يمينه ألا يزال يهجوه أبدا ويبغيه الغوائل ما بقي وخرج النعمان حتى نزل منزل أبيه بالحيرة فقال عدي بن مرينا لعدي بن زيد\n(ألا أبلغ عديا عن عدي ... فلا تجزع وإن رثت قواكا)\n(هياكلنا تبر لغير فقر ... لتحمد أو يتم به غناكا)\n(فإن تظفر فلم تظفر حميدا ... وإن تعطب فلا يبعد سواكا)\n(ندمت ندامة الكسعي لما ... رأت عيناك ما صنعت يداكا)\nال ثم قال عدي بن مرينا للأسود أما إذا لم تظفر فلا تعجزن أن تطلب بثأرك من هذا المعدي الذي فعل بك ما فعل فقد كنت أخبرك أن معدا لا ينام كيدها ومكرها وأمرتك أن تعصيه فخالفتني قال فما تريد قال أريد ألا تأتيك فائدة من مالك وأرضك إلا عرضتها علي ففعل وكان ابن مرينا كثير المال والضيعة فلم يكن في الدهر يوم يأتي إلا على باب النعمان هدية من ابن مرينا فصار من أكرم الناس عليه حتى كان لا يقضي في ملكه شيئا إلا بأمر ابن مرينا وكان إذا ذكر عدي بن زيد عند النعمان أحسن الثناء عليه وشيع ذلك بأن يقول إن عدي بن زيد فيه مكر وخديعة والمعدي لا يصلح إلا هكذا فلما رأى من يطيف بالنعمان منزلة ابن مرينا عنده لزموه وتابعوه فجعل يقول لمن يثق به من أصحابه إذا رأيتموني أذكر عديا عند الملك بخير فقولوا إنه لكذلك ولكنه لا يسلم عليه أحد وإنه ليقول إن الملك يعني النعمان عامله وإنه هو ولاه ما ولاه فلم يزالوا بذلك حتى أضغنوه عليه فكتبوا كتابا على لسانه إلى قهرمان له\nثم دسوا إليه حتى أخذوا الكتاب منه وأتوا به النعمان فقرأه فاشتد غضبه فأرسل إلى عدي بن زيد","topic":"ذكر عدى بن زيد ونسبه وقصته ومقتله","topicNo":8,"sp":4,"spl":"توعد ابن مرينا لعدي وتدبير المكيدة له"},
{"id":"b8-8","bab":"الجزء 2","sec":"عدي في حبس النعمان يقول شعرا","page":"ج2 ص102","text":"عزمت عليك إلا زرتني فإني قد اشتقت إلى رؤيتك وعدي يومئذ عند كسرى فاستأذن كسرى فأذن له فلما أتاه لم ينظر إليه حتى حبسه في محبس لا يدخل عليه فيه أحد فجعل عدي يقول الشعر وهو في الحبس فكان أول ما قاله وهو محبوس من الشعر\n(ليت شعري عن الهمام ويأتيك ... بخبر الأنباء عطف السؤال)\n(أين عنا إخطارنا المال والأنفس ... إذ ناهدوا ليوم المحال)\n(ونضالي في جنبك الناس يرمون ... وأرمي وكلنا غير آلي)\n(فأصيب الذي تريد بلا غش ... وأربي عليهم وأوالي)\n(ليت أني أخذت حتفي بكفي ... ولم ألق ميتة الأقتال)\n(محلوا محلهم لصرعتنا العام ... فقد أوقعوا الرحا بالثفال)\nهي قصيدة طويلة قالوا وقال أيضا وهو محبوس\n(أرقت لمكفهر بات فيه ... بوارق يرتقين رؤوس شيب)\n(تلوح المشرفية في ذراه ... ويجلو صفح دخدار قشيب)\nويروى تخال المشرفية الدخدار فارسية معربة وهو الثوب المصون يقول فيها\n(سعى الأعداء لا يألون شرا ... علي ورب مكة والصليب)\n(أرادوا كي تمهل عن عدي ... ليسجن أو يدهده في القليب)\n(وكنت لزاز خصمك لم أعرد ... وقد سلكوك في يوم عصيب)\n(أعالنهم وأبطن كل سر ... كما بين اللحاء إلى العسيب)\n(ففزت عليهم لما التقينا ... بتاجك فوزة القدح الأريب)\n(وما دهري بأن كدرت فضلا ... ولكن ما لقيت من العجيب)\n(ألا من مبلغ النعمان عني ... وقد تهدى النصيحة بالمغيب)\n(أحظي كان سلسلة وقيدا ... وغلا والبيان لدى الطبيب)\n(أتاك بأنني قد طال حبسي ... ولم تسأم بمسجون حريب)\n(وبيتي مقفر إلا نساء ... أرامل قد هلكن من النحيب)\n(يبادرن الدموع على عدي ... كشن خانه خرز الربيب)\n(يحاذرن الوشاة على عدي ... وما اقترفوا عليه من الذنوب)\n(فإن أخطأت أو أوهمت أمرا ... فقد يهم المصافي بالحبيب)\n(وإن أظلم فقد عاقبتموني ... وإن أظلم فذلك من نصيبي)\n(وإن أهلك تجد فقدي وتخذل ... إذا التقت العوالي في الحروب)\n(فهل لك أن تدارك ما لدينا ... ولا تغلب على الرأي المصيب)\n(فإني قد وكلت اليوم امري ... إلى رب قريب مستجيب)\nقالوا وقال فيه أيضا طال ذا الليل علينا واعتكر ... وكأني ناذر الصبح سمر\n(من نجي الهم عندي ثاويا ... فوق ما أعلن منه وأسر)\n(وكأن الليل فيه مثله ... ولقدما ظن بالليل القصر)\n(لم أغمض طوله حتى انقضى ... أتمنى لو أرى الصبح جشر)\n(غير ما عشق ولكن طارق ... خلس النوم وأجداني السهر)\nوفيها يقول\n(أبلغ النعمان عني مألكا ... قول من قد خاف ظنا فاعتذر)\n(أنني والله فاقبل حلفي ... لأبيل كلما صلى جأر)\n(مرعد أحشاؤه في هيكل ... حسن لمته وافي الشعر)\n(ما حملت الغل من أعدائكم ... ولدى الله من العلم المسر)\n(لا تكونن كآسي عظمه ... بأسا حتى إذا العظم جبر)\n(عاد بعد الجبر يبغي وهنه ... ينحون المشي منه فانكسر)\n(واذكر النعمى التي لم أنسها ... لك في السعي إذا العبد كفر)\nوقا ل له أيضا وهي قصيدة طويلة\n(أبلغ النعمان عني مألكا ... أنه قد طال حبسي وانتظاري)\n(لو بغير الماء حلقي شرق ... كنت كالغصان بالماء اعتصاري)\n(ليت شعري عن دخيل يفتري ... حيثما أدرك ليلي ونهاري)\n(قاعدا يكرب نفسي بثها ... وحراما كان سجني واحتصاري)\n(أجل نعمى ربها أولكم ... ودنوي كان منكم واصطهاري)\nفي قصائد كثيرة كان يقولها فيه ويكتب بها إليه فلا تغني عنده شيئا هذه رواية الكلبي","topic":"ذكر عدى بن زيد ونسبه وقصته ومقتله","topicNo":8,"sp":5,"spl":"عدي في حبس النعمان يقول شعرا"},
{"id":"b8-9","bab":"الجزء 2","sec":"لماذا حبس النعمان عديا","page":"ج2 ص106","text":"وأما المفضل الضبي فإنه ذكر أن عدي بن زيد لما قدم على النعمان صادفه لا مال عنده ولا أثاث ولا ما يصلح لملك وكان آدم إخوته منظرا وكلهم أكثر مالا منه فقال له عدي كيف أصنع بك ولا مال عندك فقال له النعمان ما أعرف لك حيلة إلا ما تعرفه أنت فقال له قم بنا نمض إلى ابن قردس رجل من أهل الحيرة من دومة فأتياه ليقترضا منه مالا فأبى أن يقرضهما وقال ما عندي شيء فأتيا جابر بن شمعون وهو الأسقف أحد بني الأوس بن قلام بن بطين بن جمهير ابن لحيان من بني الحارث بن كعب فاستقرضا منه مالا فأنزلهما عنده ثلاثة أيام يذبح لهم ويسقيهم الخمر فلما كان في اليوم الرابع قال لهما ما تريدان فقال له عدي تقرضنا أربعين ألف درهم يستعين بها النعمان على أمره عند كسرى فقال لكما عندي ثمانون ألفا ثم أعطاهما إياها فقال النعمان لجابر لا جرم لا\nجرى لي درهم إلا على يديك إن أنا ملكت قال وجابر هو صاحب القصر الأبيض بالحيرة ثم ذكر من قصة النعمان وإخوته وعدي وابن مرينا مثل ما ذكره ابن الكلبي وقال المفضل خاصة إن سبب حبس النعمان عدي بن زيد أن عديا صنع ذات يوم طعاما للنعمان وسأله أن يركب إليه ويتغدى عنده هو وأصحابه فركب النعمان إليه فاعترضه عدي بن مرينا فاحتبسه حتى تغدى عنده هو وأصحابه وشربوا حتى ثملوا ثم ركب إلى عدي ولا فضل فيه فأحفظه ذلك ورأى في وجه عدي الكراهة فقام فركب ورجع إلى منزله فقال عدي بن زيد في ذلك من فعل النعمان\n(أحسبت مجلسنا وحسن حديثنا يودي بمالك ... )\n(فالمال والأهلون مصرعة لأمرك أو نكالك ... )\n(ما تأمرن فينا فأمرك في يمينك أو شمالك ... )\nقال وأرسل النعمان ذات يوم إلى عدي بن زيد فأبى أن يأتيه ثم أعاد رسوله فأبى أن يأتيه وقد كان النعمان شرب فغضب وأمر به فسحب من منزله حتى انتهي به إليه فحبسه في الصنين ولج في حبسه وعدي يرسل إليه بالشعر فما قاله له\n(ليس شيء على المنون بباق ... غير وجه المسبح الخلاق)\n(إن نكن آمنين فاجأنا شر ... مصيب ذا الود والإشفاق)\n(فبريء صدري من الظلم للرب ... وحنث بمعقد الميثاق)\n(ولقد ساءني زيارة ذي قربى ... حبيب لودنا مشتاق)\n(ساءه ما بنا تبين في الأيدي ... وإشناقها إلى الأعناق)\n(فاذهبي يا أميم غير بعيد ... لايؤاتي العناق من في الوثاق)\n(واذهبي يا أميم إن يشأ الله ... ينفس من أزم هذا الخناق)\n(أو تكن وجهة فتلك سبيل الناس ... لا تمنع الحتوف الرواقي)\nويقول فيها\n(وتقول العداة أودى عدي ... وبنوه قد أيقنوا بغلاق)\n(يا أبا مسهر فأبلغ رسولا ... إخوتي إن أتيت صحن العراق)\n(أبلغا عامرا وأبلغ أخاه ... أنني موثق شديد وثاقي)\n(في حديد القسطاس يرقبني الحارس ... والمرء كل شيء يلاقي)\n(في حديد مضاعف وغلول ... وثياب منضحات خلاق)\n(فاركبوا في الحرام فكوا أخاكم ... إن عيرا قد جهزت لانطلاق)\nيعني الشهر الحرام قالوا جميعا وخرج النعمان إلى البحرين فأقبل رجل من غسان فأصاب في الحيرة ما أحب ويقال إنه جفنة بن النعمان الجفني فقال عدي بن زيد في ذلك\n(سما صقر فأشعل جانبيها ... وألهاك المروح والعزيب)\nالمروح الإبل المروحة إلى أعطانها والعزيب ما ترك في مراعيه\n(وثبن لدي الثوية ملجمات ... وصبحن العباد وهن شيب)\n(ألا تلك الغنيمة لا إفال ... ترجيها مسومة ونيب)\n(ترجيها وقد صابت بقر ... كما ترجو أصاغرها عتيب)","topic":"ذكر عدى بن زيد ونسبه وقصته ومقتله","topicNo":8,"sp":6,"spl":"لماذا حبس النعمان عديا","partial":1},
{"id":"b8-10","bab":"الجزء 2","sec":"عدي يخاطب أخاه شعرا وأخوه يرد","page":"ج2 ص109","text":"وقالوا جميعا فلما طال سجن عدي بن زيد كتب إلى أخيه أبي وهو مع كسرى بهذا الشعر\n(أبلغ أبيا على نأيه ... وهل ينفع المرء ما قد علم)\n(بأن أخاك شقيق الفؤاد ... كنت به واثقا ما سلم)\n(لدى ملك موثق في الحديد ... إما بحق وإما ظلم)\n(فلا أعرفك كذات الغلام ... ما لم تجد عارما تعترم)\n(فأرضك أرضك إن تأتنا ... تنم نومة ليس فيها حلم)\nقال فكتب إليه أخوه أبي\n(إن يكن خانك الزمان فلا عاجز ... باع ولا ألف ضعيف)\n(ويمين الإله لو أن جأواء ... طحونا تضيء فيها السيوف)\n(ذات رزمجتابة غمرة الموت ... صحيح سربالها مكفوف)\n(كنت في حميها لجئتك أسعى ... فاعلمن لو سمعت إذ تستضيف)\n(أو بمال سألت دونك لم يمنع ... تلاد لحاجة أو طريف)\n(أو بأرض أستطيع آتيك فيها ... لم يهلني بعد بها أو مخوف)\n(إن تفتني والله إلفا فجوعا ... لا يعقبك ما يصوب الخريف)\n(في الأعادي وأنت مني بعيد ... عز هذا الزمان والتعنيف)\n(ولعمري لئن جزعت عليه ... لجزوع على الصديق أسوف)\n(ولعمري لئن ملكت عزائي ... لقليل شرواك فيما أطوف)","topic":"ذكر عدى بن زيد ونسبه وقصته ومقتله","topicNo":8,"sp":7,"spl":"عدي يخاطب أخاه شعرا وأخوه يرد — كسرى يأمر باطلاق عدي والنعمان يقتله"},
{"id":"b8-11","bab":"الجزء 2","sec":"كسرى يأمر باطلاق عدي والنعمان يقتله","page":"ج2 ص111","text":"قالوا جميعا فلما قرأ أبي كتاب عدي قام إلى كسرى فكلمه في أمره وعرفه خبره فكتب إلى النعمان يأمره بإطلاقه وبعث معه رجلا وكتب خليفة النعمان إليه إنه قد كتب إليك في أمره فأتى النعمان أعداء عدي من بني بقيلة وهم من غسان فقالوا له اقتله الساعة فأبى عليهم وجاء الرسول وقد كان أخو عدي تقدم إليه ورشاه وأمره أن يبدأ بعدي فيدخل إليه وهو محبوس بالصنين فقال له ادخل عليه فانظر ما يأمرك به فامتثله فدخل الرسول على عدي فقال له إني قد جئت بإرسالك فما عندك قال عندي الذي تحب ووعده بعدة سنية وقال له لا تخرجن من عندي وأعطني الكتاب حتى أرسله إليه فإنك والله إن خرجت من عندي لأقتلن فقال لا أستطيع إلا أن آتي الملك بالكتاب فأوصله إليه فانطلق بعض من كان هناك من أعدائه فأخبر النعمان أن رسول كسرى دخل على عدي وهو ذاهب به وإن فعل والله لم يستبق منا أحدا أنت ولا غيرك فبعث إليه النعمان أعداءه فغموه حتى مات ثم دفنوه ودخل الرسول إلى النعمان فأوصل الكتاب إليه فقال نعم وكرامة وأمر له بأربعة آلاف مثقال ذهبا وجارية حسناء وقال له إذا أصبحت فادخل أنت بنفسك فأخرجه فلما أصبح ركب فدخل السجن فأعلمه الحرس أنه قد مات منذ أيام ولم نجترىء على إخبار الملك خوفا منه وقد عرفنا كراهته لموته فرجع إلى النعمان وقال له إني كنت أمس\nدخلت على عدي وهو حي وجئت اليوم فجحدني السجان وبهتني وذكر أنه قد مات منذ أيام فقال له النعمان أيبعث بك الملك إلي فتدخل إليه قبلي كذبت ولكنك أردت الرشوة والخبث فتهدده ثم زاده جائزة وأكرمه وتوثق منه ألا يخبر كسرى إلا أنه قد مات قبل أن يقدم عليه فرجع الرسول إلى كسرى وقال إني وجدت عديا قد مات قبل أن أدخل عليه وندم النعمان على قتل عدي وعرف أنه احتيل عليه في أمره واجترأ أعداؤه عليه وهابهم هيبة شديدة ثم إنه خرج إلى صيده ذات يوم فلقي ابنا لعدي يقال له زيد فلما رآه عرف شبهه فقال له من أنت فقال أنا زيد بن عدي بن زيد فكلمه فإذا غلام ظريف ففرح به فرحا شديدا وقربه وأعطاه ووصله واعتذر إليه من أمر أبيه وجهزه ثم كتب إلى كسرى إن عديا كان ممن أعين به الملك في نصحه ولبه فأصابه ما لابد منه وانقطعت مدته وانقضى أجله ولم يصب به أحد أشد من مصيبتي وأما الملك فلم يكن ليفقد رجلا إلا جعل الله له منه خلفا لما عظم الله من ملكه وشأنه وقد بلغ ابن له ليس بدونه رأيته يصلح لخدمة الملك فسرحته إليه فإن رأى الملك أن يجعله مكان أبيه فليفعل وليصرف عمه عن ذلك إلى عمل آخر وكان هو الذي يلي المكاتبة عن الملك إلى ملوك العرب في أمورها وفي خواص أمور الملك وكانت له من العرب وظيفة موظفة في كل سنة مهران أشقران يجعلان له هلاما والكمأة الرطبة في حينها واليابسة والأقط والإدم وسائر تجارات\nالعرب فكان زيد بن عدي يلي ذلك له وكان هذا عمل عدي فلما وقع زيد بن عدي عند الملك هذا الموقع سأله كسرى عن النعمان فأحسن الثناء عليه ومكث على ذلك سنوات على الأمر الذي كان أبوه عليه وأعجب به كسرى فكان يكثر الدخول عليه والخدمة له","topic":"ذكر عدى بن زيد ونسبه وقصته ومقتله","topicNo":8,"sp":7,"spl":"عدي يخاطب أخاه شعرا وأخوه يرد — كسرى يأمر باطلاق عدي والنعمان يقتله"},
{"id":"b8-12","bab":"الجزء 2","sec":"صفات نساء ملوك العجم","page":"ج2 ص113","text":"وكانت لملوك العجم صفة من النساء مكتوبة عندهم فكانوا يبعثون في تلك الأرضين بتلك الصفة فإذا وجدت حملت إلى الملك غير أنهم لم يكونوا يطلبونها في أرض العرب ولا يظنونها عندهم ثم إنه بدا للملك في طلب الصفة وأمر فكتب بها إلى النواحي ودخل إليه زيد بن عدي وهو في ذلك القول فخاطبه فيما دخل إليه فيه ثم قال إني رأيت الملك قد كتب في نسوة يطلبن له وقرأت الصفة وقد كنت بآل المنذر عارفا وعند عبدك النعمان من بناته وأخواته وبنات عمه وأهله أكثر من عشرين امرأة على هذه الصفة قال فاكتب فيهن قال أيها الملك إن شر شيء في العرب وفي النعمان خاصة أنهم يتكرمون زعموا في أنفسهم عن العجم فأنا أكره أن يغيبهن عمن تبعث إليه أو يعرض عليه غيرهن وإن قدمت أنا عليه لم يقدر على ذلك فابعثني وابعث معي رجلا من ثقاتك يفهم العربية حتى أبلغ ما تحبه فبعث معه رجلا جلدا فهما فخرج به زيد فجعل يكرم الرجل ويلطفه حتى بلغ الحيرة فلما دخل عليه أعظم الملك وقال إنه قد احتاج إلى نساء لنفسه وولده وأهل بيته وأراد كرامتك بصهره فبعث إليك فقال ما هؤلاء النسوة فقال هذه صفتهن قد جئنا بها وكانت الصفة أن المنذر الأكبر أهدى إلى أنوشروان جارية كان أصابها إذ أغار على الحارث\nالأكبر بن أبي شمر الغساني فكتب إلى أنوشروان بصفتها وقال إني قد وجهت إلى الملك جارية معتدلة الخلق نقية اللون والثغر بيضاء قمراء وطفاء كحلاء دعجاء حوراء عيناء قنواء شماء برجاء زجاء أسيلة الخد شهية المقبل جثلة الشعر عظيمة الهامة بعيدة مهوى القرط عيطاء\nعريضة الصدر كاعب الثدي ضخمة مشاش المنكب والعضد حسنة المعصم لطيفة الكف سبطة البنان ضامرة البطن خميصة الخصر غرثى الوشاح رداح الأقبال رابية الكفل لفاء الفخذين ريا الروادف ضخمة المأكمتين مفعمة الساق مشبعة الخلخال لطيفة الكعب والقدم قطوف المشي مكسال الضحى بضة المتجرد سموعا للسيد ليست بخنساء ولا سفعاء رقيقة الأنف عزيزة النفس لم تغذ في\nبؤس حيية رزينة حليمة ركينة كريمة الخال تقتصر على نسب أبيها دون فصيلتها وتستغني بفصيلتها دون جماع قبيلتها قد أحكمتها الأمور في الأدب فرأيها أهل الشرف وعملها عمل أهل الحاجة صناع الكفين قطيعة اللسان رهوة الصوت ساكنته تزين الولي وتشين العدو إن أردتها اشتهت وإن تركتها انتهت تحملق عيناها وتحمر وجنتاها وتذبذب شفتاها وتبادرك الوثبة إذا قمت ولا تجلس إلا بأمرك إذا جلست قال فقبلها أنوشروان وأمر بإثبات هذه الصفة في دواوينه فلم يزالوا يتوارثونها حتى أفضى ذلك إلى كسرى ابن هرمز فقرأ زيد هذه الصفة على النعمان فشقت عليه وقال لزيد والرسول يسمع أما في مها السواد وعين فارس ما يبلغ به كسرى حاجته فقال الرسول لزيد بالفارسية ما المها والعين فقال له بالفارسية كاوان أي البقر فأمسك الرسول وقال زيد للنعمان إنما أراد الملك كرامتك ولو علم أن هذا يشق عليك لم يكتب إليك به فأنزلهما يومين عنده ثم كتب إلى كسرى إن الذي طلب الملك ليس عندي وقال لزيد اعذرني عند الملك فلما رجعا إلى كسرى قال زيد للرسول الذي قدم معه أصدق الملك عما سمعت فإني سأحدثه بمثل حديثك ولا أخالفك فيه فلما دخلا على كسرى قال زيد هذا\nكتابه إليك فقرأه عليه فقال له كسرى وأين الذي كنت خبرتني به قال قد كنت خبرتك بضنتهم بنسائهم على غيرهم وإن ذلك من شقائهم واختيارهم الجوع والعري على الشبع والرياش وإيثارهم السموم والرياح على طيب أرضك هذه حتى إنهم ليسمونها السجن فسل هذا الرسول الذي كان معي عما قال فإني أكرم الملك عن مشافهته بما قال وأجاب به قال للرسول وما قال فقال له الرسول أيها الملك إنه قال أما كان في بقر السواد وفارس ما يكفيه حتى يطلب ما عندنا فعرف الغضب في وجهه ووقع في قلبه منه ما وقع لكنه لم يزد على أن قال رب عبد قد أراد ما هو أشد من هذا ثم صار أمره إلى التباب وشاع هذا الكلام حتى بلغ النعمان وسكت كسرى أشهرا على ذلك","topic":"ذكر عدى بن زيد ونسبه وقصته ومقتله","topicNo":8,"sp":8,"spl":"صفات نساء ملوك العجم"},
{"id":"b8-13","bab":"الجزء 2","sec":"النعمان يستجير بقبائل العرب","page":"ج2 ص117","text":"وجعل النعمان يستعد ويتوقع حتى أتاه كتابه أن أقبل فإن للملك حاجة إليك فانطلق حين أتاه كتابه فحمل سلاحه وما قوي عليه ثم لحق بجبلي طيىء وكانت فرعة بنت سعد بن حارثة بن لأم عنده وقد ولدت له رجلا وامرأة وكانت أيضا عنده زينب بنت أوس بن حارثة فأراد النعمان طيئا على أن يدخلوه الجبلين ويمنعوه فأبوا ذلك عليه وقالوا له لولا صهرك لقتلناك فإنه لا حاجة بنا إلى معاداة كسرى ولا طاقة لنا به وأقبل يطوف على قبائل العرب ليس أحد منهم يقبله غير أن بني رواحة بن قطيعة بن عبس قالوا إن شئت قاتلنا معك لمنة\nكانت له عندهم في أمر مروان القرظ قال ما أحب أن أهلككم فإنه لا طاقة لكم بكسرى فأقبل حتى نزل بذي قار في بني شيبان سرا فلقي هانىء بن قبيصة وقيل بل هانىء بن مسعود بن عامر بن عمرو بن أبي ربيعة بن ذهل بن شيبان وكان سيدا منيعا والبيت يومئذ من ربيعة في آل ذي الجدين لقيس بن مسعود بن قيس بن خالد ذي الجدين وكان كسرى قد أطعم قيس بن مسعود الأبلة فكره النعمان أن يدفع إليه أهله لذلك وعلم أن هانئا يمنعه مما يمنع منه نفسه وقال حماد الراوية في خبره إنه إنما استجار بهانىء كما استجار بغيره فأجاره وقال له قد لزمني ذمامك مما أمنع نفسي وأهلي وولدي منه ما بقي من عشيرتي الأدنين رجل وإن ذلك غير نافعك لأنه مهلكي ومهلكك وعندي رأي لك لست أشير به عليك لأدفعك عما تريده من مجاورتي ولكنه الصواب فقال هاته فقال إن كل أمر يجمل بالرجل أن يكون عليه إلا أن يكون بعد الملك سوقة والموت نازل بكل واحد ولأن تموت كريما خير من أن تتجرع الذل أو تبقى سوقة بعد الملك هذا إن بقيت فامض إلى صاحبك وأرسل إليه هدايا\nومالا وألق نفسك بين يديه فإما أن صفح عنك فعدت ملكا عزيزا وإما أن أصابك فالموت خير من أن يتلعب بك صعاليك العرب ويتخطفك ذئابها وتأكل مالك وتعيش فقيرا مجاورا أو تقتل مقهورا فقال كيف بحرمي قال هن في ذمتي لا يخلص إليهن حتى يخلص إلى بناتي فقال هذا وأبيك الرأي الصحيح ولن أجاوزه ثم أختار خيلا وحللا من عصب اليمن وجوهرا وطرفا كانت عنده ووجه بها إلى كسرى وكتب إليه يعتذر ويعلمه أنه صائر إليه ووجه بها مع رسوله فقلبها كسرى وأمره بالقدوم فعاد إليه الرسول فأخبره بذلك وأنه لم ير له عند كسرى سوءا فمضى إليه حتى إذا وصل إلى المدائن لقيه زيد بن عدي على قنطرة ساباط فقال له انج نعيم إن استطعت النجاء فقال له أفعلتها يا زيد أما والله لئن عشت لك لأقتلنك قتلة لم يقتلها عربي قط ولألحقنك بأبيك فقال له زيد امض لشانك نعيم فقد والله أخيت لك أخية لا يقطعها المهر الأرن","topic":"ذكر عدى بن زيد ونسبه وقصته ومقتله","topicNo":8,"sp":9,"spl":"النعمان يستجير بقبائل العرب — نهاية النعمان في سجن كسرى"},
{"id":"b8-14","bab":"الجزء 2","sec":"نهاية النعمان في سجن كسرى","page":"ج2 ص120","text":"فلما بلغ كسرى أنه بالباب بعث إليه فقيده وبعث به إلى سجن كان له بخانقين فلم يزل فيه حتى وقع الطاعون هناك فمات فيه وقال حماد الراوية والكوفيون بل مات بساباط في حبسه وقال ابن الكلبي ألقاه تحت أرجل الفيلة فوطئته حتى مات واحتجوا بقول الأعشى\n(فذاك وما أنجى من الموت ربه ... بساباط حتى مات وهو محزرق)\nال المحزرق المضيق عليه وأنكر هذا من زعم أنه مات بخانقين وقالوا لم يزل محبوسا مدة طويلة وإنه إنما مات بعد ذلك لحين قبيل الإسلام وغضبت له العرب حينئذ وكان قتله سبب وقعة ذي قار","topic":"ذكر عدى بن زيد ونسبه وقصته ومقتله","topicNo":8,"sp":9,"spl":"النعمان يستجير بقبائل العرب — نهاية النعمان في سجن كسرى"},
{"id":"b8-15","bab":"الجزء 2","sec":"عدي يتزوج هند بنت النعمان","page":"ج2 ص121","text":"أخبرني عمي قال حدثنا عبد الله بن أبي سعد قال حدثنا علي بن الصباح وأخبرني الحسن بن علي قال حدثني محمد بن القاسم بن ممهرويه قال قال علي بن الصباح حدثني هشام بن الكلبي عن أبيه قال كان عدي بن زيد بن حماد بن زيد بن أيوب الشاعر العبادي يهوى هند بنت النعمان بن المنذر بن المنذر بن امرىء القيس بن النعمان بن امرىء القيس ابن عمرو بن عدي بن نصر بن ربيعة بن عمرو بن الحارث بن مسعود بن مالك بن غنم بن نمارة بن لخم وهو مالك بن عدي بن الحارث بن مرة بن أدد بن زيد بن يشجب بن عريب بن زيد بن كهلان بن سبأ بن يشجب بن يعرب بن قحطان ولها يقول\n(علق الأحشاء من هند علق ... مستسر فيه نصب وأرق)\nوهي قصيدة طويلة وفيها أيضا يقول\n(من لقلب دنف أو معتمد ... قد عصى كل نصوح ومفد)\nوهي طويلة وفيها أيضا يقول\n(يا خليلي يسرا التعسيرا ... ثم روحا فهجرا تهجيرا)\n(عرجا بي على ديار لهند ... ليس أن عجتما المطي كبيرا)\nال ابن الكلبي وقد تزوجها عدي وقال ابن أبي سعد وذكر ذلك خالد\nابن كلثوم أيضا قالا كان سبب عشقه إياها أن هندا كانت من أجمل نساء أهلها وزمانها وأمها مارية الكندية فخرجت في خميس الفصح وهو بعد السعانين بثلاثة أيام تتقرب في البيعة ولها حينئذ أحدى عشرة سنة وذلك في ملك المنذر وقد عدي حينئذ بهدية من كسرى إلى المنذر والنعمان يومئذ فتى شاب فاتفق دخولها البيعة وقد دخلها عدي ليتقرب وكانت مديدة القامة عبلة الجسم فرآها عدي وهي غافلة فلم تنتبه له حتى تأملها وقد كان جواريها رأين عديا وهو مقبل فلم يقلن لها ذلك كي يراها عدي وإنما فعلن هذا من أجل أمة لهند يقال لها مارية وقد كانت أحبت عديا فلم تدر كيف تأتي له فلما رأت هند عديا ينظر إليها شق ذلك عليها وسبت جواريها ونالت بعضهن بضرب فوقعت هند في نفس عدي فلبث حولا لا يخبر بذلك أحدا فلما كان بعد حول وظنت مارية أن هندا قد أضربت عما جرى وصفت لها بيعة دومة وقال خالد بن كلثوم بيعة توما وهو الصحيح ووصفت لها من فيها من الرواهب ومن يأتيها من جواري الحيرة وحسن بنائها وسرجها وقالت لها سلي أمك الإذن لك في إتيانها فسألتها ذلك فأذنت لها وبادرت مارية إلى عدي فأخبرته الخبر فبادر فلبس يلمقا كان فرخانشاه مرد قد كساه إياه وكان مذهبا لم ير مثله حسنا","topic":"ذكر عدى بن زيد ونسبه وقصته ومقتله","topicNo":8,"sp":10,"spl":"عدي يتزوج هند بنت النعمان"}]);
window.__BOOK__['p01'].push([{"id":"b8-16","bab":"الجزء 2","sec":"عدي يتزوج هند بنت النعمان","page":"ج2 ص121","text":"وكان عدي حسن الوجه مديد القامة حلو العينين حسن المبسم نقي الثغر وأخذ معه جماعة من فتيان الحيرة فدخل البيعة فلما رأته مارية قالت لهند انظري إلى هذا الفتى فهو والله أحسن من كل ما ترين من السرج وغيرها قالت ومن هو قالت عدي بن زيد قالت أتخافين أن يعرفني إن دنوت منه لأراه من قريب قالت ومن أين يعرفك وما رآك قط من حيث يعرفك فدنت منه وهو يمازح الفتيان الذين معه وقد برع عليهم بجماله وحسن كلامه وفصاحته وما عليه من الثياب فذهلت لما رأته وبهتت تنظر إليه وعرفت مارية ما بها وتبينته في وجهها فقالت لها كلميه فكلمته وانصرفت وقد تبعته نفسها وهويته وانصرف بمثل حالها فلما كان الغد تعرضت له مارية فلما رآها هش لها وكان قبل ذلك لا يكلمها وقال لها ما غدا بك قالت حاجة إليك قال اذكريها فوالله لا تسأليني شيئا إلا أعطيتك إياه فعرفته أنها تهواه وأن حاجتها الخلوة به على أن تحتال له في هند وعاهدته على ذلك فأدخلها حانوت خمار في الحيرة ووقع عليها ثم خرجت فأتت هندا فقالت أما تشتهين أن تري عديا قالت وكيف لي به قالت أعده مكان كذا وكذا في ظهر القصر وتشرفين عليه قالت افعلي فواعدته إلى ذلك المكان فأتاه وأشرفت هند عليه فكادت تموت وقالت إن لم تدخليه إلي هلكت فبادرت الأمة إلى النعمان فأخبرته خبرها وصدقته وذكرت أنها قد شغفت به وأن سبب ذلك رؤيتها إياه في يوم الفصح وأنه إن لم يزوجها به افتضحت في أمره أو ماتت فقال لها ويلك وكيف أبدؤه بذلك فقالت هو أرغب في ذلك من أن تبدأه أنت وأنا أحتال في ذلك من حيث لا يعلم أنك عرفت أمره وأتت عديا فأخبرته الخبر وقالت ادعه فإذا أخذ الشراب منه فاخطب إليه فإنه غير رادك قال أخشى أن يغضبه ذلك فيكون سبب العداوة بيننا قالت ما قلت لك هذا حتى فرغت منه معه فصنع عدي طعاما واحتفل فيه ثم أتى النعمان بعد الفصح بثلاثة أيام وذلك في يوم الإثنين فسأله أن يتغدى عنده هو وأصحابه ففعل فلما أخذ منه الشراب خطبها إلى النعمان فأجابه وزوجه وضمها إليه بعد ثلاثة أيام","topic":"ذكر عدى بن زيد ونسبه وقصته ومقتله","topicNo":8,"sp":11,"spl":"عدي يتزوج هند بنت النعمان"},
{"id":"b8-17","bab":"الجزء 2","sec":"هند حبيسة الدير","page":"ج2 ص124","text":"قال خالد بن كلثوم فكانت معه حتى قتله النعمان فترهبت وحبست نفسها في الدير المعروف بدير هند في ظاهر الحيرة وقال ابن الكلبي بل ترهبت بعد ثلاث سنين ومنعته نفسها واحتبست في الدير حتى ماتت وكانت وفاتها بعد الإسلام بزمان طويل في ولاية المغيرة بن شعبة الكوفة وخطبها المغيرة فردته أخبرني عمي قال حدثني ابن أبي سعد قال حدثنا علي بن الصباح عن هشام ابن محمد بن الكلبي عن أبيه والشرفي بن القطامي قالا مر المغيرة بن شعبة لما ولاه معاوية الكوفة بدير هند فنزله ودخل على هند بنت النعمان بعد أن استأذن عليها فأذنت له وبسطت له مسحا فجلس عليه ثم قالت له ما جاء بك قال جئتك خاطبا قالت والصليب لو علمت أن في خصلة من جمال أو شباب رغبتك في لأجبتك ولكنك أردت أن تقول في المواسم ملكت مملكة النعمان بن المنذر ونكحت ابنته فبحق معبودك أهذا أردت قال أي والله قالت فلا سبيل إليه فقام المغيرة وانصرف وقال فيها\n(أدركت ما منيت نفسي خاليا ... لله درك يا بنة النعمان)\n(فلقد رددت على المغيرة ذهنه ... إن الملوك نقية الأذهان)\nوفي رواية أخرى\n(إن الملوك بطية الإذعان ... )\n(يا هند حسبك قد صدقت فأمسكي ... فالصدق خير مقالة الإنسان)\nقد روى عن ابن الكلبي غير علي بن الصباح في هند أنها كانت تهوى زرقاء اليمامة وأنها أول امرأة أحبت امرأة في العرب فإن الزرقاء كانت ترى الجيش من مسيرة ثلاثين ميلا فغزا قوم من العرب اليمامة فلما قربوا من مسافة نظرها قالوا كيف لكم بالوصول مع الزرقاء فاجتمع رأيهم على أن يقتلعوا شجرا تستر كل شجرة منها الفارس إذا حملها فقطع كل واحد منهم بمقدار طاقته وساروا بها فأشرفت كما كانت تفعل فقال لها قومها ما ترين يا زرقاء وذلك في آخر النهار قالت أرى شجرا يسير فقالوا كذبت أو كذبتك عينك واستهانوا بقولها فلما أصبحوا صبحهم القوم فاكتسحوا أموالهم وقتلوا منهم مقتلة عظيمة وأخذوا الزرقاء فقلعوا عينها فوجدوا فيها عروقا سوداء فسئلت عنها فقالت إني كنت أديم الإكتحال بالإثمد فلعل هذا منه وماتت بعد ذلك بأيام وبلغ هندا خبرها فترهبت ولبست المسوح وبنت ديرا يعرف بدير هند إلى الآن فأقامت فيه حتى ماتت وروى ابن حبيب عن ابن الأعرابي أن النعمان لما حبس عديا أكرهه في أمرها على طلاقها ولم يزل به حتى طلقها قال ابن حبيب وذكر عدي بن زيد صهره هذا للنعمان في قصائده وكان زوج أخته هكذا العلماء من أهل الحيرة وقالت رواة العرب إنه كان زوج ابنته هند فمن ذلك قوله في قصيدته التي أوله\n(أبصرت عيني عشاء ضوء نار ... )\nفقال فيها\n(أجل نعمى ربها أولكم ... ودنوي كان منكم واصطهاري)\n(نحن كنا قد علمتم قبلها ... عمد البيت وأوتاد الإصار)","topic":"ذكر عدى بن زيد ونسبه وقصته ومقتله","topicNo":8,"sp":12,"spl":"هند حبيسة الدير","partial":1},
{"id":"b8-18","bab":"الجزء 2","sec":"سبب تنصر النعمان","page":"ج2 ص125","text":"أخبرني محمد بن يحيى الصولي قال حدثنا إبراهيم بن فهد قال حدثنا خليفة ابن خياط شباب العصفري قال حدثنا هشام بن محمد قال حدثني يحيى بن أيوب البجلي قال حدثنا أبو زرعة بن عمرو بن جرير بن عبد الله البجلي قال سمعت جدي جرير بن عبد الله يقول وأخبرني به عمي قال حدثنا أحمد بن عبيد الله قال أخبرنا محمد بن يزيد بن زياد الكلبي أبو عبد الله قال حدثني معروف بن خربوذ عن يحيى بن أيوب عن أبي زرعة بن عمرو قال سمعت جدي جرير بن عبد الله ولفظ هذا الخبر لأحمد بن عبيد الله وروايته أتم قال كان سبب تنصر النعمان وكان يعبد الأوثان قبل ذلك وقال أحمد بن عبيد الله في خبره النعمان بن المنذر الأكبر أنه كان قد خرج يتنزه بظهر الحيرة ومعه عدي بن زيد فمر على المقابر من ظهر الحيرة ونهرها فقال له عدي بن زيد أبيت اللعن أتدري ما تقول هذه المقابر قال لا وقال أحمد بن عبيد الله في خبره فقال له تقول\nصهره هذا للنعمان في قصائده وكان زوج أخته هكذا العلماء من أهل الحيرة وقالت رواة العرب إنه كان زوج ابنته هند فمن ذلك قوله في قصيدته التي أولها\n(أبصرت عيني عشاء ضوء نار ... )\nفقال فيها\n(أجل نعمى ربها أولكم ... ودنوي كان منكم واصطهاري)\n(نحن كنا قد علمتم قبلها ... عمد البيت وأوتاد الإصار)\nبب تنصر النعمان أخبرني محمد بن يحيى الصولي قال حدثنا إبراهيم بن فهد قال حدثنا\n(أيها الركب المخبون ... على الأرض المجدون)\n(كما أنتم كنا ... كما نحن تكونون)\nوقال الصولي في خبره فقال له تقول\n(كنا كما كنتم حينا فغيرنا ... دهر فسوف كما صرنا تصيرونا)\nال فانصرف وقد دخلته رقة فمكث بعد ذلك يسيرا ثم خرج خرجة أخرى فمر على تلك المقابر ومعه عدي فقال له أبيت اللعن أتدري ما تقول هذه المقابر قال لا قال فإنها تقول\n(من رآنا فليحدث نفسه ... أنه موف على قرن زوال)\n(وصروف الدهر لا يبقى لها ... ولما تأتي به صم الجبال)\n(رب ركب قد أناخوا عندنا ... يشربون الخمر بالماء الزلال)\n(والأباريق عليها فدم ... وجياد الخيل تردي في الحلال)\n(عمروا دهرا بعيش حسن ... آمني دهرهم غير عجال)\n(ثم أضحوا عصف الدهر بهم ... وكذاك الدهر يودي بالرجال)\n(وكذاك الدهر يرمي بالفتى ... في طلاب العيش حالا بعد حال)\nقال الصولي في خبره وهو الصحيح فرجع النعمان فتنصر وقال أحمد بن عبيد الله في خبره عن الزيادي الكلبي فرجع النعمان من وجهه وقال لعدي ائتني الليلة إذا هدأت الرجل لتعلم حالي فأتاه فوجده قد لبس المسوح وتنصر وترهب وخرج سائحا على وجهه فلا يدرى ما كانت حاله فتنصر ولده بعده وبنوا البيع والصوامع وبنت هند بنت النعمان بن المنذر بن النعمان بن المنذر الدير الذي بظهر الكوفة ويقال له دير هند فلما حبس كسرى النعمان الأصغر أباها ومات في حبسه ترهبت هند ولبست المسوح وأقامت في ديرها مترهبة حتى ماتت فدفنت فيه","topic":"ذكر عدى بن زيد ونسبه وقصته ومقتله","topicNo":8,"sp":13,"spl":"سبب تنصر النعمان","partialRef":{"sid":"b8-17","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b8-19","bab":"الجزء 2","sec":"رأي المؤلف في تنصر النعمان","page":"ج2 ص128","text":"قال مؤلف هذا الكتاب إنما ذكرت الخبر الذي رواه الزيادي على ما فيه من التخليط لأني إذا أتيت بالقصة ذكرت كل ما يروى في معناها وهو خبر مختلط لأن عدي بن زيد إنما كان صاحب النعمان بن المنذر وهو المحبوس والنعمان الأكبر لا يعرفه عدي ولا رآه ولا هو جد النعمان الذي صحبه عدي كما ذكر ابن زياد وقد ذكرت نسب النعمان آنفا ولعل هذا النعمان الذي ذكره عم النعمان بن المنذر الأصغر بن المنذر الأكبر والمتنصر السائح على وجهه ليس عدي بن زيد أدخله في النصرانية وكيف يكون هو المدخل له في النصرانية وقد ضربه مثلا للنعمان في شعره لما حبسه مع من ضربه مثلا له من الملوك السالفة حدثنا بخبر ذلك الملك جعفر بن محمد الفريابي وأحمد بن عبد العزيز ابن الجعد الوشاء قالا حدثنا إسحاق بن البهلول الأنباري قال حدثنا أبي البهلول\nابن حسان التنوخي قال حدثني إسحاق بن زياد من بني سامة بن لؤي عن شبيب بن شيبة عن خالد بن صفوان بن الأهتم قال أوفدني يوسف بن عمر إلى هشام بن عبد الملك في وفد أهل العراق قال فقدمت عليه وقد خرج بقرابته وحشمه وغاشيته وجلسائه فنزل في أرض قاع صحصح منيف أفيح في عام قد بكر وسميه وتتابع وليه وأخذت الأرض فيه زينتها على اختلاف ألوان نبتها من نور ربيع مونق فهو في أحسن منظر وأحسن مختبر وأحسن مستمطر بصعيد كأن ترابه قطع الكافور قال وقد ضرب له سرادق من حبرة كان يوسف بن عمر صنعه له باليمن فيه فسطاط فيه أربعة أفرشة من خز أحمر مثلها مرافقها وعليه دراعة من خز أحمر مثلها عمامتها وقد أخذ الناس مجالسهم قال فأخرجت رأسي من ناحية السماط فنظر إلي شبه المستنطق لي فقلت أتم الله عليك يا أمير المؤمنين نعمه وجعل ما قلدك من هذا الأمر رشدا وعاقبة ما يؤول إليه حمدا وأخلصه لك بالتقى وكثره لك بالنماء ولا كدر عليك منه ما صفا ولا خالط سروره بالردى فلقد أصبحت للمؤمنين ثقة ومستراحا إليك يقصدون في مظالمهم ويفزعون في أمورهم وما\nأجد شيئا يا أمير المؤمنين هو أبلغ في قضاء حقك وتوقير مجلسك وما من الله جل وعز علي به من مجالستك من أن أذكرك نعم الله عليك وأنبهك لشكرها وما أجد في ذلك شيئا هو أبلغ من حديث من سلف قبلك من الملوك فإن أذن أمير المؤمنين أخبرته به قال فاستوى جالسا وكان متكئا ثم قال هات يابن الأهتم قال قلت يا أمير المؤمنين إن ملكا من الملوك قبلك خرج في عام مثل عامك هذا إلى الخورنق والسدير في عام قد بكر وسميه وتتابع وليه وأخذت الأرض فيه زينتها على اختلاف ألوان نبتها في ربيع مونق فهو في أحسن منظر وأحسن مختبر بصعيد كأن ترابه قطع الكافور وقد كان أعطي فتاء السن مع الكثرة والغلبة والقهر فنظر فأبعد النظر ثم قال لجلسائه لمن مثل هذا هل رأيتم مثل ما أنا فيه وهل أعطي أحد مثل ما أعطيت قال وعنده رجل من بقايا حملة الحجة والمضي على أدب الحق ومنهاجه قال ولم تخل الأرض من قائم لله بحجة في عباده فقال أيها الملك إنك سألت عن أمر أفتأذن في الجواب عنه قال نعم قال أرأيت هذا الذي أنت فيه أشيء لم تزل فيه أم شيء صار إليك ميراثا وهو زائل عنك وصائر إلى غيرك كما صار إليك قال كذلك هو قال فلا أراك إلا عجبت بشيء يسير تكون فيه قليلا وتغيب عنه طويلا وتكون غدا بحسابه مرتهنا قال ويحك فأين المهرب وأين المطلب قال إما أن تقيم في ملكك فتعمل فيه بطاعة الله ربك على ما ساءك\nوسرك وأومضك وأرمضك وإما أن تضع تاجك وتخلع أطمارك وتلبس أمساحك وتعبد ربك حتى يأتيك أجلك قال فإذا كان السحر فاقرع علي بابي فإني مختار أحد الرأيين وربما قال إحدى المنزلتين فإن اخترت ما أنا فيه كنت وزيرا لا يعصى و إن اخترت فلوات الأرض وقفر البلاد كنت رفيقا لا يخالف قال فقرع عليه عند السحر بابه فإذا هو قد وضع تاجه وخلع أطماره ولبس أمساحه و تهيأ للسياحه فلزما و الله الجبل حتى أتاهما أجلهما وهو حيث يقول عدي بن زيد أخو بني تميم\n(أيها الشامت المعير بالدهر ... أأنت المبرأ الموفور)\n(أم لديك العهد الوثيق من الأيام ... بل أنت جاهل مغرور)\n(من رأيت المنون خلدن أم من ذا ... عليه من أن يضام خفير)\n(أين كسرى كسرى الملوك أنو شيروان ... أم أين قبله سابور)\n(وبنو الأصفر الكرام ملوك الروم ... لم يبق منهم مذكور)\n(وأخو الحضر إذ بناه و إذ دجلة ... تجبى إليه والخابور)","topic":"ذكر عدى بن زيد ونسبه وقصته ومقتله","topicNo":8,"sp":14,"spl":"رأي المؤلف في تنصر النعمان"},
{"id":"b8-20","bab":"الجزء 2","sec":"رأي المؤلف في تنصر النعمان","page":"ج2 ص128","text":"(شاده مرمرا وجلله كلسا فللطير في ذراه وكور ... )\n(لم يهبه ريب المنون فباد الملك عنه فبابه مهجور ... )\n(وتذكر رب الخورنق إذ ا أشرف يوما وللهدى تفكير ... )\n(سره ماله وكثرة ما يملك والبحر معرضا والسدير ... )\n(فارعوى قلبه فقال و ما غبطه حي إلى الممات يصير ... )\n(ثم بعد الفلاح و الملك و الإمة ارتهم هناك القبور ... )\n(ثم صاروا كأنهم ورق جف فألوت به الصبا و الدبور ... )\nقال فبكى و الله هشام حتى أخضل لحيته وبل عمامته وأمر بنزع أبنيته و بنقلان قرابته وأهله وحشمه وغاشيته من جلسائه و لزم قصره فأقبلت الموالي والحشم على خالد بن صفوان فقالوا ما أردت إلى أمير المؤمنين أفسدت عليه لذته و نغصت عليه مأدبته فقال إليكم عني فإني عاهدت الله عز و جل ألا أخلو بملك إلا ذكرته الله عز و جل","topic":"ذكر عدى بن زيد ونسبه وقصته ومقتله","topicNo":8,"sp":15,"spl":"رأي المؤلف في تنصر النعمان","partial":1},
{"id":"b8-21","bab":"الجزء 2","sec":"أخبار الحضر والخورنق","page":"ج2 ص133","text":"فأما خبر الحضر وصاحبه والخورنق وصاحبه فإني أذكر خبرهما هاهنا لأنه مما يحسن ذكره بعقب هذه الأخبار ولايستغنى عنه والشيء يتبع الشىء أخبري بخبره إبراهيم بن السري عن أبيه عن شعيب عن سيف و أخبرني به الحسن بن علي قال حدثنا الحارث بن محمد قال حدثنا محمد بن سعد عن الواقدي و أخبرني به علي بن سليمان الأخفش في كتاب المغتالين عن السكري عن محمد بن حبيب عن ابن الأعرابي عن المفضل بن سلمه الضبي و هشام بن الكلبي عن أبيه و إسحاق بن الجصاص عن الكوفيين أن الحضر كان قصرا بحيال تكريت بين دجله والفرات وأن أخا الحضر الذي ذكره عدي بن زيد هو الضيزن بن معاوية بن العبيد بن الأجرام بن عمرو بن النخع بن سليح من بني تزيد بن حلوان بن عمران بن الحاف بن قضاعه و أمه جبهلة امرأة من بني تزيد بن حلوان أخي سليح بن حلوان وكان لا يعرف إلا بأمه هذه وكان ملك تلك الناحية وسائر أرض الجزيرة وكان معه من بني الأجرام ثم من بني العبيد بن الأجرام وسائر قبائل قضاعة ما لا يحصى وكان ملكه قد\nبلغ الشأم فأغار الضيزن فأصاب أختا لسابور ذي الأكتاف وفتح مدينة نهر شير و فتك فيهم فقال في ذلك عمرو بن السليح بن حدي بن الدها بن غنم بن حلوان ابن عمران بن الحاف بن قضاعة\n(لقيناهم بجمع من علاف ... وبالخيل الصلادمه الذكور)\n(فلاقت فارس منا نكالا ... وقتلنا هرابذ شهرزور)\n(دلفنا للاعاجم من بعيد ... بجمع م الجزيرة كالسعير)\nالوا ثم إن سابور ذا الأكتاف جمع لهم وسار إليهم فأقام على الحضر أربع سنين لا يستغل منهم شيئا ثم إن النضيرة بنت الضيزن عركت أي حاضت فأخرجت إلى الربض وكانت من أجمل أهل دهرها وكذلك كانوا يفعلون\nبنسائهم إذا حضن وكان سابور من أجمل أهل زمانه فراها وراته وعشقها وعشقته فأرسلت إليه ما تجعل لي إن دللتك على ما تهدم به هذه المدينة وتقتل أبي قال أحكمك وأرفعك على نسائي وأخصك بنفسي دونهن قالت عليك بحمامة مطوقة ورقاء فاكتب في رجليها بحيض جارية بكر تكون زرقاء ثم أرسلها فإنها تقع على حائط المدينة فتتداعى المدينة وكان ذلك طلسمها لايهدمها إلا هو ففعل و تأهب لهم و قالت له أنا أسقي الحرس الخمر فإذا صرعوا فاقتلهم وادخل المدينة ففعل فتداعت المدينة وفتحها سابور عنوة فقتل الضيزن يومئذ وأباد بني العبيد وأفنى قضاعة الذين كانوا مع الضيزن فلم يبق منهم باق يعرف إلى اليوم وأصيب قبائل حلوان و انقرضوا و درجوا فقال في ذلك عمرو بن آلة وكان مع الضيزن\n(ألم يحزنك و الأنباء تنمي ... بما لاقت سراة بني العبيد)\n(ومصرع ضيزن وبني أبيه ... وأحلاس الكتائب من تزيد)\n(أتاهم بالفيول مجللات ... و بالأبطال سابور الجنود)\n(فهدم من أواسي الحضر صخرا ... كأن ثقاله زبر الحديد)\nقال فأخرب سابور المدينة واحتمل النضيرة بنت الضيزن فأعرس بها بعين التمر فلم تزل ليلتها تتضور من خشانة في فرشها وهي من حرير محشو بالقز فالتمس ما كان يؤذيها فإذا هي ورقة آس ملتصقة بعكنة من عكنها قد أثرت فيها قال وكان ينظر إلى مخها من لين بشرتها فقال لها سابور ويحك بأي شيء كان أبوك يغذيك قالت بالزبد والمخ وشهد الأبكار من النحل وصفوة الخمر فقال وأبيك لأنا أحدث عهدا بمعرفتك وآثر لك من أبيك الذي غذاك بما تذكرين ثم أمر رجلا فركب فرسا جموحا وضفر غدائرها بذنبه ثم استركضه فقطعها قطعا فذلك قول الشاعر\n(أقفر الحضر من نضيرة فالمرباع ... منها فجانب الثرثار)\nالوا وكان الضيزن صاحب الحضر يلقب الساطرون وقال غيرهم بل الساطرون صاحب الحضر كان رجلا من أهل باجرمى والله أعلم أي ذلك كان","topic":"ذكر عدى بن زيد ونسبه وقصته ومقتله","topicNo":8,"sp":16,"spl":"أخبار الحضر والخورنق"},
{"id":"b8-22","bab":"الجزء 2","sec":"أخبار الحضر والخورنق","page":"ج2 ص133","text":"هذا خبر صاحب الحضر الذي ذكره عدي وأما صاحب الخورنق فهو النعمان بن الشقيقة وهو الذي ساح على وجهه فلم يعرف له خبر والشقيقة أمه بنت أبي ربيعة بن زهر بن شيبان وهو النعمان ابن امرىء القيس بن عمرو بن عدي بن نصر بن ربيعة بن الضخم اللخمي وهو صاحب الخورنق فذكر ابن الكلبي في خبره الذي قدمنا ذكره ورواية علي بن الصباح إياه عنه أنه كان سبب بنائه الخورنق أن يزدجرد بن سابور كان لا يبقى له ولد فسأل عن منزل مريء صحيح من الأدواء والأسقام فدل على ظهر الحيرة فدفع ابنه بهرام جور بن يزدجرد إلى النعمان بن الشقيقة وكان عامله على أرض العرب وأمره بأن يبني الخورنق مسكنا له ولابنه وينزله إياه معه وأمره بإخراجه إلى بوادي العرب وكان الذي بنى الخورنق رجلا يقال له سنمار فلما فرغ من بنائه عجبوا من حسنه وإتقان عمله فقال لو علمت أنكم توفوني أجرتي وتصنعون بي ما أستحقه لبنيته بناء يدور مع الشمس حيثما دارت فقالوا وإنك لتبني ما هو أفضل منه ولم تبنه ثم أمر به فطرح من أعلى الجوسق وقال في بعض الروايات أنه قال له إني لأعرف في هذا القصر موضع عيب إذا هدم تداعى القصر أجمع فقال له أما والله لا تدل عليه أحدا أبدا ثم رمي به من أعلى القصر فقالت الشعراء في ذلك أشعارا كثيرة منها قول أبي الطمحان القيني\n(جزاء سنمار جزوها وربها ... وبالللات والعزى جزاء المكفر)\nومنها قول سليط بن سعد\n(جزى بنوه أبا الغيلان عن كبر ... وحسن فعل كما يجزى سنمار)\nقال عبد العذى بن امرىء القيس الكلبي وكان أهدى إلى الحارث بن مارية الغساني أفراسا ووفد إليه فأعجب به واختصه وكان للملك ابن مسترضع في بني عبد ود من كلب فنهشته حية فظن الملك أنهم اغتالوه فقال لعبد العزى جئني بهؤلاء القوم فقال هم قوم أحرار ليس لي عليهم فضل في نسب ولا فعل فقال لتأتيني بهم أو لأفعلن وأفعلن فقال له رجونا من حبائك أمرا حال دونه عقابك ودعا ابنيه شراحيل وعبد الحارث فكتب معهما إلى قومه\n(جزاني جزاه الله شر جزائه ... جزاء سنمار وما كان ذا ذنب)\n(سوى رصه البنيان عشرين حجة ... يعلي عليه بالقراميد والسكب)\nوهي أبيات قال فقتله النعمان وكان أمره قد عظم وحعل معه كسرى كتيبتين إحداهما يقال لها دوسر وهي لتنوخ والأخرى الشهباء وهي للفرس وكانتا أيضا تسميان القبيلتين وكان يغزو بهما بلاد الشأم وكل من لم يدن له من العرب فجلس يوما يشرف من الخورنق فأعجبه ما رأى من ملكه ثم\nذكر باقي خبره مثل ما ذكره خالد بن صفوان لهشام من مخاطبة الواعظ وجوابه وما كان من اختياره السياحة وتركه ملكه","topic":"ذكر عدى بن زيد ونسبه وقصته ومقتله","topicNo":8,"sp":17,"spl":"أخبار الحضر والخورنق"},
{"id":"b8-23","bab":"الجزء 2","sec":"رثاء النابغة للنعمان","page":"ج2 ص139","text":"أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني عبد الله بن عمرو قال ذكر ابن حمزة عن مشايخه أن النعمان بن المنذر لما نعي إلى النابغة الذبياني وحدث بما صنع به كسرى قال طلبه من الدهر طالب الملوك ثم تمثل\n(من يطلب الدهر تدكه مخالبه ... والدهر بالوتر ناج غير مطلوب)\n(ما من أناس ذوي مجد ومكرمة ... إلا يشد عليهم شدة الذيب)\n(حتى يبيد على عمد سراتهم ... بالنافذات من النبل المصاييب)\n(إني وجدت سهام الموت معرضة ... بكل حتف من الآجال مكتوب)\nفي سائر قصائد عدي بن زيد التي كتب بها إلى النعمان يستعطفه ويعتذر إليه أغان منها صوت\n(لم أر مثل الفتيان في غبن الأيام ... ينسون ما عواقبها)\n(ينسون إخوانهم ومصرعهم ... وكيف تعتاقهم مخالبها)\n(ماذا ترجي النفوس من طلب الخير ... وحب الحياة كاربها)\n(تظن أن لن يصيبها عنت الدهر ... وريب المنون صائبها)\nيروى عقب الدهر يقول الأيام تغبن الناس فتخدعهم وتختلهم مثل الغبن في البيع وتعتاقهم تحبسهم يقال اعتاقه واعتقاه وكاربها هاهنا غامها وهو في موضع آخر القريب منها يقال كربه الأمر وكرثه وبهضه وغنظه إذا غمه الغناء في هذه الأبيات لابن محرز خفيف رمل بالوسطى عن عمرو بن بانة وفيها رمل بالبنصر نسبه حبش ودنانير إلى حنين ونسبه الهشامي وابن المكي إلى الهذلي ومنها صوت\n(يا لبيني أوقدي النارا ... إن من تهوين قد حارا)\n(رب نار بت أرمقها ... تقضم الهندي والغارا)\n(عندها ظبي يؤرثها ... عاقد في الجيد تقصارا)\nروضه من المديد حار يحير هنا ضل وحار في موضع آخر رجع والغار شجر طيب الريح والغار أيضا شجر السوس والغار الغيرة ويؤرثها يوقدها ويكثر حطبها والتقصار المخنقة الغناء لحنين خفيف ثقيل أول بالسبابة في مجرى الوسطى عن إسحاق وفيه خفيف رمل يقال إنه لعريب أخبرني محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق وأخبرنا\nبه يحيى بن علي عن داود بن محمد عن حماد بن إسحاق عن أبيه عن ابن عائشة عن يونس النحوي قال مات رجل من جند أهل الشأم عظيم القدر له فيهم عز وعدد فحضر الحجاج جنازته وصلى عليه وجلس على قبره وقال لينزل إليه بعض إخوانه فنزل نفر منهم فقال أحدهم وهو يسوي عليه رحمك الله أبا قنان إن كنت ما علمت لتجيد الغناء وتسرع رد الكأس ولقد وقعت في موضع سوء لا تخرج منه والله إلى يوم القيامة قال فما تمالك الحجاج أن ضحك وكان لا يكثر الضحك في جد ولا هزل فقال له أهذا موضع هذا لا أم لك فقال أصلح الله الأمير فرسه حبيس في سبيل الله لو سمعه الأمير وهو يغني\n(يا لبينى أوقدي النارا ... إن من تهوين قد حارا)\nلانتشر الأمير على سعنة وكان الميت يلقب بسعنة فقال إنا لله أخرجوه من القبر ما أبين حجة أهل العراق في جهلكم يا أهل الشأم قال وكان سعنة هذا الميت من أوحش خلق الله كلهم صورة وأذمهم قامة فلم يبق أحد حضر القبر إلا استفرغ ضحكا ومنها من قصيدة التي أولها\n(لمن الدار تعفت بخيم ... )\nوت\n(وثلاث كالحمامات بها ... بين مجثاهن توشيم االحمم)\n(أسأل الدار وقد أنكرتها ... عن حبيبي فإذا فيها صمم)\nويروى توشيم العجم والتوشيم أراد به آثار الوقود قد صار فيها كالوشم والثلاث يعني الأثافي التي تنصب عليها القدر الغناء لإبراهيم خفيف ثقيل أول مطلق في مجرى البنصر عن عمرو وابن المكي وفيه لحكم لحن من كتاب إبراهيم غير مجنس وهذه القصيدة التي أولها\n(لمن الدار تعفت بخيم ... أصبحت غيرها طول القدم)\n(ما تبين العين من آياتها ... غير نؤي مثل خط بالقلم)\nوبعده\n(وثلاث كالحمامات بها ... بين مجثاهن توشيم الحمم)\nعلى هذا خفض قوله وثلاث كالحمامات ومنها قوله\n(كفى غير الأيام للمرء وازعا ... )\nوت\n(بنات كرام لم يربن بضرة ... دمى شرقات بالعبير روادعا)\n(يسارقن م الأستار طرفا مفترا ... ويبرزن من فتق الخدور الأصابعا)\nبنات كرام موضعه نصب وهو يتبع ما قبله وينصب به وهو قوله\n(وأصبي ظباء في الدمقس خواضعا ... )\nبنات كرام هكذا في القصيدة على تواليها وقد يجوز رفعه على الابتداء ويروى بضرة وبضرة جمعا بالضم والفتح والدمى الصور واحدتها دمية الغناء في\nهذين البيتين لابن قندح ثقيل أول بالبنصر عن عمرو وذكر الهشامي أنه لمحمد ابن إسحاق بن عمرو بن بزيع وذكر حبش أنه لإبراهيم ومنها صوت\n(أرقت لمكفهر بات فيه ... بوارق يرتقين رؤوس شيب)","topic":"ذكر عدى بن زيد ونسبه وقصته ومقتله","topicNo":8,"sp":18,"spl":"رثاء النابغة للنعمان","partialRef":{"sid":"b8-4","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b8-24","bab":"الجزء 2","sec":"رثاء النابغة للنعمان","page":"ج2 ص139","text":"(تروح المشرفية في ذراه ... ويخلو صفحة الذيل القشيب)\nوالمكفهر والمكرهف السحاب المتوالي المتراكب والشيب السحائب التي فيها سواد وبياض شبهها بالرؤوس الشيب وقال قوم بل شيب جبل معروف شبه البرق في السحاب بلمعان السيوف ورواه ابن الأعرابي\n(ويجلو صفح دخدار قشيب ... )\nوقال الدخدار الثوب المصون وهو أعجمي معرب أصله تخت دار والقشيب الجديد الغناء لعريب ثقيل أول بالبنصر ومنها من قصيدة التي أولها\n(الأيا طال ليلي والنهار ... )\nصوت\n(ألا من مبلغ النعمان عني ... علانية فقد ذهب السرار)\n(بأن المرء لم يخلق حديدا ... ولا هضبا توقاه الوبار)\n(ولكن كالشهاب فثم يخبو ... وحادي الموت عنه مايحار)\n(فهل من خالد إما هلكنا ... وهل بالموت ياللناس عار)\nالهضب الجبل الوبارجمع وبر والشهاب السراج ويخبو يطفأ الغناء لبابويه ثقيل أول بالبنصر عن حبش والهشامي صوت\n(ألا من مبلغ النعمان عني ... فبينا المرء أغرب إذ أراحا)\n(أطعت بني بقيلة في وثاقي ... وكنا في حلوقهم ذباحا)\n(منحتهم الفرات وجانبيه ... وتسقينا الأواجن والملاحا)\nالغناء لحنين خفيف ثقيل أول بالسبابة في مجرى الوسطى عن إسحاق ومنها صوت\n(من لقلب دنف أو معتمد ... قد عصى كل نصيح ومفد)\n(لست إن سلمى نأتني دارها ... سامعا فيها إلى قول أحد)\nالمعتمد الذي عمده الوجع يعمده عمدا غناه ابن محرز ولحنه خفيف ثقيل\nالوبارجمع وبر والشهاب السراج ويخبو يطفأ الغناء لبابويه ثقيل أول بالبنصر عن حبش والهشامي ومنها صوت\n(ألا من مبلغ النعمان عني ... فبينا المرء أغرب إذ أراحا)\n(أطعت بني بقيلة في وثاقي ... وكنا في حلوقهم ذباحا)\n(منحتهم الفرات وجانبيه ... وتسقينا الأواجن والملاحا)\nالغناء لحنين خفيف ثقيل أول بالسبابة في مجرى الوسطى عن إسحاق ومنها صوت\n(من لقلب دنف أو معتمد ... قد عصى كل نصيح ومفد)\n(لست إن سلمى نأتني دارها ... سامعا فيها إلى قول أحد)\nالمعتمد الذي عمده الوجع يعمده عمدا غناه ابن محرز ولحنه خفيف ثقيل\nبالسبابة في مجرى النصر عن إسحاق وفيه لمالك خفيف ثقيل أخر بالوسطى عن عمرو وذكر يونس أن فيه لمالك لحنا ولسنان الكاتب لحنا وهو ثقيل أول بالوسطى عن حبش ومنها صوت\n(أروح أرواح مودع أم بكور ... لك فاعمد لأي حال تصير)\n(ويقول العداة أودى عدي ... وعدي بسخط رب أسير)\n(أيها الشامت المعير بالدهر ... أأنت المبرأ الموفور)\n(أم لديك العهد الوثيق من ألأيام ... بل أنت جاهل مغرور)\nيريد أرواح نودعك فيه أم بكور أيهما تريد فاعمد للذي تصير إليه من أمر آخرتك والموفور الذي لم تصبه نوائب الدهر الغناء لحنين من كتاب يونس ولم يذكر طريقته وذكر حماد بن إسحاق عن أبيه أن حنينا غناه خالدا القسري أيام حرم الغناء فرق له وقال غني ولا تعاشر سفيها ولا معربدا والخبر في ذلك يذكر في أخبار حنين ومما يغنى فيه أيضا من شعر عدي صوت\n(ألا يا ربما عز خليلي فتهاونت ... )\n(ولو شئت على مقدرة مني لعاقبت ... )\n(ولكن سرني أن يعلموا ... قدري فأقلعت)\n(ألا لا فاسألوا الفتية ... ما قالوا وقد قمت)\nلغناء لسياط رمل عن الهشامي وفيه ليحيى المكي خفيف ثقيل نسبه إلى مالك وليس له ولعريب في البيتين الأولين ثقيل أول وبعدهما بيت ليس من الشعر وهو\n(ولكن حبيبى جل عندي فتغافلت ... )\nومما يغنى فيه شعره صوت\n(تعرف أمس من لميس الطلل ... مثل الكتاب المدارس الأحول)\nالذي قد درس فلا يقرأ\n(أنعم صباحا علقم بن عدي ... أثويت اليوم أم ترحل)\n(قد رحل الفتيان عيرهم ... واللحم بالغيطان لم ينشل)\n(إذ هي تسبي الناظرين وتجلوا ... واضحا كالأقحوان رتل)\nالرتل المستوي البنية\n(عذبا كما ذقت الجني من التفاح ... مسقيا ببرد الطل)\nهكذا يغنى والذي قاله عدي يسقيه برد الطل الغناء لحنين رمل بالوسطى عن عمرو","topic":"ذكر عدى بن زيد ونسبه وقصته ومقتله","topicNo":8,"sp":19,"spl":"رثاء النابغة للنعمان","partialRef":{"sid":"b8-8","gi":1,"vi":1,"side":1},"partial":1},
{"id":"b8-25","bab":"الجزء 2","sec":"رثاء النابغة للنعمان","page":"ج2 ص139","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه عن ابن الكلبي أن عمرو بن امرىء القيس المكنى بأبي سريح وعلقمة بن عدي وقيل علقم بن عدي بن كعب وعمرو بن هند خرجوا إلى الصيد فأتوا قصر ابن مقاتل فمكثوا فيه يتصيدون فزعموا أن علقمة بن عدي تبع حمارا فصرعه والشمس لم تطلع ثم لحق آخر فطعنه فانقصف الرمح فيه ومر به فرسه يركض فجال به العير فضربه فأصاب صدره فقتله وقيل إن الرمح المنقصف دخل في صدره فقتله وذلك في أيام الربيع وكان عدي بن زيد معهم وإليه قصدوا وكان نازلا في قصر ابن مقاتل فقال عدي هذه القصيدة يرثيه بها صوت","topic":"ذكر عدى بن زيد ونسبه وقصته ومقتله","topicNo":8,"sp":20,"spl":"رثاء النابغة للنعمان — من المائة المختارة"},
{"id":"b8-26","bab":"الجزء 2","sec":"من المائة المختارة","page":"ج2 ص147","text":"(عفا من سليمى مسحلان فحامره ... تمشى به ظلمانه وجاذره)\n(بمستأسد القريان عاف نباته ... فنواره ميل إلى الشمس زاهره)\n(رأت عارضا جونا فقامت غريرة ... بمسحاتها قبل الظلام تبادره)\n(فما برحت حتى أتى الماء دونها ... وسدت نواحيه ورفع دابره)\nعروضه من الطويل عفا درس مسحلان موضع وحامره موضع أضافه إلى مسحلان والظلمان ذكور النعام واحدها ظليم والجآذر أولاد البقر وأحدها جؤذر وجؤذر بضم الذال وفتحها وتمشى تكثر المشي والقريان مجاري الماء إلى الرياض واحدها قري والمستأسد ما ألتف منها وطال والنوار يقال إنه يكون أبدا حيال الشمس يستقبلها بوجهه فيقول إن نوار هذه الروضة يميل زاهره حيال الشمس والعارض السحاب والجون الأسود والغريرة الناعمة التي لم تجرب الأمور يقول لما رأت هذه المرأة السحابة السوداء قامت بمسحاتها تصلح النؤي حوالي بيتها وهو الحاجز بينه وبين الأرض المستوية وقوله رفع دابره أي مؤخره الذي يلي الماء من النؤي الشعر للحطيئة يهجو الزبرقان بن بدر والغناء لابن عائشة ولحنه المختار خفيف رمل بإطلاق الوتر في مجرى الوسطى عن إسحاق وذكر حبش أن له فيه لحنا آخر من الثقيل الثاني","topic":"ذكر عدى بن زيد ونسبه وقصته ومقتله","topicNo":8,"sp":20,"spl":"رثاء النابغة للنعمان — من المائة المختارة"},
{"id":"b9-1","bab":"الجزء 2","sec":"خبر الحطيئة ونسبه والسبب الذي من أجله هجا الزبرقان بن بدر","page":"ج2 ص149","text":"الحطيئة لقب لقب به وامه جرول بن أوسمه بن مالك بن جؤية بن مخزوم ابن مالك بن غالب بن قطيعة بن عبس بن بغيض بن الريث بن غطفان بن سعد ابن قيس بن عيلان بن مضر بن نزار وهو من فحول الشعراء ومتقدميهم وفصحائهم متصرف في جميع فنون الشعر من المديح والهجاء والفخر والنسيب مجيد في ذلك أجمع وكان ذا شر وسفه ونسبه متدافع بين قبائل العرب وكان ينتمي إلى كل واحدة منها إذا غضب على الآخرين وهو مخضرم أدرك الجاهلية والأسلام فأسلم ثم ارتد وقال في ذلك\n(أطعنا رسول الله إذ كان بيننا ... فيا لعباد الله ما لأبي بكر)\n(أيورثها بكرا إذا مات بعده ... وتلك لعمر الله قاصمة الظهر)\nيكنى الحطيئة أبا مليكة وقيل إن الحطيئة غلب عليه ولقب به لقصره وقربه من الأرض وقال حماد الراوية قال أبو نصر الأعرابي سمي الحطيئة لأنه ضرط ضرطة بين قوم فقيل له ما هذا فقال إنما هي حطيئة فسمي الحطيئة وقال المدائني قال أبو اليقظان كان الحطيئة يدعي أنه ابن عمرو بن\nعلقمة أحد بني الحارث بن سدوس قال وسمي الحطيئة لقربه من الأرض أخبرني الفضل بن الحباب الجمحي أبو خليفة في كتابه إلي بإجازته لي يذكر عن محمد بن سلام أن الحطيئة كان ينتمي إلى بني ذهل بن ثعلبة فقال\n(إن اليمامة خير ساكنها ... أهل القرية من بني ذهل)\nال والقرية منازلهم ولم ينبت الحطيئة في هؤلاء وأخبرني محمد بن الحسن بن دريد قال حدثني عمي عن ابن الكلبي قال سمعت خراش بن إسماعيل وخالد بن سعيد يقولان كان الحطيئة إذا غضب على بني عبس يقول أنا من بني ذهل وإذا غضب على بني ذهل قال أنا من بني عبس أخبرني الحسين بن يحيى الرداسي قال قال حماد بن إسحاق قال أبي قال ابن الكلبي كان الحطيئة مغموز النسب وكان من أولاد الزنا الذين شرفوا قال إسحاق وقال الأصمعي كان الحطيئة يضرب بنسبه إلى بكر بن وائل فقال في ذلك\n(قومي بنو عوف بن عمرو إن أراد العلم عالم ... )\n(قوم إذاذهبت خضرم ... منهم خلفت خضارم)\n(لا يفشلون ولا تبيت على أنوفهم المخاطم ... )\nال الأصمعي وقدم الحطيئة الكوفة فنزل في بني عوف بن عامر بن ذهل يسألهم وكان يزعم أنه منهم وقال في ذلك\n(سيري أمام فإن المال يجمعه ... سيب الإله وإقبالي وإدباري)\n(إلى معاشر منهم يا أمام أبي ... من آ ' ل عوف بدوء غير أشرار)\n(نمشي على ضوء أحساب أضأن لنا ... ما ضوأت ليلة القمراء للساري)","topic":"خبر الحطيئة ونسبه والسبب الذي من أجله هجا الزبرقان بن بدر","topicNo":9,"sp":0,"spl":"خبر الحطيئة ونسبه والسبب الذي من أجله هجا الزبرقان بن بدر","partial":1},
{"id":"b9-2","bab":"الجزء 2","sec":"الحطيئة وقصته مع اخوته وأمه","page":"ج2 ص151","text":"وقال ابن دريد في خبره عن عمه عن ابن الكلبي عن أبيه وحماد بن إسحاق عن أبيه عن ابن الكلبي عن أبيه قال كان أوس بن مالك بن جؤية بن مخزوم بن مالك بن غالب بن قطيعة بن عبس تزوج بنت رياح بن عمرو بن عوف ابن الحارث بن سدوس بن شيبان بن ذهل بن ثعلبة وكان له أمة يقال لها الضراء فأعلقها بالحطيئة ورحل عنها وكان لبنت رياح أخ يقال له الأفقم وكان طويلا أفقم صغير العينين مضغوط اللحيين فولدت الضراء الحطيئة فجاءت به شبيها بالأفقم فقالت لها مولاتها من أين هذا الصبي فقالت لها من أخيك وهوابت أن تقول لها من زوجك فشبهته بأخيها فقالت لها صدقت ثم مات أوس وترك ابنين من الحرة وتزوج الضراء رجل من بني عبس فولدت له رجلين فكانا أخوي الحطيئة من أمه فأعتقت بنت رياح الحطيئة وربته فكان كأنه أحدهما وترك الأفقم نخلا باليمامة فأتى الحطيئة أخويه من أوس بن مالك وقد كانت أمه لما أعتقتها بنت رياح اعترفت أنها اعتلقت من أوس بن مالك فقال لهم\nأفردوا إلي من مالكم قطعة فقالا لا ولكن أقم معنا فنحن نواسيك فقال\n(أأمرتماني أن أقيم عليكما ... كلا لعمر أبيكما الحباق)\n(عبدان خيرهما يشل بضبعه ... شل الأجير قلائص الوراق)\nقال وسأل الحطيئة أمه من أبوه فخلطت عليه فقال\n(تقول لي الضراء لست لواحد ... ولا اثنين فانظر كيف شرك أولئكا)\n(وأنت امرؤ تبغي أبا قد ضللته ... هبلت ألما تستفق من ضلالكا)\nال وغضب عليها فلحق بإخوته بني الأفقم فقال\n(سيري أمام فإن المال يجمعه ... سيب الإله وإقبالي وإدباري)\nال فلم يدفعوه ولم يقبلوه فقال\n(إن اليمامة خير ساكنها ... أهل القرية من بني ذهل)\nوسألهم ميراثه من الأفقم فأعطوه نخلات من نخل أبيهم تدعى نخلات أم مليكة وأم مليكة امرأة الحطيئة فقال\n(ليهنى تراثي لامرىء غير ذلة ... صنابير أحدان لهن حفيف)\nال ثم لم تقنعه النخيلات وقد أقام فيهم زمانا فسألهم ميراثه كاملا من الأفقم فلم يعطوه شيئا وضربوه فغضب عليهم وقال\n(تمنيت بكرا أن يكونوا عمارتي ... وقومي وبكر شر تلك القبائل)\n(إذا قلت بكري نبوتم بحاجتي ... فياليتني من غير بكر بن وائل)\nفعاد إلى بني عبس وانتسب إلى أوس بن مالك وقال الأصمعي في خبره لما أتى أهل القرية وهم بنو ذهل يطلب ميراثه من الأفقم مدحهم فقال\n(إن اليمامة خير ساكنها ... أهل القرية من بني ذهل)\n(الضامنون لمال جارهم ... حتى يتم نواهض البقل)\n(قوم إذا انتسبوا ففرعهم ... فرعي وأثبت أصلهم أصلي)\nقال فلم يعطوه شيئا فقال يهجوهم\n(إن اليمامة شر ساكنها ... أهل القرية من بني ذهل)\nوقال أبو اليقظان في خبره كان الرجل الذي تزوج أم الحطيئة أيضا ولد زنا اسمه الكلب بن كنيس بن جابر بن قطن بن نهشل وكان كنيس زنى بأمة لزرارة يقال لها رشية فولدت له الكلب ويربوعا فطلبهم من زرارة فمنعه منهم فلما مات طلبهم من أبيه لقيط فمنعه وقال لقيط في ذلك\n(أفي نصف شهر ما صبرتم لحقنا ... ونحن صبرنا قبل ذاك سنينا)\nوهي ابيات فتزوج الكلب الضراء أم الحطيئة فهجاه الحطيئة وهجا أمه فقال\n(ولقد رأيتك في النساء فسؤتني ... وأبا بنيك فساءني في المجلس)\n(أن الذليل لمن تزور ركابه ... رهط ابن جحش في الخطوب الحوس)\n(قبح الإله قبيلة لم يمنعوا ... يوم المجيمر جارهم من فقعس)\n(أبلغ بني جحش بأن نجارهم ... لؤم وأن أباهم كالهجرس)\nوقال الحطيئة يهجو أمه\n(جزاك الله شرا من عجوز ... ولقاك العقوق من البنين)\n(فقد ملكت أمر بنيك حتى ... تركتهم أدق من الطحين)\n(فإن تخلي وأمرك لا تصولي ... بمشتد قواه ولا متين)\n(لسانك مبرد لا خير فيه ... ودرك در جاذبة دهين)\nوقال يهجو أمه أيضا\n(تنحي فاجلسي مني بعيدا ... أراح الله منك العالمينا)\n(أغربالا إذا استودعت سرا ... وكانونا على المتحدثينا)\n(حياتك ما علمت حياة سوء ... وموتك قد يسر الصالحينا)","topic":"خبر الحطيئة ونسبه والسبب الذي من أجله هجا الزبرقان بن بدر","topicNo":9,"sp":1,"spl":"الحطيئة وقصته مع اخوته وأمه"},
{"id":"b9-3","bab":"الجزء 2","sec":"الحطيئة وقصته مع اخوته وأمه","page":"ج2 ص151","text":"أخبرني محمد بن الحسن بن دريد قال أخبرني عبد الرحمن ابن أخي الأصمعي عن عمه قال كان الحطيئة جشعا سؤولا ملحفا دنيء النفس كثير الشر قليل الخير بخيلا قبيح المنظر رث الهيئة مغموز النسب فاسد الدين وما تشاء أن تقول في شعر شاعر من عيب إلا وجدته وقلما تجد ذلك في شعره أخبرني ابن دريد قال أخبرنا أبو حاتم عن أبي عبيدة قال بخلاء العرب أربعة الحطيئة وحميد الأرقط وأبو الأسود الدؤلي وخالد بن صفوان أخبرنا ابن دريد قال حدثنا أبو حاتم قال قال أبوعبيدة كان الحطيئة بذيا هجاء فالتمس ذات يوم إنسانا يهجوه فلم يجده وضاق عليه ذلك فأنشأ يقول\n(أبت شفتاي اليوم إلا تكلما ... بشر فما أدري لمن أنا قائله)\nوجعل يدهور هذا البيت في أشداقه ولا يرى إنسانا إذ اطلع في ركي أو\nحوض فرأى وجهه فقال\n(أرى لي وجها شوه الله خلقه ... فقبح من وجه وقبح حامله)","topic":"خبر الحطيئة ونسبه والسبب الذي من أجله هجا الزبرقان بن بدر","topicNo":9,"sp":2,"spl":"الحطيئة وقصته مع اخوته وأمه — هجاء الحطيئة يخيف قريش وسادات العرب"},
{"id":"b9-4","bab":"الجزء 2","sec":"هجاء الحطيئة يخيف قريش وسادات العرب","page":"ج2 ص156","text":"نسخت من كتاب الحرمي بن أبي العلاء حدثنا الزبير بن بكار قال حدثني عمي قال قدم الحطيئة المدينة فأرصدت قريش له العطايا خوفا من شره فقام في المسجد فصاح من يحملني على بغلين أخبرني أبو خليفة قال حدثنا محمد بن سلام وأخبرني الحسين بن يحيى المرداسي قال حدثنا حماد بن إسحاق عن أبيه قال قال أبو عبيدة والمدائني ومصعب كان الحطيئة سؤولا جشعا فقدم المدينة وقد أرصدت له قريش العطايا والناس في سنة مجدبة وسخطة من خليفة فمشى أشراف أهل المدينة بعضهم إلى بعض فقالوا قد قدم علينا هذا الرجل وهو شاعر والشاعر يظن فيحقق وهو يأتي الرجل من أشرافكم يسأله فإن أعطاه جهد نفسه بهرها وإن حرمه هجاه فأجمع رأيهم على أن يجعلوا له شيئا معدا يجمعونه بينهم له فكان أهل البيت من قريش والأنصار يجمعون له العشرة والعشرين والثلاثين دينارا حتى جمعوا له اربعمائة دينار وظنوا أنهم قد أغنوه فأتوه فقالوا له هذه صلة آل فلان\nوهذه صلة آل فلان وهذه صلة فلان فأخذها فظنوا أنهم قد كفوه عن المسألة فإذا هو يوم الجمعة وقد استقبل الإمام مائلا ينادي من يحملني على بغلين وقاه الله كبة جهنم ووصف أبو عبيدة ومحمد بن سلام شعر الحطيئة فجمعت متفرق ما وصفاه به في هذا الخبر أخبرنا به أبو خليفة عن محمد بن سلام وابن دريد عن أبي حاتم عن أبي عبيدة قالا كان الحطيئة متين الشعر شرود القافية وكان دنيء النفس وما تشاء أن تطعن في شعر شاعر إلا وجدت فيه مطعنا وما أقل ما تجد ذلك في شعره قالا فبلغ من دناءة نفسه أنه أتى كعب بن زهير وكان الحطيئة راوية زهير وآل زهير فقال له قد علمت روايتي لكم أهل البيت وانقطاعي إليكم وقد ذهب الفحول غيري وغيرك فلو قلت شعرا تذكر فيه نفسك وتضعني موضعا بعدك وقال أبو عبيدة تبدأ بنفسك فيه ثم تثني بي فإن الناس لأشعاركم أروى وإليها أسرع فقال كعب\n(فمن للقوافي شانها من يحوكها ... إذا ما ثوى كعب وفوز جرول)\n(كفيتك لا تلقى من الناس واحدا ... تنخل منها مثل ما نتنخل)\n(نقول فلا نعيا بشيء نقوله ... ومن قائليها من يسيء ويجمل)\n(نثقفها حتى تلين متونها ... فيقصر عنها كل ما يتمثل)\nقال فاعترضه مزرد بن ضرار واسمه يزيد وهو أخو الشماخ وكان عريضا أي شديد العارضة كثيرها فقال\n(باستك إذ خلفتني خلف شاعر ... من الناس لم أكفىء ولم أتنحل)\n(فإن تخشبا أخشب وإن تتنخلا ... وإن كنت أفتى منكما أتنخل)\n(فلست كحسان الحسام ابن ثابت ... ولست كشماخ ولا كالمخبل)\nسخت من كتاب الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني محمد بن الضحاك قال أنشد الحطيئة عمر بن الخطاب رضي الله عنه قصيدة نال فيها من قومه ومدح إبله فقال\n(مهاريس يروي رسلها ضيف أهلها ... إذا الريح أبدت أوجه الخفرات)\n(يزيل القتاد جذبها بأصوله ... إذا أصبحت مقورة خرصات)","topic":"خبر الحطيئة ونسبه والسبب الذي من أجله هجا الزبرقان بن بدر","topicNo":9,"sp":2,"spl":"الحطيئة وقصته مع اخوته وأمه — هجاء الحطيئة يخيف قريش وسادات العرب"},
{"id":"b9-5","bab":"الجزء 2","sec":"الحطيئة مكرم أينما حل","page":"ج2 ص159","text":"أخبرني عمي قال حدثنا الكراني عن التوزي عن أبي عبيدة قال بينا سعيد ابن العاص يعشي الناس بالمدينة والناس يخرجون أولا أولا إذ نظر على بساطه إلى رجل قبيح المنظر رث الهيئة جالس مع أصحاب سمره فذهب الشرط يقيمونه فأبى أن يقوم وحانت من سعيد التفاتة فقال دعوا الرجل فتركوه وخاضوا في أحاديث العرب وأشعارها مليا فقال لهم الحطيئة والله ما أصبتم جيد الشعر ولا شاعر العرب فقال له سعيد أتعرف من ذلك شيئا قال نعم قال فمن أشعر العرب قال الذي يقول\n(لا أعد الإقتار عدما ولكن ... فقد من قد رزئته الإعدام)\nوأنشدها حتى أتى عليها فقال له من يقولها قال أبو داود الإيادي قال ثم من قال الذي يقول\n(أفلح بما شئت فقد يدرك بالجهل ... وقد يخدع الأريب)\nثم أنشدها حتى فرغ منها قال ومن يقولها قال عبيد بن الأبرص قال ثم من قال والله لحسبك بي عند رغبة أو رهبة إذا رفعت إحدى رجلي علي\nالأخرى ثم عويت في أثر القوافي عواء الفصيل الصادي قال ومن أنت قال الحطيئة قال فرحب به سعيد ثم قال أسأت بكتماننا نفسك منذ الليلة ووصله وكساه ومضى لوجهه إلى عتيبة بن النهاس العجلي فسأله فقال له ما أنا على عمل فأعطيك من عدده ولا في مالي فضل عن قومي قال له فلا عليك وانصرف فقال له بعض قومه لقد عرضتنا ونفسك للشر قال وكيف قالوا هذا الحطيئة وهو هاجينا أخبث هجاء فقال ردوه فردوه إليه فقال له لم كتمتنا نفسك كأنك كنت تطلب العلل علينا اجلس فلك عندنا ما يسرك فجلس فقال له من أشعر الناس قال الذي يقول\n(ومن يجعل المعروف من دون عرضه ... يفره ومن لا يتق الشتم يشتم)\nفقال له عتيبة إن هذا من مقدمات أفاعيك ثم قال لوكيله اذهب معه إلى السوق فلا يطلب شيئا إلا اشتريته له فجعل يعرض عليه الخز ورقيق الثياب فلا يريدها ويومىء إلى الكرابيس والأكسية الغلاظ فيشتريها له حتى قضى أربه ثم مضى فلما جلس عتيبة في نادي قومه أقبل الحطيئة فلما رآه عتيبة قال هذا مقام العائذ بك يا أبا مليكة من خيرك وشرك قال قد كنت قلت بيتين فاستمعهما ثم أنشأ يقول\n(سئلت فلم تبخل ولم تعط طائلا ... فسيان لا ذم عليك ولا حمد)\n(وأنت امرؤ لا الجود منك سجية ... فتعطي ولا يعدي على النائل الوجد)\nثم ركض فرسه فذهب أخبرني الحسين بن يحيى ومحمد بن مزيد البوشنجي قالا حدثنا حماد بن إسحاق قال حدثني محمد بن عمرو الجرجرائي عن أبي صفوان الأحوزي قال ما من أحد إلا لو أشاء أن أجد في شعره مطعنا لوجدته إلا الحطيئة قال حماد وسمعت أبي يقول وقد أنشد قول الحطيئة\n(وفتيان صدق من عدي عليهم ... صفائح بصرى علقت بالعواتق)\n(إذا ما دعوا لم يسألوا من دعاهم ... ولم يمسكوا فوق القلوب الخوافق)\n(وطاروا إلى الجرد العتاق فألجموا ... وشدوا على أوساطهم بالمناطق)\n(أولئك آباء الغريب وغاثة الصريخ ... ومأوى المرملين الدرادق)\n(أحلوا حياض الموت فوق جباههم ... مكان النواصي من وجوه السوابق)\nيروى\n(إذا استلحموا . . . . ... . وإذا ركبوا لم ينظروا عن شمالهم)\nويروى أولئك أبناء العزيف ثم قال أما إني ما أزعم أن أحدا بعد زهير أشعر من الحطيئة\nأخبرني الحسين بن يحيى عن حماد بن إسحاق عن أبيه قال بلغني أنه لما قال ابن ميادة\n(تمشى به ظلمانه وجآذره ... )\nقيل له لقد سبقك الحطيئة إلى هذا فقال والله ما علمت أن الحطيئة قال هذا قط والآن علمت والله أني شاعر حين واطأت الحطيئة قال حماد قال أبي وقال لي الأصمعي وقد أنشدني شيئا من شعر الحطيئة أفسد مثل هذا الشعر الحسن بهجاء الناس وكثرة الطمع قال حماد قال أبي وبلغني عن عبد الرحمن بن أبي بكرة أنه قال لقيت الحطيئة بذات عرق فقلت له يا أبا مليكة من أشعر الناس فأخرج لسانه كأنه لسان الحية ثم قال هذا إذا طمع ونسخت من كتاب أحمد بن سعيد الدمشقي قال حدثنا الزبير قال حدثني يحيى بن محمد بن طلحة وكان قد قارب ثمانين سنة قال أخبرني بعض أشياخنا أن أعرابيا وقف على حسان بن ثابت وهو ينشد فقال\nله حسان كيف تسمع يا أعرابي قال ما أسمع بأسا قال حسان أما تسمعون إلى الأعرابي ما كنيتك أيها الرجل قال أبو مليكة قال ما كنت قط أهون علي منك حين اكتنيت بامرأة فما اسمك قال الحطيئة فأطرق حسان ثم قال له أمض بسلام","topic":"خبر الحطيئة ونسبه والسبب الذي من أجله هجا الزبرقان بن بدر","topicNo":9,"sp":3,"spl":"الحطيئة مكرم أينما حل","partial":1},
{"id":"b9-6","bab":"الجزء 2","sec":"بعض صفات الحطيئة","page":"ج2 ص163","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه عن المدائني قال مر ابن الحمامة بالحطيئة وهو جالس بفناء بيته فقال السلام عليكم فقال قلت ما لا ينكر قال إني خرجت من عند أهلي بغير زاد فقال ما ضمنت لأهلك قراك قال أفتأذن لي أن آتي ظل بيتك فأتفيأ به قال دونك الجبل يفيء عليك قال أنا ابن الحمامة قال انصرف وكن ابن أي طائر شئت وأخبرنا بهذا الخبر اليزيدي عن الخزاز عن المدائني فحكى ما ذكرناه من قول الحطيئة عن أبي الأسود الدؤلي وأخبرني الحسين عن حماد عن أبيه عن أبي عبيدة والمدائني قالا\nأتى رجل الحطيئة وهو في غنم له فقال له يا صاحب الغنم فرفع الحطيئة العصا وقال إنها عجراء من سلم فقال الرجل إني ضيف فقال للضيفان أعددتها فانصرف عنه قال إسحاق وقال غيرهما إن الرجل قال له السلام عليكم فقال له عجراء من سلم فقال السلام عليكم فقال أعددتها للطراق فأعاد السلام فقال له إن شئت قمت بها إليك فانصرف الرجل عنه أخبرني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد قال زعم الجاحظ أن الحطيئة كان يقول إنما أنا حسب موضوع فسمع عمرو بن عبيد رجلا يحكي ذلك عنه يقال له عبد الرحمن بن صديقة فقال عمرو كذب ترحه الله إنما ذلك التقوى أخبرني الحسين بن يحيى عن حماد بن إسحاق عن أبيه قال قال الأصمعي لم ينزل ضيف قط بالحطيئة إلا هجاه فنزل به رجل من بني أسد لم يسمه الأصمعي وذكر أبو عبيدة أنه صخر بن أعيى ألأسدي أحد بني أعيى بن طريف بن عمرو بن قعين فسقاه شربة من لبن فلما شربها قال\n(لما رأيت أن من يبتغي القرى ... وأن ابن أعيى لا محالة فاضحي)\n(شددت حيازيم ابن أعيى بشربة ... على ظمإ سدت أصول الجوانح)\nوروى الأصمعي شدت بالشين المعجمة\n(ولم أك مثل الكاهلي وعرسه ... بغى الود من مطروفة العين طامح)\n(غدا باغيا يبغي رضاهاوودها ... وغابت له غيب امرىء غير ناصح)\n(دعت ربها ألا يزال بفاقة ... ولا يغتدي إلا على حد بارح)\nقال فأجابه صخر بن أعيى فقال\n(ألا قبح الله الحطيئة إنه ... على كل ضيف ضافه هو سالح)\n(دفعت إليه وهو يخنق كلبه ... ألا كل كلب لا أبا لك نابح)\n(بكيت على مذق خبيث قريته ... ألا كل عبسي على الزاد شائح)\nقال أبو عبيدة وهجا الحطيئه أيضا رجلا من أضيافه فقال\n(وسلم مرتين فقلت مهلا ... كفتك المرة الأولى السلاما)\n(ونقنق بطنه ودعا رؤاسا ... لما قد نال من شبع وناما)\nأخبرني أبو خليفة عن محمد بن سلام عن يونس أن الحظيئة خرج في سفر له ومعه امراته أمامة وابنته مليكة فنزل منزلا وسرح ذودا له ثلاثا فلما قام للرواح فقد إحداها فقال\n(أذئب القفر أم ذئب أنيس ... أصاب البكر أم حدث الليالي)\n(ونحن ثلاثة وثلاث ذود ... لقد جار الزمان على عيالي)","topic":"خبر الحطيئة ونسبه والسبب الذي من أجله هجا الزبرقان بن بدر","topicNo":9,"sp":4,"spl":"بعض صفات الحطيئة"},
{"id":"b9-7","bab":"الجزء 2","sec":"لا يذهب العرف بين الله والناس","page":"ج2 ص166","text":"أخبرني محمد بن خلف وكيع والحسين بن يحيى قالا حدثنا حماد عن أبيه قال قال أبو عمرو بن العلاء لم تقل العرب بيتا قط أصدق من بيت الحطيئة\n(من يفعل الخير لا يعدم جوازيه ... لا يذهب العرف بين الله والناس)\nفقيل له فقول طرفة\n(ستبدي لك الأيام ما كنت جاهلا ... ويأتيك بالأخبار من لم تزود)\nفقال من يأتيك بها ممن زودت أكثر وليس بيت مما قالته الشعراء إلا وفيه مطعن إلا قول الحطيئة\n(لا يذهب العرف بين الله والناس ... )\nقال إسحاق قال المدائني قال سلم بن قتيبة ما أعلم قافية تستغني عن صدرها وتدل عليه وإن لم ينشد مثل قول الحطيئة\n(لا يذهب العرف بين الله والناس ... )\nخبرني محمد بن الحسن بن دريد قال حدثنا الرياشي قال سمعت\nالأصمعي يقول كتبت للحطيئة في ليلة أربعين قصيدة أخبرني الحسين بن يحيى عن حماد عن أبيه عن أبي عبيدة قال بلغني أن هذا البيت في التوراة ذكره غير واحد عن أبي بن كعب يعني قول الحطيئة\n(لا يذهب العرف بين الله والناس ... )\nال إسحاق وذكر عبد الله بن مروان عن أيوب بن عثمان الدمشقي عن عثمان ابن أبي عائشة قال سمع كعب الحبر رجلا ينشد بيت الحطيئة\n(من يفعل الخير لا يعدم جوازيه ... لا يذهب العرف بين الله والناس)\nفقال والذي نفسي بيده إن هذا البيت لمكتوب في التوراة قال إسحاق قال العمري والذي صح عندنا في التوراة لا يذهب العرف بين الله والعباد أخبرني الحسين عن حماد عن أبيه قال قال أبو عدنان لما حضرت عبيد الله ابن شداد الوفاة دعا ابنه محمد فأوصاه وقال له يا بني أرى داعي الموت لا يقلع وبحق أن من مضى لا يرجع ومن بقي فإليه ينزع يا بني ليكن أولى الأمور بك تقوى الله في السر والعلانية والشكر لله وصدق الحديث والنية فإن للشكر مزيدا والتقوى خير زاد كما قال الحطيئة\n(ولست أرى السعادة جمع مال ... ولكن التقي هو السعيد)\n(وتقوى الله خير الزاد ذخرا ... وعند الله للأتقى مزيد)\n(وما لا بد أن يأتي قريب ... ولكن الذي يمضي بعيد)\nخبرني ابو خليفة عن محمد بن سلام قال أخبرني أبو عبيدة عن يونس قال قدم حماد الراوية البصرة على بلال بن أبي بردة وهو عليها فقال له ما أطرفتني شيئا يا حماد قال بلى ثم عاد إليه فأنشده للحطيئة في أبي موسى الأشعري يمدحه\n(جمعت من عامر فيه ومن جشم ... ومن تميم ومن حاء ومن حام)\n(مستحقبات رواياها جحافلها ... يسمو بها أشعري طرفه سامي)\nفقال له بلال ويحك أيمدح الحطيئة أبا موسى الأشعري وأنا أروي شعر\nالحطيئة كله فلا أعرفها ولكن أشعها تذهب في الناس وذكر المدائني أن الحطيئة قال هذه القصيدة في أبي موسى وأنها صحيحة قالها فيه وقد جمع جيشا للغزو فأنشده\n(جمعت من عامر فيه ومن أسد ... )\nذكر البيتين وبينهما هذا البيت وهو\n(فما رضيتهم حتى رفدتهم ... بوائل رهط ذي الجدين بسطام)\nفوصله أبو موسى فكتب إليه عمر رضي الله عنه يلومه على ذلك فكتب إليه إني اشتريت عرضي منه بها فكتب إليه عمر إن كان هذا هكذا وإنما فديت عرضك من لسانه ولم تعطه للمدح والفخر فقد أحسنت ولما ولى بلال بن أبي بردة أنشده إياها حماد الراوية فوصله أيضا ونسخت من كتاب لحماد بن إسحاق حدثني به أبي وأخبرني به عمي عن الكراني عن الرياشي قال حدثني محمد بن الطفيل عن أبي بكر بن عياش عن الحارث بن عبد الرحمن عن مكحول قال سبق رسول اللهعلى فرس له فجثا على ركبتيه وقال إنه لبحر قال عمر كذب الحطيئة حيث يقول\n(وإن جياد الخيل لا تستفزنا ... ولا جاعلات الريط فوق المعاصم)\nلو ترك هذا أحد لتركه الرسول أخبرني الحسين بن يحيى عن حماد عن أبيه عن أبي عبيدة أن الحطيئة أراد سفرا فأتته امرأته وقد قدمت راحلته ليركب فقالت\n(أذكر تحنننا إليك وشوقنا ... واذكر بناتك إنهن صغار)\nفقال حطوا لا رحلت لسفر ابدا أخبرني محمد بن العباس اليزيدي ومحمد بن الحسن بن دريد قالا حدثنا عبد الرحمن ابن أخي الأصمعي عن عمه عن أبيه قال قال رجل ضفت قوما في سفر وقد ضللت الطريق فجاؤوني بطعام أجد طعمه في فمي وثقله في بطني ثم قال شيخ منهم لشاب أنشد عمك فأنشدني\n(عفا من سليمى مسحلان فحامره ... تمشى به ظلمانه وجآذره)\nفقلت له أليس هذا للحطيئة فقال بلى وأنا صاحبه من الجن أخبرني الحسين بن يحيى عن حماد عن أبيه قال قال ابن عيينة سمعت ابن شبرمة يقول أنا والله أعلم بجيذ الشعر لقد أحسن الحطيئة حيث يقول","topic":"خبر الحطيئة ونسبه والسبب الذي من أجله هجا الزبرقان بن بدر","topicNo":9,"sp":5,"spl":"لا يذهب العرف بين الله والناس","partial":1},
{"id":"b9-8","bab":"الجزء 2","sec":"لا يذهب العرف بين الله والناس","page":"ج2 ص166","text":"(أولئك قوم إن بنوا أحسنوا البنى ... وإن عاهدوا أوفوا وإن عقدوا وشدوا)\n(وإن كانت النعماء فيهم جزوا بها ... وإن أنعموا لا كدروها ولا كدوا)\n(وإن قال مولاهم على جل حادث ... من الدهر ردوا فضل أحلامكم ردوا)\nال وقال الأصمعي وقد سأله أبو عدنان عن هذا البيت ما واحد البنى قال بنية فقال له أتجمع فعلة على فعل قال نعم مثل رشوة ورشى وحبوة وحبى حدثنا أحمد بن عبيد الله بن عمار قال حدثني محمد بن أحمد بن صدقة الأنباري قال حدثنا ابن الأعرابي عن المفضل\nإن الحطيئة أقحمته السنة فنزل ببني مقلد بن يربوع فمشى بعضهم إلى بعض وقالوا إن هذا الرجل لا يسلم أحد من لسانه فتعالوا حتى نسأله عما يحب فنفعله وعما يكره فنجتنبه فأتوه فقالوا له يا أبا مليكة إنك اخترتنا على سائر العرب ووجب حقك علينا فمرنا بما تحب أن نفعله وبما تحب أن ننتهي عنه فقال لا تكثروا زيارتي فتملوني ولا تقطعوها فتوحشوني ولا تجعلوا فناء بيتي مجلسا لكم ولا تسمعوا بناتي غناء شبانكم فإن الغناء رقية الزنا قال فأقام عندهم وجمع كل رجل منهم ولده وقال أمكم الطلاق لئن تغنى أحد منكم والحطيئة مقيم بين أظهرنا لأضربنه ضربة بسيفي أخذت منه ما أخذت فلم يزل مقيما فيما يرضى حتى انجلت عنه السنة فارتحل وهو يقول\n(جاورت آل مقلد فحمدتهم ... إذ ليس كل أخي جوار يحمد)\n(أيام من يرد الصنيعة يصطنع ... فينا ومن يرد الزهادة يزهد)","topic":"خبر الحطيئة ونسبه والسبب الذي من أجله هجا الزبرقان بن بدر","topicNo":9,"sp":6,"spl":"لا يذهب العرف بين الله والناس"},
{"id":"b9-9","bab":"الجزء 2","sec":"الحطيئة والزبرقان","page":"ج2 ص171","text":"فأما خبره مع الزبرقان بن بدر والسبب في هجائه إياه فأخبرني به أبو خليفة عن محمد بن سلام ولم يتجاوزه به وأخبرني الحسين ين يحيى عن حماد عن أبيه عن محمد بن سلام عن يونس وأخبرني محمد بن الحسن بن دريد عن أبي حاتم عن أبي عبيدة وأخبرني اليزيدي عن عمه عبيد الله عن أبي حبيب عن ابن\nالأعرابي وقد جمعت رواياتهم وضممت بعضها إلى بعض أن النبيكان ولى الزبرقان بن بدر بن امرىء القيس بن خلف بن بهدلة بن عوف ببن كعب بن سعد بن زيد مناة بن تميم عملا وذكر مثل ذلك الأصمعي وقال الزبرقان القمر والزبرقان الرجل الخفيف اللحية قال وأقره أبو بكر رضي الله عنه بعد النبيعلى عمله ثم قدم على عمر في سنة مجدبة ليؤدي صدقات قومه فلقيه الحطيئة بقرقرى ومعه ابناه أوس وسوادة وبناته وامرأته فقال له الزبرقان وقد عرفه ولم يعرفه الحطيئة أين تريد قال العراق فقد حطمتنا هذه السنة قال وتصنع ماذا قال وددت أن أصادف بها رجلا يكفيني مؤونة عيالي وأصفيه مدحي أبدا فقال له الزبرقان قد أصبته فهل لك فيه يوسعك لبنا وتمرا ويجاورك أحسن جوار وأكرمه فقال له الحطيئة هذا وأبيك العيش وما كنت أرجو هذا كله قال فقد أصبته قال عند من قال عندي قال ومن أنت قال الزبرقان بن بدر قال وأين محلك قال اركب هذا الإبل واستقبل مطلع الشمس وسل عن القمر حتى تأتي منزلي قال يونس وكان اسم الزبرقان الحصين بن بدر وإنما سمي الزبرقان لحسنه شبه بالقمر وقيل بل لبس عمامة مزبرقة بالزعفران فسمي الزبرقان لذلك وقال أبو عبيدة في خبره فقال له سر إلى أم شذرة وهي أم الزبرقان وهي أيضا عمة الفرزدق وكتب إليها أن أحسني إليه وأكثري له من التمر واللبن وقال آخرون بل وكله إلى زوجته فلحق الحطيئة بزوجته على رواية ابن سلام وهي بنت صعصعة بن ناجية المجاشعية واسمها هنيدة وعلى رواية أبي عبيدة أنها\nأمه وذلك في عام صعب مجدب فأكرمته المرأة وأحسنت إليه فبلغ ذلك بغيض بن عامر بن شماس بن لأي بن جعفر وهو أنف الناقه بن قريع بن عوف ابن كعب بن سعد بن زيد مناة بن تميم وبلغ إخوته وبني عمه فاغتنموها وفي خبر اليزيدي عن عمه قال ابن حبيب عن ابن الأعرابي وكانوا يغضبون من أنف الناقة وإنما سمي جعفر أنف الناقة لأن أباه قريعا نحر ناقة فقسمها بين نسائه فبعثت جعفرا هذا أمه وهي الشموس من وائل ثم من سعد هذيم فأتى أباه ولم يبق من الناقة إلا رأسها وعنقها فقال شأنك بهذا فأدخل يده في أنفها وجر ما أعطاه فسمي أنف الناقة وكان ذلك كاللقب لهم حتى مدحهم الحطيئة فقال\n(قوم هم الأنف والأذناب غيرهم ... ومن يسوي بأنف الناقة الذنبا)\nصار بعد ذلك فخرا لهم ومدحا وكانوا ينازعون الزبرقان الشرف يعني بغيضا وإخوته وأهله وكانوا أشرف من الزبرقان إلا أنه قد كان استعلاهم بنفسه وقال أبو عبيدة في خبره كان الحطيئة دميما سيء الخلق لا تأخذه العين ومعه عيال كذلك فلما رأت أم شذرة حاله هان عليها وقصرت به ونظر بغيض وبنو أنف الناقة إلى ما تصنع به أم شذرة فأرسلوا إليه إن ائتنا فأبى عليهم وقال إن من شأن النساء التقصير والغفلة ولست بالذي أحمل على صاحبها ذنبها فلما ألح عليه بنو أنف الناقة وكان رسولهم إليه شماس بن لأي وعلقمة بن هوذة وبغيض ابن شماس والمخبل الشاعر قال لهم لست بحامل على الرجل ذنب غيره فإن\nتركت وجفيت تحولت إليكم فأطمعوه ووعدوه وعد عظيما وقال ابن سلام في خبره فلما لم يجبهم دسوا إلى هنيدة زوجة الزبرقان إنما يريد أن يتزوج ابنته مليكة وكانت جميلة كاملة فظهرت من المرأة للحطيئة جفوة وهي في ذاك تداريه ثم أرادوا النجعة قال أبو عبيدة فقالت له أم شذرة وقال ابن سلام فقالت له هنيدة قد حضرت النجعة فاركب أنت وأهلك هذا الظهر إلى مكان كذا وكذا ثم اردده إلينا حتى نلحقك فإنه لا يسعنا جميعا فأرسل إليها بل تقدمي أنت فأنت أحق بذلك ففعلت وتثاقلت عن ردها إليه وتركته يومين أو ثلاثة وألح بنو أنف الناقة عليه وقالوا له قد تركت بمضيعة وكان أشدهم في ذلك قولا بغيض بن شماس وعلقمة بن هوذة وكان الزبرقان قد قال في علقمة\n(لي ابن عم لا يزال ... يعيبني ويعين عائب)\n(وأعينه في النائبات ... ولا يعين على النوائب)\n(تسري عقاربه إلي ... ولا تدب له عقارب)\n(لاه ابن عمك لا يخاف ... المحزنات من العواقب)","topic":"خبر الحطيئة ونسبه والسبب الذي من أجله هجا الزبرقان بن بدر","topicNo":9,"sp":7,"spl":"الحطيئة والزبرقان"},
{"id":"b9-10","bab":"الجزء 2","sec":"الحطيئة والزبرقان","page":"ج2 ص171","text":"ال فكان علقمة ممتلئا غيظا عليه فلما ألحوا على الحطيئة أجابهم وقال أما الآن فنعم أنا صائر معكم فتحمل معهم فضربوا له قبة وربطوا بكل طنب من أطنابها جلة هجرية وأراحوا عليه إبلهم وأكثروا له من التمر\nواللبن وأعطوه لقاحا وكسوة قال فلما قدم الزبرقان سأل عنه فأخبر بقصته فنادى في بني بهدلة بن عوف وهم لأم دون قريع أمهم السفعاء بنت غنم بن قتيبة من باهلة فركب الزبرقان فرسه وأخذ رمحه وسار حتى وقف على نادي بني شماس القريعيين فقال ردوا علي جاري فقالوا ما هو لك بجار وقد اطرحته وضيعته فألم أن يكون بين الحيين حرب فحضرهم أهل الحجا من قومهم فلاموا بغيضا وقالوا اردد على الرجل جاره فقال لست مخرجه وقد آويته وهو رجل حر مالك لأمره فخيروه فإن اختارني لم أخرجه وإن اختاره لم أكرهه فخيروا الحطيئة فاختار بغيضا ورهطه فجاء الزبرقان ووقف عليه وقال له أبا مليكة أفارقت جواري عن سخط وذم قال لا فانصرف وتركه هذه رواية ابن سلام وأما أبو عبيدة فإنه ذكر أنه كان بين الزبرقان ومن معه من القريعيين تلاح وتشاح وزعم غيرهما أن الزبرقان استعدى عمر بن الخطاب على بغيض فحكم عمر بأن يخرج الحطيئة حتى يقام في موضع خال بين الحيين وحده ويخلى سبيله ويكون جار أيهما اختار ففعل ذلك به فاختار القريعيين قال وجعل الحطيئة يمدحهم من غير أن يهجو الزبرقان وهم يحضونه على ذلك ويحرضونه فيأبى ويقول لا ذنب للرجل عندي حتى أرسل الزبرقان إلى رجل من النمر بن قاسط يقال له دثار بن شيبان فهجا بغيضا فقال\n(أرى إبلي بجوف الماء حلت ... وأعوزها به الماء الرواء)\n(وقد وردت مياه بني قريع ... فما وصلوا القرابة مذ أساؤوا)\n(تحلأ يوم ورد الناس إبلي ... وتصدر وهي محنقة ظماء)\n(ألم أك جار شماس بن لأي ... فأسلمني وقد نزل البلاء)\n(فقلت تحولي يا أم بكر ... إلى حيث المكارم والعلاء)\n(وجدنا بيت بهدلة بن عوف ... تعالى سمكه ودحا الفناء)\n(وما أضحى لشماس بن لأي ... قديم في الفعال ولا رباء)\n(سوى أن الحطيئة قال قولا ... فهذا من مقالته جزاء)\nحينئذ قال الحطيئة يهجو الزبرقان ويناضل عن بغيض قصيدته التي يقول فيها\n(والله ما معشر لاموا امرأ جنبا ... في آل لأي بن شماس بأكياس)\n(ما كان ذنب بغيض لا أبالكم ... في بائس جاء يحدو آخر الناس)\n(لقد مريتكم لو أن درتكم ... يوما يجيء بها مسحي وإبساسي)\n(وقد مدحتكم عمدا لأرشدكم ... كيما يكون لكم متحي وإمراسي)\n(لما بدا لي منكم غيب أنفسكم ... ولم يكن لجراحي فيكم آسي)\n(أزمعت يأسا مبينا من نوالكم ... ولن يرى طاردا للحر كالياس)\n(جار لقوم أطالوا هون منزله ... وغادروه مقيما بين أرماس)\n(ملوا قراه وهرته كلابهم ... وجرحوه بأنياب وأضراس)\n(دع المكارم لا ترحل لبغيتها ... واقعد فإنك أنت الطاعم الكاسي)\n(من يفعل الخير لا يعدم جوازيه ... لا يذهب العرف بين الله والناس)\n(ما كان ذنبي أن فلت معاولكم ... من آل لأي صفاة أصلها راسي)\n(قد ناضلوك فسلوا من كنائنهم ... مجدا تليدا ونبلا غير أنكاس)\nلجنب الغريب الإبساس أن يسكنها عند الحلب والماتح المستقي الذي يجذب الدلو من فوق والإمراس أن يقع الحبل في جانب البكرة فيخرجه فاستعدى عليه الزبرقان عمر بن الخطاب فرفعه عمر إليه واستنشده فأنشده فقال عمر لحسان أتراه هجاه قال نعم وسلح عليه فحبسه عمر","topic":"خبر الحطيئة ونسبه والسبب الذي من أجله هجا الزبرقان بن بدر","topicNo":9,"sp":8,"spl":"الحطيئة والزبرقان"},
{"id":"b9-11","bab":"الجزء 2","sec":"الحطيئة وعمر","page":"ج2 ص177","text":"أخبرني أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة قال حدثني أحمد بن معاوية عن أبي عبد الرحمن الطائي عن عبد الله بن عياش عن الشعبي قال شهدت زيادا وأتاه عامر بن مسعود بأبي علاثة التيمي فقال إنه هجاني قال وما قال لك قال قال\n(وكيف أرجي ثروها ونماءها ... وقد سار فيها خصية الكلب عامر)\nفقال أبو علاثة ليس هكذا قلت قال فكيف قلت قال قلت\n(وإني لأرجو ثروها ونماءها ... وقد سار فيها ناجذ الحق عامر)\nال زياد قاتل الله الشاعر ينقل لسانه كيف شاء والله لولا أن تكون سنة لقطعت لسانك فقام قيس بن فهد الأنصاري فقال أصلح الله الأمير ما أدري من الرجل فإن شئت حدثتك عن عمر بما سمعت منه قال وكان زياد يعجبه الحديث عن عمر رضي الله عنه قال هاته قال شهدته وأتاه الزبرقان بن بدر بالحطيئة فقال إنه هجاني قال وما قال لك قال قال لي\n(دع المكارم لا ترحل لبغيتها ... واقعد فإنك أنت الطاعم الكاسي)\nقال عمر ما أسمع هجاء ولكنهامعاتبة فقال الزبرقان أو ما تبلغ مروءتي إلا أن آكل وألبس فقال عمر علي بحسان فجيء به فسأله فقال لم يهجه ولكن سلح عليه قال ويقال إنه سأل لبيدا عن ذلك فقال ما يسرني أنه لحقني من هذا الشعر ما لحقه وأن لي حمر النعم فأمر به عمر فجعل في نقير في بئر ثم ألقي عليه شيء فقال\n(ماذا تقول لأفراخ بذي مرخ ... زغب الحواصل لا ماء ولا شجر)\n(ألقيت كاسبهم في قعر مظلمة ... فاغفر عليك سلام الله يا عمر)\n(أنت الإمام الذي من بعد صاحبه ... ألقى إليك مقاليد النهى البشر)\n(لم يؤثروك بها إذ قدموك لها ... لكن لأنفسهم كانت بك الأثر)\nفأخرجه وقال له إياك وهجاء الناس قال إذا يموت عيالي جوعا هذا مكسبي ومنه معاشي قال فإياك والمقذع من القول قال وما المقذع قال أن تخاير بين الناس فتقول فلان خير من فلان وآل فلان خير من آل فلان قال فأنت والله أهجى مني ثم قال والله لولا أن تكون سنة لقطعت لسانك ولكن اذهب فأنت له خذه يا زبرقان فألقى الزبرقان في عنقه عمامة فاقتاده بها وعارضته غطفان فقالوا له يا أبا شذرة إخوتك وبنو عمك هبه لنا فوهبه لهم فقال زياد لعامر بن مسعود قد سمعت ما روي عن عمر وإنما هي السنن فاذهب به فهو لك فألقى في عنقه حبلا أو عمامة وعارضته بكر بن وائل فقالوا له أخوالك وجيرانك فوهبه لهم أخبرني محمد بن الحسن بن دريد قال أخبرنا أبو حاتم عن أبي عبيدة أن الحطيئة لما حبسه عمر قال وهو أول ما قاله\n(أعوذ بجدك إني امرؤ ... سقتني الأعادي إليك السجالا)\n(فإنك خير من الزبرقان ... أشد نكالا وأرجى نوالا)\n(تحنن علي هداك المليك ... فإن لكل مقام مقالا)\n(ولا تأخذني بقول الوشاة ... فإن لكل زمان رجالا)\n(فإن كان ما زعموا صادقا ... فسيقت إليك نسائي رجالا)\n(حواسر لا يشتكين الوجا ... يخفضن ألا ويرفعن آلا)\nفلم يلتفت عمر إليه حتى قال أبياته التي أولها\n(ماذا تقول لأفراخ بذي مرخ ... )\nخبرني الحرمي بن أبي العلاء ومحمد بن العباس اليزيدي وعمر بن عبد\nالعزيز بن أحمد وطاهر بن عبد الله الهشامي قالوا حدثنا الزبير بن بكار قال حدثني محمد بن الضحاك بن عثمان الحزامي قال حدثني عبد الله بن مصعب عن ربيعة بن عثمان عن زيد بن أسلم عن أبيه قال أرسل عمر إلى الحطيئة وأنا جالس عنده وقد كلمه فيه عمرو بن العاص وغيره فأخرجه من السجن فانشده قوله\n(ماذا تقول لأفراخ بذي مرخ ... زغب الحواصل لا ماء ولا شجر)\n(ألقيت كاسبهم في قعر مظلمة ... فاغفر عليك سلام الله يا عمر)\n(أنت الإمام الذي من بعد صاحبه ... ألقى إليك مقاليد النهى البشر)\n(لم يؤثروك بها إذ قدموك لها ... لكن لأنفسهم كانت بك الأثر)\n(فامنن على صبية بارزمل مسكنهم ... بين الأباطح تغشاهم بها القرر)\n(أهلي فداؤك كم بيني وبينهم ... من عرض داوية تعمى بها الخبر)\nال فبكى حين قال\n(ماذا تقول لأفراخ بذي مرخ ... )\nقال عمرو بن العاص ما أظلت الخضراء ولا أقلت الغبراء أعدل من رجل يبكي على تركه الحطئية فقال عمر علي بالكرسي فأتي به فجلس عليه ثم قال أشيروا علي في الشاعر فإنه يقول الهجر وينسب الحرم ويمدح الناس ويذمهم بغير ما فيهم ما أراني إلا قاطعا لسانه ثم قال علي بالطست فأتي بها","topic":"خبر الحطيئة ونسبه والسبب الذي من أجله هجا الزبرقان بن بدر","topicNo":9,"sp":9,"spl":"الحطيئة وعمر","partial":1},
{"id":"b9-12","bab":"الجزء 2","sec":"الحطيئة وعمر","page":"ج2 ص177","text":"ثم قال علي بالمخصف علي بالسكين لا بل علي بالموسى فهو أوجى فقالوا لا يعود يا أمير المؤمنين فأشاروا إليه أن قل لا أعود فقال لا أعود يا أمير المؤمنين فقال له النجاء قال فلما ولى قال له عمر يا حطيئة كأني بك عند فتى من قريش قد بسط لك نمرقة وكسر لك أخرى وقال غننا يا حطيئة فطفقت تغنيه بأعراض الناس قال ابن أسلم فما انقضت الدنيا حتى رأيت الحطيئة عند عبيد الله بن عمر قد بسط له نمرقة وكسر له أخرى وقال غننا يا حطيئة فجعل يغنيه فقلت له يا حطيئة أتذكر قول عمر ففزع وقال يرحم الله ذلك المرء أما إنه لو كان حيا ما فعلت قال وقلت لعبيد الله سمعت أباك يقول كذا وكذا فكنت أنت ذلك الرجل وروي عن عبد الله بن المبارك أن عمر رضي الله عنه لما أطلق الحطيئة أراد أن يؤكد عليه الحجة فاشترى منه أعراض المسلمين جميعا بثلاثة آلاف درهم فقال الحطيئة في ذلك\n(وأخذت أطراف الكلام فلم تدع ... شتما يضر ولا مديحا ينفع)\n(وحميتني عرض اللئيم فلم يخف ... دمي وأصبح آمنا لا يفزع)","topic":"خبر الحطيئة ونسبه والسبب الذي من أجله هجا الزبرقان بن بدر","topicNo":9,"sp":10,"spl":"الحطيئة وعمر — خبر الحطيئة مع ابن عوف وبني قريع"},
{"id":"b9-13","bab":"الجزء 2","sec":"خبر الحطيئة مع ابن عوف وبني قريع","page":"ج2 ص182","text":"أخبرني الحسين بن يحيى عن حماد بن إسحاق عن أبيه قال حدثني عبد الرحمن بن أخي الأصمعي عن عمه عن نافع بن أبي نعيم أن عبد الرحمن بن عوف هو الذي استرضى عمر بن الخطاب وكلمه في أمر الحطيئة حتى أخرجه من السجن قال حماد وأخبرني أبي عن أبي عبيدة أن عمر رضي الله عنه لما أطلقه قال الشاعر النمري الذي كان الزبرقان حمله على هجاء بغيض\n(دعاني الأثبجان ابنا بغيض ... وأهلي بالعلاة فمنياني)\n(وقالوا سر بأهلك فأتينا ... ألى حب وأنعام سمان)\n(فسرت إليهم عشرين شهرا ... وأربعة فذلك حجتان)\n(فلما أن أتيت ابني بغيض ... وأسلمني بدائي الداعيان)\n(يبيت الذئب والعثواء ضيفا ... لنا بالليل بئس الضائفان)\n(أمارس منهما ليلا طويلا ... أهجهج عن بني ويعروان)\n(تقول حليلتي لما اشتكينا ... سيدركنا بنو القرم الهجان)\n(سيدركنا بنو القمر بن بدر ... سراج الليل للشمس الحصان)\n(فقلت ادعي وأدعو إن أندى ... لصوت أن ينادي داعيان)\n(فمن يك سائلا عني فإني ... أنا النمري جار الزبرقان)\n(طريد عشيرة وطريد حرب ... بما اجترمت يدي وجنى لساني)\n(كأني إذ نزلت به طريدا ... نزلت على الممنع من أبان)\n(أتيت الزبرقان فلم يضعني ... وضيعني بتريم من دعاني)\nخبرني الحسين بن يحيى عن حماد بن إسحاق عن أبيه عن أبي عبيدة قال لم يزل الحطيئة في بني قريع يمدحهم حتى إذا أحيوا قالوا لبغيض ف لي بما كنت تضمنت فأتى بغيض علقمة بن هوذة فقال له قد جاء الله بالحيا فف لي بما قلت وكان قد ضمن له مائة بعير وأبرئني مما تضمنته عهدتي فقال نعم سل في بني قريع فمهما فضل بعد عطائهم أن يتم مائة أتممته ففعل فجمعوا له أربعين أو خمسين بعيرا كان الرجل يعطيه على قدر ماله البعير والبعيرين قال فأتمها علقمة له مائة وراعيين فدفعت إليه فلم يزل يمدحهم وهو مقيم بينهم حتى قال كلمته السينية واستعدى الزبرقان عليه عمر رضي الله عنه فلما رحل عنهم قال\n(لا يبعد الله إذ ودعت أرضهم ... أخي بغيضا ولكن غيره بعدا)\n(لا يبعد الله من يعطي الجزيل ومن ... يحبو الجليل وما أكدى ولا نكدا)\n(ومن تلاقيه بالمعروف مبتهجا ... إذا اجرهد صفا المذموم أو صلدا)\n(لاقيته ثلجا تندى أنامله ... إن يعطك اليوم لا يمنعك ذاك غدا)\n(إني لرافده ودي ومنصرتي ... وحافظ غيبه إن غاب أو شهدا)","topic":"خبر الحطيئة ونسبه والسبب الذي من أجله هجا الزبرقان بن بدر","topicNo":9,"sp":10,"spl":"الحطيئة وعمر — خبر الحطيئة مع ابن عوف وبني قريع"},
{"id":"b9-14","bab":"الجزء 2","sec":"الحطيئة لابن عباس أعلي جناح في هجاء الناس","page":"ج2 ص184","text":"أخبرني الحسن بن علي قال حدثنا محمد بن موسى قال حدثنا أحمد بن الحارث عن المدائني عن ابن دأب عن عبد الله بن عياش المنتوف قال بينا ابن عباس جالس في مجلس رسول الله كف بصره وحوله ناس من قريش إذ أقبل أعرابي يخطر وعليه مطرف وجبة وعمامة خز حتى سلم على القوم فردوا عليه السلام فقال يا بن عم رسول الله أفتني قال فيماذا قال أتخاف علي جناحا إن ظلمني رجل فظلمته وشتمني فشتمته وقصر بي فقصرت به فقال العفو خير ومن انتصر فلا جناح عليه فقال يا بن عم رسول الله أرأيت امرأ أتاني فوعدني وغرني ومناني ثم أخلفني و استخف بحرمتي أيسعني أن أهجوه قال لا يصلح الهجاء لأنه لا بد لك من أن تهجو غيره من عشيرته فتظلم من لم يظلمك وتشتم من لم يشتمك وتبغي على من لم يبغ عليك والبغي مرتع وخيم وفي العفو ما قد علمت من الفضل قال صدقت وبررت فلم ينشب أن أقبل عبد الرحمن بن سيحان المحاربي حليف قريش فلما رأى الأعرابي أجله وأعظمه وألطف في مسألته وقال قرب الله دارك يا أبا مليكة فقال ابن عباس أجرول قال جرول فإذا هو الحطيئة فقال ابن\nعباس لله أنت أي مردي قذاف وذائد عن عشيرة ومثن بعارفه تؤتاها أنت يا أبا مليكة والله لو كنت عركت بجنبك بعض ما كرهت من أمر الزبرقان كان خيرا لك ولقد ظلمت من قومه من لم يظلمك وشتمت من لم يشتمك قال إني والله بهم يا أبا العباس لعالم قال ما أنت بأعلم بهم من غيرك قال بلى والله يرحمك الله ثم أنشأ يقول\n(أنا ابن بجدتهم علما وتجربة ... فسل بسعد تجدني أعلم الناس)\n(سعد بن زيد كثير إن عددتهم ... ورأس سعد بن زيد آل شماس)\n(والزبرقان ذناباهم وشرهم ... ليس الذنابى أبا العباس كالراس)\nقال ابن عباس أقسمت عليك ألا تقول إلا خيرا قال أفعل ثم قال ابن عباس يا أبا مليكة من أشعر الناس قال أمن الماضين أم من الباقين قال من الماضين قال الذي يقول\n(ومن يجعل المعروف من دون عرضه ... يفره ومن لا يتق الشتم يشتم)\nوما بدونه الذي يقول\n(ولست بمستبق أخا لا تلمه ... على شعث أي الرجال المهذب)\nولكن الضراعة أفسدته كما أفسدت جرولا يعنى نفسه والله يا بن عم رسول الله لولا الطمع والجشع لكنت أشعر الماضين فأما الباقون فلا تشك أني أشعرهم وأصردهم سهما إذا رميت أخبرني أحمد بن عبيد الله بن عمار قال روي لنا عن أبي عبيدة والهيثم بن عدي وغيرهما أن عبد الله بن أبي ربيعة لما قدم من البحرين نزل على الزبرقان بن بدر بمائه فحلأه وهو الماء الذي يقال له بنيان فنزل على بني أنف الناقة بمائهم وهو الذي يقال له وشيع فأكرموه وذبحوا له شاة وقالوا لو كانت إبلنا منا قريبة لنحرنا لك فراح من عندهم يتغنى فيهم بقوله\n(وما الزبرقان يوم يمنع ماءه ... بمحتسب التقوى ولا متوكل)\n(مقيم على بنيان يمنع ماءه ... وماء وشيع ماء ظمآن مرمل)\nقال فركب الزبرقان إلى عمر رضي الله عنه فاستعداه على عبد الله وقال إنه هجاني يا أمير المؤمنين فسأل عمر عن ذلك عبد الله فقال له ياأمير المؤمنين إني نزلت على مائه فحلأني عنه فقال عمر رضوان الله عليه يا زبرقان أتمنع ماءك من ابن السبيل قال يا أمير المؤمنين ألا أمنع ماء حفر آبائي مجاريه ومستقره وحفرته أنا بيدي فقال عمر والذي نفسي بيده لئن بلغني أنك منعت ماءك من أبناء السبيل لا ساكنتني بنجد أبدا فقال بعض بني أنف الناقة يعير الزبرقان ما فعله\n(أتدري من منعت ورود حوض ... سليل خضارم منعوا البطاحا)\n(أزاد الركب تمنع أم هشاما ... وذا الرمحين أمنعهم سلاحا)\n(هم منعوا الأباطح دون فهر ... ومن بالخيف والبدن اللقاحا)\n(بضرب دون بيضتهم طلخف ... إذ الملهوف لاذ بهم وصاحا)\n(وما تدري بأيهم تلاقي ... صدور المشرفية والرماحا)","topic":"خبر الحطيئة ونسبه والسبب الذي من أجله هجا الزبرقان بن بدر","topicNo":9,"sp":11,"spl":"الحطيئة لابن عباس أعلي جناح في هجاء الناس"},
{"id":"b9-15","bab":"الجزء 2","sec":"وصية الحطيئة الظريفة","page":"ج2 ص187","text":"وللحطيئة وصية ظريفة يأتي كل فريق من الرواة ببعضها وقد جمعت ما وقع إلي منها في موضع واحد وصدرت بأسانيدها أخبرني بها محمد بن العباس اليزدي قال حدثنا أحمد بن يحيى ثعلب قال\nحدثنا عيينة بن المنهال عن الأصمعي وأخبرني بها أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة وأخبرني إبراهيم بن أيوب عن ابن قتيبة ونسختها من كتاب محمد بن الليث عن محمد بن عبد الله العبدي عن الهيثم بن عدي عن عبد الله بن عبد الرحمن بن أبي عمرة عن أبيه وأخبرني الحسين بن يحيى عن حماد بن إسحاق عن أبيه عن أبي عبيدة وأخبرني هاشم بن محمد الخزاعي قال حدثنا أبو غسان دماذ عن أبي عبيدة قالوا لما حضرت الحطيئة الوفاة اجتمع إليه قومه فقالوا يا أبا مليكة أوص فقال ويل للشعر من راوية السوء قالوا أوص رحمك الله يا حطيء قال من الذي يقول\n(إذا أنبض الرامون عنها ترنمت ... ترنم ثكلى أوجعتها الجنائز)\nقالوا الشماخ قال أبلغوا غطفان أنه أشعر العرب قالوا ويحك أهذه وصية أوص بما ينفعك قال أبلغوا أهل ضابىء أنه شاعر حيث يقول\n(لكل جديد لذة غير أنني ... رأيت جديد الموت غير لذيذ)\nقالوا أوص ويحك بما ينفعك قال أبلغوا أهل امرىء القيس أنه أشعر العرب\nحيث يقول\n(فيا لك من ليل كأن نجومه ... بكل مغار الفتل شدت بيذبل)\nقالوا اتق الله ودع عنك هذا فقال أبلغوا الأنصار أن صاحبهم أشعر العرب حيث يقول\n(يغشون حتى ما تهر كلابهم ... لا يسألون عن السواد المقبل)\nقالوا هذا لا يغني عنك شيئا فقل غير ما أنت فيه فقال\n(الشعر صعب وطويل سلمه ... إذا ارتقى فيه الذي لا يعلمه)\n(زلت به إلى الحضيض قدمه ... يريد أن يعربه فيعجمه)\nقالوا هذا مثل الذي كنت فيه قال\n(قد كنت أحيانا شديد المعتمد ... وكنت ذا غرب على الخصم ألد)\n(فوردت نفسي وما كادت ترد ... )\nقالوا يا أبا مليكة ألك حاجة قال لا والله و لكن أجزع على المديح الجيد يمدح به من ليس له أهلا قالوا فمن أشعر الناس فأومأ بيده إلى فيه وقال هذا الحجير إذا طمع في خير يعني فمه واستعبر باكيا فقالوا له قل لا إله إلا الله فقال\n(قالت وفيها حيدة وذعر ... عوذ بربي منكم وحجر)\nفقالوا له ما تقول في عبيدك وإمائك فقال هم عبيد قن ما عاقب الليل النهار قالوا فأوص للفقراء بشيء قال أوصيهم بالإلحاح في المسألة فإنها تجارة لا تبور وآست المسؤول أضيق قالوا فما تقول في مالك قال للأنثى من ولدي مثل حظ الذكر قالوا ليس هكذا قضى الله جل وعز لهن قال لكني هكذا قضيت قالوا فما توصي لليتامى قال كلوا أموالهم ونيكوا أمهاتهم قالوا فهل شيء تعهد فيه غير هذا قال نعم تحملونني على أتان وتتركونني راكبها حتى أموت فإن الكريم لا يموت على فراشه والأتان مركب لم يمت عليه كريم قط فحملوه على أتان وجعلوا يذهبون به ويجيئون عليها حتى مات وهو يقول\n(لا أحد ألأم من حطيه ... هجا بنيه وهجا المريه)\n(من لؤمه مات على فريه ... )\nوالفرية الأتان","topic":"خبر الحطيئة ونسبه والسبب الذي من أجله هجا الزبرقان بن بدر","topicNo":9,"sp":12,"spl":"وصية الحطيئة الظريفة","partial":1},
{"id":"b9-16","bab":"الجزء 2","sec":"شعر الحطيئة المغنى ذكر ما غني فيه من القصائد التي مدح بها الحطيئة بغيضا وقومه وهجا","page":"ج2 ص190","text":"الزبرقان وقومه\nمنها\nصوت\n(ألا طرقتنا بعد ما هجعوا هند ... وقد جزن غورا واستبان لنا نجد)\n(وإن التي نكبتها عن معاشر ... علي غضاب أن صددت كما صدوا)\nالغناء لعلويه ثقيل أول بالوسطى عن عمرو وهذه القصيدة التي يقول فيها\n(أتت آل شماس بن لأي وإنما ... أتاهم بها الأحلام والحسب العد)\n(فإن الشقي من تعادي صدورهم ... وذو الجد من لانوا إليه ومن ودوا)\n(يسوسون أحلاما بعيدا أناتها ... فإن غضبوا جاء الحفيظة والجد)\n(أقلوا عليهم لا أبا لأبيكم ... من اللوم أو سدوا المكان الذي سدوا)\n(أولئك قوم إن بنوا أحسنوا البني ... وإن عاهدوا أوفوا وإن عقدوا شدوا)\n(وإن كانت النعمى عليهم جزوا بها ... وإن أنعموا لا كدروها ولا كدوا)\n(وإن قال مولاهم على جل حادث ... من الدهر ردوا فضل أحلامكم ردوا)\n(مطاعين في الهيجا مكاشيف للدجى ... بنى لهم آباؤهم وبنى الجد)\nمنها صوت\n(وأدماء حرجوج تعاللت موهنا ... بسوطي فارمدت نجاء الخفيدد)\n(إذا آنست وقعا من السوط عارضت ... به الجور حتى يستقيم ضحى الغد)\n(وتشرب بالقعب الصغير وإن تقد ... بمشفرها يوما إلى الحوض تنقد)\nالموهن وقت من الليل بعد مضى صدر منه وارمدت نجت والارمداد النجاء والخفيدد الظليم الغناء لابن محرزخفيف رمل بالسبابة في مجرى البنصر عن إسحاق وذكر الهشامي أن فيه لإبراهيم خفيف رمل آخر وهو في جامع إبراهيم غير مجنس وفيه خفيف ثقيل مجهول وذكر حبش أنه لمعبد ويشبه أن يكون ليحيى المكي أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني إبراهيم بن المنذر عن ابن عباية عن محمد بن مسلم الجوسق عن رجل من كعب قال جئت سوق الظهر فإذا بكثير وإذا الناس متقصفون عليه فتخلصت حتى دنوت منه فقلت أبا صخر قال ما تشاء قلت من أشعر الناس قال الذي يقول\n(وآثرت إدلاجي على ليل حرة ... هضيم الحشا حسانة المتجرد)\n(تفرق بالمدرى أثيثا نباته ... على واضح الذفرى أسيل المقلد)\nقال قلت هذا الحطيئة قال هو ذاك أخبرني الحسن بن علي قال حدثنا محمد بن موسى قال حدثنا أحمد بن الحارث الخزاز عن المدائني عن علي بن مجاهد عن هشام بن عروة أن عمر بن الخطاب رضي الله عنه أنشد قول الحطيئة\n(متى تأته تعشو إلى ضوء ناره ... تجد خير نار عندها خير موقد)\nفقال عمر كذب بل تلك نار موسى نبي الله أخبرني الحسين بن يحيى عن حماد عن أبيه عن الهيثم بن عدي عن حماد الراوية أن رجلا دخل على الحطيئة وهو مضطجع على فراشه وإلى جانبه سوداء قد أخرجت رجلها من تحت الكساء فقال له ويحك أفي رجلك خف قال لا والله ولكنها رجل سوداء أتدري من هي قال لا قال وهي والله التي أقول فيها\n(وآثرت إدلاجي علي ليل حرة ... )\nوذكر البيتين والله لو رأيتها يابن أخي لما شربت الماء من يدها قال\nفجعلت تسبه أقبح سب وهو يضحك ومنها صوت\n(ما كان ذنب بغيض لا أبا لكم ... في بائس جاء يحدو أينقا شزبا)\n(طافت أمامة بالركبان آونة ... يا حسنها من خيال زار منتقبا)\n(إذ تستبيك بمصقول عوارضه ... حمش اللتات ترى في مائه شنبا)\n(قد أخلقت عهدها من بعد جدته ... وكذبت حب ملهوف وما كذبا)\nالغناء لابن سريج رمل بالوسطى عن عمرو بن بانة ومنها صوت\n(جزى الله خيرا والجزاء بكفه ... بأحسن ما يجزي الرجال بغيضا)\n(فلو شاء إذ جئناه صد فلم يلم ... وصادف منأى في البلاد عريضا)\nلغناء للهذلي ثقيل أول بالبنصر عن الهشامي","topic":"خبر الحطيئة ونسبه والسبب الذي من أجله هجا الزبرقان بن بدر","topicNo":9,"sp":13,"spl":"شعر الحطيئة المغنى ذكر ما غني فيه من القصائد التي مدح بها الحطيئة بغيضا وقومه وهجا","partial":1},
{"id":"b10-1","bab":"الجزء 2","sec":"أخبار ابن عائشة ونسبه","page":"ج2 ص195","text":"محمد بن عائشة ويكنى أبا جعفر ولم يكن يعرف له أب فكان ينسب إلى أمه ويلقبه من عاداه أو أراد سبه ابن عاهة الدار وكان هو يزعم أن اسم أبيه جعفر وليس يعرف ذلك وعائشة أمه مولاة لكثير بن الصلت الكندي حليف قريش وقيل إنها مولاة لآل المطلب بن أبي وداعة السهمي ذكر ذلك إسحاق عن محمد بن سلام وحكى ابن الكلبي القول الأول وقال إسحاق هو الصحيح يعني قول ابن الكلبي وقال إسحاق فيما رواه لنا الحسين بن يحيى عن حماد عن أبيه إن محمد بن معن الغفاري ذكر له عن أبي السائب المخزومي أن ابن عائشة مولى المطلب بن أبي وداعة السهمي وإنه كان لغير رشدة فأدركت المشيخة وهم إذا سمعوا له صوتا حسنا قالوا أحسن ابن المرأة قال إسحاق وقال عمران بن هند الأرقمي بل كان مولى لكثير بن الصلت قال إسحاق قال عبيد الله بن محمد بن عائشة قال الوليد بن يزيد لابن عائشة يا محمد ألغية أنت قال كانت أمي يا أمير المؤمنين ماشطة وكنت\nغلاما فكانت إذا دخلت إلى موضع قالوا ارفعوا هذا لابن عائشة فغلبت على نسبي","topic":"أخبار ابن عائشة ونسبه","topicNo":10,"sp":0,"spl":"أخبار ابن عائشة ونسبه"},
{"id":"b10-2","bab":"الجزء 2","sec":"المغني الذي يصلح لمنادمة الخلفاء والملوك","page":"ج2 ص196","text":"قال إسحاق وكان ابن عائشة يفتن كل من سمعه وكان فتيان من المدينة قد فسدوا في زمانه بمحادثته ومجالسته وقد أخذ عن معبد ومالك ولم يموتا حتى ساواهما على تقديمه لهما واعترافه بفضلهما وقد قيل إنه كان ضاربا ولم يكن بالجيد الضرب وقيل بل كان مرتجلا لم يضرب قط و ابتداؤه بالغناء كان يضرب به المثل فيقال للإبتداء الحسن كائنا ما كان من قراءة قرآن أو إنشاد شعر أو غناء يبدأ به فيستحسن كأنه ابتداء ابن عائشة قال إسحاق وسمعت علماءنا قديما وحديثا يقولون ابن عائشة أحسن الناس ابتداء وأنا أقول إنه أحسن الناس ابتداء وتوسطا وقطعا بعد أبي عباد معبد وقد سمعت من يقول إن ابن عائشة مثله وأما أنا فلا أجسر على أن أقول ذلك وكان ابن عائشة غير جيد اليدين فكان أكثر ما يغني مرتجلا وكان أطيب الناس صوتا قال إسحاق وحدثني محمد بن سلام قال قال لي جرير لا تخدعن عن أبي جعفر محمد بن عائشة فلولا صلف كان فيه لما كان بعد أبي عباد مثله أخبرني أحمد بن جعفر جحظة قال حدثني محمد بن أحمد بن يحيى المكي عن أبيه عن جده قال ثلاثة من المغنين كانوا أحسن الناس حلوقا ابن عائشة وابن تيزن وابن أبي الكنات حدثني عمي قال حدثنا محمد بن داود بن الجراح قال حدثنا أحمد بن زهير\nقال حدثني مصعب الزبيري عن أبيه قال رأى ابن أبي عتيق حلق ابن عائشة مخدشا فقال من فعل هذا بك قال فلان فمضى فنزع ثيابه وجلس للرجل على بابه فلما خرج أخذ بتلبيبه وجعل يضربه ضربا شديدا والرجل يقول له مالك تضربني أي شيء صنعت وهو لا يجيبه حتى بلغ منه ثم خلاه وأقبل على من حضر فقال هذا أراد أن يكسر مزامير داود شد على ابن عائشة فخنقه وخدش حلقه قال إسحاق في خبره وحدثني أبي عن سياط عن يونس الكاتب قال ما عرفنا بالمدينة أحسن ابتداء من ابن عائشة إذا غنى ولو كان آخر غنائه مثل أوله لقدمته على ابن سريج قال إبراهيم هو كذاك عندي وقال إسحاق مثل قولهما قال وقال يونس كان ابن عائشة يضرب بالعود ولم يكن مجيدا وكان غناؤه أحسن من ضربه فكان لا يكاد يمس العود إلا أن تجتمع جماعة من الضراب فيضربون عليه ويضرب هو ويغني فناهيك به حسنا أخبرني الحسين عن حماد عن أبيه عن الهيثم بن عدي عن صالح بن حسان أنه ذكر يوما المغنين بالمدينة فقال لم يكن بها أحد بعد طويس أعلم من ابن\nعائشة ولا أظرف مجلسا ولا أكثر طيبا وكان يصلح أن يكون نديم خليفة أو سمير ملك قال إسحاق فأذكرني هذا القول قول جميلة له وأنت يا أبا جعفر فمع الخلفاء تصلح أن تكون قال إسحاق وحدثني المدائني قال حدثني جرير قال كان ابن عائشة تائها سيىء الخلق فإن قال له إنسان تغن قال ألمثلي يقال هذا وإن قال له إنسان وقد ابتدأ هو بغناء احسنت قال ألمثلي يقال أحسنت ثم يسكت فكان قليلا ما ينتفع به فسال العقيق مرة فدخل عرصة سعيد بن العاصي الماء حتى ملأها فخرج الناس إليها وخرج ابن عائشة فيمن خرج فجلس على قرن البئر فبينا هم كذلك إذ طلع الحسن بن الحسن بن علي بن أبي طالب عليهم السلام على بغلة و خلفه غلامان أسودان كأنهما من الشياطين فقال لهما امضيا رويدا حتى تقفا بأصل القرن الذي عليه ابن عائشة فخرجا حتى فعلا ذلك ثم ناداه الحسن كيف أصبحت يا بن عائشة قال بخير فداك أبي وأمي قال انظر من إلى جنبك فنظر فإذا العبدان فقال له أتعرفهما قال نعم قال فهما حران لئن لم تغنني مائة صوت لآمرنهما بطرحك في البئر وهما حران لئن لم يفعلا لأقطعن أيديهما فاندفع ابن عائشة فكان أول ما ابتدأ به صوتا له وهو\n(ألا لله درك من ... فتى قوم إذا رهبوا)\nثم لم يسكت حتى غنى مائة صوت فيقال إن الناس لم يسمعوا من ابن عائشة أكثر مما سمعوا في ذلك اليوم وكان آخر ما غنى صوت\n(قل للمنازل بالظهران قد حانا ... أن تنطقي فتبيني القول تبيانا)\nقال جرير فما رئي يوم أحسن منه ولقد سمع الناس شيئا لم يسمعوا مثله وما بلغني أن أحدا تشاغل عن استماع غنائه بشيء ولا انصرف أحد لقضاء حاجة ولا لغير ذلك حتى فرغ ولقد تبادر الناس من المدينة وما حولها حيث بلغهم الخبر لاستماع غنائه فيقال إنه ما رئي جمع في ذلك الموضع مثل ذلك الجمع ولقد رفع الناس أصواتهم يقولون له أحسنت والله أحسنت والله ثم انصرفوا حوله يزفونه إلى المدينة زفا","topic":"أخبار ابن عائشة ونسبه","topicNo":10,"sp":1,"spl":"المغني الذي يصلح لمنادمة الخلفاء والملوك"},
{"id":"b10-3","bab":"الجزء 2","sec":"نسبة ما في هذا الخبر من الأغاني","page":"ج2 ص199","text":"منها صوت\n(ألا لله درك من ... فتى قوم إذا رهبوا)\n(وقالوا من فتى للحرب ... يرقبنا ويرتقب)\n(فكنت فتاهم فيها ... إذا تدعى لها تثب)\n(ذكرت أخي فعاودني ... رداع السقم والوصب)\n(كما يعتاد ذات البوه ... بعد سلوها الطرب)\n(على عبد بن زهرة بت ... طول الليل أنتتحب)\nالشعر لأبي العيال الهذلي والغناء لمعبد وله فيه لحنان أحدهما ثقيل أول بالخنصر في مجرى الوسطى عن إسحاق يبدأ فيه بقوله\n(ذكرت أخي فعاودني ... رداع السقم والوصب)\nوالآخر خفيف رمل بالوسطى عن عمرو بن بانة وفيه لابن عائشة خفيف رمل آخر وقيل بل هو لحن معبد وذكر حماد بن إسحاق أن خفيف الرمل لمالك البو جلد يحشى تبنا ويجفف ليكلا تخبث رائحته ويدنى إلى الناقة التي قد نحر فصيلها أو مات لتشمه فتدر عليه ومنها صوت\n(قل للمنازل بالظهران قد حانا ... أن تنطقي فتبيني القول تبيانا)\n(قالت ومن أنت قل لي قلت ذو شغف ... هجت له من دواعي الحب أحزانا)\nالشعر لعمر بن أبي ربيعة والغناء لابن عائشة خفيف ثقيل أول بالوسطى عن الهشامي وحبش وقال هارون بن محمد بن عبد الملك الزيات حدثني عبد الرحمن بن\nسليمان عن علي بن الجهم الشاعر قال حدثني رجل أن ابن عائشة كان واقفا بالموسم متحيرا فمر به بعض أصحابه فقال له ما يقيمك هاهنا فقال إني أعرف رجلا لو تكلم لحبس الناس هاهنا فلم يذهب أحد ولم يجىء فقال له الرجل ومن ذاك قال أنا ثم اندفع يغني\n(جرت سنحا فقلت لها أجيزي ... نوى مشمولة فمتى اللقاء)\nقال فحبس الناس واضطربت المحامل ومدت الإبل أعناقها وكادت الفتنة أن تقع فأتي به هشام بن عبد الملك فقال له يا عدو الله أردت أن تفتن الناس قال فأمسك عنه وكان تياها فقال له هشام ارفق بتيهك فقال حق لمن كانت هذه مقدرته على القلوب أن يكون تياها فضحك منه وخلى سبيله","topic":"أخبار ابن عائشة ونسبه","topicNo":10,"sp":2,"spl":"نسبة ما في هذا الخبر من الأغاني — نسبة هذا الصوت الذي غناه ابن عائشة"},
{"id":"b10-4","bab":"الجزء 2","sec":"نسبة هذا الصوت الذي غناه ابن عائشة","page":"ج2 ص201","text":"صوت\n(جرت سنحا فقلت لها أجيزي ... نوى مشمولة فمتى اللقاء)\n(بنفسي من تذكره سقام ... أعانيه ومطلبه عناء)\nالسانح ما أقبل من شمالك يريد يمينك والبارح ضده وقال أبو عبيدة سمعت\nيونس بن حبيب يسأل رؤبة عن السانح والبارح فقال السانح ما ولاك ميامنه والبارح ما ولاك مشائمه وقوله أجيزي أي انفدي قال الأصمعي يقال أجزت الوادي إذا قطعته وخلفته وجزته أي سرت فيه فتجاوزته وجاوزته مثله قال أوس بن مغراء\n(ولا يريمون في التعريف موقفهم ... حتى يقال أجيزوا آل صوفانا)\nومشمولة سريعة الانكشاف أخذه من السحابة المشمولة وهي التي تصيبها الشمال فتكشفها ومن شأن الشمال أن تقطع السحاب واستعارها هاهنا في النوى لسرعة انكشافهم فيها عن بلدهم وأجرى ذلك مجرى الذم للسانح لأنه يتشاءم به البيت الأول من الشعر لزهير بن أبي سلمى والثاني محدث ألحقه المغنون به لا أعرف قائله والغناء لابن عائشة ولحنه خفيف ثقيل أول بالبنصر","topic":"أخبار ابن عائشة ونسبه","topicNo":10,"sp":2,"spl":"نسبة ما في هذا الخبر من الأغاني — نسبة هذا الصوت الذي غناه ابن عائشة"},
{"id":"b10-5","bab":"الجزء 2","sec":"الوليد يشرب وابن عائشة يغني ومعبد بمزجر الكلب","page":"ج2 ص202","text":"أخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة قال حدثنا إسحاق\nوأخبرني به محمد بن مزيد والحسين بن يحيى قالا حدثنا حماد بن إسحاق عن أبيه عن الهيثم بن عدي عن حماد الراوية قال كتب الوليد بن يزيد إلى يوسف بن عمر أما بعد فإذا قرأت كتابي هذا فسرح إلي حمادا الراوية على ما أحب من دواب البريد وأعطه عشرة آلاف درهم يتهيأ بها قال فأتاه الكتاب وأنا عنده فنبذه إلى فقلت السمع والطاعة فقال يادكين مر شجرة يعطيه عشرة آلاف درهم فأخذتها فلما كان اليوم الذي أردت الخروج فيه أتيت يوسف بن عمر فقال يا حماد أنا بالموضع الذي قد عرفته من أمير المؤمنين ولست مستغنيا عن ثنائك فقلت أصلح الله الأمير إن العوان لا تعلم الخمرة وسيبلغك قولي وثنائي فخرجت حتى انتهيت إلى الوليد وهو بالبخراء فاستأذنت عليه فأذن لي فإذا هو على سرير ممهد وعليه ثوبان أصفران إزار ورداء يقيئان الزعفران قيئا وإذا عنده معبد ومالك بن أبي السمح وأبو كامل مولاه فتركني حتى سكن جأشي ثم قال أنشدني\n(أمن المنون وريبها تتوجع ... )\nفأنشدته حتى أتيت على آخرها فقال لساقيه يا سبرة اسقه فسقاني ثلاثة أكؤس خثرن ما بين الذؤابة والنعل ثم قال يا مالك غنني\n(ألا هل هاجك الأظعان ... إذ جاوزن مطلحا)\nففعل ثم قال له غنني\n(جلا أمية عني كل مظلمة ... سهل الحجاب وأوفى بالذي وعدا)\nففعل ثم قال له غنني\n(أتنسى إذ تودعنا سليمى ... بفرع بشامة سقي البشام)\nففعل ثم قال ياسبرة أو يا أبا سبرة اسقني بزب فرعون فأتاه بقدح معوج فسقاه به عشرين ثم أتاه الحاجب فقال أصلح الله أمير المؤمنين الرجل الذي طلبت بالباب قال ادخله فدخل شاب لم أر شابا أحسن وجها منه في رجله بعض الفدع فقال يا سبرة اسقه فسقاه كأسا ثم قال له غنني\n(وهي إذ ذاك عليها مئزر ... ولها بيت جوار من لعب)\nفغناه فنبذ إليه الثوبين ثم قال له غنني\n(طاف الخيال فمرحبا ... ألفا برؤية زينبا)\nفغضب معبد وقال يا أمير المومنين إنا مقبلون عليك بأقدارنا وأسناننا وإنك تركتنا بمزجر الكلب وأقبلت على هذا الصبي فقال والله يا أبا عباد ما جهلت قدرك ولا سنك ولكن هذا الغلام طرحني في مثل الطناجير من حرارة غنائه قال حماد الراوية فسألت عن الغلام فقيل لي هو ابن عائشة","topic":"أخبار ابن عائشة ونسبه","topicNo":10,"sp":3,"spl":"الوليد يشرب وابن عائشة يغني ومعبد بمزجر الكلب","partial":1},
{"id":"b10-6","bab":"الجزء 2","sec":"نسبه ما في هذا الخبر من الأغاني","page":"ج2 ص205","text":"صوت\n(جلا أمية عني كل مظلمة ... سهل الحجاب وأوفى بالذي وعدا)\n(إذا حللت بأرض لا أراك بها ... ضاقت علي ولم أعرف بها أحدا)\nلغناء لابن عباد الكاتب خفيف ثقيل بإطلاق الوتر في مجرى البنصر عن إسحاق وذكر عمرو بن بانة أنه لعمر الوادي وذكر حبش أن فيه لمالك لحنا من خفيف الثقيل الأول بالوسطى ومنها صوت\n(أتنسى إذ تودعنا سليمى ... بفرع بشامة سقي البشام)\n(متى كان الخيام بذي طلوح ... سقيت الغيث أيتها الخيام)\n(أتمضون الخيام ولم نسلم ... كلامكم علي إذا حرام)\n(بنفسي من تجنبه عزيز ... علي ومن زيارته لمام)\n(ومن أمسي وأصبح لا أراه ... ويطرقني إذا رقد النيام)\nلشعر لجرير والغناء لابن سريج وله في هذه الأبيات ثلاثة الحان أحدهما في الأول والرابع ثقيل أول بالخنصر في مجرى البنصر عن إسحاق والآخر في الثاني ثم الأول ثاني ثقيل بالبنصر عن عمرو والآخر في الثالث وما بعده رمل بالبنصر عن الهشامي وحبش وللدلال في الثاني والثالث ثاني ثقيل بالسبابة في مجرى الوسطى عن إسحاق والمكي وللغريض في الأول والثاني والثالث خفيف رمل بالبنصر عن عمرو وفيها لمالك ثقيل أول بالبنصر عن الهشامي ولابن جامع في الأول والثاني والرابع والخامس هزج عن الهشامي وفيها لابن جندب خفيف ثقيل بالبنصر ومنها الصوت الذي أوله في الخبر\n(وهي إذ ذاك عليها مئزر ... )\nوأوله صوت\n(عهدتني ناشئا ذا غرة ... رجل الجمة ذا بطن أقب)\n(أتبع الولدان أرخي مئزري ... ابن عشرذا قريط من ذهب)\n(وهي إذ ذاك عليها مئزر ... ولها بيت جوار من لعب)\nلشعر لامرىء القيس ويقال إنه أول شعر شبب فيه بالنساء والغناء لابن عائشة ثاني ثقيل بالبنصر عن الهشامي ودنانير وحماد بن إسحاق وفيه خفيف ثقيل بالبنصر ذكر حماد في أخبار جميلة أنه لها وذكر حبش والهشامي أنه لابن سريج وقيل إنه لغيرهما ومنها صوت\n(ألا هل هاجك الأظعا ... ن إذ جاوزن مطلحا)\n(نعم ولوشك بينهم ... جرى لك طائر سنحا)\n(أخذن الماء من ركك ... وضوء الفجر قد وضحا)\n(يقلن مقيلنا قرن ... نباكر ماءه صبحا)\n(تبعتهم بطرف العي ... ن حتى قيل لي افتضحا)\n(وهي إذ ذاك عليها مئزر ... ولها بيت جوار من لعب)\nالشعر لامرىء القيس ويقال إنه أول شعر شبب فيه بالنساء والغناء لابن عائشة ثاني ثقيل بالبنصر عن الهشامي ودنانير وحماد بن إسحاق وفيه خفيف ثقيل بالبنصر ذكر حماد في أخبار جميلة أنه لها وذكر حبش والهشامي أنه لابن سريج وقيل إنه لغيرهما ومنها صوت\n(ألا هل هاجك الأظعان ... إذ جاوزن مطلحا)\n(نعم ولوشك بينهم ... جرى لك طائر سنحا)\n(أخذن الماء من ركك ... وضوء الفجر قد وضحا)\n(يقلن مقيلنا قرن ... نباكر ماءه صبحا)\n(تبعتهم بطرف العين ... حتى قيل لي افتضحا)\n(يودع بعضنا بعضا ... وكل بالهوى جرحا)\n(فمن يفرح ببينهم ... فغيري إذ غدوا فرحا)\nلشعر ترويه الرواة جميعا لعمر بن أبي ربيعة سوى الزبير بن بكار فإنه رواه عن عمه وأهله لجعفر بن الزبير بن العوام وقد ذكر خبره في هذا مع أخباره المذكورة في آخر الكتاب ورواه الزبير إذ جاوزن من طلحا وقال ليس على وجه الأرض موضع يقال له مطلح والغناء لمالك وله فيه لحنان ثقيل أول بالبنصر عن إسحاق وخفيف ثقيل بالوسطى عن عمرو وفيه لمعبد ثقيل أول بالخنصر في مجرى الوسطى عن إسحاق وفيه لابن سريج في الخامس وهو تبعتهم بطرف العين إلى آخر الأبيات ثقيل أول مطلق في مجرى البنصر عن إسحاق وفيها للغريض ثان ثقيل بالوسطى عن الهشامي قال وهو الذي فيه استهلال وذكر ابن المكي أن الثقيل الثاني لمالك وخفيف الثقيل للغريض ومنها صوت\n(طرق الخيال فمرحبا ... ألفا برؤية زينبا)\n(أني اهتديت لفتية ... سلكوا السليل فعليبا)","topic":"أخبار ابن عائشة ونسبه","topicNo":10,"sp":4,"spl":"نسبه ما في هذا الخبر من الأغاني","partialRef":{"sid":"b10-5","gi":4,"vi":0,"side":0},"partial":1},
{"id":"b10-7","bab":"الجزء 2","sec":"عندما يغني ابن عائشة ينسى الناسك زهده","page":"ج2 ص208","text":"أخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة عن محمد بن سلام قال حدثني جرير قال\nأخذ بعض ولاة المدينة المغنين والمخنثين والسفهاء بلزوم مسجد رسول اللهوكان في المسجد رجل ناسك يكنى أبا جعفر مولى لابن عياش بن أبي ربيعة المخزومي يقرىء الناس القرآن وكان ابن عائشة يلازمه فخلا لابن عائشة يوما الموضع مع أبي جعفر فقرأ له فطرب ورجع فسمع الشيخ صوتا لم يسمع مثله قط فقال له يابن أخي أفسدت نفسك وضيعتها فلو أنك لزمت المسجد وتعلمت القرآن لأقمت للناس في مسجد رسول اللهفي شهر رمضان ولأصبت بذلك من الولاة خير فوالله ما دخل أذني قط صوت أحسن من صوتك فقال ابن عائشة فكيف لو سمعت يا أبا جعفر صوتي في الأمر الذي صنع له قال وما هو قال انطلق معي حتى أسمعكه فخرج معه إلى ميضأة ببقيع الغرقد عند دار المغيرة بن شعبة وكان أبو جعفر يتوضأ عندها كل يوم فاندفع ابن عائشة يغني\n(ألآن أبصرت الهدى ... وعلا المشيب مفارقي)\nفبلغ ذلك من الشيخ كل مبلغ وقال يابن أخي هذا حسن وأنا أشتهي أن أسمعه ولكن لا أطلبه ولا أمشي إليه قال ابن عائشة فعلي أن أسمعكه فكان يرصده فإذا خرج أبو جعفر يتوضأ خرج ابن عائشة في أثره حتى يقف خلف جدار الميضأة بحيث يسمع غناءه فيغنيه أصواتا حتى يفرغ أبو جعفر من وضوئه فلم يزل يفعل ذلك حتى أطلقوا من لزوم المسجد","topic":"أخبار ابن عائشة ونسبه","topicNo":10,"sp":5,"spl":"عندما يغني ابن عائشة ينسى الناسك زهده — نسبه هذا الصوت"},
{"id":"b10-8","bab":"الجزء 2","sec":"نسبه هذا الصوت","page":"ج2 ص209","text":"صوت\n(طرق الخيال المعتري ... وهنا فؤاد العاشق)\n(طيف ألم فهاجني ... للبين أم مساحق)\n(ألآن أبصرت الهدى ... وعلا المشيب مفارقي)\n(وتركت أمر غوايتي ... وسلكت قصد طرائقي)\n(ولقد رضيت بعيشنا ... إذ نحن بين حدائق)\n(وركائب تهوي بنا ... بين الدروب فدابق)\nلشعر للوليد بن يزيد ويقال إنه لابن رهيمة والغناء لابن عائشة رمل بالبنصر عن عمرو وذكره يونس أيضا له في كتابه وفيه لأبي زكار الأعمى خفيف رمل بالوسطى عن عمرو والهشامي وذكر ابن خرداذبه أنه لأبي زكار الأعمى وهو قديم وأنه وجد ذلك في كتاب يونس وفيه لحكم الوادي في كتاب يونس غير مجنس ولا أدري أيها هو وفي هذه الأبيات خفيف ثقيل متنازع فيه نسب إلى معبد وإلى مالك ولم أجده لهما عن ثقة وأظنه لحن حكم","topic":"أخبار ابن عائشة ونسبه","topicNo":10,"sp":5,"spl":"عندما يغني ابن عائشة ينسى الناسك زهده — نسبه هذا الصوت"},
{"id":"b10-9","bab":"الجزء 2","sec":"الحسن بن الحسن مع ابن عائشة في البغيبغة","page":"ج2 ص210","text":"أخبرني محمد بن مزيد بن أبي الأزهر البوشنجي والحسين بن يحيى الأعور المرداسي قالا حدثنا حماد بن إسحاق عن أبيه عن محمد بن سلام عن أبيه قال كان الحسن بن الحسن مكرما لابن عائشة محبا له وكان ابن عائشة منقطعا\nإليه وكان من أتيه خلق الله وأشده ذهابا بنفسه فسأله الحسن أن يخرج معه إلى البغيبغة فامتنع ابن عائشة من ذلك فأقسم عليه فأبى فدعا بغلمان له حبشان وقال نفيت من أبي لئن لم تسر معي طائعا لتسيرن كارها ونفيت من أبي لئن لم ينفذوا أمري فيك لأقطعن أيديهم فلما رأى ابن عائشة ما ظهر من الحسن علم أنه لابد من الذهاب فقال له بأبي أنت وأمي أنا أمضي معك طائعا لا كارها فأمر الحسن بإصلاح ما يحتاج إليه وركب وأمر لابن عائشة ببغلة فركبها ومضيا حتى صارا إلى البغيبغة فنزلا الشعب وجاءهم ما أعدوا فأكلوا ثم أمر الحسن بأمره وقال يا محمد فقال له لبيك يا سيدي قال غنني فاندفع فغناه صوت\n(يدعو النبي بعمه فيجيبه ... يا خير من يدعو النبي جلالا)\n(ذهب الرجال فلا أحس رجالا ... وأرى الإقامة بالعراق ضلالا)\n(وأرى المرجي للعراق وأهله ... ظمآن هاجرة يؤمل آلا)\n(وطربت إذ ذكر المدينة ذاكر ... يوم الخميس فهاج لي بلبالا)\n(فظللت أنظر في السماء كأنني ... أبغي بناحية السماء هلالا)\nلشعر لابن المولى من قصيدة طويلة قالها وقد قدم إلى العراق\nلبعض أمره فطال مقامه بها واشتاق إلى بلده وقد ذكر خبره في موضعه من هذا الكتاب والغناء لابن عائشة ثقيل أول بالبنصر عن حماد والهشامي وحبش وقال الهشامي خاصة فيه لحن لقراريط فقال له الحسن أحسنت والله يابن عائشة فقال ابن عائشة والله لا غنيتك في يومي هذا شيئا فقال الحسن فوالله لا برحت البغيبغة ثلاثة أيام فاغتم ابن عائشة ليمينه وندم وعلم أنه لا حيلة له إلا المقام فأقاموا فلما كان اليوم الثاني قال له الحسن هات ما عندك فقد برت يمينك وكانوا جلوسا على شيء مرتفع فنظروا إلى ناقة تقدم جماعة إبل فاندفع ابن عائشة فغنى\n(تمر كجندلة المنجنيق ... يرمى بها السور يوم القتال)\n(فماذا تخطرف من قلة ... ومن حدب وإكام توالي)\n(ومن سيرها العنق المسبطر ... والعجرفية بعد الكلال)\nقال له الحسن ويلك يا محمد لقد أحسنت الصنعة فسكت ابن عائشة ثم قال له غنني فغناه\n(إذا ما انتشيت طرحت اللجام ... في شدق منجرد سلهب)\n(يبذ الجياد بتقريبه ... ويأوي إلى حضر ملهب)\n(كميت كأن على متنه ... سبائك من قطع المذهب)\n(كأن القرنفل والزنجبيل ... يعل على ريقها الأطيب)\nفقال له الحسن أحسنت يا محمد فقال له ابن عائشة لكنك بأبي أنت وأمي قد ألجمتني بحجر فما أطيق الكلام فأقاموا باقي يومهم يتحدثون فلما كان اليوم الثالث قال الحسن هذا آخر أيامك يا محمد فقال ابن عائشة عليه وعليه إن غناك إلا صوتا واحدا حتى تنصرف وعليه عليه إن حلفت ألا أبر قسمك ولو في ذهاب روحه فقال له الحسن فلك الأمان على محبتك فاندفع فغناه صوت\n(أنعم الله لي بذا الوجه عينا ... وبه مرحبا وأهلا وسهلا)\n(حين قالت لا تذكرن حديثي ... يابن عمي أقسمت قلت أجل لا)\n(لا أخون الصديق في السر حتى ... ينقل البحر بالغرابيل نقلا)\nقال ثم انصرف القوم فما رأى الحسن بن الحسن ابن عائشة بعدها","topic":"أخبار ابن عائشة ونسبه","topicNo":10,"sp":6,"spl":"الحسن بن الحسن مع ابن عائشة في البغيبغة"},
{"id":"b10-10","bab":"الجزء 2","sec":"نسبة ما لم تمض نسبته في الخبر من هذه الأصوات","page":"ج2 ص213","text":"منها صوت\n(تمر كجندلة المنجنيق ... يرمى بها السور يوم القتال)\n(فماذا تخطرف من قلة ... ومن حدب وإكام توالي)\n(ومن سيرها العنق المسبطر ... والعجرفية بعد الكلال)\n(ألا يا لقوم لطيف الخيال ... أرق من نازح ذي دلال)\n(يثني التحية بعد السلا ... م ثم يفدي بعم وخال)\n(خيال لسلمى فقد عاد لي ... بنكس من الحب بعد اندمال)\nما الذي قاله الشاعر في هذا الشعر فإنه قال يمر بالياء لأنه وصف به حمارا وحشيا ولكن المغنين جميعا يغنونه بالتاء على لفظ المؤنث وقد وصف في هذه القصيدة الناقة ولم يذكر من صفتها إلا قوله\n(ومن سيرها العنق المسبطر ... )\nولكن المغنين أخذوا من صفة العير شيئا ومن صفة الناقة شيئا فخلطوهما وغنوا فيهما وقوله\n(فماذا تخطرف من قلة ... )\nيعني أنه يمر بالموضع المرتفع فيطفره وروي الأصمعي\n(فماذا تخطرف من حالق ... ومن قلة وحجاب وجال)\nفالحالق ما أشرف والحجاب ما حجب عنك ما بين يديك من ألارض والجال حرف الشيء يقال له جال وجول والعنق المسبطر المسترسل السهل والعجرفية التعسف والإسراع يقول إذا كلت وتعبت تعجرفت في السير من بقية نفسها وشدتها وروى الأصمعي فيها\n(خيال لجعدة قد هاج لي ... نكاسا من الحب بعد اندمال)\nيقال نكس ونكاس بمعنى واحد وهو عود المرض بعد الصحة والأندمال الإفاقة من العلة واندمال الجرح برؤه فأما الأبيات التي يصف فيها الناقة فقوله\n(فسل الهموم بعيرانة ... مواشكة الرجع بعد انتقال)\n(ذمول تزف زفيف الظليم ... شمر بالنعف وسط الرئال)\n(وترمد هملجة زعزعا ... كما انخرط الحبل فوق المحال)\n(ومن سيرها العنق المسبطر ... والعجرفية بعد الكلال)\n(كأني ورحلي إذا رعتها ... على جمزى جازىء بالرمال)\nوأما صفة الحمار في هذه القصيدة فقوله فيه وفي الأتن\n(فظل يسوف أبوالها ... ويوفي زيازي حدب التلال)\n(فطاف بتعشيره وانتحى ... جوائلها وهو كالمستجال)\n(تهادى حوافرها جندلا ... زواهق ضرب قلات بقال)\n(رمى بالجراميز عرض الوجين ... وارمد في الجري بعد انفتال)\n(بشأو له كضريم الحريق ... أو شقة البرق في عرض خال)\n(يمر كجندلة المنجنيق ... يرمى بها السور يوم القتال)\n(فماذا تخطرف من حالق ... ومن حدب وحجاب وجال)\nلشعر لأمية بن أبي عائذ الهذلي والغناء لابن عائشة ولحن ابن عائشة مشكوك فيه أي الألحان المصنوعة في هذا الشعر هو فيقال إنه خفيف الرمل ويقال إنه هو الثقيل الأول ويقال إنه الرمل فأما خفيف الرمل فهو بالخنصر في مجرى الوسطى وذكره إسحاق في موضع فتوقف عنه ولم ينسبه ونسبه في موضع آخر إلى ابن أبي يزن المكي ونسبه عمرو بن بانة إلى معبد وقال فيه خفيف رمل آخر لمالك وذكره يونس في أغاني ابن أبي يزن المكي ونسبه ولم يجنسه وذكر ابن خرداذبه والهشامي أن فيه لهشام بن المرية لحنا من الثقيل الأول ورأيت ذلك أيضا في بعض الكتب بخط علي بن يحيى المنجم كما ذكرا وذكر إسحاق أن الرمل مطلق في مجرى الوسطى وأنه لابن عائشة وذكر أحمد بن المكي أنه لأبيه وذكر غيره أنه غلط وأن لحن أبيه هو الثقيل الأول والرمل لابن عائشة وقال حبش فيه لابن سريج هزج خفيف بالوسطى ومنها وقد مضى تفسيره في الخبر واقتصر على البيت الأول منه\nصوت\n(إذا ما انتشيت طرحت اللجام ... في شدق منجرد سلهب)\nالشعر للنابغة الجعدي والغناء لابن عائشة خفيف ثقيل بالوسطى عن الهشامي وحماد ومنها الصوت الذي أوله\n(أنعم الله بذا الوجه عينا ... )\nقد جمع مع سائر ما يغنى فيه من القصيدة وهو\n(أثل جودي على المتيم أثلالا ... تزيدي فؤاده أثل خبلا)\n(أثل إني والراقصات بجمع ... يتبارين في الأزمة فتلا)\n(سابحات يقطعن من عرفات ... بين أيدي المطي حزنا وسهلا)\n(والأكف المطهرات على الركن ... لشعث سعوا إلى البيت رجلا)\n(لا أخون الصديق في السر حتى ... ينقل البحر بالغرابيل نقلا)\n(أو تمور الجبال مور سحاب ... مرتق قد وعى من الماء ثقلا)\n(أنعم الله لي بذا الوجه عينا ... وبه مرحبا وأهلا وسهلا)\n(حين قالت لا تفشين حديثي ... يابن عمي أقسمت قلت أجل لا)\n(فاتقي الله واقبلي العذر مني ... وتجافي عن بعض ما كان زلا)\n(إن أكن سؤتكم به فلك العتبى ... لدنيا وحق ذاك وقلا)\n(لم أرحب بأن سخطت ولكن ... مرحبا أن رضيت عنا وأهلا)\n(إن شخصا رأيته ليلة البدر ... عليه ابتنى الجمال وحلا)\n(جعل الله كل أنثى فداء ... لك بل خدها لرجليك نعلا)","topic":"أخبار ابن عائشة ونسبه","topicNo":10,"sp":7,"spl":"نسبة ما لم تمض نسبته في الخبر من هذه الأصوات","partialRef":{"sid":"b10-9","gi":1,"vi":1,"side":0},"partial":1},
{"id":"b10-11","bab":"الجزء 2","sec":"نسبة ما لم تمض نسبته في الخبر من هذه الأصوات","page":"ج2 ص213","text":"(وجهك الوجه لو سألت به المزن ... من الحسن والجمال استهلا)\nلشعر للحارث بن خالد املخزومي والغناء لمعبد في الأربعة الأبيات الأول خفيف ثقيل أول بالوسطى عن عمرو بن بانة لابن هوبر في الأول والثاني ثقيل أول عن إسحاق ولاابن سريج في الأول والثاني والخامس ثقيل أول وآخر بالبنصر أوله استهلال وللغريض في الخامس وما بعده إلى التاسع خفيف ثقيل بالوسطى ولدحمان في التاسع والثالث عشر والرابع عشر خفيف ثقيل أول بالبنصر ولمالك في التاسع إلى آخر الثاني عشر لحن من كتاب يونس ولم يقع إلي من يجنسه ولابن سريج فيها بعينها رمل بالوسطى عن الهشامي وفيها أيضا للغريض خفيف رمل بالبنصر ولابن عائشة في السابع والثامن لحن ذكره حماد عن أبيه ولم يجنسه","topic":"أخبار ابن عائشة ونسبه","topicNo":10,"sp":8,"spl":"نسبة ما لم تمض نسبته في الخبر من هذه الأصوات — الوليد بن يزيد يطرب لغنائه"},
{"id":"b10-12","bab":"الجزء 2","sec":"الوليد بن يزيد يطرب لغنائه","page":"ج2 ص218","text":"أخبرني أحمد بن عبد العزيز الجوهري وإسماعيل بن يونس الشيعي وحبيب بن نصر المهلبي قالوا حدثنا عمر بن شبة قال حدثني محمد بن سلام وأخبرني محمد بن مزيد بن أبي الأزهر والحسين بن يحيى قالا حدثنا حماد بن إسحاق عن أبيه عن محمد بن سلام عن أبيه عن شيخ من تنوخ ولم يقل عمر بن شبة في خبره محمد بن سلام عن أبيه ورواه عن محمد عن شيخ من تنوخ قال كنت صاحب ستر الوليد بن يزيد فرأيت ابن عائشة عنده وقد غناه\nصوت\n(إني رأيت صبيحة النفر ... حورا نفين عزيمة الصبر)\n(مثل الكواكب في مطالعها ... بعد العشاء أطفن بالبدر)\n(وخرجت أبغي الأجر محتسبا ... فرجعت موفورا من الوزر)\nال إسحاق في خبره والشعر لرجل من قريش والغناء لمالك هكذا في خبر إسحاق وما وجدته ذكره لمالك في جامع أغانيه ووجدته في غناء ابن سريج خفيف رمل بالوسطى عن الهشامي قال فطرب الوليد حتى كفر وألحد وقال يا غلام اسقنا بالسماء الرابعة وكان الغناء يعمل فيه عملا ضل عنه من بعده ثم قال أحسنت والله يا أميري أعد بحق عبد شمس فأعاد ثم قال أحسنت والله يا أميري أعد بحق أمية فأعاد ثم قال أعد بحق فلان أعد بحق فلان حتى بلغ من الملوك نفسه فقال أعد بحياتي فأعاده قال فقام إليه فأكب عليه فلم يبق عضو من أعضائه إلا قبله وأهوى إلى هنه فجعل ابن عائشة يضم فخذية عليه فقال والله العظيم لا تريم حتى أقبله فأبداه له فقبل رأسه ثم نزع ثيابه فألقاها عليه وبقي مجردا إلى أن أتوه بمثلها ووهب له ألف دينار وحمله على بغلة وقال اركبها بأبي أنت وانصرف فقد تركتني على مثل المقلى من حرارة غنائك فركبها على بساطه وانصرف","topic":"أخبار ابن عائشة ونسبه","topicNo":10,"sp":8,"spl":"نسبة ما لم تمض نسبته في الخبر من هذه الأصوات — الوليد بن يزيد يطرب لغنائه"},
{"id":"b10-13","bab":"الجزء 2","sec":"الوليد يكرم المحتاجين من متذوقي الغناء","page":"ج2 ص219","text":"أخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة قال حدثني محمد بن الحسن النخعي قال حدثني محمد بن الحارث بن كليب بن زيد الربعي قال خرج ابن عائشة المدني من عند الوليد بن يزيد وقد غناه\n(أبعدك معقلا أرجو وحصنا ... قد اعيتني المعاقل والحصون)\nوهي أربعة أبيات هكذا في الخبر ولم يذكر غير هذا البيت منها قال فأطربه فأمر له بثلاثين ألف درهم وبمثل كارة القصار كسوة فبينا ابن عائشة يسير إذ نظر إليه رجل من أهل وادي القرى كان يشتهي الغناء ويشرب النبيذ فدنا من غلامه وقال من هذا الراكب قال ابن عائشة المغني فدنا منه وقال جعلت فداءك أنت ابن عائشة أم المؤمنين قال لا أنا مولى لقريش وعائشة أمي وحسبك هذا فلا عليك أن تكثر قال وما هذا الذي أراه بين يديك من المال والكسوة قال غنيت أمير المؤمنين صوتا فأطربته فكفر وترك الصلاة وأمر لي بهذا المال وهذه الكسوة قال جعلت فداءك فهل تمن علي بأن تسمعني ما أسمعته إياه فقال له ويلك أمثلي يكلم بمثل هذا في الطريق قال فما أصنع قال الحقني بالباب وحرك ابن عائشة بغلة شقراء كانت تحته لينقطع عنه فعدا معه حتى وافيا الباب كفرسي رهان ودخل ابن عائشة فمكث طويلا طمعا في أن يضجر فينصرف فلم يفعل فلما أعياه قال لغلامه أدخله فلما دخل قال له هل ويلك من أين صبك الله علي قال أنا رجل من أهل وادي وادي القرى أشتهي هذا الغناء فقال له هل لك فيما هو أنفع لك منه قال وما ذاك قال مائتا دينار وعشرة أثواب تنصرف بها إلى أهلك فقال له جعلت فداءك والله إن لي لبنية ما في أذنها علم الله حلقة من الورق فضلا عن الذهب وإن لي لزوجة ما عليها يشهد الله قميص ولو أعطيتني جميع ما أمر لك به أمير المؤمنين على هذه الخلة والفقر اللذين عرفتكهما وأضعفت لي ذلك لكان الصوت أعجب إلي\nوكان ابن عائشة تائها لا يغني إلا لخليفة أو لذي قدر جليل من إخوانه فتعجب ابن عائشة منه ورحمه ودعا بالدواة وكان يغني مرتجلا فغناه الصوت فطرب له طربا شديدا وجعل يحرك رأسه حتى ظن أن عنقه سينقصف ثم خرج من عنده ولم يرزأه شيئا وبلغ الخبر الوليد بن يزيد فسأل ابن عائشة عنه فجعل يغيب عن الحديث ثم جد الوليد به فصدقه عنه وأمر بطلب الرجل فطلب حتى أحضر ووصله صلة سنية وجعله في ندمائه ووكله بالسقي فلم يزل معه حتى مات أخبرني الحسن بن علي الخفاف قال حدثنا أحمد بن زهير بن حرب قال حدثنا محمد بن سلام قال حدثني عمر بن أبي خليفة قال كان الشعبي مع أبي في أعلى الدار فسمعنا تحتنا غناء حسنا فقال له أبي هل ترى شيئا قال لا فنظرنا فإذا غلام حسن الوجه حديث السن يتغنى\n(قالت عبيد تجرما ... في القول فعل المازح)\nما سمعت غناء كان أحسن منه فإذا هو ابن عائشة فجعل الشعبي يتعجب من غنائه ويقول يؤتي الحكمة من يشاء","topic":"أخبار ابن عائشة ونسبه","topicNo":10,"sp":9,"spl":"الوليد يكرم المحتاجين من متذوقي الغناء — نسبة هذا الصوت"},
{"id":"b10-14","bab":"الجزء 2","sec":"نسبة هذا الصوت","page":"ج2 ص221","text":"صوت\n(قالت عبيد تجرما ... في القول فعل المازح)\n(أنجز بعمرك وعدنا ... فأظن حبك فاضحي)\n(فأجبتها لو تعلمين ... بما تجن جوانحي)\n(فما أرى لرحمتني ... من حمل حب فادح)\n(ما في البرية لي هوى ... فاسمع مقالة ناصح)\n(أشكو إليه جفاءكم ... إلا سلام مصافحي)\nزعم حبش أن الغناء لابن عائشة خفيف ثقيل بالبنصر","topic":"أخبار ابن عائشة ونسبه","topicNo":10,"sp":9,"spl":"الوليد يكرم المحتاجين من متذوقي الغناء — نسبة هذا الصوت"},
{"id":"b10-15","bab":"الجزء 2","sec":"ابن عائشة يتصدر المجلس ويغني","page":"ج2 ص222","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه قال حدثني بعض أهل المدينة قال حدثني من رأى ابن عائشة حاجا وقد دعاه فتية من بني هاشم فأجابهم قال وكنت فيهم فلما دخلنا جعلوا صدر المجلس لابن عائشة فجلس فتحدثوا حتى حضر الطعام فلما طعموا دعا بشراب فشربوا وكان ابن عائشة إذا سئل أن يغني أبى ذلك وغضب فإذا تحدث القوم بحديث ومضى فيه شعر قد غني فيه ابتدأ هو فغناه فكان من فطن له يفعل ذلك به فقال رجل منهم حدثني اليوم رجل من الأعراب ممن كان يصاحب جميلا بحديث عجيب فقال القوم و ما هو فقال حدثني أن جميلا بينما هو يحدثه كما كان يحدثه إذ أنكره ورأى منه غير ما كان يرى فثار نافرا مقشعر الشعر متغير اللون الى ناقلة له مجتمعة قريبة من الارض موثقة الخلق فشد عليها رحله ثم أتاها بمحلب فيه لبن فشربته ثم ثنى فشربت حتى رويت ثم قال اشدد أداة رحلك واشرب واسق جملك فإني ذاهب بك إلى بعض مذاهبي ففعلت فجال في ظهر ناقته وركبت ناقتي فسرنا بياض يومنا وسواد ليلتنا ثم أصبحنا فسرنا يومنا لا والله ما نزلنا إلا للصلاة فلما\nكان اليوم الثالث دفعنا إلى نسوة فمال إليهن فوجدنا الرجال خلوفا وإذا قدر لبأ وقد جهدت جوعا وعطشا فلما رأيت القدر اقتحمت عن بعيري وتركتهم جانبا ثم أدخلت رأسي في القدر ما يثنيني حرها حتى رويت فذهبت أخرج رأسي من القدر فضاقت علي وإذا هي على رأسي قلنسوة فضحكن مني وغسلن ما أصابني وأتي جميل بقرى فوالله ما التفت إليه فبينا هو يحدثهن إذا رواعي الابل وقد كان السلطان أحل لهم دمه إن وجدوه في بلادهم وجاء الناس فقلن ويحك انج وتقدم فو الله ما أكبرهم ذلك الاكبار فإذا بهم يرمونه ويطردونه فإذا غشوه قاتلهم ورمى فيهم وقام بي جملي فقال لي يسر لنفسك مركبا خلفي فأردفني خلفه لا والله ما انكسر ولا انحل عن فرصته حتى رجع إلى أهله وقد سار ست ليال وستة أيام وما التفت إلى طعام وقال في ذلك\n(إن المنازل هيجت أطرابي ... واستعجمت آياتها بجوابي)\nوهي قصيدة طويلة وقال أيضا\n(وأحسن أيامي وأبهج عيشتي ... إذا هيج بي يوما وهن قعود)\nقال فقال ابن عائشة أفر أغني لكم ذلك فقلنا بلى والله فاندفع فغناه فما سمع السامعون شيئا أحسن من ذلك وبقي أصحابنا يتعجبون من الحديث وحسنه والغناء وطيبه فقال له أصحابنا يا أبا جعفر إنا مستأذنوك فإن أذنت لنا سألناك وإن كرهت تركناك فقال سلوا فقالوا نحب أن تغنينا في مجلسنا هذا ما نشطت هذا الصوت فقط فقال لهم نعم ونعمة عين وكرامة فما زلنا في غاية السرور حتى انقضى المجلس","topic":"أخبار ابن عائشة ونسبه","topicNo":10,"sp":10,"spl":"ابن عائشة يتصدر المجلس ويغني"},
{"id":"b10-16","bab":"الجزء 2","sec":"نسبة هذا الغناء","page":"ج2 ص224","text":"صوت\n(إن المنازل هيجت أطرابي ... واستعجمت آياتها بجوابي)\n(قفر تلوح بذي اللجين كأنها ... أنضاء وشم أو سطور كتاب)\n(لما وقفت بها القلوص تبادرت ... مني الدموع لفرقة الأحباب)\n(وذكرت عصرا يا بثينة شاقني ... إذ فاتني وذكرت شرخ شبابي)\nلشعر لجميل والغناء للهذلي ثاني ثقيل بإطلاق الوتر في مجرى البنصر عن إسحاق أخبرني عمي قال حدثني عبد الله بن أبي سعد قال حدثني أحمد بن يحيى المكي عن أبيه حدثني عمرو بن أبي الكنات الحكمي قال حدثني يونس الكاتب قال كنا يوما متنزهين بالعقيق أنا وجماعة من قريش فبينا نحن على حالنا إذ أقبل ابن عائشة يمشي ومعه غلام من بني ليث وهو متوكىء على يده فلما رأى\nجماعتنا وسمعني أغني جاءنا فسلم وجلس إلينا وتحدث معنا وكانت الجماعة تعرف سوء خلقه وغضبه إذا سئل أن يغني فأقبل بعضهم على بعض يتحدثون بأحاديث كثير وجميل وغيرهما من الشعراء يستجرون بذلك أن يطرب فيغني فلم يجدوا عنده ما ارادوا فقلت لهم أنا لقد حدثني اليوم بعض الأعراب حديثا يأكل الأحاديث فإن شئتم حدثتكم إياه قالوا هات قلت حدثني هذا الرجل أنه مر بناحية الربذة فإذا صبيان يتغاطسون في غدير وإذا شاب جميل منهوك الجسم عليه أثر العلة والنحول في جسمه بين وهو جالس ينظر إليهم فسلمت عليه فرد علي السلام وقال من أين وضح الراكب قلت من الحمى قال ومتى عهدك به قلت رائحا قال وأين كان مبيتك قلت ببني فلان فقال أوه وألقى بنفسه على ظهره وتنفس الصعداء تنفسا قلت إنه خرق حجاب قلبه ثم أنشأ يقول صوت\n(سقى بلدا أمست سليمى تحله ... من المزن ما يروى به ويسيم)\n(وإن لم أكن من قاطنيه فإنه ... يحل به شخص علي كريم)\n(ألا حبذا من ليس يعدل قربه ... لدي وإن شط المزار نعيم)\n(ومن لامني فيه حميم وصاحب ... فرد بغيظ صاحب وحميم)\nم سكن كالمغشي عليه فصحت بالصبية فأتوا بماء فصببته على وجهه فأفاق وأنشأ يقول\n(إذا الصب الغريب رأى خشوعي ... وأنفاسي تزين بالخشوع)\n(ولي عين أضر بها التفاتي ... إلى الأجزاع مطلقة الدموع)\n(إلى الخلوات يأنس فيك قلبي ... كما أنس الغريب إلى الجميع)\nفقلت له ألا أنزل فأساعدك أو أكر عودي على بدئي إلى الحمى في حاجة إن كانت لك حاجة أو رسالة فقال جزيت خيرا وصحبتك السلامة امض لطيتك فلو أني علمت أنك تغني عني شيئا لكنت موضعا للرغبة وحقيقا بإسعاف المسألة ولكنك أدركتني في صبابة من حياتي يسيرة فانصرفت وأنا لا أراه يمسي ليلته إلا ميتا فقال القوم ما أعجب هذا الحديث واندفع ابن عائشة فتغنى في الشعرين جميعا وطرب وشرب بقية يومه ولم يزل يغنينا إلى أن انصرفنا فأما نسبة هذين الصوتين فإن في الأول منهما لحنا من خفيف الرمل الثقيل المطلق في مجرى الوسطى نسبه يحيى المكي إلى معبد وذكر الهشامي أنه منحول وفي هذا الخبر أن ابن عائشة غناه وهو يغني في البيت الأول والثاني من الأبيات وفيه للضيزني الملقب بنبيكة لحن جيد من الثقيل الأول وكان نبيكة هذا من حذاق المغنين وكبارهم وقد خدم المعتمد ثم شخص إلى مصر فخدم خمارويه بن أحمد ثم قدم بغداد في أيام المقتدر ورأيناه وشاهدناه وكانت في يده صبابة قوية من إفضال ابن طولون واستغنى بها حتى مات وله صنعة جيدة قد ذكرت ما وقع إلي منها في المجرد وذكرت مما وقع إلي له في هذا الكتاب لحنا\nجيدا في شعر سعد ذلفاء وهو\n(ولما وقفنا دون سرحة مالك ... )\nفي موضعه من أخباره وأما الشعر الثاني الذي ذكرت في هذا الخبر الماضي أن ابن عائشة غناه فما رأيت له نسبة في كتاب ولا سمعت فيه صنعة من أحد ولعله مما انطوى عني أو لم يشتهر فسقط عن الناس","topic":"أخبار ابن عائشة ونسبه","topicNo":10,"sp":11,"spl":"نسبة هذا الغناء","partial":1},
{"id":"b10-17","bab":"الجزء 2","sec":"تعددت الأسباب والموت واحد","page":"ج2 ص227","text":"أخبرني الحسين بن يحيى عن حماد بن إسحاق عن أبيه وأخبرني به الحسن بن علي عن هارون بن محمد بن عبد الملك الزيات عن حماد عن أبيه عن يعقوب بن طلحة الليثي عن بعض مشايخه من أهل المدينة قال أقبل ابن عائشة من الشأم حتى نزل قصر ذي خشب ومعه مال وطيب وكسا فشرب فيه ثم تطرقوا إلى ظهر القصر فصعدوا ثم نظر فإذا بنسوة يتمشين في ناحية الوادي فقال لأصحابه هل لكم فيهن قالوا وكيف لنا بهن فنهض فلبس ملاءة مدلوكة ثم قام على شرفة من شرفات القصر فتغنى\n(وقد قالت لأتراب ... لها زهر تلاقينا)\n(تعالين فقد طاب ... لنا العيش تعالينا)\nفأقبلن إليه فطرب واستدار حتى سقط من السطح وهذا الخبر يذكر على شرحه في خبر وفاته أخبرني الحسين بن يحيى قال قال حماد قرأت على أبي عن محمد بن سلام عن جرير أبي الحصين قال كان ابن عائشة إذا غنى في صوت له من شعر الحطيئة وهو\n(عفا من سليمى مسحلان فحامره ... )\nنظر إلى أعطافه في كل رنة فسئل يوما وقد دب فيه الشراب عن ذلك فقال أنا عاشق لهذا الصوت وعاشق لحديثه وعاشق لغريبه وعاشق لقول الحطيئة إن الغناء رقية من رقى النيك ويعجبني فهم الحطيئة بالغناء وليس هو من أهله ولا بصاحب غناء وكيف لا أعجب به ومحله مني هذا المحل وكان لا يسأله أحد إياه إلا غناه فمن فطن له أكثر سؤاله إياه وكان جرير يقول إنه أحسن صوت له وأرقه وأجوده","topic":"أخبار ابن عائشة ونسبه","topicNo":10,"sp":12,"spl":"تعددت الأسباب والموت واحد — وفاة ابن عائشة","partialRef":{"sid":"b8-26","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b10-18","bab":"الجزء 2","sec":"وفاة ابن عائشة","page":"ج2 ص228","text":"وتوفي ابن عائشة فيما قيل في أيام هشام بن عبد الملك وقيل في أيام الوليد وما أظن الصحيح إلا أنه توفي في أيام الوليد لأنه أقدمه إليه وذكر من زعم أنه توفي في خلافة هشام أنه إنما وفد على الوليد وهو ولي عهد أخبرني الحسين بن يحيى عن حماد عن أبيه قال\nذكر عمران بن هند أن الغمر بن يزيد خرج إلى الشأم فلما نزل قصر ذي خشب شرب على سطحه فغنى ابن عائشة صوتا طرب له الغمر فقال اردده فأبى وكان لا يرد صوتا لسوء خلقه فأمر به فطرح من أعلى السطح فمات ويقال بل قام من الليل وهو سكران ليبول فسقط من السطح فمات قال إسحاق فحدثني المدائني قال حدثني بعض أهل المدينة قال أقبل ابن عائشة من عند الوليد بن يزيد وقد أجازه وأحسن إليه فجاء بما لم يأت به أحد من عنده فلما قرب من المدينة نزل بذي خشب على أربعة فراسخ من المدينة وكان واليها إبراهيم بن هشام بن إسماعيل المخزومي ولاه هشام وهو خاله وكان في قصر هناك فقيل له أصلح الله الأمير هذا ابن عائشة قد أقبل من عند الوليد بن يزيد فلو سألته أن يقيم عندنا اليوم فيطربنا وينصرف من غد فدعا به فسأله المقام عنده فأجابه إلى ذلك فلما أخذوا في شربهم أخرج المخزومي جواريه فنظر إلى ابن عائشة وهو يغمز جارية منهن فقال لخادمه إذا خرج ابن عائشة يريد حاجته فارم به وكانوا يشربون فوق سطح ليس له إفريز ولا شرفات وهو يشرف على بستان فلما قام ليبول رمى به الخادم من فوق السطح فمات فقبره معروف هناك أخبرني الحسين بن يحيى عن حماد عن أبيه وأخبرني به الحسن بن علي عن هارون بن محمد بن عبد الملك بن حماد بن إسحاق عن أبيه عن يعقوب بن طلحة الليثي عن بعض مشايخه من أهل المدينة قال\nأقبل ابن عائشة من الشأم حتى نزل بقصر ذي خشب ومعه مال وطيب وكسا فشرب فيه ثم تطوقوا إلى ظهر القصر فصعدوا ثم نظر فإذا بنسوة يتمشين في ناحية الوادي فقال لأصحابه هل لكم فيهن قالوا وكيف لنا بهن فنهض فلبس ملاءة مدلوكة ثم قام على شرفة من شرف القصر فتغنى في شعر ابن أذينة\n(وقد قالت لأتراب ... لها زهر تلاقينا)\n(تعالين فقد طاب ... لنا العيش تعالينا)\nأقبلن إليه وطرب فاستدار فسقط فمات قال وقال قوم بل قدم المدينة فمات بها قال ولما مات قال أشعب قد قلت لكم ولكنه لا يغني حذر من قدر زوجوا ابن عائشة ربيحة الشماسية تخرج لكم بينهما مزامير داود فلم تفعلوا وجعل يبكي والناس يضحكون منه","topic":"أخبار ابن عائشة ونسبه","topicNo":10,"sp":12,"spl":"تعددت الأسباب والموت واحد — وفاة ابن عائشة"},
{"id":"b10-19","bab":"الجزء 2","sec":"نسبة هذا الصوت الذي غناه ابن عائشة","page":"ج2 ص230","text":"صوت\n(سليمى أزمعت بينا ... فأين تقولها أينا)\n(وقد قالت لأتراب ... لها زهر تلاقينا)\n(تعالين فقد طاب ... لنا العيش تعالينا)\n(وغاب البرم الليلة ... والعين فلا عينا)\n(فأقبلن إليها مسرعات ... يتهادينا)\n(إلى مثل مهاة الرمل ... تكسو المجلس الزينا)\n(إلى خود منعمة ... حففن بها وفدينا)\n(تمنين مناهن ... فكنا ما تمنينا)\nالشعر لعروة بن اذينة والغناء لابن عائشة لحنان أحدهما رمل مطلق في مجرى الوسطى عن إسحاق والآخر ثاني ثقيل بالوسطى عن حبش أخبرني الحسين بن يحيى ومحمد بن مزيد قالا حدثنا حماد بن إسحاق عن أبيه قال سمعت إبراهيم بن سعد يحلف للرشيد وقد سأله عمن بالمدينة يكره الغناء فقال من قنعه الله بخزيه مالك بن أنس ثم حلف له إنه سمع مالكا يغني\n(سليمى أزمعت بينا ... فأين تقولها أينا)\nي عرس رجل من أهل المدينة يكنى أبا حنظلة أخبرنا أحمد بن عبد العزيز وإسماعيل بن يونس قالا حدثنا عمر بن شبة قال حدثني أبو غسان محمد بن يحيى عن بعض أصحابه قال\nمر ابن عائشة بابن أذينة فقال له قل أبياتا هزجا أعن فيها فقال له اجلس فجلس فقال\n(سليمى أزمعت بيننا ... )\nالأبيات قال أبو غسان فحدثت أن ابن عائشة رواها ثم ضحك لما سمع قوله\n(تمنين مناهن ... فكنا ما تمنينا)\nثم قال له يا أبا عامر تمنينك لما أقبل بخرك وأدبر ذفرك وذبل ذكرك فجعل يشتمه هذا لفظ إسماعيل بن يونس أخبرني الجوهري وإسماعيل بن يونس قالا حدثنا عمر بن شبة قال حدثني أبو غسان قال فحدثني حماد الخشبي قال ذكر ابن أذينة عند عمر بن عبد العزيز فقال نعم الرجل أبو عامر على أنه الذي يقول\n(وقد قالت لتراب ... لها زهر تلاقينا)","topic":"أخبار ابن عائشة ونسبه","topicNo":10,"sp":13,"spl":"نسبة هذا الصوت الذي غناه ابن عائشة — ومما في المائة الصوت المختارة من أغاني ابن عائشة","partial":1},
{"id":"b10-20","bab":"الجزء 2","sec":"ولي عهد المسلمين إذ ا طرب","page":"ج2 ص232","text":"أخبرني محمد بن مزيد والحسين بن يحيى قالا حدثنا حماد عن أبيه عن المدائني عن إسحاق بن أيوب القرشي قال كان هشام بن عبد الملك مكرما للوليد بن يزيد وكان عبد الصمد بن عبد الأعلى مؤدبا للوليد وكان فيما يقال زنديقا فحمل الوليد على الشراب والاستخفاف بدينه فاتخذ ندماء وشرب وتهتك فأراد هشام قطعهم عنه فولاه\nالموسم في سنة عشر ومائة فرأى الناس منه تهاونا واستخفافا بدينه وأمر مولاه عيسى فصلى بالناس وبعث إلى المغنين فغنوه وفيهم ابن عائشة فغناه\n(سليمى أجمعت بينا ... )\nفنعر الوليد نعرة أذن لها أهل مكة وأمر لابن عائشة بألف دينار وخلع عليه عدة خلع وحمله فخرج ابن عائشة من عنده بأمر أنكره الناس وأمر للمغنين بدون ذلك فتكلم أهل الحجاز وقالوا أهذا ولي عهد المسلمين وبلغ ذلك هشاما فطمع في خلعه وأراده على ذلك فأبى وتنكر هشام للوليد وتمادى الوليد في الشرب واللذات فأفرط وتعبث هشام بالوليد وخاصته ومواليه فنزل بالأزرق بين أرض بلقين وفزارة على ماء يقال له الأغدق حتى مات هشام انقضت أخباره","topic":"أخبار ابن عائشة ونسبه","topicNo":10,"sp":13,"spl":"نسبة هذا الصوت الذي غناه ابن عائشة — ومما في المائة الصوت المختارة من أغاني ابن عائشة","partial":1},
{"id":"b10-21","bab":"الجزء 2","sec":"ومما في المائة الصوت المختارة من أغاني ابن عائشة","page":"ج2 ص233","text":"صوت\nمن رواية علي بن يحيى\n(حنت إلى برق فقلت لها قري ... بعض الحنين فإن شجوك شائقي)\n(بأبي الوليد وأم نفسي كلما ... بدت النجوم وذر قرن الشارق)\n(أثوى فأكرم في الثواء وقضيت ... حاجاتنا من عند أروع باسق)\n(لا تبعدن إداوة مطروحة ... كانت حديثا للشراب العاتق)\nيروى بالشراب العاتق عروضه من الكامل حنت يعني ناقته وهذا البيت يبتع بيتا قبله وهو\n(فإلى الوليد اليوم حنت ناقتي ... تهوي بمغبر المتون سمالق)\nوبعده حنت إلى برق وقوله قري من الوقار كأنها لما حنت أسرعت ونازعت إلى الوطن أو المقصد فقال يخاطبها قري وذر قرن الشارق طلع قرن الشمس يريد بأبي الوليد وأمي في كل ليل ونهار أبدا وأثوى أنزل والثواء الإقامة قال الأعشى\n(لقد كان في حول ثواء ثويته ... تقضى لبانات ويسأم سائم)\nوالباسق الطويل قال الله عز و جل ( والنخل باسقات\nأي طوالا ويروى\n(لا تبعدن إداوة مطروحة ... )\nالشعر لعبد الرحمن بن أرطأة المحاربي والغناء لابن عائشة ولحنه المختار ثقيل أول بإطلاق الوتر في مجرى البنصر عن إسحاق وفيه للهذلي لحن آخر من\nالثقيل الأول عن الهشامي وابن المكي فأول لحن الهذلي استهلال في\n(حنت إلى برق فقلت لها قري ... )\nوأول لحن ابن عائشة\n(بأبي الوليد وأم نفسي كلما ... بدت النجوم وذر قرن الشارق)","topic":"أخبار ابن عائشة ونسبه","topicNo":10,"sp":13,"spl":"نسبة هذا الصوت الذي غناه ابن عائشة — ومما في المائة الصوت المختارة من أغاني ابن عائشة","partial":1},
{"id":"b11-1","bab":"الجزء 2","sec":"أخبار ابن أرطأة ونسبه","page":"ج2 ص236","text":"هو عبد الرحمن بن أرطأة وقيل عبد الرحمن بن سيحان بن أرطأة بن سيحان بن عمرو بن نجيد بن سعد بن لاحب بن ربيعة بن شكم بن عبد الله ابن عوف بن زيد بن بكر بن عمير بن علي بن جسر بن محارب بن خصفة بن قيس بن عيلان بن مضر بن نزار وأم جسر بن محارب كأس بنت لكيز بن أفصى بن عبد القيس وأم علي بن جسر ماوية بنت علي بن بكر بن وائل هذه رواية أبي عمرو الشيباني أخبرني بها عمي والصولي عن الحزنبل عن عمرو بن أبي عمرو عن أبيه قال وشكم بن عبد الله أول محاربي ساد قومه وأبذهم رأسا بنفسه وكانوا جيرانا في هوازن وآل سيحان حلفاء حرب بن أمية بن عبد شمس بن عبد مناف وبمنزلة بعضهم عندهم خاصة وعند سائر بني أمية عامة أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثنا محمد بن يحيى عن عبد العزيز بن عمران قال بنو سيحان من بنى جسر بن محارب وبنو عبد مناف تقوي حلفهم وهم عندي أعزاؤهم وليسوا بأحلافهم أخبرني أحمد بن عبيد الله بن عمار وأحمد بن عبد العزيز الجوهري قالا\nحدثنا عمر بن شبة قال حدثنا محمد بن يحيى أبو غسان قال لما قتل هشام بن الوليد أبا أزيهر بعثت قريش أرطأة بن سيحان حليف حرب بن أمية إلى الشراة يحذر من بها من تجار قريش وخرج حاجز الأزدي ليخبر قومه فسبقه أرطأة وقال في ذلك وقد حذرهم فنجوا\n(مثل الحليف يشد عروته ... يثني العناج لها مع الكرب)\n(زلم إذا يسروا به يسر ... ومناضل يحمي عن الحسب)\n(هل تشكرن فهر وتاجرها ... دأب السرى بالليل والخبب)\n(حتى جلوت لهم يقينهم ... ببيان لا ألس ولا كذب)","topic":"أخبار ابن أرطأة ونسبه","topicNo":11,"sp":0,"spl":"أخبار ابن أرطأة ونسبه"},
{"id":"b11-2","bab":"الجزء 2","sec":"فحل الخمرة وليس فحل الشعر","page":"ج2 ص238","text":"وكان عبد الرحمن شاعرا مقلا إسلاميا ليس من الفحول المشهورين ولكنه كان يقول في الشراب والغزل والفخر ومدح أحلافه من بني أمية وهو أحد المعاقرين للشراب والمحدودين فيه وكان مع بني أمية كواحد منهم إلا أن اختصاصه بآل أبي سفيان وآل عثمان خاصة كان أكثر وخصوصه بالوليد بن عثمان ومؤانسته إياه أزيد من خصوصه بسائرهم لأنهما كانا يتنادمان على الشراب وهذه الأبيات التي فيها الغناء يقولها في الوليد بن عثمان وقيل بل في الوليد بن عتبة وخبره في ذلك يذكر بعد هذا أخبرنا محمد بن العباس اليزيدي قال قال عتبة بن المنهال المهلبي حدثني غير واحد من أهل الحجاز قالوا كان ابن سيحان حليفا لقريش ينزل بالمدينة وكان نديما للوليد بن عثمان فأصابه ذات يوم خمار فذهب لسانه وسكنت أطرافه وصرخ أهله عليه فأقبل الوليد إليه فزعا فلما رآه قال أخي مخمور ورب الكعبة ثم أمر غلاما له فأتاه بشراب من منزله في إداوة فأمر به فأسخن ثم سقاه إياه وقيأه وصنع له حساء وجعل على رأسه دهنا وجعل رجليه في ماء سخن فما لبث أن انطلق وذهب ما كان به ومات الوليد بعد ذلك فبينا ابن سيحان يوما جالس وبعض متاعه ينقل من بيت إلى بيت إذ مرت الخادم بإداوة الوليد التي كان داواه بما فيها من الشراب وقد يبست وتقبضت فانتحب وقال\n(لا تبعدن إداوة مطروحة ... كانت حديثا للشراب العاتق)\nوذكر باقي الأبيات أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا أحمد بن معاوية عن الواقدي قال حدثنا عبد الله بن أبي عبيدة عن أبيه قال كان الوليد بن عثمان بن عفان يشرب مع الوليد بن عتبة بن أبي سفيان وابن سيحان وكان يخمر فأصابه من ذلك شيء شديد خيف عليه وشق النساء عليه الجيوب فدعي له ابن سيحان فلما رآه قال اخرجن عني وعن أخي فخرجن فقال له الصبوح أبا عبد الله فجلس مفيقا فذلك حيث يقول ابن سيحان\n(بأبي الوليد وأم نفسي كلما ... بدت النجوم وذر قرن الشارق)\n(أثوى فأكرم في الثواء وقضيت ... حاجاتنا من عند أروع باسق)\n(كم عنده من نائل وسماحة ... وفضائل معدودة وخلائق)\n(وسماحة للمعتفين إذا اعتفوا ... في ماله حقا وقول صادق)\n(لا تبعدن إداوة مطروحة ... كانت حديثا للشراب العاتق)\nخبرني الحسين بن يحيى عن حماد بن إسحاق عن أبيه قال كان الوليد بن عثمان يكنى أبا الجهم وكان لابن سيحان صديقا ونديما وكان صاحب شراب فمرض فعاده الوليد وقال ما تشتهي قال شرابا فبعث فجائه بشراب في إداوة ثم ذكر باقي الخبر نحو الذي قبله أخبرني محمد بن خلف وكيع قال حدثني حماد بن إسحاق عن أبيه عن\n(لا تبعدن إداوة مطروحة ... كانت حديثا للشراب العاتق)\nوذكر باقي الأبيات أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا أحمد بن معاوية عن الواقدي قال حدثنا عبد الله بن أبي عبيدة عن أبيه قال كان الوليد بن عثمان بن عفان يشرب مع الوليد بن عتبة بن أبي سفيان وابن سيحان وكان يخمر فأصابه من ذلك شيء شديد خيف عليه وشق النساء عليه الجيوب فدعي له ابن سيحان فلما رآه قال اخرجن عني وعن أخي فخرجن فقال له الصبوح أبا عبد الله فجلس مفيقا فذلك حيث يقول ابن سيحان\n(بأبي الوليد وأم نفسي كلما ... بدت النجوم وذر قرن الشارق)\n(أثوى فأكرم في الثواء وقضيت ... حاجاتنا من عند أروع باسق)\n(كم عنده من نائل وسماحة ... وفضائل معدودة وخلائق)\n(وسماحة للمعتفين إذا اعتفوا ... في ماله حقا وقول صادق)\n(لا تبعدن إداوة مطروحة ... كانت حديثا للشراب العاتق)\nخبرني الحسين بن يحيى عن حماد بن إسحاق عن أبيه قال كان الوليد بن عثمان يكنى أبا الجهم وكان لابن سيحان صديقا ونديما وكان صاحب شراب فمرض فعاده الوليد وقال ما تشتهي قال شرابا فبعث فجائه بشراب في إداوة ثم ذكر باقي الخبر نحو الذي قبله أخبرني محمد بن خلف وكيع قال حدثني حماد بن إسحاق عن أبيه عن\nحذف 240","topic":"أخبار ابن أرطأة ونسبه","topicNo":11,"sp":1,"spl":"فحل الخمرة وليس فحل الشعر"},
{"id":"b11-3","bab":"الجزء 2","sec":"فحل الخمرة وليس فحل الشعر","page":"ج2 ص238","text":"أيوب بن عباية قال كان الوليد بن عثمان ذا غلة في الحجاز يخرج إليها في زمان التمر بنفر من قومه يجنون له ويعاونونه فكان إذا حضر خروجهم دفع إليهم نفقات لأهليهم إلىرجعتهم فخرج بهم مرة كما كان يخرج وفيهم ابن سيحان فأتى ابن سيحان كتاب من أهله يسألونه القدوم لحاجة لا بد منها فاستأذنه فأذن له فقال له ابن سيحان زودوني من شرابكم هذا فزودوه إداوة ملأها له من شرابهم فكان يشربها في طريقه حتى قدم على أهله فألقاها في جانب بيته فارغة فمكث زمانا لا يذكرها ثم كنسوا البيت فرآها ملقاة في الكناسة فقال\n(لا تبعدن إداوة مطروحة ... كانت حديثا للشراب العاتق)\n(إن تصبحي لا شيء فيك فربما ... أترعت من كأس تلذ لذائق)\n(بأبي الوليد وأم نفسي كلما ... بدت النجوم وذر قرن الشارق)\n(كم عنده من نائل وسماحة ... وشمائل ميمونة وخلائق)\n(وكرامة للمعتفين إذا اعتفوا ... في ماله حقا وقول صادق)\n(أثوى فأكرم في الثواء وقضيت ... حاجاتنا من عند أروع باسق)\n(لما أتيناه أتينا ماجد الأخلاق ... سباقا لقرم سابق)\n(قال الوليد يدي لكم رهن بما ... حاولتم من صامت أو ناطق)\n(فإلى الوليد اليوم حنت ناقتي ... تهوي بمغبر المتون سمالق)\n(حنت إلى برق فقلت لها قري ... بعض الحنين فإن شجوك شائقي)","topic":"أخبار ابن أرطأة ونسبه","topicNo":11,"sp":2,"spl":"فحل الخمرة وليس فحل الشعر"},
{"id":"b11-4","bab":"الجزء 2","sec":"مروان والوليد بن عثمان يضر بانه الحد","page":"ج2 ص240","text":"خبرني عمي قال حدثني محمد بن عبد الله التميمي الأصبهاني المعروف بالحزنبل قال حدثني عمرو بن أبي عمرو الشيباني عن أبيه وأخبرني الحسين بن يحيى المرداسي قال قال حماد بن إسحاق قرأت على أبي قالا جميعا\nكان عبد الرحمن بن سيحان قد غاظ مروان بن الحكم أيام كان معاوية يعاقب بينه وبين سعيد بن العاص في ولاية الحرمين وأنكر عليه أشياء بلغته فغاظته من مدحه سعيدا وانقطاعه إليه وسروره بولايته فرصده حتى وجده خارجا من دار الوليد بن عثمان وهو سكران فضربه الحد ثمانين سوطا وقدم البريد من المدينة على معاوية فسأله عن أخبار الناس فجعل يخبره بها حتى انتهى به الحديث إلى ابن سيحان فأخبره أن مروان ضربه الحد ثمانين فغضب معاوية وقال والله لو كان حليف أبي العاص لما ضربه ولكنه ضربه لأنه حليف حرب أليس هو الذي يقول\n(وإني امرؤ حلف إلى أفضل الورى ... عديدا إذا ارفضت عصا المتحلف)\nذب والله مروان لا يضربه في نبيذ أهل المدينة وشكهم وحمقهم ثم قال لكاتبه أكتب إلى مروان فليبطل الحد عن ابن سيحان وليخطب بذلك على المنبر وليقل إنه كان ضربه على شبهة ثم بان له أنه لم يشرب مسكرا وليعطه ألفي درهم فلما ورد الكتاب على مروان عظم ذلك عليه ودعا بابنه عبد الملك فقرأه عليه وشاوره فيه فقال له عبد الملك راجعه ولا تكذب نفسك ولا تبطل حكمك فقال مروان أنا أعلم بمعاوية إذا عزم على شيء أو أراده لا والله لا اراجعه فلما كان يوم الجمعة وفرغ من الخطبة قال وابن سيحان فإنا كشفنا أمره فإذا هو لم يشرب مسكر وإذا نحن قد عجلنا عليه وقد أبطلت عنه الحد ثم نزل فأرسل إليه بألفي درهم\nأخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثني أحمد بن معاوية عن الواقدي قال حدثني عبد الرحمن بن أبي الزناد عن أبيه قال كان عبد الرحمن بن سيحان المحاربي شاعرا وكان حلو الأحاديث عنده أحاديث حسنة غريبة من أخبار العرب وأيامها وأشعارها وكان على ذلك يصيب من الشراب فكان كل من قدم من ولاة بني أمية وأحداثهم ممن يصيب الشراب يدعوه وينادمه فلما ولي الوليد بن عتبة بن أبي سفيان وعزل مروان وجد مروان في نفسه وكان قد سبعه فحقد ذلك عليه مروان واضطغنه وكان الوليد يصيب من الشراب ويبعث إلى ابن سيحان فيشرب معه وابن سيحان لايظن أن مروان يفعل به الذي فعله وقد كان مدحه بان سيحان ووصله مروان ولكن مروان أراد فضيحة الوليد فرصده ليلة في المسجد وكان ابن سيحان يخرج في السحر من عند الوليد ثملا فيمر في المقصورة من المسجد حتى يخرج في زقاق عاصم وكان محمد بن عمرو يبيت في المسجد يصلي وكذلك عبد الله بن حنظلة وغيرهما من القراء يبيتون في المسجد يتهجدون فلما خرج ابن سيحان ثملا من دار الوليد أخذه مروان وأعوانه ثم دعا له محمد بن عمرو وعبد الله بن حنظلة فأشهدهما على سكره وقد سأله أن يقرأ أم القرآن فلم يقرأها فدفعه إلى صاحب شرطته فحبسه فلما أصبح الوليد بلغه الخبر وشاع في المدينة وعلم أن مروان إنما أراد أن يفضحه وأنه لو لقي ابن سيحان ثملا خارجا من عند غيره لم يعرض له فقال الوليد لا يبرئني من هذا عند أهل المدينة إلا ضرب ابن سيحان فأمر صاحب شرطته فضربه الحد ثم أرسله فجلس ابن سيحان في بيته\nلا يخرج حياء من الناس فجاءه عبد الرحمن بن الحارث بن هشام في ولده وكان له جليسا فقال له ما يجلسك في بيتك قال الإستحياء من الناس قال اخرج أيها الرجل وكان عبد الرحمن قد حمل له معه كسوة فقال له البسها ورح معنا إلى المسجد فهذا أحرى أن يكذب به مكذب ثم ترحل إلى أمير المؤمنين فتخبره بما صنع بك الوليد فإنه يصلك ويبطل هذا الحد عنك فراح مع عبد الرحمن في جماعة ولده متوسطا لهم حتى دخل المسجد فصلى ركعتين ثم تساند مع عبد الرحمن إلى الأسطوانة فقائل يقول لم يضرب وقائل يقول أنا رأيته يضرب وقائل يقول عزر أسواطا","topic":"أخبار ابن أرطأة ونسبه","topicNo":11,"sp":3,"spl":"مروان والوليد بن عثمان يضر بانه الحد"},
{"id":"b11-5","bab":"الجزء 2","sec":"معاوية يبطل الحد عن ابن أرطأة","page":"ج2 ص243","text":"فمكث أياما ثم رحل إلى معاوية فدخل إلى يزيد فشرب معه وكلم يزيد أباه معاوية في أمره فدعا به فأخبره بقصته وما صنعه به مروان فقال قبح الله الوليد ما أضعف عقله أما استحيا من ضربك فيما شرب وأما مروان فإني كنت لا أحسبه يبلغ هذا منك مع رأيك فيه ومودتك له ولكنه أراد أن يضع الوليد عندي ولم يصب وقد صير نفسه في حد كنا ننزهه عنه صار شرطيا ثم قال لكاتبه اكتب بسم الله الرحمن الرحيم من عبد الله معاوية أمير المؤمنين إلى الوليد بن عتبة أما بعد فالعجب لضربك ابن سيحان فيما تشرب منه ما زدت على أن عرفت أهل المدينة ما كنت تشربه مما حرم عليك فإذا جاءك كتابي هذا فأبطل الحد عن ابن سيحان وطف به في حلق المسجد وأخبرهم أن صاحب شرطك تعدى عليه وظلمه وأن أمير المؤمنين قد أبطل ذلك عنه أليس ابن سيحان الذي يقول\n(وإني امرؤ أنمى إلى أفضل الورى ... عديدا إذا ارفضت عصا المتحلف)\n(إلى نضد من عبد شمس كأنهم ... هضاب أجا أركانها لم تقصف)\n(ميامين يرضون الكفاية إن كفوا ... ويكفون ما ولوا بغير تكلف)\n(غطارفة ساسوا البلاد فأحسنوا ... سياستها حتى أقرت لمردف)\n(فمن يك منهم موسرا يفش فضله ... ومن يك منهم معسرا يتعفف)\n(وإن تبسط النعمى لهم يبسطوا بها ... أكفا سباطا نفعها غير مقرف)\n(وإن تزو عنهم لا يضجوا وتلفهم ... قليلي التشكي عندها والتكلف)\n(إذا انصرفوا للحق يوما تصرفوا ... إذا الجاهل الحيران لم يتصرف)\n(سموا فعلوا فوق البرية كلها ... ببنيان عال من منيف ومشرف)\nال وكتب له بأن يعطى أربعمائة شاة وثلاثين لقحة مما يوطن السيالة وأعطاه هو خمسمائة دينار وأعطاه يزيد مائتي دينار ثم قدم بكتاب معاوية إلى الوليد فطاف به في المسجد وأبطل ذلك الحد عنه وأعطاه ما كتب به له معاوية وكتب معاوية إلى مروان يلومه فيما فعله بابن سيحان وما أراده بذلك ودعا الوليد عبد\nالرحمن بن سيحان إلى أن يعود للشرب معه فقال والله لا ذقت معك شرابا أبدا أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثنا أبو مسلم الغفاري قال حدثني موسى بن عبد العزيز قال أخذ ابن سيحان الجسري هكذا قال وهو غلط في شراب في إمارة مروان وكان حليفا لأبي سفيان بن حرب فضربه مروان ثمانين سوطاعلى رؤوس الناس فكتب إلى معاوية يشكوه فكتب إ ليه معاوية أما بعد فإنك أخذت حليف حرب فضربته ثمانين علي رؤوس الناس والله لتبطلنها عنه أو لأقيدنه منك فقال مروان لابنه عبد الملك ما ترى قال أرى والله ألا تفعل قال ويحك أنا أعلم بعزمات معاوية منك فصعد المنبر فحمد الله وأثنى عليه ثم قال أيها الناس إنا كنا ضربنا ابن سيحان بشهادة رجل من الحرس ووجدناه غير عدل ولا رضا فاشهدوا أني قد أبطلت ذلك الحد عنه أخبرني أحمد قال حدثنا عمر قال حدثني محمد بن يحيى قال حدثني عبد العزيز بن عمران قال ضرب مروان عبد الرحمن بن سيحان في الخمر ثمانين سوطا فكتب إليه معاوية أما بعد فإنك ضربت عبد الرحمن في نبيذ أهل الشأم الذي يستعملونه وليس بحرام وإنما ضربته حيث كان حلفه إلى أبي سفيان بن حرب وايم الله لو كان حليفا للحكم ما ضربته فأبطل عنه الحد قبل أن أضرب من أخذ معه أخاك عبد الرحمن بن الحكم فأبطل مروان عنه الحد فقال ابن سيحان في ذلك يذكر حلفه\n(إني امرؤ عقدي إلى أفضل الورى ... عديدا إذا ارفضت عصا المتحلف)\nوقال الطوسي كان عبد الرحمن بن الحكم أخو مروان يشرب مع ابن سيحان فلما ضربه مروان الحد كتب إليه معاوية والله لتبطلنه عنه أو لأبعثن إلى أخيك من يضرب ظهره بالسوط في السوق أليس ابن سيحان الذي يقول\n(سموت بحلفي للطوال من الربى ... ولم تلقني قنا لدى مبرك الجرب)\n(إذا ما حليف الذل أقمأ شخصه ... ودب كما دب الحسير على نقب)\n(وهصت الحصى لا أخنس الأنف قابعا ... إذا أنا راخى لي خناقي بنو حرب)\nخبرني الحرمي بن أبي العلاء وأحمد بن سليمان الطوسي قالا حدثنا الزبير ابن بكار قال حدثنا عمي مصعب وغيره قالوا","topic":"أخبار ابن أرطأة ونسبه","topicNo":11,"sp":4,"spl":"معاوية يبطل الحد عن ابن أرطأة"},
{"id":"b11-6","bab":"الجزء 2","sec":"ابن أرطأة يرثي سعيد بن عثمان","page":"ج2 ص246","text":"قدم سعيد بن عثمان المدينة فقتله غلمان جاء بهم من الصغد وكان معه عبد الرحمن بن أرطأة بن سيحان حليف بني حرب بن أمية فهرب عنه لما\nقتلوه فقال خالد بن عقبة بن أبي معيط يرثي سعيد بن عثمان وعثمان أخوه لأمه\n(يا عين جودي بدمع منك تهتانا ... وابكي سعيد بن عثمان بن عفانا)\n(إن ابن زينة لم تصدق مودته ... وفر عنه ابن أرطأة بن سيحانا)\nفقال ابن سيحان يعتذر من ذلك\n(يقول رجال قد دعاك فلم تجب ... وذلك من تلقاء مثلك رائع)\n(فإن كان نادى دعوة فسمعتها ... فشلت يدي واستك مني المسامع)\n(وإلا فكانت بالذي قال باطلا ... ودارت عليه الدائرات القوارع)\n(يلومونني أن كنت في الدار حاسرا ... وقد فر عنه خالد وهو دارع)\nفقال بعض الشعراء يجيبه\n(فإنك لم تسمع ولكن رأيته ... بعينك إذ مجراك في الدار واسع)\n(وأسلمته للصغد تدمى كلومه ... وفارقته والصوت في الدار شائع)\n(وما كان فيها خالد بمعذر ... سواء عليكم صم أو هو سامع)\n(فلا زلتما في غل سوء بعبرة ... ودارت عليكم بالشمات القوارع)\nخبرني عمي قال حدثني الكراني قال حدثنا العمري عن العتبي قال لما قتل سعيد بن عثمان بن عفان قالت أمه أشتهي أن يرثيه شاعر كما في نفسي حتى أعطيه ما يحتكم فقال ابن سيحان\n(إن كنت باكية فتى ... فأبكي هبلت على سعيد)\n(فارقت أهلك بغتة ... وجلبت حتفك من بعيد)\n(أذري دموعك والدماء ... على الشهيد ابن الشهيد)\nفقالت هكذا كنت أشتهي أن يقال فيه ووصلت ابن سيحان وكانت تندبه بهذا الشعر قال أبو عمرو في روايته التي ذكرتها عن عمي عن الحزنبل عن عمرو بن أبي عمرو عن أبيه قال جلس ابن سيحان وخالد بن عقبة بعد مقتل سعيد بن عثمان يتحدثان فجرى ذكره فبكيا جميعا عليه فقال ابن سيحان يرثيه\n(ألا إن خير الناس إن كنت سائلا ... سعيد بن عثمان القتيل بلا ذحل)\n(تداعت عليه عصبة فارسية ... فأضحى سعيد لا يمر ولا يحلي)\nوقال خالد بن عقبة\n(ألا إن خير الناس نفسا ووالدا ... سعيد بن عثمان قتيل الأعاجم)\n(بكت عين من لم يبكه وسط يثرب ... مدى الدهر منه بالدموع السواجم)\n(فإن تكن الأيام أردت صروفها ... سعيدا فمن هذا عليها بسالم)\nقال الحزنبل أنشدني عمرو بن أبي عمرو عن أبيه لابن سيحان قال عمي وأنشدني السكري عن ابن حبيب والطوسي له\nصوت\n(رحم الله صاحبي ابني الحارث ... إذ ينهيانني أن أبوحا)\n(بالتي تيمت فؤادي وأن أذري ... دموعي على ردائي سفوحا)\n(في مغاني منازل من حبيب ... باشرت بعده قطارا وريحا)\n(ولقد قلت للفؤاد ولكن ... كان قدما إلى هواه جموحا)\n(قلت أقصر عن بعض حبك أروى ... إن بعض الحباب كان فضوحا)\n(فعصاني فليس يسمع قولا ... من حمام على الأراك جنوحا)\n(أم يحيى تقبل الله يحيى ... بقبول كما تقبل نوحا)\n(أم يحيى لولا طلابك قد سحت ... مع الوحش أو لبست المسوحا)\n(ولقد قلت لا أحدث سرا ... سر أخرى ما دمت أمشي صحيحا)\nالغناء لمعبد خفيف ثقيل أول بالسبابة في مجرى الوسطى عن إسحاق ويونس وفيه للغريض ثقيل أول عن الهشامي وفيه لزريق رمل قال أبو عمرو وابن سيحان الذي يقول\n(ألا هل هاجك الأظعان ... إذ جاوزن مطلحا)","topic":"أخبار ابن أرطأة ونسبه","topicNo":11,"sp":5,"spl":"ابن أرطأة يرثي سعيد بن عثمان"},
{"id":"b11-7","bab":"الجزء 2","sec":"هجاء ابن أرطأة لبني مطيع","page":"ج2 ص249","text":"والناس يروونه لعمر بن أبي ربيعة لغلبته على أهل الحجاز جميعا وقال أبو عمرو في خبره كان ابن سيحان يحدث قال كنت آلف من قريش أهل بيتين سوى من كنت منقطعا إليه من بني أمية بني عبد الرحمن بن الحارث بن هشام وبني\nمطيع فلما ضربني مروان الحد جئت فجلست إلى بني مطيع كما كنت أجلس فلما رأوني عرفت الكراهة في وجوههم والله ما أقبلوا علي بحديثهم ولا وسعوا لي فانصرفت ورحت إلى بني عبد الرحمن فلما رأوني أقبلوا بوجوههم علي وحيوا ورحبوا وسهلوا ووسعوا ورفعوني إلى حيث لم أكن أجلس وأقبلوا علي بوجوههم يحدثونني وقالوا لعلك خشعت للذي لحقك أما والله لقد علم الناس أنك مظلوم وظلموا مروان في فعله ورأوا أنه قد أساء وأخطأ في شأنك وقالوا ما ضرك ذلك ولا نقصك ولا زادك إلا خيرا ولم يزالوا حتى بسطوني فقلت أمدحهم وأذم بني مطيع\n(لقد حرمت ود بني مطيع ... حرام الدهن للرجل الحرام)\n(وإن جنف الزمان مددت حبلا ... متينا من حبال بني هشام)\n(رطيب عودهم أبدا وريق ... إذا ما اغبر عيدان اللئام)\nقال أبو عمرو في خبره كان عبد الرحمن بن سيحان ينادم الوليد بن عثمان على الشراب فيبيت عنده خوفا من أن يظهر وهو سكران فيحد فقالت له امرأته قد صرت لا تبيت في منزلك وأظنك قد تزوجت وإلا فما مبيتك عن أهلك فقال لها\n(لا تعدميني نديما ماجدا أنفا ... لا قائلا قاذفا خلقا ببهتان)\n(أغر روواقه ملآن صافية ... تنفي القذى عن جبين غير خزيان)\n(سبيئة من قرى بيروت صافية ... عذراء أو سبئت من أرض بيسان)\n(إنا لنشربها حتى تميل بنا ... كما تمايل وسنان بوسنان)","topic":"أخبار ابن أرطأة ونسبه","topicNo":11,"sp":6,"spl":"هجاء ابن أرطأة لبني مطيع"},
{"id":"b11-8","bab":"الجزء 2","sec":"يشرب الخمرة ويحث على شربها","page":"ج2 ص251","text":"أخبرني محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه عن عاصم بن الحدثان قال كان بن سيحان صاحب شراب فدخل على ابن عم له يقال له الحارث بن سريع فوجده يشرب نبيذ زبيب فجعل يعظه ويأمره بشرب الخمر وقال له يابن سريع إن كنت تشربه على أن نبيذ الزبيب حلال فإنك أحمق وإن كنت تشربه على أنه حرام تستغفر الله منه وتنوي التوبة فاشرب أجوده فإن الوزر واحد ثم قال\n(دع ابن سريع شرب ما مات مرة ... وخذها سلافا حية مزة الطعم)\n(تدعك على ملك ابن ساسان قادرا ... إذا حرمت قراؤنا حلب الكرم)\n(فشتان بين الحي والميت فاعتزم ... على مزة صفراء راووقها يهمي)\n(فإن سريعا كان أوصى بحبها ... بنيه وعمي جاوز الله عن عمي)\n(ويا رب يوم قد شهدت بني أبي ... عليها إلى أن غاب تالية النجم)\n(حسوها صلاة العصر والشمس حية ... تدار عليهم بالصغير وبالضخم)\n(فماتوا وعاشوا والمدامة بينهم ... مشعشعة كالنجم توصف بالوهم)\nأخبرني محمد بن مزيد قال حدثنا حماد عن أبيه عن عاصم بن الحدثان قال كان ابن سيحان حليف حرب بن أمية ينادم الوليد بن عقبة بن أبي معيط ويشرب معه الخمر وهو القائل\n(إصبح نديمك من صهباء صافية ... حتى يروح كريما ناعم البال)\n(واشرب هديت أبا وهب مجاهرة ... واختل فإنك من قوم أولي خال)\n(أنت الجواد أبا وهب إذا جمدت ... أيدي الرجال بما تحويه من مال)\n(لولا رجاؤك قد شمرت مرتجلا ... عنسا تعاقب تخويدا بإرقال)\n(لما تواصوا بقتلي قمت معتزما ... حتى حميت من الأعداء أوصالي)\n(عم الوليد بمعروف عشيرته ... والأبعدون حظوا منه بإفضال)\nال وكان ابن سيحان قد ضرب رجلا من أخواله بالسيف فقطع يده ولم تقم عليه بينة فتآمر به القوم ومنع منه ابن خال له منهم وخاف الوليد بن عقبة أن يرجع إلى المدينة هاربا منهم وخوفا من جنايته عليهم فيفارقه وينقطع عنه فدعاهم وأرضاهم وأعطاهم دية صاحبهم فلم يزل عند الوليد حتى عزل وهو نديمه\nوصفيه وهو القائل في الوليد وفيه غناء صوت\n(بات الوليد يعاطينى مشعشعة ... حتى هويت صريعا بين أصحابي)\nفي الغناء بات الكريم يعاطيني\n(لا أستطيع نهوضا إن هممت به ... وما أنهنه من حسو وتشراب)\n(حتى إذا الصبح لاحت لي جوانبه ... وليت أسحب نحو القوم أثوابي)\n(كأنني من حميا كأسه جمل ... صحت قوائمه من بعد أوصاب)\nويروى\n(كأنني من حميا كأسه ظلع ... )\nلغناء ليحيى المكي وروي ضلع خفيف ثقيل بالبنصر عن الهشامي وبذل قالت بذل وفيه لحن آخر ليحيى ولم تذكر طريقته أخبرني محمد بن مزيد قال حدثنا الزبير بن بكار قال حدثني أبو فهيرة قال دخل عبد الرحمن بن أرطأة على سعيد بن العاص وهو أمير المدينة فقال له ألست القائل\n(إنا لنشربها حتى تميل بنا ... كما تمايل وسنان بوسنان)\nفقال له عبد الرحمن معاذ الله أن أشربها وأنعتها ولكني الذي أقول\n(سموت بحلفي للطوال من الذرى ... ولم تلقني كالنسر في ملتقى جدب)\n(إذا ما حليف القوم أقعى مكانه ... ودب كما يمشي الحسير من النقب)\n(وهصت الحصى لا أرهب الضيم قائما ... إذا أنا راخى لي خناقي بنو حرب)\nقام يجر مطرفه بين الصفين حتى خرج فأقبل عمرو بن سعيد على أبيه فقال لو أمرت بهذا الكلب فضرب مائتي سوط كان خيرا له فقال يا بني أضربه وهو حليف حرب بن أمية ومعاوية خليفة بالشام إذا لا يرضى فلما حج معاوية لقيه بمنى فقال إيه يا سعيد أمرك أحمقك بأن تضرب حليفي مائتي سوط أما والله لو جلدته سوطا لجلدتك سوطين فقال له سعيد ولم ذاك أولم تجلد أنت حليفك عمر بن جبلة فقال له معاوية هو لحمي آكله ولا أوكله قال وكان ابن سيحان قد قال\n(لا يعدمني نديمي ماجدا أنفا ... لا قائلا خالطا زورا ببهتان)\n(أمسي أعاطيه كأسا لذ مشربها ... كالمسك خفت بنسرين وريحان)\n(سبيئة من قرى بيروت صافية ... أو التي سبئت من أرض بيسان)\n(إنا لنشربها حتى تميل بنا ... كما تمايل وسنان بوسنان)\nانقضت أخباره صوت","topic":"أخبار ابن أرطأة ونسبه","topicNo":11,"sp":7,"spl":"يشرب الخمرة ويحث على شربها","partial":1},
{"id":"b11-9","bab":"الجزء 2","sec":"من المائةالمختارة من رواية علي بن يحيى","page":"ج2 ص254","text":"(يا خليلي هجرا كي تروحا ... هجتما للرواح قلبا قريحا)\n(إن تريغا لتعلما سر سعدى ... تجداني بسر سعدى شحيحا)\n(إن سعدى لمنية المتمني ... جمعت عفة ووجها صبيحا)\n(كلمتني وذاك ما نلت منها ... إن سعدى ترى الكلام ربيحا)\nلشعر لابن ميادة والغناء لحنين ولحنه المختار من الثقيل الأول بإطلاق الوتر في مجرى البنصر عن إسحاق وذكر عمرو بن بانة أن فيه لدحمان لحنا من الثقيل الأول بالبنصر وأظنه هذا وأن عمرا غلط في نسبته إلى دحمان","topic":"أخبار ابن أرطأة ونسبه","topicNo":11,"sp":8,"spl":"من المائةالمختارة من رواية علي بن يحيى"},
{"id":"b12-1","bab":"الجزء 2","sec":"أخبار ابن ميادة ونسبه","page":"ج2 ص256","text":"اسمه الرماح بن أبرد بن ثوبان بن سراقة بن حرملة هكذا قال الزبير بن بكار في نسبه وقال ابن الكلبي ثوبان بن سراقة بن سلمى بن ظالم ويقال سراقة بن قيس بن سلمى بن ظالم بن جذيمة بن يربوع بن غيظ بن مرة بن عوف ابن سعد بن ذبيان بن بغيض بن ريث بن زيد بن غطفان بن سعد بن قيس بن عيلان بن مضر وأمه ميادة أم ولد بربرية وروي أنها كانت صقلبية ويكنى أبا شرحبيل وقيل بل يكنى أبا شراحيل\n(وكان ابن ميادة يزعم أن أمه فارسية وذكر ذلك في شعره فقال ... )\n(أنا ابن سلمى وجدي ظالم ... وأمي حصان أخلصتها الأعاجم)\n(أليس غلام بين كسرى وظالم ... بأكرم من نيطت عليه التمائم)\nخبرني بذلك الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني أبو مسلمة مرهوب بن سيد وأخبرني الحرمي قال حدثنا الزبير قال حدثني موسى بن زهير الفزاري قال أخبرني موسى بن سيار بن نجيح المزني قال أنشدني ابن ميادة أبياته التي يقول فيها\n(أليس غلام بين كسرى وظالم ... بأكرم من نيطت عليه التمائم)\nقلت له لقد أشحطت بدا العجوز وأبعدت بها النجعة فهلا غربت يريد\nأنها صقلبية ومحلها بناحية المغرب فقال إي بأبي أنت إنه من جاع انتجع فدعها تسر في الناس فإنه من يسمع يخل قال الزبير قال ابن مسلمة ولما قال ابن ميادة هذه الأبيات قال الحكم الخضري يرد عليه\n(وما لك فيهم من أب ذي دسيعة ... ولا ولدتك المحصنات الكرائم)\n(وما أنت إلا عبدهم إن تربهم ... من الدهر يوما تستربك المقاسم)\n(رمى نهبل في فرج أمك رمية ... بحوقاء تسقيها العروق الثواجم)\nال أبو مسلمة ونهبل عبد لبني مرة كانت ميادة تزوجته بعد سيدها وكانت صقلبية وابن ميادة شاعر فصيح مقدم مخضرم من شعراء الدولتين وجعله ابن سلام في الطبقة السابعة وقرن به عمر بن لجأ والعجيف العقيلي والعجير السلولي","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":0,"spl":"أخبار ابن ميادة ونسبه","partial":1},
{"id":"b12-2","bab":"الجزء 2","sec":"ابن ميادة يتعرض للمهاجاة","page":"ج2 ص258","text":"أخبرني علي بن سليمان الأخفش قال حدثنا الحسن بن الحسين السكري قال حدثنا محمد بن حبيب عن ابن الأعربي قال كان ابن ميادة عريضا للشر طالبا مهاجاة الشعراء ومسابة الناس وكان يضرب بيده على جنب أمه ويقول\n(اعرنزمي مياد للقوافي ... )\nأي إني سأهجو الناس فيهجونك وأخبرنا يحيى بن علي عن أبي هفان بهذه الحكاية مثله وزاد فيها\n(لإعرنزمي مياد للقوافي ... واستسمعيهن ولا تخافي)\n(ستجدين ابنك ذا قذاف ... )\nخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثنا داود بن علفة الأسدي قال جاورت امرأة من الخضر رهط الحكم الخضري أبيات ابن ميادة فجاءت ذات يوم تطلب رحى وثفالا لتطحن فأعاروها إياهما فقال لها ابن ميادة يا أخت الخضر أتروين شيئا مما قاله الحكم الخضري لنا يريد بذلك أن تسمع أمه فجعلت تأبى فلم يزل حتى أنشدته\n(أمياد قد أفسدت سيف ابن ظالم ... ببظرك حتى عاد أثلم باليا)\nقال وميادة جالسة تسمع فضحك الرماح وثارت ميادة إليها بالعمود تضربها به وتقول أي زانية هيا زانية أإياي تعنين وقام ابن ميادة يخلصها فبعد لأي ما أنقذها وقد انتزعت منها الرحى والثفال أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني أبو حرملة منظور بن أبي عدي الفزاري قال حدثني شماطيط وهو الذي يقول\n(أنا شماطيط الذي حدثت به ... متى أنبه للغداء أنتبه)\n(حتى يقال شره ولست به ... )\nقال كنت جالسا مع ابن ميادة فوردت عليه أبيات للحكم الخضري يقول فيها\n(أأنت ابن أشبانية أدلجت به ... إلى اللؤم مقلات لئيم جنينها)\nشبانية صقلبية قال وأمه ميادة تسمع فضرب جنبها وقال\n(إعرنزمي مياد للقوافي ... )\nقالت هذه جنايتك يابن من خبت وشر وأهوت إلى عصا تريد ضربه بها ففر منها وهو يقول\n(يا صدقها ولم تكن صدوقا ... )\nفصحت به أيهما المعني فقال أضرعهما خدين وألأمهما جدين فضربت جنبها الآخر وقلت فهي إذا ميادة وخرجت أعدو في أثر الرماح وتبعتنا ترمينا بالحجارة وتفتري علينا حتى فتناها أخبرني يحيى بن علي بن يحيى قال حدثنا حماد بن إسحاق عن أبيه قال حدثني أبو داود الفزاري أن ميادة كانت أمة لرجل من كلب زوجة لعبد له يقال له نهبل فاشتراها بنو ثوبان بن سراقة فأقبلوا بها من الشام فلما قدموا وصبحوا بها المليحة وهي ماءة لبني سلمى ورحل بن ظالم بن جذيمة نظر رجل من بني سلمى إليها وهي ناعسة تمايل على بعيرها فقال ما هذه قالوا اشتراها بنو ثوبان فقال وأبيكم إنها لميادة تميد وتميل على بعيرها فغلب عليها ميادة وكان أبرد ضلة من الضلل ورثة من الرثث جلفا لا تخلص إحدى يديه من الاخرى يرعى على إخوته وأهله وكانت إخوته كلهم ظرفاء غيره فأرسلوا ميادة ترعى الأبل معه فوقع عليها فلم يشعروا بها إلا حبلى قد أقعسها بطنها فقالوا لها لمن ما في بطنك قالت لأبرد وسألوه فجعل يسكت ولا يجيبهم حتى رمت بالرماح فرأوا غلاما فدغما نجيبا فأقر به أبرد وقالت بنو سلمى ويلكم يابني ثوبان ابتطنوه فلعله ينجب فقالوا والله ما له غير ميادة فبنوا لها\nبيتا وأقعدوها فيه فجاءت بعد الرماح بثوبان وخليل وبشير بني أبرد وكانت أول نسائه و آخرهن و كانت امرأة صدق ما رميت بشيء ولا سبت إلا بنهبل قال عبد الرحمن بن جهيم الأسدي في هجائه ابن مياده\n(لعمري لئن شابت حليلة نهبل ... لبئس شباب المرء كان شبابها)\n(و لم تدر حمراء العجان انهبل ... أبوه أم المري تب تبابها)\nال أبو داود وكان ابن ميادة هجا بني مازن وفزارة بن ذبيان وذلك أنهم ظلموا بني الصارد والصارد من مرة فأخذوا مالهم و غلبوهم عليه حتى الساعة فقال ابن ميادة\n(فلأوردن على جماعة مازن ... خيلا مقلصة الخصى ورجالا)\n(ظلوا بذي أرك كأن رؤسهم ... شجر تخطاه الربيع فحالا)\nفقال رجل من بني مازن يرد عليه\n(يا بن الخبيثه يا بن طلة نهبل ... هلا جمعت كما زعمت رجالا)\n(أببظر ميدة أم بخصيي نهبل ... أم بالفساة تنازل الأبطالا)\n(و لئن وردت على جماعة مازن ... تبغي القتال لتلقين قتالا)\nقال وبنو مرة يسمون الفساه لكثرة امتيارهم التمر وكانت منازلهم بين\nفدك وخيبر فلقبوا بذلك لأكلهم التمر وقال يحيى بن علي في خبره ولم يذكره عن أحد وقال ابن ميادة يفتخر بأمه\n(أنا ابن ميادة تهوي نجبي ... سلط الجبين حسن مركبي)\n(ترفعني أمي و ينميني أبي ... فوق السحاب ودوين الكوكب)","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":1,"spl":"ابن ميادة يتعرض للمهاجاة","partial":1},
{"id":"b12-3","bab":"الجزء 2","sec":"ابن ميادة يتعرض للمهاجاة","page":"ج2 ص258","text":"قال يحيى بن علي في خبره عن حماد أبيه عن أبي داود الفزاري إن ابن ميادة قال يفخر بنسب أبيه في العرب ونسب أمه في العجم\n(أليس غلام بين كسرى وظالم ... بأكرم من نيطت عليه التمائم)\n(لو ان جميع الناس كانوا بتلعة ... وجئت بجدي ظالم وابن ظالم)\n(لظلت رقاب الناس خاضعة لنا ... سجودا على أقدامنا بالجماجم)\nفأخبرني هاشم بن محمد الخزاعي قال حدثنا أبو غسان دماذ عن أ بي عبيدة قال كان ابن ميادة واقفا في الموسم ينشد\n(لو ان جميع الناس كانوا بتلعة ... )\nذكر تمام البيت والذي بعده قال والفرزدق واقف عليه في جماعة وهو متلثم فلما سمع هذين البيتين أقبل عليه ثم قال أنت يابن أبرد صاحب هذه الصفة كذبت والله وكذب من سمع ذلك منك فلم يكذبك فأقبل عليه فقال فمه يا أبا فراس فقال أنا والله أولى بهما منك ثم أقبل على راويته فقال اضممهما إليك\n(لو ان جميع الناس كانوا بتلعة ... وجئت بجدي دارم وابن دارم)\n(لظلت رقاب الناس خاضعة لنا ... سجودا على أقدامنا بالجماجم)\nال فأطرق ابن ميادة فما أجابه بحرف ومضى الفرزدق فانتحلهما أخبرنا يحيى قال حدثنا حماد عن أبيه عن أبي داود قال أم بني ثوبان وهم أبرد أبو ابن ميادة والعوثبان وقريض وناعضة وكان العوثبان وقريض شاعرين أمهم جميعا سلمى بنت كعب بن زهير بن أبي سلمى ويقال إن الشعر أتى ابن ميادة عن أعمامه من قبل جدهم زهير قال اسحاق في خبره هذا وحدثني حميد بن الحارث أن عقبة بن كعب بن زهير نزل المليحة على بني سلمى بن ظالم فأكلوا له بعيرا وبلغ ابن ميادة أن عقبة قال في ذلك شعرا فقال ابن ميادة يرد عليه\n(ولقد حلفت برب مكة صادقا ... لولا قرابة نسوة بالحاجر)\n(لكسوت عقبة كسوة مشهورة ... ترد المناهل من كلام عائر)\nهي قصيدة فقال له عقبة\n(ألوما أنني أصبحت خالا ... وذكر الخال ينقص أو يزيد)\n(لقد قلدت من سلمى رجالا ... عليهم مسحة وهم العبيد)\nقال ابن ميادة\n(إن تك خالنا فقبحت خالا ... فأنت الخال تنقص لاتزيد)\n(فيوما في مزينة أنت حر ... ويوما أنت محتدك العبيد)\n(أحق الناس أن يلقى هوانا ... ويؤكل ماله العبد الطريد)\nال إسحاق فحدثني عجرمة قال كان ابن ميادة أحمر سبطا عظيم الخلق طويل اللحية وكان لباسا عطرا ما دنوت من رجل كان أطيب عرفا منه قال إسحاق وحدثني أبو داود قال سمعت شيخا عالما من غطفان يقول كان الرماح أشعر غطفان في الجاهلية والاسلام وكان خيرا لقومه من النابغة لم يمدح غير قريش وقيس وكان النابغة إنما يهذي باليمن مضللا حتى مات قال إسحاق وحدثني أبو داود أن بني ذبيان تزعم أن الرماح بن ميادة كان آخر الشعراء قال إسحاق وحدثني أبو صالح الفزاري أن القاسم بن جندب الفزاري وكان عالما قال لابن ميادة والله لو أصلحت شعرك لذكرت به فإني لأراه كثير السقط فقال له ابن ميادة يابن جندب إنما الشعر كنبل في جفيرك ترمي به الغرض فطالع وواقع وعاصد وقاصد أخبرنا أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال كان ابن ميادة حديث العهد لم يدرك زمان قتيبة بن مسلم ولا دخل فيمن عناه حين قال أشعر قيس الملقبون من بني عامر والمنسوبون إلى أمهاتهم من غطفان\nولكنه شاعر مجيد كان في أيام هشام بن عبد الملك وبقي إلى زمن المنصور أخبرنا يحيى بن علي قال كان ابن ميادة فصيحا يحتج بشعره وقد مدح بني أميه وبني هاشم مدح من بني أمية الوليد بن يزيد وعبد الواحد بن سليمان ومدح من بني هاشم المنصور وجعفر بن سليمان وأخبرني هاشم بن محمد الخزاعي قال حدثنا الرياشي عن الأصمعي قال أخبرني طماح ابن أخي الرماح بن ميادة قال قال لي عمي الرماح ما علمت أني شاعر حتى وأطأت الحطيئة فإنه قال\n(عفا مسحلان من سليمى فحامره ... تمشي به ظلمانه وجآذره)\nو الله ما سمعته ولا رويته فواطآته بطبعي فقلت\n(فذو العش والممدور أصبح قاويا ... تمشي به ظلمانه وجآذره)\nفلما أنشدتها قيل لي قد قال الحطيئة\n(تمشى به ظلمانه وجآذره ... )\nفعلمت أني شاعر حينئذ","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":2,"spl":"ابن ميادة يتعرض للمهاجاة","partialRef":{"sid":"b9-5","gi":6,"vi":0,"side":0},"partial":1},
{"id":"b12-4","bab":"الجزء 2","sec":"ابن ميادة وأم جحدر","page":"ج2 ص266","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني موسى ابن زهير بن مضرس قال كان الرماح بن أبرد المعروف بابن ميادة ينسب بأم جحدر بنت حسان المرية إحدى نساء بني جذيمة فحلف أبوها ليخرجنها إلى رجل من غير عشيرته ولا يزوجها بنجد فقدم عليه رجل من الشأم فزوجه إياها فلقي عليها ابن ميادة شدة فرأيته وما لقي عليها فأتاها نساؤها ينظرن إليها عند خروج الشامي بها قال فوالله ماذكرن منها جمالا بارعا ولا حسنا مشهورا ولكنها كانت أكسب الناس لعجب فلما خرج بها زوجها إلى بلاده اندفع ابن ميادة يقول\n(ألا ليت شعري هل إلى أم جحدر ... سبيل فأما الصبر عنها فلا صبرا)\n(إذا نزلت بصرى تراخىمزارها ... وأغلق بوابان من دونها قصرا)\n(فهل تأتيني الريح تدرج موهنا ... برياك تعروري بها جرعا عفرا)\nقال الزبير وزادني عمي مصعب فيها\n(فلو كان نذر مدينا أم جحدر ... إلي لقد أوجبت في عنقي نذرا)\n(ألا لا تلطي الستر يا أم جحدر ... كفى بذرا الأعلام من دوننا سترا)\n(لعمري لئن أمسيت يا أم جحدر ... نأيت لقد أبليت في طلب عذرا)\n(فبهرا لقومي إذ يبيعون مهجتي ... بغانية بهرا لهم بعدها بهرا)\nال الزبير بهرا هاهنا يدعو عليهم أن ينزل بهم من الأمور ما يبهرهم كما تقول جدعا وعقرا وفي أول هذه القصيدة على ما رواه يحيى بن علي عن حماد بن إسحاق عن أبيه عن حميد بن الحارث يقول\n(ألا لا تعد لي لوعة مثل لوعتي ... عليك بأدمى والهوى يرجع الذكرا)\n(عشية ألوي بالرداء على الحشا ... كأن ردائي مشعل دونه جمرا)\nال حميد بن الحارث وأم جحدر امراة من بني رحل بن ظالم بن جذيمة ابن يربوع بن غيظ بن مرة أخبرني يحيى بن علي قال حدثنا حماد بن إسحاق عن أبيه وأخبرني الحرمي ابن أبي العلاء عن الزبير عن موهوب بن رشيد عن جبر بن رباط النعامي أن أم جحدر كانت امرأة من بني مرة ثم من بني رحل وأن أباها بلغه مصير ابن ميادة إليها فحلف ليزوجنها رجلا من غير ذلك البلد فزوجها رجلا من أهل الشأم فاهتداها وخرج بها إلى الشأم فتبعها ابن ميادة حتى أدركه أهل بيته فردوه مصمتا لا يتكلم من الوجد بها فقال قصيدة أولها\n(خليلي من أبناء عذرة بلغا ... رسائل منا لا تزيدكما وقرا)\n(ألما على تيماء نسأل يهودها ... فإن لدى تيماء من ركبها خبرا)\n(وبالغمر قد جازت وجاز مطيها ... عليه فسل عن ذاك نيان فالغمرا)\n(ويا ليت شعري هل يحلن أهلها ... وأهلك روضات ببطن اللوى خضرا)\nخبرني الحرمي بن أبي العلاء قال حدثني أبو سعيد يعني عبد الله بن شبيب قال حدثني أبو العالية الحسن بن مالك وأخبرني به الأخفش عن ثعلب عن عبد الله بن شبيب عن أبي العالية الحسن بن مالك الرياحي العذري قال حدثني عمر ابن وهب العبسي قال حدثني زياد بن عثمان الغطفاني من بني عبد الله بن غطفان قال كنا بباب بعض ولاة المدينة فغرضنا من طول الثواء فإذا أعرابي يقول يا معشر العرب أما منكم رجل يأتيني أعلله إذ غرضنا من هذا المكان فأخبره عن أم جحدر وعني فجئت إليه فقلت من أنت فقال أنا الرماح بن أبرد قلت فأخبرني ببدء أمركما قال كانت أم جحدر من عشيرتبي فأعجبتني وكانت بيني وبينها خلة هم إني عتبت عليها في شيء بلغني عنها فأتيتها فقلت يا أم جحدر إن الوصل عليك مردود فقالت ما قضى الله فهو خير فلبثت على تلك\n(خليلي من أبناء عذرة بلغا ... رسائل منا لا تزيدكما وقرا)\n(ألما على تيماء نسأل يهودها ... فإن لدى تيماء من ركبها خبرا)\n(وبالغمر قد جازت وجاز مطيها ... عليه فسل عن ذاك نيان فالغمرا)\n(ويا ليت شعري هل يحلن أهلها ... وأهلك روضات ببطن اللوى خضرا)","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":3,"spl":"ابن ميادة وأم جحدر"},
{"id":"b12-5","bab":"الجزء 2","sec":"ابن ميادة وأم جحدر","page":"ج2 ص266","text":"خبرني الحرمي بن أبي العلاء قال حدثني أبو سعيد يعني عبد الله بن شبيب قال حدثني أبو العالية الحسن بن مالك وأخبرني به الأخفش عن ثعلب عن عبد الله بن شبيب عن أبي العالية الحسن بن مالك الرياحي العذري قال حدثني عمر ابن وهب العبسي قال حدثني زياد بن عثمان الغطفاني من بني عبد الله بن غطفان قال كنا بباب بعض ولاة المدينة فغرضنا من طول الثواء فإذا أعرابي يقول يا معشر العرب أما منكم رجل يأتيني أعلله إذ غرضنا من هذا المكان فأخبره عن أم جحدر وعني فجئت إليه فقلت من أنت فقال أنا الرماح بن أبرد قلت فأخبرني ببدء أمركما قال كانت أم جحدر من عشيرتي فأعجبتني وكانت بيني وبينها خلة ثم إني عتبت عليها في شيء بلغني عنها فأتيتها فقلت يا أم جحدر إن الوصل عليك مردود فقالت ما قضى الله فهو خير فلبثت على تلك\nالحال سنة وذهبت بهم نجعة فتباعدوا واشتقت إليها شوقا شديدا فقلت لامرأة أخ لي والله لئن دنت دارنا من أم جحدر لآتينها ولأطلبن إليها أن ترد الوصل بيني وبينها ولئن ردته لا نقضته أبدا ولم يكن يومان حتى رجعوا فلما أصبحت غدوت عليهم فإذا أنا ببيتين نازلين إلى سند أبرق طويل وإذا امرأتان جالستان في كساء واحد بين البيتين فجئت فسلمت فردت إحداهما ولم ترد الأخرى فقالت ما جاء بك يا رماح إلينا ما كنا حسبنا إلا أنه قد انقطع ما بيننا وبينك فقلت إني جعلت علي نذرا لئن دنت بأم جحدر دار لآتينها ولأطلبن منها أن ترد الوصل بيني وبينها ولئن هي فعلت لا نقضته أبدا وإذا التي تكلمني امرأة أخيها وإذا الساكتة أم جحدر فقالت امرأة أخيها فادخل مقدم البيت فدخلت وجاءت فدخلت من مؤخره فدنت قليلا ثم إذا هي قد برزت فساعة برزت جاء غراب فنعب على رأس الأبرق فنظرت إليه وشهقت وتغير وجهها فقلت ما شأنك قالت لا شيء قلت بالله إلا أخبرتني قالت أرى هذا الغراب يخبرني أنا لا نجتمع بعد هذا اليوم إلا ببلد غير هذا البلد فتقبضت نفسي ثم قلت جارية والله ما هي في بيت عيافة ولا قيافة فأقمت عندها\nثم تروحت إلى أهلي فمكثت عندهم يومين ثم أصبحت غاديا إليها فقالت لي امرأة أخيها ويحك يا رماح أين تذهب فقلت إليكم فقالت وما تريد قد والله زوجت أم جحدر البارحة فقلت بمن ويحك قالت برجل من أهل الشأم من أهل بيتها جاءهم من الشأم فخطبها فزوجها وقد حملت إليه فمضيت إليهم فإذا هو قد ضرب سرادقات فجلست إليه فأنشدته وحدثته وعدت إليه أياما ثم إنه احتملها فذهب بها فقلت\n(أجارتنا إن الخطوب تنوب ... علينا وبعض الآمنين تصيب)\n(أجارتنا لست الغداة ببارح ... ولكن مقيم ما أقام عسيب)\n(فإن تسأليني هل صبرت فإنني ... صبور على ريب الزمان صليب)\nال علي بن الحسين هذه الأبيات الثلاثة أغار عليها ابن ميادة فأخذها بأعيانها أما البيتان الأولان فهما لامرىء القيس قالهما لما احتضر بأنقرة في بيت واحد هو\n(أجارتنا إن الخطوب تنوب ... وإني مقيم ما أقام عسيب)\nوالبيت الثالث لشاعر من شعراء الجاهلية وتمثل به أمير المؤمنين علي بن أبي طالب عليه السلام في رسالة كتب بها إلى أخيه عقيل بن أبي طالب فنقله ابن ميادة نقلا ونرجع إلى باقي شعر ابن ميادة\n(جرى بانبتات الحبل من أم جحدر ... ظباء وطير بالفراق نعوب)\n(نظرت فلم أعتف وعافت فبينت ... لها الطير قبلي واللبيب لبيب)\n(فقالت حرام أن نرى بعد هذه ... جميعين إلا أن يلم غريب)\n(أجارتنا صبرا فيا رب هالك ... تقطع من وجد عليه قلوب)\nال ثم انحدرت في طلبها وطمعت في كلمتها إلا أن نجتمع في بلد غير هذا البلد قال فجئت فدرت الشأم زمانا فتلقاني زوجها فقال م لك لا تغسل ثيابك هذه أرسل بها إلى الدار تغسل فأرسلت بها ثم إني وقفت أنتظر خروج الجارية بالثياب فقالت أم جحدر لجاريتها إذا جاء فأعلميني فلما جئت إذا أم جحدر وراء الباب فقالت ويحك يا رماح قد كنت أحسب أن لك عقلا أما ترى أمرا قد حيل دونه وطابت أنفسنا عنه انصرف إلى عشيرتك فإني أستحيي لك من هذا المقام فانصرفت وأنا أقول صوت\n(عسى إن حججنا أن نرى أم جحدر ... ويجمعنا من نخلتين طريق)\n(وتصطك أعضاد المطي وبيننا ... حديث مسر دون كل رفيق)","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":4,"spl":"ابن ميادة وأم جحدر"},
{"id":"b12-6","bab":"الجزء 2","sec":"شعر ابن ميادة في أم جحدر","page":"ج2 ص271","text":"في هذين البيتين لحن من الثقيل الثاني ذكر الهشامي أنه للحجبي وقال حين خرج إلى الشأم هذه رواية ابن شبيب\n(ألا حييا رسما بذي العش مقفرا ... وربعا بذي الممدور مستعجما قفرا)\n(فأعجب دار دارها غير أنني ... إذا مما ما أتيت الدار ترجعني صفرا)\n(عشية أثني بالرداء على الحشى ... كأن الحشى من دونه أسعرت جمرا)\n(يميل بنا شحط النوى ثم نلتقي ... عداد الثريا صادفت ليلة بدرا)\n(وبالغمر قد جازت وجاز مطيها ... فأسقى الغوادي بطن نيان فالغمرا)\n(خليلي من غيظ بن مرة بلغا ... رسائل مني لا تزيدكما وقرا)\n(ألا ليت شعري هل إلى أم جحدر ... سبيل فأما الصبر عنها فلا صبرا)\n(فإن يك نذر راجعا أم جحدر ... علي لقد أوذمت في عنقي نذرا)\n(وإني لاستنشي الحديث من اجلها ... لأسمع منها وهي نازحة ذكرا)\n(وأني لأستحيي من الله أن أرى ... إذا غدر الخلان أنوي لها غدرا)\nأخبرني محمد بن مزيد قال حدثنا حماد عن أبيه قال أنشدني أبو داود لابن ميادة وهو يضحك منذ أنشدني إلى أن سكت\n(ألم تر أن الصاردية جاورت ... ليالي بالممدور غير كثير)\n(ثلاثا فلما أن أصابت فؤاده ... بسهمين من كحل دعت بهجير)\n(بأصهب يرمي للزمام برأسه ... كأن على ذفراه نضخ عبير)\n(جلت إذ جلت عن أهل نجد حميدة ... جلاء غني لا جلاء فقير)\n(وقالت وما زادت على أن تبسمت ... عذيرك من ذي شيبة وعذيري)\n(عدمت الهوى ما يبرح الدهر مقصدا ... لقلبي بسهم في اليدين طرير)\n(وقد كان قلبي مات للوجد موتة ... فقد هم قلبي بعدها بنشور)\nقال فقلت ما أضحكك فقال كذب ابن ميادة والله ما جلت إلا على حمار وهو يذكر بعيرا ويصفه وأنها جلت جلاء غني لا جلاء فقير فأنطقه الشيطان بهذا كله كما سمعت أخبرني الحرمي قال حدثنا الزبير بن بكار قال حدثني موسى بن زهير قال مكثت أم جحدر عند زوجها زمانا ثم مات زوجها عنها ومات ولدها منه فقدمت نجدا على إخوتها وقد مات أبوها\nأخبرني سيار بن نجيح المزني قال لقيت ابن ميادة وهو يبكي فقلت له ويحك مالك قال أخرجتني أم جحدر وآلت يمينا ألا تكلمني فانطلق فاشفع لي عندها فخرجت حتى غشيت رواق بيتها فوجدتها وهي تدمك جريرا لها بين الصلاية والمدق تريد أن تخطم به بعيرا تحج عليه فقالت إن كنت جئت شفيعا لابن ميادة فبيتي حرام عليك أن تلقي فيه قدمك قال فحجت ولا والله ما كلمته ولا رآها ولا رأته قال موسى قال سيار فقلت له اذكر لي يوما رأيته منها فقال لي أما والله لأخبرنك يا سيار بذلك بعثت إليها عجوزا منهم فقلت هل ترين من رجال فقالت لا والله ما رأيت من رجل فألقيت رحلي على ناقتي ثم أرسلتها حتى أنختها بين أطناب بيتهم ثم جعلت أقيد الناقة فما كان إلا ذاك حتى دخلت وقد ألقت لي فراشا مرقوما مطموما وطرحت لي وسادتين على عجز الفراش وأخريين على مقدمه قال ثم تحدثنا ساعة وكأنما تلعقني بحديثها الرب من حلاوته ثم إذا هي تصب في عس مخضوب بالحناء والزعفران من ألبان اللقاح فأخذت منها ذلك العس وكأنه قناة فراوحته بين يدي ما ألقمته فمي ولا دريت أنه معي حتى قالت لي عجوز ألا تصلي يابن مياد لا صلى الله عليك فقد أظلك صدر النهار ولا أحسب إلا أنني في أول البكرة قال فكان ذلك اليوم آخر يوم كلمتها فيه حتى زوجها أبوها وهو أظرف ما كان بيني وبينها أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني حكم بن\nطلحة الفزاري ثم المنظوري قال قال ابن ميادة أني لأعلم أقصر يوم مر بي من الدهر قيل له وأي يوم هو يا أبا الشرحبيل قال يوم جئت فيه أم جحدر باكرا فجلست بفناء بيتها فدعت لي بعس من لبن فأتيت به وهي تحدثني فوضعته علي يدي وكرهت أن أقطع حديثها أن شربت فما زال القدح على راحتي وأنا أنظر إليها حتى فاتتني صلاة الظهر وما شربت قال الزبير وحدثني أبو مسلمة موهوب بن رشيد بمثل هذا وزاد في خبره وقال ابن ميادة فيها أيضا\n(ألم تر أن الصاردية جاورت ... ليالي بالممدور غير كثير)\n(ثلاثا فلما أن أصابت فؤاده ... بسهمين من كحل دعت بهجير)\n(بأحمر ذيال العسيب مفرج ... كأن على ذفراه نضخ عبير)\n(حلفت برب الراقصات إلى منى ... زفيف القطا يقطعن بطن هبير)\n(لقد كاد حب الصاردية بعدما ... علا في سواد الرأس نبذ قتير)\n(يكون سفاها أو يكون ضمانة ... على ما مضى من نعمة وعصور)\n(عدمت الهوى لا يبرح الدهر مقصدا ... لقلبي بسهم في الفؤاد طرير)","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":5,"spl":"شعر ابن ميادة في أم جحدر"},
{"id":"b12-7","bab":"الجزء 2","sec":"شعر ابن ميادة في أم جحدر","page":"ج2 ص271","text":"(وقد كان قلبي مات للحب موتة ... فقد هم قلبي بعدها بنشور)\n(جلت إذ جلت عن أهل نجد حميدة ... جلاء غني لا جلاء فقير)\nومما يغنى فيه من أشعار ابن ميادة في النسيب بأم جحدر قوله صوت\n(ألا يا لقومي للهوى والتذكر ... وعين قذى أنسانها أم جحدر)\n(فلم تر عيني مثل قلبي لم يطر ... ولا كضلوع فوقه لم تكسر)\nالغناء لإسحاق ثقيل أول بالوسطى أخبرنا الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثنا حكيم ابن طلحة الفزاري عن رجل من كلب قال جنيت جناية فغرمت فيها فنهضت إلى أخوالي بني مرة فاستعنتهم فأعانوني فأتيت سيار بن نجيح أحد بني سلمى بن ظالم فأعانني ثم قال انهض بنا إلى الرماح بن أبرد يعني ابن ميادة حتى يعينك فدفعنا إلى بيتين له فسألنا عنه فقيل ذهب أمس فقال سيار ذهب إلى أمة لبني سهيل فخرجنا في طلبه فوقعنا عليه في قرارة بيضاء بين حرتين وفي القرارة غنم من الضأن سود وبيض وإذا حمار مقيد مع الغنم وإذا به معها فجلسنا فإذا شابة حلوة صفراء في دراعة مورسة فسلمنا وجلسنا فقال أنشديهم مما قلت فيك شيئا فأنشدتنا\n(يمنونني منك اللقاء وإنني ... لأعلم لا ألقاك من دون قابل)\n(إلى ذاك ما حارت أمورك وانجلت ... غياية حبيك انجلاء المخايل)\n(إذا حل أهلي بالجناب وأهلها ... بحيث التقى الغلان من ذي أرائل)\n(أقل خله بانت وأدبر وصلها ... تقطع منها باقيات الحبائل)\n(وحالت شهور الصيف بيني وبينها ... ورفع الأعادي كل حق وباطل)\n(أقول لعذالي لما تقابلا ... علي بلوم مثل طعن المعابل)\n(لا تكثرا عنها السؤال فإنها ... مصلصلة من بعض تلك الصلاصل)\n(من الصفر لا ورهاء سمج دلالها ... وليست من الشود القصار الحوائل)\n(ولكنها ريحانة طال نشرها ... وردت عليها بالضحى والأصائل)\nثم قال لها قومي فاطرحي عنك دراعتك فقالت لا حتى يقول لي سيار بن نجيح ذلك فأبى سيار فقال له ابن ميادة لئن لم تفعل لا قضيت حاجتكما فقال لها فقامت فطرحتها فما رأيت أحلى منها فقال له سيار فمالك يا أبا\nالشرحبيل لا تشتريها فقال إذا يفسد حبها","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":6,"spl":"شعر ابن ميادة في أم جحدر"},
{"id":"b12-8","bab":"الجزء 2","sec":"ابن ميادة و ابن الجعد الخضري","page":"ج2 ص278","text":"أخبرني الحرمي قال حدثنا الزبير قال حدثتني مغيرة بنت أبي عدي بن عبد الجبار بن منظور بن زبان بن سيار الفزارية قالت أخبرني أبي قال جمعني وابن ميادة و صخر بن الجعد الخضري مجلس فأنشدنا ابن ميادة قوله\n(يمنونني منك اللقاء وإنني ... لأعلم لا ألقاك من دون قابل)\nفأقبل عليه صخر فقال له المحب المكب يرجو الفائت و يغم الطير و أراك حسن العزاء يا أبا الشرحبيل فأعرض عنه ابن ميادة قال أبو عدي فقلت\n(صادف درء السيل سيلا يردعه ... بهضبة ترده و تدفعه)\nو يروي درء السيل سيل فقال لي يا أبا عدي والله لا أتلطخ بالخضر مرتين و قد قال أخو عذرة\n(هو العبد أقصى همه أن تسبه ... وكان سباب الحر أقصى مدى العبد)\nقال الزبير قوله يغم الطير يقول إذا رأى طيرا لم يزجرها مخافة أن يقع ما يكره قال فلم يحر إليه صخر بن الجعد جوابا يعني بقوله لا أتلطخ بالخضر مرتين مهاجاته الحكم الخضري وكانا تهاجيا زمانا ثم كف ابن ميادة وسأله الصلح فصالحه الحكم\nأخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني أبو مسلمة موهوب بن رشيد عن عبد الرحمن بن الأحول التغلبي ثم الخولاني قال كان أول ما بدأ الهجاء بين ابن ميادة وحكم بن معمر الخضري أن ابن ميادة مر بالحكم بن معمر وهو ينشد في مصلى النبي في جماعة من الناس قوله\n(لمن الديار كأنها لم تعمر ... بين الكناس وبين برق محجر)\nحتى انتهى إلى قوله\n(يا صاحبي ألم تشيما بارقا ... نضح الصراد به فهضب المنحر)\n(قد بت أرقبه وبات مصعدا ... نهض المقيد في الدهاس الموقر)\nفقال له ابن ميادة ارفع إلي رأسك أيها المنشد فرفع حكم إليه رأسه فقال له من أنت قال أنا حكم بن معمر الخضري قال فوالله ما أنت في بيت حسب ولا في أرومة شعر فقال له حكم و ماذا عبت من شعري عبت أنك أدهست وأوقرت قال له حكم ومن أنت أنا ابن ميادة قال ويحك ! فلم رغبت عن أبيك و انتسبت إلى أمك قبح الله والدين خيرهما ميادة أما و الله\nلو وجدت في أبيك خيرا ما انتسبت إلى أمك راعية الضأن وأما إدهاسي وإيقاري فإني لم آت خيبر إلا ممتارا لا متحاملا وما عدوت أن حكيت حالك وحال قومك فلو كنت سكت عن هذا لكان خيرا لك وأبقى عليك فلم يفترقا إلا عن هجاء أخبرني الحرمي قال حدثنا الزبير قال حدثنا عبد الله بن إبراهيم الجمحي قال حدثني عمر بن ضمرة الخضري قال أول ما هاج الهجاء بين ابن ميادة وبين حكم بن معمر بن قنبر بن جحاش بن سلمة بن ثعلبة بن مالك بن طريف بن محارب قال والخضر ولد مالك بن طريف سموا بذلك لأن مالكا كان شديد الأدمة وكذلك خرج ولده فسموا والخضر أن حكما نزل بسمير بن سلمة بن عوسجة بن أنس بن يزيد بن معاوية بن ساعدة بن عمرو وهو خصيلة بن مرة فأقبل ابن ميادة إلى حكم ليعرض عليه شعره وليسمع من شعره وكان حكم أسنهما فأنشدا جميعا جماعة القوم ثم قال ابن ميادة والله لقد أعجبني بيتان قلتهما يا حكم قال أو ما أعجبك من شعري إلا بيتان فقال والله لقد أعجباني يردد ذلك مرارا لا يزيده عليه فقال له حكم فأي بيتين هما قال حين تساهم بين ثوبيها وتقول\n(فوالله ما أدري أزيدت ملاحة ... وحسنا على النسوان أم ليس لي عقل)\n(تساهم ثوباها ففي الدرع غادة ... وفي المرط لفاوان ردفهما عبل)\nفقال له حكم أو ما أعجبك غير هذين البيتين فقال له ابن ميادة قد أعجباني فقال أو ما في شعري ما أعجبك غيرهما فقال لقد أعجباني فقال له حكم فإني سوف أعيب عليك قولك\n(ولا برح الممدور ريان مخصبا ... وجيد أعالي شعبه وأسافله)\nاستسقيت لأعلاه وأسفله وتركت وسطه وهو خير موضع فيه فقال وأي شئ تريد تركته لا يزال ريان مخصبا وتهاترا فغضب حكم فارتحل ناقته وهدر ثم قال\n(فإنه يوم قريض ورجز ... )\nقال رجل من بني مرة لابن ميادة اهدركما هدر يا رماح فقال إنما يغط البكر ثم قال الرماح\n(فإنه يوم قريض ورجز ... من كان منكم ناكزا فقد نكز)\n(وبين الطرف النجيب فبرز ... )\nال يريد بقوله ناكزا غائضا قد نزف ل الزبير وسمعت رجلا من أهل البادية ينزع على إبل له كثيرة من قليب ويرتجز\n(قد نكزت أن لم تكن خسيفا ... أو يكن البحر لها حليفا)","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":7,"spl":"ابن ميادة و ابن الجعد الخضري","partial":1},
{"id":"b12-9","bab":"الجزء 2","sec":"أم جحدر تفضل ابن ميادة على الحكم وعملس","page":"ج2 ص281","text":"قال الزبير قال الجمحي قال عمير بن ضمرة فهذه أول ما هاج التهاجي\nبينهما قال الزبير قال الجمحي وحدثني عبد الرحمن بن ضبعان المحاربي قال كان ابن ميادة وحكم الخضري وعملس بن عقيل بن علفة متجاورين متحالين وكانوا جميعا يتحدثون إلى أم جحدر بنت حسان المرية وكانت أمها مولاة ففضلت ابن ميادة على الحكم وعملس فغضبا وكان ابن ميادة قال في أم جحدر\n(ألا ليت شعري هل إلى أم جحدر ... سبيل فإما الصبر عنها فلا صبرا)\n(وياليت شعري هل يحلن أهلها ... وأهلك روضات ببطن اللوى خضرا)\nوقال فيها أيضا\n(إذا ركدت شمس النهار ووضعت ... طنافسها ولينها الأعين الخزرا)\nالأبيات فقال عملس بن عقيل وحكم الخضري يهجوانها وهي تنسب إلى حكم\n(لا عوفيت في قبرها أم جحدر ... ولا لقيت إلا الكلاليب والجمرا)\n(كما حادثت عبدا لئيما وخلته ... من الزاد إلا حشو ريطاته صفرا)\n(فياليت شعري هل رأت أم جحدر ... أكشك أو ذاقت مغابنك القشرا)\n(وهل أبصرت أرساغ أبرد أورأت ... قفا أم رماح إذا ما استقت دفرا)\n(وبالغمر قد صرت لقاحا وحادثت ... عبيدا فسل عن ذاك نيان بالغمرا)\nوقال عملس بن عقيل بن علفة ويقال بل قالها علفة بن عقيل\n(فلا تضعا عنها الطنافس إنما ... يقصر بالمرماة من لم يكن صقرا)\nزاد يحيى بن علي مع هذا البيت عن حماد عن أبيه عن جرير بن رباط وأبي داود قال يعرض بقوله من لم يكن صقرا بابن ميادة أي إنه هجين ليس من أبوين متشابهين كما الصقر وبعده بيت آخر من رواية يحيى ولم يروه الزبير معه\n(منعمة لم تلق بؤسا وشقوة ... بنجد ولم يكشف هجين لها سترا)\nقالوا جميعا فقال ابن ميادة يهجو علفة\n(أعلف إن الصقر ليس بمدلج ... ولكنه بالليل متخذ وكرا)\n(ومفترش بين الجناحين سلحه ... إذا الليل ألقى فوق خرطومه كسرا)\n(فإن يك صقرا بعد ليلة أمه ... وليلة جحاف فأف له صقرا)\n(تشد بكفيها على جذل أيره ... إذا هي خافت من مطيتها نفرا)\nيريد أن أم علفة من بني أنمار وكان أبوه عقيل بن علفة ضربها فأرسلت إلى رجل من بني أنمار يقال له جحاف فأتاها ليلا فاحتملها على جمل فذهب بها وقال يحيى بن علي خاصة في خبره عن حماد عن أبيه عن أبي داود إن جحاف بن إياد كان رجلا من بني قتال بن يربوع بن غيظ بن مرة وكان يتحدث إلى امرأة عقيل ابن علفة وهي أم ابنه علفة بن عقيل ويتهم بها وهي امرأة من بني أنمار بن بغيض بن ريث بن غطفان يقال لها سلافة وكانت أحسن الناس وجها وكان\nعقيل من أغير الناس فربطها بين أربعة أوتاد ودهنها بإهالة وجعلها في قرية نمل فمر بها جحاف بن إياد ليلا فسمع أنينها فأتاها فاحتملها حتى طرحها بفدك فاستعدت واليها على عقيل وقام عقيل من جوف الليل فأوقد عشوة ونظرها فلم يجدها ووجد أثرجحاف فعرفه وتبعه حتى صبح القرية وخنس جحاف عنها فأتى الوالي فقال إن هذه رأتني قد كبرت سني وذهب بصري فاجترأت علي وكان عقيل رجلا مهيبا فلم يعاقبه الوالي بما صنعه لموضعه من صهر بني مروان قال فعير ابن ميادة علفة بن عقيل بأمر جحاف هذا في قوله\n(فإن يك صقرا بعد ليلة أمه ... وليلة جحاف فأف له صقرا)\nقال ولج الهجاء بينهما وقال فيه ابن ميادة وفي حكم الخضري وقد عاون علفة\n(لقد ركب الخضري مني وتربه ... على مركب من نابيات المراكب)\nوقال لعلفة\n(يابن عقيل لا تكن كذوبا ... أأن شربت الحزر والحليبا)\n(من شول زيد وشممت الطيبا ... جهلا تجنيت لي الذنوبا)\nقال ثم لم يلبثه ابن ميادة أن غلبه وهاج التهاجي بينه وبين حكم الخضري وانقطع عنه علفة مفضوحا قال وماتت أم جحدر التي كان ينسب بها ابن ميادة\nعلى تفيئة ما كان بينه وبين علفة من المهاجاة ونعيت له فلم يصدق حتى أتاه رجل من بني رحل يقال له عمار فنعاها له فقال\n(ما كنت أحسب أن القوم قد صدقوا ... حتى نعاها لي الرحلي عمار)\nوقال يرثيها\n(خلت شعب الممدور لست بواجد ... به غير بال من عضاه وحرمل)\n(تمنيت أن تلقى به أم جحدر ... وماذا تمنى من صدى تحت جندل)\n(فللموت خير من حياة ذميمة ... وللبخل خير من عناء مطول)","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":8,"spl":"أم جحدر تفضل ابن ميادة على الحكم وعملس"},
{"id":"b12-10","bab":"الجزء 2","sec":"أم جحدر تفضل ابن ميادة على الحكم وعملس","page":"ج2 ص281","text":"خبرني الحرمي قال حدثنا الزبير قال حدثني عبد الله بن إبراهيم عن ساعدة ابن مرمىء وذكره إسحاق أيضا عن أصحابه أن ابن ميادة وحكما الخضري تواعدا المدينة ليتواقفا بها فتواقفا بها وجاء نفر من قريش أمهاتهم من مرة إلى ابن ميادة فمنعوه من مواقفة حكم وقالوا أتتعرض له ولست بكفئه فيشتم أمهاتنا وأخوالنا وخالاتنا وهو رجل خبيث اللسان قال وكان حكم يسجع سجعا كثيرا فقال والله لئن واقفته لأسجعن به قبل المقارضة سجعا أفضحه به فلم يلقه وذكر الزبير له سجعا طويلا غثا لا فائدة فيه لأنه ليس برجز منظوم ولا كلام فصيح ولا مسجع سجعا مؤتلفا كائتلاف القوافي إلا أن من أسلمه قوله والله لئن ساجعتني سجاعا لتجدني شجاعا للجار مناعا ولأجدنك هياعا للحسب مضياعا ولئن باطشتك بطاشا لأدهشنك إدهاشا ولأذقن منك مشاشا حتى يجيء بولك رشاشا وهذا من غث السجع ورذله وإنما ذكرته ليستدل به على ما هو دونه مما ألغيت ذكره قال\nورجز به فقال\n(يا معدن اللؤم وأنت جبله ... وآخر اللؤم وأنت أوله)\n(جاريت سباقا بعيدا مهله ... كان إذا جارى أباك يفشله)\n(فكيف ترجوه وكيف تأمله ... وأنت شر رجل وأنذله)\n(ألأ مه في مأزق وأجهله ... أدخله بيت المخازي مدخله)\n(فاللؤم سربال له يسربله ... ثوبا إذا أنهجه يبدله)\nفأجابه حكم\n(يا بن التي جيرانها كانت تضر ... وتتبع الشول وكانت تمتصر)\n(كيف إذا مارست حرا تنتصر ... )\nولهما أراجيز كثيرة طويلة جدا أسقطتها لكثرتها وقلة فائدتها أخبرني الحرمي قال حدثنا الزبير عن عبد الله بن إبراهيم قال أخبرني بعض من لقيت من الخضر أن حكما الخضري خرج يريد لقاء ابن ميادة بالرقم من غير موعد فلم يلقه إما لأنه تغيب عنه وإما لأنه لم يصادفه فقال حكم\n(فر ابن ميادة الرقطاء من حكم ... بالصغر مثل فرار الأعقد الدهم)\n(أصبحت في أقر تعلو أطاوله ... تفر مني وقد أصبحت بالرقم)\nوقال إسحاق في روايته عن أصحابه قال ابن ميادة يهجو حكما وينسب بأم جحدر\n(يمنونني منك اللقاء وإنني ... لأعلم لا ألقاك من دون قابل)\nقد مضى أكثر هذه الأبيات متقدما فذكرت هاهنا منها ما لم يمض وهو قوله\n(فياليت رث الوصل من أم جحدر ... لنا بجديد من أولاك البدائل)\n(ولم يبق مما كان بيني وبينها ... من الود إلا مخفيات الرسائل)\n(وإني إذا استنبهت من حلو رقدة ... رميت بحبيها كرمي المناضل)\nصوت فما انس م الأشياء لا أنس قولها ... وأدمعها يذرين حشو المكاحل تمتع بذا اليوم القصير فإنه ... رهين بأيام الدهور الأطاول\nالغناء في هذين البيتين لعلي بن يحيى المنجم ولحنه من الثقيل الثاني\n(وكنت امرأ أرمي الزوائل مرة ... فأصبحت قد ودعت رمي الزوائل)\n(وعطلت قوس اللهو من سرعانها ... وعادت سهامي بين رث وناصل)\nالسرعان وتر يعمل من عقب المتن وهو أطول العقب\n(إذا حل بيتي بين بدر ومازن ... ومرة نلت الشمس واشتد كاهلي)\nيعني بدر بن عمرو بن جؤية بن لوذان بن ثعلبة بن عدي بن فزارة بن ذبيان ومرة ابن عوف بن سعد بن ذبيان ومرة بن فزارة ومازن بن فزارة\n(وهي طويلة ... )\nقال أبو الفرج الأصبهاني أخذ إسحاق الموصلي معنى بيت ابن ميادة في قوله\n(نلت الشمس واشتد كاهلي ... )\nفقال\n(عطست بأنف شامخ وتناولت ... يداي الثريا قاعدا غير قائم)\nلعمري لئن كان استعار معناه لقد اضطلع به وزاد فاحسن وأجاد وفي هذه القصيدة يقول\n(فضلنا قريشا غير رهط محمد ... وغير بني مروان أهل الفضائل)\nال يحيى بن علي وأخبرني علي بن سليمان بن أيوب عن مصعب وأخبرني به الحسن بن علي عن أحمد بن زهير عن مصعب قال قال إبراهيم بن هشام بن إسماعيل لابن ميادة أنت فضلت قريشا وجرده فضربه أسواطا أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال لما قال ابن ميادة\n(فضلنا قريشا غير رهط محمد ... وغير بني مروان أهل الفضائل)\nقال له الوليد بن يزيد قدمت آل محمد قبلنا فقال ما كنت يا أمير المؤمنين أظنه يمكن غير ذلك قال فلما أفضت الخلافة إلى بني هاشم وفد ابن ميادة إلى المنصور ومدحه فقال له أبو جعفر لما دخل إليه كيف قال لك الوليد فأخبره بما قال فجعل المنصور يتعجب","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":9,"spl":"أم جحدر تفضل ابن ميادة على الحكم وعملس","partial":1},
{"id":"b12-11","bab":"الجزء 2","sec":"ابن ميادة والحكم الخضري بعريجاء","page":"ج2 ص289","text":"أخبرني الحرمي قال حدثنا الزبير قال حدثني عبد الله بن إبراهيم الجمحي قال حدثني العباس بن سمرة بن عباد بن شماخ بن سمرة عن ريحان بن سويد الخضري وكان راوية حكم بن معمر الخضري قال تواعد حكم وابن ميادة عريجاء وهي ماءة يتواقفان عليها فخرج كل واحد منهما في نفر من قومه وأقبل صخر بن الجعد الخضري يؤم حكما وهو يومئذ عدو لحكم لما كان فرط بينهما من الهجاء في أركوب من بني مازن بن مالك بن طريف بن خلف بن محارب فلما لقيه قال له يا حكم أهؤلاء الذين عرضت للموت وهم وجوه قومك فوالله ما دماؤهم على بني مرة إلا كدماء جدايه فعرف حكم أن قول صخر هو الحق فرد قومه وقال لصخر قد وعدني ابن ميادة أن يواقفني غدا بعريجاء لأن أناشده فقال له صخر أنا كثير الإبل وكان حكم مقلا فإذا وردت إبلي فارتجز فإن القوم لا يشجعون عليك وأنت وحدك فإن لقيت الرجل نحر وأطعم فانحر وأطعم وإن أتيت على مالي كله قال ريحان راويته فورد يومئذ عريجاء وأنا معه فظل على عريجاء ولم يلق رماحا ولم\nيواف لموعده وظل ينشد يومئذ حتى أمسى ثم صرف وجوه إبل صخر وردها وبلغ الخبر ابن ميادة وموافاة حكم لموعده فأصبح على الماء وهو يرتجز يقول\n(أنا ابن ميادة عقار الجرز ... كل صفي ذات ناب منفطر)\nوظل على الماء فنحر وأطعم فلما بلغ حكا ما صنع ابن ميادة من نحره وإطعامه شق عليه مشقة شديدة ثم إنهما بعد توافيا بحمى ضرية قال ريحان بن سويد وكان ذلك العام عام جدب وسنة إلا بقية كلأ بضرية قال فسبقنا ابن ميادة يومئذ فنزلنا عى مولاة لعكاشة بن مصعب بن الزبير ذات مال ومنزلة من السلطان قال وكان حكم كريما على الولاة هناك يتقى لسانه قال ريحان فبينا نحن عند المولاة وقد حططنا براذع دوابنا إذا ركبان قد أقبلا وإذا نحن برماح وأخيه ثوبان ولم يكن لثوبان ضريب في الشجاعة والجمال فأقبلا يتسايران فلما رآهما حكم عرفهما فقال يا ريحان هذان ابنا أبرد فما رأيك أتكفيني ثوبان أم لا قال فأقبلا نحونا ورماح يتضاحك حتى قبض على يد حكم وقال مرحبا برجل سكت عنه ولم يسكت عني وأصبحت الغداة أطلب سلمه يسوقني الذئب والسنة وأرجو أن أرعى الحمى بجاهه وبركته ثم جلس إلى جنب حكم وجاء ثوبان فقعد إلى جنبي فقال له حكم أما ورب المرسلين يا رماح لولا أبيات جعلت\nتعتصم بهن وترجع إليهن يعني أبيات ابن ظالم لاستوسقت كما استوسق من كان قبلك قال ريحان وأخذا في حديث أسمع بعضه ويخفى علي بعضه فظللنا عند المرأة وذبح لنا وهما في ذلك يتحادثان مقبل كل واحد منهما على صاحبه لا ينظران شدنا حتى كان العشاء فشددنا للرواح نؤم أهلنا فقال رماح لحكم يا أبا منيع وكانت كنية حكم قد قضيت حاجتك وحاجة من طلبت له من هذا العامل وإن لنا إليه حاجة في أن يرعينا فقال له حكم قد والله قضيت حاجتي منه وإني لأكره الرجوع إليه وما من حاجتك بد ثم رجع معه إلى العامل فقال له بعد الحديث معه إن هذا الرجل من قد عرفت ما بيني وبينه وقد سأل الصلح وأناب إليه فأحببت أن يكون ذلك على يدك وبمحضرك قال فدعا به عامل ضرية ول هل لك حاجة غير ذلك قال لا والله ونسي حاجة رماح فأذكرته إياها فرجع فطلبها واعتذر بالنسيان ف العامل لابن ميادة ما حاجتك فقال ترعيني عريجاء لا يعرض لي فيها أحد فأرعاه إياها فأقبل رماح على حكم فقال جزاك الله خيرا يا أبا منيع فوالله لقد كان ورائي من قومي من يتمنى أن يرعى عريجاء بنصف ماله قال فلما عزما على الانصراف ودع كل واحد منهما صاحبه وانصرفا راضيين وانصرف ابن ميادة إلى قومه فوجد بعضهم قد ركب إلى ابن هشام فاستغضبه على حكم في قوله\n(وما ولدت مرية ذات ليلة ... من الدهر إلا زاد لؤما جنينها)\nفأطرده وأقسم لئن ظفر به ليسرجنه وليحملن عليه أحدهم فقال رماح وساءه ما صنعوا عمدتم إلى رجل قد صلح ما بيني وبينه وأرعيت بوجهه فاستعديتم عليه وجئتم بإطراده وبلغ الحكم الخبر فطار إلى الشأم فلم يبرحها حتى مات\nقال العباس بن سمرة مات بالشأم غرقا وكان لا يحسن العوم فمات في بعض أنهارها قال وهو وجهه الذي مدح فيه أسود بن بلال المحاربي ثم السوائي في قصيدته التي يقول فيها\n(واستيقنت أن لا براح من السرى ... حتى تناخ بأسود بن بلال)\n(قرم إذا نزل الوفود ببابه ... سمت العيون إلى أشم طوال)","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":10,"spl":"ابن ميادة والحكم الخضري بعريجاء"},
{"id":"b12-12","bab":"الجزء 2","sec":"مناقضات حكم وابن ميادة","page":"ج2 ص292","text":"ولحكم الخضري وابن ميادة مناقضات كثيرة وأراجيز طوال طويت ذكر أكثرها وألغيته وذكرت منها لمعا من جيد ما قالاه لئلا يخلو هذا الكتاب من ذكر بعض ما دار بينهما ولا يستوعب سائره فيطول فمما قاله حكم في ابن ميادة قوله\n(خليلي عوجا حييا الدار بالجفر ... وقولا لها سقيا لعصرك من عصر)\n(وماذا تحيي من رسوم تلاعبت ... بها حرجف تذري بأذيالها الكدر)\nومن جيد قوله فيها يفتخر\n(إذا يبست عيدان قوم وجدتنا ... وعيداننا تغشى على الورق الخضر)\n(إذا الناس جاؤوا بالقروم أتيتهم ... بقرم يساوي رأسه غرة البدر)\n(لنا الغور والأنجاد والخيل والقنا ... عليكم وأيام المكارم والفخر)\nومن جيد هجائه قوله\n(فيا مر قد أخزاك في كل موطن ... من اللؤم خلات يزدن على العشر)\n(فمنهن أن العبد حامي ذماركم ... وبئس المحامي العبد عن حوزة الثغر)\n(ومنهن أن لم تمسحوا وجه سابق ... جواد ولم تأتوا حصانا على طهر)\n(ومنهن أن الميت يدفن منكم ... فيفسو على دفانه وهو في القبر)\n(ومنهن أن الجار يسكن وسطكم ... بريئا فيلقى بالخيانة والغدر)\n(ومنهن أن عذتم بأرقط كودن ... وبئس المحامي أنت يا ضرطة الجفر)\n(ومنهن أن الشيخ يوجد منكم ... يدب إلى الحارات محدودب الظهر)\n(تبيت ضباب الضغن تخشى احتراشها ... وإن هي أمست دونها ساحل البحر)\nأجابه ابن ميادة بقصيدة طويلة منها قوله مجيبا له عن هذه الخصال التي سبهم بها\n(لقد سبقت بالمخزيات محارب ... وفازت بخلات على قومها عشر)\n(فمنهن أن لم تعقروا ذات ذروة ... لحق إذا ما احتيج يوما إلى العقر)\n(ومنهن أن لم تمسحوا عربية ... من الخيل يوما تحت جل على مهر)\n(ومنهن أن لم تضربوا بسيوفكم ... جماجم إلا فيشل القرح الحمر)\n(ومنهن أن كانت شيوخ محارب ... كما قد علمتم لا تريش ولا تبري)\n(ومنهن أخزى سوءة لو ذكرتها ... لكنتم عبيدا تخدمون بني وبر)\n(ومنهن أن الضأن كانت نساءكم ... إذا اخضر أطراف الثمام من القطر)\n(ومنهن أن كانت عجوز محارب ... تريغ الصبا تحت الصفيح من القبر)\n(ومنهن أن لو كان في البحر بعضكم ... لخبث ضاحي جلده حومة البحر)\nومما قاله ابن ميادة في حكم قوله من قصيدة أولها\n(ألا حييا الأطلال طالت سنينها ... بحيث التقت ربد الجناب وعينها)\nويقول فيها\n(فلما أتاني ما تقول محارب ... تغنت شياطيني وجن جنونها)\n(ألم تر أن الله غشى محاربا ... إذا اجتمع الأقوام لونا يشينها)\n(ترى بوجوه الخضر خضر محارب ... طوابع لؤم ليس ينفت طينها)\n(لقد ساهمتناكم سليم وعامر ... فضمناهم إنا كذاك ندينها)\n(فصارت لنا أهل الضئين محارب ... وصارت لهم جسر وذاك ثمينها)\n(إذا أخذت خضرية قائم الرحى ... تحرك قنباها فطار طحينها)\n(وما حملت خضرية ذات ليلة ... من الدهر إلا ازداد لؤما جنينها)\nقال حكم يجيبه عن هذه بقصيدته\n(لأنت ابن أشبانية أدلجت به ... إلى اللؤم مقلات لئيم جنينها)\n(فجاءت برواث كأن جبينه ... إذا ما صغا في خرقتيها جبينها)\n(فما حملت مرية قط ليلة ... من الدهر إلا ازداد لؤما جنينها)\n(وما حملت إلا لألأم من مشى ... ولا ذكرت إلا بأمر يشينها)\n(تزوج عثوان الضئين وتبتغي ... بها الدر لا درت بخير لبونها)\n(أظنت بنو عثوان أن لست شاتما ... بشتمي وبعض القوم حمقى ظنونها)\n(مدانيس أبرام كأن لحاهم ... لحى مستهبات طوال قرونها)\nال الزبير فحدثني موهوب بن رشيد قال فسمع هذه القصيدة أحد بني قتال بن مرة فقال ماله أخزاه الله يهجو صبيتنا قال وهم أجفى قوم غضبا لصبيتهم وقد هجاهم بما هجاهم به قال وبلغ إبراهيم بن هشام قوله في نساء بني مرة إذ يقول\n(وما حملت إلا لألأم من مشى ... )\nغضب ثم نذر دمه فهرب من الحجاز إلى الشأم فمات بها\nأخبرني الحرمي بن ابي العلاء قال حدثنا الزبير قال حدثني عبد الرحمن بن ضبعان الخضري قال لقي ابن ميادة صخر بن الجعد الخضري فقال له يا صخر أعنت علي ابن عمك الحكم بن معمر فقال له صخر لا والله يا أبا الشرحبيل ما أعنته عليك ولكن خيل إليك ما كان يخيل إلي ولقد هاجيته فكنت أظن أن شجر الوادي يعينه علي ومن جيد قول ابن ميادة في حكم قصيدته التي أولها صوت\n(لقد سبقتك اليوم عيناك سبقة ... وأبكاك من عهد الشباب ملاعبه)\n(فوالله ما أدري أيغلبني الهوى ... إذا جد جد البين أم أنا غالبه)\n(فإن أستطع أغلب وإن يغلب الهوى ... فمثل الذي لاقيت يغلب صاحبه)","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":11,"spl":"مناقضات حكم وابن ميادة","partial":1},
{"id":"b12-13","bab":"الجزء 2","sec":"مناقضات حكم وابن ميادة","page":"ج2 ص292","text":"في هذه الأبيات غناء ينسب يقول فيها في هجاء حكم\n(لقد طال حبس الوفد وفد محارب ... عن المجدلم يأذن لهم بعد حاجبه)\n(وقال لهم كروا فلست بآذن ... لكم أبدا أو يحصي الترب حاسبه)\nهي قصيدة طويلة","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":12,"spl":"مناقضات حكم وابن ميادة — منزلة ابن ميادة عند الوليد"},
{"id":"b12-14","bab":"الجزء 2","sec":"منزلة ابن ميادة عند الوليد","page":"ج2 ص296","text":"أخبرني الحرمي قال حدثنا الزبير قال حدثني جلال بن عبد العزيز المري ثم الصاردي عن أبيه قال جلال وقد رأيت ابن ميادة في بيت أبي قال قال لي ابن ميادة وصلت أنا والشعراء إلى الوليد بن يزيد وهو خليفة وكان مولى من موالي خرشة\nيقال له شقران يعيب ابن ميادة ويحسده على مكانه من الوليد فلما اجتمعت الشعراء قال الوليد بن يزيد لشقران يا شقران ما علمك في ابن ميادة قال علمي فيه يا أمير المؤمنين أنه\n(لئيم يباري فيه أبرد نهبلا ... لئيم أتاه اللؤم من كل جانب)\nقال الوليد يا ابن ميادة ما علمك في شقران قال علمي يا أمير المؤمنين أنه عبد لعجوز من خرشة كاتبته على أربعين درهما ووعدها أو قال وعدته أن تجيزه بعشرين درهما فقبضته إياها فأغنه عني يا أمير المؤمنين فليس له أصل فأحتفره ولا فرع فاهتصره فقال له الوليد اجتنبه يا شقران فقد أبلغ إليك في الشتيمة فقصر صقران صاغرا ثم أنشدته فأقيمت الشعراء جميعا غيري وأمر لي بمائة لقحة وفحلها وراعيها وجارية بكر وفرس عتيق فاختلت ذلك اليوم وقلت\n(أعطيتني مائة صفرا مدامعها ... كالنخل زين أعلى نبته الشرب)\nيروى\n(كأنها النخل روى نبتها الشرب ... )\n(يسوقها يافع جعد مفارقه ... مثل الغراب غذاه الصر والحلب)\n(وذا سبيب صهيبيا له عرف ... وهامة ذات فرق نابها صخب)\nم يذكر الزبير في خبره غير هذه الأبيات الثلاثة وهي من قصيدة للرماح طويلة يمدح فيها الوليد بن يزيد وقد أجاد فيها وأحسن وذكرت من مختارها هاهنا طرفا وأولها\n(هل تعرف الدار بالعلياء غيرها ... سافي الرياح ومستن له طنب)\n(دار لبيضاء مسود مسائحها ... كأنها ظبية ترعى وتنتصب)\nلمسائح ما بين الأذن إلى الحاجب من الشعر وتنتصب تقف إذا ارتاعت منتصبة تتوجس\n(تحنو لأكحل ألقته بمضيعة ... فقلبها شفقا من حوله يجب)\nيقول فيها\n(يا أطيب الناس ريقا بعد هجعتها ... وأملح الناس عينا حين تنتقب)\n(ليست تجود بنيل حين أسألها ... ولست عند خلاء اللهو أغتصب)\n(في مرفقيها إذا ما عونقت جمم ... على الضجيع وفي أنيابها شنب)\n(وليلة ذات أهوال كواكبها ... مثل القناديل فيها الزيت والعطب)\n(قد جبتها جوب ذي المقراض ممطرة ... إذا استوى مغفلات البيد والحدب)\n(بعنتريس كأن الدبر يلسعها ... إذا ترنم حاد خلفها طرب)\n(إلى الوليد أبي العباس ما عجلت ... ودونه المعط من لبنان والكثب)\nوبعد هذا البيت قوله\n(أعطيتني مائة صفرا مدامعها ... )\nالخ\n(لما أتيتك من نجد وساكنه ... نفحت لي نفحة طارت بها العرب)\n(إني امرؤ أعتفي الحاجات أطلبها ... كما اعتفى سنق يلقى له العشب)\nالسنق الذي قد شبع حتى بشم يقول أطلب الحاجة بغير حرص ولا كلب كما يعتفي هذا البعير البشم من غير شره ولا شدة طلب\n(ولا ألح على الخلان أسألهم ... كما يلح بعظم الغارب القتب)\n(ولا أخادع ندماني لأخدعه ... عن ماله حين يسترخي به اللبب)\n(وأنت وابناك لم يوجد لك مثل ... ثلاثة كلهم بالتاج معتصب)\n(الطيبون إذا طابت نفوسهم ... شوس الحواجب والأبصار إن غضبوا)\n(قسني إلى شعراء الناس كلهم ... وادع الرواة إذا ما غب ما اجتلبوا)\n(إني وإن قال أقوام مديحهم ... فأحسنوه وما حابوا وما كذبوا)\n(أجري أمامهم جري امرء فلج ... عنانه حين يجري ليس يضطرب)","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":12,"spl":"مناقضات حكم وابن ميادة — منزلة ابن ميادة عند الوليد","partial":1},
{"id":"b12-15","bab":"الجزء 2","sec":"اشتداد الهجاء بين ابن ميادة وشقران","page":"ج2 ص300","text":"أخبرني يحيى بن علي قال أخبرنا حماد بن إسحاق عن أبيه قال أخبرني أبو الحسن أظنه المدائني قال أخبرني أبو صالح الفزاري قال أقبل شقران مولى بني سلامان بن سعد هذيم أخي عذرة بن سعدا بن هذيم قال وهذيم عبد حبشي كان حضن سعدا فغلب عليه وهو ابن ليث بن سود بن أسلم بن الحاف بن قضاعة من اليمامة ومعه تمر قد امتاره فلقيه ابن ميادة فقال له ما هذا معك قال تمر امترته لأهلي يقال له زب رباح فقال له ابن ميادة يمازحه\n(كأنك لم تقفل لأهلك تمرة ... إذا أنت لم تقفل بزب رباح)\nفقال له شقران\n(فإن كان هذا زبه فانطلق به ... إلى نسوة سود الوجوه قباح)\nفغضب ابن ميادة وأمضه وأنحى عليه بالسوط فضربه ضربات وانصرف مغضبا فكان ذلك سبب الهجاء بينهما قال حماد عن أبيه وحدثني أبو علي الكلبي قال اجتمع ابن ميادة وشقران مولى بني سلامان عند الوليد بن يزيد فقال ابن ميادة يا أمير المؤمنين أتجمع بيني وبين هذا العبد وليس بمثلي في حسبي ولا نسبي ولا لساني ولا منصبي فقال شقران\n(لعمري لئن كنت ابن شيخي عشيرتي ... هرقل وكسرى ما أراني مقصرا)\n(وما أتمنى أن أكون ابن نزوة ... نزاها ابن أرض لم تجد متمهرا)\n(على حائل تلوي الصرار بكفها ... فجاءت بخوار إذا عض جرجرا)\nخبرني الحرمي قال حدثنا الزبير بن بكار وأخبرنا يحيى بن علي عن أبي أيوب المديني عن زبير قال حدثني جلال بن عبد العزيز وقال يحيى بن خلاد عن أبي أيوب بن عبد العزيز قال استأذن ابن ميادة على الوليد بن يزيد وعنده شقران مولى قضاعة فأدخله في صندوق وأذن لابن ميادة فلما دخل أجلسه على الصندوق واستنشده هجاء شقران\nفجعل ينشده ثم أمر بفتح الصندوق فخرج عليه شقران وجعل يهدر كما يهدر الفحل ويقول\n(سأكعم عن قضاعة كلب قيس ... على حجر فينصت للكعام)\n(أسير أمام قيس كل يوم ... وما قيس بسائرة أمامي)\nوقال أيضا وهو يسمع\n(إني إذا الشعراء لاقى بعضهم ... بعضا ببلقعة يريد نضالها)\n(وقفوا لمرتجز الهدير إذا دنت ... منه البكارة قطعت أبوالها)\n(فتركتهم زمرا ترمز باللحى ... منها عنافق قد حلقت سبالها)\nفقال له ابن ميادة يا أمير المؤمنين اكفف عني هذا الذي ليس له أصل فأحفره ولا فرع فأهصره فقال الوليد أشهد أنك قد جرجرت كما قال شقران\n(فجاءت بخوار إذا عض جرجرا ... )\nقال يحيى في خبره واجتمع ابن ميادة وعقال بن هاشم بباب الوليد بن\nيزيد و كان عقال شديد الرأي في اليمين فغمز عقال ابن ميادة واعتلاه فقال ابن ميادة\n(فجرنا ينابيع الكلام و بحره ... فأصبح فيه ذو الروايه يسبح)\n(وما الشعر إلا شعر قيس وخندف ... وقول سواهم كلفة و تملح)\nفقال عقال يجيبه\n(ألا أبلغ الرماح نقض مقالة ... بها خطل الرماح أو كان يمزح)\n(لئن كان في قيس وخندف ألسن ... طوال وشعر سائر ليس يقدح)\n(لقد خرق الحي اليمانون قبلهم ... بحور الكلام تستقي وهي تطفح)\n(وهم علموا من بعدهم فتعلموا ... وهم اعربوا هذا الكلام وأوضحوا)\n(فللسابقين الفضل لا يجحدونه ... و ليس لمخلوق عليهم تبجح)","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":13,"spl":"اشتداد الهجاء بين ابن ميادة وشقران","partial":1},
{"id":"b12-16","bab":"الجزء 2","sec":"الحنين إلى الوطن","page":"ج2 ص303","text":"أخبرني الحرمي قال حدثنا الزبير قال حدثنا جلال بن عبد العزيز عن أبيه قال حدثني ابن ميادة قال قلت وأنا عند الوليد بن يزيد بأباين وهو موضوع كان الوليد ينزله في الربيع\n(لعمرك إني نازل بأباين ... لصوءر مشتاق وإن كنت مكرما)\n(أبيت كأني أرمد العين ساهر ... إذا بات أصحابي من الليل نوما)\nقال فقال لي الوليد يا بن ميادة كأنك غرضت من قربنا فقلت ما مثلك يا أمير المؤمنين يغرض من قربه ولكن\n(ألا ليت شعري هل أبيتن ليلة ... بحرة ليلى حيث ربتني أهلي)\n(وهل أسمعن الدهر أصوات هجمة ... تطالع من هجل خصيب إلى هجل)\n(بلاد بها نيطت علي تمائمي ... وقطعن عني حين أدركني عقلي)\n(فإن كنت عن تلك المواطن حابسي ... فأيسر علي الرزق واجمع إذا شملي)\nفقال كم الهجمة مائة ناقة فقال قد صدرت بها كلها عشراء قال ابن ميادة فذكرت ولدانا لي بنجد إذا استطعموا الله عز و جل أطعمهم و أنا و إذا استسقوه سقاهم الله وأنا وإذا استكسوه كساهم الله وأنا فقال يا بن ميادة وكم ولدانك فقلت سبعة عشر منهم عشرة نفر وسبع نسوة فذكرت ذلك منهم فأخذ بقلبي فقال يا بن ميادة قد أطعمهم الله وأمير المؤمنين وسقاهم الله وأمير المؤمنين وكساهم الله وأمير المؤمنين أما النساء فأربع حلل مختلفات الألوان\nوأما الرجال فثلاث حلل مختلفات الألوان و أما السقي فلا أرى مائة لقحة إلا سترويهم فإن لم تروهم زدتهم عينين من الحجاز قلت يا أمير المؤمنين لسنا بأصحاب عيون يأكلنا بها البعوض و تأخذنا بها الحميات قال فقد أخلفها الله عليك كل عام لك فيه مثل ما أعطيتك العام مائة لقحة و فحلها وجارية بكر وفرس عتيق وأخبرنا يحيى بن علي قال حدثنا حماد بن إسحاق عن أبيه قال حدثني شداد بن عقبة عن عبد السلام بن القتال قال عارضني ابن ميادة فقال أنشدني يابن القتال فأنشدته\n(ألا ليت شعري هل أبيتن ليلة ... بصحراء ما بين التنوفة والرمل)\n(وهل أزجرن العيس شاكية الوجى ... كما عسل السرحان بالبلد المحل)\n(وهل أسمعن الدهر صوت حمامة ... تغني حمامات على فنن جثل)\n(وهل أشربن الدهر مزن سحابة ... على ثمد الأفعاة حاضره أهلي)\n(بلاد بها نيطت علي تمائمي ... وقطعن عني حين أدركني عقلي)\nقال فأتاني الرواة بهذا البيت وقد اصطرفه ابن ميادة وحده أخبرني حبيب بن نصر المهلبي قال حدثنا عمر بن شبة قال حدثني إسحاق بن إبراهيم قال حدثني رجل من كلب وأخبرني يحيى بن علي بن يحيى عن حماد عن أبيه عن أبي علي الكلبي قال أمر الوليد بن يزيد لابن ميادة بمائة من الإبل من صدقات بني كلب فلما أتى الحول أرادوا أن يبتاعوها له من الطرائد وهي الغرائب وأن يمسكوا التلاد فقال ابن ميادة\n(ألم يبلغك أن الحي كلبا ... أرادوا في عطيتك ارتدادا)\n(وقالوا إنها صهب وورق ... وقد أعطيتها دهما جعادا)\nفعلموا أن الشعر سيبلغ الوليد فيغضبه فقالوا له انطلق فخذها صفرا جعادا","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":14,"spl":"الحنين إلى الوطن"},
{"id":"b12-17","bab":"الجزء 2","sec":"رثاء الوليد","page":"ج2 ص306","text":"وقال يحيى بن على في روايته لما قتل الوليد بن يزيد قال ابن ميادة يرثيه\n(ألا يا لهفتي على وليد ... غداة أصابه القدر المتاح)\n(ألا أبكي الوليد فتى قريش ... وأسمحها إذا عد السماح)\n(وأجبرها لذي عظم مهيض ... إذا ضنت بدرتها اللقاح)\n(لقد فعلت بنو مروان فعلا ... وأمرا ما يسوغ به القراح)\nقال يحيى وغنى فيه عمر الوادي ولم يذكر طريقة غنائه أخبرنا الحرمي قال حدثنا الزبير قال حدثنا محمد بن زهير بن مضرس الفزاري عن أبيه قال أخصب جناب الحجاز الشامي فمالت لذلك الخصب بنو فزارة وبنو مرة فتحالوا جميعا به فبينا ذات يوم أنا وابن ميادة جالسان على قارعة الطريق عشاء إذا راكبان يوجفان راحلتين حتى وقفا علينا فإذا أحدهما بحر الريح وهو عثمان بن عمرو بن عثمان بن عفان معه مولى له فنسبنا وانتسب لنا وقد كان ابن ميادة يعللني بشعره فلما انقضى كلامنا مع القرشي ومولاه استعدت ابن ميادة ما كنا فيه فأنشدني فخرا له يقول فيه\n(وعلى المليحة من جذيمة فتية ... يتمارضون تمارض الأسد)\n(وترى الملوك الغر تحت قبابهم ... يمشون في الحلقات والقد)\nقال فقال له القرشي كذبت قال ابن ميادة أفي هذا وحده أنا والله في غيره أكذب فقال له القرشي إن كنت تريد في مديحك قريشا فقد كفرت بربك ودفعت قوله ثم قرأ عليه لإ يلا ف قريش\nحتى أتى على آخرها ونهض هو ومولاه وركبا راحلتيهما فلما فاتا أبصارنا قال ابن ميادة\n(سمين قريش مانع منك نفسه ... وغث قريش حيث كان سمين)","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":15,"spl":"رثاء الوليد — رجع إلى الشعر"},
{"id":"b12-18","bab":"الجزء 2","sec":"هجاء بني حميس","page":"ج2 ص308","text":"أخبرنا يحيى بن علي عن حماد عن أبيه عن أبي الحارث المري قال\nكان ابن ميادة قد هاجى سنان بن جابر أحد بنى حميس بن عامر بن جهينة ابن زيد بن ليث بن سود بن أسلم فقال ابن ميادة له فيما قال من هجائه\n(لقد طالما عللت حجرا وأهله ... بأعراض قيس يا سنان بن جابر)\n(أأهجو قريشا ثم تكره ريبتي ... ويسرقني عرضي حميس بن عامر)\nقال وقال فيهم أيضا\n(قصار الخطى فرق الخصى زمر اللحى ... كأنهم ظربى اهترشن على لحم)\n(ذكرت حمام القيظ لما رأيتهم ... يمشون حولي في ثيابهم الدسم)\n(وتبدي الحميسيات في كل زينة ... فروجا كآثار الصغار من البهم)\nقال ثم إن ابن ميادة خرج يبغي إبلا له حتى ورد جبارا وهو ماء لحميس بن عامر فأتى بيتا فوجد فيه عجوزا قد أسنت فنشدها إبله فذكرتها له وقالت ممن أنت قال رجل من سليم بن منصور فأذنت له وقالت ادخل حتى نقريك وقد عرفته وهو لا يدري فلما قرته قال ابن ميادة وجدت ريح الطيب قد نفح علي من البيت فإذا بنت لها قد هتكت الستر ثم استقبلتني وعليها إزار أحمر وهي مؤتزرة به فأطلقته وقالت انظر يا بن ميادة الزانية أهذا كما نعت فلم أر امرأة أضخم قبلا منها فقالت أهذه كما قلت\n(وتبدي الحميسيات في كل زينة ... فروجا كآثار الصغار من البهم)\nقال قلت لا والله يا سيدتي ما هكذا قلت ولكن قلت\n(وتبدي الحميسيات في كل زينة ... فروجا كآثار المقيسرة الدهم)\nوانصرف يتشبب بها فذلك حين يقول\n(نظرنا فهاجتنا على الشوق والهوى ... لزينب نار أوقدت بجبار)\n(كأن سناها لاح لي من خصاصة ... على غير قصد والمطي سواري)\n(حميسية بالرملتين محلها ... تمد بحلف بيننا وجوار)\nال أبو داود وكانت بنو حميس حلفاء لبنى سهم بن مرة ثم للحصين بن\nالحمام وتمد وتمت واحد","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":15,"spl":"رثاء الوليد — رجع إلى الشعر"},
{"id":"b12-19","bab":"الجزء 2","sec":"رجع إلى الشعر","page":"ج2 ص310","text":"(تجاور من سهم بن مرة نسوة ... بمجتمع النقبين غير عواري)\n(نواعم أبكارا كأن عيونها ... عيون ظباء أو عيون صوار)\n(كأنا نراها وهي منا قريبة ... على متن عصماء اليدين نوار)\n(تتبع من حجر ذرا متمنع ... لها معقل في رأس كل طمار)\n(يدور بها ذو أسهم لا ينالها ... وذو كلبات كالقسي ضواري)\n(كأن على المتنين منها ودية ... سقتها السواقي من ودي دوار)\n(يظل سحيق المسك يقطر حولها ... إذا الماشطات احتفنه بمداري)\n(وما روضة خضراء يضربها الندى ... بها قنة من حنوة وعرار)\n(بأطيب من ريح القرنفل ساطعا ... بما التف من درع لها وخمار)\n(وما ظبية ساقت لها الريح نغمة ... على غفلة فاستسمعت لخوار)\n(بأحسن منها يوم قامت فأتلعت ... على شرك من روعة ونفار)\n(فليتك يا حسناء يابنة مالك ... يبيع لنا منك المودة شاري)","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":15,"spl":"رثاء الوليد — رجع إلى الشعر"},
{"id":"b12-20","bab":"الجزء 2","sec":"ابن ميادة وزينب بنت مالك","page":"ج2 ص311","text":"أخبرني بهذا الخبر الحرمي قال حدثنا الزبير قال حدثني أبو حرملة منظور بن أبي عدي الفزاري ثم المنظوري عن أبيه قال حدثني رماح بن أبرد قال خرجت قافلا من السلع إلى نجد حتى إذا كنت ببعض أهضام الحرة هكذا في نسختى وأظنه هضاب الحرة رفع لي بيت كالطراف العظيم وإذ\nبفنائه غنم لم تسرح فقلت بيت من بيوت بني مرة وبي من العيمة إلى اللبن ما ليس بأحد فقلت آتيهم فأسلم عليهم وأشرب من لبنهم فلما كنت غير بعيد سلمت فردت علي امرأة برزة بفناء البيت وحيت ورحبت واسنزلتني فنزلت فدعت بلبن ولبأ ورسل من رسل تلك الغنم ثم قالت هيا فلانة البسي شفا واخرجي فخرجت علي جارية كأنها شمعة ما رأيت في الخلق لها نظيرا قبل ولا بعد فإذا شفها ذاك ليس يواري منها شيئا وقد نبا عن ركبها ما وقع عليه من الثوب فكأنه قعب مكفأ ثم قالت يا بن ميادة الخبيثة أأنت القائل\n(وتبدي الحميسيات في كل زينة ... فروجا كآثار الصغار من البهم)\nفقلت لا والله جعلني الله فداك يا سيدتي ما قلت هذا قط وإنما قلت\n(وتبدي الحميسيات في كل زينة ... فروجا كآثار المقيسرة الدهم)\nقال وكان يقال للجارية الحميسية زينب بنت مالك وفيها قال ابن ميادة قصيدته\n(ألما فزورا اليوم خير مزار ... )\nخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني موهوب ابن رشيد الكلابي قال أعطى الوليد بن زيد ابن ميادة جارية طبرية أعجمية لا تفصح حسناء جميلة كاملة لولا العجمة فعشقها وقال فيها\n(جزاك الله خيرا من أمير ... فقد أعطيت مبرادا سخونا)\n(بأهلي ما ألذك عند نفسي ... لو أنك بالكلام تعريينا)\n(كأنك ظبية مضغت أراكا ... بوادي الجزع حين تبغمينا)","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":16,"spl":"ابن ميادة وزينب بنت مالك — بعض أوصاف ابن ميادة","partial":1},
{"id":"b12-21","bab":"الجزء 2","sec":"بعض أوصاف ابن ميادة","page":"ج2 ص313","text":"أخبرني الحرمي قال حدثنا الزبير قال حدثني إسحاق بن شعيب بن إبراهيم ابن محمد بن طلحة قال وردت على بني فزارة ساعيا فأتاني ابن ميادة مسلما على وجائتني بنو\nفزارة ومعها رجل من بني جعفر بن كلاب كان لهم جارا وكان مخططا موسوما بجمال فلما رأيته أعجبني فأقبلت على بني فزارة وقلت لهم أي أخوالي هذا فو الله إنه ليسرني أن أرى فيكم مثله فقالوا هذا أمتع الله بك رجل من بني جعفر بن كلاب وهو لنا جار قال فأصغى إلي ابن ميادة وكان قريبا مني وقال لا يغرنك بأبي أنت ما ترى من جسمه فإنه أجوف لا عقل له فسمعه الجعفري فقال أفي تقع يا بن ميادة وأنت لا تقري ضيفك فقال له بان ميادة إن لم أقره قراه ابن عمي وأنت لا تقري ولا ابن عمك قال ابن عمران فضحكت مما شهد به ابن ميادة على نفسه أخبرني الحرمي قال حدثنا الزبير قال حدثني محمد بن إسماعيل الجعفري عن المعلى بن نوح الفزاري قال حدثني خال لي كان شريفا من سادات بني فزارة قال ضفت ابن ميادة فأكرمني وتحفى بي وفرغ لي بيتا فكنت فيه ليس معي أحد ثم جاءني بقدح ضخم من لين إبله فشربته ثم ولى فلم ينشب أن جاءني بآخر فتناولت منه شيئا يسيرا فما لبثت حتى عاد بآخر فقلت حسبك يا رماح فلا حاجة لي بشيء فقال اشرب بأبي أنت فوالله لربما بات الضيف عندنا مدحورا أخبرني الحرمي قال حدثنا الزبير قال حدثني عمي مصعب عن جدي عبد الله بن مصعب قال\nأتينا ابن ميادة نتلقى منه الشعر فقال لنا هل لكم في فضل شنة فظنناها تمرا فقلنا له هات لنبسطه بذلك فإذا شنة فيها فضلة من خمر قد شرب بعضها وبقي بعض فلما رأيناها قمنا وتركناه أخبرنا الحرمي قال حدثنا الزبير قال حدثني إبراهيم بن عبد الرحمن الكثيري قال حدثني نعمة الغفاري قال قدم ابن ميادة المدينة فدعي في وليمة فجاء فوجد على باب الدار التي فيها الوليمة حرسا يضربون الزلالين بالسياط يمنعونهم من الدخول فرجع و هو يقول\n(ولما رأيت الأصبحية قنعت ... مفارق شمط حيث تلوى العمائم)\n(تركت دفاع الباب عما وراءه ... وقلت صحيح من نجا وهو سالم)\nخبرني يحيى بن علي عن أبيه عن إسحاق قال قال الوليد بن يزيد لابن ميادة في بعض وفاداته عليه من تركت عند نسائك قال رقيبين لا يخالفاني طرفة عين الجوع والعري وهذا القول والجواب يروى أن عمر بن عبد العزيز وعقيل بن علفة تراجعاهما وقد ذكر في\nأخبار عقيل","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":16,"spl":"ابن ميادة وزينب بنت مالك — بعض أوصاف ابن ميادة"},
{"id":"b12-22","bab":"الجزء 2","sec":"مدح أبي جعفر المنصور","page":"ج2 ص316","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عمي مصعب وأخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه عن الزبير و أخبرنا يحيى بن علي قال حدثنا أبو أيوب المديني عن مصعب أن ابن ميادة مدح أبا جعفر المنصور بقصيدته التي يقول فيها\n(طلعت علينا العيس بالرماح ... )\nثم خرج من عند أهله يريده فمر على إبله فحلبت له ناقة من إبله وراح عليه راعيه بلبنها فشربه ثم مسح على بطنه ثم قال سبحان الله إن هذا لهو الشره يكفيني لبن بكرة وأنا شيخ كبير ثم أخرج واغترب في طلب المال ثم رجع فلم يخرج وهذه القصيدة من جيد شعر ابن ميادة أولها\n(وكواعب قد قلن يوم تواعد ... قول المجد وهن كالمزاح)\n(يا ليتنا في غير أمر فادح ... طلعت علينا العيس بالرماح)\n(بينا كذاك رأينني متعصبا ... بالخز فوق جلالة سرداح)\n(فيهن صفراء المعاصم طفلة ... بيضاء مثل غريضة التفاح)\n(فنظرن من خلل الحجال بأعين ... مرضى مخالطها السقام صحاح)\n(وارتشن حين اردن أن يرمينني ... نبلا بلا ريش ولا بقداح)\nيقول فيها في مدح المنصور وبني هاشم\n(فلئن بقيت لألحقن بأبحر ... ينمين لا قطع ولا أنزاح)\n(ولآتين بني علي إنهم ... من يأتهم يتلق بالإفلاح)\n(قوم إذا جلب الثناء إليهم ... بيع الثناء هناك بالأرباح)\n(ولأجلسن إلى الخليفة إنه ... رحب الفناء بواسع بحباح)\nوهي قصيدة طويلة أخبرني الحرمي قال حدثنا الزبير قال حدثنا إسحاق بن أيوب بن سلمة قال اعتمرت في رجب سنة خمس ومائة فصادفني ابن ميادة بمكة وقدمها معتمرا فأصابنا مطر شديد تهدمت منه البيوت وتوالت فيه الصواعق فجلس إلي ابن ميادة الغد من ذلك اليوم فجعل يأتيني قوم من قومي وغيرهم فأستخبرهم عن ذلك الغيث فيقولون صعق فلان وانهدم منزل فلان فقال ابن ميادة هذا العيث لا الغيث فقلت فما الغيث عندك فقال\n(سحائب لا من صيب ذي صواعق ... ولا محرقات ماؤهن حميم)\n(إذا ما هبطن الأرض قد مات عودها ... بكين بها حتى يعيش هشيم)\nخبرني الحرمي قال حدثنا الزبير قال حدثني موسى بن زهير عن أبيه قال جلست أنا وعيسى بن عميلة وابن ميادة ذات يوم فأنشدنا ابن ميادة شعره مليا ثم أنشدنا قوله\n(ألا ليت شعري هل أبيتن ليلة ... بحرة ليلى حيث ربتني أهلي)\n(بلاد بها نيطت علي تمائمي ... وقطعن عني حين أدركني عقلي)\n(وهل أسمعن الدهر أصوات هجمة ... تطالع من هجل خصيب إلى هجل)\n(صهيبية صفراء تلقي رباعها ... بمنعرج الصمان والجرع السهل)\nتلقى راعها تطرح أولادها وواحد الرباع ربع\n(وهل أجمعن الدهر كفي جمعة ... بمهضومة الكشحين ذات شوى عبل)\n(محللة لي لا حراما أتيتها ... من الطيبات حين تركض في الحجل)\n(تميل إذا مال الضجيع بعطفها ... كما مال دعص من ذرا عقد الرمل)\nفقال له عيسى بن عميلة فأين قولك يا أبا الشرحبيل\n(لقد حرمت أمي علي عدمتها ... كرائم قومي ثم قلة ماليا)\nفقلت له فاعطف إذا إلى أمة بني سهيل فهي أعند وأنكد وقد كنت أظن أن ميادة قد ضربت جأشك على اليأس من الحرائر وأنا أداعبه وأضاحكه فضحك وقال\n(ألم تر قوما ينكحون بمالهم ... ولو خطبت أنسابهم لم تزوج)\nخبرني الحرمي قال حدثنا الزبير قال حدثني عمي مصعب وغيره أن حسينة اليسارية كانت جميلة وآل يسار من موالي عثمان رضوان الله عليه يسكنون تيماء ولهم هناك عدد وجلد وقد انتسبوا في كلب إلى يسار بن أبي هند فقبلهم بنو كلب قال وكانت عند رجل من قومها يقال له عيسى بن إبراهيم ابن يسار وكان ابن ميادة يزورها وفيها\n(ستأتينا حسينة حيث شئنا ... وإن رغمت أنوف بني يسار)\nقال فدخل عليها زوجها يوما فوجد ابن ميادة عندها فهم به هو وأهلها فقاتلهم وعاونته عليهم حسينة حتى أفلت ابن ميادة فقال في ذلك\n(لقد ظلت تعاونني عليهم ... صموت الحجل كاظمة السوار)\n(وقد غادرت عيسى وهو كلب ... يقطع سلحه خلف الجدار)","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":17,"spl":"مدح أبي جعفر المنصور","partial":1},
{"id":"b12-23","bab":"الجزء 2","sec":"ابن ميادة يمدح عبد الواحد بن سليمان بن عبد الملك","page":"ج2 ص319","text":"أخبرني يحيى بن علي بن يحيى قال حدثني إبراهيم بن سعد بن شاهين قال حدثني عبد الله بن خالد بن دفيف التغلبي عن عثمان بن عبد الرحمن بن نميرة العدوي عن أبي العلاء بن وثاب قال\nقدم ابن ميادة المدينة زائرا لعبد الواحد بن سليمان بن عبد الملك وهو أميرها وكان يسمر عنده في الليل فقال عبد الواحد لأصحابه إني أهم أن أتزوج فابغوني أيما فقال له ابن ميادة أنا أدلك أصلحك الله أيها الأمير قال على من يا أبا الشرحبيل قال قدمت عليك أيها الأمير فدخلت مسجدكم فإذا أشبه شيء به وبمن فيه الجنة وأهلها فوالله لبينا أنا أمشي فيه إذ قادتني رائحة عطر رجل حتى وقفت بي عليه فلما وقع بصري عليه استلهاني حسنه فما أقلعت عنه حتى تكلم فخلته لما تكلم يتلو زبورا أو يدرس إنجيلا أو يقرأ قرآنا حتى سكت فلولا معرفتي بالأمير لشككت أنه هو ثم خرج من مصلاه إلى داره فسألت من هو فأخبرت أنه للحيين وبين الخليفتين وأن قد نالته ولادة من رسول الله لها نور ساطع من غرته وذؤابته فنعم المنكح ونعم حشو الرحل وابن العشيرة فإن اجتمعت أنت وهو على ولد ساد العباد وجاب ذكره البلاد فلما قضى ابن ميادة كلامه قال عبد الواحد ومن حضره ذاك محمد بن عبد الله بن عمرو بن عثمان وأمه فاطمة بنت الحسين فقال ابن ميادة\n(لهم نبوة لم يعطها الله غيرهم ... وكل قضاء الله فهو مقسم)\nقال يحيى بن علي ومما مدح به عبد الواحد لما قدم عليه قوله\n(من كان أخطأه الربيع فإنما ... نصر الحجاز بغيث عبد الواحد)\n(إن المدينة أصبحت معمورة ... بمتوج حلو الشمائل ماجد)\n(ولقد بلغت بغير أمر تكلف ... أعلى الحظوظ برغم أنف الحاسد)\n(وملكت ما بين العراق ويثرب ... ملكا أجار لمسلم ومعاهد)\n(ماليهما ودميهما من بعد ما ... غشى الضعيف شعاع سيف المارد)\nأخبرني الحرمي قال حدثنا الزبير قال حدثني سعيد بن زيد السلمي إنا لنزول أنا وأصحاب لي قبل الفطر بثلاث ليال على ماء لنا فإذا راكب يسير على جمل ملتف بثوب والسماء تغسله حتى أناخ إلى أجم عرفته فلما رأيناه لثقا قمنا إليه فوضعنا رحله وقيدنا جمله فلما أقلعت السماء عنا وهو معنا قاعد قام غلمة منا يرتجزون والرجل لم ينتسب لناولا عرفناه فارتجز أحدهم فقال\n(أنا ابن ميادة لباس الحلل ... أمر من مر وأحلى من عسل)\nحتى قال له الرجل يابن أخي أتدري من قال هذا الشعر قال نعم ابن ميادة قال فأنا هو ابن ميادة الرماح بن أبرد وبات يعللنا من شعره ويقطع عنا الليل بنشيده وسرينا راحلين فصبحنا مكة فقضينا نسكنا ولقيه رجلان من قومه من بني مرة فعرفهما وعرفاه وأفطرنا بمكة فلما انصرفنا من المسجد يوم الفطر إذا نحن بفارسين مسودين وراجلين مع المريين يقولون أين ابن ميادة فقلنا هاهو وقد برزنا من خيمة كنا فيها فقلنا لابن ميادة ابرز فلما نظر إلى المريين قال\n(إحدى عشياتك يا شميرج ... )\nال وهذا رجز لبعض بني سليم يقوله لفرسه\n(أقول والركبة فوق المنسج ... إحدى عشياتك يا شميرج)\nويروى مشمرج فقالوا لابن ميادة أجب الأمير عبد الصمد بن علي وخذ معك من أصحابك من أحببت فخرج وخرج معه منا أربعة نفر أنا أحدهم حتى وقفنا على باب دار الندوة فدخل أحد المسودين ثم خرج فقال ادخل يا أبا شجرة فدخلت على عبد الصمد بن علي فوجدته جالسا متوشحا بملحفة موردة فقال لي من أنت قلت رجل من بني سليم فقال مالك تصاحب المري وقد قتلوا معاوية بن عمرو وقالت الخنساء\n(ألا ما لعيني ألا ما لها ... لقد أخضل الدمع سربالها)\n(فآليت آسى على هالك ... وأسأل نائحة مالها)\n(أبعد ابن عمرو من آل الشريد ... حلت به الأرض أثقالها)\n(فإن تك مرة أودت به ... فقد كان يكثر تقتالها)\nأترويها قلت نعم أصلح الله الأمير وما زال من المعركة حتى قتل به خفاف ابن عمرو المعروف بابن ندبة كبش القوم مالك بن حمار الفزاري ثم\nالشمخي أما سمع الأمير قول خفاف بن ندبة في ذلك\n(فإن تك خيلي قد أصيب صميمها ... فعمدا على عين تيممت مالكا)\n(تيممت كبش القوم حين رأيته ... وجانبت شبان الرجال الصعالكا)\n(أقول له والرمح يأطر متنه ... تأمل خفافا إنني أنا ذلكا)","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":18,"spl":"ابن ميادة يمدح عبد الواحد بن سليمان بن عبد الملك","partial":1},
{"id":"b12-24","bab":"الجزء 2","sec":"ابن ميادة يمدح عبد الواحد بن سليمان بن عبد الملك","page":"ج2 ص319","text":"وقد توسط معاوية بن عمرو خيلهم فأكثر فيهم القتل وقتل كبش القوم الذي أصيب بأيديهم فقال لله درك إذا ولدت النساء فليلدن مثلك وأمر لي بألف درهم فدفعت إلي وخلع علي وأدخل ابن ميادة فسلم عليه بالإمرة فقال له لا سلم الله عليك يا ماص كذا من أمه فقال ابن ميادة ما أكثر الماصين فضحك عبد الصمد ودعا بدفتر فيه قصيدة ابن ميادة التي يقول فيها\n(لنا الملك إلا أن شيئا تعده ... قريش ولو شئنا لداخت رقابها)\nثم قال لابن ميادة أعتق ما أملك إن غادرت منها شيئا إن لم أبلغ غيظك فقال ابن ميادة أعتق ما أملك إن أنكرت منها بيتا قلته أو أقرررت ببيت لم أقله فقرأها عبد الصمد ثم قال له أأنت قلت هذا قال نعم قال أفكنت أمنت يابن ميادة أن ينقض عليك باز من قريش فيضرب رأسك فقال ما أكثر البازين أفكان ذلك البازي آمنا أن يلقاه باز من قيس وهو يسير فيرميه فتشول رجلاه فضحك عبد الصمد ثم دعا بكسوة فكساهم\nأخبرني حبيب بن نصر المهلبي قال حدثنا عبد الصمد بن شبيب قال قال أبو حذافة السهمي سب رجل من قريش في أيام بني أمية بعض ولد الحسن بن علي عليهما السلام فأغلظ له وهو ساكت والناس يعجبون من صبره عليه فلما أطال أقبل الحسني عليه متمثلا بقول ابن ميادة\n(أظنت سفاها من سفاهة رأيها ... أن اهجوها لما هجتني محارب)\n(فلا وأبيها إنني بعشيرتي ... ونفسي عن ذاك المقام لراغب)\nفقام القرشي خجلا وما رد عليه جوابا","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":19,"spl":"ابن ميادة يمدح عبد الواحد بن سليمان بن عبد الملك — مدح جعفر بن سليمان"},
{"id":"b12-25","bab":"الجزء 2","sec":"مدح جعفر بن سليمان","page":"ج2 ص324","text":"أخبرني أبو خليفة إجازة عن محمد بن سلام قال مدح ابن ميادة جعفر بن سليمان وهو على المدينة فأخبرني مسمع بن عبد الملك أنه قام له بحاجته عند جعفر وأوصلها إليه قال فقال له جزاك الله خيرا ممن أنت رحمك الله قلت أحد بني مسمع قال ممن قلت من قيس بن ثعلبة قال ممن عافاك الله قلت من بكر بن وائل قال والله لو كنت سمعت ببكر بن وائل قط أو عرفتهم لمدحتك ولكني ما سمعت ببكر قط ولا عرفتهم ثم مدح جعفرا فقال\n(لعمرك ما سيوف بني علي ... بنابية الظباة ولا كلال)\n(هم القوم الألى ورثوا أباهم ... تراث محمد غير انتحال)\n(وهم تركوا المقال لهم رفيعا ... وما تركوا عليهم من مقال)\n(حذوتم قومكم ما قد حذوتم ... كما يحذى المثال على المثال)\n(فردوا في جراحكم أسكم ... فقد أبلغتم مر النكال)\nيشير عليه بالعفو عن بني أمية ويذكره بأرحامهم أخبرنا بهذا الخبر يحيى بن علي عن سليمان المديني عن محمد بن سلام قال يحيى قال أبو الحارث المري فيما ذكره إسحاق من أخباره قال جعفر بن سليمان لابن ميادة أتحب أن أعطيك مثل ما أعطاك ابن عمك رياح بن عثمان فقال لا أيها الأمير ولكن أعطني كما أعطاني ابن عمك الوليد بن يزيد","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":19,"spl":"ابن ميادة يمدح عبد الواحد بن سليمان بن عبد الملك — مدح جعفر بن سليمان"},
{"id":"b12-26","bab":"الجزء 2","sec":"ابن ميادة يهجو بني أسد وبني تميم","page":"ج2 ص325","text":"قال يحيى وأخبرنا حماد عن أبيه عن أبي الحارث قال قال جعفر بن سليمان لابن ميادة أأنت الذي تقول\n(بني أسد إن تغضبوا ثم تغضبوا ... وتغضب قريش تحم قيسا غضابها)\nقال لا والله ما هكذا قلت قال فكيف قلت قال قلت\n(بني أسد إن تغضبوا ثم تغضبوا ... وتعدل قريش تحم قيسا غضابها)\nال صدقت هكذا قلت وهذه القصيدة يهجو بها ابن ميادة بني أسد وبني تميم وفيها يقول بعد هذا البيت الذي ذكره له جعفر بن سليمان\n(وأحقر محقور تميم أخوكم ... وإن غضبت يربوعها وربابها)\n(ألا ما أبالي أن تنخدف خندف ... ولست أبالي أن يطن ذبابها)\n(ولو أن قيسا قيس عيلان أقسمت ... على الشمس لم يطلع عليكم حجابها)\n(ولو حاربتنا الجن لم نرفع القنا ... عن الجن حتى لا تهر كلابها)\n(لنا الملك إلا أن شيئا تعده ... قريش ولو شئنا لذلت رقابها)\n(وإن غضبت من ذا قريش فقل لها ... معاذ الإله أن أكون أهابها)\n(وإني لقوال الجواب وإنني لمفتجر أشياء يعيي جوابها ... )\n(إذا غضبت قيس عليك تقاصرت ... يداك وفات الرجل منك ركابها)\nقال إسحاق في خبره فحدثني جبر بن رباط بن عامر بن نصر قال فقال سماعة بن أشول النعامي يعارض ابن ميادة\n(لعل ابن أشبانية عارضت به ... رعاء الشوي من مريح وعازب)\n(يسامي فروعا من خزيمة أحرزت ... عليه ثنايا المجد من كل جانب)\nفقال ابن ميادة من هذا لقد أغلق على أغلق الله عليه قالوا سماعة بن أشول فقال سماعة يسمع بي وأشول يشول بي والله لا أهاجيه أبدا وسكت عنه وقال عبد الرحمن بن جهيم الأسدي أحد بني الحارث بن سعد بن ثعلبة بن\nدودان بن أسد يرد على ابن ميادة وهي قصيدة طويلة ذكرت منها أبياتا\n(لقد كذب العبد ابن ميادة الذي ... ربا وهي وسط الشول تدمى كعابها)\n(شرنبثة الأطراف لم يقن كفها ... خضاب ولم تشرق بعطر ثيابها)\n(أراماح إن تغضب صناديد خندف ... يهج لك حربا قصبها واعتيابها)\nويروى اغتيابها من الغيبة واعتيابها من العيب\n(ولو أغضبت قيس قريشا لجدعت ... مسامع قيس وهي خضع رقابها)\n(لقد جر رماح ابن واهصة الخصى ... على قومه حربا عظيما عذابها)\n(وقد علم المملوح بالشؤم رأسه ... قتيبة أن لم تحم قيسا غضابها)\n(ولم تحمها أيام قتل ابن حازم ... وأيام قتلى كان خزيا مصابها)\n(ولا يوم لاقينا نميرا فقتلت ... نمير وفرت كعبها وكلابها)\n(وإن تدع قيسا لا تجبك وحولها ... خيول تميم سعدها وربابها)\n(ولو أن قيسا قيس عيلان أصحرت ... لأنواء غنم غرقتها شعابها)\n(ولو أن قرن الشمس كان لمعشر ... لكان لنا إشراقها واحتجابها)\n(ولكنها لله يملك أمرها ... بقدرته إصعادها وانصبابها)\n(لعمري لئن شابت حليلة نهبل ... لبئس شباب المرء كان شبابها)\n(ولم تدر حمراء العجان أنهبل ... أبوه أم المري تب تبابها)\nفإن يك رماح بن ميادة التي ... يصن إذا باتت بأرض ترابها جرى جري موهون القوى قصرت به ... لئيمة أعراق إليه انتسابها فلن تسبق المضمار في كل موطن ... من الخيل عند الجد إلا عرابها ووالله لولا أن قيسا أذلة ... لئام فلا يرضى لحر سبابها لألحقتها بالزنج ثم رميتها ... بشنعاء يعيي القائلين جوابها","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":20,"spl":"ابن ميادة يهجو بني أسد وبني تميم","partial":1},
{"id":"b12-27","bab":"الجزء 2","sec":"ابن ميادة وابان بن سعيد","page":"ج2 ص328","text":"أخبرني يحيى بن علي عن حماد عن أبيه قال وجدت في كتاب أبي عمرو الشيباني فعرضته على أبي داود فعرفه أو عامته قال أنا لجلوس على الهجم في ظل القصر عشية إذا أقبل إلينا ثلاثة نفر يقودون ناقة حتى جلسوا إلى أبان بن سعيد بن عيينة بن حصن وهو في جماعة من بني عيينة قال فرأيت أجلة ثلاثة ما رأيتهم قط فقلنا من القوم فقال أحدهم أنا ابن ميادة وهذان من عشيرتي فقال أبان لأحد بنيه اذهب بهذه الناقة فأطلق عنها عند بيت أمك فقال له ابن ميادة هذا يا أبا جعفر السعلاة أفلا أنشدك ما قلت فيها قال بلى فهات فقال\n(قعدت على السعلاة تنقض مسحها ... وتجذب مثل الأيم في برة الصفر)\n(تيمم خير الناس ماء وحاضرا ... وتحمل حاجات تضمنها صدري)\n(فإني على رغم الأعادي لقائل ... وجدت خيار الناس حي بني بدر)\n(لهم حاضر بالهجم لم أر مثلها ... من الناس حيا أهل بدو ولا حضر)\n(وخير معد مجلسا مجلس لهم ... يفيء عليه الظل من جانب القصر)\n(أخص بها روقي عيينة إنه ... كذاك ضحاح الماء يأوي إلى الغمر)\n(فأنتم أحق الناس أن تتخيروا المياه ... وأن ترعوا ذرى البلد القفر)\nال فكان أول قائم من القوم ركضة بن علي بن عيينة وهو ابن عم أبان وعبدة بنت أبان وكانت إبله في العطن وهي أكرم نعم بني عيينة وأكثره قال ما سمعت كاليوم مديح قوم قط حكمك ماض في هذه الإبل ثم قام آخر فقال مثل ذلك وقام آخر وآخر فقال ابن ميادة يا بني عيينة إني لم آتكم لتتبارى لي شياطينكم في أموالكم إنما كان علي دين فأردت أن تعطوني أبكرا أبيعها في ديني فأقام عند أبان بن سعيد خمسة عشر يوما ثم راح بتسع عشرة ناقة فيها ناقة لابن أبان عشراء أو رباعية قال يحيى في خبره وقال يعقوب بن\nجعفر بن أبان بن سعيد بن عيينة إني على الهجم يوما إذ أقبل رجل فجعل يصرف راحلته في الحياض فيرده الرجل بعد الرجل فدعوته فقلت اشرع في هذا الحوض فلما شرع فسقى قال من هذا الفتى فقيل هذا جعفر بن أبان بن سعيد بن عيينة فقال\n(بنو الصالحين الصالحون ومن يكن ... لآباء سوء يلقهم حيث سيرا)\n(فما العود إلا نابت في أرومه ... أبى شجر العيدان أن يتغيرا)\nقال إسحاق سألت أبا داود عن قوله\n(كذاك ضحاح الماء يجري إلى الغمر ... )\nفقال أراد أن الأمر كله والسؤدد يصير إليه كما يصير الماء إلى الغمرة حين كانت","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":21,"spl":"ابن ميادة وابان بن سعيد — ابن ميادة وأيوب بن سلمة","partial":1},
{"id":"b12-28","bab":"الجزء 2","sec":"ابن ميادة وأيوب بن سلمة","page":"ج2 ص330","text":"أخبرنا يحيى بن علي قال حدثنا أبو أيوب المديني قال أخبرني مصعب بن الزبير قال ضاف ابن ميادة أيوب بن سلمة فلم يقره وابن ميادة من أخوال أيوب بن سلمة فقال فيه\n(ظللنا وقوفا عند باب ابن أختنا ... وظل عن المعروف والمجد في شغل)\n(صفا صلد عند الندى ونعامة ... إذا الحرب أبدت عن نواجذها العصل)\nقال أبو أيوب وأخبرني مصعب قال قدم ابن ميادة على رياح بن عثمان وقد ولى المدينة وهو جاد في طلب محمد بن عبد الله بن حسن وإبراهيم أخيه فقال له اتخذ حرسا وجندا من غطفان واترك هؤلاء العبيد الذين تعطيهم دراهمك وحذار من قريش فاستخف بقوله ولم يقبل رأيه فلما قتل رياح قال ابن ميادة\n(أمرتك يا رياح بأمر حزم ... فقلت هشيمة من أهل نجد)\n(وقلت له تحفظ من قريش ... ورقع كل حاشية وبرد)\n(فوجدا ما وجدت على رياح ... وما أغنيت شيئا غير وجدي)","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":21,"spl":"ابن ميادة وابان بن سعيد — ابن ميادة وأيوب بن سلمة"},
{"id":"b12-29","bab":"الجزء 2","sec":"النساء في شعره","page":"ج2 ص331","text":"أخبرني عمي قال حدثني أحمد بن أبي طاهر قال حدثني أحمد بن إبراهيم ابن إسماعيل قال حدثني أكثم بن صيفي المري ثم الصاردي عن أبيه قال كان ابن ميادة رأى امرأة من بني جشم بن معاوية ثم من بني حرام يقال لها أم الوليد وكانوا ساروا عليه فأعجب بها وقال فيها\n(ألا حبذا أم الوليد ومربع ... لنا ولها نشتو به ونصيف)\nويروى\n(. . . . . . . . . . . . . . . . ومربع ... لنا ولها بالمشتوى ومصيف)\n(حرامية أما ملاث إزارها ... فوعث وأما خصرها فلطيف)\n(كأن القرون السود فوق مقذها ... إذا زال عنها برقع ونصيف)\n(بها زرجونات بقفر تنسمت ... لها الريح حتى بينهن رفيف)\nقال فلما سمع زوجها هذه الأبيات أتاها فحلف بطلاقها لئن وجد ابن ميادة عندها ليدقن فخذها ثم أعرض عنها واغترها حتى وجده يوما عند بيتها فدق فخذها واحتمل فرحل ورحل بها معه فقال ابن ميادة\n(أتانا عام سار بنو كلاب ... حراميون ليس لهم حرام)\n(كأن بيوتهم شجر صغار ... بقيعان تقيل بها النعام)\n(حراميون لا يقرون ضيفا ... ولا يدرون ما خلق الكرام)\nقال ثم سارت عليهم بعد ذلك بنو جعفر بن كلاب فأعجب بامرأة منهم يقال لها أم البختري وكان يتحدث إليها مدة مقامهم ثم ارتحلوا فقال فيها\n(أرقت لبرق لا يفتر لامعه ... بشهب الربى والليل قد نام هاجعه)\n(أرقت له من بعد ما نام صحبتي ... وأعجبني إيماضه وتتابعه)\n(يضيء صبيرا من سحاب كأنه ... هجان أرنت للحنين نوازعه)\n(هنيئا لأم البختري الروى به ... وإن أنهج الحبل الذي النأي قاطعه)\n(لقد جعل المستبضع الغش بيننا ... ليصرم حبلينا تجوز بضائعه)\n(فما سرحة تجري الجداول تحتها ... بمطرد القيعان عذب ينابعه)\n(بأحسن منها يوم قالت بذي الغضا ... أترعى جديد الحبل أم أنت قاطعه)\nخبرني عمي قال حدثني أحمد بن أبي طاهر قال حدثني أحمد بن إبراهيم قال وذكر أبو الأشعث أن ابن ميادة خطب امرأة بني سلمى بن مالك بن جعفر ثم من بني البهثة وهم بطن يقال لهم البهثاء فأبوا أن يزوجوه وقالوا أنت هجين ونحن أشرف منك فقال\n(فلو طاوعتني آل سلمى بن مالك ... لأعطيت مهرا من مسرة غاليا)\n(وسرب كسرب العين من آل جعفر ... يغادين بالكحل العيون السواجيا)\n(إذا ما هبطن النيل أو كن دونه ... بسرو الحمى ألقين ثم المراسيا)","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":22,"spl":"النساء في شعره — مات في صدر خلافة المنصور"},
{"id":"b12-30","bab":"الجزء 2","sec":"مات في صدر خلافة المنصور","page":"ج2 ص333","text":"قال أحمد بن إبراهيم مات ابن ميادة في صدر من خلافة المنصور وقد كان مدحه ثم لم يفد إليه ولا مدحه لما بلغه من قلة رغبته في مدائح الشعراء وقلة ثوابه لهم","topic":"أخبار ابن ميادة ونسبه","topicNo":12,"sp":22,"spl":"النساء في شعره — مات في صدر خلافة المنصور"},
{"id":"b13-1","bab":"الجزء 2","sec":"أخبار حنين الحيري ونسبه","page":"ج2 ص334","text":"حنين بن بلوع الحيري مختلف في نسبه فقيل إنه من العباديين من تميم وقيل إنه من بني الحارث بن كعب وقيل إنه من قوم بقوا من جديس وطسم فنزلوا في بني الحارث بن كعب فعدوا فيهم ويكنى أبا كعب وكان شاعرا مغنيا فحلا من فحول المغنين وله صنعة فاضلة متقدم وكان يسكن الحيرة ويكري الجمال إلى الشأم وغيرها وكان نصرانيا وهو القائل يصف الحيرة ومنزله بها صوت\n(أنا حنين ومنزلي النجف ... وما نديمي إلا الفتى القصف)\n(أقرع بالكأس ثغر باطية ... مترعة تارة وأغترف)\n(من قهوة باكر التجار بها ... بيت يهود قرارها الخزف)\n(والعيش غض ومنزلي خصب ... لم تغذني شقوة ولا عنف)\nالغناء والشعر لحنين ولحنه خفيف رمل بالبنصر وفيه لابن المكي خفيف ثقيل قديم ولعريب فيه خفيف ثقيل آخر عن الهشامي","topic":"أخبار حنين الحيري ونسبه","topicNo":13,"sp":0,"spl":"أخبار حنين الحيري ونسبه"},
{"id":"b13-2","bab":"الجزء 2","sec":"غناء حنين وبعض من أوصافه","page":"ج2 ص335","text":"أخبرنا وكيع قال قال حماد حدثني أبي عن أبي الخطاب قال وحدثني ابن كناسة عن سليمان بن داود مولى ليحيى وأخبرني بهذا الخبر الحسن بن علي عن ابن مهرويه عن قعنب بن المحرز الباهلي عن المدائني قالوا جميعا حج هشام بن عبد الملك وعديله الأبرش الكلبي فوقف له حنين بظهر الكوفة ومعه عوده وزامر له وعليه قلنسية طويلة فلما مر به هشام عرض له فقال من هذا فقيل حنين فأمر به فحمل في محمل على جمل وعديله زامره وسير به أمامه وهو يتغنى صوت\n(أمن سلمى بظهر الكوفة ... الآيات والطلل)\n(يلوح كما تلوح على ... جفون الصيقل الخلل)\nلصنعة في هذا الصوت لحنين ثاني ثقيل بالبنصر عن عمرو وفيه خفيف ثقيل ينسب إلى حنين أيضا وإلى غيره قال فأمر له هشام بمائتي دينار وللزامر بمائة وذكر إسحاق في خبره عن أبيه الخطاب أنه غنى هشاما\nصوت\n(صاح هل أبصرت بالخبتين ... من أسماء نارا)\n(موهنا شبت لعينيك ... ولم توقد نهارا)\n(كتلالي البرق في المزن ... إذا البرق استطارا)\n(أذكرتني الوصل من سعدى ... وأياما قصارا)\nلشعر للأحوص والغناء لابن سريج ثاني ثقيل بالسبابة في مجرى الوسطى عن إسحاق ونسبه ابن المكي إلى الغريض وقال يونس فيه لحنان لمالك ولم يجنسهما وقال الهشامي فيه لمالك خفيف رمل قال فلم يزل هشام يستفيده حتى نزل من النجف فأمر له بمائتي دينار وقال إسحاق قيل لحنين أنت تغني منذخمسين سنة ما تركت لكريم مالا ولا دارا ولا عقاراإلا أتيت عليه فقال بأبي أنتم إنما هي أنفاسي أقسمها بين الناس أفتلومونني أن أغلي بها الثمن وأخبرني الحسين بن يحيى ومحمد بن مزيد قالا حدثنا حماد بن إسحاق عن أبيه ومصعب بن الزبير عن بعض المكيين وأخرني به الحرمي بن أبي العلاء وحبيب بن نصر قالا حدثنا الزبير بن بكار قال حدثني عمي مصعب قال حدثني شيخ من المكيين يقال له شريس قال إنا لبالأبطح أيام الموسم نشتري ونبيع إذ أقبل شيخ أبيض الرأس واللحية على بغلة شهباء ما ندري أهو أشد بياضا أم بغلته أم ثيابه فقال أين بيت\nأبي موسى فأشرنا له إلى الحائط فمضى حتى انتهى إلى الظل من بيت أبي موسى ثم استقبلنا ببغلته ووجهه ثم اندفع يغني صوت\n(أسعديني بدمعة أسراب ... من دموع كثيرة التسكاب)\n(إن أهل الحصاب قد تركوني ... مغرما مولعا بأهل الحصاب)\n(فارقوني وقد علمت يقينا ... ما لمن ذاق ميتة من إياب)\n(سكنوا الجزع جزع بيت أبي موسى ... إلى النخل من صفي السباب)\n(كم بذاك الحجون من حي صدق ... وكهول أعفة وشباب)\n(أهل بيت تتايعوا للمنايا ... ما على الموت بعدهم من عتاب)\n(فلي الويل بعدهم وعليهم ... صرت فردا وملني أصحابي)\nلشعر لكثير بن كثير بن المطلب بن أبي وداعة السهمي والغناء لمعبد ثقيل أول بالسبابة في مجرى الوسطى وفيه لابن أبي دباكل الخزاعي ثاني ثقيل بالوسطى عن ابن خرداذبه قال ثم صرف الرجل بغلته وذهب فتبعناه حتى أدركناه فسألناه من هو فقال أنا حنين بن بلوع وأنا رجل جمال أكري الإبل ثم مضى أخبرني الحسين بن يحيى قال قال حماد قرأت على أبي عن المدائني قال كان حنين غلاما يحمل الفاكهة بالحيرة وكان لطيفا في عمل التحيات فكان إذا حمل الرياحين إلى بيوت الفتيان ومياسير أهل الكوفة وأصحاب القيان والمتطربين إلى الحيرة ورأوا رشاقته وحسن قده وحلاوته وخفة روحه استحلوه وأقام عندهم وخف لهم فكان يسمع الغناء ويشتهيه ويصغي إليه ويستمعه ويطيل الإصغاء إليه فلا يكاد ينتفع به في شيء إذا سمعه حتى شدا منه أصواتا فأسمعها الناس وكان مطبوعا حسن الصوت واشتهوا غناءه والاستماع منه وعشرته وشهر بالغناء ومهر فيه وبلغ منه مبلغا كبيرا ثم رحل إلى عمر بن داود الوادي وإلى حكم الوادي وأخذ منهما وغنى لنفسه في أشعار الناس فأجاد الصنعة وأحكمها ولم يكن بالعراق غيره فاستولى عليه في عصره وقدم ابن محرز حينئذ إلى الكوفة فبلغ خبره حنينا وقد كان يعرفه فخشي أن يعرفه الناس فيستحلوه ويستولي على البلد فيسقط هو فقال له كم منتك نفسك من العراق قال ألف دينار قال فهذه خمسمائة دينار عاجلة فخذها وانصرف واحلف لي أنك لا تعود","topic":"أخبار حنين الحيري ونسبه","topicNo":13,"sp":1,"spl":"غناء حنين وبعض من أوصافه"},
{"id":"b13-3","bab":"الجزء 2","sec":"غناء حنين وبعض من أوصافه","page":"ج2 ص335","text":"إلى العراق فأخذها وانصرف أخبرني عمي وعيسى بن الحسين قالا حدثنا أبو أيوب المدائني عن أحمد بن إبراهيم بن إسماعيل قال كان ابن محرز قدم الكوفة وبها بشر بن مروان وقد بلغه أنه يشرب الشراب ويسمع الغناء فصادفه وقد خرج إلى البصرة بلغ خبره حنين بن بلوع فتلطف له حتى دعاه فغناه ابن محرز لحنه قال أحمد بن إبراهيم وهو من الثقيل الثاني من جيد الأغاني صوت\n(وحر الزبرجد في نظمه ... على واضح الليت زان العقودا)\n(يفصل ياقوته دره ... وكالجمر أبصرت فيه الفريدا)\nقال فسمع شيئا هاله وحيره فقال له حنين كم منتك نفسك من العراق قال ألف دينار فقال هذه خمسمائة دينار حاصلة عاجلة ونفقتك في عودتك وبدأتك ودع العراق لي وامض مصاحبا حيث شئت قال وكان ابن محرز صغير الهمة لا يحب عشرة الملوك ولا يؤثر على الخلوة شيئا فأخذها وانصرف","topic":"أخبار حنين الحيري ونسبه","topicNo":13,"sp":2,"spl":"غناء حنين وبعض من أوصافه — حنين يغني في حمص متكسبا"},
{"id":"b13-4","bab":"الجزء 2","sec":"حنين يغني في حمص متكسبا","page":"ج2 ص339","text":"وقال حماد في خبره قال أبي حدثني بعض أهل العلم بالغناء عن حنين قال خرجت إلى حمص ألتمس الكسب بها وأرتاد من أستفيد منه شيئا فسألت\nعن الفتيان بها وأين يجتمعون فقيل لي عليك بالحمامات فإنهم يجتمعون بها إذا أصبحوا فجئت إلى أحدها فدخلته فإذا فيه جماعة منهم فأنست وانبسطت وأخبرتهم أني غريب ثم خرجوا وخرجت معهم فذهبوا بي إلى منزل أحدهم فلما قعدنا أتينا بالطعام فأكلنا وأتينا بالشراب فشربنا فقلت لهم هل لكم في مغن يغنيكم قالوا ومن لنا بذلك قلت أنا لكم به هاتوا عودا فأتيت به فابتدأت في هنيات أبي عباد معبد فكأنما غنيت للحيطان لا فكهوا لغنائي ولا سوا به فقلت ثقل عليهم غناء معبد بكثرة عمله وشدته وصعوبة مذهبه فأخذت في غناء الغريض فإذا هو عندهم كلا شيء وغنيت خفائف ابن سريج وأهزاج حكم والأغاني التي لي واجتهدت في أن يفهموا فلم يتحرك من القوم أحد وجعلوا يقولون ليت أبا منبه قد جاءنا فقلت في نفسي أرى أني سأفتضح اليوم بأبي منبه فضيحة لم يفتضح أحد قط مثلها فبينا نحن كذلك إذ جاء أبو منبه وإذا هو شيخ عليه خفان أحمران كأنه جمال فوثبوا جميعا إليه وسلموا عليه وقالوا يا أبا منبه أبطأت علينا وقدموا له الطعام وسقوه أقداحا وخنست أنا حتى صرت كلا شيء خوفا منه فأخذ العود ثم اندفع يغني\n(طرب البحر فاعبري يا سفينه ... لا تشقي على رجال المدينه)\nفأقبل القوم يصفقون ويطربون ثم أخذ في نحو هذا من الغناء فقلت في نفسي أنتم هاهنا لئن أصبحت سالما لا أمسيت في هذه البلدة فلما أصبحت شددت رحلي على ناقتي واحتقبت ركوة من شراب ورحلت متوجها إلى الحيرة وقلت\n(ليت شعري متى تخب بي الناقة ... بين السدير والصنين)\n(محقبا ركوة وخبز رقاق ... وبقولا وقطعة من نون)\n(لست أبغي زادا سواها من الشام ... وحسبي علالة تكفيني)\n(فإذا أبت سالما قلت سحقا ... وبعادا لمعشر فارقوني)\nخبرني محمد بن مزيد والحسين بن يحيى عن حماد عن أبيه وأخبرنا به وكيع في عقب أخبار رواها عن حماد بن إسحاق عن أبيه فقال وقال لي إسحاق فلا أدري أأدرج الإسناد وهو سماعه أم ذكره مرسلا قال إسحاق وذكر ابن كناسة أن خالد بن عبد الله القسري حرم الغناء بالعراق في أيامه ثم أذن للناس يوما في الدخول عليه عامة فدخل أليه حنين ومعه عود تحت ثيابه فقال أصلح الله الأمير كانت لي صناعة أعود بها على عيالي فحرمها الأمير فأضر ذلك بي وبهم فقال وما صناعتك فكشف عن عوده وقال هذا فقال له خالد عن فحرك أوتاره وغنى\nصوت\n(أيها الشامت المعير بالدهر ... أأنت المبرأ الموفور)\n(أم لديك العهد الوثيق من الأيام ... بل أنت جاهل مغرور)\n(من رأيت المنون خلدن أم من ... ذا عليه من أن يضام خفير)\nقال فبكى خالد وقال قد أذنت لك وحدك خاصة فلا تجالسن سفيها ولا معربدا فكان إذا دعي قال أفيكم سفيه أو معربد فإذا قيل له لا دخل شعر هذا الصوت المذكور لعدي بن زيد والغناء لحنين رمل بالوسطى عن عمرو وقوله المبرأ يعني المبرأ من المصائب الموفور الذي لم يذهب من ماله ولا من حاله شيء يقال وفر الرجل يوفر ولديك بمعنى عندك هاهنا","topic":"أخبار حنين الحيري ونسبه","topicNo":13,"sp":2,"spl":"غناء حنين وبعض من أوصافه — حنين يغني في حمص متكسبا"},
{"id":"b13-5","bab":"الجزء 2","sec":"حنين يغني بشر بن مروان","page":"ج2 ص342","text":"أخبرني أبو صالح محمد بن عبد الواحد الصحاف الكوفي قال حدثنا قعنب ابن المحرز الباهلي قال أخبرنا الهيثم بن عدي عن عبد الله بن عياش وعن مجالد عن الشعبي جميعا وأخبرني محمد بن مزيد وحسين بن يحيى عن حماد عن أبيه عن الهيثم بن عدي عن عبد الله بن عياش عن الشعبي قال لما ولي بشر بن مروان الكوفة كنت على مظالمه فأتيته عشية وحاجبه أعين صاحب حمام أعين جالس فقلت له استأذن لي على الأمير فقال لي يا أبا عمرو هو على حال ما أظنك تصل إليه معها فقلت أعلمه وخلاك ذم فقد حدث أمر لا بد لي من إنهائه إليه وكان لا يجلس بالعشي فقال لا ولكن اكتب حاجتك في رقعة حتى أوصلها إليه فكتبت رقعة فما لبث أن خرج التوقيع على ظهرها ليس الشعبي ممن يحتشم منه فأذن له فأذن لي فقال ادخل فدخلت فإذا بشر بن مروان عليه غلالة رقيقة صفراء وملاءة تقوم قياما من شدة\nالصقال وعلى رأسه إكليل من ريحان وعلى يمينه عكرمة بن ربعي وعلى يساره خالد بن عتاب بن ورقاء وإذا بين يديه حنين بن بلوع معه عوده فسلمت فرد علي السلام ورحب وقرب ثم قال يا أبا عمرو لو كان غيرك لم آذن له على هذه الحال فقلت أصلح الله الأمير عندي لك الستر لكل ما أرى منك والدخول معك فيما لا يجمل والشكر على ما توليني فقال كذاك الظن بك ثم التفت إلى حنين وعوده في حجره وعليه قباء خشك شوي وقال إسحاق خشكون ومستقة حمراء وخفان مكعبان فسلم علي فقلت له كيف أنت أبا كعب فقال بخير أبا عمرو فقلت احزق الزير وارخ البم ففعل وضرب فأجاد فقال بشر لأصحابه تلومونني على أن آذن له في كل حال ثم أقبل علي فقال أبا عمرو من أين وقع لك حزق الزير فقلت ظننت أن الأمر هناك فقال فإن الأمر كما ظننت هناك كله ثم قال فمن أين تعرف حنينا فقلت هذا بطة أعراسنا فكيف لا أعرفه فضحك وغنى حنين فأجاد فطرب وأمر له بجائزة ثم ودعته وقمت بعد أن ذكرت له ما جئت فيه فأمر لي بعشرة آلاف درهم وعشرة أثواب فقمت مع الخادم حتى قبضت ذلك منه وانصرفت وقد\nوجدت هذا الخبر بخط أبي سعيد السكري يأثره عن محمد بن عثمان المخزومي عن أبيه عن جده أنه كان عند بشر بن مروان يوم دخل عليه الشعبي هذا المدخل وأن حنين بن بلوع غناه\n(هم كتموني سيرهم حين أزمعوا ... وقالوا اتعدنا للرواح وبكروا)\nوهذا القول خطأ قبيح لأن هذا الشعر للعباس بن الأحنف والغناء لعلويه رمل بالوسطى وغني للمأمون فيه فقال سخروا من أبي الفضل أعزه الله","topic":"أخبار حنين الحيري ونسبه","topicNo":13,"sp":3,"spl":"حنين يغني بشر بن مروان"},
{"id":"b13-6","bab":"الجزء 2","sec":"بعض من اوصاف الحيرة","page":"ج2 ص344","text":"أخبرني الحسين بن يحيى قال قال حماد بن إسحاق قرأت على أبي وقال أبو عبيد الله الكاتب حدثني سليمان بن بشر بن عبد الملك بن بشر بن مروان قال وكان بعض ولاة الكوفة يذم الحيرة في أيام بني أمية فقال له رجل من أهلها وكان عاقلا ظريفا أتعيب بلدة بها يضرب المثل في الجاهلية والإسلام قال وبماذا تمدح قال بصحة هوائها وطيب مائها ونزهة ظاهرها تصلح للخف والظلف سهل وجبل وبادية وبستان وبر وبحر محل الملوك ومزارهم ومسكنهم ومثواهم وقد قدمتها أصلحك الله مخفا فرجعت مثقلا ووردتها مقلا فأصارتك مكثرا قال فكيف نعرف ما وصفتها به من الفضل قال بأن تصير إلي ثم ادع ما شئت من لذات العيش فوالله لا أجوز\nبك الحيرة فيه قال فاصنع لنا صنيعا واخرج من قولك قال أفعل فصنع لهم طعاما وأطعمهم من خبزها وسمكها وما صيد من وحشها من ظباء ونعام وأرانب وحبارى وسقاهم ماؤها في قلالها وخمرها في آنيتها وأجلسهم على رقمها وكان يتخذ بها من الفرش أشياء ظريفة ولم يستخدم لهم حرا ولا عبدا إلا من مولديها ومولداتها من خدم ووصائف ووصفاء كأنهم اللؤلؤ لغتهم لغة أهلها ثم غناهم حنين وأصحابه في شعر عدي بن زيد شاعرهم وأعشى همدان لم يتجاوزهما وحياهم برياحينها ونقلهم على خمرها وقد شربوا بفواكهها ثم قال له هل رأيتني استعنت على شيء مما رأيت وأكلت وشربت وافترشت وشممت وسمعت بغير ما في الحيرة قال لا والله ولقد أحسنت صفة بلدك ونصرته فأحسنت نصرته والخروج مما تضمنته فبارك الله لكم في بلدكم قال إسحاق ولم يكن بالحيرة مذكور في الغناء سوى حنين إلا نفرا من السدريين يقال لهم عباديس وزيد بن الطليس وزيد بن كعب ومالك بن حممة وكانوا يغنون غناء الحيرة بين الهزج والنصب وهو إلى النصب أقرب\nولم يدون منه شيء لسقوطه وأنه ليس من أغاني الفحول وما سمعنا نحن لأحد من هؤلاء خبرا إلا لمالك بن حممة أخبرني به عمي عن عبد الله بن أبي سعد وقال وكيع في خبره عن إسحاق حدثني أبو بشر الفزاري قال حدثني بشر بن الحسين بن سليمان بن سمرة بن جندب قال عاش حنين بن بلوع مائة سنة وسبع سنين وكان يقال إنه من جديس قال وقيل أيضا إنه من لخم وكان هو يزعم أنه عبادي وأخواله من بني الحارث بن كعب أخبرني رضوان بن أحمد الصيدلاني قال حدثنا يوسف بن إبراهيم قلا حدثنا أبو إسحاق إبراهيم بن المهدي قال كنت مع الرشيد في السنة التي نزل فيها على عون العبادي فأتاني عون بابن ابن حنين بن بلوع وهو شيخ فغناني عدة أصوات لجده فما استحسنتها لأن الشيخ كان مشوه الخلق طن الغناء قليل الحلاوة إلا أنه كان لا يفارق عمود الصوت أبدا حتى يفرغ منه فغناني صوت ابن سريج\n(فتركته جزر السباع ينشنه ... ما بين قلة رأسه والمعصم)\nفما أذكر أني سمعته من أحد قط أحسن مما سمعته منه فقلت له لقد أحسنت في\nهذا الصوت وما هو من أغاني جدك ولا من أغاني بلدك وإني لأعجب من ذلك فقال لي الشيخ والصليب والقربان ما صنع هذا الصوت إلا في منزلنا وفي سرداب لجدي ولقد كاد أن يأتي على نفس عمتي فسألته عن الخبر في ذلك فقال","topic":"أخبار حنين الحيري ونسبه","topicNo":13,"sp":4,"spl":"بعض من اوصاف الحيرة"},
{"id":"b13-7","bab":"الجزء 2","sec":"حنين في ضيافة ابن سريج","page":"ج2 ص347","text":"حدثني أبي أن عبيد بن سريج قدم الحيرة ومعه ثلثمائة دينار فأتى بها منزلنا في ولاية بشر بن مروان الكوفة وقال أنا رجل من أهل الحجاز من أهل مكة بلغني طيب الحيرة وجودة خمرها وحسن غنائك في هذا الشعر\n(حنتني حانيات الدهر حتى ... كأني خاتل يدنو لصيد)\n(قريب الخطو يحسب من رآني ... ولست مقيدا أني بقيد)\nفخرجت بهده الدنانير لأنفقها معك وعندك ونتعاشر حتى تنفد وأنصرف إلى منزلي فسأله جدي عن اسمه ونسبه فغيرهما وانتمى إلى بني مخزوم فأخذ جدي المال منه وقال موفر مالك عليك ولك عندنا كل ما يحتاج إليه مثلك ما نشطت للمقام عندنا فإذا دعتك نفسك إلى بلدك جهزناك إليه ورددنا عليك مالك وأخلفنا ما أنفقته عليك إلى أن جئتنا وأسكنه دارا كان ينفرد فيها فمكث عندنا شهرين لا يعلم جدي ولا أحد من أهلنا أنه يغني حتى انصرف جدي من دار بشر ابن مروان في يوم صائف مع قيام الظهيرة فصار إلى باب الدار التي كان أنزل ابن سريج فيها فوجده مغلقا فارتاب بذلك ودق الباب فلم يفتح له ولم يجبه أحد فصار إلى منازل الحرم فلم يجد فيها ابنته ولا جواريه ورأى ما بين الدار التي فيها الحرم ودار ابن سريج مفتوحا فانتضى سيفه ودخل الدار ليقتل ابنته فلما دخلها رأى ابنته وجواريه وقوفا على باب السرداب وهن يومئن إليه بالسكوت وتخفيف\nالوطء فلم يلتفت إلى إشارتهن لما تداخله إلى أن سمع ترنم ابن سريج بهذا الصوت فألقى السيف من يده وصاح به وقد عرفه من غير أن يكون رآه ولكن بالنعت والحذق أبا يحيى جعلت فداءك أتيتنا بثلثمائة دينار لتنفقها عندنا في حيرتنا فوحق المسيح لا خرجت منها إلا ومعك ثلثمائة دينار وثلثمائة دينار وثلثمائة دينار سوى ما جئت به معك ثم دخل إليه فعانقه ورحب به ولقيه بخلاف ما كان يلقاه به وسأله عن هذا الصوت فأخبره أنه صاغه في ذلك الوقت فصار معه إلى بشر بن مروان فوصله بعشرة آلاف درهم أول مرة ثم وصله بعد ذلك بمثلها فلما أراد الخروج رد عليه جدي ماله وجهزه ووصله بمقدار نفقته التي أنفقها من مكة إلى الحيرة ورجع ابن سريج إلى أهله وقد أخذ جميع من كان في دارنا منه هذا الصوت","topic":"أخبار حنين الحيري ونسبه","topicNo":13,"sp":5,"spl":"حنين في ضيافة ابن سريج — غنى للناس فمات بسبب الازدحام"},
{"id":"b13-8","bab":"الجزء 2","sec":"غنى للناس فمات بسبب الازدحام","page":"ج2 ص348","text":"أخبرني عمي قال حدثني عبد الله بن أبي سعد قال حدثني حسان بن محمد الحارثي قال حدثنا عبد الله قال حدثنا عبيد بن حنين الحيري قال كان المغنون في عصر جدي أربعة نفر ثلاثة بالحجاز وهو وحده بالعراق والذين بالحجاز ابن سريج والغريض ومعبد فكان يبلغهم أن جدي حنينا قد غنى في هذا الشعر\n(هلا بكيت على الشباب الذاهب ... وكففت عن ذم المشيب الآئب)\n(هذا ورب مسوفين سقيتهم ... من خمر بابل لذة للشارب)\n(بكروا علي بسحرة فصبحتهم ... من ذات كوب مثل قعب الحالب)\n(بزجاجة ملء اليدين كأنها ... قنديل فصح في كنيسة راهب)\nقال فاجتمعوا فتذاكروا أمر جدي وقالوا ما في الدنيا أهل صناعة شر منا لنا أخ بالعراق ونحن بالحجاز لا نزوره ولا نستزيره فكتبوا إليه ووجهوا إليه نفقة وكتبوا يقولون نحن ثلاثة وأنت وحدك فأنت أولى بزيارتنا فشخص إليهم فلما كان على مرحلة من المدينة بلغهم خبره فخرجوا يتلقونه فلم ير يوم كان أكثر حشرا ولا جمعا من يومئذ ودخلوا فلما صاروا في بعض الطريق قال له معبد صيروا إلي فقال له ابن سريج إن كان لك من الشرف والمروءة مثل ما لمولاتي سكينة بنت الحسين عطفنا إليك فقال مالي من ذلك شيء وعدلوا إلى منزل سكينة فلما دخلوا إليها أذنت للناس إذنا عاما فغصت الدار بهم وصعدوا فوق السطح وأمرت لهم بالأطعمة فأكلوا منها ثم إنهم سألوا جدي حنينا أن يغنيهم صوته الذي أوله\n(هلا بكيت على الشباب الذاهب ... )\nفغناهم إياه بعد أن قال لهم ابدأوا أنتم فقالوا ما كنا لنتقدمك ولا نغني قبلك حتى نسمع هذا الصوت فغناهم إياه وكان من أحسن الناس صوتا فازدحم الناس على السطح وكثروا ليسمعوه فسقط الرواق على من تحته فسلموا جميعا وأخرجوا أصحاء ومات حنين تحت الهدم فقالت سكينة عليها السلام لقد كدر علينا حنين سرورنا انتظرناه مدة طويلة كأنا والله كنا نسوقه إلى منيته","topic":"أخبار حنين الحيري ونسبه","topicNo":13,"sp":5,"spl":"حنين في ضيافة ابن سريج — غنى للناس فمات بسبب الازدحام","partial":1},
{"id":"b13-9","bab":"الجزء 2","sec":"نسبة ما في الخبر الأول من الغناء","page":"ج2 ص349","text":"صوت\n(فتركته جزر السباع ينشنه ... ما بين قلة رأسه والمعصم)\n(إن تغدفي دوني القناع فإنني ... طب بأخذ الفارس المستلئم)\nالشعر لعنترة بن شداد العبسي والعناء فيه لحنين ثاني ثقيل ومنها صوت\n(حنتني حانيات الدهر حتى ... كأني خاتل يدنو لصيد)\n(قريب الخطو يحسب من رآني ... ولست مقيدا أني بقيد)\nلغناء لحنين الحيري ثقيل أول وفيه لإبراهيم الموصلي ماخوري جميعا عن ابن المكي ووافقه عمرو بن بانة في لحن إبراهيم الموصلي ونسبة الشعر الذي غناه حنين في منزل سكينة عليها السلام يقال إنه لعدي بن زيد وقيل إن بعضه له وقد أضافه المغنون إليه ولحنه خفيف ثقيل مطلق في مجرى البنصر عن إسحاق صوت","topic":"أخبار حنين الحيري ونسبه","topicNo":13,"sp":6,"spl":"نسبة ما في الخبر الأول من الغناء — عمر بن أبي ربيعة وقصته مع بنت عبد الملك"},
{"id":"b13-10","bab":"الجزء 2","sec":"من المائة المختارة","page":"ج2 ص350","text":"(راع الفؤاد تفرق الأحباب ... يوم الرحيل فهاج لي أطرابي)\n(فظللت مكتئبا أكفكف عبرة ... سحا تفيض كواشل الأسراب)\n(لما تنادوا للرحيل وقربوا ... بزل الجمال لطية وذهاب)\nكاد الأسى يقضي عليك صبابة ... والوجه منك لبين إلفك كابي\nروضه من الكامل والشعر لعمر بن أبي ربيعة والغناء للغريض ولحنه المختار من الثقيل الأول بإطلاق الوتر في مجرى البنصر عن إسحاق وقال حبش وفيه لأبي كامل ثاني ثقيل بالوسطى وذكر حبش أن للغريض أيضا فيه خفيف ثقيل بالوسطى ولمالك ثقيل أول بالوسطى وهذه الأبيات قالها عمر ابن أبي ربيعة في بنت لعبد الملك بن مروان كانت حجت في خلافته","topic":"أخبار حنين الحيري ونسبه","topicNo":13,"sp":6,"spl":"نسبة ما في الخبر الأول من الغناء — عمر بن أبي ربيعة وقصته مع بنت عبد الملك"},
{"id":"b13-11","bab":"الجزء 2","sec":"عمر بن أبي ربيعة وقصته مع بنت عبد الملك","page":"ج2 ص351","text":"أخبرني علي بن صالح بن الهيثم قال أخبرني أبو هفان عن إسحاق بن إبراهيم عن الزبيري والمدائني ومحمد بن سلام والمسيبي أن بنتا لعبد الملك بن مروان حجت فكتب الحجاج إلى عمر بن أبي ربيعة يتوعده إن ذكرها في شعره بكل مكروه وكانت تحب أن يقول فيها شيئا وتتعرض لذلك فلم يفعل خوفا من الحجاج فلما قضت حجها خرجت فمر بها رجل فقالت له من أين أنت قال من أهل مكة قالت عليك وعلى أهل بلدك لعنة الله قال ولم ذاك قالت حججت فدخلت مكة ومعي من الجواري ما لم تر الأعين مثلهن فلم يستطع ابن أبي ربيعة أن يزودنا من شعره أبياتا نلهو بها في الطريق في سفرنا قال فإني لا أراه إلا قد فعل قالت فأتنا بشيء إن كان قاله ولك بكل بيت عشرة دنانير فمضى إليه فأخبره فقال لقد فعلت ولكن أحب أن تكتم علي قال أفعل فأنشده\n(راع الفؤاد تفرق الأحباب ... يوم الرحيل فهاج لي أطرابي)\nهي طويلة وأنشده\n(هاج قلبي تذكر الأحباب ... واعترتني نوائب الأطراب)\nوهي طويلة أيضا يقول فيها\n(أقتليني قتلا سريعا مريحا ... لا تكوني علي سوط عذاب)\n(شف عنها محقق جندي ... فهي كالشمس من خلال سحاب)\nذكر حبش أن في هذه الثلاثة الأبيات للهذلي ثاني ثقيل بالبنصر قال فعاد إليها الرجل فأنشدها هاتين القصيدتين فدفعت إليه ما وعدته به","topic":"أخبار حنين الحيري ونسبه","topicNo":13,"sp":6,"spl":"نسبة ما في الخبر الأول من الغناء — عمر بن أبي ربيعة وقصته مع بنت عبد الملك"},
{"id":"b14-1","bab":"الجزء 2","sec":"ذكر الغريض وأخباره","page":"ج2 ص353","text":"الغريض لقب لقب به لأنه كان طري الوجه نضرا غض الشباب حسن المنظر فلقب بذلك والفريض الطري من كل شيء وقال ابن الكلبي شبه بالإغريض وهو الجمار فسمي به وثقل ذلك على الألسنة فحذفت الألف منه فقيل له الغريض واسمه عبد الملك وكنيته أبو يزيد وأخبرنا إسماعيل بن يونس الشيعى عن عمر بن شبة عن أبي غسان عن جماعة من المكيين أنه كان يكنى أبا مروان وهو مولى العبلات وكان مولدا من مولدي البربر وولاؤه وولاء يحيى قيل وسمية للثريا صاحبة عمر بن أبي ربيعة وأخواتها الرضيا وقريبة وأم عثمان بنات علي بن عبد الله بن الحارث بن أمية الأصغر وقد مضت أخبارهن في صدر الكتاب أخبرني أحمد بن عبد العزيز الجوهري قال حدثني محمد بن نصر الضبعي قال حدثني عبد الكريم بن أبي معاوية العلابي عن هشام بن الكلبي عن أبيه وعن أبي مسكين وأخبرني أحمد بن عبد العزيز الجوهري قال حدثني عمر بن شبة قال حدثني أبو غسان محمد بن يحيى وأخبرني الحسين بن يحيى ومحمد بن أبي\nالأزهر حدثنا حماد بن إسحاق عن أبيه عن الزبيري والمدائني ومحمد بن سلام وقد جمعت رواياتهم في قصة الغريض قالوا","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":0,"spl":"ذكر الغريض وأخباره — الغريض يتعلم النوح وينوح في المآتم"},
{"id":"b14-2","bab":"الجزء 2","sec":"الغريض يتعلم النوح وينوح في المآتم","page":"ج2 ص354","text":"كان الغريض يضرب بالعود وينقر بالدف ويوقع بالقضيب وكان جميلا وضيئا وكان يصنع نفسه ويبرقها وكان قبل أن يغني خياطا وأخذ الغناء في أول أمره عن ابن سريج لأنه كان يخدمه فلما رأى ابن سريج طبعه وظرفه وحلاوة منطقه خشي أن يأخذ غناءه فيغلبه عليه عند الناس ويفوقه بحسن وجهه وجسده فاعتل عليه وشكاه إلى مولياته وهن كن دفعنه إليه ليعلمه الغناء وجعل يتجنى عليه ثم طرده فشكا ذلك إلى مولياته وعرفهن غرض ابن سريج في تنحيته إياه عن نفسه وأنه حسده على تقدمه فقلن له هل لك في أن تسمع نوحنا في قبلانا فتأخذه وتغني عليه قال نعم فافعلن فأسمعنه المراثي فاحتذاها وخرج غناء عليها كالمراثي وكان ينوح مع ذلك فيدخل المآتم وتضرب دونه الحجب ثم ينوح فيفتن كل من سمعه ولما كثر غناؤه اشتهاه الناس وعدلوا إليه لما كان فيه من الشجا فكان ابن سريج لا يغني صوتا إلا عارضه الغريض فيه لحنا آخر فلما رأى ابن سريج موقع الغريض اشتد عليه وحسده فغنى الأرمال والأهزاج فاشتهاها الناس فقال له الغريض يا أبا يحيى قصرت الغناء وحذفته قال نعم يا مخنث حين جعلت تنوح على أمك وأبيك قال إسحاق وحدثني أبو عبيدة قال لما غضب ابن سريج على الغريض فأقصاه وهجره لحق بحوراء وبغوم جاريتين نائحتين كانتا في شعب ابن\nعامر بمكة ولم يكن قبلهما ولا بعدهما مثلهما فرأتاه يوما يعصر عينيه ويبكي فقالتا له مالك تبكي فذكر لهما ما صنع به ابن سريج فقالتا له لا أرقأ الله دمعك ألزز رأسك بين ما أخذته عنه وبين ما تأخذه منا فإن ضعت بعدها فأبعدك الله","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":0,"spl":"ذكر الغريض وأخباره — الغريض يتعلم النوح وينوح في المآتم"},
{"id":"b14-3","bab":"الجزء 2","sec":"الغريض من الأربعة المشهورين في الفناء","page":"ج2 ص355","text":"قال إسحاق وحدثني أبو عبد الله الزبيري قال رأيت جريرا في مجلس من مجالس قريش فسمعته يقول كان المغنون بمكة أربعة فسيد مبرز وتابع مسدد فسألناه عن ذاك فقال كان السيد أبو يحيى بن سريج والتابع أبو يزيد الغريض وكان هناك رجل عالم بالصناعة فقال كان الغريض أحذق أهل زمانه بمكة بالغناء بعد ابن سريج وما زال أصحابنا لا يفرقون بينهما لمقاربتهما في الغناء قال الزبيري وقال بعض أهلي لو حكمت بين أبي يحيى وأبي يزيد لما فرقت بينهما وإنما تفضيلي أبا يحيى بالسبق فأما غير ذلك فلا لأن أبا يزيد عنه أخذ ومن بحره اغترف وفي ميدانه جرى فكان كأنه هو ولذلك قالت سكينة لما غنى الغريض وابن سريج\n(عوجي علينا ربة الهودج ... )\nوالله ما أفرق بينكما وما مثلكما عندي إلا كمثل اللؤلؤ والياقوت في أعناق الجواري الحسان لا يدري أي ذلك أحسن قال إسحاق وسمعت جماعة من البصراء عند أبي يتذاكرونهما فأجمعوا على أن الغريض أشجى غناء وأن ابن سريج أحكم صنعة\nقال إسحاق وحدثني أبو عبد الله الزبيري قال حدثني بعض أهلي قال حججنا فلما كنا بجمع سمعنا صوتا لم نسمع أحسن منه ولا أشجى فأصغى الناس كلهم إليه تعجبا من حسنه فسألت من هذا الرجل فقيل لي الغريض فتتابع جماعة من أهل مكة فقالوا ما نعرف اليوم أحدا أحسن غناء من الغريض ويدلك على ذلك أنه يعترض بصوته الحاج وهم في حجهم فيصغون إليه فسألوا الغريض عن ذلك فقال نعم فسألوه أن يغنيهم فأجابهم وخرج فوقف حيث لا يرى ويسمع صوته فترنم ورجع صوته وغنى في شعر عمر بن أبي ربيعة\n(أيها الرائح المجد ابتكارا ... قد قضى من تهامة الأوطار)\nفما سمع السامعون شيئا كان أحسن من ذلك الصوت وتكلم الناس فقالوا طائفة من الجن حجاج","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":1,"spl":"الغريض من الأربعة المشهورين في الفناء — نسبة هذا الصوت","partialRef":{"sid":"b3-16","gi":4,"vi":0,"side":0},"partial":1},
{"id":"b14-4","bab":"الجزء 2","sec":"نسبة هذا الصوت","page":"ج2 ص356","text":"صوت\n(أيها الرائح المجد ابتكارا ... قد قضى من تهامة الأوطار)\n(من يكن قلبه الغداة خليا ... ففؤادي بالخيف أمسى معارا)\n(ليت ذا الحج كان حتما علينا ... كل شهرين حجة واعتمارا)\nعروضه من الخفيف الشعر لعمر بن أبي ربيعة والغناء لابن محرز ولحنه من القدر الأوسط من الثقيل الثاني بالخنصر في مجرى الوسطى وفيه لحن للغريض من رواية حماد عن أبيه","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":1,"spl":"الغريض من الأربعة المشهورين في الفناء — نسبة هذا الصوت"},
{"id":"b14-5","bab":"الجزء 2","sec":"أمير مكة ينفي الغريض","page":"ج2 ص357","text":"أخبرني أحمد بن عبد العزيز الجوهري وإسماعيل بن يونس قالا حدثنا عمد ابن شبة قال حدثني إسحاق بن إبراهيم قال بلغني أن معبدا وابن سريج والغريض اجتمعوا بمكة ذات ليلة فقالوا هلم نبك أهل مكة ووجدت هذا الخبر بغير إسناد مرويا عن يونس الكاتب أن أميرا من أمراء مكة أمر بإخراج المغنين من الحرم فلما كان في الليلة التي عزم بهم على النفي في غدها اجتمعوا على أبي قبيس وكان معبد قد زارهم فبدأ معبد فغنى كذا روي عن يونس ولم يذكره الباقون صوت\n(أتربي من أعلى معد هديتما ... أجدا البكا إن التفرق باكر)\n(فما مكثنا دام الجميل عليكما ... بثهلان إلا أن تزم الأباعر)\nروضه من الطويل هكذا ذكره ولم ينسبه ولا جنسه قال فتأوه أهل مكة وأنوا وتمخطوا واندفع الغريض يغني\n(أيها الرائح المجد ابتكارا ... قد قضى من تهامة الأوطار)\nفارتفع البكاء والنحيب واندفع ابن سريج يغني\n(جددي الوصل يا قريب وجودي ... لمحب فراقه قد ألما)\n(ليس بين الحياة والموت إلا ... أن يردوا جمالهم فتزما)\nفارتفع الصراخ من الدور بالويل والحرب قال يونس في خبره واجتمع الناس إلى الأمير فاستعفوه من نفيهم فأعفاهم وذكر الباقون أن الغريض ابتدأ بلحنه\n(أيها الراكب المجد ابتكارا ... )\nوتلاه ابن سريج في جددي الوصل قال وارتفع الصراخ فلم يسمع من معبد شيء ولم يقدر على أن يغني أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال أخبرني عبد الرحمن بن محمد السعدي قال حضرت شطباء المغنية جارية علي بن جعفر ذات يوم تغني\n(ليس بين الرحيل والبين إلا ... أن يردوا جمالهم فتزما)\nفطرب علي بن جعفر وصاح سبحان الله العظيم ألا يوكون قربة ألا يشدون محملا ألا يعلقون سفرة ألا يسلمون على جار هذه والله العجلة أخبرني أحمد بن عبد العزيز وإسماعيل بن يونس قالا حدثنا عمر بن شبة قال حدثنا محمد بن يحيى قال زعم عبيد بن يعلى قال قال لي كثير بن كثير السهمي لما ماتت الثريا أتاني الغريض فقال لي قل لي شعرا أبك به عليها فقلت\nصوت\n(ألا يا عين مالك تدمعينا ... أمن رمد بكيت فتكحلينا)\n(أم انت مريضة تبكين شجوا ... فشجوك مثله أبكى العيونا)\nفناح به عليها قال وأخبرني من رآه بين عمودي سريرها ينوح به الغناء للغريض في هذين البيتين خفيف ثقيل بالوسطى عن ابن المكي وفيه ثقيل أول مجهول","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":2,"spl":"أمير مكة ينفي الغريض — سكينة بنت الحسين تساوي بين الغريض وابن سريج","partialRef":{"sid":"b2-62","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b14-6","bab":"الجزء 2","sec":"سكينة بنت الحسين تساوي بين الغريض وابن سريج","page":"ج2 ص359","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني محمد ابن سلام وأخبرنا وكيع قال حدثنا محمد بن إسماعيل عن محمد بن سلام بن جرير ورواه حماد عن أبيه عن ابن سلام عن جرير أيضا أن سكينة بنت الحسين عليه السلام حجت فدخل إليها ابن سريج والغريض وقد استعار ابن سريج حلة لامرأة من قريش فلبسها فقال لها ابن سريج يا سيدتي إني كنت صنعت صوتا وحسنته وتنوقت فيه وخبأته لك في حريرة في درج مملوء مسكا فنازعنيه هذا الفاسق يعني الغريض فأردنا أن نتحاكم إليك فيه فأينا قدمته فيه تقدم قالت هاته فغناها\n(عوجي علينا ربة الهودج ... إنك إلا تفعلي تحرجي)\nفقالت هاته أنت يا غريض فغناها إياه فقالت لابن سريج أعده فأعاده وقالت يا غريض أعده فأعاده فقالت ما أشبهكما إلا بالجديين الحار\nوالبارد لا يدري أيهما أطيب وقال إسحاق في خبره ما أشبهكما إلا باللؤلؤ والياقوت في أعناق الجواري الحسان لا يدري أيهما أحسن","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":2,"spl":"أمير مكة ينفي الغريض — سكينة بنت الحسين تساوي بين الغريض وابن سريج"},
{"id":"b14-7","bab":"الجزء 2","sec":"نسبة هذا الصوت","page":"ج2 ص360","text":"صوت\n(عوجي علينا ربة الهودج ... إنك إلا تفعلي تحرجي)\n(إني أتيحت لي يمانية ... إحدى بني الحارث من مذحج)\n(نلبث حولا كاملا كله ... لا نلتقي إلا على منهج)\n(في الحج إن حجت وماذا منى ... وأهله إن هي لم تحجج)\n(أيسر ما نال محب لدى ... بين حبيب قوله عرج)\nروضه من السريع والشعر للعرجي والغناء لابن سريج ثاني ثقيل بالوسطى عن عمرو وفيه للغريض ثقيل أول بالوسطى عن حبش ولإسحاق في الأول والثالث ثقيل أول بالبنصر عن عمرو وللأبجر فيه ثاني ثقيل بالخنصر في مجرى بالبنصر عن ابن المكي ولعلويه خفيف ثقيل عن الهشامي ولحكم خفيف رمل عنه أيضا أخبرني محمد بن خلف قال وكيع قال حدثنا عبد الله بن عمر عمرو بن بشر قال حدثني إبراهيم بن المنذر قال حدثني حمزة بن عتبة اللهبي عن عبد الوهاب بن مجاهد أو غيره قال كنت مع عطاء بن أبي رباح فجاءه رجل فأنشده قول العرجى\n(إني أتيحت لي يمانية ... )\nوذكر الأبيات وختمها بقوله\n(في الحج إن حجت وماذا منى ... وأهله إن هي لم تحجج)\nقال فقال عطاء بمنى والله وأهله خير كثير إذ غيبها الله وإياه عن مشاعره أخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة قال حدثني إسحاق قال ولي قضاء مكة الأوقص المخزومي فما رأى الناس مثله في عفافه ونبله فإنه لنائم ليلة في جناح له إذ مر به سكران يتغنى\n(عوجي علينا ربة الهودج ... )\nفأشرف عليه فقال يا هذا شربت حراما وأيقظت نياما وغنيت خطأ خذه غني فأصلحه له وانصرف أخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة قال حدثني إسحاق عن حمزة بن عتبة اللهبي قال مر الأبجر بعطاء وهو سكران فعذله وقال شهرت نفسك بالغناء واطرحتها وأنت ذو مروءة فقال امرأته طالق ثلاثا إن برحت أو أغنيك صوتا فإن قلت لي هو قبيح تركته فقال له عطاء هات ويحك فقد أضررت بي فغناه\n(في الحج إن حجت وماذا منى ... وأهله إن هي لم تحجج)\nفقال له عطاء الخير والله كله هناك حجت أولم تحج فاذهب الآن راشدا فقد برت يمينك","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":3,"spl":"نسبة هذا الصوت — نسبة هذا الصوت","partialRef":{"sid":"b3-16","gi":4,"vi":0,"side":0},"partial":1},
{"id":"b14-8","bab":"الجزء 2","sec":"الغريض وابن أبي عتيق","page":"ج2 ص361","text":"أخبرني أحمد بن عبد العزيز قال حدثنا محمد بن القاسم بن مهرويه قال حدثني المغيرة بن محمد قال حدثني هارون بن موسى الفروي قال حدثني بعض المدنيين قال خرج ابن أبي عتيق على نجيب له من المدينة قد أوقره من طرف المدينة\nالصخرة ففعل ذلك مرارا فقالوا له ما هذا يا غريض قال كأني بها قد جاءت يوم القيامة رافعة ذيلها تشهد علينا بما كان منا إلى جانبها فأردت أن أجرح شهادتها على ذلك اليوم","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":3,"spl":"نسبة هذا الصوت — نسبة هذا الصوت"},
{"id":"b14-9","bab":"الجزء 2","sec":"نسبة هذا الصوت","page":"ج2 ص361","text":"صوت\n(جرى ناصح بالود بيني وبينها ... فقربني يوم الحصاب إلى قتلي)\n(فقالت وأرخت جانب الستر إنما ... معي فتحدث غير ذي رقبة أهلي)\n(فقلت لها ما بي لهم من ترقب ... ولكن سري ليس يحمله مثلي)\nروضه من الطويل الشعر لعمر بن أبي ربيعة والغناء لابن سريج رمل بإطلاق الوتر في مجرى البنصر عن إسحاق في الثلاثة الأبيات وذكر يونس أن فيه لحنا لمالك وفيه للغريض خفيف ثقيل أول بالوسطى عن حبش والهشامي وعلي ابن يحيى وحماد بن إسحاق ولمعبد فيه ثقيل أول بالبنصر عن حبش ولابن محرز ثاني ثقيل بالوسطى عنه","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":3,"spl":"نسبة هذا الصوت — نسبة هذا الصوت"},
{"id":"b14-10","bab":"الجزء 2","sec":"عمر وجميل يتعارضان الشعر","page":"ج2 ص362","text":"حدثني علي بن صالح بن الهيثم قال حدثني أبو هفان عن إسحاق بن إبراهيم عن المسيبي والمدائني وابن سلام أن عمر بن أبي ربيعة كان يعارض جميلا إذا قال هذا قصيدة قال هذا مثلها فيقال إن عمر في الرائية والعينية أشعر من جميل وإن جميلا أشعر منه في اللامية وقال الزبير فيما أخبرني به الحرمي بن أبي العلاء عنه من الناس من\nيفضل قصيدة جميل اللامية على قصيدة عمر وأنا لا أقول هذا لأن قصيدة جميل مختلفة غير مؤتلفة فيها طوالع النجد وخوالد المهد وقصيدة عمر بن أبي ربيعة ملساء المتون مستوية الأبيات آخذ بعضها بأذناب بعض ولو أن جميلا خاطب في قصيدته مخاطبة عمر لأرتج عليه وعثر كلامه به أخبرني الحرمي قال حدثنا الزبير قال حدثني محمد بن إسماعيل بن إبراهيم قال حدثني شيخ من أهلي عن أبي الحارث بن نابتة مولى هشام بن الوليد المخزومي وهو الذي يقول له عمر بن أبي ربيعة\n(يا أبا الحارث قلبي طائر ... فاستمع قول رشيد مؤتمن)\nال شهدت عمر بن أبي ربيعة وجميلا بالأبطح فأنشد جميل قصيدته التي يقول فيها\n(لقد فرح الواشون أن صرمت حبلي ... بثينة أو أبدت لنا جانب البخل)\nثم قال يا أبا الخطاب هل قلت في هذا الوزن شيئا قال نعم فأنشده قوله\n(جرى ناصح بالود بيني وبينها ... )\nفقال جميل هيهات يا أبا الخطاب والله لا أقول مثل هذا سجيس الليالي والله ما خاطب النساء مخاطتبك أحد وقام مشمرا أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال\nرأيت علماءنا جميعا لا يشكون في أن أحسن ما يروى في تعظيم السر قول عمر\n(ولكن سري ليس يحمله مثلي ... )\nال الزبير وحدثني محمد بن إسماعيل قال حدثني ابن أبي الزناد قال إنما اجتمع عمر بن أبي ربيعة وجميل بالجناب أخبرني محمد بن أحمد الطلاس قال أخبرنا أحمد بن الحارث الخزاز عن المدائني أن الفرزدق سمع عمر بن أبي ربيعة ينشد هذه القصيدة فلما بلغ إلى قوله\n(فقمن وقد أفهمن ذا اللب أنما ... فعلن الذي يفعلن من ذاك من أجلي)\nصاح الفرزدق وقال هذا والله الشعر الذي أرادته الشعراء فأخطأته وبكت الديار","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":4,"spl":"عمر وجميل يتعارضان الشعر","partialRef":{"sid":"b2-26","gi":4,"vi":8,"side":1},"partial":1},
{"id":"b14-11","bab":"الجزء 2","sec":"نسبة ما في قصيدة عمر وسائر هذه الأخبار من الأغاني","page":"ج2 ص365","text":"سوى قصيدة جميل فإن لها أخبارا تذكر مع أخباره\nفمن ذلك قصيدة عمر التي أولها\n(جرى ناصح بالود بيني وبينها ... )\nوت\n(قفي البغلة الشهباء بالله سلمي ... عزيزة ذات الدل والخلق الجزل)\n(فلما تواقفنا عرفت الذي بها ... كمثل الذي بي حذوك النعل بالنعل)\n(فقلن لها هذا عشاء وأهلنا ... قريب ألما تسأمي مركب البغل)\nعروضه من الطويل الشعر لعمر بن أبي ربيعة و الغناء لمعبد في الأول و الثاني ثقيل أول و بالوسطى عن عمرو بن بانة و علي بن يحيى و قيل إنه لمالك ولابن محرز في الثاني و الثالث خفيف ثقيل أول بالبنصر عن الهشامي ولإبن سريج في الأول ثقيل و الثاني خفيف اخر بالوسطى وهو الذي فيه استهلال ولمالك في الثاني و الثالث ثاني ثقيل بالبنصر و لابراهيم فيهما خفيف ثقيل بالسبابة في مجرى الوسطى عن ابن المكي ومنها صوت\n(يا أبا الحارث قلبي طائر ... فاستمع قول رشيد مؤتمن)\n(ليس حب فوق ما أحببتكم ... غير أن أقتل نفسي أو أجن)\n(حسن الوجه نقي لونه ... طيب النشر لذيذ المحتضن)\nروضه من الرمل الشعر لعمر بن أبي ربيعة والغناء لابن سريج ثاني ثقيل بالوسطى عن عمرو وقيل إنه لابن عائشة وذكر ابن المكي أنه للغريض في الثاني والثالث وفيهما رمل يقال إنه لأهل مكة ويقال إنه لعبد الله بن يونس صاحب أيلة وفيه ثقيل أول ذكر حبش أنه لابن سريج وذكر غيره أنه لمحمد ابن السندي المكي وأنه غناه بحضرة إسحاق فأخذه عنه أخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة قال حدثنا أبو غسان محمد بن يحيىقال\nكان ابن عائشة يغني الهزج والخفيف فقيل له إنك لا تستطيع أن تغني غناء شجيا ثقيلا فغنى\n(يا أبا الحارث قلبي طائر ... )\nجع الحديث إلى أخبار الغريض أخبرني الحسين بن يحيى عن حماد عن أبيه عن أيوب بن عباية عن مولى لآل الغريض قال حدثني بعض مولياتي وقد ذكرن الغريض فترحمن عليه وقلن جاءنا يوما يحدثنا بحديث أنكرناه عليه ثم عرفنا بعد ذلك حقيقته وكان من أحسن الناس وجها صغيرا وكبيرا وكنا نلقى من الناس عنتا بسببه هو كان ابن سريج في جوارنا فدفعناه إليه فلقن الغناء وكان من أحسن الناس صوتا ففتن أهل مكة بحسن وجهه مع حسن صوته فلما رأى ذلك ابن سريج نحاه عنه وكانت بعض مولياته تعلمه النياحة فبرز فيها فجاءني يوما فقال نهتني الجن أن أنوح وأسمعتني صوتا عجيبا فقد ابتنيت عليه لحنا فاسمعيه مني واندفع فغنى بصوت عجيب في شعر المرار الأسدي\n(حلفت لها يالله ما بين ذي الغضا ... وهضب القنان من عوان ولا بكر)\n(أحب إلينا منك دلا وما نرى ... به عند ليلى من ثواب ولا أجر)\nفكذبناه وقلنا شيء فكر فيه وأخرجه على هذا اللحن فكان في كل يوم يأتينا فيقول سمعت البارحة صوتا من الجن بترجيع وتقطيع قد بنيت عليه صوت كذا وكذا بشعر فلان فلم يزل على ذلك ونحن ننكر عليه فإنا لكذلك ليلة وقد اجتمع جماعة من نساء أهل مكة في جمع لنا سهرنا فيه ليلتنا والغريض يغنينا بشعر عمر بن أبي ربيعة\n(أمن آل زينب جد البكور ... نعم فلأي هواها تصير)\nإذ سمعنا في بعض الليل عزيفا عجيبا وأصواتا مختلفة ذعرتنا وأفزعتنا فقال لنا الغريض إن في هذه الأصوات صوتا إذا نمت سمعته وأصبح فأبني عليه غنائي فأصغينا إليه فإذا نغمتة نغمة الغريض بعينها فصدقناه تلك الليلة","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":5,"spl":"نسبة ما في قصيدة عمر وسائر هذه الأخبار من الأغاني — نسبة ما في هذا الخبر من الغناء","partialRef":{"sid":"b2-26","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b14-12","bab":"الجزء 2","sec":"نسبة ما في هذا الخبر من الغناء","page":"ج2 ص368","text":"صوت\n(حلفت لها ... )\nالبيتان عروضه من الطويل غناه الغريض ولحنه من الثقيل الأول بالوسطى عن حبش قال ولعلويه فيه ثقيل أول آخر بالبنصر ومنها صوت\n(أمن آل زينب جد البكور ... نعم فلأي هواها تصير)\n(أبا الغور أم أنجدت دارها ... وكانت حديثا بعهدي تغور)\n(نظرت بخيف منى نظرة ... إليها فكاد فؤادي يطير)\n(هي الشمس تسري بها بغلة ... وما خلت شمسا بليل تسير)\n(ألم تر أنك مستشرف ... وأن عدوك حولي حضور)\nروضه من المتقارب الشعر للنميري وقيل أنه ليزيد بن معاوية والغناء لسياط خفيف ثقيل أول بالوسطى عن عمرو ولابن سريج فيه خفيف ثقيل بالوسطى أوله\n(هي الشمس تسري بها بغلة ... )\nوفيه للغريض ثاني ثقيل بالبنصر عن الهشامي وحماد ذكر غيرهما أنه لابن جامع وذكر حبش أن فيها لابن محرز ثقيلا أول بالبنصر","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":5,"spl":"نسبة ما في قصيدة عمر وسائر هذه الأخبار من الأغاني — نسبة ما في هذا الخبر من الغناء","partial":1},
{"id":"b14-13","bab":"الجزء 2","sec":"الغريض وسكينة","page":"ج2 ص369","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه قال قال أبو عبد الله مصعب الزبيري اجتمع نسوة فذكرن عمر بن أبي ربيعة وشعره وظرفه وحسن مجلسه وحديثه وتشوقن إليه وتمنينه فقالت سكينة أنا لكن به فبعثت إليه رسولا ووعدته الصورين\nلليلة سمتها فوافاها على رواحله ومعه الغريض فحدثهن حتى وافى الفجر وحان انصرافهن فقال لهن إني والله لمشتاق إلى زيارة قبر النبيوالصلاة في مسجده ولكن لا أخلط بزيارتكن شيئا ثم انصرف إلى مكة وقال\n(ألمم بزينب إن البين قد أفدا ... قل الثواء لئن كان الرحيل غدا)\nقال وانصرف عمر بالغريض معه فلما كان بمكة قال عمر يا غريض إني أريد أن أخبرك بشيء يتعجل لك نفعه ويبقى لك ذكره فهل لك فيه قال افعل من ذلك ما شئت وما أنت أهله قال إني قد قلت في هذه الليلة التي كنا فيها شعرا فامض به إلى النسوة فأنشدهن ذلك وأخبرهن أني وجهت بك فيه قاصدا قال نعم فحمل الغريض الشعر ورجع إلى المدينة فقصد سكينة وقال لها جعلت فداك إن يا سيدتي ومولاتي إن أبا الخطاب أبقاه الله وجهني إليك قاصدا قالت أوليس في خير وسرور تركته قال نعم قالت وفيم وجهك أبو الخطاب حفظه الله قال جعلت فداك إن ابن أبي ربيعة حملني شعرا وأمرني أن أنشدك إياه قالت فهاته قال فأنشدها\n(ألمم بزينب إن البين قد أفدا ... قل الثواء لئن كان الرحيل غدا)\nالشعر كله قالت فيا ويحه فما كان عليه ألا يرحل في غده فوجهت إلى النسوة فجمعتهن وأنشدتهن الشعر وقالت للغريض هل عملت فيه شيئا قال قد غنيته ابن أبي ربيعة قالت فهاته فغناه الغريض فقالت سكينه أحسنت والله وأحسن ابن أبي ربيعه لولا أنك سبقت فغنيته عمر قبلنا لأحسنا جائزتك يا بنانة أعطيه بكل بيت ألف درهم فأخرجت اليه بنانة أربعة الاف درهم فدفعتها إليه وقالت سكينة لو زادنا عمر لزدناك","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":6,"spl":"الغريض وسكينة — الغريض وعائشة بنت طلحة"},
{"id":"b14-14","bab":"الجزء 2","sec":"نسبة هذا الغناء","page":"ج2 ص371","text":"صوت\n(ألمم بزينب إن البين قد أفدا ... قل الثواء لئن كان الرحيل غدا)\n(قد حلفت ليلة الصورين جاهدة ... وما على الحر إلا الصبر مجتهدا)\n(لأختها ولأخرى من مناصفها ... لقد وجدت به فوق الذي وجدا)\n(لعمرها ما أراني إن نوى نزحت ... وهكذا الحب إلا ميتا كمدا)\nروضه - من البسيط - الشعر لعمر بن أبي ربيعة والغناء لابن سريج وله فيه لحنان أحدهما رمل بالسبابة في مجرى البنصر عن إسحاق والآخر خفيف رمل بالوسطى عن عمرو وفيه لحن للغريض خفيف ثقيل بالنصر عن الهشامي وحماد وذكر عمرو إنه لمالك أوله الرابع ثم الأول ومن الناس من ينسب هذا إلى معبد وأوله\n(يا أم طلحة إن البين قد أفدا ... )\nذلك خطأ اللحن الذي عمله معبد غير هذا وهو صوت\n(يا أم طلحة إن البين قد أفدا ... قل الثواء لئن كان الرحيل غدا)\n(أ مسى العراقي لا يدري إذا برزت ... من ذا تطوف بالأركان أو سجدا)\nروضه - من البسيط - الشعر للأحوص ويقال إنه لعمر أيضا والغناء لمعبد ولحنه من الثقيل الأول بالبنصر عن عمرو والهشامي","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":6,"spl":"الغريض وسكينة — الغريض وعائشة بنت طلحة","partialRef":{"sid":"b2-77","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b14-15","bab":"الجزء 2","sec":"الغريض وعائشة بنت طلحة","page":"ج2 ص372","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه عن محمد بن سلام قال حجت عائشة بنت طلحة بن عبيد الله فجاءتها الثريا وأخواتها ونساء أهل مكة القرشيات وغيرهن وكان الغريض فيمن جاء فدخل النسوة عليها فأمرت لهن بكسوة وألطاف كانت قد أعدتها لمن يجيئها فجعلت تخرج كل واحدة ومعها جاريتهاومعها ما أمرت لها به عائشة والغريض بالباب حتى خرج مولياته مع جواريهن الخلع والألطاف فقال الغريض فأين نصيبي من عائشة فقلن له أغفلناك وذهبت عن قلوبنا فقال ما أنا ببارح من بابها أو آخذ بحظي منها فإنها كريمة بنت كرام واندفع يغني بشعر جميل\n(تذكرت ليلى فالفؤاد عميد ... وشطت نواها فالمزار بعيد)\nفقالت ويلكم هذا مولى العبلات بالباب يذكر بنفسه هاتوه فدخل فلما رأته ضحكت وقالت لم أعلم بمكانك ثم دعت له بأشياء أمرت له بها ثم قالت له إن أنت غنيتني صوتا في نفسي فلك كذا وكذا شيء سمته له ذهب عن ابن سلام قال فغناها في شعر كثير\n(ومازلت من ليلى لدن طر شاربي ... إلى اليوم أخفي حبها وأداجن)\n(وأحمل في ليلى لقوم ضغينة ... وتحمل في ليلى علي الضغائن)\nفقالت له ما عدوت ما في نفسي ووصلته فأجزلت قال إسحاق فقلت لأبي عبد الله وهل علمت حديث هذين البيتين ولم سألت الغريض ذلك قال نعم","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":6,"spl":"الغريض وسكينة — الغريض وعائشة بنت طلحة"},
{"id":"b14-16","bab":"الجزء 2","sec":"الشعبي عند مصعب وزوجته عائشة","page":"ج2 ص373","text":"حدثني أبي قال قال الشعبي دخلت المسجد فإذا أنا بمصعب ابن الزبير على سرير جالس والناس عنده فسلمت ثم ذهبت لأنصرف فقال لي ادن فدنوت حتى وضعت يدي على مرافقه ثم قال إذا قمت فاتبعني فجلس قليلا ثم نهض فتوجه نحو دار موسى بن طلحة فتبعته فلما طعن في الدار التفت إلي فقال ادخل فدخلت معه ومضى نحو حجرته وتبعته فالتفت لي فقال ادخل فدخلت معه فإذا حجلة وإنها لأول حجلة رأيتها لأمير فقمت ودخل الحجلة فسمعت حركة فكرهت الجلوس ولم يأمرني بالانصراف فإذا جارية قد خرجت فقالت يا شعبي إن الأمير يأمرك أن تجلس فجلست على وسادة ورفع سجف الحجلة فإذا أنا بمصعب بن الزبير ورفع السجف الآخر فإذا أنا بعائشة بنت طلحة قال فلم أر زوجا قط كان أجمل منهما مصعب وعائشة فقال مصعب يا شعبي هل تعرف هذه فقلت نعم أصلح الله الأمير قال ومن هي قلت سيدة نساء\nالمسلمين عائشة بنت طلحة قال لا ولكن هذه ليلى التي يقول فيها الشاعر\n(ومازلت من ليلى لدن طر شاربي ... )\nذكر البيتين ثم قال إذا شئت فقم فقمت فلما كان العشي رحت واذا هو جالس على سريره في المسجد فسلمت فلما رآني قال لي ادن فدنوت حتى وضعت يدي على مرافقه فأصغى إلي فقال هل رأيت مثل ذلك لإنسان قط قلت لا والله قال أفتدري لم أدخلناك قلت لا قال لتحدث بما رأيت ثم التفت إلى عبد الله بن أبي فروة فقال أعطه عشرة آلاف درهم وثلاثين ثوبا فما انصرف يومئذ أحد بمثل ما انصرفت به بعشرة آلاف درهم وبمثل كارة القصار ثيابا وبنظرة من عائشة بنت طلحة","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":7,"spl":"الشعبي عند مصعب وزوجته عائشة — نسبة هذا الصوت","partialRef":{"sid":"b14-15","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b14-17","bab":"الجزء 2","sec":"عائشة بنت طلحة وأزواجها","page":"ج2 ص374","text":"قال وكانت عائشة عند عبد الله بن عبد الرحمن بن أبي بكر وكان أبا عذرتها ثم هلك فتزوجها مصعب فقتل عنها ثم تزوجها عمر بن عبيد الله بن معمر فبنى بها بالحيرة ومهدت له يوم عرسه فرش لم ير مثلها سبع أذرع في عرض أربع فانصرف تلك الليلة عن سبع مرات فلقيته مولاة لها حين أصبح فقالت يا أبا حفص كملت في كل شيء حتى في هذا فلما مات ناحت عليه وهي قائمة ولم تنح على أحد منهم قائمة وكانت العرب إذا ناحت المرأة قائمة على زوجها علم أنها لا تريد أن تتزوج بعده فقيل لها يا عائشة ما صنعت هذا بأحد من أزواجك قالت إنه كان فيه خلال ثلاث لم تكن في أحد منهم كان سيد بنى تيم وكان أقرب القوم بي قرابة وأردت ألا أتزوج بعده وأخبرني بخبر مصعب والشعبي وعائشة أحمد بن عبيد الله بن عمار قال\nحدثنا سليمان بن أبي شيخ قال أخبرنا محمد بن الحكم عن عوانة قال خرج مصعب بن الزبير من دار الإمارة يريد دار موسى بن طلحة فمر بالمسجد فأخذ بيد الشعبي ثم ذكر باقي الحديث مثله ولم يذكر شيئا من حديث المغنين قال ابن عمار وأخبرني به داود بن جميل بن محمد بن جميل الكاتب عن ابن الأعرابي قال ابن عمار وأخبرني به أحمد بن الحارث الخزاز عن المدائني أن الشعبي قال دخلت المسجد وفيه مصعب بن الزبير فاستدناني فدنوت حتى وضعت يدي على مرافقه فأصغى إلي وقال إذا قمت فاتبعني ثم ذكر باقي الحديث أيضا مثل الذي تقدمه","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":7,"spl":"الشعبي عند مصعب وزوجته عائشة — نسبة هذا الصوت"},
{"id":"b14-18","bab":"الجزء 2","sec":"نسبة هذا الصوت","page":"ج2 ص374","text":"صوت\n(ومازلت من ليلى لدن طر شاربي ... إلى اليوم أخفي حبها وأداجن)\n(وأحمل في ليلى ضفائن معشر ... وتحمل في ليلى علي الضغائن)\nروضه - من الطويل - الشعر لكثير بن عبد الرحمن والغناء لمعبد ثقيل أول بالبنصر عن حبش وفيه لحن للغريض","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":7,"spl":"الشعبي عند مصعب وزوجته عائشة — نسبة هذا الصوت"},
{"id":"b14-19","bab":"الجزء 2","sec":"الغريض يغني عبد الملك في مكة","page":"ج2 ص375","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه قال كان الغريض إذا غنى بيتين لكثير قال أنا السريجي حقا ولم يكن يقول\nحذف\nذلك في شيء من غنائه وكان من جيد غنائه و قدم يزيد بن عبد الملك مكة فبعث إلى الغريض سرا فأتاه فغناه بهذا اللحن وهو فيهما\n(و إني لأرعى قومها من جلالها ... وإن أظهروا غشا نصحت لهم جهدي)\n(ولو حاربوا قومي لكنت لقومها ... صديقا ولم أحمل على قومها حقدي)\nأشير إلى الغريض أن اسكت وفطن يزيد فقال دعوا أبا يزيد حتى يغنيني بما يريد فأعاد عليه الصوت مرارا ثم قال زدني مما عندك فغناه بشعر عمرو بن شأس الأسدي\n(فواندمي على الشباب وواندم ... ندمت وبان اليوم مني بغير ذم)\n(أرادت عرارا بالهوان ومن يرد ... عرارا لعمري بالهوان فقد ظلم)\nال فطرب يزيد وأمر له بجائزة سنية قال إسحاق فحدثت أبا عبد الله هذا الحديث وقد أخذنا في أحاديث الخلفاء ومن كان منهم يسمع الغناء أيضا فقال أبو عبد الله كان قدوم يزيد مكة وبعثته إلى الغريض سرا قبل أن يستخلف فقلت له فلم أشير إلى الغريض أن يسكت حين غناه بشعر كثير\n(وإني لأرعى قومها من جلالها ... )\nوما السبب في ذلك فقال أبو عبد الله أنا أحدثكه","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":8,"spl":"الغريض يغني عبد الملك في مكة — قصة اختلاف عبد الملك مع زوجته عاتكلة","partial":1},
{"id":"b14-20","bab":"الجزء 2","sec":"قصة اختلاف عبد الملك مع زوجته عاتكلة","page":"ج2 ص376","text":"حدثني أبي قال كان عبد الملك بن مروان من أشد الناس حبا لعاتكه امرأته وهي ابنة يزيد بن معاوية وأمها أم كلثوم بنت عبد الله بن عامر بن كريز وهي أم يزيد بن عبد الملك فغضبت مرة على عبد الملك وكان بينهما باب\nفحجبته واغلقت ذلك الباب فشق غضبها على عبد الملك وشكا إلى رجل من خاصته يقال له عمر بن بلال الأسدي فقال له مالي عندك إن رضيت قال حكمك فأتى عمر بابها وجعل يتباكى وأرسل إليها بالسلام فخرجت إليه حاضنتها ومواليها وجواريها فقلن مالك قال فزعت إلى عاتكه ورجوتها فقد علمت مكاني من أمير المؤمنين معاوية ومن أبيها بعده قلن ومالك قال ابناي لم يكن لي غيرهما فقتل أحدهما صاحبه فقال أمير المؤمنين أنا قاتل الآخر به فقلت أنا الولي وقد عفوت قال لا أعود الناس هذه العادة فرجوت أن ينجي الله ابني هذا على يدها فدخلن عليها فذكرن ذلك لها فقالت وكيف أصنع مع غضبي عليه وما أظهرت له قلن إذا والله يقتل فلم يزلن حتى دعت بثيابها فأجمرتها ثم خرجت نحو الباب فأقبل حديج الخصي قال يا أمير المؤمنين هذه عاتكة قد أقبلت قال ويلك ما تقول قال قد والله طلعت فأقبلت وسلمت فلم يرد عليها فقالت أما والله لولا عمر ما جئت إن أحد أبنية تعدى على الآخر فقتله فأردت قتل الأخر وهو الولي وقد عفا قال إني أكره أن أعود الناس هذه العادة قالت أنشدك الله يا أمير المؤمنين فقد عرفت مكانه من أمير المؤمنين معاوية ومن أمير المؤمنين يزيد وهو ببابي فلم تزل به حتى أخذت برجله فقبلتها فقال هو لك ولم يبرحا حتى اصطلحا ثم راح عمر بن بلال إلى عبد الملك فقال يا لأمير المؤمنين كيف رأيت قال رأينا أثرك فهات حاجتك قال مزرعة بعدتها وما فيها وألف دينار وفرائض لولدي وأهل بيتي وعيالي قال ذلك لك ثم اندفع عبد الملك يتمثل بشعر كثير\n(وإني لأرعى قومها من جلالها ... )\nالبيتين فعلمت عاتكة ما أراد فلما غني يزيد بهذا الشعر كرهته مواليه إذ كان عبد الملك تمثل به في أمه ولم يكرهه يزيد وقال لو قيل هذا الشعر فيها ثم\nغني به لما كان عيبا فكيف وإنما هو مثل تمثل به أمير المؤمنين في اجمل العالمين قال أبو عبد الله وأما خبره لما غنى بشعر عمرو بن شأس فإن ابن الأشعث لما قتل بعث الحجاج إلى عبد الملك برأسه مع عرار بن عمرو بن شأس فلما ورد به وأوصل كتاب الحجاج جعل عبد الملك يقرأه فكلما شك في شيء سأل عرارا عنه فأخبره فعجب عبد الملك من بيانه وفصاحته مع سواده فقال متمثلا\n(وإن عرارا إن يكن غير واضح ... فإني أحب الجون ذا المنكب العمم)\nضحك عرار من قوله ضحكا غاظ عبد الملك فقال له مم ضحكت ويلك قال أتعرف عرارا يا أمير المؤمنين الذي قيل فيه هذا الشعر قال لا قال فأنا والله هو فضحك عبد الملك وقال حظ وافق كلمة ثم أحسن جائزته وسرحه قال أبو عبد الله وإنما أراد الغريض أن يغني يزيد بمتمثلات عبد الملك في الأمور العظام فلما تبين كراهة مواليه غناءه فيما تمثل به في عاتكة أراد أن يعقبه ما تمثل به في فتح عظيم كان لعبد الملك فغناه بشعر عمرو بن شأس في عرار","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":8,"spl":"الغريض يغني عبد الملك في مكة — قصة اختلاف عبد الملك مع زوجته عاتكلة","partialRef":{"sid":"b14-19","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b14-21","bab":"الجزء 2","sec":"نسبة ما في هذا الخبر من الغناء","page":"ج2 ص378","text":"صوت\n(و إني لأرعى قومها من جلالها ... وإن أظهروا غشا نصحت لهم جهدي)\n(ولو حاربوا قومي لكنت لقومها ... )\n(صديقا ولم أحمل على قومها حقدي ... )\nروضه - من الطويل - الشعر لكثير والغناء للغريض ثاني ثقيل بالسبابة في مجرى البنصر عن إسحاق وذكر حبش أن فيه لقفا النجار ثاني ثقيل بالوسطى وفيه لعلويه ثقيل أول","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":9,"spl":"نسبة ما في هذا الخبر من الغناء — للغريض ولم تذكر طريقته","partialRef":{"sid":"b14-19","gi":0,"vi":1,"side":1},"partial":1},
{"id":"b14-22","bab":"الجزء 2","sec":"الغريض ومعبد","page":"ج2 ص378","text":"وأخبرني الحسين بن يحيى عن حماد عن أبيه قال حدثني إبراهيم عن يونس الكاتب قال حدثني معبد قال خرجت إلى مكة في طلب لقاء الغريض وقد بلغني حسن غنائه في لحنه\n(وما أنس م الأشياء لا أنس شادنا ... بمكة مكحولا أسيلا مدامعه)\nقد كان بلغني أنه أول لحن صنعه وان الجن نهته أن يغنيه لأنه فتن طائفة منهم فانتقلوا عن مكة من اجل حسنه فلما قدمت مكة سألت عنه فدللت على منزله فأتيته فقرعت الباب فما كلمني أحد فسألت بعض الجيران فقلت هل في الدار أحد قالوا لي نعم فيها الغريض فقلت إني قد أكثرت دق الباب فما أجابني أحد قالوا إن الغريض هناك فرجعت فدققت الباب فلم يجبنى أحد فقلت إن نفعني غنائى يوما نفعنى اليوم فاندفعت فغنيت لحني في شعر جميل\n(علقت الهوى منها وليدا فلم يزل ... إلى اليوم ينمي حبها ويزيد)\nو الله ما سمعت حركة الباب فقلت بطل سحري وضاع سفري وجئت أطلب ما هو عسير علي واحتقرت نفسي وقلت لم يتوهمني لضعف غنائي عنده فما شعرت إلابصائح يصيح يا معبد المغني افهم وتلق عني شعر جميل الذي تغني فيه يا شقي البخت وغنى صوت","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":9,"spl":"نسبة ما في هذا الخبر من الغناء — للغريض ولم تذكر طريقته"},
{"id":"b14-23","bab":"الجزء 2","sec":"للغريض ولم تذكر طريقته","page":"ج2 ص379","text":"(وما أنس م الأشياء لا أنس قولها ... وقد قربت نضوي أمصر تريد)\n(ولا قولها لولا العيون التي ترى ... أتيتك فاعذرني فدتك جدود)\n(خليلي ما أخفي من الوجد باطن ... ودمعي بما قلت الغداة شهيد)\n(يقولون جاهد يا جميل بغزوة ... وأي جهاد غيرهن أريد)\n(لكل حديث عندهن بشاشة ... وكل قتيل بينهن شهيد)\nروضه - من الطويل - قال فلقد سمعت شيئا لم أسمع أحس منه وقصر إلي نفسي وعلمت فضيلته علي بما أحسن من نفسه وقلت إنه لحري بالاستتار من الناس تنزيها لنفسه وتعظيما لقدره وإن مثله لا يستحق الابتذال ولا أن تتداوله الرجال فأردت الانصراف إلى المدينة راجعا فلما كنت غير بعيد إذا بصائح يصيح بي يا معبد انتظر أكلمك فرجعت فقال لي إن الغريض يدعوك فأسرعت فرحا فدنوت من الباب فقال لي أتحب الدخول فقلت وهل إلى ذلك من سبيل فقرع الباب ففتح فقال لي ادخل ولا تطل الجلوس فدخلت فإذا شمس طالعة في بيت فسلمت فرد السلام ثم قال اجلس فجلست فإذا أنبل الناس وأحسنهم وجها وخلقا وخلقا فقال يا معبد كيف طرأت إلى مكة فقلت جعلت فداءك وكيف عرفتني فقال بصوتك فقلت وكيف وأنت لم تسمعه قط قال لما غنيت عرفتك به وقلت إن كان معبد في الدنيا فهذا فقلت جعلت فداءك فكيف أجبتني بقولك\n(وما أنس م الأشياء لا أنس قولها ... وقد قربت نضوي أمصر تريد)\nقال قد علمت أنك تريد أن أسمعك صوتي\n(وما أنس م الأشياء لا أنس شادنا ... بمكة مكحولا أسيلا مدامعه)\nلم يكن إلى ذلك سبيل لأنه صوت قد نهيت أن أغنيه فغنيتك هذا الصوت\nجوابا لما سألت وغنيت فقلت والله ما عدوت ما أردت فهل لك حاجة فقال لي يا أبا عباد لولا ملالة الحديث وثقل إطالة الجلوس لاستكثرت منك فاعذر فخرجت من عنده وإنه لأجل الناس عندي ورجعت إلى المدينة فتحدثت بحديثه وعجبت من فطنته وقيافته فما رأيت إنسانا إلا وهو أجل منه في عيني وذكرت جميلا وبثينة فقلت ليتني عرفت إنسانا يحدثني بقصة جميل وخبر الشعر فأكون قد أخذت بفضيلة الأمر كله في الغناء والشعر","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":9,"spl":"نسبة ما في هذا الخبر من الغناء — للغريض ولم تذكر طريقته"}]);
window.__BOOK__['p01'].push([{"id":"b14-24","bab":"الجزء 2","sec":"خبر لقاء جميل وبثينة","page":"ج2 ص381","text":"فسألت عن ذلك فإذا الحديث مشهور وقيل لي إن أردت أن تخبر بمشاهدته فأت بني حنظلة فإن فيهم شيخا منهم يقال له فلان يخبرك الخبر فأتيت الشيخ فسألته فقال نعم بينا أنا في الربيع إذا أنا برجل منطو على رحله كأنه جان فسلم علي ثم قال ممن أنت يا عبد الله فقلت أحد بني حنظلة قال فانتسب فانتسبت حتى بلغت إلى فخذي الذي أنا منه ثم سألني عن بني عذرة أين نزلوا فقلت له هل ترى ذلك السفح فإنهم نزلوا من ورائه قال يا أخا بني حنظلة هل لك في خير تصطنعه إلي فو الله لو أعطيتني ما أصبحت تسوق من هذه الإبل ما كنت بأشكر مني لك عليه فقلت نعم ومن أنت أولا قال لا تسألني من أنا ولا أخبرك غير أني رجل بيني وبين هؤلاء القوم مايكون بين بني العم فإن رأيت أن تأتيهم فإنك تجد القوم في مجلسهم فتنشدهم بكرة أدماء تجر خفيها غفلا من السمعة فإن ذكروا لك شيئا فذاك وإلا استأذنتهم في\nالبيوت وقلت إن المرأة والصبي قد يريان ما لايرى الرجال فتنشدهم ولا تدع أحد تصيبه عينك ولا بيتا من بيوتهم إلا نشدتها فيه فأتيت القوم فإذا هم على جزور يقتسمونها فسلمت وانتسبت لهم ونشدتهم ضالتي فلم يذكروا لي شيئا فاسستأذنتهم في البيوت وقلت إن الصبي والمرأة يريان ما لاترى الرجال فأذنوا فأتيت أقصاها بيتا ثم استقريتها بيتا بيتا أنشدهم فلا يذكرون شيئا حتى إذا انتصف النهار وآذاني حر الشمس وعطشت وفرغت من البيوت وذهبت لأنصرف حانت مني التفاته فإذا بثلاثة أبيات فقلت ما عند هؤلاء إلا ما عند غيرهم ثم قلت لنفسي سوءة وثق بي رجل وزعم أن حاجته تعدل مالي ثم آتيه فأقول عجزت عن ثلاثة أبيات فأنصرفت عامدا إلى أعظمها بيتا فإذا هو قد أرخي مؤخره ومقدمه فسلمت فرد علي السلام وذكرت ضالتي فقالت جارية مهنم يا عبد الله قد أصبت ضالتك وما أظنك إلا قد اشتد عليك الحر واشتهيت الشراب قلت أجل قالت ادخل فدخلت فأتتني بصحفه فيها تمر من تمر هجر وقدح فيه لبن والصحفه مصرية مفضضة والقدح مفضض لم أر إناء قط أحسن منه فقالت دونك فتجمعت وشربت من اللبن حتى رويت ثم قلت يا أمة الله والله ما أتيت اليوم أكرم منك ولا أحق بالفضل فهل ذكرت من ضالتي شيئا فقالت هل ترى هذه الشجرة فوق الشرف قلت نعم قالت فإن الشمس غربت أمس وهي تطيف حولها ثم حال الليل بيني وبينها فقمت وجزيتها الخير وقلت والله لقد تغذيت ورويت فخرجت حتى أتيت الشجرة فأطفت بها فو الله ما رأيت من أثر فأتيت صاحبي فإذا هو متشح في الإبل بكسائه ورافع عقيرته يغني قلت\nالسلام عليك قال وعليك السلام ما وراءك قلت ما ورائي من شيء قال لا عليك فأخبرني بما فعلت فاقتصصت عليه القصة حتى انتهيت إلى ذكر المرأة وأخبرته بالذي صنعت فقال قد أصبت طلبتك فعجبت من قوله وأنا لم أجد شيئا ثم سألني عن صفة الإناءين الصحفة والقدح فوصفتهما له فتنفس الصعداء وقال قد أصبت طلبتك ويحك ثم ذكرت له الشجرة وأنها رأتها تطيف بها فقال حسبك فمكثت حتى إذا أوت إبلى إلى مباركها دعوته إلى العشاء فلم يدن منه وجلس مني بمزجر الكلب فلما ظن أني قد نمت رمقته فقام إلى عيبة له فاستخرج منها بردين فأتزر بأحدهما وتردى بالآخر ثم انطلق عامدا نحو الشجرة واستبطنت الوادي فجعلت أخفي نفسي حتى إذا خفت أن يراني انبطحت فلم أزل كذلك حتى سبقته إلى شجرات قريب من تلك الشجرة بحيث أسمع كلامهما فاستترت بهن وإذا صاحبته عند الشجرة فأقبل حتى كان منها غير بعيد فقالت اجلس فو الله لكأنه لصق بالأرض فسلم عليها وسألها عن حالها أكرم سؤال سمعت به قط وأبعده من كل ربية وسألته مثل مسالته ثم أمرت جارية معها فقربت إليه طعاما فلما أكل وفرغ قالت أنشدني ما قلت فأنشدها\n(علقت الهوى منها وليدا فلم يزل ... إلى اليوم ينمي حبها ويزيد)\nلم يزالا يتحدثان ما يقولان فحشا ولا هجرا حتى التفتت التفاتة فنظرت إلى الصبح فودع كل واحد منهما صاحبه أحسن وداع ما سمعت به قط ثم انصرفا فقمت فمضيت إلى إبلي فاضطجعت وكل واحد منهما يمشي خطوة ثم يلتفت إلى صاحبه فجاء بعدما أصبحنا فرفع برديه ثم قال يا أخا بني تميم حتى متى تنام فقمت وتوضأت وصليت وحلبت إبلي وأعانني عليها وهو أظهر الناس سرورا ثم","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":10,"spl":"خبر لقاء جميل وبثينة"},
{"id":"b14-25","bab":"الجزء 2","sec":"خبر لقاء جميل وبثينة","page":"ج2 ص381","text":"دعوته إلى الغداء فتغدى ثم قام إلى عيبته فافتتحها فإذا فيها سلاح وبردان مما كسته الملوك فأعطاني أحدهما وقال أما والله لو كان معي شيء ما ذخرته عنك وحدثني حديثه وانتسب لي فإذا هو جميل بن معمر والمرأة بثينة وقال لي إني قد قلت أبياتا في منصرفي من عندها فهل لك إن رأيتها أن تنشدها قلت نعم فأنشدني\n(وما أنس م الأشياء لا أنس قولها ... وقد قربت نضوي أمصر تريد)\nلأبيات ثم ودعني وأنصرف فمكث حتى أخذت الإبل مراتعها ثم عمدت إلى دهن كان معي فدهنت به رأسي ثم ارتديت بالبرد وأتيت المرأة فقلت السلام عليكم إني جئت أمس طالبا واليوم زائرا أفتأذنون قالت نعم فسمعت جويزيه تقول لها يا بثينة عليه والله برد جميل فجعلت اثني على ضيفي وأذكر فضله وقلت إنه ذكرك فاحسن الذكر فهل أنت بارزة لي حتى أنظر إليك قالت نعم فلبست ثيابها ثم برزت ودعت لي بطرف ثم قالت يا أخا بني تميم والله ما ثوباك هذان بمشتبهين ودعت بعيبتها فأخرجت لي ملحفة مروية مشبعة من العصفر ثم قالت أقسمت عليك لتقومن إلى كسر البيت ولتخلعن مدرعتك ثم لتأتزرن بهذه الملحفة فهي أشبه ببردك ففعلت ذلك وأخذت مدرعتي بيدي فجعلتها إلى جانبي وأنشدتها الأبيات فدمعت عيناها وتحدثنا طويلا من النهار ثم انصرفت إلى إبلي بملحفة بثينة وبرد جميل ونظرة من بثينة\nقال معبد فجزيت الشيخ خيرا وانصرفت من عنده وأنا والله أحسن الناس حالا بنظرة من الغريض واستماع لغنائه وعلم بحديث جميل وبثينة فيما غنيت أنا به وفيما غنى به الغريض على حق ذلك وصدقه فما رأيت ولا سمعت بزوجين قط احسن من جميل وبثينة ومن الغريض ومني","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":11,"spl":"خبر لقاء جميل وبثينة — نسبة هذه الأصوات التي ذكرت في هذا الخير"},
{"id":"b14-26","bab":"الجزء 2","sec":"نسبة هذه الأصوات التي ذكرت في هذا الخير","page":"ج2 ص385","text":"وهي كلها من قصيدة واحدة منها صوت\n(علقت الهوى منها وليدا فلم يزل ... إلى اليوم ينمي حبها ويزيد)\n(وأفنيت عمري في انتظاري نوالها ... وأفنت بذاك الدهر وهو جديد)\n(فلا أنا مردود بما جئت طالبا ... ولا حبها فيما يبيد يبيد)\n(وما أنس م الأشياء لا أنس قولها ... وقد قربت نضوي أمصر تريد)\n(ولا قولها لولا العيون التي ترى ... لزرتك فاعذرني فدتك جدود)\n(إذا قلت ما بي يا بثينة قاتلي ... من الحب قالت ثابت ويزيد)\n(وإن قلت ردي بعض عقلي اعش به ... تولت وقالت ذاك منك بعيد)\nروضه - من الطويل - الشعر لجميل بن معمر والغناء لمعبد في الأول والثاني والثالث والسادس والسابع ولحنه ثقيل أول بالسبابة في مجرى الوسطى عن إسحاق وعمرو بن بانه وذكر عمرو والهشامي أن فيه ثقيلا أول آخر للهذلي وأن فيه خفيف ثقيل ينسب إلى معبد وإلى الغريض وإلى إبراهيم أوله وما أنس م الأشياء وفي الأربعة الابيات الأول ثاني ثقيل بالبنصر لابن أبي قباحة ولإسحاق في الثالث والسادس ثاني ثقيل آخر بالوسطى عن الهشامي وأول هذه القصيدة فيه غناء أيضا وهو موصول بأبيات أخر\nصوت\n(ألا ليت ريعان الشباب جديد ... ودهرا تولى يا بثين يعود)\n(فنغنى كما كنا نكون وأنتم ... قريب وما قد تبذلين زهيد)\n(ألا ليت شعري هل أبيتن ليلة ... بوادي القرى إني إذا لسعيد)\n(وهل ألقين سعدى من الدهر ليلة ... ومارث من حبل الصفاء جديد)\n(فقد تلتقي الأهواء بعد تفاوت ... وقد تطلب الحاجات وهي بعيد)\nي البيتين الأولين خفيف ثقيل مطلق في مجرى البنصر ذكر حبش أنه لإسحاق وليس يشبه أن يكون له وفي الثالث وما بعده لابن سريج ثاني ثقيل بالبنصر عن حبش أيضا أخبرني إسماعيل بن يونس إجازة قال حدثنا عمر بن شبة قال حدثني أبو غسان قال حدثني الوليد بن هشام عن محمد بن معن عن خالد بن سلمة المخزومي قال خرجت مع أعمامي وأنا على نجيب ومعنا شيخ فلما أسحرنا قال لي أعمامي انزل عن نجيبك واحمل عليه هذا الشيخ واركب جملة ففعلت فإذا الشيخ قد أخرج عودا له من غلاف ثم ضرب به وغنى\n(هاج الغريض الذكر ... لما غدوا فانشمروا)\nقلت لبعض أصحابنا من هذا قال الغريض","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":11,"spl":"خبر لقاء جميل وبثينة — نسبة هذه الأصوات التي ذكرت في هذا الخير"},
{"id":"b14-27","bab":"الجزء 2","sec":"نسبة هذا الصوت","page":"ج2 ص387","text":"صوت\n(هاج الغريض الذكر ... لما غدوا فانشمروا)\n(علىبغال شحج ... قد ضمهن السفر)\n(فيهن هند ليتني ... ما عمرت أعمر)\n(حتىإذاماجاءها ... حتف أتاني القدر)\nروضه من الرجز الذي قال عمر\n(هاج القريض الذكر ... )\nبالقاف فجعله الغريض لما غني فيه الغريض يعني نفسه الشعر لعمربن أبي ربيعة والغناء لابن سريج ذكر يونس أن له فيه لحنين وذكر إسحاق أن أحدهما رمل مطلق في مجرى البنصر ولم يذكر الآخر وذكر الهشامي أن الآخر خفيف رمل وفيه للغريض ثقيل أول بالبنصر وقيل إنه لحن ابن سريج وإن خفيف الرمل للغريض وأول هذا الصوت في كتاب يونس\n(هاج فؤادي محضر ... بذي عكاظ مقفر)\n(حتى إذا ما وازنوا المروة ... حين ائتمروا)\n(قيل انزلوا فعرسوا ... من ليلكم وانشمروا)\n(وقولها لأختها ... أمطمئن عمر)","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":12,"spl":"نسبة هذا الصوت — رأي نصيب في عمر وجميل وكثير","partialRef":{"sid":"b2-73","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b14-28","bab":"الجزء 2","sec":"الغريض يغني الوليد في مكة","page":"ج2 ص388","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه قال وذكر السعدي أن الوليد بن عبد الملك قدم مكة فأراد أن يأتي الطائف فقال هل من رجل عالم يخبرني عنها فقالوا عمر بن أبي ربيعة قال لا حاجة لي به ثم عاد فسأل فذكروه ثم عاد فذكروه فقال هاتوه وركب معه فجعل يحدثه ثم حول عمر رداءه ليصلحه على نفسه فرأى الوليد على ظهره أثرا فقال ما هذا الأثر قال كنت عند جارية لي إذ جاءتني جارية برسالة من عند جارية أخرى وجعلت تسارني بها فغارت التي كنت عندها فعضت منكبي فما وجدت ألم عضتها من لذة ما كانت تلك تنفث في أذني حتى بلغت ماترى والوليد يضحك فلما رجع عمر قيل له ما الذي كنت تضحك به أمير المؤمنين قال ما زلنا في حديث الزنا حتى رجع وكان قد حمل الغريض معه فقال له يا أمير المؤمنين إن عندي أجمل الناس وجها وأحسنهم حديثا فهل لك أن تسمعه قال هاته فدعا به فقال أسمع أمير المؤمنين أحسن شيء قلته فاندفع يغني بشعر عمر ومن الناس من يرويه لجميل صوت\n(إني لأحفظ سركم ويسرني ... لو تعلمين بصالح أن تذكري)\n(ويكون يوم لا أرى لك مرسلا ... أو نلتقي فيه علي كأشهر)\n(يا ليتني ألقى المنية بغتة ... إن كان يوم لقائكم لم يقدر)\n(ما كنت والوعد الذي تعدينني ... إلا كبرق سحابة لم تمطر)\n(تقضي الديون وليس ينجز عاجلا ... هذا الغريم لنا وليس بمعسر)\nروضه من الكامل وذكر حبش أن الغناء للغريض ولحنه ثقيل أول\nبالبنصرقال فاشتد سرور الوليد بذلك وقال له ياعمر هذه رقيتك ووصله وكساه وقضى حوائجه","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":12,"spl":"نسبة هذا الصوت — رأي نصيب في عمر وجميل وكثير"},
{"id":"b14-29","bab":"الجزء 2","sec":"رأي نصيب في عمر وجميل وكثير","page":"ج2 ص389","text":"أخبرني الحسن بن علي الخفاف قال حدثنا الحارث بن محمد عن المدائني عن عوانة قال حدثني رجل من أهل الكوفة قال قدم نصيب الكوفة فأرسلني أبي إليه وكان له صديقا فقال أقرئه مني السلام وقال له إن رأيت أن تهدي لنا شيئا مما قلت فأتيته في يوم جمعة وهو يصلي فلما فرغ أقرأته السلام وقلت له فقال قد علم أبوك أني لا أنشد في يوم الجمعة ولكن تلقاني في غيره فأبلغ ما تحب فلما خرجت وانتهيت إلى الباب رددت إليه فقال أتروي شيئا من الشعر قلت نعم قال فأنشدني فأنشدته قول جميل\n(إني لأحفظ غيبكم ويسرني ... لو تعلمين بصالح أن تذكري)\nلأبيات المتقدمة فقال نصيب أمسك أمسك لله دره ما قال أحد إلادون ما قال ولقد نحت للناس مثالا يحتدون عليه ثم قال أما أصدقنا في شعره فجميل وأما أوصفنا لربات الحجال فكثير وأما أكذبنا فعمر بن أبي ربيعة وأما أنا فأقول ما أعرف وقال هارون بن محمد الزيات حدثني حماد بن إسحاق عن أبيه أن الغريض سمع أصوات رهبان بالليل في دير لهم فاستحسنها فقال له بعض من معه يا أبا يزيد صغ على مثل هذا الصوت لحنا فصاغ مثله في لحنه\n(يا أم بكر حبك البادي ... لا تصرميني إنني غادي)\nفما سمع بأحسن منه","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":12,"spl":"نسبة هذا الصوت — رأي نصيب في عمر وجميل وكثير"},
{"id":"b14-30","bab":"الجزء 2","sec":"نسبة هذا الصوت","page":"ج2 ص390","text":"صوت\n(يا أم بكر حبك البادي ... لا تصرميني إنني غادي)\n(جد الرحيل وحثني صحبي ... وأريد إمتاعا من الزاد)\nروضه من مزاحف - الكامل - الشعر لسعيد بن عبد الرحمن بن حسان بن ثابت الأنصاري والغناء للغريض خفيف ثقيل أول بالوسطى وفيه لابن المكي ثاني ثقيل بالوسطى عن حبش وفيه لإبراهيم بن أبي الهيثم خرج وأخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة عن أيوب بن عباية عن عمرو بن عقبة وكان يعرف بابن الماشطة قال خرجت أنا وأصحاب لي فيهم إبراهيم بن أبي الهيثم إلى العقيق ومعنا رجل ناسك كنا نحتشم منه وكان محموما نائما وأحببنا أن نسمع من معنا من المغنين ونحن نهابه ونحتشمه فقلت له إن فينا رجلا ينشد الشعر فيحسن ونحن نحب أن نسمعه ولكنا نهابك قال فما علي منكم أنا محموم نائم فاصنعوا ما بدا لكم فاندفع إبراهيم بن أبي الهيثم فغنى\n(يا أم بكر حبك البادي ... لا تصرميني إنني غادي)\n(جد الرحيل وحثني صحبي ... وأريد إمتاعا من الزاد)\nفأجاده وأحسنه قال فوثب الناسك فجعل يرقص ويصيح أريد إمتاعا من الزاد والله أريد إمتاعا من الزاد ثم كشف عن أيره وقال أنا أنيك أم الحمى قال يقول لي ابن الماشطة اعتقت ما أملك إن كان ناك أم الحمى أحد قبله أخبرني به الحسين بن يحيى عن حماد عن أبيه عن أيوب فذكر الخبر ولم يذكر فيه كشف الناسك عن سوءته وما قاله بعد ذلك","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":13,"spl":"نسبة هذا الصوت"},
{"id":"b14-31","bab":"الجزء 2","sec":"وفاة الغريض","page":"ج2 ص391","text":"وكانت وفاة الغريض في أيام سليمان بن عبد الملك أو عمر بن عبد العزيز لم يتجاوزها والأشبة أنه مات في خلافة سليمان لأن الوليد كان ولي نافع بن علقمة مكة فهرب منه الغريض وأقام باليمن واستوطنها مدة ثم مات بها وأخبرني بخبره الحسين بن يحيى عن حماد عن أبيه عن المسيبى قال أخبرني بعض المخزوميين ايضا بخبره وأخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثني أبو غسان أن نافع بن علقمة لما ولي مكة خافه الغريض وكان كثيرا ما يطلبه فلم يجئه فهرب منه واستخفى في بعض منازل اخوانه قال فحدثني رجل من أهل مكة كان يخدمه أنه دفع إليه يوما ربعة له وقال له صر بها إلى فلان العطار يملؤها لي طيبا قال فصرت بها إليه فلقيني نافع بن علقمة فقال هذه ربعة\nالغريض والله فلم أقدر أن أكتمه فقلت نعم قال ما قصته فأخبرته الخبر فضحك وقال سر معي إلى المنزل ففعلت فملأها طيبا وأعطاني دنانير وقال أعطه وقل له يظهر فلا بأس عليه فسرت إليه مسرورا فأخبرته بذلك فجزع وقال الآن ينبغي أن أهرب إنما هذه حيلة احتالها علي لأقع في يده ثم خرج من وقته إلى اليمن فكان آخر العهد به قال إسحاق فحدثني هذا المخزومي أن الغريض لما صار إلى اليمن وأقام به اجتزنا به في بعض أسفارنا قال فلما رآني بكى فقلت له ما يبكيك قال بأبي أنت وأمي وكيف يطيب لي أن أعيش بين قوم يرونني أحمل عودي فيقولون لي يا هناه أتبيع آخرة الرحل فقلت له فارجع إلى مكة ففيها أهلك فقال يابن أخي إنما كنت أستلذ مكة وأعيش بها مع أبيك ونحوه وقد أوطنت هذا المكان ولست تاركه ما عشت قلنا له فغننا بشيء من غنائك فتأبى ثم أقسمنا عليه فأجاب وعمدنا إلى شاة فذبحناها وخرطنا من مصرانها أوتارا فشدها على عوده واندفع فغنى في شعر زهير\n(جرى دمعي فهيج لي شجونا ... فقلبي يستجن به جنونا)\nفما سمعنا شيئا أحسن منه فقلنا له ارجع إلى مكة فكل من بها يشتاقك ولم نزل نرغبه في ذلك حتى أجاب إليه ومضينا لحاجتنا ثم عدنا فوجدناه عليلا فقلنا ما قصتك قال جاءني منذ ليال قوم وقد كنت أغني في الليل فقالوا غننا فأنكرتهم وخفتهم فجعلت أغنيهم فقال لي بعضهم غنني\n(لقد حثوا الجمال ليهربوا ... منا فلم يئلوا)\nففعلت فقام إلي هن منهم أزب فقال لي أحسنت والله ودق رأسي حتى سقطت لا أدري أين أنا فأقمت بعد ثالثة وأنا عليل كما ترى ولا أراني إلا سأموت قال فأقمنا عنده بقية يومنا ومات من غد فدفناه وانصرفنا أخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة عن أبي غسان قال زعم المكيون أن الغريض خرج إلى بلاد عك فغنى ليلا\n(هم ركب لقوا ركبا ... كما قد تجمع السبل)\nفصاح به صائح اكفف يا أبا مروان فقد سفهت حلماءنا وأصبيت سفهاءنا قال فأصبح ميتا أخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة قال حدثني محمد بن الخطاب قال حدثنا رجل من آل أبي قبيل يقال له محرز عن أبي قبيل قال رأيت الغريض وقال إسحاق في خبره المذكور حدثني محمد بن سلام عن أبي قبيل وهو مولى لآل الغريض قال شهدت مجمعا لآل الغريض إما عروسا أو ختانا فقيل له تغن فقال هو ابن زانية إن فعل فقال له بعض مواليه فأنت والله كذلك قال أو كذلك أناقال نعم قال أنت أعلم بي والله ثم أخذ الدف فرمى به وتمشى مشية لم أر أحسن منها ثم تغنى\n(تشرب لون الرازقي بياضه ... أو الزعفران خالط المسك رادعه)\nفجعل يغنيه مقبلا ومدبرا حتى التوت عنقه وخر صريعا وما رفعناه إلا ميتا وظننا أن فالجا عاجله قال إسحاق وحدثني ابن الكلبي عن أبي مسكين قال إنما نهته الجن أن يتغنى بهذا الصوت فلما أغضبه مواليه تغناه فقتلته الجن في ذلك","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":14,"spl":"وفاة الغريض — نسبة هذه الأصوات"},
{"id":"b14-32","bab":"الجزء 2","sec":"نسبة هذه الأصوات","page":"ج2 ص393","text":"صوت منها\n(جرى دمعي فهيج لي شجونا ... فقلبي يستجن به جنونا)\n(أأبكي للفراق وكل حي ... سيبكي حين يفتقد القرينا)\n(فإن تصبح طليحة فارقتني ... ببين فالرزية أن تبينا)\n(فقد بانت بكرهي يوم بانت ... مفارقة وكنت بها ضنينا)\nلشعر لزهير والغناء للغريض عن حبش وقيل إنه لدحمان وفيه لأبي الورد خفيف رمل بالوسطى عن حبش والهشامي انقضت أخبار الغريض ومنها صوت","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":14,"spl":"وفاة الغريض — نسبة هذه الأصوات"},
{"id":"b14-33","bab":"الجزء 2","sec":"من المائة المختارة في رواية جحظة","page":"ج2 ص394","text":"(لقد حثوا الجمال ليهربوا ... منا فلم يئلوا)\n(على آثارهن مقلص ... السربال معتمل)\n(وفيهم قلبك المتبول ... بالحسناء مختبل)\n(مخففة بحمل حمائل ... الديباج والحلل)\n(أسائل عاصما في السر ... أين تراهم نزلوا)\n(فقال هم قريب منك ... لو نفعوك إذ رحلوا)\nلشعر للحكم بن عبدل الأسدي والغناء في اللحن المختار للغريض ولحنه خفيف ثقيل أول بإطلاق الوتر في مجرى الوسطى في الأول والثاني من الأبيات وذكر الهشامي أن فيهما لحنا لمعبد من الثقيل الأول وفي الثالث وما بعده من الأبيات لابن سريج رمل بالسبابة في مجرى الوسطى عن إسحاق وفيها لإبراهيم ثقيل أول بالوسطى عن حبش وذكر أحمد بن عبيد أن الذي صح فيه أربعة ألحان منها لحنان في خفيف الثقيل للغريض ومالك ولحنان في الرمل لابن سريج ومخارق وذكر ابن الكلبي أن فيها لعريب رملا ثالثا وذكر حبش أن فيها لابن سريج خفيف رمل بالبنصر ولابن مسجح رملا بالبنصر ولابن سريج ثاني ثقيل بالبنصر هذه الألحان كلها في لقد حثوا والذي بعده","topic":"ذكر الغريض وأخباره","topicNo":14,"sp":15,"spl":"من المائة المختارة في رواية جحظة"},
{"id":"b15-2","bab":"الجزء 2","sec":"أخبار الحكم بن عبدل ونسبه — الأعمى الذي لا يرد طلبه","page":"ج2 ص394 – ج2 ص396","text":"هو الحكم بن عبدل بن جبلة بن عمرو بن ثعلبة بن عقال بن بلال بن سعد بن حبال بن نصر بن غاضرة بن مالك بن ثعلبة بن دودان بن أسد بن خزيمة شاعر مجيد مقدم في طبقته هجاء خبيث اللسان من شعراء الدولة الأموية وكان أعرج أحدب ومنزله ومنشؤه الكوفة\nأخبرني محمد بن عبيد الله بن عمار قال حدثني يعقوب بن إسرائيل قال حدثنا محمد بن إدريس القيسي بواسط قال حدثنا العتبي قال كان الحكم بن عبدل الأسدي أعرج لا تفارقه العصا فترك الوقوف بأبواب الملوك وكان يكتب على عصاه حاجته ويبعث بها مع رسله فلا يحبس له رسول ولا تؤخر له حاجة فقال في ذلك يحيى بن نوفل\n(عصا حكم في الدار أول داخل ... ونحن على الأبواب نقصى ونحجب)\n(وكانت عصا موسى لفرعون آية ... وهذي لعمر الله أدهي وأعجب)\n(تطاع فلا تعصى ويحذر سخطها ... ويرغب في المرضاة منها وترهب)\nقال فشاعت هذه الأبيات بالكوفة وضحك الناس منها فكان ابن عبدل بعد ذلك يقول ليحيى يابن الزانية ما أردت من عصاي حتى صيرتها ضحكة واجتنب أن يكتب عليها كما كان يفعل وكاتب الناس بحوائجه في الرقاع أخبرني عمي قال حدثنا الكراني وأخبرني ابن عمار قال حدثني يعقوب بن\nنعيم قال حدثنا أبو جعفر القرشي قال كان للحكم بن عبدل صديق أعمى يقال له أبو علية وكان ابن عبدل قد أقعد فخرجا ليلة من منزلهما إلى منزل بعض إخوانهما والحكم يحمل وأبو علية يقاد فلقيهما صاحب العسس بالكوفة فأخذهما فحبسهما فلما استقرا في الحبس نظر الحكم إلى عصا أبي علية موضوعة إلى جانب عصاه فضحك وأنشأ يقول\n(حبسي وحبس أبي علية ... من أعاجيب الزمان)\n(أعمى يقاد ومقعدلا ... الرجل منه ولا اليدان)\n(هذا بلا بصر هناك ... وبي يخب الحاملان)\n(يا من رأى ضب الفلاة ... قرين حوت في مكان)\n(طرفي وطرف أبي علية ... دهرنا متوافقان)\n(من يفتخر بجواده ... فجيادنا عكازتان)\n(طرفان لا علفاهما ... يشرى ولا يتصاولان)\n(هبني وإياه الحريق ... أكان يسطع بالدخان)\nال وكان اسم أبي علية يحيى فقال فيه الحكم أيضا\n(أقول ليحيى ليلة الحبس سادرا ... ونومي به نوم الأسير المقيد)\n(أعني علي رعي النجوم ولحظها ... أعنك على تحبير شعر مقصد)\n(ففي حالتينا عبرة وتفكر ... وأعجب شيء حبس أعمى ومقعد)\n(كلانا إذا العكاز فارق كفه ... ينيخ صريعا أو على الوجه يسجد)\n(فعكازة تهدي إلى السبل أكمها ... وأخرى مقام الرجل قامت مع اليد)","topic":"أخبار الحكم بن عبدل ونسبه","topicNo":15,"sp":0,"spl":"أخبار الحكم بن عبدل ونسبه — الأعمى الذي لا يرد طلبه — اجتماع العرجان"},
{"id":"b15-3","bab":"الجزء 2","sec":"اجتماع العرجان","page":"ج2 ص398","text":"أخبرني محمد بن عمران الصيرفي قال حدثنا الحسن بن عليل قال حدثني أحمد بن بكير الأسدي قال حدثني محمد بن أنس السلامي الأسدي عن محمد بن سهل راوية الكميت قال ولي الشرطة بالكوفة رجل أعرج ثم ولي الإمارة آخر أعرج وخرج ابن عبدل وكان أعرج فلقي سائلا اعرج وقد تعرض للأمير يسأله فقال ابن عبدل للسائل\n(ألق العصا ودع التخامع والتمس ... عملا فهذي دولة العرجان)\n(لأميرنا وأمير شرطتنا معا ... يا قومنا لكليهما رجلان)\n(فإذا يكون أميرنا ووزيرنا ... وأنا فإن الرابع الشيطان)\nفبلغت أبياته ذلك الأمير فبعث إليه بمائتي درهم وسأله أن يكف عنه وحدثنيه الأخفش عن عبيد الله اليزيدي عن سليمان بن أبي شيخ عن محمد بن الحكم عن عوانة عن عمر بن عبد العزيز قال ولي عبد الحميد بن عبد الرحمن بن زيد بن الخطاب الكوفة وضم إليه رجل\nمن الأشعريين يقال له سهل وكانا جميعا ين ثم ذكر باقي الحديث مثل حديث يعقوب بن نعيم","topic":"أخبار الحكم بن عبدل ونسبه","topicNo":15,"sp":0,"spl":"أخبار الحكم بن عبدل ونسبه — الأعمى الذي لا يرد طلبه — اجتماع العرجان"},
{"id":"b15-4","bab":"الجزء 2","sec":"الحكم وعبد الملك بن بشر بن مروان","page":"ج2 ص399","text":"أخبرني أحمد بن عبيد الله بن عمار قال حدثني يعقوب بن بشر بن مروان فجعل قعنب بن المحرز الباهلي عن الهيثم الأحمري قال كانت لابن عبدل الأسدي حاجة إلى عبد الملك بن إسرائيل عن يدخل عليه ولا يتهيأ له الكلام حتى جاءه رجل فقال إني رأيت لك رؤيا فقال هاتها فقصها عليه فقال ابن عبد وأنا قد رأيت أيضا قال هات ما رأيت فقال\n(أغفيت قبل الصبح نوم مسهد ... في ساعة ما كنت قبل أنامها)\n(فحبوتني فيما أرى بوليدة ... مغنوجة حسن علي قيامها)\n(وببدرة حملت إلي وبغلة ... شهباء ناجية يصل لجامها)\n(ليت المنابر يابن بشر أصبحت ... ترقى وأنت خطيبها وإمامها)\nفقال له ابن بشر إذا رأيت هذا في اليقظة أتعرفه قال نعم وإنما رأيته قبيل الصبح قال يا غلام ادع فلانا فجاء بوكيله فقال هات فلانة فجاءت فقال أين هذه مما رأيت قال هي هي وإلا فعليه وعليه ثم دعا له ببدرة فقال مثل ذلك وببغلة فركبها وخرج فلقيه قهرمان عبد الملك قال أتبيعها قال نعم قال بكم قال بستمائة قال هي لك فأعطاه ستمائة فقال له أما والله لو أبيت إلا ألفا لأعطيتك قال إياي تندم لو أبيت إلا ستة لبعتك","topic":"أخبار الحكم بن عبدل ونسبه","topicNo":15,"sp":1,"spl":"الحكم وعبد الملك بن بشر بن مروان — الحكم يهجو محمد بن حسان"},
{"id":"b15-5","bab":"الجزء 2","sec":"الحكم يهجو محمد بن حسان","page":"ج2 ص400","text":"أخبرني عمي الحسن بن محمد قال حدثنا الكراني قال حدثنا العمري عن الهيثم عن ابن عياش عن لقيط قال تزوج محمد بن حسان بن سعد التميمي امرأة من ولد قيس بن عاصم وهي ابنة مقاتل بن طلبة بن قيس زوجها إياه رجل منهم يقال له زياد فقال ابن عبدل\n(أباع زياد سود الله وجهه ... عقيلة قوم سادة بالدراهم)\n( وما كان حسان بن سعد ولا ابنه ... أبو المسك من أكفاء قيس بن عاصم ولكنه رد الزمان على استه ... وضيع أمر المحصنات الكرائم خذي دية منه تكن لك عدة ... وجيئي إلى باب الأمير فخاصمي فلو كنت في روح لما قلت خاصمي ... ولكنما ألقيت في سجن عارم\nال فلما بلغ أهلها شعره أنفوا من ذلك فاجتمعوا على محمد بن حسان حتى فارقها قال وكان محمد بن حسان عاملا على بعض كور السواد فسأله ابن عبدل حاجة فرده عنها فقال فيه هذا الشعر وغيره وهجاه هجاء كثيرا أخبرني بهذا الخبر محمد بن عمران الصيرفي قال حدثنا الحسن بن عليل العنزي قال حدثنا أحمد بن بكير الأسدي عن محمد بن بشر السلامي عن محمد بن سهل راوية الكميت فذكر نحوا مما ذكره عمي وزاد فيه قال وكانت المرأة التي تزوجها معاذة بنت مقاتل بن طلبة فلما سمعت ما قال\nحذف\nابن عبدل فيها نشزت على زوجها وهربت إلى أهلها فتوسطوا مابينهما وافتديت منه بمال وفارقها أخبرني عمي قال حدثني الكراني عن العمري عن عطاء عن يحيى بن نصر أبي زكريا قال سمع ابن عبدل الأسدي امرأة وهي تتمشى بالبلاط تتمثل بقوله\n(أعسر أحيانا فتشتد عسرتي ... وأدرك ميسور الغنى ومعي عرضي)\nقال لها ابن عبدل وكان قريبا منها يا أخيا أتعرفين قائل هذا الشعر قالت نعم ابن عبدل الأسدي قال أفتثبيتنه معرفة قالت لا قال فأنا هو وأنا الذي أقول\n(وأنعظ أحيانا فينقد جلده ... وأعذله جهدي فلا ينفع العذل)\n(وأزداد نعظا حين أبصر جارتي ... فأوثقة كيما يثوب له عقل)\n(وربتما لم أدر ما حيلتي له ... إذا هو أذاني وغر به الجهل)\n(فآويته في بطن جاري وجارتي ... مكابرة قدما وإن رغم البعل)\nقالت له المرأة بئس والله الجار للمغيبة أنت فقال إي والله وللتي معها زوجها وأبوها وابنها وأخوها","topic":"أخبار الحكم بن عبدل ونسبه","topicNo":15,"sp":1,"spl":"الحكم وعبد الملك بن بشر بن مروان — الحكم يهجو محمد بن حسان"},
{"id":"b15-6","bab":"الجزء 2","sec":"ابن هبيرة لايخيب أمل الحكم","page":"ج2 ص402","text":"أخبرني محمد بن زكريا الصحاف قال حدثنا قعنب بن المحرز الباهلي قال حدثنا الهيثم بن عدي وأخبرني به حبيب بن نصر المهلبي قال حدثنا عبد الله بن أبي سعد قال حدثني علي بن الحسن قال حدثني أبو خالد الخزاعي الأسلمي عن الهيثم بن عدي عن ابن عياش قال : قدم الحكم بن عبدل الشاعر الكوفي واسطا على ابن هبيره وكان بخيلا فأقبل حتى وقف بين يديه ثم قال\n(أتيتك في أمر من أمر عشيرتي ... وأعيا الأمور المفظعات جسيمها)\n(فإن قلت لي في حاجتي أنا فاعل ... فقد ثلجت نفسي وولت همومها)\nقال أنا فاعل إن اقتصدت فما حاجتك قال غرم لزمني في حمالة قال وكم هي قال أربعة الاف قال نحن مناصفوكها قال أصلح الله الأمير أتخاف علي التخمة إن أتممتها قال أكره أن أعود الناس هذه العادة قال فأعطني جميعها سرا وامنعني جميعها ظاهرا حتى تعود الناس المنع وإلا فالضرر عليك واقع إن عودتهم نصف ما يطلبون فضحك ابن هبيرة قال ما عندنا غير ما بذلناه لك فجثا بين يديه وقال امرأته طالق لاأخذت أقل من أربعة آلاف أو أنصرف وأنا غضبان قال أعطوه إياها قبحه الله فإنه ما علمت حلاف مهين فأخذها وانصرف أخبرني حبيب بن نصرالمهلبي قال حدثنا العنزي قال حدثني محمد بن\nمعاوية الأسدي قال حدثني مشايخنا من بني أسد محمد بن أنس وغيره قالوا","topic":"أخبار الحكم بن عبدل ونسبه","topicNo":15,"sp":2,"spl":"ابن هبيرة لايخيب أمل الحكم — هجاء محمد بن حسان"},
{"id":"b15-7","bab":"الجزء 2","sec":"طاعون الكوفة ورثاء ابن عبدل","page":"ج2 ص402","text":"لما وقع الطاعون بالكوفة أفنى بني غاضرة ومات فيه بنو زر بن حبيش الغاضري صاحب علي بن أبي طالب عليه السلام وكانوا ظرفاء وبنو عم لهم فقال الحكم بن عبدل الغاضري يرثيهم\n(أبعد بني زر وبعد ابن جندل ... وعمرو أرجي لذة العيش في خفض)\n(مضوا وبقينا نأمل العيش بعدهم ... ألا إن من يبقى على إثر من يمضي)\n(فقد كان حولي من جياد وسالم ... كهول مساعير وكل فتى بض)\n(يرى الشح عارا والسماحة رفعة ... أغر كعود البانة الناعم الغض)","topic":"أخبار الحكم بن عبدل ونسبه","topicNo":15,"sp":2,"spl":"ابن هبيرة لايخيب أمل الحكم — هجاء محمد بن حسان"},
{"id":"b15-8","bab":"الجزء 2","sec":"هجاء محمد بن حسان","page":"ج2 ص403","text":"قال أبو الفرج ونسخت من كتاب أبي محلم قال سأل الحكم بن عبدل أخو بني نصر بن قعين محمد بن حسان بن سعد حاجة لرجل سأله مسألته إياها فرده ولم يقضها فقال فيه ابن عبدل\n(رأيت محمدا شرها ظلوما ... وكنت أراه ذا ورع وقصد)\n(يقول أماتني ربي خداعا ... أمات الله حسان بن سعد)\n(فلولا كسبه لوجدت فسلا ... لئيم الكسب شأنك شأن عبد)\n(ركبت اليه في رجل أتاني ... كريم يبتغي المعروف عندي)\n(فقلت له وبعض القول نصح ... ومنه ما أسر له وأبدي)\n(توق دراهم البكري إني ... أخاف عليك عاقبة التعدي)\n(أقرب كل اصرة ليدنو ... فما يزداد مني غير بعد)\n(فأقسم غير مستثن يمينا ... أبا بخر لتتخمن ردي)\nخبرني محمد بن عمران الصيرفي قال حدثنا الحسن بن عليل العنزي قال حدثني احمد بن بكير الأسدي قال حدثني محمد بن أنس السلامي قال حدثني محمد بن سهل الأسدي راوية الكميت أن الحكم بن عبدل الأسدي أتى محمد بن حسان بن سعد التميمي وكان على خراج الكوفة فكلمه في رجل من العرب أن يضع عنه ثلاثين درهما من خراجه فقال أماتني الله إن كنت أقدر أن أضع من خراج أمير المؤمنين شيئا فانصرف ابن عبدل وهو يقول\n(دع الثلاثين لا تعرض لصاحبها ... لا بارك الله في تلك الثلاثينا)\n(لما علا صوته في الدار مبتكرا ... كأشتفان يرى قوما يدوسونا)\n(أحسن فإنك قد أعطيت مملكة ... إمارة صرت فيها اليوم مفتونا)\n(لايعطك الله خيرا مثلها أبدا ... أقسمت بالله إلا قلت آمينا)\nال فلم يضع له شيئا مما على الرجل فقال فيه\n(رأيت محمدا شرها ظلوما ... وكنت أراه ذا ورع وقصد)\n(يقول أماتني ربي خداعا ... أمات الله حسان بن سعد)\n(فما صادفت في قحطان مثلي ... ولا صادفت مثلك في معد)\n(أقل براعة وأشد بخلا ... وألأم عند مسألة وحمد)\n(نحوت محمدا ودخان فيه ... كريح الجعر فوق عطين جلد)\n(فأقسم غير مستثن يمينا ... أبا بخرلتتخمن ردي)\n(فلو كنت المهذب من تميم ... لخفت ملامتي ورجوت حمدي)\n(نكهت علي نكهة أخدري ... شتيم أعصل الأنياب ورد)\n(فما يدنو إلى فمه ذباب ... ولو طليت مشافره بقند)\n(فإن أهديت لي من فيك حتفا ... فإني كالذي أهديت مهدي)\nال محمد بن سهل وما زال ابن عبدل يزيد في قصيدته هذه الدالية حتى مات وهي طويلة جدا قال واشتهرت حتى إن كان المكاري ليسوق بغله أو حماره فيقول عد أمات الله حسان بن سعد فإذا سمع ذلك أبوه قال بل أمات الله ابني محمدا فهو عرضني لهذا البلاء في ثلاثين درهما","topic":"أخبار الحكم بن عبدل ونسبه","topicNo":15,"sp":2,"spl":"ابن هبيرة لايخيب أمل الحكم — هجاء محمد بن حسان"},
{"id":"b15-9","bab":"الجزء 2","sec":"ابن عبدل وأبو المهاجر وعمر الأسدي","page":"ج2 ص405","text":"أخبرني أحمد بن محمد بن زكريا الصحاف قال حدثنا قعنب بن محرز قال أخبرنا الهيثم بن عدي قال دعا أبو المهاجر الحكم بن عبدل ليشرب عنده وله جارية تغني فغنت فقال ابن عبدل\n(يا أبا المهاجر قد أردت كرامتي ... فأهنتني وضررتني لو تعلم)\n(عند التي لو مس جلدي جلدها ... يوما بقيت مخلدا لا أهرم)\n(أو كنت في أحمى جهنم بقعة ... فرأيتها بردت علي جهنم)\nقال فجعل أبو المهاجر يضحك ويقول له ويحك والله لو كان إليها سبيل لوهبتها لك ولكن لها مني ولد أخبرنا الحسن بن علي قال حدثنا أحمد بن الحارث الخزاز عن المدائني قال كان عمر بن يزيد الأسدي مبخلا ووجده أبوه مع أمة له فكان يعير بذلك وجاءه الحكم بن عبدل الأسدي ومعه جماعة من قومه يسألونه حاجة فدخلوا إليه وهو يأكل تمرا فلم يدعهم إليه وذكروا له حاجتهم فلم يقضها فقال فيه ابن عبدل\n(جئنا وبين يديه التمر في طبق ... فما دعانا أبو حفص ولا كادا)\n(علا على جسمه ثوبان من دنس ... لؤم وجبن ولولا أيره سادا)\nأخبرني علي بن سليمان الأخفش قال أخبرنا محمد بن الحسن الأحول عن أبي نصر عن الأصمعي قال كانت امرأة موسرة بالكوفة وكانت لها على الناس ديون بالسواد فاستعانت بابن عبدل في دينها وقالت إني امرأة ليس لي زوج وجعلت تعرض بأنها تزوجه نفسها فقام ابن عبدل في دينها حتى اقتضاه فلما طالبها بالوفاء كتبت إليه\n(سيخئطك الذي حاولت مني ... فقطع حبل وصلك من حبالي)\n(كما أخطاك معروف ابن بشر ... وكنت تعد ذلك رأس مال)\nال وكان ابن عبدل أتى ابن بشر بالكوفة فسأله فقال له أخمسمائة أحب إليك الآن عاجلة أم ألف في قابل قال ألف في قابل فلما أتاه قال له ألف أحب إليك أم ألفان في قابل قال ألفان فلم يزل ذلك دأبة حتى مات ابن بشر وما أعطاه شيئا\nأخبرني عمي قال حدثنا الكراني قال حدثنا العمري عن لقيط قال دخل ابن عبدل على عبد الملك بن بشر فقال له ما أحدثت بعدي قال خطبت امرأة من قومي فردت علي جواب رسالتي ببيتي شعر قال وما هما قال قالت\n(سخطئك الذي حاولت مني ... فقطع حبل وصلك من حبالي)\n(كما أخطاك معروف ابن بشر ... وكنت تعد ذلك رأس مال)\nفضحك عبد الملك ثم قال لجاد ما أذكرت بنفسك وأمر له بألفي درهم","topic":"أخبار الحكم بن عبدل ونسبه","topicNo":15,"sp":3,"spl":"ابن عبدل وأبو المهاجر وعمر الأسدي — ابن عبدل وبشر بن مروان"},
{"id":"b15-10","bab":"الجزء 2","sec":"ابن عبدل وبشر بن مروان","page":"ج2 ص407","text":"أخبرني أبو الحسن الأسدي وحبيب بن نصر المهلبي قالا حدثنا الحسن بن عليل قال حدثنا محمد بن معاوية الأسدي قال حدثني منجاب بن الحارث قال حدثني عبد الملك بن عفان قال كان الحكم بن عبدل الأسدي ثم الغاضري صديقا لبشر بن مروان فرأى منه جفاء لشغل عرض له فغبر عنه شهرا ثم التقيا فقال يابن عبدل مالك تركتنا وقد كنت لنا زوارا فقال ابن عبدل\n(كنت أثني عليك خيرا فلما ... أضمر القلب من نوالك ياسا)\n(كنت ذا منصب قنيت حيائي ... لم أقل غير أن هجرتك باسا)\n(لم أطق ما أردت بي يابن مروان ... ستلقى إذا أردت أناسا)\n(يقبلون الخسيس منك ويثنون ... ثناء مدخمسا دخماسا)\nفقال له لا نسومك الخسيس ولا نريد منك ثناء مدخمسا ووصله وحمله وكساه أخبرني الأسدي قال حدثنا الحسن بن عليل العنزي قال وحدثني محمد بن معاوية قال حدثني منجاب بن الحارث عن عبد الملك بن عفان قال أراد عمر بن هبيرة أن يغزي الحكم بن عبدل الغاضري فاعتل بالزمانة فحمل وألقي بين يديه فجرده فإذا هو أعرج مفلوج فوضع عنه الغزو وضمه إليه وشخص به معه إلى واسط فقال الحكم بن عبدل\n(لعمري لقد جردتني فوجدتني ... كثير العيوب سيء المتجرد)\n(فأعفيتني لما رأيت زمانتي ... ووفقت مني للقضاء المسدد)\nلما وصل عمر إلى واسط شكا إليه الحكم بن عبدل الضبعة فوهب له جارية من جواريه فواثبها ليلة صارت إليه فنكحها تسعا أو عشرا طلقا فلما أصبحت قالت له جعلت فداك من أي الناس أنت قال امرؤ من أهل الشام قالت بهذا العمل نصرتم أخبرني بهذا الخبر محمد بن عمران الصيرفي قال حدثنا الحسن بن عليل\nقال حدثنا أحمد بن بكير الأسدي عن محمد بن أنس السلامي عن محمد بن سهل راوية الكميت فقال فيه ضرب الحجاج البعث على المحتلمين ومن أنبت من الصبيان فكانت المرأة تجيء إلى ابنها وقد جرد فتضمه إليها وتقول له بأبي جزعا عليه فسمي ذلك الجيش جيش بأبي وأحضر ابن عبدل فجرد فوجد أعرج فأعفي فقال في ذلك\n(لعمري لقد جردتني فوجدتني ... )\nالبيتين وزاد معهما ثالثا وهو\n(ولست بذي شيخين يلتزمانه ... ولكن يتيم ساقط الرجل واليد)","topic":"أخبار الحكم بن عبدل ونسبه","topicNo":15,"sp":3,"spl":"ابن عبدل وأبو المهاجر وعمر الأسدي — ابن عبدل وبشر بن مروان","partial":1},
{"id":"b15-11","bab":"الجزء 2","sec":"كره زوجته وقال فيها شعرا","page":"ج2 ص409","text":"أخبرني أبو الحسن الأسدي قال حدثنا العنزي قال حدثنا محمد بن معاوية عن منجاب عن عبد الملك بن عفان قال تزوج ابن عبدل امرأة من همدان فقالوا له على كم تزوجت فقال\n(تزوجت همدانية ذات بهجة ... على نمط عادية ووسائد)\n(لعمري لقد غاليت بالمهر إنه ... كذاك يغالى بالنساء المواجد)\nقال فلما دخل بها كرهها فقال\n(أعاذلتي من لوم دعاني ... أقلا اللوم إن لم تعذراني)\n(فإني قد دللت على عجوز ... مبرقعة مخضبة البنان)\n(تغضن جلدها واخضر إلا ... إذا ما ضرجت بالزعفران)\n(فلما أن دخلت وحادثتني ... أظلتني بيوم أرونان)\n(تحدثني عن الأزمان حتى ... سمعت نداء حر بالأذان)\n(فقالت قد نكحت اثنين شتى ... فلما صاحباني طلقاني)\n(وأربعة نكحتهم فماتوا ... فليت عريف حي قد نعناي)\n(وقالت ما تلادك قلت مالي ... حمار ظالع ومزادتان)\n(وبوري وأربعة زيوف ... وثوبا مفلس متخرقان)\n(وقطعة جلة لا تمر فيها ... ودنا عومة متقابلان)\n(فقالت قد رضيت فسم ألفا ... ليسمع ما تقول الشاهدان)\n(وما لك عندنا ألف عتيد ... ولا تسع تعد ولا ثمان)\n(ولا سبع ولا ست ولكن ... لكم عندي الطويل من الهوان)","topic":"أخبار الحكم بن عبدل ونسبه","topicNo":15,"sp":4,"spl":"كره زوجته وقال فيها شعرا — رثاء بشر بن مروان"},
{"id":"b15-12","bab":"الجزء 2","sec":"رثاء بشر بن مروان","page":"ج2 ص410","text":"أخبرني محمد بن الحسن بن دريد قال حدثني عمي عن أبيه عن ابن الكلبي قال\nكان الحكم بن عبدل الأسدي منقطعا إلي بشر بن مروان وكان يأنس به ويحبه ويستطيبه وأخرجه معه إلي البصرة لما وليها فلما مات بشر جزع عليه الحكم وقال يرثيه\n(أصبحت جم بلابل الصدر ... متعجبا لتصرف الدهر)\n(مازلت أطلب في البلاد فتى ... ليكون لي ذخرا من الذخر)\n(ويكون يسعدني وأسعده ... في كل نائبة من الأمر)\n(حتى إذا ظفرت يداي به ... جاء القضاء بحينه يجري)\n(إني لفي هم يباكرني ... منه وهم طارق يسري)\n(فلأصبرن وما رأيت دوى ... للهم غير عزيمة الصبر)\n(والله ما استعظمت فرقته ... حتى أحاط بفضله خبري)\nخبرني ابن دريد قال حدثني عمي عن أبيه عن ابن الكلبي قال لما ظفر ابن الزبير بالعراق وأخرج عنها عمال بني أمية خرج ابن عبدل معهم إلى الشأم وكان ممن يدخل لى عبد الملك ويسمر عنده فقال لعبد الملك ليلة\n(يا ليت شعري وليت ربما نفعت ... هل أبصرن بني العوام قد شملوا)\n(بالذل والأسر والتشريد إنهم ... على البرية حتف حيثما نزلوا)\n(أم هل أراك بأكناف العراق وقد ... ذلت لعزك أقوام وقد نكلوا)\nفقال عبد الملك ويروى أنه قائل هذا الشعر\n(إن يمكن الله من قيس ومن جدس ... ومن جذام ويقتل صاحب الحرم)\n(نضرب جماجم أقوام على حنق ... ضربا ينكل عنا سائر الأمم)","topic":"أخبار الحكم بن عبدل ونسبه","topicNo":15,"sp":4,"spl":"كره زوجته وقال فيها شعرا — رثاء بشر بن مروان"},
{"id":"b15-13","bab":"الجزء 2","sec":"ابن هبيرة وبنت ابن عبدل","page":"ج2 ص412","text":"أخبرني علي بن سليمان الأخفش قال حدثني هارون بن علي بن يحيى المنجم عن أبيه قال حدثني محمد بن عمر الجرجاني عن رجل من بني أسد قال خرج يزيد بن عمر بن هبيرة يسير بالكوفة فانتهى إلى مسجد بنى غاضرة وأقيمت الصلاة فنزل يصلي واجتمع الناس لمكانه في الطريق وأشرف النساء من السطوح فلما قضى صلاته قال لمن هذا المسجد قالوا لبني غاضرة فتمثل قول الشاعر\n(ما إن تركن من الغواضر معصرا ... إلا فصمن بساقها خلخالا)\nفقالت له امرأة من المشرفات\n(ولقد عطفن على فزارة عطفة ... كر المنيح وجلن ثم مجالا)\nفقال يزيد من هذه فقالوا بنت الحكم بن عبدل فقال هل تلد الحية إلا حية وقام خجلا أخبرني محمد بن خلف بن المرزبان قال حدثني أحمد بن الهيثم قال حدثنا العمري عن عطاء بن مصعب عن عاصم بن الحدثان قال كان ابن عبدل الأسدي أعرج أحدب وكان من أطيب الناس وأملحهم فلقيه صاحب العسس ليلة وهو سكران محمول في محفة فقال له من أنت فقال\nله يا بغيض أنت أعرف بي من أن تسألني من أنا فاذهب إلى شغلك فإنك تعلم أن اللصوص لا يخرجون بالليل للسرقة محمولين في محفة فضحك الرجل وانصرف عنه أخبرني هاشم بن محمد قال حدثنا العباس بن ميمون طائع قال حدثني أبو عدنان عن الهيثم بن عدي عن ابن عياش قال رأيت ابن عبدل الأسدي وقد دخل على ابن هبيرة فقال له أنشدني شيئا فقال أنشدك مقولة أيها الأمير قال هات فأنشده هذه الأبيات وهي قديمة وقد تمثل بها ابن الأشعث حين خرج ويروى أنها لأعشى همدان\n(نجم ولا نعطى وتعطى جيوشهم ... وقد ملأوا من مالنا ذا الأكارع)\n(وقد كلفونا عدة وروائعا ... فقد وأبي رعناكم بالروائع)\n(ونحن جلبنا الخيل من ألف فرسخ ... إليكم بمحمر من الموت ناقع)\nقال فغضب ابن هبيرة من تعريضه به وقال له والله لولا أني قد أمنتك واستنشدتك لضربت عنقك أخبرني محمد بن خلف بن المرزبان أبو عبد الله قال حدثنا القاسم بن عبد الرحمن قال كانت للحكم بن عبدل جارية سوداء وقد كان يميل إليها فولدت له ابنا أسود فكان من أعرم الصبيان فقال فيه\n(يا رب خال لك مسود القفا ... لا يشتكي من رجله مس الحفا)\n(كأن عينيه إذا تشوفا ... عينا غراب فوق نيق أشرفا)\nخبرنا محمد بن خلف بن المرزبان أبو عبد الله قال حدثنا عبيد الله بن محمد قال حدثنا المدائني قال كان عمر بن يزيد الأسدي بخيلا على الطعام فدخل عليه الحكم بن عبدل الشاعر وهو يأكل بطيخا فسلم فلم يرد عليه السلام ولم يدعه إلى الطعام فقال ابن عبدل يهجوه\n(في عمر بن يزيد خلتا دنس ... بخل وجبن ولولا أيره سادا)\n(جئناه يأكل بطيخا على طبق ... فما دعانا أبو حفص ولا كادا)\nقال وكان عمر على شرطة الحجاج وكان بخيلا جدا فأصابه قولنج فحقنه الطبيب بدهن كثير فانحل ما في بطنه في الطست فقال الغلام ما تصنع به قال أصبه قال لا ولكن ميز منه الدهن واستصبح به","topic":"أخبار الحكم بن عبدل ونسبه","topicNo":15,"sp":5,"spl":"ابن هبيرة وبنت ابن عبدل"},
{"id":"b15-14","bab":"الجزء 2","sec":"ابن عبدل وكاتب عبد الملك بن بشر","page":"ج2 ص414","text":"أخبرني عيسى بن الحسين الوراق قال حدثنا أبو هفان قال كان لعبد المك بن بشر بن مروان كاتب يقال له محمد بن عمير وكان كلما مدحه ابن عبدل بشي وأمر له بجائزة دافعه بها وعارضه فيها فدخل يوما إلى عبد الملك وكاتبه هذا يساره فوقف وأنشأ يقول\n(ألقيت نفسك في عروض مشقة ... وحصاد أنفك بالمناجل أهون)\n(فبحق أمك وهي غيرحقيقة ... باللين واللطف الذي لا يخزن)\n(لا تدن فاك إلى الأمير ونحه ... حتى يداوي نتنه لك أهون)\n(إن كان للظربان حجر منتن ... فلحجر أنفك يا محمد أنتن)\nخبرني محمد بن عمران الصيرفي قال حدثنا العنزي قال حدثني أحمد بن بكير الأسدي عن محمد بن أنس السلامي عن محمد بن سهل راوية الكميت قال خطب ابن عبدل امرأة من همدان يقال لها أم رياح فلم تتزوجه فقال أما والله لأفضحنك ولأعيرنك فقال\n(فلا خير في الفتيان بعد ابن عبدل ... ولا في الزواني بعد أم رياح)\n(يرى بحمد الله ماض مجرب ... وأم رياح عرضة لنكاحي)\nال فتحاماها الناس فما تزوجت حتى أسنت وبهذا الإسناد عن محمد بن سهل قال ولد للحكم بن عبدل ابن فسماه بشرا ودخل على بشر بن مروان فأنشده\n(سميت بشرا ببشر الندى ... فلا تفضحني بتصداقها)\n(إذا ما قريش قريش البطاح ... عند تجمع آفاقها)\n(تسامت قرومهم للندى ... تباري الرياح بأوراقها)\n(فما لك أنفع أموالها ... وخلقك أكرم أخلاقها)\nفأمر له بألفي درهم وقال استعن بهذه على أمرك وبإسناده عن محمد بن سهل قال اقترض ابن عبدل مالا من التجار وحلف لهم بالطلاق ثلاثا أن يقضيهم المال عند طلوع الهلال فلما بقي من الشهر يومان قال\n(قد بات همي قرنا أكابده ... كأنما مضجعي على حجر)\n(من رهبة أن يرى هلال غد ... فإن رأوه فحق لي حذري)\n(من فقد بيضاء غادة كملت ... كأنها صورة من الصور)\n(أصبحت من أهلي الغداة ومن ... مالي على مثل ليلة الصدر)\nفبلغ خبره عبد الملك بن بشر فأعطاهم ما لهم عليه وأضعفه له فقال فيه\n(لما أتاه الذي أصبت به ... وأنشدوه إياه في شعري)\n(جاد بضعفي ما حل من غرمي ... عفوا فزالت حرارة الصدر)\n(لأشكرن الذي مننت به ... ما دمت حيا وطال لي عمري)\nقال محمد بن سهل بهذا الإسناد اجتمع الشعراء إلى الحجاج وفيهم ابن عبدل فقالوا للحجاج إنما شعر ابن عبدل كله هجاء وشعر سخيف فقال له قد سمعت قولهم فاستمع مني قال هات فأنشده قوله\n(وإني لأستغني فما أبطر الغنى ... وأعرض ميسوري لمن يبتغي قرضي)\n(وأعسر أحيانا فتشتد عسرتي ... فأدرك ميسور الغنى ومعي عرضي)\nحتى انتهى إلى قوله\n(ولست بذي وجهين فيمن عرفته ... ولا البخل فاعلم من سمائي ولا أرضي)\nفقال له الحجاج أحسنت وفضله في الجائزة عليهم بألفي درهم صوت","topic":"أخبار الحكم بن عبدل ونسبه","topicNo":15,"sp":6,"spl":"ابن عبدل وكاتب عبد الملك بن بشر — من المائة المختارة"},
{"id":"b15-15","bab":"الجزء 2","sec":"من المائة المختارة","page":"ج2 ص417","text":"(أجد بعمرة غنيانها ... فتهجر أم شأننا شانها)\n(فإن تمس شطت بها دارها ... وباح لك اليوم هجرانها)\n(فما روضة من رياض القطا ... كأن المصابيح حوذانها)\n(بأحسن منها ولا مزنة ... دلوح تكشف إدجانها)\n(وعمرة من سروات النساء ... تنفح بالمسك أردانها)\nجد استمر وغنيانها استغناؤها أم شأننا شانها يقول أم هي على ما تحب وشطت بعدت قال ابن الأعرابي يقال شطت وشطنت وشسعت وتشسعت وبعدت ونأت وتزحزحت وشطرت قال الشاعر\n(لا تتركني فيهم شطيرا ... )\nومنه سمي الشاطر وباح ظهر ومنه باحة الدار وأنشد\n(أتكتم حب سلمى أم تبوح ... )\nوالروضة موضع فيه نبت وماء مستدير وكذلك الحديقة و قوله\n(كأن المصابيح حوذانها ... )\nأراد كأن حوذانها المصابيح فقلب و العرب تفعل ذلك قال الأعشى\n( ... كأن الجمر مثل ترابها)\nأراد كأن ترابها مثل الجمر والمزنة السحابة والدلوح النقيلة يقال مر يدلح بحمله إذا مر مثقلا والدجن إلباس الغيم السحاب برش و ندى يقال أدجنت السماء وقوله تكشف إدجانها إذا انكشف السواد عنها وذلك أحسن لها وأراد مزنة بيضاء والأردان ما يلي الذراعين جميعا والإبطين من الكمين الشعر لقيس بن الخطيم والغناء لطويس خفيف ثقيل أول باطلاق الوتر في مجرى الوسطى الى هنا انتهى الجزء الثاني من كتاب الأغاني ويليه إن شاء الله تعالى الجزء الثالث منه وأوله ذكر قيس بن الخطيم واخباره ونسبه","topic":"أخبار الحكم بن عبدل ونسبه","topicNo":15,"sp":6,"spl":"ابن عبدل وكاتب عبد الملك بن بشر — من المائة المختارة","partial":1},
{"id":"b16-1","bab":"الجزء 2","sec":"ذكر قيس بن الخطيم وأخباره ونسبه","page":"ج2 ص418","text":"هو قيس بن الخطيم بن عدي بن عمرو بن سود بن ظفر ويكنى قيس أبا يزيد أخبرني الحرمي بن أبي العلاء قال حدثنا محمد بن موسى بن حماد قال حدثنا حماد بن إسحاق عن أبيه قال أنشد ابن أبي عتيق قول قيس بن الخطيم\n(بين شكول النساء خلقتها ... حذوا فلا جبلة ولا قضف)\nقال لولا أن أبا يزيد قال حذوا ما درى الناس كيف يحشون هذا الموضع وكان أبوه الخطيم قتل وهو صغير قتله رجل من بني حارثة بن الحارث بن الخزرج فلما بلغ قتل قاتل أبيه ونشبت لذلك حروب بين قومه وبين الخزرج وكان سببها","topic":"ذكر قيس بن الخطيم وأخباره ونسبه","topicNo":16,"sp":0,"spl":"ذكر قيس بن الخطيم وأخباره ونسبه — قيس بن الخطيم يخرج إلى خداش بن زهير"},
{"id":"b16-2","bab":"الجزء 3","sec":"خداش بن زهير يساعد قيس بن الخطيم على الأخذ بالثأر","page":"ج3 ص3","text":"فأخبرني علي بن سليمان الأخفش قال أخبرني أحمد بن يحيى\nثعلب عن ابن الأعرابي عن المفضل قال كان سبب قتل الخطيم أن رجلا من بني حارثة بن الحارث بن الخزرج يقال له مالك اغتاله فقتله وقيس يومئذ صغير وكان عدي أبو الخطيم أيضا قتل قبله قتله رجل من عبد القيس فلما بلغ قيس بن الخطيم وعرف أخبار قومه وموضع ثأره ولم يزل يلتمس غرة من قاتل أبيه وجده في المواسم حتى ظفر بقاتل أبيه بيثرب فقتله وظفر بقاتل جده بذي المجاز فلما أصابه وجده في ركب عظيم من قومه ولم يكن معه إلا رهط من الأوس فخرج حتى أتى حذيفة بن بدر الفزاري فاستنجده فلم ينجده فأتى خداش بن زهير فنهض معه ببني عامر حتى أتوا قاتل عدي فإذا هو واقف على راحلته في السوق فطعنه قيس بحربة فقتله ثم استمر فأراده رهط الرجل فحالت بنو عامر دونه فقال في ذلك قيس بن الخطيم\n(ثأرت عديا والخطيم فلم أضع ... ولاية أشباخ جعلت إزاءها)\n(ضربت بذي الزجين ربقة مالك ... فأبت بنفس قد أصبت شفاءها)\n(وسامحني فيها ابن عمرو بن عامر ... خداش فأدى نعمة وأفاءها)\n(طعنت ابن عبد القيس طعنة ثائر ... لها نفذ لولا الشعاع أضاءها)\n(ملكت بها كفي فأنهرت فتقها ... يرى قائم من دونها ما وراءها)\nذه رواية ابن الأعرابي عن المفضل وأما ابن الكلبي فإنه ذكر أن رجلا من قريش أخبره عن أبي عبيدة أن محمد بن عمار بن ياسر وكان عالما بحديث الأنصار قال كان من حديث قيس بن الخطيم أن جده عدي بن عمرو قتله رجل من بني عمرو بن عامر بن ربيعة بن عامر بن صعصعة يقال له مالك وقتل أباه الخطيم بن عدي رجل من عبد القيس ممن يسكن هجر وكان قيس يوم قتل أبوه صبيا صغيرا وقتل الخطيم قبل أن يثأر بأبيه عدي فخشيت أم قيس على ابنها أن يخرج فيطلب بثأر أبيه وجده فيهلك فعمدت إلى كومة من تراب عند باب دارهم فوضعت عليها أحجارا وجعلت تقول لقيس هذا قبر أبيك وجدك فكان قيس لا يشك أن ذلك على ذلك ونشأ أيدا شديد الساعدين فنازع يوما فتى من فتيان بني ظفر فقال له ذلك الفتى والله لو جعلت شدة ساعديك على قاتل أبيك وجدك لكان خيرا لك من أن تخرجها علي فقال ومن قاتل أبي وجدي قال سل أمك تخبرك فأخذ السيف ووضع قائمه على الأرض وذبابه بين ثدييه وقال لأمه أخبريني من قتل أبي وجدي قالت ماتا كما يموت الناس وهذان قبراهما بالفناء فقال والله لتخبرينني من قتلهما أو لأتحاملن على هذا السيف حتى يخرج من ظهري فقالت أما جدك فقتله رجل من بني عمرو بن عامر بن ربيعة يقال له مالك وأما أبوك فقتله رجل من عبد القيس ممن يسكن هجر فقال والله لا أنتهي حتى أقتل\nقاتل أبي وجدي فقالت يا بني إن مالكا قاتل جدك من قوم خداش بن زهير ولأبيك عند خداش نعمة هو لها شاكر فأته فاستشره في أمرك واستعنه يعنك","topic":"ذكر قيس بن الخطيم وأخباره ونسبه","topicNo":16,"sp":0,"spl":"ذكر قيس بن الخطيم وأخباره ونسبه — قيس بن الخطيم يخرج إلى خداش بن زهير"},
{"id":"b16-3","bab":"الجزء 3","sec":"قيس بن الخطيم يخرج إلى خداش بن زهير","page":"ج3 ص6","text":"فخرج قيس من ساعته حتى أتى ناضحه وهو يسقي نخله فضرب الجرير بالسيف فقطعه فسقطت الدلو في البئر وأخذ برأس الجمل فحمل عليه غرارتين من تمر وقال من يكفيني أمر هذه العجوز يعني أمه فإن مت أنفق عليها من هذا الحائط حتى تموت ثم هوله وإن عشت فما لي عائد إلي وله منه ما شاء أن يأكل من تمره فقال رجل من قومه أنا له فأعطاه الحائط ثم خرج يسأل عن خداش بن زهير حتى دل عليه بمر الظهران فصار إلى خبائه فلم يجده فنزل تحت شجرة يكون تحتها أضيافه ثم نادى امرأة خداش هل من طعام فأطلعت إليه فأعجبها جماله وكان من أحسن الناس وجها فقالت والله ما عندنا من نزل نرضاه لك إلا تمرا فقال لا أبالي فأخرجي ما كان عندك فأرسلت إليه بقباع فيه تمر فأخذ منه تمرة فأكل شقها ورد شقها الباقي في القباع ثم أمر بالبقاع فأدخل على امرأة خداش بن زهير ثم ذهب لبعض حاجاته ورجع خداش فأخبرته امرأته خبر قيس فقال هذا رجل متحرم","topic":"ذكر قيس بن الخطيم وأخباره ونسبه","topicNo":16,"sp":0,"spl":"ذكر قيس بن الخطيم وأخباره ونسبه — قيس بن الخطيم يخرج إلى خداش بن زهير"},
{"id":"b16-4","bab":"الجزء 3","sec":"زهير بن خداش يخبر قيس بن الخطيم عن قاتلي أبيه وجده","page":"ج3 ص7","text":"وأقبل قيس راجعا وهو مع امرأته يأكل رطبا فلما رأى خداش رجله وهو على بعيره قال لامرأته هذا ضيفك قالت نعم قال كأن قدمه قدم الخطيم صديقي اليثربي فلما دنا منه قرع طنب البيت بسنان رمحه واستأذن فأذن له خداش فدخل إليه فنسبه فانتسب وأخبره بالذي جاء له وسأله أن يعينه وأن يشير عليه في أمره فرحب به خداش وذكر نعمة أبيه عنده وقال إن هذا الأمر ما زلت أتوقعه منك منذ حين فأما قاتل جدك فهو ابن عم لي وأنا أعينك عليه فإذا اجتمعنا في نادينا جلست إلى جنبه وتحدثت معه فإذا ضربت فخذه فثب إليه فاقتله فقال قيس فأقبلت معه نحوه حتى قمت على رأسه لما جالسه خداش فحين ضرب فخذه ضربت رأسه بسيف يقال له ذو الخرصين فثار إلي القوم ليقتلوني فحال خداش بينهم وبيني وقال دعوه فإنه والله ما قتل إلا قاتل جده ثم دعا خداش بجمل من إبله فركبه وانطلق مع قيس إلى العبدي الذي قتل أباه حتى إذا كانا قريبا من هجر أشار عليه خداش أن ينطلق حتى يسأل عن قاتل أبيه فإذا دل عليه قال له إن لصا من لصوص قومك عارضني فأخذ متاعا لي فسألت من سيد قومه فدللت عليك فانطلق معي حتى تأخذ متاعي منه فإن اتبعك وحده فستنال ما تريد منه وإن أخرج معه غيره فاضحك فإن سألك مم ضحكت فقل إن الشريف عندنا لا يصنع كما صنعت إذا دعي إلى اللص من قومه إنما يخرج وحده بسوطه دون سيفه فإذا رآه اللص أعطى كل شيء أخذ هيبة له فإن أمر أصحابه بالرجوع فسبيل ذلك وإن أبي إلا أن يمضوا معه فأتني به فإني أرجو أن تقتله وتقتل أصحابه ونزل خداش تحت ظل شجرة وخرج قيس حتى أتى العبدي فقال له ما أمره خداش فأحفظه فأمر أصحابه فرجعوا ومضى مع قيس فلما طلع على خداش قال له اختر يا قيس إما أن أعينك وإما أن أكفيك قال لا أريد واحدة\nمنهما ولكن إن قتلني فلا يفلتنك ثم ثار إليه فطعنه قيس بالحربة في خاصرته فأنفذها من الجانب الآخر فمات مكانه فلما فرغ منه قال له خداش إنا إن فررنا الآن طلبنا قومه ولكن ادخل بنا مكانا قريبا من مقتله فإن قومه لا يظنون أنك قتلته وأقمت قريبا منه ولكنهم إذا افتقدوه اقتفوا أثره فإذا وجدوه قتيلا خرجوا في طلبنا في كل وجه فإذا يئسوا رجعوا قال فدخلا في دارات من رمال هناك وفقد العبدي قومه فاقتفوا أثره فوجدوه قتيلا فخرجوا يطلبونهما في كل وجه ثم رجعوا فكان من أمرهم ما قال خداش وأقاما مكانهما أياما ثم خرجا فلم يتكلما حتى أتيا منزل خداش ففارقه عنده قيس بن الخطيم ورجع إلى أهله ففي ذلك يقول قيس\n(تذكر ليلى حسنها وصفاءها ... وبانت فما إن يستطيع لقاءها)\n(ومثلك قد أصبيت ليست بكنة ... ولا جارة أفضت إلي خباءها)\n(إذا مااصطبحت أربعا خط مئزري ... وأتبعت دلوي في السماح رشاءها)\n(ثأرت عديا والخطيم فلم أضع ... وصية أشياخ جعلت إزاءها)\nهي قصيدة طويلة","topic":"ذكر قيس بن الخطيم وأخباره ونسبه","topicNo":16,"sp":1,"spl":"زهير بن خداش يخبر قيس بن الخطيم عن قاتلي أبيه وجده"},
{"id":"b16-5","bab":"الجزء 3","sec":"رسول الله يستنشد شعر قيس ويعجب بشجاعته","page":"ج3 ص8","text":"أخبرني أحمد بن عبيد الله بن عمار قال حدثني يعقوب بن إسرائيل قال حدثنا زكريا بن يحيى المنقري قال حدثنا زياد بن بيان العقيلي قال حدثنا أبو خولة\nالأنصاري عن أنس بن مالك قال جلس رسول الله في مجلس ليس فيه إلا خزرجي ثم استنشدهم قصيدة قيس بن الخطيم يعني قوله\n(أتعرف رسما كاطراد المذاهب ... لعمرة وحشا غير موقف راكب)\nأنشده بعضهم إياها فلما بلغ إلى قوله\n(أجالدهم يوم الحديقة حاسرا ... كأن يدي بالسيف مخراق لاعب)\nالتفت إليهم رسول الله فقال هل كان كما ذكر فشهد له ثابت بن قيس بن شماس وقال له والذي بعثك بالحق يا رسول الله لقد خرج إلينا يوم سابع عرسه عليه غلالة وملحفة مورسة فجالدنا كما ذكر وهكذا في هذه الرواية وقد أخبرني الحسن بن علي قال حدثنا الزبير بن بكار قال حدثني عمي مصعب قال\nلم تكن بينهم في هذه الأيام حروب إلا في يوم بعاث فإنه كان عظيما وإنما كانوا يخرجون فيترامون بالحجارة ويتضاربون بالخشب قال الزبير وأنشدت محمد بن فضالة قول قيس بن الخطيم\n(أجالدهم يوم الحديقة حاسرا ... كأن يدي بالسيف مخراق لاعب)\nضحك وقال ما اقتتلوا يومئذ إلا بالرطائب والسعف قال أبو الفرج وهذه القصيدة التي استنشدهم إياها رسول الله من جيد شعر قيس بن الخطيم ومما أنشده نابغة بني ذبيان فاستحسنه وفضله وقدمه من أجله أخبرنا الحسن بن علي قال حدثنا أحمد بن زهير قال حدثنا الزبير بن بكار قال قال أبو غزية قال حسان بن ثابت قدم النابغة المدينة فدخل السوق فنزل عن راحلته ثم جثا على ركبتيه ثم اعتمد على عصاه ثم أنشأ يقول\n(عرفت منازلا بعريتنات ... فأعلى الجزع للحي المبن)\nفقلت هلك الشيخ ورأيته قد تبع قافية منكرة قال ويقال إنه قالها في موضعه فما زال ينشد حتى أتى على آخرها ثم قال ألا رجل ينشد فتقدم قيس بن الخطيم فجلس بين يديه وأنشده\n(أتعرف رسما كاطراد المذاهب ... )\nتى فرغ منها فقال أنت أشعر الناس يابن أخي قال حسان فدخلني منه وإني في ذلك لأجد القوة في نفسي عليهما ثم تقدمت فجلست بين يديه فقال أنشد فوالله إنك لشاعر قبل أن تتكلم قال وكان يعرفني قبل ذلك فأنشدته فقال أنت أشعر الناس قال الحسن بن موسى وقالت الأوس لم يزد قيس بن الخطيم النابغة على\n(أتعرف رسما كاطراد المذاهب ... )\nنصف البيت حتى قال أنت أشعر الناس","topic":"ذكر قيس بن الخطيم وأخباره ونسبه","topicNo":16,"sp":2,"spl":"رسول الله يستنشد شعر قيس ويعجب بشجاعته — صفات قيس بن الخطيم الجسدية","partial":1},
{"id":"b16-6","bab":"الجزء 3","sec":"صفات قيس بن الخطيم الجسدية","page":"ج3 ص11","text":"أخبرني الحسن بن علي قال حدثنا أحمد بن زهير قال حدثنا الزبير قال قال سليمان بن داود المجمعي كان قيس بن الخطيم مقرون الحاجبين أدعج العينين أحمر الشفتين براق الثنايا كأن بينها برقا ما رأته حليلة رجل قط إلا ذهب عقلها أخبرني الحسن قال حدثنا محمد قال حدثنا الزبير قال حدثني حسن بن موسى عن سليمان بن داود المجمعي قال قال حسان بن ثابت للخنساء اهجي قيس بن الخطيم فقالت لا أهجو\nأحدا أبدا حتى أراه قال فجاءته يوما فوجدته في مشرقة ملتفا في كساء له فنخسته برجلها وقالت قم فقام فقالت أدبر فأدبر ثم قالت أقبل فأقبل قال والله لكأنها تعترض عبدا تشتريه ثم عاد إلى حاله نائما فقالت والله لا أهجو هذا أبدا قال الزبير وحدثني عمي مصعب قال كانت عند قيس بن الخطيم حواء بنت يزيد بن سنان بن كريز بن زعوراء فأسلمت وكانت تكتم قيس بن الخطيم إسلامها فلما قدم قيس مكة عرض عليه رسول الله الإسلام فاستنظره قيس حتى يقدم رسول الله المدينة فسأله رسول الله أن يجتنب زوجته حواء بنت يزيد وأوصاه بها خيرا وقال له إنها قد أسلمت ففعل قيس وحفظ وصية رسول الله فبلغ رسول الله فقال وفي الأديعج قال أبو الفرج وأحسب هذا غلطا من مصعب وأن صاحب هذه القصة قيس بن شماس وأما قيس بن الخطيم فقتل قبل الهجرة","topic":"ذكر قيس بن الخطيم وأخباره ونسبه","topicNo":16,"sp":2,"spl":"رسول الله يستنشد شعر قيس ويعجب بشجاعته — صفات قيس بن الخطيم الجسدية"},
{"id":"b16-7","bab":"الجزء 3","sec":"مقتل ابن الخطيم على أيدي الخزرج","page":"ج3 ص12","text":"أخبرني علي بن سليمان الأخفش النحوي عن أبي سعيد السكري عن محمد بن حبيب عن ابن الأعرابي عن المفضل أن حرب الأوس والخزرج لما هدأت تذكرت الخزرج قيس بن الخطيم ونكايته فيهم فتوامروا وتواعدوا قتله فخرج عشية من منزله في ملاءتين يريد\nمالا له بالشوط حتى مر بأطم بني حارثة فرمي من الأطم بثلاثة أسهم فوقع أحدها في صدره فصاح صيحة سمعها رهطه فجاءوا فحملوه إلى منزله فلم يروا له كفأ إلا أبا صعصعة يزيد بن عوف بن مدرك النجاري فاندس إليه رجل حتى اغتاله في منزله فضرب عنقه واشتمل على رأسه فأتى به قيسا وهو بآخر رمق فألقاه بين يديه وقال يا قيس قد أدركت بثأرك فقال عضضت بأير أبيك إن كان غير أبي صعصعة فقال هو أبو صعصعة وأراه الرأس فلم يلبث قيس بعد ذلك أن مات وهذا الشعر أعني\n(أجد بعمرة غنيانها ... )\nيما قيل يقوله قيس في عمرة بنت رواحة وقيل بل قاله في عمرة امرأة كانت لحسان بن ثابت وهي عمرة بنت صامت بن خالد وكان حسان ذكر ليلى بنت الخطيم في شعره فكافأه قيس بذلك وكان هذا في حربهم التي يقال لها يوم الربيع فأخبرني الحسن بن علي قال حدثنا أحمد بن زهير قال أخبرنا الزبير قال حدثني مصعب قال مر حسان بن ثابت بليلى بنت الخطيم وقيس بن الخطيم أخوها بمكة حين خرجوا يطلبون الحلف في قريس فقال له حسان أظعني فالحقي بالحي فقد ظعنوا وليت شعري ما خلفك وما شأنك أقل ناصرك أم راث رافدك فلم تكلمه وشتمه نساؤها فذكرها في شعره في يوم الربيع الذي يقول فيه\n(لقد هاج نفسك أشجانها ... وعاودها اليوم أديانها)\n(تذكرت ليلى وأنى بها ... إذا قطعت منك أقرانها)\n(وحجل في الدار غربانها ... وخف من الدار سكانها)\n(وغيرها معصرات الرياح ... وسح الجنوب وتهتانها)\n(مهاة من العين تمشي بها ... وتتبعها ثم غزلانها)\n(وقفت عليها فساءلتها ... وقد ظعن الحي ما شانها)\n(فعيت وجاوبني دونها ... بما راع قلبي أعوانها)\nوهي طويلة فأجابه قيس بن الخطيم بهذه القصيدة التي أولها\n(أجد بعمرة غنيانها ... )\nفخر فيها بيوم الربيع وكان لهم فقال\n(ونحن الفوارس يوم الربيع ... قد علموا كيف فرسانها)\n(حسان الوجوه حداد السيوف ... يبتدر المجد شبانها)\nهي أيضا طويلة أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال أخبرنا الأصمعي\nقال حدثني شيخ قدم من المدينة وأخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة قال حدثنا أبو غسان عن أبي السائب المخزومي وأخبرني الحسين بن يحيى عن حماد عن أبيه قال ذكر لي عن جعفر بن محرز السدوسي قالوا دخل النعمان بن بشير الأنصاري المدينة أيام يزيد بن معاوية وابن الزبير فقال والله لقد أخفقت أذناي من الغناء فأسمعوني فقيل له لو وجهت إلى عزة فإنها من قد عرفت قال إي ورب البيت إنها لمن يزيد النفس طيبا والعقل شحذا ابعثوا إليها عن رسالتي فإن أبت صرنا إليها فقال له بعض القوم إن النقلة تشتد عليها لثقل بدنها وما بالمدينة دابة تحملها فقال النعمان وأين النجائب عليها الهوادج فوجه إليها بنجيب فذكرت علة فلما عاد الرسول إلى النعمان قال لجليسه أنت كنت أخبر بها قوموا بنا فقام هو مع خواص أصحابه حتى طرقوها فأذنت وأكرمت واعتذرت فقبل النعمان عذرها وقال غنيني فغنته\n(أجد بعمرة غنيانها ... فتهجر أم شأننا شانها)\nأشير إليها أنها أمة فسكتت فقال غنيني فوالله ما ذكرت إلا كرما وطيبا لا تغنيني سائر اليوم غيره فلم تزل تغنيه هذا اللحن فقط حتى انصرف وتذاكروا هذا الحديث عند الهيثم بن عدي فقال ألا أزيدكم فيه\nطريفة قلنا بلى يا أبا عبد الرحمن قال قال لقيط كنت عند سعيد الزبيري قال سمعت عامرا الشعبي يقول اشتاق النعمان بن بشير إلى الغناء فصار إلى منزل عزة فلما انصرف إذا امرأة بالباب منتظرة له فلما خرج شكت إليه كثرة غشيان زوجها إياها فقال لها النعمان بن بشير لأقضين بينكما بقضية لا ترد علي قد أحل الله له من النساء مثنى وثلاث ورباع فله امرأتان بالنهار وامرأتان بالليل فهذا يدل على أن المعنية بهذا الشعر عمرة بنت رواحة وأما ما ذكر أنه غنى عمرة امرأة حسان بن ثابت فأخبرني الحسن بن علي قال حدثنا أحمد بن زهير قال حدثنا الزبير بن بكار عن عمه أن قيس بن الخطيم لما ذكر حسان أخته ليلى في شعره ذكر امرأته عمرة وهي التي يقول فيها حسان\n(أزمعت عمرة صرما فابتكر ... )","topic":"ذكر قيس بن الخطيم وأخباره ونسبه","topicNo":16,"sp":3,"spl":"مقتل ابن الخطيم على أيدي الخزرج","partialRef":{"sid":"b15-15","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b16-8","bab":"الجزء 3","sec":"مقتل ابن الخطيم على أيدي الخزرج","page":"ج3 ص12","text":"ول حسان بن ثابت في زوجه عمرة بنت الصامت أخبرني الحسن قال حدثنا أحمد قال حدثنا الزبير قال حدثني عمي مصعب قال تزوج حسان بن ثابت عمرة بنت الصامت بن خالد بن عطية الأوسية ثم إحدى بني عمرو بن عوف فكان كل واحد منهما معجبا بصاحبه وإن الأوس أجاروا مخلد بن الصامت الساعدي فقال في ذلك أبو قيس بن الأسلت\n(أجرت مخلدا ودفعت عنه ... وعند الله صالح ما أتيت)\nتكلم حسان في أمره بكلام أغضب عمرة فعيرته بأخواله وفخرت عليه بالأوس فغضب لهم فطلقها فأصابها من ذلك ندم وشدة وندم هو بعد فقال\nصوت\n(أزمعت عمرة صرما فابتكر ... إنما يدهن للقلب الحصر)\n(لا يكن حبك حبا ظاهرا ... ليس هذا منك يا عمر بسر)\n(سألت حسان من أخواله ... إنما يسأل بالشيء الغمر)\n(قلت أخوالي بنو كعب إذا ... أسلم الأبطال عورات الدبر)\nريد يدهن القلب فأدخل اللام زائدة للضرورة عمر ترخيم عمرة والسر الخالص الحسن غنت في هذه الأبيات عزة الميلاء ثاني ثقيل بالبنصر من رواية حبش وتمام القصيدة\n(رب خال لي لو أبصرته ... سبط المشية في اليوم الخصر)\n(عند هذا الباب إذ ساكنه ... كل وجه حسن النقبة حر)\n(يوقد النار إذا ما أطفئت ... يعمل القدر بأثباج الجزر)\n(من يغر الدهر أو يأمنه ... من قبيل بعد عمرو وحجر)\n(ملكا من جبل الثلج إلى ... جانبي أيلة من عبد وحر)\n(ثم كانا خير من نال الندى ... سبقا الناس بإقساط وبر)\n(فارسي خيل إذا ما أمسكت ... ربة الخدر بأطراف الستر)\n(أتيا فارس في دارهم ... فتناهوا بعد إعصار بقر)\n(ثم نادوا يالغسان اصبروا ... إنه يوم مصاليت صبر)\n(اجعلوا معقلها أيمانكم ... بالصفيح المصطفى غير الفطر)\n(بضراب تأذن الجن له ... وطعان مثل أفواه الفقر)\n(ولقد يعلم من حاربنا ... أننا ننفع قدما ونضر)\n(صبر للموت إن حل بنا ... صادقو البأس غطاريف فخر)\n(وأقام العز فينا والغنى ... فلنا فيه على الناس الكبر)\n(منهم أصلي فمن يفخر به ... يعرف الناس بفخر المفتخر)\n(نحن أهل العز والمجد معا ... غير أنكاس ولا ميل عسر)\n(فاسألوا عنا وعن أفعالنا ... كل قوم عندهم علم الخبر)\nال الزبير فحدثني عمي قال ثم إن حسان بن ثابت مر يوما بنسوة فيهن\nعمرة بعد ما طلقها فأعرضت عنه وقالت لامرأة منهن إذا حاذاك هذا الرجل فاسأليه من هو وآنسبيه وآنسبي أخواله وهي متعرضة له فلما حاذاهن سألته من هو ونسبته فانتسب لها فقالت فمن أخوالك فأخبرها فبصقت عن شمالها وأعرضت عنه فحدد النظر إليها وعجب من فعلها وجعل ينظر إليها فبصر بامرأته وهي تضحك فعرفها وعلم أن الأمر من قبلها أتى فقال في ذلك\n(قالت له يوما تخاطبه ... ريا الروادف غادة الصلب)\n(أما المروءة والوسامة أو ... حشم الرجال فقد بدا حسبي)\n(فوددت أنك لو تخبرنا ... من والداك ومنصب الشعب)\n(فضحكت ثم رفعت متصلا ... صوتي كرفع المنطق الشغب)\n(جدي أبو ليلى ووالده ... عمرو وأخوالي بنو كعب)\n(وأنا من القوم الذين إذا ... أزم الشتاء بحلقة الجدب)\n(أعطى ذوو الأموال معسرهم ... والضاربين بموطن الرعب)\nال مصعب أبو ليلى الذي عناه حسان حرام بن عمرو بن زيد مناة","topic":"ذكر قيس بن الخطيم وأخباره ونسبه","topicNo":16,"sp":4,"spl":"مقتل ابن الخطيم على أيدي الخزرج — ومما فيه صنعة من المائة المختارة من شعر قيس بن الخطيم"},
{"id":"b16-9","bab":"الجزء 3","sec":"ومما فيه صنعة من المائة المختارة من شعر قيس بن الخطيم","page":"ج3 ص19","text":"صوت\n(حوراء ممكورة منعمة ... كأنما شف وجهها نزف)\n(تنام عن كبر شأنها فإذا ... قامت رويدا تكاد تنقصف)\n(أوحش من بعد خلة سرف ... فالمنحنى فالعقيق فالجرف)\nلشعر لقيس بن الخطيم سوى البيت الثالث والغناء لقفا النجار ولحنه المختار ثاني ثقيل هكذا ذكر يحيى بن علي في الاختيار الواثقي وهو في كتاب إسحاق لقفا النجار ثقيل أول بإطلاق الوتر في مجرى البنصر ولعله غير هذا اللحن المختار","topic":"ذكر قيس بن الخطيم وأخباره ونسبه","topicNo":16,"sp":4,"spl":"مقتل ابن الخطيم على أيدي الخزرج — ومما فيه صنعة من المائة المختارة من شعر قيس بن الخطيم"},
{"id":"b16-10","bab":"الجزء 3","sec":"أسباب الحرب بين مالك بن العجلان وبني عمرو بن عوف","page":"ج3 ص20","text":"وهذا الشعر يقوله قيس بن الخطيم في حرب كانت بينهم وبين بني جحجبي وبني خطمة ولم يشهدها قيس ولا كانت في عصره وإنما أجاب عن ذكرها شاعرا منهم يقال له درهم بن يزيد\nقال أبو المنهال عتيبة بن المنهال بعث رجل من غطفان من بني ثعلبة بن سعد بن ذبيان إلى يثرب بفرس وحلة مع رجل من غطفان وقال ادفعهما إلى أعز أهل يثرب قال وقيل إن الباعث بهما عبد ياليل بن عمرو الثقفي قال وقيل بل الباعث بهما علقمة بن علاثة فجاء الرسول بهما حتى ورد سوق بني قينقاع فقال ما أمر به فوثب إليه رجل من غطفان كان جارا لمالك بن العجلان الخزرجي يقال له كعب الثعلبي فقال مالك بن العجلان\nأعز أهل يثرب وقام رجل آخر فقال بل أحيحة بن الجلاح أعز أهل يثرب وكثر الكلام فقبل الرسول الغطفاني قول الثعلبي الذي كان جارا لمالك بن العجلان ودفعهما إلى مالك فقال كعب الثعلبي ألم أقل لكم إن حليفي أعزكم وأفضلكم فغضب رجل من بني عمرو بن عوف يقال له سمير فرصد الثعلبي حتى قتله فأخبر مالك بذلك فأرسل إلى بني عوف بن عمرو بن مالك بن الأوس إنكم قتلتم منا قتيلا فأرسلوا إلينا بقاتله فلما جاءهم رسول مالك تراموا به فقالت بنو زيد إنما قتلته بنو جحجبى وقالت بنو جحجبى إنما قتلته بنو زيد ثم أرسلوا إلى مالك إنه قد كان في السوق التي قتل فيها صاحبكم ناس كثير ولا يدرى أيهم قتله وأمر مالك أهل تلك السوق أن يتفرقوا فلم يبق فيها غير سمير وكعب فأرسل مالك إلى بني عمرو بن عوف بالذي بلغه من ذلك وقال إنما قتله سمير فأرسلوا به إلي أقتله فأرسلوا إليه إنه ليس لك أن تقتل سميرا بغير بينة وكثرت الرسل بينهم في ذلك يسألهم مالك أن يعطوه سميرا ويأبون أن يعطوه إياه ثم إن بني عمرو بن عوف كرهوا أن ينشبوا بينهم وبين مالك حربا فأرسلوا إليه يعرضون عليه الدية فقبلها فأرسلوا إليه إن صاحبكم حليف وليس لكم فيه إلا نصف الدية فغضب مالك وأبي أن يأخذ فيه إلا الدية كاملة أو يقتل سميرا فأبت بنو عمرو بن عوف أن يعطوه إلا دية الحليف وهي نصف الدية ثم دعوه أن يحكم بينهم وبينه عمرو بن امرئ القيس أحد بني الحارث بن الخزرج وهو جد عبد الله بن رواحة ففعل فانطلقوا حتى جاءوه في بني الحارث بن الخزرج فقضى على مالك بن العجلان أنه ليس له في حليفه إلا دية الحليف وأبى مالك أن\nيرضى بذلك وآذن بني عمرو بن عوف بالحرب واستنصر قبائل الخزرج فأبت بنو الحارث بن الخزرج أن تنصره غضبا حين رد قضاء عمرو بن امرئ القيس فقال مالك بن العجلان يذكر خذلان بني الحارث بن الخزرج له وحدب بني عمرو بن عوف على سمير ويحرض بني النجار على نصرته\n(إن سميرا أرى عشيرته ... قد حدبوا دونه وقد أنفوا)\n(إن يكن الظن صادقا ببني النجار ... لا يطعموا الذي علفوا)\n(لا يسلمونا لمعشر أبدا ... ما دام منا ببطنها شرف)\n(لكن موالي قد بدا لهم ... رأي سوى ما لدي أوضعفوا)\nقال علفوا الضيم إذا أقروا به أي ظني أنهم لا يقبلون الضيم صوت\n(بين بني جحجبى وبين بني ... زيد فأنى لجاري التلف)\n(يمشون في البيض والدروع كما ... تمشي جمال مصاعب قطف)\n(كما تمشى الأسود في رهج الموت ... إليه وكلهم لهف)\nنى في هذه الأبيات معبد خفيف ثقيل عن إسحاق وذكر الهشامي أن فيه لحنا من الثقيل الأول للغريض وقال درهم بن يزيد بن ضبيعة أخو سمير في ذلك\n(يا قوم لا تقتلوا سميرا فإن ... القتل فيه البوار والأسف)\n(إن تقتلوه ترن نسوتكم ... على كريم ويفزع السلف)\n(إني لعمر الذي يحج له الناس ... ومن دون بيته سرف)\n(يمين بر بالله مجتهد ... يحلف إن كان ينفع الحلف)\n(لا نرفع العبد فوق سنته ... ما دام منا ببطنها شرف)\n(إنك لاق غدا غواة بني ... عمي فانظر ما أنت مزدهف)\n(فأبد سيماك يعرفوك كما ... يبدون سيماهم فتعترف)\nعنى قوله فأبد سيماك أن مالك بن العجلان كان إذا شهد الحرب يغير لباسه ويتنكر لئلا يعرف فيقصد وقال درهم بن يزيد في ذلك\n(يا مال لا تبغين ظلامتنا ... يا مال إنا معاشر أنف)\n(يا مال والحق إن قنعت به ... فيه وفينا لأمرنا نصف)\n(إن بجيرا عبد فخذ ثمنا ... فالحق يوفى به ويعترف)\n(ثم اعلمن إن أردت ضيم بني ... زيد فإني ومن له الحلف)\n(لأصبحن داركم بذي لجب ... جون له من أمامه عزف)\n(البيض حصن لهم إذا فزعوا ... وسابغات كأنها النطف)\n(والبيض قد ثلمت مضاربها ... بها نفوس الكماة تختطف)","topic":"ذكر قيس بن الخطيم وأخباره ونسبه","topicNo":16,"sp":5,"spl":"أسباب الحرب بين مالك بن العجلان وبني عمرو بن عوف"},
{"id":"b16-11","bab":"الجزء 3","sec":"أسباب الحرب بين مالك بن العجلان وبني عمرو بن عوف","page":"ج3 ص20","text":"(كأنها في الأكف إذ لمعت ... وميض برق يبدو وينكسف)\nقال قيس بن الخطيم الظفري أحد بني النبيت في ذلك ولم يدركه وإنما قاله بعد هذه الحرب بزمان ومن هذه القصيدة الصوت المذكور\n(رد الخليط الجمال فانصرفوا ... ماذا عليهم لو أنهم وقفوا)\n(لو وقفوا ساعة نسائلهم ... ريث يضحي جماله السلف)\n(فيهم لعوب العشاء آنسة الدل ... عروب يسوءها الخلف)\n(بين شكول النساء خلقتها ... قصد فلا جبلة ولا قضف)\n(تنام عن كبر شأنها فإذا ... قامت رويدا تكاد تنغرف)\n(تغترق الطرف وهي لاهية ... كأنما شف وجهها نزف)\n(حوراء جيداء يستضاء بها ... كأنها خوط بانة قصف)\n(قضى لها الله حين صورها الخالق ... أن لا يكنها سدف)\n(خود يغث الحديث ما صمتت ... وهو بفيها ذو لذة طرف)\n(تخزنه وهو مشتهى حسن ... وهو إذا ما تكلمت أنف)\nهي طويلة يقول فيها\n(أبلغ بني جحجبى وإخوتهم ... زيدا بأنا وراءهم أنف)\n(إنا وإن قل نصرنا لهم ... أكبادنا من ورائهم تجف)\n(لما بدت نحونا جباههم ... حنت إلينا الأرحام والصحف)\n(نفلي بحد الصفيح هامهم ... وفلينا هامهم بها جنف)\n(يتبع آثارها إذا اختلجت ... سخن عبيط عروقه تكف)\n(إن بني عمنا طغوا وبغوا ... ولج منهم في قومهم سرف)\nفرد عليه حسان بن ثابت ولم يدرك ذلك\n(ما بال عينيك دمعها يكف ... من ذكر خود شطت بها قذف)\n(بانت بها غربة تؤم بها ... أرضا سوانا والشكل مختلف)\n(ما كنت أدري بوشك بينهم ... حتى رأيت الحدوج تنقذف)\n(دع ذا وعد القريض في نفر ... برجون مدحي ومدحي الشرف)\n(إن تدع قومي للمجد تلفهم ... أهل فعال يبدو إذا وصفوا)\n(إن سميرا عبد طغى سفها ... ساعده أعبد لهم نطف)\nقال ثم أرسل مالك بن العجلان إلى بني عمرو بن عوف يؤذنهم بالحرب ويعدهم يوما يلتقون فيه وأمر قومه فتهيؤوا للحرب وتحاشد الحيان وجمع بعضهم لبعض وكانت يهود قد حالفت قبائل الأوس والخزرج إلا بني قريضة وبني النضير فإنهم لم يحالفوا أحدا منهم حتى كان هذا الجمع فأرسلت إليهم الأوس والخزرج كل يدعوهم إلى نفسه فأجابوا الأوس وحالفوهم والتي حالفت قريظة والنضير من الأوس أوس الله وهي خطمة وواقف وأمية ووائل فهذه قبائل أوس الله ثم زحف مالك بمن معه من الخزرج وزحفت الأوس بمن معها من حلفائها من قريظة والنضير فالتقوا بفضاء كان بين بئر سالم وقباء وكان أول يوم التقوا فيه فاقتتلوا قتالا شديدا ثم انصرفوا وهم منتصفون جميعا ثم التقوا مرة أخرى عند أطم بني قينقاع فاقتتلوا حتى حجز الليل بينهم وكان الظفر يومئذ للأوس على الخزرج فقال أبو قيس بن الأسلت في ذلك\n(لقد رأيت بني عمرو فما وهنوا ... عند اللقاء وما هموا بتكذيب)\n(ألا فدى لهم أمي وما ولدت ... غداة يمشون إرقال المصاعيب)\n(بكل سلهبة كالأيم ماضية ... وكل أبيض ماضي الحد مخشوب)\nصل المخشوب الحديث الطبع ثم صار كل مصقول مخشوبا فشبهها بالحية في انسلالها","topic":"ذكر قيس بن الخطيم وأخباره ونسبه","topicNo":16,"sp":6,"spl":"أسباب الحرب بين مالك بن العجلان وبني عمرو بن عوف"},
{"id":"b16-12","bab":"الجزء 3","sec":"الأوس والخزرج يقبلون بحكم ثابت بن المنذر","page":"ج3 ص26","text":"قال فلبث الأوس والخزرج متحاربين عشرين سنة في أمر سمير يتعاودون القتال في تلك السنين وكانت لهم فيها أيام ومواطن لم تحفظ فلما رأت\nالأوس طول الشر وأن مالكا لا ينزع قال لهم سويد بن صامت الأوسي وكان يقال له الكامل في الجاهلية وكان الرجل عند العرب إذا كان شاعرا شجاعا كاتبا سابحا راميا سموه الكامل وكان سويد أحد الكملة يا قوم أرضوا هذا الرجل من حليفه ولا تقيموا على حرب إخوتكم فيقتل بعضكم بعضا ويطمع فيكم غيركم وإن حملتم على أنفسكم بعض الحمل فأرسلت الأوس إلى مالك بن العجلان يدعونه إلى أن يحكم بينه وبينهم ثابت بن المنذر بن حرام أبو حسان بن ثابت فأجابهم إلى ذلك فخرجوا حتى أتوا ثابت بن المنذر وهو في البئر الذي يقال له سميحة فقالوا إنا قد حكمناك بيننا فقال لا حاجة لي في ذلك قالوا ولم قال أخاف أن تردوا حكمي كما رددتم حكم عمرو بن امرئ القيس قالوا فإنا لا نرد حكمك فاحكم بيننا قال لا أحكم بينكم حتى تعطوني موثقا وعهدا لترضون بحكمي وما قضيت فيه ولتسلمن له فأعطوه على ذلك عهودهم ومواثيقهم فحكم بأن يودى حليف مالك دية الصريح ثم تكون السنة فيهم بعده على ما كانت عليه الصريح على ديته والحليف على ديته وأن تعد القتلى الذين أصاب بعضهم من بعض في حربهم ثم يكون بعض ببعض ثم يعطوا الدية لمن كان له فضل في القتلى من الفريقين فرضي بذلك مالك وسلمت الأوس وتفرقوا على أن على بني النجار نصف دية جار مالك معونة لاخوتهم وعلى بني عمرو بن عوف نصفها فرأت بنو عمرو بن عوف أنهم لم يخرجوا إلا الذي كان عليهم ورأى مالك أنه قد أدرك ما كان يطلب وودي جاره دية الصريح ويقال بل الحاكم المنذر أبو ثابت","topic":"ذكر قيس بن الخطيم وأخباره ونسبه","topicNo":16,"sp":7,"spl":"الأوس والخزرج يقبلون بحكم ثابت بن المنذر"}]);